        SELECTED = DARKER_GRAY_HOVER_COLOR, TEXT = TEXT_COLOR, LABEL = LIGHT_GRAY_COLOR,
        OFF = MEDIUM_GRAY_COLOR, ACCENT = BRAND_ORANGE;
