    final int ICON_ROW = 28,

        ICON_WIDTH = 24, ICON_BOX = 24, HEADER = 22, GAP = 6;

    /** Text width inside a sheet, which sits inside the panel's own padding. */
    final int SHEET_TEXT = 165, VALUE_WIDTH = 46;

    /** What a value is, which decides its colour. */
    @AllArgsConstructor
    enum Tone {
        GAIN(GRAND_EXCHANGE_PRICE), SUPPLY(GRAND_EXCHANGE_ALCH), LOSS(new Color(0xff7a6b)),
        MARKET(new Color(0x5ab4ff)), REVIEW(PROGRESS_INPROGRESS_COLOR), PLAIN(WHITE),
        DIM(LIGHT_GRAY_COLOR); final Color color;

        /** Gain above zero, loss below it. */
        static Tone sign(long value) {
            return value > 0 ? GAIN : value < 0 ? LOSS : PLAIN;
        }

        /** A booked category's tone; fees read as losses, audit-only rows as dim. */
        static Tone of(Contribution.Category category) {
            return category == null || category == Contribution.Category.AUDIT ? DIM : valueOf(category.name());
        }
    }

    /** Recompute layout, then repaint the same component. */
    void repaintLayout(JComponent component) {
        component.revalidate(); component.repaint();
    }

    void preferredHeight(JComponent component, int height) {
        component.setPreferredSize(new Dimension(0, height));
    }

    JMenuItem item(String text, Runnable action) {
        return item(text, true, action);
    }

    JMenuItem item(String text, boolean enabled, Runnable action) {
        var item = new JMenuItem(text); item.setEnabled(enabled); item.addActionListener(e -> action.run());
        return item;
    }

    /** A transparent panel with the caller's unchanged layout. */
    JPanel transparent(LayoutManager layout) {
        var panel = new JPanel(layout); panel.setOpaque(false); return panel;
    }

    /** A left-aligned transparent row of controls. */
    JPanel row(Component... components) {
        var row = transparent(new FlowLayout(LEFT, 2, 0)); for (var component : components) row.add(component);
        return row;
    }

    /** Text is Inter (GE Uncut direction); the bundled OFL files fall back to RuneLite's fonts. */



    final Font bodyFont =
            loaded("Inter-Regular", 12.5f, FontManager.getRunescapeFont()),
        smallFont = bodyFont.deriveFont(11f),
        boldFont = loaded("Inter-SemiBold", 12.5f,
                    FontManager.getRunescapeBoldFont());

    /** A bundled resource face when the build ships it; else the RuneLite font. */
    private Font loaded(String resource, float size, Font fallback) {
        try (InputStream in = Kit.class.getResourceAsStream("/com/gpmanager/fonts/" + resource + ".ttf")) {
            if (in != null) return Font.createFont(Font.TRUETYPE_FONT, in).deriveFont(size);
        } catch (Exception unavailable) {
            // A build without the font bundle keeps RuneLite's own fonts.
        }
        return fallback;
    }

    /**
     * One page toolbar band: controls left, actions right; Ledger and Grinds share the same shape.
     */
    void headerBand(JPanel holder, JComponent control, JComponent... actions) {
        holder.setOpaque(false); pad(holder, 2, 4, 2, 2); holder.add(control, CENTER); holder.add(row(actions), EAST);
    }

    /** Refit bounded text when its allocated width changes, without rebuilding the page. */
    void onResize(JComponent component, Runnable resized) {
        component.addComponentListener(new ComponentAdapter() {
                    public void componentResized(ComponentEvent event) { resized.run(); }
                });
    }

    /** Table and sheet page count; retain the original integer boundary behavior. */
    int pageCount(int count, int perPage) {
        return max(1, (count + perPage - 1) / perPage);
    }

    /** Clamp a requested table/sheet page to the existing nonempty page range. */
    int clampPage(int page, int pages) {
        return max(0, min(page, pages - 1));
    }

    /** Apply pager text and navigation state; callers retain their different text formats. */
    void applyPager(JLabel label, JButton previous, JButton next, int page, int pages, String text) {
        label.setText(text); previous.setEnabled(page > 0); next.setEnabled(page < pages - 1);
    }

    /** The same ordered row/Grind menu: labels, listeners and Swing defaults remain intact. */
    JPopupMenu menuOf(List<Menu> items) {
        var menu = new JPopupMenu(); for (var item : items) menu.add(item(item.label, () -> item.action.run()));
        return menu;
    }

    /**
     * The text shortened with "…" to fit a pixel budget; the full text belongs in the tooltip.
     */
    int fittingPrefix(String text, int budget, ToIntFunction<String> width) {
        int low = 0, high = text.length();
        while (low < high) {
            int middle = low + high + 1 >>> 1; if (width.applyAsInt(text.substring(0, middle)) <= budget) low = middle;
            else high = middle - 1;
        }
        return low;
    }

    String fit(JComponent label, String text, int budget) {
        if (text == null) return ""; var metrics = label.getFontMetrics(label.getFont());
        return budget <= 0 || metrics.stringWidth(text) <= budget ? text : text.substring(0, fittingPrefix(text, budget - metrics.stringWidth("…"), metrics::stringWidth)) + "…";
    }

    /**
     * Fits text by shrinking its font, down to 10 pt, before cutting it with an ellipsis, so a
     * long name stays readable (owner 1.5.2); the caller keeps the full text in a tooltip.
     */
    String fitShrinking(JLabel label, String text, Font font, int budget) {
        Font size = font;
        while (budget > 0 && size.getSize2D() > 10f
                && label.getFontMetrics(size).stringWidth(string(text)) > budget)
            size = size.deriveFont(size.getSize2D() - 0.5f);
        label.setFont(size); return fit(label, text, budget);
    }

    /** A small label in the muted label colour. */
    JLabel muted(String text) {
