        var crop = visible(image); double scale = min(1d, box / (double) max(crop.width, crop.height));
        int w = max(1, (int) round(crop.width * scale)), h = max(1, (int) round(crop.height * scale));
        var out = new BufferedImage(box, box, BufferedImage.TYPE_INT_ARGB); var g = out.createGraphics();
        g.setRenderingHint(KEY_INTERPOLATION, scale < 1d ? VALUE_INTERPOLATION_BILINEAR
