class KeyValue extends JPanel {
    JPanel body = stack(CARD, 0);

    KeyValue(String title) {
        super(new BorderLayout()); setBackground(CARD);
        if (title != null) {
            var header = muted(title);
            header.setBorder(headerBorder(6));
            preferredHeight(header, HEADER); add(header, NORTH);
        }
        add(body, CENTER);
    }



    KeyValue put(String key, String value, Tone tone) {
        return put(key, value, tone, null);
    }

    /** Adds a line; {@code exact} is the value's hover text, such as "−184,612 gp". */
    KeyValue put(String key, String value, Tone tone, String exact) {
        var line = transparent(new BorderLayout(GAP, 0)); pad(line, 0, 6, 0, 6);
        preferredHeight(line, ROW); line.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW));
        // The key keeps its width; a value too long for the rest ends in "…" and hovers in full.
        line.add(muted(key), WEST); char first = value.isEmpty() ? ' ' : value.charAt(0);
        boolean numeral = Character.isDigit(first) || first == '−' || first == '-' || first == '+';
        var shown = label(value, numeral ? numbers(11.5f) : bodyFont, (tone == null ? PLAIN : tone).color);
        shown.setHorizontalAlignment(SwingConstants.RIGHT);
        shown.setToolTipText(exact == null ? value : exact); line.add(shown, CENTER);
