            this.open = open;
        }

    }

    JLabel dot = label("●", bodyFont, OFF), name = label("", boldFont, WHITE), word = muted("");
    JPanel icons = transparent(new FlowLayout(RIGHT, 0, 0));

    /** Net in the GP/h face at its own size: RuneLite's pixel fonts blur when scaled. */
    JLabel net = label("", boldFont, TEXT),

        rate = label("", boldFont, TEXT), clock = muted("");

    /**
     * A slim line under the Net: the run's whole total while Live counts fresh, and Risk where you
     * can be attacked (owner 1.5.2: out of the header). Hidden when it has nothing to say.
     */
    JPanel under = transparent(new FlowLayout(LEFT, 6, 0)),

        strips = stack(CARD, 0), statusRight = transparent(new GridBagLayout()),
        big = transparent(new BorderLayout(GAP, 0));
    List<Cell> drawnIcons = emptyList(); List<List<Cell>> drawn = emptyList();
    Runnable onDot;

    Hero() {
        super(new BorderLayout()); setBackground(CARD); net.setFont(numbers(16f)); rate.setFont(numbers(12f));
        var status = transparent(new BorderLayout(2, 0)); preferredHeight(status, 28); pad(status, 0, 4, 0, 4);
        var left = transparent(new BorderLayout(2, 0)); left.add(dot, WEST); left.add(name, CENTER); status.add(left, CENTER);
        word.setFont(smallFont.deriveFont(10f));
        word.setBorder(createCompoundBorder(createLineBorder(LINE),
                        createEmptyBorder(2, 3, 2, 3)));
        statusRight.add(icons); statusRight.add(word); status.add(statusRight, EAST);
        clickable(dot, "Pause or resume tracking", () -> {
                    if (onDot != null) onDot.run();
                });
        pad(big, 0, 6, 4, 6); big.add(net, CENTER);
        var pace = new JPanel(); pace.setLayout(new BoxLayout(pace, BoxLayout.Y_AXIS));
        pace.setOpaque(false); rate.setAlignmentX(RIGHT_ALIGNMENT); clock.setAlignmentX(RIGHT_ALIGNMENT); pace.add(rate);
        pace.add(clock); big.add(pace, EAST); var top = transparent(new BorderLayout()); top.add(status, NORTH);
        top.add(big, CENTER); pad(under, 0, 0, 4, 0); under.setVisible(false); top.add(under, SOUTH);
        add(top, NORTH); add(strips, CENTER);
    }

    /**
     * The dot's colour says the state; clicking it runs {@code toggle} (pause / resume) when set.
