    Hero status(Color dotColor, String dotTip, String title, String statusWord, Runnable toggle) {
        dot.setForeground(dotColor); dot.setToolTipText(dotTip);
        dot.setCursor(toggle == null ? getDefaultCursor() : getPredefinedCursor(HAND_CURSOR));
        onDot = toggle; dot.setFocusable(toggle != null);
        String state = string(statusWord); word.setForeground(statusColor(state));
        word.setText(state.isEmpty() ? "" : state.substring(0, 1) + lower(state.substring(1), false));
        word.setVisible(!word.getText().isEmpty()); String text = string(title);
        name.setText(fitShrinking(name, text, boldFont, nameBudget())); name.setToolTipText(text.isEmpty() ? null : text);
        return this;
    }

    static Color statusColor(String state) {
        switch (state) {
            case "AWAY": return ACCENT;
            case "PAUSED": return REVIEW.color;
            case "LOGGED OUT": return LOSS.color;
            case "RECONNECTING": return MARKET.color;
            case "CALIBRATING":
            case "COMPLETE": return GAIN.color;
            default: return state.startsWith("RESUMING") ? GAIN.color : LABEL;
        }
