    static JPanel box(Cell cell) {
        var box = new JPanel(new BorderLayout()); box.setBackground(CARD);
        pad(box, 2, 5, 3, 5); box.add(muted(cell.label), NORTH);
        box.add(label(cell.value, numbers(11f), cell.tone.color), CENTER);
