    void apply(LiveSnapshot snapshot) {
        boolean loggedIn = !snapshot.offline; counts(snapshot); hero.icons(statusIcons(snapshot));
        signals.setVisible(hero.icons.getComponentCount() + counts.getComponentCount() > 0);
        hero.status(snapshot.offline ? OFF : snapshot.paused && !snapshot.idle ? REVIEW.color
                        : !snapshot.present || snapshot.idle ? OFF : GAIN.color, statusTooltip(snapshot), identityOf(snapshot), wordOf(snapshot),
                loggedIn ? actions::togglePause : null);
        // Owner 1.5.2: Risk lives off the header, so a long name keeps its room.
        total.setVisible(snapshot.fresh);
