        label.setFont(smallFont); label.setForeground(tone.color);
        label.setIcon(image == null || image.getIconHeight() <= 12 ? image : new ImageIcon(
                                image.getImage().getScaledInstance(-1, 12, Image.SCALE_SMOOTH)));
        label.setIconTextGap(2); label.setToolTipText(tip); label.setBorder(null); label.setBorderPainted(true);
        label.setContentAreaFilled(false); label.setFocusPainted(false);
