        var ending = session(); if (ending == null || !engine.customActive()) return;
        String endedId = ending.id(), endedName = ending.name(); Object owner = panel.ownerToken;
        mutate(() -> {
                    if (session() != ending || !engine.finishCustom(now())) return;
                    var ended = engine.historyMetrics(endedId, now());
                    Runnable done = () -> {
                        if (panel.suspended || panel.ownerToken != owner) return;
                        shell.notify(endedName + " ended", ended == null ? "" : signed(ended.net), false, null, null);
                    }; SidebarPanel.onEdt(done);
                });
