    /**
     * One-click values under a target field ("label=value" when they differ; Clear empties it). The
     * pick matching the field is lit, so the sheet shows the current target at a glance.
     */
    static void picks(JPanel form, JTextField field, String... picks) {
        var row = transparent(new GridLayout(1, 0)); pad(row, 0, 0, 2, 0); Map<JButton, String> values = new LinkedHashMap<>();
        Runnable light = () -> values.forEach((chip, value) -> chip.setForeground(
                                                value.equalsIgnoreCase(field.getText().trim()) ? ACCENT : LABEL));
        for (String pick : picks) {
            String[] part = pick.split("=", -1); String value = part[part.length - 1];
            JButton chip = button(part[0], () -> {
                                field.setText(value); light.run();
                            });
            pad(chip, 1, 0, 1, 0); chip.setContentAreaFilled(false); values.put(chip, value); row.add(chip);
        }
        field.addCaretListener(e -> light.run()); light.run(); form.add(row);
    }

