/**
 * Grinds read model: the current canonical Grind, the reusable My Grinds definitions with their
 * derived Last/Best subset, the Recent Grinds history and one Grind detail. Targets and Pace are
 * derived from canonical facts; estimates never feed accounting, completion or PBs.
 */
@AllArgsConstructor
class GrindsData {
    /** A target field that did not parse: it never mutates and never means "clear". */
    static final long INVALID = -1;

    /**
     * Friendly Net-target parsing: 5m, 5M, 5000k, 5,000,000. Blank is 0 (no target); malformed is
     * {@link #INVALID}.
     */
    static long parseNet(String raw) {
        if (blank(raw)) return 0;
        // Strict whole-string form: digits with optional decimals and one k/m/b suffix. Anything
        // else is malformed and must never be treated as "clear".
        String text = lower(raw).replace(",", "").replace("_", "").replace(" ", "");
        if (!matches("target-net", text)) return INVALID; long value = parseGp(text);
        return value > 0 ? value : INVALID;
    }

    /**
     * Friendly Active-Time parsing: 90m, 3h, "3h 30m", plain minutes. Blank is 0 (no target);
     * malformed is {@link #INVALID}.
     */
    static long parseTime(String raw) {
        if (blank(raw)) return 0; String text = lower(raw).replace(",", "").replace("_", "").trim();
        try {
            if (matches("target-minutes", text)) {
                long minutes = round(Double.parseDouble(text)); return minutes > 0 ? multiplyExact(minutes, 60000) : INVALID;
            }
            // Strict whole-string form: optional "Nh" then optional "Mm" and nothing else.
            var matcher = pattern("target-time").matcher(text);
            if (!matcher.matches() || matcher.group(1) == null && matcher.group(2) == null)
                return INVALID;
            long total = 0;
            if (matcher.group(1) != null)
                total = addExact(total, round(Double.parseDouble(matcher.group(1)) * 3_600_000d));
            if (matcher.group(2) != null)
                total = addExact(total, round(Double.parseDouble(matcher.group(2)) * 60_000d));
            return total > 0 && total < Long.MAX_VALUE ? total : INVALID;
        } catch (ArithmeticException overflow) {
            return INVALID;
        }
    }

    /** Applies a Net input to an existing target: INVALID keeps the existing value untouched. */
    static Long applyNet(String raw, Long existing) {
        return apply(parseNet(raw), existing);
    }

    /** Applies an Active-Time input to an existing target: INVALID keeps the existing value. */
    static Long applyTime(String raw, Long existing) {
        return apply(parseTime(raw), existing);
    }

    static Long apply(long parsed, Long existing) {
        return parsed == INVALID ? existing : parsed == 0 ? null : parsed;
    }

    /** True when both fields are safe to apply (valid or deliberately blank). */
    static boolean inputsValid(String netRaw, String timeRaw) {
        return parseNet(netRaw) != INVALID && parseTime(timeRaw) != INVALID;
    }

    /** Derived pace over canonical facts; nothing here is booked or persisted. */
    @AllArgsConstructor
    static class Pace {
        /** True when a Pace question exists at all (at least one target). */
        boolean present,

            available;
        String line, second;

        /** No target at all: there is no Pace question to answer, so no row renders. */
        static Pace none() {
            return new Pace(false, false, "", null);
        }
    }

    /**
     * Mode A/B/C pace. A: time until the Net target. B: projected Net at the Active-Time target. C:
     * both plus the required average. Unavailable evidence reads "Calculating…" instead of a
     * fabricated precision; estimates stay visually muted.
     */
    static Pace pace(Long profit, Long targetMillis, long net, boolean ready, long rate,
            long active) {
        if (profit == null && targetMillis == null) return Pace.none();
        if (!ready) return new Pace(true, false, "Calculating…", null);
        if (profit != null && targetMillis == null) {
            if (net >= profit) return new Pace(true, true, "Target reached", null);
            if (rate <= 0)
                // The rate is established and genuinely non-positive: an ETA would be fabricated.
                return new Pace(true, true, "Not earning at this rate", null);
            long minutes = positive(round(subtract(profit, net) * 60d / rate));
            return new Pace(true, true, "~" + durationMinutes(minutes) + " remaining", null);
        }
        // A time target counts down; a projected Net only repeated GP/h (owner 1.5.2).
        long remaining = positive(targetMillis - active); String left = durationMinutes(remaining / 60000) + " left";
        if (profit == null)
            return new Pace(true, true, remaining <= 0 ? "Time target reached" : left, null);
        if (remaining <= 0)
            return new Pace(true, true, "Time target reached", "Required average was "
                            + compact(requiredAverage(profit, net, active)) + "/h");
        long required = requiredAverage(profit, net, targetMillis);
        return new Pace(true, true, left, "Required average " + compact(required) + "/h");
    }

    static long requiredAverage(long target, long net, long byMillis) {
        return Session.hourly(positive(subtract(target, net)), byMillis);
    }

    static String durationMinutes(long minutes) {
        return minutes < 90 ? minutes + "m" : minutes / 60 + "h " + minutes % 60 + "m";
    }

    /** One reusable definition plus its derived Last/Best subset from linked canonical history. */
    @AllArgsConstructor
    static class MyGrind {
        SavedGrind definition; int linkedCount;
        boolean hasLast; long lastNet, lastStartedAt;
        boolean hasBest; long bestNet;

        /** Average GP/h over every finished run (owner 1.5.0: Grinds compare by rate). */
        long rate;

        boolean hasRate;
    }

    /** One recent canonical instance, rendered with Grind language. */
    @AllArgsConstructor
    static class Recent {
        String session, name; long startedAt, net, activeMillis;

        /** A Free play run (current or reset), listed under FREE PLAY (owner 1.5.2). */
        boolean general;
    }

    /** One instance's detail: financial summary, targets and target outcome. */
    @AllArgsConstructor
    static class Detail {
        String session, name; long startedAt, net;
        /** What the Net aim counted when this ran (the run's Net minus its set baseline). */
        long targetProgress, income, supplies, losses; boolean splitAvailable;
        long activeMillis;
        /** The Active Time window the run's time target counts from (set moment to now/end). */
        long targetWindowMillis; boolean ready;
        long rate; Long netTarget, timeTarget;
        boolean closed, compacted;

        /** Factual target outcome wording; never "Failed". */
        String netOutcome() {
            return GrindHistory.netOutcome(netTarget, targetProgress, closed);
        }

        String timeOutcome() {
            return GrindHistory.timeOutcome(timeTarget, targetWindowMillis);
        }
    }

    boolean hasActive; String activeName, activeSessionId;
    long activeNet, rate; boolean ready;
    long activeMillis; Long activeNetTarget, activeTimeTarget;
    Pace pace; List<MyGrind> plans;
    List<Recent> recent;

    /** Free play's milestone progress, "1B · 42%"; empty with none (owner 1.5.2). */
    String target;

    ZoneId zone; Detail detail;
    AllTime overall;

    /** The All time card: every retained session (Free play included) from canonical metrics. */
    @AllArgsConstructor
    static class AllTime {
        long net, activeMillis; Long rate;
        int plans; boolean splitAvailable;
        long supplies, losses; String bestName;
        long bestNet; String rateName;
        long bestRate;
    }

    static AllTime allTime(Engine engine, long now) {
        var summary = engine.summary(); long net = 0, active = 0, supplies = 0, lost = 0, best = 0, bestRate = 0;
        var grinds = new HashSet<String>(); boolean split = true;
        String bestName = null, rateName = null; var seen = new HashSet<String>();
        var sessions = copiedList(engine.history()); sessions.add(engine.session()); sessions.add(engine.freePlay());
        for (var session : sessions) {
            if (session == null || !seen.add(session.id())) continue; var run = summary.run(engine, session, now);
            var metrics = run.metrics; net = sum(net, metrics.net); active = sum(active, metrics.elapsed);
            split &= metrics.split; supplies = sum(supplies, metrics.supplies); lost = sum(lost, metrics.other);
            if (session.grind)
                // Runs of one saved Grind count once; an unsaved Grind is its own name.
                grinds.add(session.isLinked() ? session.grindId() : "name:" + session.name());
            if (!session.isClosed()) continue;
            if (bestName == null || run.net() > best) {
                bestName = session.name(); best = run.net();
            }
            if (run.rate != null && (rateName == null || run.rate > bestRate)) {
                rateName = session.name(); bestRate = run.rate;
            }
        }
        return new AllTime(net, active, RateReadiness.isEstablished(active) ? Session.hourly(net, active) : null,
                grinds.size(), split, supplies, lost, bestName, best, rateName, bestRate);
    }

    static GrindsData capture(Engine engine, long now, boolean includeArchived, String id) {
        var summary = engine.summary(); var active = engine.session();
        boolean custom = engine.customActive(); long net = 0, rate = 0;
        boolean ready = false; long elapsed = 0;
        Long target = null, duration = null; String activeName = "", activeSessionId = "";
        if (active != null) {
            var metrics = summary.metrics(engine.session(), now); net = metrics.net;
            rate = metrics.rate; ready = RateReadiness.isEstablished(metrics.elapsed);
            elapsed = metrics.elapsed; target = active.targetGp(); duration = active.timeTargetMillis(); activeName = active.name();
            activeSessionId = active.id();
        }
        // The Active Time target's own window counts from when it was set (owner live 2026-10-13);
        // the displayed Active Time above stays the run's total.
        long targetWindowMillis = active == null ? 0 : active.timeWindowMillis(elapsed);
        Pace pace = pace(target, duration, active == null ? net : active.targetProgress(net),
                        ready, rate, targetWindowMillis);
        var plans = new ArrayList<MyGrind>();
        for (var definition : engine.plans(includeArchived)) {
            var rollup = summary.rollups.get(definition.id());
            plans.add(new MyGrind(definition, rollup.count, rollup.has, rollup.last, rollup.at, rollup.has,
                            rollup.best, Session.hourly(rollup.total, rollup.millis),
                            RateReadiness.isEstablished(rollup.millis)));
        }
        plans.sort(comparing((MyGrind plan) -> !plan.definition.favorite)
                        .thenComparing(grind -> -grind.lastStartedAt).thenComparing(
                                grind -> grind.definition.name(), CASE_INSENSITIVE_ORDER)
                        .thenComparing(grind -> grind.definition.id()));
        var recent = new ArrayList<Recent>(); var runs = copiedList(engine.history());
        // The current Free play heads FREE PLAY; a running Grind pauses it, so it waits then.
        if (!custom && engine.freePlay() != null) runs.add(engine.freePlay());
        for (var session : runs) {
            if (session == null) continue; var metrics = summary.run(engine, session, now).metrics;
            recent.add(new Recent(session.id(),
                            session.isClosed() || session.grind ? session.name() : "Free play",
                            session.startedAt, metrics.net, metrics.elapsed, !session.grind));
        }
        recent.sort(comparingLong((Recent item) -> item.startedAt).reversed()
                        .thenComparing(item -> item.session));
        for (var saved : engine.saved) {
            var money = saved.session.metrics(now);
            recent.add(new Recent(saved.id, saved.session.name(), saved.session.endedAt,
                    money.net, money.elapsed, false));
        }
        Detail detail = null;
        if (!empty(id)) {
            Session selected = active != null && id.equals(active.id()) ? active
                            : engine.historySession(id);
            if (selected != null) {
                boolean liveDetail = active != null && id.equals(active.id());
                Metrics metrics = engine.savedSession(id) != null ? selected.metrics(now)
                                : liveDetail ? summary.metrics(engine.session(), now)
                                : summary.run(engine, selected, now).metrics;
                detail = new Detail(id, selected.name(), selected.startedAt, metrics.net,
                                selected.targetProgress(metrics.net), metrics.income,
                                metrics.split ? metrics.supplies : -1,
                                metrics.split ? metrics.other : -1, metrics.split,
                                metrics.elapsed, selected.timeWindowMillis(metrics.elapsed),
                                RateReadiness.isEstablished(metrics.elapsed),
                                Session.hourly(metrics.net, metrics.elapsed), selected.targetGp(),
                                selected.timeTargetMillis(), selected.isClosed(),
                                selected.retainedRevenue != 0 || selected.retainedCosts != 0);
            }
        }
        var profileZone = engine.timeZone();
        return new GrindsData(active != null && custom, activeName, activeSessionId, net, rate, ready,
                elapsed, target, duration, pace, plans, recent,
                milestoneText(engine.freePlay(), now), profileZone, detail, allTime(engine, now));
    }

    /** "1B · 42%" or "1B ✓" for Free play's milestone; empty with none. */
    static String milestoneText(Session general, long now) {
        Long gp = general == null ? null : general.milestoneGp; if (gp == null) return ""; long net = general.metrics(now).net;
        return compact(gp) + SEPARATOR + (net >= gp ? "✓" : percent(max(0d, (double) net / gp)));
    }
}

/**
 * Shared Grind facts: one session's run metrics and the factual target wording the Grinds pages
 * show. Nothing here books, prices, persists or feeds accounting.
 */
class GrindHistory {
    /**
     * One session's shared facts: the retained summary's metrics, else the session's own
     * correction-aware totals, plus the full-session rate once established. Grinds, Grind history
     * and the All time card all read sessions through this, so the pages cannot disagree.
     */
    static class Run {
        Session session; Metrics metrics;
        Long rate;

        /** Detached metrics supplied by the revision summary; fields keep their existing names. */
        Run(Session session, Metrics metrics) {
            this.session = session; this.metrics = metrics;
            rate = RateReadiness.isEstablished(metrics.elapsed)
                            ? Session.hourly(metrics.net, metrics.elapsed) : null;
        }

        long net() {
            return metrics.net;
        }
    }

    /** Factual target wording; never "Failed". Shared with the Grinds detail. */
    static String netOutcome(Long profit, long net, boolean closed) {
        return profit == null ? "No Net target" : net >= profit ? "Reached " + compact(profit) + " Net" : closed ? msg("endedBefore") + signed(profit - net) + " remaining"
                : msg("reached") + signed(profit - net) + " remaining";
    }

    /** Factual Active-Time target wording; never "Failed". Shared with the Grinds detail. */
    static String timeOutcome(Long active, long activeMillis) {
        return active == null ? msg("timePaused") : activeMillis >= active ? msg("timeTarget") : duration(active - activeMillis) + msg("activeTimeRemaining");
    }

    /** Full-session rate: Net over canonical Active Time; zero Active Time has no rate. */
}

/**
 * One presentation law for "is this GP/h trustworthy yet". A computed rate is only meaningful once
 * the Grind has real Active Time behind it; before that the canonical number is a data-availability
 * artifact, not a rate, and every surface must render the unavailable form ("—") instead of a
 * fabricated 0/h.
 *
 * <p>The minimum window is the historical accepted value (the retired {@code RateAvailability} used
 * the same 60 seconds); it is presentation-only and never affects accounting.
 */
class RateReadiness {
    /** Minimum Active Time before a computed rate is presentation-trustworthy. */
    static final long MIN_ACTIVE_MILLIS = 60000;

    /**
     * GP/h is Net over canonical Active Time; it is shown once that Active Time reaches the floor.
     *
     * @param activeMillis Active Time of the displayed rate window
     */
    static boolean isEstablished(long active) {
        return active >= MIN_ACTIVE_MILLIS;
    }
}

/** Observed raid history; canonical receipts remain the sole financial owners. */
class RaidHistory {
    static final List<String[]> RULES = rows("raid_history");
    static final Map<Integer,String> PICKAXES = byId("raid_pickaxes"), PICKAXE_STORES = byId("raid_pickaxe_stores");

    static class Run extends SaveCopies {
        String id, mode; long started, ended;
        boolean complete, claimed, partial, died, failed; Set<String> owners = new HashSet<>();
    }

    static class State extends SaveCopies {
        List<Run> runs = new ArrayList<>(); List<Claim> claims = new ArrayList<>(); long[] clears = new long[RULES.size()];
        int seen; String death;
        Map<Integer, Long> supplies = numberMap();
    }

    static class Claim extends SaveCopies {
        String id; int chest; int[] epoch;
        Map<Integer, Long> remaining = orderedNumberMap(); boolean observed;
    }

    @AllArgsConstructor
    static class Sample {
        int kind; boolean inside;
        String mode; int[] counters;
    }

    final Engine engine; State state = new State();
    Run active; Sample[] previous = new Sample[RULES.size()];
    int absent, absentTick = -1; long revision = -1;
    String selected; Map<String, long[]> totals = new HashMap<>();
    Set<String> missing = new HashSet<>(); SavedSession view;

    RaidHistory(Engine engine) {
        this.engine = engine;
    }

    static int kind(String id) {
        return id != null && (id.length() == 1 || id.length() == 38 && id.charAt(1) == ':')
                && id.charAt(0) >= '0' && id.charAt(0) - '0' < RULES.size() ? id.charAt(0) - '0' : -1;
    }

    Run find(String id) {
        return firstMatch(state.runs, run -> Objects.equals(id, run.id));
    }

    String activeId() {
        return active == null ? null : active.id;
    }

    void changed() {
        revision = -1; engine.changed();
    }

    Run start(int kind, String mode, long now, boolean partial) {
        var run = new Run(); run.id = kind + ":" + uuid(); run.mode = mode; run.started = now;
        run.partial = partial; state.runs.add(0, run); state.seen |= 1 << kind; changed();
        return run;
    }

    void observe(Sample sample, long now, int tick) {
        int kind = sample.kind; if (kind < 0 || kind >= RULES.size()) return; var old = previous[kind]; previous[kind] = sample;
        if (sample.inside) {
            if (active == null || kind(active.id) != kind || active.complete && old != null && !old.inside) {
                end(now); if (kind != 3 && old != null && !old.inside) state.claims.removeIf(claim -> kind(claim.id) == kind);
                active = start(kind, sample.mode, now, old == null || old.inside); prune();
            }
            absent = 0;
        }
        if (active != null && kind(active.id) == kind) {
            if (old != null && old.counters.length == sample.counters.length) {
                int count = 0; boolean invalid = false;
                for (int i = 0; i < sample.counters.length; i++) {
                    long delta = (long) sample.counters[i] - old.counters[i]; count += delta == 1 ? 1 : 0;
                    invalid |= delta != 0 && delta != 1;
                }
                if (invalid || count > 1) {
                    active.partial = true; changed();
                } else if (count == 1) complete(active, now);
            }
            if (!sample.inside && absentTick != tick) {
                absentTick = tick; if (++absent >= 3) end(now);
            }
        }
    }

    void complete(Run run, long now) {
        if (run.complete) return; run.complete = true; run.ended = now;
        int kind = kind(run.id),
            chest = Integer.parseInt(RULES.get(kind)[2]);
        state.claims.removeIf(item -> item.chest == chest && !run.id.equals(item.id));
        var claim = firstMatch(state.claims, item -> run.id.equals(item.id));
        if (claim == null) {
            claim = new Claim(); claim.id = run.id; claim.chest = chest; state.claims.add(claim);
        }
        claim.epoch = previous[kind].counters.clone(); changed();
    }

    void end(long now) {
        if (active == null) return; if (active.ended == 0) active.ended = now;
        active = null; absent = 0; changed();
    }

    /** Restore visibility only from retained raid identities; no attempts or money are inferred. */
    void recoverVisibility() {
        read("all");
        for (var id : totals.keySet()) state.seen |= 1 << kind(id);
    }

    boolean unlocked() {
        return state.seen != 0 || !state.runs.isEmpty() || stream(state.clears).anyMatch(n -> n > 0);
    }

    void death() {
        var sample = active == null ? null : previous[kind(active.id)];
        state.death = sample == null || sample.inside ? activeId() : null; if (state.death != null) active.died = true;
        changed();
    }

    void fee(Transaction row) {
        var run = find(state.death); if (run == null || row == null) return; for (var flow : row.flows()) flow.raid = run.id;
        run.owners.add(engine.session().id()); changed();
    }

    /** A source-confirmed dose allowance, spent first when borrowed and owned stock mix. */
    boolean supplies(List<Flow> flows, boolean use, Map<Integer, Long> loot) {
        if (!use) claim(flows, f -> PICKAXES.containsKey(f.item), (f, q) -> engine.events.take(Inbox.RAID_STORE, -1,
                q - (f.gain() ? min(q, amount(loot, f.item)) : 0L),
                e -> e.data == state && e.x == Long.signum(f.quantity)));
        if (state.supplies.isEmpty() && engine.events.peek(Inbox.LOAN) == null) return false;
        if (!use) {
            claim(flows, Flow::gain, (flow, quantity) -> {
                long n = engine.events.take(Inbox.LOAN, flow.item,
                        quantity - min(quantity, amount(loot, flow.item)), e -> e.data == state);
                if (n > 0) {
                    state.supplies.merge(ItemVariationMapping.map(flow.item),
                            multiply(n, max(1, ActionReader.dose(flow.name))), SafeMath::sum);
                    changed();
                }
                return n;
            });
            // A borrowed hammer removed outside a death wipe is stripped without a booking.
            claim(flows, f -> f.item == 2347 && f.cost() && !engine.death.wipePending(), (f, q) -> {
                long n = take(state.supplies, 2347, q); if (n > 0) changed(); return n;
            }); return false;
        }
        boolean applied = false;
        for (int family : copiedList(state.supplies.keySet())) {
            var group = matching(flows, f -> ItemVariationMapping.map(f.item) == family); long used = 0, cost = 0, vials = 0;
            for (var f : group) {
                int dose = ActionReader.dose(f.name);
                used = subtract(used, multiply(f.quantity, max(1, dose))); cost = subtract(cost, f.value);
                if (dose == 1 && f.cost()) vials = sum(vials, SafeMath.abs(f.quantity));
            }
            long free = take(state.supplies, family, used); if (free == 0) continue; changed(); applied = true;
            var containers = numberMap(); containers.put(229, min(free, vials));
            claim(flows, f -> f.gain() && f.item == 229, (f, q) -> take(containers, 229, q));
            if (free == used) flows.removeAll(group);
            else {
                // Captured unit quotes and physical quantities stay exact; only paid GP remains.
                long credit = cost <= 0 ? 0 : multiply(cost, free) / used;
                for (var f : group) if (f.cost()) {
                    long n = min(credit, SafeMath.abs(f.value)); f.value = sum(f.value, n); credit -= n;
                }
            }
        }
        return applied;
    }

    void received(String id, Session owner, long now) {
        var run = find(id);
        if (run == null) {
            run = start(kind(id), "Partial capture", now, true); run.id = id; prune();
        }
        run.complete = true; run.claimed = true; if (run.ended == 0) run.ended = now;
        run.owners.add(owner.id()); changed();
    }

    void logout(long now) {
        if (active != null) active.partial = true; end(now); restore(snapshot());
    }

    void restore(State saved) {
        state = copy(saved); active = null; previous = new Sample[RULES.size()]; absent = 0;
        absentTick = -1; if (state.runs == null) state.runs = new ArrayList<>();
        state.runs.removeIf(run -> run == null || kind(run.id) < 0 || run.id.length() != 38 || run.started <= 0);
        state.seen &= (1 << RULES.size()) - 1;
        for (var run : state.runs) {
            state.seen |= 1 << kind(run.id); if (run.owners == null) run.owners = new HashSet<>();
            if (run.ended == 0) {
                run.ended = run.started; run.partial = true;
            }
        }
        if (state.claims == null) state.claims = new ArrayList<>();
        state.claims.removeIf(claim -> claim == null || kind(claim.id) < 0 || claim.epoch == null || claim.remaining == null
                || claim.chest != Integer.parseInt(RULES.get(kind(claim.id))[2]));
        for (var claim : state.claims) claim.remaining = cash(claim.remaining);
        state.clears = state.clears == null ? new long[RULES.size()] : copyOf(state.clears, RULES.size());
        for (int i = 0; i < RULES.size(); i++) state.clears[i] = max(0, state.clears[i]); prune(); changed();
    }

    State snapshot() {
        return copy(state);
    }

    static State copy(State saved) {
        if (saved == null) return new State(); var copy = shallow(saved);
        copy.runs = list(saved.runs, run -> SaveCopies.copy(run, next ->
                next.owners = next.owners == null ? null : new HashSet<>(next.owners)));
        copy.claims = list(saved.claims, claim -> SaveCopies.copy(claim, next -> {
            next.epoch = next.epoch == null ? null : next.epoch.clone();
            next.remaining = next.remaining == null ? null : new LinkedHashMap<>(next.remaining);
        })); copy.supplies = positive(saved.supplies);
        copy.clears = saved.clears == null ? null : saved.clears.clone(); return copy;
    }

    void prune() {
        int count = 0; var kept = new HashSet<String>();
        var iterator = state.runs.iterator();
        while (iterator.hasNext()) {
            var run = iterator.next(); boolean pending = any(state.claims, claim -> run.id.equals(claim.id));
            if (run == active || pending || Objects.equals(run.id, state.death)
                    || ++count <= max(1, engine.config.maxHistorySessions())) kept.add(run.id);
            else {
                if (run.complete) state.clears[kind(run.id)] = sum(state.clears[kind(run.id)], 1); iterator.remove();
            }
        }
        for (var session : engine.sessions()) if (session.compactedRaids != null) {
            var next = new HashMap<String, long[]>();
            session.compactedRaids.forEach((id, money) -> add(next, kept.contains(id) ? id : Integer.toString(kind(id)), money));
            session.compactedRaids = next;
        }
    }

    static void add(Map<String, long[]> values, String id, long[] money) {
        if (kind(id) < 0 || money == null || money.length != 2 || money[0] < 0 || money[1] < 0) return;
        var total = values.computeIfAbsent(id, key -> new long[2]);
        for (int i = 0; i < 2; i++) total[i] = sum(total[i], money[i]);
    }

    static void compact(Session session, Transaction row) {
        for (var flow : row.flows()) if (flow != null && kind(flow.raid) >= 0) {
            if (session.compactedRaids == null) session.compactedRaids = new HashMap<>(); var money = Accounting.flow(row, flow);
            add(session.compactedRaids, flow.raid, new long[] {money.income, money.cost});
        }
    }

    static Map<String, long[]> copyMoney(Map<String, long[]> source) {
        if (source == null) return null; var copy = new HashMap<String, long[]>();
        source.forEach((id, money) -> copy.put(id, money == null ? null : money.clone())); return copy;
    }

    /** One revision-scoped fold when Raids is viewed; a selected attempt reuses existing Ledger. */
    SavedSession read(String id) {
        if (revision == engine.revision() && Objects.equals(id, selected)) return view;
        boolean all = "all".equals(id); selected = id; totals = new HashMap<>(); missing = new HashSet<>();
        var owners = new HashSet<String>(); var derived = new Session("Raid receipts", 1, SessionMode.GENERAL);
        for (var session : engine.sessions()) {
            owners.add(session.id());
            if (session.compactedRaids != null) session.compactedRaids.forEach((key, money) -> {
                add(totals, key, money); if (key.length() > 1) add(totals, Integer.toString(kind(key)), money);
                if (all || Objects.equals(key, id)) {
                    derived.retainedRevenue = sum(derived.retainedRevenue, money[0]);
                    derived.retainedCosts = sum(derived.retainedCosts, money[1]); derived.compactedTransactionCount++;
                }
            });
            for (var row : session.transactions()) {
                var flows = flowList();
                for (var flow : row.flows()) if (flow != null && kind(flow.raid) >= 0) {
                    var money = Accounting.flow(row, flow);
                    var value = new long[] {money.income, money.cost}; add(totals, flow.raid, value);
                    add(totals, Integer.toString(kind(flow.raid)), value);
                    if (all || Objects.equals(id, flow.raid)) flows.add(SaveCopies.copy(flow));
                }
                if (!flows.isEmpty()) {
                    var copy = SaveCopies.copy(row); copy.replaceFlows(flows); derived.transactions.add(copy);
                }
            }
        }
        for (var run : state.runs) if (!owners.containsAll(run.owners)) missing.add(run.id);
        view = new SavedSession("raid:" + id, derived, List.of()); revision = engine.revision(); return view;
    }



    static Map<Integer, Long> positive(Map<Integer, Long> values) {
        return quantities(values, item -> item > 0);
    }

    /** A short-lived request only annotates already-booked canonical quantities. */
    static class Request {
        Claim claim; State owner;
        int tick; long at;
        boolean bank, inventory; Map<Integer, Long> last, proof = numberMap();
        Map<Transaction, Session> rows = new LinkedHashMap<>();
    }

    static class Native {
        final GpManagerPlugin plugin; final RaidHistory history;
        Request request; List<Request> requests = new ArrayList<>();

        Native(GpManagerPlugin plugin) {
            this.plugin = plugin; history = plugin.engine.raids;
        }

        boolean ready() {
            return plugin.client != null && plugin.client.isClientThread()
                    && plugin.client.getGameState() == GameState.LOGGED_IN;
        }

        boolean live(Request request) {
            if (request == null || request.owner != history.state || !history.state.claims.contains(request.claim) || !ready()) return false;
            int tick = plugin.tick(); return tick >= request.tick && (long) tick - request.tick <= 10;
        }

        static int number(String[] row, int column) {
            return Integer.parseInt(row[column]);
        }

        Sample sample(String[] row) {
            var client = plugin.client;
            int kind = number(row, 0), slot = plugin.varbit(number(row, 7)) - (kind == 2 ? 1 : 0); boolean inside;
            if (kind == 0) inside = plugin.varbit(number(row, 6)) > 0 && slot >= 0
                    && plugin.varbit(number(row, 8)) > 0;
            else {
                String name = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName(),
                    member = slot < 0 || slot >= number(row, 10) ? null : client.getVarcStrValue(number(row, 9) + slot);
                inside = name != null && member != null && Text.standardize(name).equals(Text.standardize(member))
                        && Widgets.visible(client, number(row, 5) << 16)
                        && (kind == 3 ? client.getTopLevelWorldView().isInstance() && plugin.varbit(number(row, 12)) == 0
                                : kind == 2 ? client.getTopLevelWorldView().isInstance() && plugin.varbit(number(row, 8)) == 1
                                : plugin.varbit(number(row, 8)) == 2 || plugin.varbit(number(row, 8)) == 3);
            }
            int[] counters = stream(row[11].split(",")).mapToInt(Integer::parseInt).map(client::getVarpValue).toArray();
            return new Sample(kind, inside, kind == 0 ? plugin.varbit(number(row, 12)) > 0 ? "Challenge" : "Normal"
                    : kind == 2 ? "Level " + plugin.varbit(number(row, 12)) : "Observed mode", counters);
        }

        void chat(String message, long now) {
            synchronized (history.engine) {
                var run = history.active;
                if (run != null && (kind(run.id) == 2 || kind(run.id) == 3) && !run.complete
                        && message.equalsIgnoreCase("You failed to survive the " + RULES.get(kind(run.id))[1].replaceFirst("^The ", "") + ".") && ready()) {
                    run.failed = run.died = true; history.state.death = run.id;
                    if (kind(run.id) == 2) {
                        var held = plugin.containers.captureDeathOwned();
                        history.engine.armDeathReclaim(plugin.consumeTicks(), held == null ? null : held.items, emptyMap());
                    }
                    history.end(now);
                }
            }
        }

        void pulse(long now) {
            synchronized (history.engine) {
                if (!ready()) return; for (var rule : RULES) history.observe(sample(rule), now, plugin.tick());
                requests.removeIf(value -> !live(value)); if (!live(request)) request = null;
            }
        }

        Claim preview(String[] rule) {
            int kind = number(rule, 0), chest = number(rule, 2), flag = number(rule, 4);
            var container = plugin.container(chest); var sample = sample(rule);
            if (container == null || !Widgets.visible(plugin.client, number(rule, 3) << 16)
                    || (flag > 0 ? plugin.varbit(flag) == 0 : !sample.inside)) return null;
            var claim = firstMatch(history.state.claims, item -> item.chest == chest);
            if (claim != null && !Arrays.equals(claim.epoch, sample.counters)) return null;
            if (claim == null) {
                claim = new Claim();
                claim.id = history.active != null && kind(history.active.id) == kind
                        ? history.active.id : kind + ":" + uuid();
                claim.chest = chest; claim.epoch = sample.counters; history.state.claims.add(claim);
            }
            var contents = cash(plugin.counts(container)); if (!claim.observed) claim.remaining = positive(contents);
            else {
                for (var item : claim.remaining.entrySet())
                    item.setValue(min(item.getValue(), amount(contents, item.getKey())));
                claim.remaining.values().removeIf(qty -> qty <= 0);
            }
            claim.observed = true; return claim;
        }

        void menu(MenuOptionClicked event, long now) {
            var clicked = event.getMenuAction();
            synchronized (history.engine) {
                if (event.isConsumed()) return;
                if (live(request)) container(request.claim.chest, plugin.container(request.claim.chest));
                requests.removeIf(value -> !live(value));
                var rule = firstMatch(RULES, row -> number(row, 3) == event.getParam1() >>> 16);
                String option = lower(Text.removeTags(event.getMenuOption()), false);
                if (ready() && clicked != null && clicked.name().startsWith("GAME_OBJECT_")
                        && ActionSignals.rule("pickaxe-store", option) && PICKAXE_STORES.containsKey(event.getId())) {
                    var move = history.engine.events.put(Inbox.RAID_STORE, -1, 1, plugin.consumeTicks(), null);
                    move.data = history.state; move.x = option.startsWith("take") ? 1 : -1;
                }
                var active = history.active;
                if (ready() && active != null && sample(RULES.get(kind(active.id))).inside
                        && ActionSignals.rule("take-or-buy", option)) {
                    String action = clicked == null ? "" : clicked.name();
                    for (var loan : cached("raid_supplies")) {
                        int item = number(loan, 3), stock = number(loan, 4);
                        if (number(loan, 0) != kind(active.id) || !action.startsWith(loan[1])
                                || number(loan, 2) != (action.startsWith("CC_OP") ? event.getParam1() >>> 16 : event.getId())
                                || stock > 0 && !plugin.counts(plugin.container(stock)).containsKey(event.getItemId())) continue;
                        String count = option.replaceFirst("^(take|buy)-", "");
                        long n = item > 0 ? 1 : count.matches("[0-9]+") ? min(28, digits(count)) : 28;
                        item = item > 0 ? item : plugin.containers.canonical(event.getItemId());
                        if (item > 0) history.engine.events.add(Inbox.LOAN, item, n, 6, null).data = history.state;
                    }
                }
                // Only an executed reward disposition ends the current request.
                if (rule != null && ActionSignals.rule("chest-action", option))
                    request = null;
                if (!option.startsWith("take") && !option.equals("bank-all") || rule == null || !ready()) return;
                var claim = preview(rule); if (claim == null || claim.remaining.isEmpty()) return;
                boolean bank = option.equals("bank-all"); requests.removeIf(value -> value.claim != claim);
                request = firstMatch(requests, value -> value.bank == bank);
                if (request == null) {
                    request = new Request(); request.claim = claim;
                    request.owner = history.state; request.tick = plugin.tick(); request.at = now; request.bank = bank;
                    requests.add(request);
                }
                request.last = positive(claim.remaining);
            }
        }

        void container(int id, ItemContainer container) {
            synchronized (history.engine) {
                if (id == net.runelite.api.gameval.InventoryID.INV)
                    for (var value : requests) if (live(value) && !value.bank) value.inventory = true;
                if (!live(request) || id != request.claim.chest || container == null) return; var next = cash(plugin.counts(container));
                if (any(next.entrySet(), item -> item.getValue() > amount(request.last, item.getKey()))) {
                    requests.removeIf(value -> value.claim == request.claim); request = null; return;
                }
                request.last.forEach((item, qty) -> {
                    long gone = qty - amount(next, item); if (gone > 0) request.proof.merge(item, gone, SafeMath::sum);
                }); request.last = next; request.claim.remaining = positive(next);
                assign(request);
            }
        }

        void booked(Transaction row, boolean bank, int chest) {
            synchronized (history.engine) {
                if (row == null || row.isTransfer() || row.original() == TRADE
                        || any(requests, value -> value.rows.containsKey(row))) return;
                var owner = history.engine.sessionHolding(row.id()); if (owner == null) return;
                for (var value : requests) if (live(value) && row.timestamp >= value.at && bank == value.bank
                        && (bank ? chest == value.claim.chest : value.inventory) && value.rows.size() < 32) {
                    value.rows.put(row, owner); assign(value); return;
                }
            }
        }

        void assign(Request request) {
            for (var entry : request.rows.entrySet()) {
                var row = entry.getKey(); var owner = entry.getValue(); if (owner.findTransaction(row.id()) != row) continue;
                var old = row.flows; var next = flowList();
                var proof = new HashMap<>(request.proof); boolean changed = false;
                var before = Accounting.transaction(row);
                for (var flow : old) {
                    long qty = flow == null || flow.quantity <= 0 || flow.raid != null ? 0
                            : min(flow.quantity, amount(proof, flow.item));
                    if (qty == 0) {
                        next.add(flow); continue;
                    }
                    var part = qty == flow.quantity ? SaveCopies.copy(flow) : flow.part(qty); part.raid = request.claim.id; next.add(part);
                    if (qty < flow.quantity) next.add(flow.rest(qty)); proof.put(flow.item, proof.get(flow.item) - qty); changed = true;
                }
                if (!changed) continue; row.replaceFlows(next);
                var after = Accounting.transaction(row);
                if (before.income != after.income || before.cost != after.cost || before.included != after.included) {
                    row.replaceFlows(old); continue;
                }
                request.proof = proof; owner.transactionChanged(row); history.received(request.claim.id, owner, row.timestamp);
            }
        }
    }
}

/** Existing paged Ledger tables embedded in the selected raid, with read-only receipt details. */
class RaidsPage extends Page {
    SidebarPanel panel; JPanel overview = stack(PANEL, GAP), detail = stack(PANEL, GAP);
    Table history = new Table("ATTEMPTS"); LedgerPage ledger;
    Entry entry = Entry.current().withScope(HISTORY, "raid:all", "Raid receipts").live(GAINS); Integer kind;
    String selected;

    RaidsPage(SidebarPanel panel) {
        this.panel = panel;
        var actions = new LedgerController(panel) {
            Entry entry() {
                return RaidsPage.this.entry;
            }

            void entry(Entry next) {
                RaidsPage.this.entry = next;
            }
        }; ledger = new LedgerPage(actions, panel::sprite); ledger.noteWidth = 112;
        ledger.raid = true; ledger.income.title.setToolTipText("Saved loot entries");
        ledger.protect = action -> {
            Object owner = panel.ownerToken; return () -> { if (owner == panel.ownerToken && !panel.suspended) action.run(); };
        }; pad(ledger.body, 0, 0, 0, 0); history.setPageSize(15);
        pad(body, 0, GAP, GAP, GAP); body.add(overview); body.add(history); body.add(detail);
    }

    public String id() {
        return RAIDS;
    }



    void open(Integer kind, String id) {
        open(kind, id, null);
    }

    void open(Integer kind, String id, Semantics.Table table) {
        this.kind = kind; selected = id;
        entry = Entry.current().withScope(LedgerData.Scope.HISTORY, "raid:" + fallback(id, "all"), "Raid receipts")
                        .live(id == null ? GAINS : table);
        ledger.resetOwner(); history.resetPage(); panel.refresh();
    }

    static long net(long[] money) {
        return subtract(money[0], money[1]);
    }

    /** Loot lives in the table below; the summary keeps its signed total and actual death fees. */
    static KeyValue card(String title, long[] money) {
        long net = net(money); var card = new KeyValue(title);
        var value = label(signed(net), numbers(18), sign(net).color);
        value.setToolTipText(gp(net)); card.body.add(Kit.row(value));
        card.body.add(Kit.row(muted("Death fees:"), label(signed(-money[1]), smallFont, LOSS.color)));
        return card;
    }

    /** One raid or attempt row: Net on the right in its tone, the exact amount on hover. */
    static Row row(String id, String name, String detail, long[] money, String tip, Runnable open) {
        long net = net(money);
        return new Row(id, null, name, detail, signed(net), sign(net), tip, gp(net), false,
                open, List.of());
    }

    void apply(RaidHistory.State state, Map<String, long[]> totals, LedgerData data, long now) {
        overview.removeAll(); detail.removeAll(); history.setVisible(selected == null);
        var rows = new ArrayList<Row>();
        if (kind != null || selected != null) overview.add(button(selected == null || kind == null ? msg("prevr")
                : msg("prevatt"), () -> open(selected == null ? null : kind, null)));
        if (kind == null) {
            long[] all = new long[2];
            totals.forEach((id, money) -> {
                if (id.length() == 1) for (int i = 0; i < 2; i++) all[i] = sum(all[i], money[i]);
            }); if (data != null) data.income.total = all[0];
            overview.add(card("All Time Raids", all));
        }
        for (int i = 0; i < RaidHistory.RULES.size(); i++) if ((state.seen & 1 << i) != 0
                && (kind == null && selected == null || kind != null && kind == i)) {
            final int raid = i; long[] money = totals.getOrDefault(Integer.toString(i), new long[2]);
            long clears = state.clears[i] + state.runs.stream()
                    .filter(run -> RaidHistory.kind(run.id) == raid && run.complete).count();
            String name = RaidHistory.RULES.get(i)[1], count = "Clears " + clears;
            if (kind == null) rows.add(row(Integer.toString(i), name, "", money, count, () -> open(raid, null)));
            else if (selected == null) overview.add(note(name + SEPARATOR + count + " · Net " + signed(net(money)), TEXT, 128));
        }
        for (var run : state.runs) if (kind != null && RaidHistory.kind(run.id) == kind) {
            long[] money = totals.getOrDefault(run.id, new long[2]); if (!run.complete && !run.failed && money[1] == 0) continue;
            long took = max(0, (run.ended == 0 ? now : run.ended) - run.started);
            String status = run.claimed ? "Loot received" : run.complete ? "Not claimed"
                    : money[1] == 0 ? "Failed" : "Death Fee",
                caption = status + (run.partial ? " · Partial capture" : "");
            rows.add(row(run.id, status, durationShort(took), money, caption, () -> open(kind, run.id)));
            if (Objects.equals(run.id, selected)) {
                String title = RaidHistory.RULES.get(kind)[1]; detail.add(note(title + SEPARATOR + run.mode, TEXT, 128));
                detail.add(note(caption, LABEL, 128)); Object owner = panel.ownerToken; detail.add(card(null, money));
                detail.add(button("Copy summary", () -> {
                    if (owner != panel.ownerToken || panel.suspended) return;
                    panel.actions.shareSummary(() -> GrindsController.summary(title + SEPARATOR + caption, net(money),
                            money[0], money[1], 0, money[1], true, took));
                }));
            }
        }
        if (data != null) {
            ledger.apply(data); (selected == null ? overview : detail).add(ledger.body());
        }
        history.rowTitle(kind == null ? "RAIDS" : "ATTEMPTS", rows); detail.setVisible(selected != null); repaintLayout(body);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.client.util.Filepath;

public final class GeneralProfitSimulation
{
    private GeneralProfitSimulation()
    {
    }

    public static void main(String[] args) throws Exception
    {
        Path output = args.length == 0
            ? Paths.get("build", "simulation", "general")
            : Paths.get(args[0]);
        SimulationSupport.Suite suite = new SimulationSupport.Suite(
            "General Profit Simulation",
            output);

        suite.run("Opening inventory is baseline-only", GeneralProfitSimulation::openingInventoryIsNotProfit);
        suite.run("Bank and equipment round trips are neutral", GeneralProfitSimulation::bankAndEquipmentTransfersAreNeutral);
        suite.run("NPC loot and consumed supplies calculate exact net", GeneralProfitSimulation::npcLootAndSupplies);
        suite.run("Production inputs and outputs calculate processing margin", GeneralProfitSimulation::processingMargin);
        suite.run("Uncertain mixed changes require correction and support undo", GeneralProfitSimulation::uncertainCorrectionAndUndo);
        suite.run("Pause freezes elapsed time and both rates", GeneralProfitSimulation::pauseFreezesRates);
        suite.run("Idle pause and Auto activity segments preserve active time", GeneralProfitSimulation::idlePauseAndAutoActivity);
        suite.run("Crash-safe state save and restore preserves accounting", () -> crashSafeRestore(output));
        suite.run("Session history summaries preserve financial totals", GeneralProfitSimulation::sessionHistorySummaries);
        suite.run("History renames, corrections, and deletion", GeneralProfitSimulation::historyManagement);
        suite.run("History keeps every finished session, newest first", GeneralProfitSimulation::sessionIntelligenceComplete);
        suite.run("General simulation exports readable CSV files", () -> exportGeneralExample(output));

        suite.finish();
    }

    private static void openingInventoryIsNotProfit()
    {
        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        long start = 100_000L;
        engine.ensureSession(start);
        engine.beginPriming();

        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.empty(), start + 600L, null), "warm-up tick 1");
        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.snapshot(1265, 1L), start + 1_200L, null), "warm-up tick 2");
        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.snapshot(1265, 1L), start + 1_800L, null), "warm-up tick 3");
        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.snapshot(1265, 1L), start + 2_400L, null), "warm-up tick 4");

        SimulationSupport.equal(0L, engine.metrics(start + 2_400L).net, "opening inventory net");
        SimulationSupport.equal(0, engine.session().transactions().size(), "opening inventory transactions");

        engine.markDirty();
        Transaction consumed = SimulationSupport.settle(engine, SimulationSupport.empty(), start + 3_000L);
        SimulationSupport.equal(TransactionType.CONSUMPTION, consumed.type(), "post-baseline removal type");
        SimulationSupport.equal(-100L, consumed.net(), "post-baseline removal value");
    }

    private static void bankAndEquipmentTransfersAreNeutral()
    {
        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        long start = 200_000L;
        engine.ensureSession(start);
        engine.setBaseline(SimulationSupport.snapshot(1265, 1L));

        engine.markContext(Context.TRANSFER, 8, "Bank transfer");
        engine.markDirty();
        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.empty(), start + 600L, null), "temporary removal tick 1");
        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.empty(), start + 1_200L, null), "temporary removal tick 2");

        engine.markDirty();
        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.snapshot(1265, 1L), start + 1_800L, null), "restore tick 1");
        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.snapshot(1265, 1L), start + 2_400L, null), "restore tick 2");
        SimulationSupport.equal(null, engine.processIfDirty(SimulationSupport.snapshot(1265, 1L), start + 3_000L, null), "restore settle");

        SimulationSupport.equal(0, engine.session().transactions().size(), "round-trip transaction count");
        SimulationSupport.equal(0L, engine.metrics(start + 3_000L).net, "round-trip net");
    }

    private static void npcLootAndSupplies()
    {
        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        long start = 300_000L;
        engine.ensureSession(start);
        engine.setBaseline(SimulationSupport.snapshot(379, 4L, 892, 100L, 555, 50L));

        engine.markDirty();
        Transaction supplies = SimulationSupport.settle(
            engine,
            SimulationSupport.snapshot(379, 3L, 892, 90L, 555, 45L),
            start + 600L);
        SimulationSupport.equal(TransactionType.CONSUMPTION, supplies.type(), "supply transaction type");
        SimulationSupport.equal(875L, engine.metrics(start + 2_400L).cost, "all settled supply costs");

        Map<Integer, Long> loot = new LinkedHashMap<>();
        loot.put(526, 1L);
        loot.put(555, 6L);
        engine.recordAction("Goblin");
        engine.markLoot(loot, 50, "Loot from Goblin", "Goblin");
        engine.markDirty();
        Transaction drop = SimulationSupport.settle(
            engine,
            SimulationSupport.snapshot(379, 3L, 892, 90L, 555, 51L, 526, 1L),
            start + 3_000L);

        SimulationSupport.equal(TransactionType.LOOT, drop.type(), "loot transaction type");
        SimulationSupport.equal(Confidence.CONFIRMED, drop.confidence(), "loot confidence");
        SimulationSupport.equal(61L, drop.revenue(), "loot revenue");
        Metrics metrics = engine.metrics(start + 6_000L);
        SimulationSupport.equal(61L, metrics.income, "session revenue");
        SimulationSupport.equal(875L, metrics.cost, "session costs");
        SimulationSupport.equal(-814L, metrics.net, "session net");
    }

    private static void processingMargin()
    {
        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        long start = 400_000L;
        engine.ensureSession(start);
        engine.setBaseline(SimulationSupport.snapshot(1511, 10L));

        engine.markContext(Context.PRODUCTION, 8, "Fletching logs");
        engine.markDirty();
        Transaction processing = SimulationSupport.settle(
            engine,
            SimulationSupport.snapshot(1511, 5L, 50, 5L),
            start + 600L);

        SimulationSupport.equal(TransactionType.PROCESSING, processing.type(), "processing type");
        SimulationSupport.equal(600L, processing.revenue(), "output value");
        SimulationSupport.equal(250L, processing.costs(), "input value");
        SimulationSupport.equal(350L, processing.net(), "processing margin");
    }

    private static void uncertainCorrectionAndUndo()
    {
        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        long start = 500_000L;
        engine.ensureSession(start);
        engine.setBaseline(SimulationSupport.snapshot(995, 100L));

        engine.markDirty();
        Transaction uncertain = SimulationSupport.settle(
            engine,
            SimulationSupport.snapshot(995, 50L, 526, 2L),
            start + 600L);

        SimulationSupport.equal(TransactionType.UNCERTAIN, uncertain.type(), "automatic uncertain type");
        SimulationSupport.check(!uncertain.counts(), "uncertain transaction should be excluded");
        SimulationSupport.equal(0L, engine.metrics(start + 3_000L).net, "uncertain net before correction");

        SimulationSupport.check(
            engine.correctTransaction(uncertain.id(), Correction.REVENUE,
                "Manual revenue correction"),
            "manual revenue correction should apply");
        SimulationSupport.equal(112L, engine.metrics(start + 4_000L).net, "corrected gross revenue");

        Transaction removed = engine.undoTransaction();
        SimulationSupport.equal(uncertain.id(), removed.id(), "undo transaction id");
        SimulationSupport.equal(0, engine.session().transactions().size(), "transactions after undo");
        SimulationSupport.equal(0L, engine.metrics(start + 5_000L).net, "net after undo");
    }

    private static void pauseFreezesRates()
    {
        Session session = new Session("Pause simulation", 0L, SessionMode.GENERAL);
        session.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                TransactionType.GAIN,
                Context.GENERIC,
                "Synthetic gain",
                "General",
                true,
                Collections.singletonList(SimulationSupport.valuedFlow(20001, "Test gain", 1L, 1_000))),
            100, false);

        session.pause(2_000L, PauseReason.MANUAL);
        Metrics atPause = session.metrics(2_000L);
        Metrics oneMinuteLater = session.metrics(62_000L);
        SimulationSupport.equal(atPause.elapsed, oneMinuteLater.elapsed, "paused elapsed time");
        SimulationSupport.equal(atPause.rate, oneMinuteLater.rate, "paused session rate");

        session.resume(62_000L);
        SimulationSupport.equal(3_000L, session.metrics(63_000L).elapsed, "resumed active time");
    }

    private static void idlePauseAndAutoActivity()
    {
        Engine engine = SimulationSupport.newEngine(SessionMode.AUTO);
        engine.ensureSession(0L);
        engine.setDetectedActivity("PvM", 500L);
        engine.setDetectedActivity("Skilling", 1_000L);

        SimulationSupport.equal("Skilling", engine.metrics(1_000L).activity, "auto activity hint");

        engine.session().pause(2_000L, PauseReason.IDLE);
        SimulationSupport.check(engine.isIdlePaused(), "engine must record idle pause reason");
        long frozenElapsed = engine.metrics(8_000L).elapsed;
        SimulationSupport.equal(2_000L, frozenElapsed, "idle pause frozen elapsed");

        engine.resume(8_000L, PauseReason.IDLE);
        SimulationSupport.check(!engine.isIdlePaused(), "idle pause must clear after activity");
        SimulationSupport.equal(3_000L, engine.metrics(9_000L).elapsed, "active time after idle resume");
    }

    private static void crashSafeRestore(Path output) throws Exception
    {
        Path stateDirectory = output.resolve("state-recovery");
        Files.createDirectories(stateDirectory);
        SessionRepository repository = new SessionRepository(new Gson(), Filepath.Unchecked.getRooted(stateDirectory), false);
        Session session = new Session("Recovered session", 1_000L, SessionMode.GENERAL);
        session.addTransaction(
            Tx.of(
                2_000L,
                TransactionType.LOOT,
                Context.LOOT,
                "Recovered loot",
                true,
                Collections.singletonList(SimulationSupport.gain(526, 2L))),
            100, false);
        repository.save(new WriteIntent(null, repository.generation,
            repository.revision, new SavedState(session, null, Collections.emptyList()), null));

        SavedState restored = repository.load();
        SimulationSupport.check(SimulationSupport.currentSession(restored) != null, "active session should restore");
        SimulationSupport.equal("Recovered session", SimulationSupport.currentSession(restored).name(), "restored session name");
        SimulationSupport.equal(62L, SimulationSupport.currentSession(restored).metrics(3_000L).net, "restored session net");

        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        engine.restore(restored, SafeMath.now());
        SimulationSupport.equal(PauseReason.RECOVERY, engine.session().pauseReason(),
            "interrupted active session waits paused for recovery");
    }

    private static void sessionHistorySummaries()
    {
        Session profitable = new Session("Profitable", 0L, SessionMode.GENERAL);
        profitable.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                TransactionType.GAIN,
                Context.GENERIC,
                "Historical profit",
                "General",
                true,
                Collections.singletonList(SimulationSupport.valuedFlow(20010, "Profit", 1L, 1_000))),
            100, false);
        profitable.close(3_600_000L);

        Session loss = new Session("Loss", 0L, SessionMode.GENERAL);
        loss.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                TransactionType.CONSUMPTION,
                Context.GENERIC,
                "Historical loss",
                "General",
                true,
                Collections.singletonList(SimulationSupport.valuedFlow(20011, "Cost", -1L, 500))),
            100, false);
        loss.close(3_600_000L);

        Session current = new Session("Current", 0L, SessionMode.GENERAL);
        current.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                TransactionType.GAIN,
                Context.GENERIC,
                "Current profit",
                "General",
                true,
                Collections.singletonList(SimulationSupport.valuedFlow(20012, "Current", 1L, 600))),
            100, false);

        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        engine.restore(new SavedState(current, null, Arrays.asList(profitable, loss)), 3_600_000L);

        SimulationSupport.equal(2, engine.history().size(), "compared session count");
        SimulationSupport.equal(600L, engine.metrics(3_600_000L).net, "current net");
        SimulationSupport.equal(1_000L, engine.historyMetrics(profitable.id(), 3_600_000L).net, "best historical net");
        SimulationSupport.equal(-500L, engine.historyMetrics(loss.id(), 3_600_000L).net, "worst historical net");
    }

    private static void historyManagement()
    {
        Session pvm = new Session("Bossing", 0L, SessionMode.GENERAL);
        pvm.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                TransactionType.LOOT,
                Context.LOOT,
                "Boss loot",
                "Bossing",
                true,
                Collections.singletonList(SimulationSupport.valuedFlow(21000, "Boss drop", 1L, 1_000))),
            100, false);
        pvm.close(3_600_000L);

        Session skilling = new Session("Fletching", 0L, SessionMode.GENERAL);
        skilling.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                TransactionType.PROCESSING,
                Context.PRODUCTION,
                "Fletching",
                "Fletching",
                true,
                Collections.singletonList(SimulationSupport.valuedFlow(21001, "Bow", 1L, 500))),
            100, false);
        skilling.close(3_600_000L);

        Session trading = new Session("Flipping", 0L, SessionMode.GENERAL);
        Transaction tradeLoss = Tx.of(
            1_000L,
            1_000L,
            TransactionType.TRADE,
            Context.MARKET,
            "Trade loss",
            "Market",
            true,
            Collections.singletonList(SimulationSupport.valuedFlow(21002, "Trade", -1L, 200)));
        trading.addTransaction(tradeLoss, 100, false);
        trading.close(3_600_000L);

        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        engine.restore(new SavedState(null, null, Arrays.asList(pvm, skilling, trading)), 3_600_000L);

        engine.historySession(pvm.id()).rename("Vorkath");

        Metrics before = engine.historyMetrics(trading.id(), 3_600_000L);
        SimulationSupport.equal(-200L, before.net, "historical net before correction");
        SimulationSupport.check(
            engine.historySession(trading.id()).correctTransaction(
                tradeLoss.id(), Correction.REVENUE, "Manual correction"),
            "historical correction");
        Metrics after = engine.historyMetrics(trading.id(), 4_000_000L);
        SimulationSupport.equal(200L, after.net, "historical net after correction");

        SimulationSupport.check(engine.deleteHistory(skilling.id()), "history deletion");
        SimulationSupport.equal(2, engine.history().size(), "history size after deletion");
    }

    private static void sessionIntelligenceComplete()
    {
        long day = 24L * 60L * 60L * 1000L;
        long now = 100L * day;
        Session pvm = completedSession("Vorkath", now - day, Context.LOOT, TransactionType.LOOT, 1_000L);
        Session skilling = completedSession("Fletching", now - 10L * day, Context.PRODUCTION, TransactionType.PROCESSING, 500L);
        Session trading = completedSession("Flipping", now - 40L * day, Context.MARKET, TransactionType.TRADE, -200L);

        Engine engine = SimulationSupport.newEngine(SessionMode.GENERAL);
        engine.restore(new SavedState(null, null, Arrays.asList(pvm, skilling, trading)), now);

        SimulationSupport.equal(3, engine.history().size(), "history retained");
        SimulationSupport.equal("Vorkath", engine.history().get(0).name(), "newest first");
    }

    private static Session completedSession(
        String name, long start, Context context, TransactionType type, long value)
    {
        Session session = new Session(name, start, SessionMode.GENERAL);
        long quantity = value < 0L ? -1L : 1L;
        session.addTransaction(Tx.of(
            start + 1_000L, 1_000L, type, context, name, name, true,
            Collections.singletonList(new Flow(31_000, "Item", quantity, (int) Math.abs(value), value))), 100, false);
        session.close(start + 3_600_000L);
        return session;
    }

