    @Test
    public void aFreshStartLeavesEarlierEstimatesBookedButOutOfTheNextCheck()
    {
        GpManagerConfig config = new GpManagerConfig() {};
        Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[]{Client.class}, (proxy, method, args) ->
            {
                if (method.getName().equals("getTickCount")) return 10;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
        ChargeIntake intake = new ChargeIntake(client, null, config, engine, null);
        assertTrue(intake.startCheck(ChargeCheck.ChargedItem.TRIDENT_SEAS, "a", 10, 2));
        assertTrue(intake.observeCheck("Your Trident of the seas has 100 charges.", 1_001L));
        Transaction cast = engine.bookEstimatedCharge("a", "Trident of the seas", ActionKind.CAST,
            Collections.singletonList(new Flow(ItemID.DEATHRUNE, "Death rune", -1, 100, -100,
                PriceSource.GRAND_EXCHANGE)), 1_002L);
        String session = engine.session().id();
        assertEquals(1L, ChargeProbes.adp(engine.estimate, session, "a", "seas", ItemID.DEATHRUNE));

        // A recharge read ("charged with") arrives before its load books: a fresh start.
        assertTrue(intake.startCheck(ChargeCheck.ChargedItem.TRIDENT_SEAS, "a", 10, 2));
        assertTrue(intake.observeCheck("Your Trident of the seas has 150 charges.", 1_003L));
        assertEquals("the next Check never reconciles it", 0L,
            ChargeProbes.adp(engine.estimate, session, "a", "seas", ItemID.DEATHRUNE));
        assertTrue("the cast stays booked", cast.counts());
        assertEquals(100L, engine.metrics(2_000L).cost);
    }

    @Test
    public void nonSpendOutcomesCannotAuthorizeValuedLosses()
    {
        ChargeDelta load = new ChargeDelta(ChargeCheck.ChargedItem.TRIDENT_SEAS,
            Collections.singletonList(new ChargeDelta.ComponentDelta(ItemID.DEATHRUNE, -1)),
            ChargeDelta.CheckResult.LOAD);
        assertEquals(0L, load.exactCost(Collections.singletonList(
            new Flow(ItemID.DEATHRUNE, "Death rune", -1, 100, -100, PriceSource.GRAND_EXCHANGE))));
    }
}

package com.gpmanager;

import java.util.List;

/** Read-only charge lookups the tests assert on; the plugin itself never needs them. */
final class ChargeProbes
{
    private ChargeProbes()
    {
    }

    /** The family's first pinned local cast graphic (d20); 0 means no automatic estimate. */
    static int nx(ChargeCheck.ChargedItem variant)
    {
        return variant.graphics.length == 0 ? 0 : variant.graphics[0];
    }

    /** The journal's still-open estimated quantity of one component for one weapon. */
    static long adp(ChargeEstimateJournal journal, String sessionId, String targetIdentity, String family, int itemId)
    {
        long total = 0L;
        for (ChargeEstimateJournal.Receipt receipt : journal.receipts(sessionId, targetIdentity, itemId))
        {
            total = SafeMath.sum(total, Math.max(0L, receipt.remaining));
        }
        return total;
    }
}

package com.gpmanager;

import java.util.Collections;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.*;

/** Window closure, leftover removal, and the bounded journal's overlap memory. */
public class ChargeReconciliationWindowTest
{
    private static final long T0 = 10_000L;

    @Test
    public void clearingATargetKeepsTheReceiptBoundHonest()
    {
        ChargeEstimateJournal journal = new ChargeEstimateJournal();
        for (int i = 0; i < ChargeEstimateJournal.MAX_RECEIPTS; i++)
        {
            journal.record("s1", "slot", "tx" + i, 1, 1L);
        }
        journal.clearTarget("s1", "slot");
        for (int i = 0; i < ChargeEstimateJournal.MAX_RECEIPTS; i++)
        {
            journal.record("s1", "slot", "ty" + i, 1, 1L);
        }
        assertEquals("a cleared target must not evict its replacements early",
            ChargeEstimateJournal.MAX_RECEIPTS, journal.receipts("s1", "slot", 1).size());
    }

    @Test
    public void evictedReceiptsKeepTheirWindowOverlapUntilCleared()
    {
        ChargeEstimateJournal journal = new ChargeEstimateJournal();
        for (int i = 0; i < ChargeEstimateJournal.MAX_RECEIPTS + 3; i++)
        {
            journal.record("s1", "slot", "tx" + i, 1, 2L);
        }
        assertEquals("evicted quantities stay visible to reconciliation", 6L,
            journal.evictedOverlap("s1", "slot", 1));
        journal.clearTarget("s1", "slot");
        assertEquals(0L, journal.evictedOverlap("s1", "slot", 1));
    }

    @Test
    public void leftoverEstimatesAreRemovedWhenACheckClosesTheWindow()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Transaction first = estimate(engine, T0 + 1L);
        Transaction second = estimate(engine, T0 + 2L);
        Transaction third = estimate(engine, T0 + 3L);

        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.TRIDENT_SEAS,
            Collections.singletonList(new ChargeDelta.ComponentDelta(ItemID.DEATHRUNE, -1L)), ChargeDelta.CheckResult.SPEND);
        Transaction measured = engine.bookChargeSpend(delta, "Trident of the seas",
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -1L, 100)), T0 + 4L, "slot-a");

        assertNull("the surviving estimate already booked the measured unit", measured);
        assertEquals(1L, first.quantity(ItemID.DEATHRUNE, false));
        assertEquals(0L, second.quantity(ItemID.DEATHRUNE, false));
        assertEquals(0L, third.quantity(ItemID.DEATHRUNE, false));
        assertEquals(Correction.IGNORE, second.correction());
        assertEquals(Correction.IGNORE, third.correction());
        assertEquals(0L, ChargeProbes.adp(engine.estimate,
            engine.session().id(), "slot-a", "seas", ItemID.DEATHRUNE));
    }

    @Test
    public void aCompatibleCheckThatMovedNothingClosesTheWindow()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Transaction first = estimate(engine, T0 + 1L);
        Transaction second = estimate(engine, T0 + 2L);

        engine.closeChargeWindow("slot-a");

        assertEquals(0L, first.quantity(ItemID.DEATHRUNE, false));
        assertEquals(0L, second.quantity(ItemID.DEATHRUNE, false));
        assertEquals(Correction.IGNORE, first.correction());
        assertEquals(Correction.IGNORE, second.correction());
        assertEquals(0L, ChargeProbes.adp(engine.estimate,
            engine.session().id(), "slot-a", "seas", ItemID.DEATHRUNE));
    }

    private static Transaction estimate(Engine engine, long at)
    {
        return engine.bookEstimatedCharge("slot-a", "seas", ActionKind.CAST,
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -1L, 100)), at);
    }

    private static Flow flow(int id, String name, long quantity, int unit)
    {
        return new Flow(id, name, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE);
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), new GpManagerConfig() {});
    }
}

package com.gpmanager;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.gpmanager.ChargeCheck.ChargedItem.*;
import com.gpmanager.ChargeCheck.ChargedItem;
import static com.gpmanager.ActionSignals.rule;
import static com.gpmanager.GameData.msg;
import static com.gpmanager.Phrases.lower;
import static com.gpmanager.FlowFilters.firstMatch;

/** The optional possessive sharing must retain every supported and malformed Check surface. */
public class ChargeSurfaceTrimTest {
    @Test public void everyCatalogueNameAndPrefixKeepsItsPreviousSurface() {
        for (var item : ChargedItem.values()) {
            assertFalse(item.displayName, lower(item.displayName, false).startsWith("your "));
            for (String prefix : List.of("", "your ", "your your ", "the ", "other "))
                for (String suffix : List.of(" has 1 charge.", " only has 1 charge.", " has junk",
                        " only has ", " has", " has no charges left.", " has 999999999999999999999999 charges.")) {
                    String line = prefix + lower(item.displayName, false) + suffix;
                    assertEquals(line, previousSurface(line), ChargeCheck.surface(line));
                }
        }
        for (String line : List.of("", "your tome is charged with soaked pages.",
                "your tome is charged with soiled pages.", "the pendant has 4 charges.",
                "your bow has 1 charge.", "your sailors' amulet has 106 charges."))
            assertEquals(line, previousSurface(line), ChargeCheck.surface(line));
    }

    static ChargedItem previousSurface(String lower) {
        if (rule("blowpipe-check", lower)) return BLOWPIPE; if (lower.startsWith("the pendant has ")) return ATES;
        if (rule("sailors-check", lower))
            // The sailors' amulet's own Check wording ("...has 106 charges." or "...charges
            // left."); the blood fury's hit-count line names itself below (owner 2026-10-14).
            return SAILORS_AMULET;
        if (lower.startsWith(msg("tomeCharged")))
        {
            // The page names the tome; a bare "your tome" line stays fire and the clicked row
            // redirects it (owner 2026-10-12).
            if (lower.contains("soaked")) return TOME_OF_WATER; return lower.contains("soiled") ? TOME_OF_EARTH : TOME_OF_FIRE;
        }
        if (lower.startsWith(msg("amuletBlood"))) return BLOOD_FURY;
        if (lower.startsWith(msg("eyeCapacity")) || lower.startsWith(msg("eyeLoaded")))
            return EYE_OF_AYAK;
        for (var variant : ChargedItem.values()) {
            if (variant == BLOWPIPE) continue; String name = lower(variant.displayName, false);
            if (lower.startsWith("your " + name + " has ") || lower.startsWith("your " + name + " only has ")
                    || lower.startsWith(name + " has ") || lower.startsWith(name + " only has "))
                return variant;
        }
        // A Check that names no weapon ("Your bow has…"): the first row sharing that wording.
        return firstMatch(List.of(ChargedItem.values()), variant -> variant.check != null && variant.check.matcher(lower).matches());
    }

}

package com.gpmanager;

import com.google.gson.Gson;
import java.lang.management.ManagementFactory;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * 1.7.0: a reward chest's measured Bank-all decrease is checked, spent and re-armed in one
 * engine-then-inbox hold, and the production owner fence takes the same order. A fence that
 * arrives while a chest is being consumed lands after it: no foreign receipt, no stale re-arm for
 * the next owner and no lock inversion.
 */
public class ChestConsumeOwnerTest
{
    private static final long T0 = 1_700_000_000_000L;

    private static final class Rig
    {
        final int[] tick = {100};
        final Item[][] chest = {{new Item(ItemID.TWISTED_BOW, 1), new Item(ItemID.DRAGON_ARROW, 50)}};
        final AtomicReference<Runnable> onValue = new AtomicReference<>();
        final Engine engine;
        final Persistence persistence;
        final GpManagerPlugin plugin = new GpManagerPlugin();
        final ItemContainer rewards;

        Rig()
        {
            JsonCodec.bind(new Gson());
            engine = new Engine(deltas ->
            {
                Runnable hook = onValue.getAndSet(null);
                if (hook != null) hook.run();
                List<Flow> result = new ArrayList<>();
                deltas.forEach((id, q) -> result.add(new Flow(id, "Item " + id, q, 100, q * 100)));
                return result;
            }, new TransactionClassifier(), new GpManagerConfig() {});
            engine.ensureSession(T0);
            engine.setBaseline(FixtureReads.empty());
            persistence = new Persistence(null, null, null, null, engine);
            persistence.activeIdentity = new TrackingIdentity("rsprofile.alice", 1L);
            persistence.fence();
            rewards = (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
                new Class<?>[]{ItemContainer.class},
                (proxy, method, args) -> "getItems".equals(method.getName()) ? chest[0] : null);
            Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
                (proxy, method, args) ->
                {
                    if ("getTickCount".equals(method.getName())) return tick[0];
                    if ("getItemContainer".equals(method.getName()))
                        return (int) args[0] == InventoryID.RAIDS_REWARDS ? rewards : null;
                    return null;
                });
            plugin.engine = engine;
            plugin.client = client;
            plugin.containers = new ContainerSnapshotFactory(client, null);
        }

        void bankAll()
        {
            plugin.bankAll(InterfaceID.RAIDS_REWARDS);
        }

        void changed()
        {
            plugin.chestChanged(InventoryID.RAIDS_REWARDS, rewards);
        }

        Observation chestProof()
        {
            return engine.events.peek(Inbox.CHEST, v -> true);
        }
    }

    @Test
    public void aFenceDuringConsumptionLandsAfterItWithNoStaleReArm() throws Exception
    {
        Rig rig = new Rig();
        rig.bankAll();
        rig.chest[0] = new Item[]{new Item(ItemID.DRAGON_ARROW, 20)};
        rig.tick[0]++;
        AtomicBoolean fenced = new AtomicBoolean();
        Thread[] fence = new Thread[1];
        rig.onValue.set(() ->
        {
            // An account switch fences the owner while the first portion is being booked.
            fence[0] = new Thread(() ->
            {
                rig.persistence.activeIdentity = new TrackingIdentity("rsprofile.bob", 2L);
                rig.persistence.fence();
                fenced.set(true);
            });
            fence[0].start();
            try
            {
                fence[0].join(300L);
            }
            catch (InterruptedException ex)
            {
                throw new AssertionError(ex);
            }
        });

        rig.changed();
        fence[0].join(5_000L);
        assertTrue("the fence completes once the chest hold ends", fenced.get());
        assertEquals("the whole decrease belongs to the owner that sampled it", 1L,
            RewardChestBankAllTest.received(rig.engine, ItemID.TWISTED_BOW));
        assertEquals(30L, RewardChestBankAllTest.received(rig.engine, ItemID.DRAGON_ARROW));
        assertNull("no chest proof is re-armed for the next owner", rig.chestProof());
    }

    @Test
    public void anAccountRoundTripNeverReusesTheOldChestProof()
    {
        Rig rig = new Rig();
        rig.bankAll();
        rig.persistence.activeIdentity = new TrackingIdentity("rsprofile.bob", 2L);
        rig.persistence.fence();
        rig.persistence.activeIdentity = new TrackingIdentity("rsprofile.alice", 1L);
        rig.persistence.fence();
        rig.chest[0] = new Item[0];
        rig.tick[0]++;
        rig.changed();
        assertEquals("A -> B -> A: the earlier click proves nothing", 0L,
            RewardChestBankAllTest.received(rig.engine, ItemID.TWISTED_BOW));
        assertNull(rig.chestProof());
    }

    @Test
    public void partialRepeatedAndExpiredDecreasesStayExactlyOnce()
    {
        Rig rig = new Rig();
        rig.bankAll();
        rig.chest[0] = new Item[]{new Item(ItemID.TWISTED_BOW, 1), new Item(ItemID.DRAGON_ARROW, 40)};
        rig.tick[0]++;
        rig.changed();
        rig.changed();
        assertEquals("a repeated callback moves nothing", 10L,
            RewardChestBankAllTest.received(rig.engine, ItemID.DRAGON_ARROW));
        rig.chest[0] = new Item[]{new Item(ItemID.DRAGON_ARROW, 40)};
        rig.tick[0]++;
        rig.changed();
        assertEquals(1L, RewardChestBankAllTest.received(rig.engine, ItemID.TWISTED_BOW));
        rig.plugin.chestChanged(InventoryID.BANK, rig.rewards);
        rig.chest[0] = new Item[0];
        rig.tick[0] += 11;
        rig.changed();
        assertEquals("after the window nothing more is proof", 10L,
            RewardChestBankAllTest.received(rig.engine, ItemID.DRAGON_ARROW));
    }

    @Test
    public void chestConsumptionAndOwnerFencesNeverDeadlock() throws Exception
    {
        Rig rig = new Rig();
        int rounds = 200;
        CyclicBarrier start = new CyclicBarrier(2);
        CountDownLatch done = new CountDownLatch(2);
        AtomicReference<Throwable> failure = new AtomicReference<>();
        Thread client = new Thread(() ->
        {
            try
            {
                start.await(5, TimeUnit.SECONDS);
                for (int i = 0; i < rounds; i++)
                {
                    rig.chest[0] = new Item[]{new Item(ItemID.TWISTED_BOW, 1), new Item(ItemID.DRAGON_ARROW, 50)};
                    rig.bankAll();
                    rig.chest[0] = new Item[]{new Item(ItemID.DRAGON_ARROW, 25)};
                    rig.changed();
                }
            }
            catch (Throwable ex)
            {
                failure.compareAndSet(null, ex);
            }
            finally
            {
                done.countDown();
            }
        });
        Thread lifecycle = new Thread(() ->
        {
            try
            {
                start.await(5, TimeUnit.SECONDS);
                for (int i = 0; i < rounds; i++) rig.persistence.fence();
            }
            catch (Throwable ex)
            {
                failure.compareAndSet(null, ex);
            }
            finally
            {
                done.countDown();
            }
        });
        client.start();
        lifecycle.start();
        boolean finished = done.await(20, TimeUnit.SECONDS);
        long[] deadlocked = ManagementFactory.getThreadMXBean().findDeadlockedThreads();
        assertNull("no lock inversion", deadlocked);
        assertTrue(finished);
        assertNull(failure.get());
        assertFalse(client.isAlive() && lifecycle.isAlive());
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collections;
