 @Test public void malformedOverflowingAndAmbiguousPairsStayUntouched(){
  for(int state=0;state<3;state++){
   var h=new DelayedPriceFixture();var row=h.sip();if(state==0)row.flows().get(0).quantity=Long.MIN_VALUE;
