    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(spam("Payment has been taken from your coffer: 15,325 Coins."));
        plugin.onChatMessage(spam("Payment has been taken from your bank: 9,675 x Coins"));
        assertEquals(25_000L, engine.metrics(2_000L).cost);
        assertEquals(2, engine.session().transactions().size());
    }

    @Test
    public void aLaterBankPaymentIsNotAnInstanceFee() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(spam("Payment has been taken from your coffer: 15,325 Coins."));
        tick++;
        plugin.onChatMessage(spam("Payment has been taken from your bank: 9,675 x Coins"));
        assertEquals(15_325L, engine.metrics(2_000L).cost);
    }

    @Test
    public void aCofferOnlyInstanceFeeBooksTheCapturedLiveLine() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(spam("Payment has been taken from your coffer: 12,500 Coins."));
        assertEquals(12_500L, engine.metrics(2_000L).cost);
        assertEquals(1, engine.session().transactions().size());
    }

    @Test
    public void aSpamBankLineWithNoCofferBooksTheBankPaidFee() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(spam("Payment has been taken from your bank: 12,500 Coins."));
        assertEquals(12_500L, engine.metrics(2_000L).cost);
        assertEquals(1, engine.session().transactions().size());
        assertEquals("Instance fee (bank)",
            engine.session().transactions().get(0).note());
    }

    @Test
    public void aGameMessageBankLineIsNotAnInstanceFee() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(gameMessage("Payment has been taken from your bank: 12,500 Coins."));
        assertEquals(0L, engine.metrics(2_000L).cost);
        assertEquals(0, engine.session().transactions().size());
    }

    private Engine engine()
    {
        Engine engine = new Engine(deltas -> {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, qty) -> flows.add(new Flow(id, "Item " + id, qty, 1, qty)));
            return flows;
        }, new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        engine.setBaseline(FixtureReads.empty());
        return engine;
    }

    private GpManagerPlugin plugin(Engine engine) throws Exception
    {
        GpManagerPlugin plugin = new GpManagerPluginProbe();
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[] {Client.class},
            (proxy, method, args) -> "getTickCount".equals(method.getName()) ? tick : null);
        set(plugin, "config", config);
        set(plugin, "engine", engine);
        set(plugin, "client", client);
        set(plugin, "charges", new ChargeIntake(null, null, config, engine, null));
        return plugin;
    }

    private static ChatMessage spam(String text)
    {
        ChatMessage message = new ChatMessage();
        message.setType(ChatMessageType.SPAM);
        message.setMessage(text);
        return message;
    }

    private static ChatMessage gameMessage(String text)
    {
        ChatMessage message = new ChatMessage();
        message.setType(ChatMessageType.GAMEMESSAGE);
        message.setMessage(text);
        return message;
    }

}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/** The interaction tracker titles NPCs only: scenery and opponent names never publish. */
public class InteractionContextTrackerTest
{
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void sceneryClicksNeverTitle()
    {
        Harness harness = new Harness();
        harness.clickObject("Bank", 100);
        assertEquals("a bank booth is not an activity", "", harness.last());
        harness.clickObject("Chop down", 200);
        assertEquals("a tree is not an activity either", "", harness.last());
    }

    @Test
    public void npcTargetsTitleButPlayerNamesDoNot()
    {
        Harness harness = new Harness();
        harness.interact(harness.npc("Goblin", 2));
        assertEquals("Goblin", harness.last());
        harness.interact(harness.player("Rival"));
        assertEquals("opponent names never display", "", harness.last());
    }

    @Test
    public void aCombatTargetSurvivesSceneryClicks()
    {
        Harness harness = new Harness();
        harness.interact(harness.npc("Vorkath", 732));
        harness.clickObject("Open", 300);
        assertEquals("Vorkath", harness.last());
    }

    private static final class Harness
    {
        private final Engine engine;
        private final Client client;
        private final Player local;
        private final InteractionContextTracker tracker;
        private String published = "";

        Harness()
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override
                public int stabilizationTicks()
                {
                    return 0;
                }
            };
            engine = new Engine(deltas ->
            {
                List<Flow> flows = new ArrayList<>();
                deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Item " + id, quantity, 50, quantity * 50)));
                return flows;
            }, new TransactionClassifier(), config);
            engine.ensureSession(T0);
            local = player("Local");
            client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
                (proxy, method, args) ->
                {
                    switch (method.getName())
                    {
                        case "getLocalPlayer": return local;
                        case "getObjectDefinition": return object(args == null || args.length == 0 ? "" : "Scenery");
                        default:
                            if (method.getReturnType() == boolean.class) return false;
                            if (method.getReturnType() == int.class) return 0;
                            if (method.getReturnType() == long.class) return 0L;
                            return null;
                    }
                });
            tracker = new InteractionContextTracker(client, engine, config);
            tracker.bindPresentation(() -> true, (name, combat) -> published = name == null ? "" : name);
        }

        String last()
        {
            return published;
        }

        void interact(Actor target)
        {
            tracker.onInteractingChanged(new InteractingChanged(local, target));
        }

        void clickObject(String option, int id)
        {
            tracker.onMenuOptionClicked(new MenuOptionClicked(menu(option, id, MenuAction.GAME_OBJECT_FIRST_OPTION)));
        }

        Player player(String name)
        {
            return (Player) Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[] {Player.class},
                (proxy, method, args) ->
                {
                    if ("getName".equals(method.getName())) return name;
                    if ("isDead".equals(method.getName())) return false;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return 0L;
                    return null;
                });
        }

        NPC npc(String name, int combatLevel)
        {
            return (NPC) Proxy.newProxyInstance(NPC.class.getClassLoader(), new Class<?>[] {NPC.class},
                (proxy, method, args) ->
                {
                    if ("getName".equals(method.getName())) return name;
                    if ("getCombatLevel".equals(method.getName())) return combatLevel;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return 0L;
                    return null;
                });
        }

        private static ObjectComposition object(String name)
        {
            return (ObjectComposition) Proxy.newProxyInstance(ObjectComposition.class.getClassLoader(),
                new Class<?>[] {ObjectComposition.class}, (proxy, method, args) ->
                {
                    if ("getName".equals(method.getName())) return name;
                    if ("getImpostorIds".equals(method.getName())) return null;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return 0L;
                    return null;
                });
        }

        private static MenuEntry menu(String option, int id, MenuAction action)
        {
            return (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
                new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
                {
                    if ("getOption".equals(method.getName())) return option;
                    if ("getId".equals(method.getName())) return id;
                    if ("getType".equals(method.getName())) return action;
                    if ("getIdentifier".equals(method.getName())) return id;
                    if ("getItemOp".equals(method.getName())) return 0;
                    if ("isItemOp".equals(method.getName())) return false;
                    if ("getWidget".equals(method.getName())) return null;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return 0L;
                    return null;
                });
        }
    }
}

package com.gpmanager;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** Menu/chat vocabulary that becomes an accounting intent; anything else stays ambiguous. */
public class InventoryConsumptionOptionTest
{
    @Test
    public void recognisesSupportedInventoryConsumeOptions()
    {
        for (String option : new String[] {"bury", "scatter", "eat", "drink", "empty", "break", "cast", "release", "teleport", "eat 1", "drink 1", "light", "offer", "tend-to"})
        {
            assertTrue(option, ActionSignals.isSpend(option));
        }
        assertFalse(ActionSignals.isSpend("cook"));
        assertTrue(ActionSignals.isSpendName("light"));
        assertFalse(ActionSignals.isSpendName("cook"));
    }

    @Test
    public void ignoresDropUseAndBankishOptions()
    {
        for (String option : new String[] {"drop", "use", "wear", "wield", "deposit", ""})
        {
            assertFalse(option, ActionSignals.isSpend(option));
        }
        assertFalse(ActionSignals.isSpend(null));
    }

    @Test
    public void transformOptionsArmProductionBySkill()
    {
        assertEquals("Cooking", ActionSignals.transformSkill("cook"));
        assertEquals("Smelting", ActionSignals.transformSkill("smelt"));
        assertEquals("Herblore", ActionSignals.transformSkill("clean"));
        assertEquals("Fletching", ActionSignals.transformSkill("fletch"));
        assertEquals("", ActionSignals.transformSkill("eat"));
        assertTrue(FixtureReads.lightsFire("use", "Tinderbox -> Willow logs"));
        assertFalse(FixtureReads.lightsFire("use", "Willow logs"));
        assertTrue(FixtureReads.offersBones("use", "Dragon bones -> Altar"));
        assertTrue(ActionSignals.isOffering("cast", "Sinister Offering"));
    }

    @Test
    public void recognisesHarvestGatherOptionsForActivityHints()
    {
        assertTrue(ActionSignals.namesActivityOnly("pick"));
        assertTrue(ActionSignals.namesActivityOnly("harvest"));
        assertTrue(ActionSignals.namesActivityOnly("chop down"));
        assertTrue(ActionSignals.namesActivityOnly("mine"));
        assertFalse(ActionSignals.namesActivityOnly("rake"));
        assertEquals("Farming", ActionSignals.gatherActivity("pick"));
        assertEquals("Woodcutting", ActionSignals.gatherActivity("chop"));
        assertEquals("Mining", ActionSignals.gatherActivity("mine"));
        assertEquals("Fishing", ActionSignals.gatherActivity("fish"));
        assertEquals("General", ActionSignals.gatherActivity("open"));
    }

    @Test
    public void recognisesLiveConsumptionChatMessages()
    {
        assertTrue(ActionSignals.isChatSpend("you drink some of your prayer potion."));
        assertTrue(ActionSignals.isChatSpend("you dig a hole and bury the bones."));
        assertTrue(ActionSignals.isChatSpend("you eat the lobster."));
        assertTrue(ActionSignals.isChatSpend("you scatter the ashes."));
        assertTrue(ActionSignals.isChatSpend("the gods are very pleased with your offering."));
        assertFalse("bone-save keeps the bone: never a spend", ActionSignals.isChatSpend("the dark lord spares your sacrifice but still rewards you."));
        assertTrue(ActionSignals.isSpared("The Dark Lord spares your sacrifice."));
        assertFalse(ActionSignals.isChatSpend("you pick a potato."));
        assertFalse(ActionSignals.isChatSpend(""));
        assertFalse(ActionSignals.isChatSpend(null));
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Taking items out of a tackle box (or another kit with its own window) is neutral (owner 1.2). */
public class KitWithdrawTest
{
    static ItemContainer holding(Item... items)
    {
        return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[]{ItemContainer.class}, (proxy, method, args) -> "getItems".equals(method.getName()) ? items : null);
    }

    static Engine withdraw(int kitEvents)
    {
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(1_000_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        GpManagerPlugin plugin = new GpManagerPlugin();
        plugin.engine = engine;
        if (kitEvents > 0)
        {
            plugin.kit(InventoryID.TACKLE_BOX, holding(new Item(ItemID.DRAGON_HARPOON, 1)));
        }
        if (kitEvents > 1)
        {
            plugin.kit(InventoryID.TACKLE_BOX, holding());
        }
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.DRAGON_HARPOON, 1L))), 1_000_000L + tick * 600L, null);
        }
        return engine;
    }

    @Test
    public void takingAHarpoonOutOfTheTackleBoxIsNotLoot()
    {
        Engine engine = withdraw(2);
        assertEquals(0L, engine.metrics(1_010_000L).net);
        assertTrue(engine.session().transactions().toString(),
            engine.session().transactions().stream().noneMatch(Transaction::counts));
    }

    @Test
    public void withoutTheKitChangingTheSameItemCountsAsAGain()
    {
        assertTrue(withdraw(0).metrics(1_010_000L).net > 0L);
    }

    @Test
    public void openingAKitForTheFirstTimeIsNotEvidence()
    {
        assertTrue("a kit loading is not a withdrawal", withdraw(1).metrics(1_010_000L).net > 0L);
    }
}

package com.gpmanager;

import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Login recheck must never infer a grave recovery from item overlap. Genuine income stays booked
 * before and after a death, ambiguous historical rows wait for the owner's explicit correction,
 * and an actual neutral recovery books nothing.
 */
public class LegacyGraveRepairTest
{
    private static final int WHIP = 4151;
    private static final int AVA = 10499;
    private static final int SEED_POD = 19564;
    private static final int BONES = 526;
    private static final int TWISTED_BOW = 20997;
    private static final long T0 = ReviewFixesTest.T0;
    private static final long MINUTE = 60_000L;
    private static final long VALUE = 1_600_000L;

    @Test
    public void genuineNpcLootBeforeALaterGraveKeepsItsBookedIncome()
    {
        Engine engine = ReviewFixesTest.engine();
        var session = engine.session();
        var loot = loot(T0 + 1_000L, WHIP, "Abyssal whip", VALUE);
        session.addTransaction(loot, 2_000, false);
        session.addTransaction(grave(T0 + 5_000L, WHIP, "Abyssal whip", VALUE), 2_000, false);
        assertEquals(VALUE, session.metrics(T0 + MINUTE).net);

        engine.recheck();

        assertEquals("a later grave cannot erase earlier NPC loot", VALUE,
                session.metrics(T0 + MINUTE).net);
        assertEquals(Correction.AUTO, loot.correction());
        assertEquals("no automatic correction was invented", 0, session.correctionHistory.size());
    }

    @Test
    public void genuineNpcLootAfterAnEarlierGraveKeepsItsBookedIncome()
    {
        Engine engine = ReviewFixesTest.engine();
        var session = engine.session();
        session.addTransaction(grave(T0 + 1_000L, WHIP, "Abyssal whip", VALUE), 2_000, false);
        var loot = loot(T0 + 30L * MINUTE, WHIP, "Abyssal whip", VALUE);
        session.addTransaction(loot, 2_000, false);
        assertEquals(VALUE, session.metrics(T0 + 31L * MINUTE).net);

        engine.recheck();

        assertEquals("a new confirmed NPC drop is not a grave recovery", VALUE,
                session.metrics(T0 + 31L * MINUTE).net);
        assertEquals(Correction.AUTO, loot.correction());
    }

    @Test
    public void aFreshPvpDeathKeepsItsOffsetAfterRecheckAndReload()
    {
        Engine engine = ReviewFixesTest.engine();
        var session = engine.session();
        var loot = loot(T0 + 1_000L, WHIP, "Abyssal whip", VALUE);
        session.addTransaction(loot, 2_000, false);
        session.addTransaction(Tx.of(T0 + 5_000L, TransactionType.PK_DEATH_LOSS,
                Context.PK_DEATH, "Death: PvP", true,
                List.of(new Flow(WHIP, "Abyssal whip", -1, VALUE, -VALUE))), 2_000, false);
        assertEquals("loot and its later PK loss offset each other", 0,
                session.metrics(T0 + MINUTE).net);

        engine.recheck();

        assertEquals(0, session.metrics(T0 + MINUTE).net);
        assertEquals(Correction.AUTO, loot.correction());

        engine.restoreProfile("grave-reload", engine.savedState(), T0 + 2L * MINUTE);
        assertEquals("reload keeps the same booked offset", 0, engine.metrics(T0 + 3L * MINUTE).net);
        engine.recheck();
        assertEquals(0, engine.metrics(T0 + 4L * MINUTE).net);
        assertEquals(Correction.AUTO, engine.session().findTransaction(loot.id()).correction());
    }

    @Test
    public void genuineRaidPkAndChestProceedsStayCounted()
    {
        Engine engine = ReviewFixesTest.engine();
        var session = engine.session();
        var raid = loot(T0 + 1_000L, TWISTED_BOW, "Twisted bow", 1_000_000L);
        var pk = pkLoot(T0 + 2_000L, AVA, "Ava's accumulator", 12L);
        var chest = loot(T0 + 3_000L, SEED_POD, "Royal seed pod", 600L);
        session.addTransaction(raid, 2_000, false);
        session.addTransaction(pk, 2_000, false);
        session.addTransaction(chest, 2_000, false);
        session.addTransaction(Tx.of(T0 + 4_000L, TransactionType.TRANSFER, Context.GENERIC,
                GameData.msg("deathItems"), false,
                List.of(new Flow(TWISTED_BOW, "Twisted bow", -1, 1_000_000L, -1_000_000L),
                        new Flow(AVA, "Ava's accumulator", -1, 12L, -12L),
                        new Flow(SEED_POD, "Royal seed pod", -1, 600L, -600L))), 2_000, false);

        engine.recheck();

        assertEquals(1_000_612L, session.metrics(T0 + MINUTE).net);
        assertEquals(Correction.AUTO, raid.correction());
        assertEquals(Correction.AUTO, pk.correction());
        assertEquals(Correction.AUTO, chest.correction());
    }

    @Test
    public void anActualNeutralRecoveryStillBooksNoIncome()
    {
        Engine engine = ReviewFixesTest.engine();
        var session = engine.session();
        session.addTransaction(grave(T0 + 1_000L, WHIP, "Abyssal whip", VALUE), 2_000, false);
        session.addTransaction(recovery(T0 + 2_000L, WHIP, "Abyssal whip", VALUE), 2_000, false);
        assertEquals(0, session.metrics(T0 + 3_000L).net);

        engine.recheck();

        assertEquals("the gear return stays ownership-neutral", 0,
                session.metrics(T0 + 3_000L).net);
    }

    @Test
    public void deathFeeAccountingRemainsIntact()
    {
        Engine engine = ReviewFixesTest.engine();
        engine.bookDeathFee(500_000L, null, T0 + 1_000L);
        assertEquals(-500_000L, engine.metrics(T0 + 2_000L).net);

        engine.recheck();

        assertEquals(-500_000L, engine.metrics(T0 + 3_000L).net);
        assertEquals("the observed fee stays one counted row", 1,
                engine.session().transactions().stream()
                        .filter(row -> "Death reclaim".equals(row.activityName()) && row.type() == TransactionType.CONSUMPTION)
                        .count());
    }

    @Test
    public void ambiguousHistoricalGainsWaitForExplicitCorrection()
    {
        Engine engine = ReviewFixesTest.engine();
        var session = engine.session();
        session.addTransaction(grave(T0 + 1_000L, WHIP, "Abyssal whip", VALUE), 2_000, false);
        var ambiguous = gain(T0 + 2_000L, WHIP, "Abyssal whip", VALUE);
        session.addTransaction(ambiguous, 2_000, false);

        engine.recheck();

        assertEquals("item overlap alone cannot prove a recovery", VALUE,
                session.metrics(T0 + MINUTE).net);
        assertEquals(Correction.AUTO, ambiguous.correction());

        assertTrue(session.correctTransaction(ambiguous.id(), Correction.IGNORE, "not income"));
        assertEquals(0, session.metrics(T0 + MINUTE).net);
        engine.recheck();
        assertEquals("an explicit decision is never re-derived", 0, session.metrics(T0 + MINUTE).net);
        assertEquals(Correction.IGNORE, ambiguous.correction());
        assertEquals(1, session.correctionHistory.size());
    }

    @Test
    public void ownerDecisionsAndOriginalPricesSurviveRecheck()
    {
        Engine engine = ReviewFixesTest.engine();
        var session = engine.session();
        var legacyIgnored = gain(T0 + 1_000L, WHIP, "Abyssal whip", VALUE);
        session.addTransaction(legacyIgnored, 2_000, false);
        assertTrue(session.correctTransaction(legacyIgnored.id(), Correction.IGNORE, "old cleanup"));
        var loot = loot(T0 + 2_000L, AVA, "Ava's accumulator", 12L);

        engine.recheck();

        assertEquals("an old IGNORE is never bulk-reversed", Correction.IGNORE, legacyIgnored.correction());
        assertEquals(Correction.AUTO, loot.correction());
        assertEquals("the captured quote is kept, not repriced", 12L, loot.flows().get(0).unitPrice);
        assertEquals(12L, loot.flows().get(0).value);
        assertEquals(0, session.metrics(T0 + MINUTE).net);
    }

    @Test
    public void repeatedRecheckAndReloadRemainStable()
    {
        Engine engine = ReviewFixesTest.engine();
        var session = engine.session();
        var loot = loot(T0 + 1_000L, WHIP, "Abyssal whip", VALUE);
        session.addTransaction(loot, 2_000, false);
        session.addTransaction(grave(T0 + 5_000L, WHIP, "Abyssal whip", VALUE), 2_000, false);

        engine.recheck();
        engine.recheck();
        assertEquals(VALUE, session.metrics(T0 + MINUTE).net);
        assertEquals(0, session.correctionHistory.size());

        engine.restoreProfile("grave-reload", engine.savedState(), T0 + 2L * MINUTE);
        engine.recheck();
        engine.recheck();

        assertEquals(VALUE, engine.metrics(T0 + 3L * MINUTE).net);
        assertEquals(0, engine.session().correctionHistory.size());
        assertNotNull(engine.session().findTransaction(loot.id()));
        assertEquals(Correction.AUTO, engine.session().findTransaction(loot.id()).correction());
    }

    private static Transaction loot(long at, int item, String name, long value)
    {
        var row = Tx.of(at, TransactionType.LOOT, Context.LOOT, name, true,
                List.of(new Flow(item, name, 1, value, value)));
        row.confidence = Confidence.CONFIRMED;
        return row;
    }

    private static Transaction pkLoot(long at, int item, String name, long value)
    {
        var row = Tx.of(at, TransactionType.PK_LOOT, Context.PK_LOOT, name, true,
                List.of(new Flow(item, name, 1, value, value)));
        row.confidence = Confidence.CONFIRMED;
        return row;
    }

    private static Transaction gain(long at, int item, String name, long value)
    {
        return Tx.of(at, TransactionType.GAIN, Context.GENERIC, "Loot", true,
                List.of(new Flow(item, name, 1, value, value)));
    }

    private static Transaction grave(long at, int item, String name, long value)
    {
        return Tx.of(at, TransactionType.TRANSFER, Context.GENERIC, GameData.msg("deathItems"),
                false, List.of(new Flow(item, name, -1, value, -value)));
    }

    private static Transaction recovery(long at, int item, String name, long value)
    {
        return Tx.of(at, TransactionType.TRANSFER, Context.GENERIC,
                GameData.msg("deathReclaimItems"), false,
                List.of(new Flow(item, name, 1, value, value)));
    }
}

package com.gpmanager;

