        reverse.markPkLoot(expected, 50, 1_100L);
        settleSnapshot(reverse, expected, 1_600L);

        Map<Integer, String> forwardIds = claimSuffixes(forward);
        Map<Integer, String> reverseIds = claimSuffixes(reverse);
