import java.util.Map;
import java.util.function.LongSupplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import org.junit.After;
import org.junit.Test;
import static org.junit.Assert.*;

/** Offline plugin lifecycle: only fresh XP after enabling can confirm an ongoing Make-X run. */
public class PluginProductionResumeTest
{
    LongSupplier clock = SafeMath.clock;
    static final long T0 = 1_700_000_000_000L;
    static final int LOG = 1515, BOW = 66;

    @After public void restoreClock() { SafeMath.clock = clock; }

    @Test public void firstFletchingActionAfterQuickToggleCountsWithoutAnotherClick()
    {
        Harness harness = new Harness();
        harness.enable(T0);
        harness.plugin.activity.armProduction("Fletching", T0);
        Transaction before = harness.make(Skill.FLETCHING, T0 + 600L);
        harness.disable(T0 + 2_000L);
        harness.inventory = new ContainerSnapshot(Map.of(LOG, 5L, BOW, 10L)); // Churn while disabled is baseline material.
        harness.enable(T0 + 3_000L);
        Transaction after = harness.make(Skill.FLETCHING, T0 + 3_600L);
        assertEquals(TransactionType.PROCESSING, after.type());
        assertTrue(after.counts());
        assertTrue("already booked history is preserved", harness.plugin.engine.current.transactions().contains(before));
        assertEquals(2, harness.plugin.engine.current.transactions().size());
        assertEquals("only two enabled actions count", 120L, harness.plugin.engine.metrics(T0 + 6_000L).net);
    }

    @Test public void productionCanResumeAfterTheOldRunExpiredOrWithAFreshPlugin()
    {
        for (Skill skill : new Skill[]{Skill.FLETCHING, Skill.CRAFTING, Skill.SMITHING,
                Skill.HERBLORE, Skill.COOKING, Skill.CONSTRUCTION})
                {
            Harness harness = new Harness();
            harness.plugin.activity.armProduction(skill.getName(), T0 - 60_000L);
            harness.enable(T0);
            Transaction row = harness.make(skill, T0 + 600L);
            assertEquals(skill.getName(), TransactionType.PROCESSING, row.type());
            assertTrue(row.counts());
            assertEquals(60L, harness.plugin.engine.metrics(T0 + 3_000L).net);
        }
    }

    @Test public void readinessStartsTheResumeWindowAfterASlowBind()
    {
        Harness harness = new Harness();
        harness.plugin.ready = false;
        harness.enable(T0);
        harness.xp.put(Skill.FLETCHING, 2_000); // Disabled/fenced XP is never the action being booked.
        harness.at(T0 + 60_000L);
        harness.plugin.ready = true;
        harness.plugin.initLoggedIn();
        assertEquals(TransactionType.PROCESSING, harness.make(Skill.FLETCHING, T0 + 60_600L).type());
        assertEquals(60L, harness.plugin.engine.metrics(T0 + 63_000L).net);
    }

    @Test public void enablingOrUnchangedXpCannotConfirmAMixedChange()
    {
        Harness harness = new Harness();
        harness.enable(T0);
        harness.plugin.onStatChanged(new StatChanged(Skill.FLETCHING, 1_000, 1, 1));
        harness.plugin.onStatChanged(new StatChanged(Skill.FLETCHING, 999, 1, 1));
        Transaction row = harness.change(T0 + 600L);
        assertEquals(TransactionType.UNCERTAIN, row.type());
        assertFalse(row.counts());
        assertEquals(0L, harness.plugin.engine.metrics(T0 + 3_000L).net);
    }

    @Test public void combatAndGatherXpCannotConfirmProduction()
    {
        for (Skill skill : new Skill[]{Skill.ATTACK, Skill.MAGIC, Skill.PRAYER, Skill.MINING, Skill.WOODCUTTING})
        {
            Harness harness = new Harness();
            harness.enable(T0);
            Transaction row = harness.make(skill, T0 + 600L);
            assertEquals(skill.getName(), TransactionType.UNCERTAIN, row.type());
            assertFalse(row.counts());
        }
    }

    @Test public void anIdleEnableDoesNotKeepProductionArmedForever()
    {
        Harness harness = new Harness();
        harness.enable(T0);
        assertEquals(TransactionType.UNCERTAIN, harness.make(Skill.FLETCHING, T0 + 31_000L).type());
    }

    @Test public void anOrdinaryProfileResumeCannotRenewTheEnableWindow()
    {
        Harness harness = new Harness();
        harness.enable(T0);
        harness.at(T0 + 60_000L);
        harness.plugin.initLoggedIn();
        assertEquals(TransactionType.UNCERTAIN, harness.make(Skill.FLETCHING, T0 + 60_600L).type());
    }

    @Test public void aManualPauseStaysHeldThroughToggleAndProductionXp()
    {
        Harness harness = new Harness();
        harness.enable(T0);
        harness.plugin.engine.current.pause(T0 + 600L, PauseReason.MANUAL);
        harness.disable(T0 + 1_200L);
        harness.enable(T0 + 1_800L);
        harness.at(T0 + 2_400L);
        harness.xp.put(Skill.FLETCHING, 1_100);
        harness.plugin.onStatChanged(new StatChanged(Skill.FLETCHING, 1_100, 1, 1));
        assertEquals(PauseReason.MANUAL, harness.plugin.engine.current.pauseReason());
        assertNull(harness.plugin.engine.processIfDirty(new ContainerSnapshot(Map.of(BOW, 1L)), T0 + 3_000L, null));
        assertTrue(harness.plugin.engine.current.transactions().isEmpty());
    }

    static class Plugin extends GpManagerPlugin
    {
        boolean ready = true;
        @Override boolean canIngest() { return ready; }
        @Override void installPresentation() { }
        @Override void removePresentation() { }
        @Override void pulse() { }
    }

    class Harness
    {
        Plugin plugin = new Plugin();
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        ContainerSnapshot inventory = new ContainerSnapshot(Map.of(LOG, 1L));
        List<Runnable> callbacks = new ArrayList<>();

        Harness()
        {
            JsonCodec.bind(new Gson());
            for (Skill skill : Skill.values()) xp.put(skill, 1_000);
            plugin.gson = new Gson();
            plugin.config = new GpManagerConfig()
            {
                @Override public int stabilizationTicks() { return 0; }
            };
            plugin.valuation = new Valuation(new GpManagerConfig() {}, id -> null, (id, active) -> 0, id -> false, Valuation.Economy.UNKNOWN);
            plugin.engine = new Engine(deltas ->
            {
                List<Flow> flows = new ArrayList<>();
                deltas.forEach((id, quantity) ->
                {
                    int price = id == LOG ? 100 : 160;
                    flows.add(new Flow(id, id == LOG ? "Yew logs" : "Yew longbow (u)", quantity, price, quantity * price));
                });
                return flows;
            }, new TransactionClassifier(), plugin.config);
            plugin.engine.ensureSession(T0);
            ItemContainer container = ReviewFixesTest.proxy(ItemContainer.class, Map.of("getItems", new Item[0]));
            plugin.client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
            {
                if (method.getName().equals("getSkillExperience"))
                {
                    assertNotEquals("Overall has no individual skill XP slot", Skill.OVERALL, args[0]);
                    return xp.get(args[0]);
                }
                if (method.getName().equals("getGameState")) return GameState.LOGGED_IN;
                if (method.getName().equals("getItemContainer")) return container;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 123L;
                return null;
            });
            plugin.clientThread = new ClientThread()
            {
                @Override public void invokeLater(Runnable task) { callbacks.add(task); }
            };
            plugin.containers = new ContainerSnapshotFactory(plugin.client, null)
            {
                @Override ContainerSnapshot capture(boolean equipment, boolean pouch) { return inventory; }
            };
            // Disk/UI are excluded; the real plugin enable, disable, baseline and XP handlers run.
            plugin.storage = new Persistence(plugin.client, null, null, null, plugin.engine)
            {
                @Override void initAsync(Runnable task) { }
                @Override void shutdown() { fence(); }
            };
            plugin.offers = new OfferSlots();
            plugin.activity = new ActivityDetector(plugin.config, plugin.engine);
            plugin.targets = GpManagerPluginProbe.tracker(plugin.client, plugin.engine, plugin.config);
            plugin.idle = new CharacterIdleTracker(plugin.client, new CharacterIdleModel());
            plugin.charges = new ChargeIntake(plugin.client, null, plugin.config, plugin.engine, null)
            {
                @Override void learnEyeCast(Skill skill, int tick, long now) { }
            };
        }

        void at(long now) { SafeMath.clock = () -> now; }
        void enable(long now)
        {
            at(now);
            plugin.startUp();
            for (Runnable task : new ArrayList<>(callbacks)) task.run();
            callbacks.clear();
        }
        void disable(long now) { at(now); plugin.shutDown(); }
        Transaction make(Skill skill, long now)
        {
            at(now);
            xp.put(skill, xp.get(skill) + 100);
            plugin.onStatChanged(new StatChanged(skill, xp.get(skill), 1, 1));
            return change(now);
        }
        Transaction change(long now)
        {
            Map<Integer, Long> next = new java.util.HashMap<>(inventory.items);
            next.merge(LOG, -1L, Long::sum);
            next.merge(BOW, 1L, Long::sum);
            inventory = new ContainerSnapshot(next);
            plugin.engine.markDirty();
            assertNull(plugin.engine.processIfDirty(inventory, now, null));
            Transaction row = plugin.engine.processIfDirty(inventory, now + 600L, null);
            assertNotNull(row);
            return row;
        }
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import java.util.function.LongSupplier;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/** Pouch controls must resume Idle before a split transfer becomes the ownership baseline. */
public class PouchIdleResumeTest {
    static final int RUNE = ItemID.LAWRUNE, FOOD = ItemID.SHARK;
    LongSupplier clock;

    @Before public void pinClock() { clock = SafeMath.clock; SafeMath.clock = () -> ReviewFixesTest.T0; }
    @After public void restoreClock() { SafeMath.clock = clock; }

    @Test public void custodyControlResumesBeforeEitherTransferHalf() {
        for (boolean itemOp : new boolean[]{false, true}) for (boolean pouchFirst : new boolean[]{false, true}) {
            Harness h = new Harness();
            h.click(InterfaceID.RUNE_POUCH, "Fill", itemOp);
            assertFalse("the control resumes before quantities change", h.engine.session().paused);
            if (pouchFirst) { h.pouch(10); h.inventory(RUNE, 0); }
            else { h.inventory(RUNE, 0); h.pouch(10); }
            h.settle();
            assertEquals(0, h.net());
            assertTrue("a transfer creates no financial row", h.engine.session().transactions().isEmpty());
        }
    }

    @Test public void laterRuneAndFoodSpendingRetainTheirFullCosts() {
        Harness h = new Harness();
        h.click(InterfaceID.RUNE_POUCH, "Fill", false);
        h.pouch(10); h.inventory(RUNE, 0); h.settle();
        h.engine.noteConsume(FOOD, 10, false, ActionKind.EAT, null);
        h.inventory(FOOD, 0); h.pouch(9); h.settle();
        assertEquals("one rune and one food at fixture prices", -200, h.net());
    }

    @Test public void manualPauseRemainsHeld() {
        Harness h = new Harness();
        h.engine.session().resume(h.now); h.engine.togglePause(h.now);
        h.click(InterfaceID.RUNE_POUCH, "Fill", false);
        h.pouch(10); h.inventory(RUNE, 0); h.settle();
        assertTrue(h.engine.session().paused);
        assertEquals(PauseReason.MANUAL, h.engine.session().pauseReason());
        assertEquals(0, h.net());
    }

    @Test public void otherWidgetsAndNonCustodyControlsLeaveIdleHeld() {
        Harness h = new Harness();
        h.click(InterfaceID.RUNE_POUCH, "Examine", false);
        assertTrue(h.engine.isIdlePaused());
        h.click(InterfaceID.BANKMAIN, "Fill", false);
        assertTrue(h.engine.isIdlePaused());
    }

    static final class Harness {
        final Engine engine = ReviewFixesTest.engine();
        final GpManagerPlugin plugin = new GpManagerPluginProbe();
        final Map<Integer, Long> inventory = new HashMap<>();
        int tick, quantity;
        long now = ReviewFixesTest.T0;

        Harness() {
            inventory.put(RUNE, 10L); inventory.put(FOOD, 1L);
            Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
                (proxy, method, args) -> {
                    switch (method.getName()) {
                        case "getGameState": return GameState.LOGGED_IN;
                        case "getTickCount": return tick;
                        case "getVarbitValue": return (int) args[0] == VarbitID.RUNE_POUCH_TYPE_1 ? 1
                            : (int) args[0] == VarbitID.RUNE_POUCH_QUANTITY_1 ? quantity : 0;
                        case "getItemContainer": return (int) args[0] == InventoryID.INV ? container() : null;
                        case "getEnum": return ReviewFixesTest.proxy(EnumComposition.class, Map.of("getIntValue", RUNE));
                        default:
                            if (method.getReturnType() == boolean.class) return false;
                            if (method.getReturnType() == int.class) return 0;
                            if (method.getReturnType() == long.class) return 0L;
                            return null;
                    }
                });
            plugin.engine = engine; plugin.config = ReviewFixesTest.CONFIG; plugin.client = client;
            plugin.containers = new ContainerSnapshotFactory(client, null);
            plugin.targets = GpManagerPluginProbe.tracker(client, engine, plugin.config);
            plugin.charges = new ChargeIntake(client, null, plugin.config, engine, null);
            plugin.activity = new ActivityDetector(plugin.config, engine);
            engine.setBaseline(plugin.containers.capture(false, true)); engine.pauseIdle(now);
        }

        ItemContainer container() {
            Item[] items = inventory.entrySet().stream().map(e -> new Item(e.getKey(), e.getValue().intValue())).toArray(Item[]::new);
            return ReviewFixesTest.proxy(ItemContainer.class, Map.of("getItems", items));
        }

        void click(int group, String option, boolean itemOp) {
            MenuEntry entry = ReviewFixesTest.proxy(MenuEntry.class, Map.of("getOption", option, "getTarget", "Law rune",
                "getType", MenuAction.CC_OP, "isItemOp", itemOp, "getParam1", group << 16 | 7, "getItemId", ItemID.BH_RUNE_POUCH));
            plugin.onMenuOptionClicked(new MenuOptionClicked(entry));
        }

        void inventory(int id, long amount) {
            if (amount > 0) inventory.put(id, amount); else inventory.remove(id);
            plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, container()));
        }

        void pouch(int amount) {
            quantity = amount;
            VarbitChanged event = new VarbitChanged(); event.setVarbitId(VarbitID.RUNE_POUCH_QUANTITY_1);
            plugin.onVarbitChanged(event);
        }

        void settle() {
            for (int i = 0; i < 5; i++) {
                tick++; now += 600; engine.processIfDirty(plugin.containers.capture(false, true), now, null);
            }
        }

        long net() { return engine.metrics(now).net; }
    }
}

package com.gpmanager;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Collections;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static com.gpmanager.GpManagerPluginProbe.set;
import static org.junit.Assert.*;

/** Plugin presentation wiring against the concrete sidebar and its read models. */
public class PresentationWiringTest
{
    @Test
    public void missingToolbarDegradesToNoPresentationWithoutThrowing() throws Exception
    {
        GpManagerPlugin plugin = new GpManagerPlugin();
        set(plugin, "clientToolbar", null);
        set(plugin, "filter",
            new LootPresentationFilterService(
                GroundItemsPrefs.disabled()));
        invoke(plugin, "installPresentation", new Class<?>[0]);
        assertNull("a missing toolbar leaves no panel bound", get(plugin, "sidebar"));
    }

    @Test
    public void ownerScopeHeldClearsAndResumesTheConcreteSidebar() throws Exception
    {
        GpManagerPlugin plugin = new GpManagerPlugin();
        SidebarPanel panel = panel(plugin);
        SwingUtilities.invokeAndWait(() -> SidebarPanelProbe.refresh(panel));
        assertNotNull(SidebarPanelProbe.live(panel));
        invoke(plugin, "ownerScopeChanged", new Class<?>[] {String.class}, "held");
        SwingUtilities.invokeAndWait(() -> SidebarPanelProbe.refresh(panel));
        assertNull("held presentation cannot render the previous owner", SidebarPanelProbe.live(panel));
        invoke(plugin, "ownerScopeChanged", new Class<?>[] {String.class}, "switching");
        assertNull(SidebarPanelProbe.live(panel));
        invoke(plugin, "ownerScopeChanged", new Class<?>[] {String.class}, "12345");
        SwingUtilities.invokeAndWait(() ->
            assertNotNull("ready presentation resumes its facts", SidebarPanelProbe.live(panel)));
    }

    @Test
    public void presentationSignalsRefreshWithoutBookingMoney() throws Exception
    {
        GpManagerPlugin plugin = new GpManagerPlugin();
        SidebarPanel panel = panel(plugin);
        Engine engine = (Engine) get(plugin, "engine");
        engine.ensureSession(1L);
        Session session = engine.session();
        long revision = engine.revision();
        invoke(plugin, "pulse", new Class<?>[0]);
        invoke(plugin, "transactionBooked", new Class<?>[] {Transaction.class, long.class},
            Tx.of(1L, null, TransactionType.GAIN, Context.GENERIC, "", "Test", true,
                Collections.emptyList()), 1L);
        invoke(plugin, "lootObserved", new Class<?>[] {boolean.class, String.class,
            java.util.Collection.class, int.class, long.class}, false, "Test", Collections.emptyList(), 1, 1L);
        invoke(plugin, "refreshPresentation", new Class<?>[0]);
        SwingUtilities.invokeAndWait(() -> {});
        SwingUtilities.invokeAndWait(() -> {});
        assertNotNull("signals reach the sidebar read model", SidebarPanelProbe.live(panel));
        assertSame(session, engine.session());
        assertTrue(session.transactions().isEmpty());
        assertEquals(revision, engine.revision());
        assertEquals(0L, engine.metrics(1L).net);
    }

    @Test
    public void detachedPresentationAcceptsEverySignal() throws Exception
    {
        GpManagerPlugin plugin = new GpManagerPlugin();
        invoke(plugin, "pulse", new Class<?>[0]);
        invoke(plugin, "refreshPresentation", new Class<?>[0]);
        invoke(plugin, "ownerScopeChanged", new Class<?>[] {String.class}, (Object) null);
        invoke(plugin, "interactionChanged", new Class<?>[] {String.class, boolean.class}, "Goblin", true);
        invoke(plugin, "transactionBooked", new Class<?>[] {Transaction.class, long.class}, null, 1L);
        invoke(plugin, "lootObserved", new Class<?>[] {boolean.class, String.class,
            java.util.Collection.class, int.class, long.class}, true, "Test", null, 1, 1L);
    }

    private static SidebarPanel panel(GpManagerPlugin plugin) throws Exception
    {
        GpManagerConfig config = new GpManagerConfig() {};
        Engine engine = new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        SidebarPanel[] panel = new SidebarPanel[1];
        SwingUtilities.invokeAndWait(() -> panel[0] = new SidebarPanel(engine, config, null, null, null));
        set(plugin, "engine", engine);
        set(plugin, "sidebar", panel[0]);
        return panel[0];
    }

    private static void invoke(Object target, String name, Class<?>[] types, Object... args) throws Exception
    {
        Method method = GpManagerPlugin.class.getDeclaredMethod(name, types);
        method.setAccessible(true);
        method.invoke(target, args);
    }

    private static Object get(Object target, String name) throws Exception
    {
        Field field = GpManagerPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }

}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.http.api.item.ItemPrice;
import org.junit.Test;
import static org.junit.Assert.*;

/** Live varps, ownership transitions and measured charge reconciliation, with explicit ticks. */
public class QuiverSupportTest {
    static final long T0 = 1_800_000_000_000L;
    static final GpManagerConfig CONFIG = new GpManagerConfig() {
        public int stabilizationTicks() { return 0; }
        public boolean keepTransferAuditRows() { return true; }
    };

    @Test public void liveAmmoVarpsWorkForEveryCarriedQuiverWithoutAContainer() throws Exception {
        for (int id : new int[] {ItemID.DIZANAS_QUIVER_UNCHARGED, ItemID.DIZANAS_QUIVER_CHARGED,
            ItemID.DIZANAS_QUIVER_UNCHARGED_TROUVER, ItemID.DIZANAS_QUIVER_CHARGED_TROUVER,
            ItemID.DIZANAS_QUIVER_INFINITE, ItemID.DIZANAS_QUIVER_INFINITE_TROUVER,
            ItemID.SKILLCAPE_MAX_DIZANAS, ItemID.SKILLCAPE_MAX_DIZANAS_TROUVER}) {
            Harness h = new Harness();
            h.worn.put(EquipmentInventorySlot.CAPE.getSlotIdx(), new Item(id, 1));
            h.ammo = 250;
            assertEquals(250L, h.capture().quantity(ItemID.DRAGON_ARROW));
            h.worn.clear(); h.inventory.put(id, 1L);
            assertEquals("unequipping retains ownership", 250L, h.capture().quantity(ItemID.DRAGON_ARROW));
        }
    }

    @Test public void staleVarpsAndDuplicateQuiversNeverAddUnownedOrDuplicateAmmo() throws Exception {
        Harness h = new Harness(); h.ammo = 250;
        assertEquals(0L, h.capture().quantity(ItemID.DRAGON_ARROW));
        h.equipQuiver(); h.inventory.put(ItemID.DIZANAS_QUIVER_INFINITE, 1L);
        assertEquals(250L, h.capture().quantity(ItemID.DRAGON_ARROW));
        assertEquals(0L, h.factory.capture(false, false).quantity(ItemID.DRAGON_ARROW));
        h.ammo = -1;
        assertEquals(0L, h.capture().quantity(ItemID.DRAGON_ARROW));
    }

    @Test public void loadingAndUnequippingAreNeutralAndFiringBooksOnlyTheSpentArrow() throws Exception {
        Harness h = new Harness(); h.equipQuiver(); h.ammo = 10;
        h.inventory.put(ItemID.DRAGON_ARROW, 5L); h.engine.setBaseline(h.capture());
        h.inventory.remove(ItemID.DRAGON_ARROW); h.ammo = 15; h.settle();
        assertEquals(0L, h.net());
        h.worn.clear(); h.inventory.put(ItemID.DIZANAS_QUIVER_CHARGED, 1L); h.settle();
        assertEquals(0L, h.net());
        h.ammo = 14; h.settle();
        assertEquals(-20L, h.net());
        assertEquals(ActionKind.FIRE, h.rows().get(0).action());
    }

    @Test public void quiverVarpEventsMarkTheSnapshotDirty() throws Exception {
        Harness h = new Harness();
        for (int id : new int[] {VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO,
            VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT}) {
            h.engine.dirty = false;
            VarbitChanged event = new VarbitChanged(); event.setVarbitId(-1); event.setVarpId(id);
            h.plugin.onVarbitChanged(event);
            assertTrue(h.engine.dirty);
        }
    }

    @Test public void checksReadChargesAndActualProgressReconcilesWithoutDoubleCounting() throws Exception {
        Harness h = new Harness(); h.equipQuiver();
        h.check(10); h.progress(100); h.progress(101); h.progress(101);
        assertEquals(-20L, h.net());
        h.check(9);
        assertEquals("the Check replaces, rather than duplicates, the observed use", -20L, h.net());
        assertTrue(h.rows().stream().filter(t -> t.net() != 0).allMatch(t ->
            t.flows().stream().allMatch(f -> CostKind.of(t, f) == CostKind.SUPPLIES)));
    }

    @Test public void twoChargeTicksAndLaterCheckAreStillOneMeasuredCost() throws Exception {
        Harness h = new Harness(); h.equipQuiver();
        h.check(10); h.progress(100); h.progress(102); h.progress(102);
        assertEquals(-40L, h.net());
        h.check(8); assertEquals(-40L, h.net());
        h.charges.resetOwner(); h.progress(103);
        assertEquals("another owner starts from its own first observed value", -40L, h.net());
    }

    @Test public void progressNeverGuessesAnAverageOrSpendsOnLoginJumpsAndFreeQuivers() throws Exception {
        Harness h = new Harness(); h.equipQuiver();
        h.progress(100); h.progress(100); h.progress(1100); h.progress(0);
        assertEquals(0L, h.net());
        h.charges.resetTransient(); h.progress(600);
        assertEquals(0L, h.net());
