package com.gpmanager;

import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Codex's overall 1.7.0 review (2026-11-07), kept as regressions: the crystal cleanup needs the
 * tool's own dragon tool, and a Hardcore death's deleted grave (looting-bag stock included) is lost,
 * never reclaimable. Its two bond-cleanup findings retired with that cleanup (2026-11-08).
 */
public class ReleaseReviewFixesTest {
    java.util.function.LongSupplier previous;

    @Before public void clock() {
        previous = SafeMath.clock;
        SafeMath.clock = () -> ProductionRecipeTest.T0;
    }
    @After public void restoreClock() { SafeMath.clock = previous; }

    @Test public void crystalCleanupRequiresTheMatchingDragonTool() {
        var engine = CrystalRevertMigrationTest.engine();
        var row = CrystalRevertMigrationTest.review(CrystalRevertMigrationTest.AXE,
                CrystalRevertMigrationTest.SEED,
                CrystalRevertMigrationTest.flow(385, "Shark", 1, 900));
        engine.session().addTransaction(row, 2000, false);
        engine.recheck();
        assertEquals("a shark is not the returned dragon felling axe",
                Correction.AUTO, row.correction());
    }

    @Test public void hardcoreDeletedGearMustNotNeutralizeLaterReplacementLoot() {
        int whip = HardcoreWorldPricesTest.WHIP;
        var valuation = HardcoreWorldPricesTest.valuation(Valuation.Economy.HARDCORE);
        var fixture = new ProductionRecentTest.Fixture(java.util.Map.of(whip, 1L));
        fixture.engine.valuation = valuation;
        fixture.engine.markPvmDeath(8, java.util.Map.of(whip, 1L), java.util.Map.of(), fixture.engine.events.owner);
        fixture.become(java.util.Map.of());
        assertEquals("the deleted whip was booked as a loss", -72_000L, fixture.live().net);
        var saved = JsonCodec.gson().fromJson(JsonCodec.gson().toJson(fixture.engine.savedState()), SavedState.class);
        fixture.engine.restore(saved, fixture.at + 600);
        // A reload pauses for recovery until login resumes tracking, as the live client does.
        fixture.engine.resume(fixture.at + 600, PauseReason.IDLE, PauseReason.RECOVERY);
        fixture.engine.setBaseline(new ContainerSnapshot(java.util.Map.of()));
        valuation.setEconomy(Valuation.Economy.NORMAL);
        fixture.become(java.util.Map.of(whip, 1L));
        assertEquals("a later pickup after Transfer is new loot, not a return of the destroyed whip",
                2_000_000L - 72_000L, fixture.live().net);
    }

    @Test public void hardcoreDeathMustBookKnownLootingBagContents() {
        int bag = ItemID.LOOTING_BAG, whip = HardcoreWorldPricesTest.WHIP;
        var valuation = HardcoreWorldPricesTest.valuation(Valuation.Economy.HARDCORE);
        valuation.learn(whip, 2_500_000L, 1);
        var fixture = new ProductionRecentTest.Fixture(java.util.Map.of(bag, 1L));
        fixture.engine.valuation = valuation;
        fixture.engine.markPvmDeath(8, java.util.Map.of(bag, 1L), java.util.Map.of(whip, 1L), fixture.engine.events.owner);
        fixture.become(java.util.Map.of());
        assertEquals("the known contents were deleted with the bag", -2_500_000L, fixture.live().net);
    }

    @Test public void crystalCleanupUndoSurvivesJsonReloadWithoutAnotherShardRow() {
        var engine = CrystalRevertMigrationTest.engine();
        var row = CrystalRevertMigrationTest.review(CrystalRevertMigrationTest.AXE,
                CrystalRevertMigrationTest.SEED, CrystalRevertMigrationTest.DRAGON);
        engine.session().addTransaction(row, 2000, false);
        engine.recheck();
        assertTrue(engine.undoCorrection());
        var saved = JsonCodec.gson().fromJson(JsonCodec.gson().toJson(engine.savedState()), SavedState.class);
        var restored = CrystalRevertMigrationTest.engine();
        restored.restore(saved, ProductionRecipeTest.T0 + 2000);
        restored.recheck();
        assertEquals(Correction.AUTO, restored.session().findTransaction(row.id()).correction());
        assertEquals(1L, restored.session().transactions().stream()
                .filter(t -> t.flows().stream().anyMatch(f -> f.item == ItemID.PRIF_CRYSTAL_SHARD)).count());
    }
}

package com.gpmanager;

import com.google.gson.*;
import java.nio.file.*;
import java.time.Duration;
import java.util.Collections;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.*;

/** Real coordinator reset safety: copies precede destruction, and stale exports cannot qualify. */
public class ResetSafetyCopyTest
{
    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    static final long NOW = 1_700_000_000_000L;
    static final TrackingIdentity PROFILE = new TrackingIdentity("rsprofile.safety", -1L);

    /** A saved profile with one open and one closed session, on a real repository and writer. */
    static class Fixture implements AutoCloseable
    {
        SessionRepository repository;
        OrderedPersistenceWriter writer;
        Persistence persistence;

        Fixture(Path directory)
        {
            this(directory, false);
        }

        /** @param editDuringCopy rename the open session while each backup copy is written */
        Fixture(Path directory, boolean editDuringCopy)
        {
            JsonCodec.bind(new Gson());
            repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), true);
            writer = new OrderedPersistenceWriter(repository);
            Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
                new GpManagerConfig() {});
            persistence = new Persistence(null, null, repository, writer, engine)
            {
                @Override
                TrackingIdentity resolveCurrentIdentity()
                {
                    return PROFILE;
                }

                @Override
                Filepath writeBackup(long now) throws java.io.IOException
                {
                    Filepath backup = super.writeBackup(now);
                    if (editDuringCopy) engine.session().rename("Edited during copy");
                    return backup;
                }
            };
            assertTrue(persistence.switchIdentity(PROFILE, true));
            engine.ensureSession(NOW);
            engine.session().rename("Before reset");
            engine.session().addTransaction(receipt(NOW), 2_000, false);
            Session closed = new Session("Closed history", NOW - 60_000L, SessionMode.GENERAL);
            closed.addTransaction(receipt(NOW - 30_000L), 2_000, false);
            closed.close(NOW - 1_000L);
            engine.history.add(closed);
            assertTrue(persistence.saveNow());
        }

        @Override
        public void close()
        {
            writer.shutdown(Duration.ofSeconds(5));
        }
    }

    static Transaction receipt(long at)
    {
        return new Transaction(at, TransactionType.LOOT, Context.LOOT, "", "Guard", true,
            Collections.singletonList(new Flow(560, "Death rune", 46L, 187, 8_602L)),
            Confidence.CONFIRMED, "test", null);
    }

    static SavedState read(Filepath backup) throws Exception
    {
        return SessionRepository.parseBackup(JsonCodec.gson(), backup);
    }

    @Test
    public void directResetKeepsTheCompletePriorStateAndExistingSuccessNotice() throws Exception
    {
        try (Fixture fixture = new Fixture(temporary.newFolder().toPath()))
        {
            Persistence persistence = fixture.persistence;
            JsonObject before = Persistence.backupContent(persistence.engine.exportState());
            Persistence.ResetOutcome reset = persistence.factoryReset(NOW + 1_000L, true);
            assertTrue(reset.getDetail(), reset.isApplied());
            assertEquals(1, persistence.backups().size());
            SavedState copy = read(persistence.backups().get(0));
            assertTrue(copy.isSupportedSchema());
            assertEquals(before, Persistence.backupContent(copy));
            assertEquals(1, copy.generalSession.transactions().size());
            assertEquals(1, copy.history.size());
            assertNull(persistence.engine.session());
        }
    }

    /** Owner 1.5.2: Delete Profile without a backup deletes and writes no safety copy. */
    @Test
    public void deleteWithoutBackupWritesNoCopy() throws Exception
    {
        try (Fixture fixture = new Fixture(temporary.newFolder().toPath()))
        {
            Persistence persistence = fixture.persistence;
            Persistence.ResetOutcome reset = persistence.factoryReset(NOW + 1_000L, false);
            assertTrue(reset.getDetail(), reset.isApplied());
            assertEquals(0, persistence.backups().size());
            assertNull(persistence.engine.session());
        }
    }

    @Test
    public void anEarlierBackupIsKeptAndResetWritesItsOwnCopy() throws Exception
    {
        try (Fixture fixture = new Fixture(temporary.newFolder().toPath()))
        {
            Persistence persistence = fixture.persistence;
            Filepath backup = persistence.writeBackup(NOW);
            assertTrue(persistence.saveNow());
            assertTrue(persistence.factoryReset(NOW + 1_000L, true).isApplied());
            assertEquals(2, persistence.backups().size());
            assertTrue(persistence.backups().contains(backup));
            assertEquals("Before reset", read(persistence.backups().get(0)).generalSession.name());
        }
    }

    @Test
    public void changedFactsRequireANewCopy() throws Exception
    {
        try (Fixture fixture = new Fixture(temporary.newFolder().toPath()))
        {
            Persistence persistence = fixture.persistence;
            Filepath backup = persistence.writeBackup(NOW);
            persistence.engine.session().rename("Changed before reset");
            persistence.engine.session().addTransaction(receipt(NOW + 500L), 2_000, false);
            assertTrue(persistence.factoryReset(NOW + 1_000L, true).isApplied());
            assertEquals(2, persistence.backups().size());
            assertEquals("Before reset", read(backup).generalSession.name());
            SavedState newest = read(persistence.backups().get(0));
            assertEquals("Changed before reset", newest.generalSession.name());
            assertEquals(2, newest.generalSession.transactions().size());
        }
    }

    @Test
    public void backupFailureRefusesResetBeforeMutatingTheOwner() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        try (Fixture fixture = new Fixture(directory))
        {
            Persistence persistence = fixture.persistence;
            Files.writeString(directory.resolve("backups"), "blocked directory");
            JsonObject before = Persistence.backupContent(persistence.engine.exportState());
            Persistence.ResetOutcome reset = persistence.factoryReset(NOW, true);
            assertFalse(reset.isApplied());
            assertTrue(reset.getDetail(), reset.getDetail().startsWith(GameData.msg("preRestore")));
            assertEquals(before, Persistence.backupContent(persistence.engine.exportState()));
            assertEquals("Before reset", fixture.repository.load().generalSession.name());
            assertFalse(persistence.maintenance);
        }
    }

    @Test
    public void corruptIncompatibleAndWrongOwnerExportsArePreservedButNotReused() throws Exception
    {
        for (int damage = 0; damage < 3; damage++)
        {
            try (Fixture fixture = new Fixture(temporary.newFolder().toPath()))
            {
                Persistence persistence = fixture.persistence;
                Filepath backup = persistence.writeBackup(NOW);
                JsonObject json = new JsonParser().parse(SessionRepository.readText(backup)).getAsJsonObject();
                if (damage == 1) json.addProperty("schemaVersion", 999);
                if (damage == 2) json.addProperty("ownerKey", "another.owner");
                String damaged = damage == 0 ? "{broken" : json.toString();
                backup.write(damaged, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
                assertTrue(persistence.factoryReset(NOW + 1_000L, true).isApplied());
                assertEquals(2, persistence.backups().size());
                assertEquals("existing evidence is preserved", damaged, SessionRepository.readText(backup));
                SavedState fresh = read(persistence.backups().get(0));
                assertTrue(fresh.isSupportedSchema());
                assertEquals(PROFILE.rsProfileKey, fresh.ownerKey);
                assertEquals("Before reset", fresh.generalSession.name());
            }
        }
    }

    @Test
    public void aSidebarEditDuringCopyRefusesResetAndKeepsTheNewerData() throws Exception
    {
        try (Fixture fixture = new Fixture(temporary.newFolder().toPath(), true))
        {
            Persistence persistence = fixture.persistence;
            Persistence.ResetOutcome reset = persistence.factoryReset(NOW, true);
            assertFalse(reset.isApplied());
            assertTrue(reset.getDetail(), reset.getDetail().contains("data changed"));
            assertEquals("Edited during copy", persistence.engine.session().name());
            assertEquals("Before reset", read(persistence.backups().get(0)).generalSession.name());
            assertEquals(1, persistence.engine.session().transactions().size());
            assertFalse(persistence.maintenance);
        }
    }
}

