/**
 * The tool and staff charge rows (owner 2026-10-14): crystal tools, infernal tools, echo boots
 * and the slayer's staff (e) are load-costed — their components book a counted Supplies spend at
 * load and a Check books nothing; the bone staff's chaos runes load neutrally, each cast spends
 * one and its Check measures; the upgrades keep the base's worth.
 */
public class ToolChargeRowsTest
{
    private static final long T0 = 1_000_000L;
    private static final int SHARD = ItemID.PRIF_CRYSTAL_SHARD;
    private static final int STONE = ItemID.SMOULDERING_STONE;
    private static final int ECHO = ItemID.ECHO_CRYSTAL;
    private static final int ENCHANT = ItemID.SLAYER_ENCHANTMENT;
    private static final int CHAOS = ItemID.CHAOSRUNE;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }

        @Override
        public boolean keepTransferAuditRows()
        {
            return true;
        }
    };

    @Test
    public void crystalToolShardsBookAtLoadAndTheirCheckBooksNothing()
    {
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(SHARD, 500L))));
        engine.markChargeLoad(ChargeCheck.ChargedItem.CRYSTAL_AXE, SHARD, "Crystal shard",
            "149:0:23673:CRYSTAL_AXE", ChargeIntake.LOAD_TICKS);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(SHARD, 380L))),
                T0 + tick * 600L, null);
        }
        assertEquals("a dismantle loses the shard charges, so the load books", true,
            engine.session().transactions().stream().anyMatch(Transaction::counts));
        assertTrue("and it is a cost", engine.metrics(T0 + 10_000L).net < 0L);

        ChargeIntake intake = new ChargeIntake(client(null, null), null, CONFIG, engine, null);
        assertTrue("the tool's Check is a read, consumed",
            intake.observeCheck("Your crystal axe has 9,000 charges remaining.", T0 + 12_000L));
        assertTrue("and books nothing",
            engine.session().transactions().stream().noneMatch(
                row -> row.counts() && row.note() != null
                    && row.note().toLowerCase().contains("check")));
    }

    @Test
    public void infernalToolLoadsBookForTheStoneAndForTheDragonTool()
    {
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(STONE, 2L, ItemID.DRAGON_AXE, 1L))));
        engine.markChargeLoad(ChargeCheck.ChargedItem.INFERNAL_AXE, STONE, "Smouldering stone",
            "149:0:13241:INFERNAL_AXE", ChargeIntake.LOAD_TICKS);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(STONE, 1L, ItemID.DRAGON_AXE, 1L))),
                T0 + tick * 600L, null);
        }
        assertTrue("the stone books as a cost", engine.metrics(T0 + 10_000L).net < 0L);

        engine.markChargeLoad(ChargeCheck.ChargedItem.INFERNAL_AXE, ItemID.DRAGON_AXE, "Dragon axe",
            "149:0:13241:INFERNAL_AXE", ChargeIntake.LOAD_TICKS);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(STONE, 1L, ItemID.DRAGON_AXE, 0L))),
                T0 + 6_000L + tick * 600L, null);
        }
        assertTrue("the dragon-tool recharge books too",
            engine.session().transactions().stream()
                .filter(Transaction::counts).count() >= 2);
    }

    @Test
    public void echoCrystalsAndTheSlayerEnchantmentBookAtLoad()
    {
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(ECHO, 1L, ENCHANT, 1L))));
        engine.markChargeLoad(ChargeCheck.ChargedItem.ECHO_BOOTS, ECHO, "Echo crystal",
            "149:0:28945:ECHO_BOOTS", ChargeIntake.LOAD_TICKS);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(ECHO, 0L, ENCHANT, 1L))),
                T0 + tick * 600L, null);
        }
        assertTrue("the echo crystal books as a cost", engine.metrics(T0 + 10_000L).net < 0L);

        engine.markChargeLoad(ChargeCheck.ChargedItem.SLAYER_STAFF_E, ENCHANT, "Slayer's enchantment",
            "149:0:21255:SLAYER_STAFF_E", ChargeIntake.LOAD_TICKS);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(ECHO, 0L, ENCHANT, 0L))),
                T0 + 6_000L + tick * 600L, null);
        }
        assertTrue("the enchantment books too",
            engine.session().transactions().stream()
                .filter(Transaction::counts).count() >= 2);
    }

    @Test
    public void boneStaffChaosLoadsAreNeutralAndACastSpendsOne()
    {
        // The load: chaos runes move into charges, so nothing is a cost (Uncharge refunds them).
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(CHAOS, 500L))));
        engine.markChargeLoad(ChargeCheck.ChargedItem.BONE_STAFF, CHAOS, "Chaos rune",
            "149:0:28796:BONE_STAFF", ChargeIntake.LOAD_TICKS);
        engine.markDirty();
        Transaction load = null;
        for (int tick = 1; tick <= 5; tick++)
        {
            Transaction row = engine.processIfDirty(
                new ContainerSnapshot(new HashMap<>(Map.of(CHAOS, 400L))), T0 + tick * 600L, null);
            if (row != null) load = row;
        }
        assertNotNull(load);
        assertEquals("a refundable load is a neutral transfer", TransactionType.TRANSFER, load.type());
        assertEquals(0L, engine.metrics(T0 + 10_000L).net);

        // A cast books one chaos rune from the pinned cast animations.
        Valuation valuation = ModelProbe.valuation(CONFIG, ToolChargeRowsTest::compositionOf,
            id -> id == CHAOS ? 100 : 0);
        Engine castEngine = new Engine(ToolChargeRowsTest::flows, new TransactionClassifier(), CONFIG);
        castEngine.startCustom("Scurrius", T0);
        castEngine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        ChargeIntake intake = new ChargeIntake(
            client(container(EquipmentInventorySlot.WEAPON.getSlotIdx(), ItemID.RAT_BONE_STAFF), null),
            lookup(), CONFIG, castEngine, valuation);
        intake.onAnimation(1162, T0);
        List<Transaction> rows = castEngine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertEquals(1L, rows.get(0).quantity(CHAOS, false));
        assertTrue(rows.get(0).counts());
    }

    @Test
    public void boneStaffCheckMeasuresTheCasts()
    {
        Engine engine = new Engine(ToolChargeRowsTest::flows, new TransactionClassifier(), CONFIG);
        String identity = ChargeIntake.weaponIdentity(
            InterfaceID.Inventory.ITEMS, 5, ItemID.RAT_BONE_STAFF, ChargeCheck.ChargedItem.BONE_STAFF);
        ChargeCheck first = ChargeCheck.parse("Your bone staff has 900 charges.");
        assertNotNull("the Check shape parses", first);
        assertEquals(ChargeCheck.ChargedItem.BONE_STAFF, first.variant);
        ChargeOutcomeTest.none(engine.observeCheck(first, identity, T0));
        ChargeDelta delta = engine.observeCheck(
            ChargeCheck.parse("Your bone staff has 850 charges."), identity, T0 + 1_000L);
        assertNotNull(delta);
        assertEquals(-50L, delta.componentDeltas.stream()
            .filter(component -> component.getItemId() == CHAOS)
            .mapToLong(ChargeDelta.ComponentDelta::getQuantityDelta).sum());
    }

    @Test
    public void theToolUpgradesSwapNeutral()
    {
        assertSwapNeutral(ItemID.DRAGON_AXE, ItemID.INFERNAL_AXE);
        assertSwapNeutral(ItemID.DRAGON_PICKAXE, ItemID.INFERNAL_PICKAXE);
        assertSwapNeutral(ItemID.DRAGON_HARPOON, ItemID.INFERNAL_HARPOON);
        assertSwapNeutral(ItemID.GUARDIAN_BOOTS, ItemID.ECHO_BOOTS);
        assertSwapNeutral(ItemID.SLAYER_STAFF, ItemID.SLAYER_STAFF_ENCHANTED);
        // A crystal tool's revert is the dismantle rule (only its shards cost), so it is not a
        // proxy pair.
        List<Flow> crystal = new ArrayList<>();
        crystal.add(new Flow(ItemID.CRYSTAL_HARPOON, "Crystal harpoon", -1L, 100, -100L));
        crystal.add(new Flow(ItemID.DRAGON_HARPOON, "Dragon harpoon", 1L, 100, 100L));
        assertFalse("the crystal tools keep their dismantle rule",
            FlowFilters.withoutSwaps(crystal).isEmpty());
    }

    private static void assertSwapNeutral(int base, int upgraded)
    {
        List<Flow> flows = new ArrayList<>();
        flows.add(new Flow(base, "Item " + base, -1L, 100, -100L));
        flows.add(new Flow(upgraded, "Item " + upgraded, 1L, 100, 100L));
        assertTrue("swap " + base + " -> " + upgraded, FlowFilters.withoutSwaps(flows).isEmpty());
    }

    private static List<Flow> flows(Map<Integer, Long> deltas)
    {
        List<Flow> flows = new ArrayList<>();
        for (Map.Entry<Integer, Long> entry : deltas.entrySet())
        {
            flows.add(new Flow(entry.getKey(), "Item " + entry.getKey(), entry.getValue(), 100,
                entry.getValue() * 100));
        }
        return flows;
    }

    private static ItemComposition compositionOf(int id)
    {
        String name = id == CHAOS ? "Chaos rune" : "Item " + id;
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) ->
            {
                if ("getName".equals(method.getName())) return name;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
    }

    private static ItemLookup lookup()
    {
        return new ItemLookup(null)
        {
            @Override
            ItemComposition composition(int id)
            {
                return compositionOf(id);
            }
        };
    }

    private static Client client(ItemContainer worn, ItemContainer inventory)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (proxy, method, args) ->
            {
                if ("getItemContainer".equals(method.getName()))
                {
                    int containerId = (int) args[0];
                    if (containerId == InventoryID.WORN) return worn;
                    if (containerId == InventoryID.INV) return inventory;
                    return null;
                }
                if ("getTickCount".equals(method.getName())) return 10;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
    }

    private static ItemContainer container(int slot, int itemId)
    {
        return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[] {ItemContainer.class}, (proxy, method, args) ->
            {
                if ("getItem".equals(method.getName()))
                    return (int) args[0] == slot ? new Item(itemId, 1) : null;
                if ("size".equals(method.getName())) return 28;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static com.gpmanager.GpManagerPluginProbe.set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner live 2026-10-13: the Vyre well is refundable storage for scythe charges. Filling it
 * (announced by its own message box, "You fill the well with N charges.") moves the player's
 * vials and blood runes neutrally; the scythe's charge estimates book each use, never the load.
 */
public class VyreWellFillTest
{
    private static final long T0 = 1_000_000L;
    private static final int VIAL = 22446;
    private static final int RUNE = 565;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private static Engine engine()
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) ->
                flows.add(new Flow(id, "Item " + id, quantity, 100, quantity * 100)));
            return flows;
        }, new TransactionClassifier(), CONFIG);
        engine.ensureSession(T0);
        return engine;
    }

    private static void fill(Engine engine) throws Exception
    {
        GpManagerPlugin plugin = new GpManagerPluginProbe();
        set(plugin, "config", CONFIG);
        set(plugin, "engine", engine);
        ChatMessage message = new ChatMessage();
        message.setType(ChatMessageType.MESBOX);
        message.setMessage("You fill the well with 10 charges.");
        plugin.onChatMessage(message);
    }

    private static Transaction deposit(Engine engine)
    {
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(VIAL, 10L, RUNE, 2_000L))));
        engine.markDirty();
        Transaction row = null;
        for (long tick = 1; row == null && tick <= 5; tick++)
            row = engine.processIfDirty(new ContainerSnapshot(new HashMap<>()), T0 + tick * 600L, null);
        return row;
    }

    @Test
    public void theFillLineKeepsTheDepositNeutral() throws Exception
    {
        Engine engine = engine();
        fill(engine);
        Transaction row = deposit(engine);
        assertNotNull(row);
        assertEquals(0L, engine.metrics(T0 + 10_000L).net);
        assertTrue("nothing counted for a refundable deposit",
            engine.session().transactions().stream().noneMatch(Transaction::counts));
    }

    @Test
    public void withoutTheLineTheDepositBooks() throws Exception
    {
        Engine engine = engine();
        Transaction row = deposit(engine);
        assertNotNull(row);
        assertEquals(-(10L * 100L + 2_000L * 100L), engine.metrics(T0 + 10_000L).net);
    }

    @Test
    public void playerCopiesOfTheWellLineCannotOpenANeutralWindow() throws Exception
    {
        for (ChatMessageType type : new ChatMessageType[] {
            ChatMessageType.PUBLICCHAT, ChatMessageType.CLAN_CHAT, ChatMessageType.PRIVATECHAT})
        {
            Engine engine = engine();
            GpManagerPlugin plugin = new GpManagerPluginProbe();
            set(plugin, "config", CONFIG);
            set(plugin, "engine", engine);
            ChatMessage message = new ChatMessage();
            message.setType(type);
            message.setMessage("You fill the well with 10 charges.");
            plugin.onChatMessage(message);
            assertTrue(engine.session().transactions().isEmpty());
            assertNotNull(deposit(engine));
            assertEquals(type.toString(), -201_000L, engine.metrics(T0 + 10_000L).net);
        }
    }

    @Test
    public void theEmptyOptionKeepsTheReturnNeutral() throws Exception
    {
        Engine engine = engine();
        empty(engine);
        Transaction row = refund(engine);
        assertNotNull(row);
        assertEquals(0L, engine.metrics(T0 + 10_000L).net);
        assertTrue("storage coming back is never income",
            engine.session().transactions().stream().noneMatch(Transaction::counts));
    }

    @Test
    public void withoutTheEmptyClickTheReturnBooks() throws Exception
    {
        Engine engine = engine();
        Transaction row = refund(engine);
        assertNotNull(row);
        assertEquals(10L * 100L + 2_000L * 100L, engine.metrics(T0 + 10_000L).net);
    }

    private static void empty(Engine engine) throws Exception
    {
        GpManagerPlugin plugin = new GpManagerPluginProbe();
        set(plugin, "config", CONFIG);
        set(plugin, "engine", engine);
        set(plugin, "targets", GpManagerPluginProbe.tracker(null, engine, CONFIG));
        set(plugin, "charges", new ChargeIntake(null, null, CONFIG, engine, null));
        plugin.onMenuOptionClicked(wellClick("Empty"));
    }

    private static Transaction refund(Engine engine)
    {
        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        engine.markDirty();
        Transaction row = null;
        for (long tick = 1; row == null && tick <= 5; tick++)
            row = engine.processIfDirty(
                new ContainerSnapshot(new HashMap<>(Map.of(VIAL, 10L, RUNE, 2_000L))), T0 + tick * 600L, null);
        return row;
    }

    private static MenuOptionClicked wellClick(String option)
    {
        MenuEntry entry = (MenuEntry) java.lang.reflect.Proxy.newProxyInstance(
            MenuEntry.class.getClassLoader(), new Class<?>[] {MenuEntry.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption":
                        return option;
                    case "getTarget":
                        return "Vyre well";
                    case "getType":
                        return MenuAction.GAME_OBJECT_FOURTH_OPTION;
                    default:
                        Class<?> type = method.getReturnType();
                        if (type == boolean.class) return false;
                        if (type == int.class) return 0;
                        if (type == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }

}

package com.gpmanager;

import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static com.gpmanager.ReviewFixesTest.T0;
import static com.gpmanager.ReviewFixesTest.engine;
import static com.gpmanager.ReviewFixesTest.plugin;
import static com.gpmanager.ReviewFixesTest.proxy;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The 1.5.0 guards: separate-economy worlds pause tracking, and windows hold the activity label. */
public class WorldPauseAndWindowHoldTest
{
    @Test
    public void aSeparateEconomyWorldPausesAndLeavingResumes()
    {
        Engine engine = engine();
        engine.pauseForWorld(T0 + 1_000L);
        assertTrue("a separate-economy world pauses the session", engine.session().paused);
        assertEquals(PauseReason.WORLD, engine.session().pauseReason());
        assertFalse("nothing resumes while still there",
                engine.resume(T0 + 1_500L, PauseReason.WORLD, PauseReason.IDLE));
        engine.separate = false;
        assertTrue(engine.resume(T0 + 2_000L, PauseReason.WORLD));
        assertFalse("leaving resumes like a relog", engine.session().paused);
    }

    @Test
    public void anIdlePauseCarriedOntoTheWorldStaysPaused()
    {
        Engine engine = engine();
        engine.session().pause(T0 + 1_000L, PauseReason.IDLE);
        engine.pauseForWorld(T0 + 2_000L);
        assertFalse("gameplay there never lifts the idle pause",
                engine.resume(T0 + 3_000L, PauseReason.LIFECYCLE, PauseReason.IDLE, PauseReason.RECOVERY));
        assertTrue(engine.session().paused);
    }

    @Test
    public void aWorldPauseNeverTouchesAManualOne()
    {
        Engine engine = engine();
        engine.session().pause(T0 + 1_000L, PauseReason.MANUAL);
        engine.pauseForWorld(T0 + 2_000L);
        assertEquals("the manual pause stands", PauseReason.MANUAL, engine.session().pauseReason());
        assertFalse("a world resume cannot lift a manual pause", engine.resume(T0 + 3_000L, PauseReason.WORLD));
    }

    @Test
    public void theTickPausesOnLeaguesBeforeAnythingIsRead()
    {
        Engine engine = engine();
        ReviewFixesTest.Plugin p = plugin(engine, new int[] {11});
        p.client = clientOn(WorldType.SEASONAL);
        assertTrue("a Leagues world is a separate economy", p.onUnsupportedWorld());
        // The fixture wires no valuation, pvp or activity: reaching them would throw.
        p.onGameTick(null);
        assertTrue(engine.separate);
        assertEquals(PauseReason.WORLD, engine.session().pauseReason());
        p.client = clientOn(WorldType.MEMBERS);
        assertFalse("a members world tracks", p.onUnsupportedWorld());
    }

    @Test
    public void hardcoreWorldsTrackWhileDeadmanStillPauses()
    {
        // Owner 2026-11-07: a Hardcore Worlds character never plays main worlds, so it tracks there
        // with its own economy's prices; Deadman keeps the world pause.
        Engine engine = engine();
        ReviewFixesTest.Plugin p = plugin(engine, new int[] {11});
        p.client = clientOn(WorldType.HARDCORE_MAIN);
        assertFalse("a Hardcore world tracks: no world pause", p.onUnsupportedWorld());
        assertFalse(engine.separate);
        p.client = clientOn(WorldType.DEADMAN);
        assertTrue("Deadman is still a separate economy", p.onUnsupportedWorld());
        p.onGameTick(null);
        assertTrue(engine.separate);
        assertEquals(PauseReason.WORLD, engine.session().pauseReason());
    }

    @Test
    public void anExchangeOrTradeWindowHoldsTheActivityLabel()
    {
        ReviewFixesTest.Plugin p = plugin(engine(), new int[] {11});
        p.client = proxy(Client.class, Map.of("getWidget", proxy(Widget.class, new HashMap<>())));
        assertTrue("an open exchange window holds the label", p.windowHoldsActivity());
        p.client = proxy(Client.class, new HashMap<>());
        assertFalse("no window, no hold", p.windowHoldsActivity());
    }

    static Client clientOn(WorldType type)
    {
        Map<String, Object> values = new HashMap<>();
        values.put("getGameState", GameState.LOGGED_IN);
        values.put("getWorldType", EnumSet.of(type));
        return proxy(Client.class, values);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
