            f.swap(ids[0],ids[1],0);f.feeOnly(0);
            f.swap(ids[1],ids[2],0);f.feeOnly(0);
            f.swap(ids[2],ids[0],1500000);f.feeOnly(1500000);
            f.swap(ids[0],ids[1],0);
            f.swap(ids[1],ids[0],757500);f.feeOnly(2257500);
