            if (first) f.change(Map.of(COINS,-1500000L));
            f.swap(MOONS[0][2],MOONS[0][0],0);
            if (!first) f.change(Map.of(COINS,-1500000L));
            f.feeOnly(1500000);
        }
    }

    @Test public void samePieceLootDuringWearSurvivesAndOrdinaryPurchasesAreNotNeutralized() {
        int[] ids = MOONS[0];var f = new Fixture(ids[1]);
        f.engine.markLoot(Map.of(ids[0],1L),30,"Lunar Chest","Lunar Chest");
        f.change(Map.of(ids[1],-1L,ids[0],2L));
        assertEquals(1200000,f.money().income);assertEquals(0,f.money().cost);
        assertFalse(f.engine.session().transactions().stream().anyMatch(ReviewRules::needsReview));
        var bought = new Fixture();bought.engine.events.put(Inbox.DIALOGUE,0,1L,4,null);
        bought.change(Map.of(ids[0],1L,COINS,-1200000L));
        assertTrue(bought.engine.session().transactions().stream().anyMatch(t -> t.counts() && t.flows().stream().anyMatch(x -> x.item == ids[0])));
    }

    @Test public void aTrueDropAndANewSamePieceGainCannotPretendToBeARepair() {
        int[] ids = MOONS[0];var f = new Fixture(ids[1]);
        f.engine.noteDrop(ids[1],8);
        f.swap(ids[1],ids[0],0);
        assertTrue("the new item must remain visible",f.engine.session().transactions().stream()
                .filter(Transaction::counts).flatMap(t -> t.flows().stream()).anyMatch(x -> x.item == ids[0] && x.gain()));
    }

    @Test public void unknownSameNameVariantsAndDifferentPiecesNeverGetPaired() {
        var f = new Fixture(999998);f.swap(999998,999999,0);
        assertFalse(f.engine.session().transactions().stream().anyMatch(t -> t.type() == TransactionType.TRANSFER));
        assertNull(Engine.piece(new Flow(999999,"Dharok's helm 75",1,10,10)));
        var different = new Fixture(MOONS[0][1]);different.swap(MOONS[0][1],MOONS[1][0],1500000);
        assertFalse(different.engine.session().transactions().stream().anyMatch(t -> t.note().equals(GameData.msg("barrowsWear"))));
    }

    @Test public void feeOnlyProjectionAndReloadKeepRecentLedgerAndMoneyAligned() {
        var f = new Fixture(MOONS[0][2]);f.swap(MOONS[0][2],MOONS[0][0],1500000);f.feeOnly(1500000);
        var snapshot = LiveSnapshot.capture(f.engine,f.now+60000,null);
        assertEquals(0,snapshot.income);assertEquals(-1500000,snapshot.net);
        var ledger = LedgerData.capture(f.engine,f.now+60000,LedgerData.Entry.current());
        assertTrue(ledger.income.groups.isEmpty());assertEquals(-1500000,ledger.cost.total);
        assertFalse(snapshot.recent.stream().anyMatch(row -> row.item == MOONS[0][0]));
        var hud = new HudBuilder(HudBuilderTest.config(false,8),(id,q) -> null);
        hud.update(snapshot,flow -> true,f.now);
        for (var row : f.engine.session().transactions()) hud.tray.booked(row,f.now,false,f.now);
        hud.update(snapshot,flow -> true,f.now);
        assertEquals(-1500000,hud.lastNet);
        assertTrue(hud.tray.entries().stream().noneMatch(row -> row.item != COINS));
        var copy = new Fixture();copy.engine.restore(new Gson().fromJson(new Gson().toJson(f.engine.exportState()),SavedState.class),f.now+60000);
        assertEquals(f.money().net,copy.engine.metrics(f.now+60000).net);
        assertEquals(f.engine.session().transactions().size(),copy.engine.session().transactions().size());
    }

    static Object defaultValue(Class<?> type) {
        if (type == boolean.class) return false;
        if (type == int.class) return 0;
        if (type == long.class) return 0L;
        return null;
    }
    static ItemContainer container(Item[] items) {
        return (ItemContainer)Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),new Class<?>[]{ItemContainer.class},
                (p,m,a) -> m.getName().equals("getItems") ? items : defaultValue(m.getReturnType()));
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** A pickup that lands straight in an open bag counts like any pickup (owner 1.2). */
public class BagPickupTest
{
    private static final int BONES = 526;
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }

        @Override
        public boolean keepTransferAuditRows()
        {
            return true;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Item " + id, quantity, 35, quantity * 35)));
        return flows;
    };

    private Engine started(long bones)
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(new ContainerSnapshot(Collections.singletonMap(BONES, bones)));
        return engine;
    }

    @Test
    public void aBaggedPickupIsAGainThoughTheInventoryNeverChanges()
    {
        Engine engine = started(0L);
        engine.bagged(BONES, 3L);
        Transaction pickup = settle(engine, FixtureReads.empty(), 1_600L);
        assertEquals(TransactionType.GAIN, pickup.type());
        assertTrue(pickup.counts());
        assertEquals(105L, engine.metrics(5_000L).net);
    }


    /** Loot is private to you for a minute; a bag pickup inside it is still yours (research 1.2). */
    @Test
    public void yourLootStaysYoursForTheMinuteItIsPrivate()
    {
        Engine engine = started(0L);
        engine.markLoot(Collections.singletonMap(BONES, 3L), 50, "Loot from Guard", "Guard");
        for (int tick = 0; tick < 60; tick++)
        {
            engine.events.tick(engine.events.now + 1);
        }
        assertTrue("past the 30 s attribution window", (FixtureReads.has(engine.events, Inbox.PRIVATE_LOOT, BONES)));
        for (int tick = 60; tick < 100; tick++)
        {
            engine.events.tick(engine.events.now + 1);
        }
        assertFalse("forgotten once the minute is over", (FixtureReads.has(engine.events, Inbox.PRIVATE_LOOT, BONES)));
    }

    @Test
    public void nothingIsBookedBeforeTrackingHasABaseline()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.bagged(BONES, 1L);
        assertNull(engine.baseline);
    }

    /** The catch and cut messages name the item an open barrel or basket takes (owner 1.2). */
    @Test
    public void catchAndCutMessagesNameTheItem()
    {
        String[][] cases = {{"You catch a shark.", null, "shark"}, {"You catch an anglerfish.", null, "anglerfish"},
            {"You catch some shrimps.", null, "shrimps"}, {"You catch 2 karambwanji.", "2", "karambwanji"},
            {"You get some yew logs.", null, "yew logs"}, {"You get some logs.", null, "logs"}};
        for (String[] c : cases)
        {
            java.util.regex.Matcher m = GameData.pattern("bag").matcher(c[0].toLowerCase());
            assertTrue(c[0], m.matches());
            assertEquals(c[0], c[1], m.group(1));
            assertEquals(c[0], c[2], m.group(2));
        }
        assertFalse(GameData.pattern("bag").matcher("you light the logs.").matches());
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        assertNull(engine.processIfDirty(snapshot, firstTick, null));
        assertNull(engine.processIfDirty(snapshot, firstTick + 600L, null));
        Transaction tx = engine.processIfDirty(snapshot, firstTick + 1_200L, null);
        assertNotNull(tx);
        return tx;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;

/**
 * Bank-evidence boundaries around burials: closing the bank must not hide a burial as
 * a transfer, while a deposit that started with the bank open still settles as one.
 * Companion to {@link ConsumptionBurialEngineTest}; these are the independent review
 * probes (September 2026) with their own minimal fixture.
 */
public class BankBoundaryBurialTest
{
    @Test
    public void recentBankEvidenceMustNotHideBurialAfterClosingBank()
    {
        Engine engine = engine();
        engine.ensureSession(1000L);
        ContainerSnapshot bones = new ContainerSnapshot(Collections.singletonMap(526, 1L));
        engine.setBaseline(bones);
        engine.bankOpened(6);
        engine.processIfDirty(bones, 1000L, null);
        engine.bankClosed();
        engine.markDirty();
        engine.processIfDirty(FixtureReads.empty(), 1600L, null);
        engine.processIfDirty(FixtureReads.empty(), 2200L, null);
        Transaction transaction = engine.processIfDirty(FixtureReads.empty(), 2800L, null);
        assertNotNull(transaction);
        assertEquals("burial after bank close must be a cost", TransactionType.CONSUMPTION, transaction.type());
        assertEquals(35L, engine.metrics(2800L).cost);
    }


    @Test
    public void pendingDepositStartedWhileBankOpenStillSettlesAsTransferAfterClose()
    {
        Engine engine = engine();
        engine.ensureSession(1000L);
        ContainerSnapshot bones = new ContainerSnapshot(Collections.singletonMap(526, 1L));
        engine.setBaseline(bones);
        engine.bankOpened(6);
        engine.markDirty();
        engine.markContext(Context.TRANSFER, 6, "Bank container transfer");
        engine.processIfDirty(FixtureReads.empty(), 1600L, null);
        engine.bankClosed();
        engine.processIfDirty(FixtureReads.empty(), 2200L, null);
        Transaction transaction = engine.processIfDirty(FixtureReads.empty(), 2800L, null);
        assertNotNull(transaction);
        assertEquals(TransactionType.TRANSFER, transaction.type());
        assertFalse(transaction.counts());
    }


    @Test
    public void hardBankEvidenceThenIdleTickThenInventoryStillSettlesAsTransfer()
    {
        Engine engine = engine();
        engine.ensureSession(1000L);
        ContainerSnapshot bones = new ContainerSnapshot(Collections.singletonMap(526, 1L));
        engine.setBaseline(bones);
        engine.markContext(Context.TRANSFER, 6, "Bank container transfer");
        engine.processIfDirty(bones, 1000L, null);
        engine.bankClosed();
        engine.processIfDirty(bones, 1600L, null);
        engine.markDirty();
        engine.processIfDirty(FixtureReads.empty(), 2200L, null);
        engine.processIfDirty(FixtureReads.empty(), 2800L, null);
        Transaction transaction = engine.processIfDirty(FixtureReads.empty(), 3400L, null);
        assertNotNull(transaction);
        assertEquals(TransactionType.TRANSFER, transaction.type());
        assertFalse(transaction.counts());
        assertEquals(0L, engine.metrics(3400L).cost);
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 2;
            }

            @Override
            public boolean keepTransferAuditRows()
            {
                return true;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) ->
                flows.add(new Flow(id, "Bones", quantity, 35, quantity * 35L)));
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import org.junit.Before;
import org.junit.After;

import static org.junit.Assert.assertEquals;

/**
 * Owner 1.7.0 bank boundary through the plugin's own callbacks: the BANK container's counts are the
 * only bank movement. Every item is quoted at 10 GP; counted logs carry 10 GP of basis each.
 */
public class BankBoundaryEvidenceTest
{
    private static final int LOGS = 1511, AIR = 556, BOLTS = 9140;
    private static final Map<Integer, Long> PRICES = Map.of(995, 1L, 1515, 94L, 66, 155L, 13441, 1459L,
            BOLTS, 10L);
    private static final Map<Integer, String> NAMES = Map.of(LOGS, "Logs", AIR, "Air rune", 995, "Coins",
            1515, "Yew logs", 66, "Yew longbow (u)", 13441, "Anglerfish", BOLTS, "Iron bolts");
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override public int stabilizationTicks() { return 2; }
        @Override public boolean keepTransferAuditRows() { return true; }
    };

    private long now = 1_000;
    private java.util.function.LongSupplier previousClock;
    @Before public void fixedClock() {
        previousClock = SafeMath.clock;
        SafeMath.clock = () -> now;
    }
    @After public void restoreClock() { SafeMath.clock = previousClock; }
    private boolean bankShown;
    private Engine e;
    private GpManagerPlugin plugin;
    private final List<Transaction> published = new ArrayList<>();

    private void start(long logs, long air) throws Exception
    {
        e = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> {
                long unit = PRICES.getOrDefault(id, 10L);
                flows.add(new Flow(id, NAMES.get(id), quantity, unit,
                        quantity * unit, id == 995 ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
            });
            return flows;
        }, new TransactionClassifier(), CONFIG);
        e.ensureSession(now);
        e.setBaseline(held(logs, air));
        e.session().addTransaction(Tx.of(now, TransactionType.GAIN, Context.GENERIC, "Initial loot", true,
            List.of(new Flow(LOGS, "Logs", logs, 10, logs * 10, PriceSource.GRAND_EXCHANGE))), 2_000, false);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (proxy, method, args) ->
            {
                if ("getGameState".equals(method.getName())) return GameState.LOGGED_IN;
                // The bank's item panel is visible exactly while the bank is open.
                if ("getWidget".equals(method.getName()) && bankShown && args != null && args.length == 1
                    && Integer.valueOf(InterfaceID.Bankmain.ITEMS_CONTAINER).equals(args[0]))
                    return Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[] {Widget.class},
                        (widget, call, callArgs) -> zero(call.getReturnType()));
                return zero(method.getReturnType());
            });
        plugin = new GpManagerPlugin() {
            @Override boolean canIngest() { return true; }
            @Override void transactionBooked(Transaction transaction, long at) { published.add(transaction); }
        };
        GpManagerPluginProbe.set(plugin, "engine", e);
        plugin.activity = new ActivityDetector(CONFIG, e);
        GpManagerPluginProbe.set(plugin, "config", CONFIG);
        GpManagerPluginProbe.set(plugin, "client", client);
        GpManagerPluginProbe.set(plugin, "targets", GpManagerPluginProbe.tracker(client, e, CONFIG));
        GpManagerPluginProbe.set(plugin, "charges", new ChargeIntake(client, null, CONFIG, e, null));
        GpManagerPluginProbe.set(plugin, "containers", new ContainerSnapshotFactory(client, null));
    }

    private static Object zero(Class<?> type)
    {
        if (type == boolean.class) return false;
        if (type == int.class) return 0;
        if (type == long.class) return 0L;
        return null;
    }

    private static ContainerSnapshot held(long logs, long air)
    {
        Map<Integer, Long> items = new HashMap<>();
        if (logs > 0) items.put(LOGS, logs);
        if (air > 0) items.put(AIR, air);
        return new ContainerSnapshot(items);
    }

    private void dropClick()
    {
        dropClick(LOGS);
    }

    private void dropClick(int item)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(), new Class<?>[] {MenuEntry.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return "Drop";
                    case "getTarget": return item == BOLTS ? "Iron bolts" : "Logs";
                    case "getItemId": return item;
                    case "getType": return MenuAction.CC_OP;
                    default: return zero(method.getReturnType());
                }
            });
        plugin.onMenuOptionClicked(new MenuOptionClicked(entry));
    }

    private void groundClick(int item)
    {
        e.events.put(Inbox.GROUND_CLICK, item, 1, 5, null);
    }

    /** A Take click on a ground item through the plugin, as the game sends it. */
    private void takeClick(int item)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(), new Class<?>[] {MenuEntry.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return "Take";
                    case "getTarget": return NAMES.get(item);
                    case "getIdentifier": return item;
                    case "getType": return MenuAction.GROUND_ITEM_THIRD_OPTION;
                    default: return zero(method.getReturnType());
                }
            });
        plugin.onMenuOptionClicked(new MenuOptionClicked(entry));
    }

    /** An inventory (or worn equipment) callback: the engine samples the snapshot on the next tick. */
    private void inventory(int container)
    {
        plugin.onItemContainerChanged(new ItemContainerChanged(container, null));
    }

    /** The BANK container callback with the bank's own counts. */
    private void bank(long logs, long air)
    {
        Map<Integer, Long> counts = new HashMap<>();
        if (logs > 0) counts.put(LOGS, logs);
        if (air > 0) counts.put(AIR, air);
        bankItems(counts);
    }

    private void bankItems(Map<Integer, Long> counts) {
        bankShown = true;
        List<Item> items = new ArrayList<>();
        counts.forEach((id, quantity) -> items.add(new Item(id, quantity.intValue())));
        ItemContainer container = (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[] {ItemContainer.class},
            (proxy, method, args) -> "getItems".equals(method.getName()) ? items.toArray(new Item[0])
                : "getId".equals(method.getName()) ? InventoryID.BANK : zero(method.getReturnType()));
        plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.BANK, container));
    }

    private void tick(long logs, long air)
    {
        e.processIfDirty(held(logs, air), now += 600, null);
    }

    private void openTicks(long logs, long air, int ticks)
    {
        bankShown = true;
        for (int i = 0; i < ticks; i++)
        {
            e.bankOpened(6);
            tick(logs, air);
        }
    }

    private void close()
    {
        bankShown = false;
        e.bankClosed();
    }

    private void closeAndPickUp(long before, long after)
    {
        close();
        for (int i = 0; i < 4; i++) tick(before, 0);
        inventory(InventoryID.INV);
        for (int i = 0; i < 4; i++) tick(after, 0);
    }

    private long count(String note)
    {
        return e.session().transactions().stream().filter(t -> note.equals(t.note())).count();
    }

    private Transaction dropped()
    {
        return e.session().transactions().stream().filter(t -> "Dropped".equals(t.note())).findFirst().orElse(null);
    }

    private void assertMoney(long net, long income, long cost)
    {
        assertEquals("net", net, e.metrics(now).net);
        assertEquals("income", income, e.metrics(now).income);
        assertEquals("cost", cost, e.metrics(now).cost);
    }

    private void assertKnown(int item, long quantity, long basis)
    {
        assertEquals("known quantity", quantity, EngineProbe.availableQty(e, item));
        assertEquals("known basis", basis, EngineProbe.availableBasisGp(e, item));
    }

    @Test public void pickingUpDroppedBoltsImmediatelyAfterBankCloseRecoversTheLoss() throws Exception
    {
        start(0, 0);
        e.setBaseline(new ContainerSnapshot(Map.of(BOLTS, 7L)));
        e.session().addTransaction(Tx.of(now, TransactionType.GAIN, Context.GENERIC, "Initial bolts", true,
                List.of(new Flow(BOLTS, "Iron bolts", 7, 10, 70, PriceSource.GRAND_EXCHANGE))), 2_000, false);
        dropClick(BOLTS);
        inventory(InventoryID.INV);
        for (int i = 0; i < 4; i++)
            e.processIfDirty(new ContainerSnapshot(Map.of()), now += 600, null);
        assertEquals(1, count("Dropped"));
        bankItems(Map.of());
        e.bankOpened(6);
        e.processIfDirty(new ContainerSnapshot(Map.of()), now += 600, null);
        close();
        groundClick(BOLTS);
        inventory(InventoryID.INV);
        for (int i = 0; i < 4; i++)
            e.processIfDirty(new ContainerSnapshot(Map.of(BOLTS, 7L)), now += 600, null);
        assertEquals("drop audit is empty", 0, dropped().flows().size());
        assertEquals("no recovered loss", 0, dropped().net());
        assertMoney(70, 70, 0);
        assertKnown(BOLTS, 7, 70);
    }

    @Test public void bankWithdrawalOfTheSameItemDoesNotRecoverTheGroundDrop() throws Exception
    {
        start(0, 0);
        e.setBaseline(new ContainerSnapshot(Map.of(BOLTS, 7L)));
        e.session().addTransaction(Tx.of(now, TransactionType.GAIN, Context.GENERIC, "Initial bolts", true,
                List.of(new Flow(BOLTS, "Iron bolts", 7, 10, 70, PriceSource.GRAND_EXCHANGE))), 2_000, false);
        dropClick(BOLTS);
        inventory(InventoryID.INV);
        for (int i = 0; i < 4; i++)
            e.processIfDirty(new ContainerSnapshot(Map.of()), now += 600, null);
        bankItems(Map.of(BOLTS, 7L));
        e.bankOpened(6);
        e.processIfDirty(new ContainerSnapshot(Map.of()), now += 600, null);
        bankItems(Map.of());
        inventory(InventoryID.INV);
        for (int i = 0; i < 4; i++)
            e.processIfDirty(new ContainerSnapshot(Map.of(BOLTS, 7L)), now += 600, null);
        assertEquals("withdrawal is not a ground pickup", 1, dropped().flows().size());
        assertEquals(-70, dropped().net());
        assertEquals(0, count("Picked back up"));
        assertMoney(0, 70, 70);
    }

    @Test public void nonBankTransferGainDoesNotRecoverTheGroundDrop() throws Exception
    {
        start(0, 0);
        e.setBaseline(new ContainerSnapshot(Map.of(BOLTS, 7L)));
        e.session().addTransaction(Tx.of(now, TransactionType.GAIN, Context.GENERIC, "Initial bolts", true,
                List.of(new Flow(BOLTS, "Iron bolts", 7, 10, 70, PriceSource.GRAND_EXCHANGE))), 2_000, false);
        dropClick(BOLTS);
        inventory(InventoryID.INV);
        for (int i = 0; i < 4; i++)
            e.processIfDirty(new ContainerSnapshot(Map.of()), now += 600, null);
        e.markContext(Context.TRANSFER, 6, "Grand Exchange");
        inventory(InventoryID.INV);
        for (int i = 0; i < 4; i++)
            e.processIfDirty(new ContainerSnapshot(Map.of(BOLTS, 7L)), now += 600, null);
        assertEquals("transfer gain is not a ground pickup", 1, dropped().flows().size());
        assertEquals(-70, dropped().net());
        assertEquals(0, count("Picked back up"));
        assertMoney(0, 70, 70);
    }

    // G1: the bank's first sight arrives before the drop's inventory callback.
    @Test public void bankSyncBeforeTheDropsInventoryCallbackKeepsTheDrop() throws Exception
    {
        start(3, 0);
        dropClick();
        bank(0, 0);
        inventory(InventoryID.INV);
        openTicks(0, 0, 4);
        assertEquals(1, count("Dropped"));
        assertEquals(-30, dropped().net());
        assertEquals(10, dropped().flows().get(0).unitPrice);
        closeAndPickUp(0, 3);
        assertEquals(1, count("Picked back up"));
        assertMoney(30, 30, 0);
        assertKnown(LOGS, 3, 30);
    }

    @Test public void bankPanelBeforeTheBankSyncKeepsTheDrop() throws Exception
    {
        start(3, 0);
        dropClick();
        bankShown = true;
        e.bankOpened(6);
        bank(0, 0);
        inventory(InventoryID.INV);
        openTicks(0, 0, 4);
        assertEquals(1, count("Dropped"));
        closeAndPickUp(0, 3);
        assertMoney(30, 30, 0);
        assertKnown(LOGS, 3, 30);
    }

    @Test public void sampledDropThenBankSyncKeepsTheDrop() throws Exception
    {
        start(3, 0);
        dropClick();
        inventory(InventoryID.INV);
        tick(0, 0);
        bank(0, 0);
        openTicks(0, 0, 4);
        closeAndPickUp(0, 3);
        assertMoney(30, 30, 0);
        assertKnown(LOGS, 3, 30);
    }

    // G2: a cancelled Drop, an unrelated equipment callback, then a real deposit before any sample.
