import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The binding necklace (16 uses, destroyed when its charges run out) is consumption gear: its
 * crumble books one counted loss at its price, and nothing per-charge is inferred (owner
 * 2026-10-13; VarPlayer 487 confirms charges exist but the crumble is the honest observable).
 */
public class BindingNecklaceTest
{
    private static final int NECKLACE = ItemID.MAGIC_EMERALD_NECKLACE;

    private static Engine settle(Map<Integer, Long> before, Map<Integer, Long> after)
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Binding necklace", quantity, 620,
                quantity * 620)));
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
        });
        engine.ensureSession(1_000_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(before)));
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)), 1_000_000L + tick * 600L, null);
        }
        return engine;
    }

    @Test
    public void theCrumbleBooksOneCountedLoss()
    {
        Engine engine = settle(Map.of(NECKLACE, 1L), Map.of());
        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertTrue(rows.get(0).counts());
        assertEquals(-620L, engine.metrics(1_010_000L).net);
    }
}

package com.gpmanager;

import java.util.*;
import net.runelite.api.ItemComposition;
import org.junit.Test;
import static org.junit.Assert.*;

/** Recorded 20261024-022450: partial blighted bottles have no independent market quote. */
public class BlightedDoseTest {
    static final int[] RESTORE = {24605, 24603, 24601, 24598};
    static final int[] OVERLOAD = {29640, 29637, 29634, 29631};

    static Valuation service(int[] ids, String name, int price, String manual) {
        Map<Integer, String> names = new HashMap<>();
        for (int i = 0; i < ids.length; i++) names.put(ids[i], name + "(" + (i + 1) + ")");
        return ModelProbe.valuation(new GpManagerConfig() {
            @Override public String manualPriceOverrides() { return manual; }
        }, id -> ReviewFixesTest.proxy(ItemComposition.class,
                Map.of("getName", names.getOrDefault(id, "Item " + id), "getHaPrice", 24,
                        "isTradeable", true)), id -> id == ids[3] ? price : 0);
    }

    static List<Transaction> drinks(Valuation value, int[] ids) {
        var rows = new ArrayList<Transaction>();
        for (int i = 3; i >= 0; i--) {
            Map<Integer, Long> deltas = new LinkedHashMap<>();
            deltas.put(ids[i], -1L);
            if (i > 0) deltas.put(ids[i - 1], 1L);
            var raw = value.value(deltas, 1000);
            var normalized = value.normalizeConsumedFlows(raw, ActionKind.DRINK, 1000);
            assertNotNull("one dose must have an authoritative price", normalized);
            var row = new Transaction(1000 + i, TransactionType.CONSUMPTION, Context.GENERIC,
                    "", "PKing", true, normalized, Confidence.LIKELY, "recorded sip", null);
            row.setAction(ActionKind.DRINK);
            rows.add(row);
        }
        return rows;
    }

    @Test public void allFourRestoreDosesMergeAndCostOneBottle() {
        assertBottle(RESTORE, "Blighted super restore");
    }

    @Test public void allFourOverloadDosesUseTheirOwnFamily() {
        assertBottle(OVERLOAD, "Blighted overload");
    }

    static void assertBottle(int[] ids, String name) {
        var rows = drinks(service(ids, name, 2324, ""), ids);
        var result = SemanticProbe.capture(rows, List.of(), "", null);
        assertEquals(1, result.groups.size());
        assertEquals(4, result.groups.get(0).quantity);
        assertEquals(-2324, result.groups.get(0).value);
        for (var row : rows) {
            assertEquals(-581, row.flows().stream().mapToLong(flow -> flow.value).sum());
            for (var flow : row.flows()) assertEquals(PriceSource.GRAND_EXCHANGE, flow.source());
        }
        Session session = new Session("PKing", 0, SessionMode.GENERAL);
        rows.forEach(row -> session.addTransaction(row, 100, false));
        assertEquals(0, session.metrics(5000).income);
        assertEquals(2324, session.metrics(5000).supplies);
    }

    @Test public void manualFullQuoteRemainsAuthoritative() {
        var rows = drinks(service(RESTORE, "Blighted super restore", 2324, "24598=4000"), RESTORE);
        assertEquals(-4000, rows.stream().flatMap(row -> row.flows().stream()).mapToLong(flow -> flow.value).sum());
        for (var row : rows) for (var flow : row.flows()) assertEquals(PriceSource.MANUAL_OVERRIDE, flow.source());
    }

    @Test public void missingFamilyQuoteCannotTurnAlchFallbackIntoMarketAuthority() {
        var value = service(RESTORE, "Blighted super restore", 0, "");
        assertNull(value.normalizeConsumedFlows(value.value(Map.of(24598, -1L, 24601, 1L), 1000),
                ActionKind.DRINK, 1000));
    }

    @Test public void blightedAndOrdinaryRestoresNeverMerge() {
        var rows = drinks(service(RESTORE, "Blighted super restore", 2324, ""), RESTORE);
        int[] normal = {3030, 3028, 3026, 3024};
        // Ordinary restores have their own (1) authority, preserving their existing policy.
        var value = ModelProbe.valuation(new GpManagerConfig() {}, id -> ReviewFixesTest.proxy(ItemComposition.class,
                Map.of("getName", "Super restore(" + (Arrays.binarySearch(new int[]{3024,3026,3028,3030}, id) < 0 ? 1 :
                    (3030 - id) / 2 + 1) + ")", "isTradeable", true)), id -> (3030 - id) / 2 * 581 + 581);
        rows.addAll(drinks(value, normal));
        assertEquals(2, SemanticProbe.capture(rows, List.of(), "", null).groups.size());
    }
}

package com.gpmanager;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Owner 2026-09-29: a blood shard becomes a charge only when a read measures hits used.
 * Attaching one to a plain fury is an uncounted mixed change, and a pending recharge blocks
 * the shard from measured spend until the Review row is decided — never both at once.
 */
public class BloodFuryLoadTest
{
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void attachingABloodShardToAFuryIsAnUncountedMixedChange()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(ItemID.BLOOD_SHARD, 1L);
        held.put(ItemID.ENCHANTED_ONYX_AMULET, 1L);
        engine.setBaseline(new ContainerSnapshot(held));
        engine.markDirty();
        Map<Integer, Long> attached = new HashMap<>();
        attached.put(ItemID.BLOOD_AMULET, 1L);

        Transaction settled = settle(engine, attached, T0);
        assertNotNull(settled);
        assertEquals("a mixed attach with no context stays uncertain", TransactionType.UNCERTAIN,
            settled.type());
        assertFalse("the default never counts an uncertain mixed change", settled.counts());
        assertEquals("Net stays 0 until a read measures hits used", 0L,
            engine.metrics(T0 + 2_400L).net);
    }

    @Test
    public void aValidatedRechargeTransfersNeutrallyAndNeverBlocks()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(ItemID.BLOOD_SHARD, 1L);
        engine.setBaseline(new ContainerSnapshot(held));
        engine.markDirty();
        assertTrue(engine.markChargeLoad(ChargeCheck.ChargedItem.BLOOD_FURY, ItemID.BLOOD_SHARD, "Blood shard",
            "149:2:0:" + ItemID.BLOOD_AMULET + ":BLOOD_FURY", 6));

        Transaction load = settle(engine, new HashMap<>(), T0);
        assertNotNull(load);
        assertEquals("value moved into charges, never a cost", TransactionType.TRANSFER, load.original());
        assertFalse(load.counts());
        assertEquals(0L, engine.metrics(T0 + 2_400L).net);
    }

    private static Transaction settle(Engine engine, Map<Integer, Long> held, long from)
    {
        Transaction result = null;
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(held)), from + 600L + i * 600L, null);
            if (settled != null)
            {
                result = settled;
            }
        }
        return result;
    }

    private static Engine engine()
    {
        Map<Integer, String> names = new HashMap<>();
        names.put(ItemID.BLOOD_SHARD, "Blood shard");
        names.put(ItemID.ENCHANTED_ONYX_AMULET, "Amulet of fury");
        names.put(ItemID.BLOOD_AMULET, "Amulet of blood fury");
        Map<Integer, Integer> prices = new HashMap<>();
        prices.put(ItemID.BLOOD_SHARD, 8_000_000);
        prices.put(ItemID.ENCHANTED_ONYX_AMULET, 2_800_000);
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int unit = prices.getOrDefault(delta.getKey(), 0);
                flows.add(new Flow(delta.getKey(),
                    names.getOrDefault(delta.getKey(), "Item " + delta.getKey()),
                    delta.getValue(), unit, delta.getValue() * unit, PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        });
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Blue Moon's Weapon Freeze (Moons of Peril) seals the wielded weapon in a block of ice until the
 * player punches it free; after a logout Eyatlalli holds it (OSRS Wiki: Blue Moon, Eyatlalli).
 * Profit Loss Calculator keys the freeze off PMOON_BOSS_BLUE_WEARPREVENT. The weapon stays carried
 * throughout, so the round trip books nothing.
 */
public class BlueMoonWeaponFreezeTest
{
    private static final int WEAPON = EquipmentInventorySlot.WEAPON.getSlotIdx();

    /** Mutable inventory, worn weapon slot and freeze varbit behind a proxy client. */
    static final class Harness
    {
        Item[] inventory = new Item[0];
        Item weapon;
        int frozen;
        /** The logged-in account; null leaves it unknown, as an offline client reports. */
        Long hash;
        final ContainerSnapshotFactory factory;

        Harness()
        {
            Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
                (proxy, method, args) -> {
                    if ("getItemContainer".equals(method.getName()))
                    {
                        int id = (int) args[0];
                        return id == InventoryID.INV ? container(inventory) : id == InventoryID.WORN ? worn() : null;
                    }
                    if ("getVarbitValue".equals(method.getName()))
                    {
                        return (int) args[0] == VarbitID.PMOON_BOSS_BLUE_WEARPREVENT ? frozen : 0;
                    }
                    if ("getAccountHash".equals(method.getName()))
                    {
                        return hash;
                    }
                    return null;
                });
            factory = new ContainerSnapshotFactory(client, null);
        }

        ItemContainer worn()
        {
            Item[] slots = new Item[14];
            slots[WEAPON] = weapon;
            return container(slots);
        }

        static ItemContainer container(Item[] items)
        {
            return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
                new Class<?>[]{ItemContainer.class}, (proxy, method, args) -> {
                    if ("getItems".equals(method.getName()))
                    {
                        return items;
                    }
                    if ("getItem".equals(method.getName()))
                    {
                        int slot = (int) args[0];
                        return slot < items.length ? items[slot] : null;
                    }
                    return null;
                });
        }

        long carried(int item)
        {
            return factory.capture(true, false).quantity(item);
        }
    }

    @Test
    public void aFrozenWeaponStaysCarriedUntilItReturns()
    {
        Harness game = new Harness();
        game.weapon = new Item(ItemID.ABYSSAL_WHIP, 1);
        assertEquals(1L, game.carried(ItemID.ABYSSAL_WHIP));
        game.frozen = 1;
        assertEquals("the weapon still wielded as the freeze starts", 1L, game.carried(ItemID.ABYSSAL_WHIP));
        game.weapon = null;
        assertEquals("sealed in ice", 1L, game.carried(ItemID.ABYSSAL_WHIP));
        game.frozen = 0;
        assertEquals("the varbit clearing before the weapon is back", 1L, game.carried(ItemID.ABYSSAL_WHIP));
        game.weapon = new Item(ItemID.ABYSSAL_WHIP, 1);
        assertEquals("punched free", 1L, game.carried(ItemID.ABYSSAL_WHIP));
        game.weapon = null;
        assertEquals("a later deposit from the slot is a real change", 0L, game.carried(ItemID.ABYSSAL_WHIP));
    }

    @Test
    public void aFrozenThrownStackKeepsItsQuantity()
    {
        Harness game = new Harness();
        game.weapon = new Item(ItemID.DRAGON_DART, 2_000);
        game.carried(ItemID.DRAGON_DART);
        game.weapon = null;
        game.frozen = 1;
        assertEquals(2_000L, game.carried(ItemID.DRAGON_DART));
    }

    @Test
    public void eyatlalliReturningItToTheInventoryCountsItOnce()
    {
        Harness game = new Harness();
        game.weapon = new Item(ItemID.ABYSSAL_WHIP, 1);
        game.carried(ItemID.ABYSSAL_WHIP);
        game.weapon = null;
        game.frozen = 1;
        game.carried(ItemID.ABYSSAL_WHIP);
        game.frozen = 0;
        game.inventory = new Item[]{new Item(ItemID.ABYSSAL_WHIP, 1)};
        assertEquals(1L, game.carried(ItemID.ABYSSAL_WHIP));
        game.inventory = new Item[0];
        assertEquals("the hold ended once the weapon was seen", 0L, game.carried(ItemID.ABYSSAL_WHIP));
    }

    @Test
    public void withoutTheFreezeAnEmptiedSlotIsNotHeld()
    {
        Harness game = new Harness();
        game.weapon = new Item(ItemID.ABYSSAL_WHIP, 1);
        game.carried(ItemID.ABYSSAL_WHIP);
        game.weapon = null;
        assertEquals(0L, game.carried(ItemID.ABYSSAL_WHIP));
    }

    @Test
    public void theRoundTripBooksNothing()
    {
        Harness game = new Harness();
        game.weapon = new Item(ItemID.DRAGON_DART, 500);
        Engine engine = new Engine(deltas -> {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Dragon dart", quantity, 1_000, quantity * 1_000)));
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 2;
            }
        });
        engine.ensureSession(1_000L);
        engine.setBaseline(game.factory.capture(true, false));
        long now = 1_600L;
        for (int tick = 0; tick < 30; tick++, now += 600L)
        {
            game.frozen = tick >= 2 && tick < 20 ? 1 : 0;
            Item before = game.weapon;
            game.weapon = tick >= 3 && tick < 22 ? null : new Item(ItemID.DRAGON_DART, 500);
            // Only a worn-container change marks the inventory dirty, as in the plugin.
            if ((before == null) != (game.weapon == null)) engine.markDirty();
            engine.processIfDirty(game.factory.capture(true, false), now, null);
        }
        assertTrue(engine.session().transactions().isEmpty());
        assertEquals(0L, engine.metrics(now).cost);
        assertEquals(0L, engine.metrics(now).income);
    }
    @Test
    public void aSpareOfTheSameWeaponIsNotTheFrozenOneReturning()
    {
        Harness game = new Harness();
        game.inventory = new Item[]{new Item(ItemID.ABYSSAL_WHIP, 1)};
        game.weapon = new Item(ItemID.ABYSSAL_WHIP, 1);
        assertEquals(2L, game.carried(ItemID.ABYSSAL_WHIP));
        game.weapon = null;
        game.frozen = 1;
        assertEquals("the spare and the frozen whip", 2L, game.carried(ItemID.ABYSSAL_WHIP));
        game.frozen = 0;
        assertEquals("still in the ice once the varbit clears", 2L, game.carried(ItemID.ABYSSAL_WHIP));
        game.inventory = new Item[]{new Item(ItemID.ABYSSAL_WHIP, 1), new Item(ItemID.ABYSSAL_WHIP, 1)};
        assertEquals("Eyatlalli returns it beside the spare", 2L, game.carried(ItemID.ABYSSAL_WHIP));
        game.inventory = new Item[]{new Item(ItemID.ABYSSAL_WHIP, 1)};
        assertEquals("the hold ended at the return", 1L, game.carried(ItemID.ABYSSAL_WHIP));
    }

    @Test
    public void frozenDartsKeepTheirQuantityBesideLooseDartsUntilTheyReturn()
    {
        Harness game = new Harness();
        game.inventory = new Item[]{new Item(ItemID.DRAGON_DART, 100)};
        game.weapon = new Item(ItemID.DRAGON_DART, 500);
        assertEquals(600L, game.carried(ItemID.DRAGON_DART));
        game.weapon = null;
        game.frozen = 1;
        for (int capture = 0; capture < 3; capture++)
        {
            assertEquals("capture " + capture, 600L, game.carried(ItemID.DRAGON_DART));
        }
        game.inventory = new Item[]{new Item(ItemID.DRAGON_DART, 130)};
        assertEquals("30 more picked up while frozen", 630L, game.carried(ItemID.DRAGON_DART));
        game.frozen = 0;
        assertEquals("the varbit clearing before the darts are back", 630L, game.carried(ItemID.DRAGON_DART));
        game.weapon = new Item(ItemID.DRAGON_DART, 500);
        assertEquals("punched free, counted once", 630L, game.carried(ItemID.DRAGON_DART));
        game.weapon = null;
        assertEquals("a later deposit from the slot is a real change", 130L, game.carried(ItemID.DRAGON_DART));
    }

    @Test
    public void anotherAccountNeverInheritsTheFrozenWeapon()
    {
        Harness game = new Harness();
        game.hash = 7L;
        game.weapon = new Item(ItemID.ABYSSAL_WHIP, 1);
        game.carried(ItemID.ABYSSAL_WHIP);
        game.weapon = null;
        game.frozen = 1;
        assertEquals(1L, game.carried(ItemID.ABYSSAL_WHIP));
        game.frozen = 0;
        Engine other = ReviewFixesTest.engine();
        GpManagerPlugin plugin = switcher(game, other);
        game.hash = -1L;
        plugin.beginOwnerSwitch();
        game.hash = 8L;
        plugin.beginOwnerSwitch();
        game.inventory = new Item[]{new Item(ItemID.BRONZE_DAGGER, 1)};
        other.setBaseline(game.factory.capture(true, false));
        assertEquals(0L, other.baseline.quantity(ItemID.ABYSSAL_WHIP));
        game.weapon = new Item(ItemID.BRONZE_DAGGER, 1);
        game.inventory = new Item[0];
        other.markDirty();
        for (int tick = 0; tick < 8; tick++)
        {
            other.processIfDirty(game.factory.capture(true, false), ReviewFixesTest.T0 + (tick + 1) * 600L, null);
        }
        assertEquals("equipping the new account's own dagger is neutral", 0L,
            other.metrics(ReviewFixesTest.T0 + 10_000L).net);
    }

    @Test
    public void anUnknownOwnerReleasesTheWeaponAtAnOwnerSwitch()
    {
        Harness game = new Harness();
        game.weapon = new Item(ItemID.ABYSSAL_WHIP, 1);
        game.carried(ItemID.ABYSSAL_WHIP);
        game.weapon = null;
        game.frozen = 1;
        assertEquals(1L, game.carried(ItemID.ABYSSAL_WHIP));
        game.frozen = 0;
        switcher(game, ReviewFixesTest.engine()).beginOwnerSwitch();
        assertEquals(0L, game.carried(ItemID.ABYSSAL_WHIP));
    }

    @Test
    public void aRelogOnTheSameAccountKeepsTheWeaponWithEyatlalli()
    {
