package com.gpmanager;

import java.util.*;
import com.google.gson.Gson;
import org.junit.*;
import static org.junit.Assert.*;

/** Captured historical sips are financial facts, not permission to rewrite later item basis. */
public class CapturedBlightedRecoveryTest {
    static final int[] IDS=BlightedDoseTest.RESTORE;
    static final long AT=1700000000000L;
    java.util.function.LongSupplier previous;
    @Before public void clock(){previous=SafeMath.clock;SafeMath.clock=()->AT;JsonCodec.bind(new Gson());}
    @After public void restore(){SafeMath.clock=previous;}
    static Engine engine(){var e=new Engine(BlightedDoseTest.service(IDS,"Blighted super restore",2720,""),
            new TransactionClassifier(),new GpManagerConfig(){});e.ensureSession(AT);return e;}
    static Transaction sip(int[] ids,String family,int dose,int unit,long at){
        var flows=new ArrayList<Flow>();flows.add(new Flow(ids[dose-1],family+"("+dose+")",-1,unit*dose,-unit*dose,PriceSource.GRAND_EXCHANGE,at));
        if(dose>1)flows.add(new Flow(ids[dose-2],family+"("+(dose-1)+")",1,unit*(dose-1),unit*(dose-1),PriceSource.GRAND_EXCHANGE,at));
        var row=new Transaction(at,dose>1?TransactionType.UNCERTAIN:TransactionType.CONSUMPTION,Context.GENERIC,"","PKing",dose==1,flows,
                dose>1?Confidence.UNCERTAIN:Confidence.LIKELY,dose>1?GameData.msg("consumedDose"):"Consumed",null);
        row.setAction(ActionKind.DRINK);return row;
    }
    static String json(Object x){return new Gson().toJson(x);}
    static String basis(Engine e){var s=new SavedState();e.basis.writeTo(s);return json(s.trackedBasis());}
    static void locked(Engine e){for(int id:IDS){var p=e.basis.pool(id);p.availableQty=7;p.availableBasisGp=7000;p.acquiredAt=AT+50000;p.fencedAt=AT+60000;}}
    static Transaction add(Engine e,int dose){var row=sip(IDS,"Blighted super restore",dose,581,AT+dose);e.session().addTransaction(row,2000,false);return row;}

    @Test public void capturedSipsMergeWithAlreadyCountedDoseWithoutUsingTodaysPrice(){
        var e=engine();var pending=new ArrayList<Transaction>();for(int dose=4;dose>1;dose--)pending.add(add(e,dose));
        var finalDose=add(e,1);String booked=json(finalDose);locked(e);String stock=basis(e);
        for(var row:pending){String flows=json(row.flows());assertTrue(e.recoverDose(e.session(),row,AT+100000));assertEquals(flows,json(row.flows()));}
        assertEquals(booked,json(finalDose));assertEquals(stock,basis(e));assertEquals(-2324,e.metrics(AT+100000).net);
        assertTrue(e.getReviewRows(AT+100000).isEmpty());
        var groups=SemanticProbe.capture(e.session().transactions(),List.of(),"",null).groups;
        assertEquals(1,groups.size());assertEquals("Blighted super restore",groups.get(0).name);
        assertEquals(4,groups.get(0).quantity);assertEquals(-2324,groups.get(0).value);
    }
    @Test public void boundedQueueReloadAndRepeatCannotBookAgain(){
        var e=engine();for(int dose=4;dose>1;dose--)add(e,dose);add(e,1);locked(e);
        e.restore(SaveCopies.copy(e.savedState()),AT+100000);
        for(int left=2;left>=0;left--){e.retryDose(AT+100000);assertEquals(left,e.getReviewRows(AT+100000).size());}
        String once=json(e.savedState());e.retryDose(AT+200000);assertEquals(once,json(e.savedState()));
        var next=engine();next.restore(SaveCopies.copy(e.savedState()),AT+300000);
        assertTrue(next.doseRetries.isEmpty());assertEquals(-2324,next.metrics(AT+300000).net);
        assertEquals(basis(e),basis(next));
    }
    @Test public void financialRecoveryAllowsLaterCorrectionAndUndoWithoutChangingBasis(){
        var e=engine();var row=add(e,4);locked(e);String stock=basis(e);
        assertTrue(e.recoverDose(e.session(),row,AT+100000));assertTrue(e.correctTransaction(row.id(),Correction.IGNORE,"owner"));
        assertEquals(0,e.metrics(AT+100002).net);assertEquals(stock,basis(e));
        assertTrue(e.undoCorrection());assertEquals(-581,e.metrics(AT+100004).net);assertEquals(stock,basis(e));
    }
    @Test public void genuinelyReviewedAndUndoneDecisionsRemainUntouched(){
        for(boolean undone:new boolean[]{false,true}){
            var e=engine();var row=add(e,4);assertTrue(e.correctTransaction(row.id(),Correction.IGNORE,"owner"));
            if(undone)assertTrue(e.undoCorrection());locked(e);String before=json(row);
            assertFalse(e.recoverDose(e.session(),row,AT+100000));assertEquals(before,json(row));
        }
    }
    @Test public void capturedPricesMustProveAnExactDoseAndSupportedFamily(){
        for(int variant=0;variant<9;variant++){
            var e=engine();var row=add(e,4);locked(e);
            if(variant==0){row.flows.get(0).unitPrice++;row.flows.get(0).value--;}
            if(variant==1)row.flows.get(1).quantity=2;
            if(variant==2)row.flows.get(1).priceSource=PriceSource.HIGH_ALCHEMY;
            if(variant==3){for(var f:row.flows)f.name=f.name.replace("super restore","Saradomin brew");}
            if(variant==4)row.setSourceClaimId("claim");
            if(variant==5)row.flows.get(0).raid="raid";
            if(variant==6){row.flows.get(0).name="Blighted super restore(5)";row.flows.get(0).unitPrice=2905;row.flows.get(0).value=-2905;
                row.flows.get(1).name="Blighted super restore(4)";row.flows.get(1).unitPrice=2324;row.flows.get(1).value=2324;}
            if(variant==7)row.flows.get(0).item=1113;
            if(variant==8)row.flows.get(0).item=row.flows.get(1).item;
            String before=json(row);assertFalse("unsafe variant "+variant,e.recoverDose(e.session(),row,AT+100000));assertEquals(before,json(row));
        }
    }
    @Test public void restoredHistoricalSpendsNeverCreateTrackedItemCredit(){
        var e=engine();var row=add(e,4);locked(e);e.basis.epoch=AT+10000;String stock=basis(e);
        assertTrue(e.recoverDose(e.session(),row,AT+100000));
        var s=SaveCopies.copy(e.savedState());var next=engine();next.restore(s,AT+200000);
        assertEquals(stock,basis(next));assertTrue(next.correctTransaction(row.id(),Correction.REVENUE,"owner"));
        assertEquals(stock,basis(next));assertTrue(next.undoCorrection());assertEquals(stock,basis(next));
    }
    @Test public void differentPotionFamiliesRemainSeparate(){
        var e=engine();var restore=add(e,4);locked(e);assertTrue(e.recoverDose(e.session(),restore,AT+100000));
        var brew=sip(new int[]{6691,6689,6687,6685},"Saradomin brew",1,1000,AT+9);e.session().addTransaction(brew,2000,false);
        var groups=SemanticProbe.capture(e.session().transactions(),List.of(),"",null).groups;
        assertEquals(2,groups.size());assertEquals(Set.of("Blighted super restore","Saradomin brew"),
                groups.stream().map(g->g.name).collect(java.util.stream.Collectors.toSet()));
    }
    @Test public void savedProvenanceMarkerIsStable(){
        assertEquals("Recovered from original blighted dose prices; later tracked item values are unchanged.",GameData.msg("capturedDose"));
    }
    static Engine previewEngine(){
        var e=engine();var pending=new ArrayList<Transaction>();for(int dose=4;dose>1;dose--)pending.add(add(e,dose));add(e,1);
        var fresh=BlightedDoseTest.drinks(BlightedDoseTest.service(IDS,"Blighted super restore",2720,""),IDS);
        int index=0;for(var row:fresh){row.timestamp=AT+100+index++;e.session().addTransaction(row,2000,false);}
        var extra=SaveCopies.copy(fresh.get(0));extra.id=Phrases.uuid();extra.timestamp=AT+110;e.session().addTransaction(extra,2000,false);
        locked(e);for(var row:pending)assertTrue(e.recoverDose(e.session(),row,AT+100000));return e;
    }
    static void previews(java.io.File out)throws java.io.IOException{
        var previous=SafeMath.clock;SafeMath.clock=()->AT+100000;
        try{for(int width:new int[]{213,225,300}){
            var e=previewEngine();var panel=new SidebarPanel(e,new GpManagerConfig(){},null,null,null);
            var frame=new javax.swing.JFrame("Offline captured-dose preview");
            frame.setUndecorated(true);frame.setFocusableWindowState(false);frame.setLocation(-10000,-10000);
            try{
                frame.add(panel);frame.pack();frame.setSize(width,540);frame.setVisible(true);SidebarPanelProbe.refresh(panel);frame.validate();
                var row=panel.snapshot.recent.get(0);assertEquals("Blighted super restore",row.name);assertEquals(Fmt.times(9)+" doses",row.qty.trim());
                assertEquals(-5724,row.value);assertEquals(1,panel.snapshot.recent.size());
                var image=new java.awt.image.BufferedImage(width,540,java.awt.image.BufferedImage.TYPE_INT_RGB);
                var g=image.createGraphics();panel.printAll(g);g.dispose();
                javax.imageio.ImageIO.write(image,"png",new java.io.File(out,"captured-blighted-"+width+".png"));
            }finally{frame.dispose();}
        }}finally{SafeMath.clock=previous;}
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner report 2026-09-28: an Ice Barrage cast settling with a pickup showed as loose Death, Blood and
 * Water "losses" on the loot receipt, and a spell clicked while autocasting renamed the autocast.
 */
public class CastWithPickupTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final Map<Integer, String> NAMES = new HashMap<>();

    static
    {
        NAMES.put(560, "Death rune");
        NAMES.put(565, "Blood rune");
        NAMES.put(555, "Water rune");
        NAMES.put(562, "Chaos rune");
        NAMES.put(808, "Steel dart");
        NAMES.put(2434, "Prayer potion(4)");
        NAMES.put(139, "Prayer potion(3)");
        NAMES.put(561, "Nature rune");
        NAMES.put(554, "Fire rune");
        NAMES.put(995, "Coins");
        NAMES.put(4698, "Mud rune");
        NAMES.put(1359, "Rune axe");
    }

    @Test
    public void aCastSettlingWithAPickupBooksAsItsOwnCast()
    {
        Engine engine = engine();
        engine.startCustom("Nechryael", T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(560, 100L);
        held.put(565, 100L);
        held.put(555, 100L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(held)));
        held.put(560, 96L);
        held.put(565, 98L);
        held.put(555, 94L);
        held.put(1359, 1L);
        engine.markDirty();
        List<Transaction> booked = new ArrayList<>();
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(held)),
                T0 + 600L + i * 600L, booked::add);
            if (settled != null)
            {
                booked.add(settled);
            }
        }
        Transaction cast = booked.stream().filter(t -> t.action() == ActionKind.CAST).findFirst().orElse(null);
        assertNotNull("the runes book as a Cast: " + booked, cast);
        assertEquals("Ice Barrage", cast.spellName());
        assertEquals(3, cast.flows().size());
        assertTrue("the pickup keeps only its gain", booked.stream().anyMatch(t -> t != cast
            && t.flows().size() == 1 && t.flows().get(0).item == 1359 && t.counts()));
    }

    @Test
    public void aQueuedClickNeverRenamesTheSpellItsRunesPaid()
    {
        Transaction barrage = new Transaction(T0, TransactionType.CONSUMPTION, Context.GENERIC,
            "", "Nechryael", true, Arrays.asList(new Flow(560, "Death rune", -4L, 187, -748L),
                new Flow(565, "Blood rune", -2L, 341, -682L), new Flow(555, "Water rune", -6L, 5, -30L)),
            Confidence.CONFIRMED, "fixture", null);
        barrage.setAction(ActionKind.CAST);
        barrage.setActionLabel(ActionLabel.of("Ice Burst"));
        assertEquals("Ice Barrage", barrage.spellName());

        Transaction alch = new Transaction(T0, TransactionType.CONSUMPTION, Context.GENERIC,
            "", "Magic", true, Arrays.asList(new Flow(561, "Nature rune", -1L, 100, -100L),
                new Flow(554, "Fire rune", -5L, 5, -25L)), Confidence.CONFIRMED, "fixture", null);
        alch.setAction(ActionKind.CAST);
        alch.setActionLabel(ActionLabel.of("High Level Alchemy"));
        assertEquals("a spell outside the combat table keeps its click", "High Level Alchemy", alch.spellName());
    }

    @Test
    public void aPotionAndACastKeepTheirOwnSupplyReceipts()
    {
        Engine engine = engine();
        engine.startCustom("Nechryael", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(
            562, 100L, 560, 100L, 555, 100L, 2434, 1L))));
        engine.noteConsume(2434, 10, false, ActionKind.DRINK, null);
        List<Transaction> booked = settle(engine, Map.of(562, 96L, 560, 98L, 555, 96L, 139, 1L));
        assertEquals("the drink and cast are separate", 2, booked.size());
        Transaction cast = booked.stream().filter(t -> t.action() == ActionKind.CAST)
            .findFirst().orElseThrow(AssertionError::new);
        Transaction drink = booked.stream().filter(t -> t.action() == ActionKind.DRINK)
            .findFirst().orElseThrow(AssertionError::new);
        assertEquals("Ice Burst", cast.spellName());
        assertEquals(3, cast.flows().size());
        assertEquals(2, drink.flows().size());
        assertEquals("no costs are lost or counted twice", -1_100L,
            booked.stream().mapToLong(Transaction::net).sum());
        assertSupplies(booked);
    }

    @Test
    public void aCastAndDartsSettlingWithLootAreSeparateSupplies()
    {
        Engine engine = engine();
        engine.startCustom("Nechryael", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(
            562, 100L, 560, 100L, 555, 100L, 808, 100L))));
        engine.markLoot(Map.of(1359, 1L), 30, "Loot from Greater Nechryael", "Greater Nechryael");
        List<Transaction> booked = settle(engine, Map.of(562, 96L, 560, 98L, 555, 96L, 808, 97L, 1359, 1L));
        assertEquals(3, booked.size());
        assertEquals(1L, booked.stream().filter(t -> t.action() == ActionKind.CAST).count());
        assertEquals(1L, booked.stream().filter(t -> t.action() == ActionKind.FIRE).count());
        Transaction loot = booked.stream().filter(t -> t.type() == TransactionType.LOOT)
            .findFirst().orElseThrow(AssertionError::new);
        assertEquals("loot owns no supply legs", 1, loot.flows().size());
        assertEquals(6_190L, booked.stream().mapToLong(Transaction::net).sum());
        assertSupplies(booked);
    }

    @Test
    public void aRunePickupKeepsItsMeasuredGainAndCannotInventAWaterBlast()
    {
        Engine engine = engine();
        engine.startCustom("Nechryael", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(562, 100L, 560, 100L, 555, 100L))));
        List<Transaction> booked = settle(engine, Map.of(562, 146L, 560, 98L, 555, 96L));
        assertEquals(2, booked.size());
        Transaction cast = booked.stream().filter(t -> t.action() == ActionKind.CAST)
            .findFirst().orElseThrow(AssertionError::new);
        assertEquals("incomplete spell evidence stays generic", "", cast.spellName());
        assertEquals("measured gain, without invented missing rune costs", 46L, booked.stream()
            .flatMap(t -> t.flows().stream()).filter(f -> f.item == 562).mapToLong(f -> f.quantity).sum());
        assertEquals(4_000L, booked.stream().mapToLong(Transaction::net).sum());
        assertSupplies(booked);
    }

    @Test
    public void alchingAmmunitionKeepsTheInputWithItsUtilitySpell()
    {
        Engine engine = engine();
        engine.startCustom("Alchemy", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(561, 100L, 554, 100L, 808, 100L))));
        engine.noteConsume(808, 10, false, ActionKind.CAST, ActionLabel.of("High Level Alchemy"));
        List<Transaction> booked = settle(engine, Map.of(561, 99L, 554, 95L, 808, 99L, 995, 6L));
        assertEquals("the dart was alched, never fired", 1, booked.size());
        assertEquals("High Level Alchemy", booked.get(0).spellName());
        assertEquals(4, booked.get(0).flows().size());
    }

    @Test
    public void bankMovesAndExplicitDropsNeverBecomeRoutineSpends()
    {
        for (boolean bank : new boolean[] {true, false})
        {
            Engine engine = engine();
            engine.startCustom("Nechryael", T0);
            engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(562, 100L, 560, 100L, 555, 100L))));
            if (bank) engine.markTransfer("Bank transfer", 10);
            else engine.noteDrop(560, 10);
            List<Transaction> booked = settle(engine, Map.of(562, 96L, 560, 98L, 555, 96L, 1359, 1L));
            assertTrue("stronger evidence prevents an automatic Cast", booked.stream()
                .noneMatch(t -> t.action() == ActionKind.CAST || t.action() == ActionKind.FIRE));
        }
    }

    @Test
    public void elementalRunesTurningIntoCombinationRunesDoNotProveACast()
    {
        // The existing 20261013-014425 recording: no spell click or catalytic rune spend.
        Engine engine = engine();
        engine.startCustom("Rune changes", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(555, 100L))));
        List<Transaction> booked = settle(engine, Map.of(555, 78L, 4698, 24L));
        assertEquals(1, booked.size());
        assertTrue(booked.stream().noneMatch(t -> t.action() == ActionKind.CAST));
    }

    private static List<Transaction> settle(Engine engine, Map<Integer, Long> after)
    {
        engine.markDirty();
        List<Transaction> booked = new ArrayList<>();
        for (int tick = 0; tick < 3; tick++)
        {
            Transaction row = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)),
                T0 + 600L + tick * 600L, booked::add);
            if (row != null) booked.add(row);
        }
        return booked;
    }

    private static void assertSupplies(List<Transaction> booked)
    {
        for (Transaction row : booked)
            for (Flow flow : row.flows())
                if (flow.cost()) assertEquals("spent rune/ammo/dose is a supply", CostKind.SUPPLIES,
                    CostKind.of(row, flow));
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int unit = delta.getKey() == 1359 ? 7_202 : delta.getKey() == 2434 ? 400
                    : delta.getKey() == 139 ? 300 : delta.getKey() == 808 ? 4 : delta.getKey() == 995 ? 1 : 100;
                flows.add(new Flow(delta.getKey(), NAMES.get(delta.getKey()), delta.getValue(), unit,
                    delta.getValue() * unit, PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.*;

/** Focused contracts for automatic charge estimates and Check reconciliation. */
public class ChargeEstimateReconciliationTest
{
    private static final long T0 = 10_000L;

    @Test
    public void estimatedUsageBooksLikelyCostAndKeepsComponentJournal()
    {
        Engine engine = engine();
        engine.ensureSession(T0);

        Transaction receipt = engine.bookEstimatedCharge("slot-a", "seas",
            ActionKind.CAST, flows(
                flow(ItemID.DEATHRUNE, "Death rune", -2L, 100),
                flow(ItemID.CHAOSRUNE, "Chaos rune", -2L, 50)), T0 + 1L);

        assertNotNull(receipt);
        assertEquals(Confidence.LIKELY, receipt.confidence());
        assertEquals("Estimated", receipt.explanation());
        assertEquals(-300L, receipt.net());
        assertEquals(2L, ChargeProbes.adp(engine.estimate,
            engine.session().id(), "slot-a", "seas", ItemID.DEATHRUNE));
        assertEquals(2L, ChargeProbes.adp(engine.estimate,
            engine.session().id(), "slot-a", "seas", ItemID.CHAOSRUNE));
    }

    @Test
    public void checkShrinksEstimatesAtCapturedPricesAndBooksOnlyMeasuredRemainder()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Transaction estimate = engine.bookEstimatedCharge("slot-a", "seas",
            ActionKind.CAST, flows(
                flow(ItemID.DEATHRUNE, "Death rune", -3L, 100),
                flow(ItemID.CHAOSRUNE, "Chaos rune", -1L, 50),
                flow(ItemID.FIRERUNE, "Fire rune", -10L, 5),
                new Flow(ItemID.COINS, "Coins", -20L, 1, -20L, PriceSource.FACE_VALUE)), T0 + 1L);

        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.TRIDENT_SEAS,
            Arrays.asList(new ChargeDelta.ComponentDelta(ItemID.DEATHRUNE, -2L),
                new ChargeDelta.ComponentDelta(ItemID.CHAOSRUNE, -3L),
                new ChargeDelta.ComponentDelta(ItemID.FIRERUNE, -10L),
                new ChargeDelta.ComponentDelta(ItemID.COINS, -20L)), ChargeDelta.CheckResult.SPEND);
        Transaction measured = engine.bookChargeSpend(delta, "Trident of the seas",
            flows(
                flow(ItemID.DEATHRUNE, "Death rune", -2L, 100),
                flow(ItemID.CHAOSRUNE, "Chaos rune", -3L, 50),
                flow(ItemID.FIRERUNE, "Fire rune", -10L, 5),
                new Flow(ItemID.COINS, "Coins", -20L, 1, -20L, PriceSource.FACE_VALUE)),
            T0 + 2L, "slot-a");

        assertNotNull(measured);
        assertEquals(2L, estimate.quantity(ItemID.DEATHRUNE, false));
        assertEquals(100, estimate.flows().get(0).unitPrice);
        assertEquals(1L, estimate.quantity(ItemID.CHAOSRUNE, false));
        assertEquals(Confidence.CONFIRMED, estimate.confidence());
        assertEquals("Confirmed", estimate.explanation());
        assertEquals(2L, measured.quantity(ItemID.CHAOSRUNE, false));
        assertEquals(0L, ChargeProbes.adp(engine.estimate,
            engine.session().id(), "slot-a", "seas", ItemID.DEATHRUNE));
        assertEquals(0L, ChargeProbes.adp(engine.estimate,
            engine.session().id(), "slot-a", "seas", ItemID.CHAOSRUNE));
    }

    @Test
    public void manualCorrectionSurvivesReconciliationWithoutRepricing()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Transaction estimate = engine.bookEstimatedCharge("slot-a", "seas",
            ActionKind.CAST, Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -3L, 100)),
            T0 + 1L);
        assertTrue(engine.session().correctTransaction(estimate.id(),
            Correction.COST, "Owner decision"));

        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.TRIDENT_SEAS,
            Collections.singletonList(new ChargeDelta.ComponentDelta(ItemID.DEATHRUNE, -2L)), ChargeDelta.CheckResult.SPEND);
        Transaction measured = engine.bookChargeSpend(delta, "Trident of the seas",
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -2L, 100)), T0 + 3L, "slot-a");

        assertNull(measured);
        assertEquals(Correction.COST, estimate.correction());
        assertEquals(3L, estimate.quantity(ItemID.DEATHRUNE, false));
        assertEquals(100, estimate.flows().get(0).unitPrice);
    }

    @Test
    public void estimatesCannotReconcileAcrossSessions()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Transaction old = engine.bookEstimatedCharge("slot-a", "seas",
            ActionKind.CAST, Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -2L, 100)),
            T0 + 1L);
        String oldSession = engine.session().id();
        engine.startCustom("Custom", T0 + 2L);

        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.TRIDENT_SEAS,
            Collections.singletonList(new ChargeDelta.ComponentDelta(ItemID.DEATHRUNE, -2L)), ChargeDelta.CheckResult.SPEND);
        Transaction measured = engine.bookChargeSpend(delta, "Trident of the seas",
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -2L, 100)), T0 + 3L, "slot-a");

        assertNotNull(measured);
        assertEquals(2L, old.quantity(ItemID.DEATHRUNE, false));
        assertEquals(2L, measured.quantity(ItemID.DEATHRUNE, false));
        assertEquals(0L, ChargeProbes.adp(engine.estimate, oldSession,
            "slot-a", "seas", ItemID.DEATHRUNE));
    }

    @Test
    public void lifecycleResetClearsTransientEstimates()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        engine.bookEstimatedCharge("slot-a", "seas", ActionKind.CAST,
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -1L, 100)), T0 + 1L);
        engine.pauseForLifecycle(T0 + 2L);
        assertEquals(0L, ChargeProbes.adp(engine.estimate,
            engine.session().id(), "slot-a", "seas", ItemID.DEATHRUNE));
    }

    @Test
    public void aMeasuredCheckClearsItsWeaponsPendingEstimates()
    {
        ChargeEstimateJournal journal = new ChargeEstimateJournal();
        journal.record("s1", "target", "tx1", 23962, 200L);
        journal.record("s2", "target", "tx2", 20718, 20L);
        assertEquals(1, journal.receipts("s1", "target", 23962).size());

        journal.clearTarget("s1", "target");
        assertTrue("the checked weapon's estimate receipts are gone",
            journal.receipts("s1", "target", 23962).isEmpty());
        assertEquals("another session stays untouched", 1,
            journal.receipts("s2", "target", 20718).size());
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), new GpManagerConfig() {});
    }

    private static Flow flow(int id, String name, long quantity, int unit)
    {
        return new Flow(id, name, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE);
    }

    private static List<Flow> flows(Flow... values)
    {
        return Arrays.asList(values);
    }

}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * A widget-target click carries the target as the clicked widget and the item in hand as the
 * client's selected widget. A load arms in either order, against the weapon's own slot.
 */
public class ChargeLoadArmingTest
{
    private static final int BLOWPIPE_SLOT = 5;
    private static final int SCALES_SLOT = 9;

    private static Widget item(int itemId, int slot)
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[] {Widget.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getItemId": return itemId;
                    case "getIndex": return slot;
                    case "getId": return InterfaceID.Inventory.ITEMS;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        return null;
                }
            });
    }

    private static Client selecting(Widget selected)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getSelectedWidget": return selected;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
    }

    static MenuOptionClicked click(MenuAction action, String option, Widget clicked)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return option;
                    case "getTarget": return "";
                    case "getType": return action;
                    case "getWidget": return clicked;
                    case "getItemId": return clicked == null ? -1 : clicked.getItemId();
                    case "getParam0": return clicked == null ? -1 : clicked.getIndex();
                    case "getParam1": return clicked == null ? -1 : clicked.getId();
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
    }

    private static ChargeIntake intake(Client client, Engine engine)
    {
        return new ChargeIntake(client, null, new GpManagerConfig() {}, engine, null)
        {
            @Override
            String itemName(int itemId)
            {
                return itemId == ItemID.SNAKEBOSS_SCALE ? "Zulrah's scales" : null;
            }
        };
    }

    private static final String BLOWPIPE_IDENTITY = (InterfaceID.Inventory.ITEMS >>> 16) + ":" + BLOWPIPE_SLOT + ":"
        + ItemID.TOXIC_BLOWPIPE_LOADED + ":" + ChargeCheck.ChargedItem.BLOWPIPE.name();

    @Test
    public void scalesUsedOnTheBlowpipeArmTheLoad()
    {
        Engine engine = engine();
        Widget blowpipe = item(ItemID.TOXIC_BLOWPIPE_LOADED, BLOWPIPE_SLOT);
        Widget scales = item(ItemID.SNAKEBOSS_SCALE, SCALES_SLOT);
        intake(selecting(scales), engine).armLoad(
            click(MenuAction.WIDGET_TARGET_ON_WIDGET, "Use", blowpipe), "");
        assertEquals(ChargeCheck.ChargedItem.BLOWPIPE, (engine.events.peek(Inbox.LOAD_TARGET) == null ? null : engine.events.peek(Inbox.LOAD_TARGET).variant));
        assertEquals("the item in hand is the source", ItemID.SNAKEBOSS_SCALE,
            engine.events.item(Inbox.LOAD_TARGET));
        assertEquals("the weapon's own slot", BLOWPIPE_IDENTITY, (engine.events.peek(Inbox.LOAD_TARGET) == null ? null : engine.events.peek(Inbox.LOAD_TARGET).id));
    }

    @Test
    public void theBlowpipeUsedOnScalesArmsTheSameLoad()
    {
        Engine engine = engine();
        Widget blowpipe = item(ItemID.TOXIC_BLOWPIPE_LOADED, BLOWPIPE_SLOT);
        Widget scales = item(ItemID.SNAKEBOSS_SCALE, SCALES_SLOT);
        intake(selecting(blowpipe), engine).armLoad(
            click(MenuAction.WIDGET_TARGET_ON_WIDGET, "Use", scales), "");
        assertEquals(ChargeCheck.ChargedItem.BLOWPIPE, (engine.events.peek(Inbox.LOAD_TARGET) == null ? null : engine.events.peek(Inbox.LOAD_TARGET).variant));
        assertEquals(ItemID.SNAKEBOSS_SCALE, engine.events.item(Inbox.LOAD_TARGET));
        assertEquals("the identity follows the weapon, not the clicked scales", BLOWPIPE_IDENTITY,
            (engine.events.peek(Inbox.LOAD_TARGET) == null ? null : engine.events.peek(Inbox.LOAD_TARGET).id));
    }

    @Test
    public void anUnrelatedItemOrPlainClickArmsNothing()
    {
        Engine engine = engine();
        Widget blowpipe = item(ItemID.TOXIC_BLOWPIPE_LOADED, BLOWPIPE_SLOT);
        intake(selecting(item(ItemID.BIG_BONES, 2)), engine).armLoad(
            click(MenuAction.WIDGET_TARGET_ON_WIDGET, "Use", blowpipe), "");
        assertNull((engine.events.peek(Inbox.LOAD_TARGET) == null ? null : engine.events.peek(Inbox.LOAD_TARGET).variant));
        intake(selecting(item(ItemID.SNAKEBOSS_SCALE, SCALES_SLOT)), engine).armLoad(
            click(MenuAction.CC_OP, "Check", blowpipe), "");
        assertNull("only a use-on click arms a load", (engine.events.peek(Inbox.LOAD_TARGET) == null ? null : engine.events.peek(Inbox.LOAD_TARGET).variant));
    }

    @Test
    public void anyOtherActionEndsTheUnchargeWatchButAnsweringThePromptKeepsIt()
    {
        Engine engine = engine();
        engine.ensureSession(1_000L);
        ChargeIntake intake = intake(selecting(null), engine);
        Widget trident = item(ItemID.TOTS_CHARGED, 0);
        intake.onMenuOptionClicked(click(MenuAction.CC_OP, "uncharge", trident), "uncharge", "trident of the seas");
        assertEquals(ChargeCheck.ChargedItem.TRIDENT_SEAS, (intake.engine.events.peek(Inbox.UNCHARGE) == null ? null : intake.engine.events.peek(Inbox.UNCHARGE).variant));
        intake.onMenuOptionClicked(click(MenuAction.WIDGET_CONTINUE, "continue", null), "continue", "");
        assertEquals("answering the prompt keeps watching", ChargeCheck.ChargedItem.TRIDENT_SEAS, (intake.engine.events.peek(Inbox.UNCHARGE) == null ? null : intake.engine.events.peek(Inbox.UNCHARGE).variant));
        intake.onMenuOptionClicked(click(MenuAction.WALK, "walk here", null), "walk here", "");
        assertNull("walking away ends it, so later runes stay loot", (intake.engine.events.peek(Inbox.UNCHARGE) == null ? null : intake.engine.events.peek(Inbox.UNCHARGE).variant));
    }

    @Test
    public void aNotedRecoilLoadCanonicalisesToTheRingOfRecoil()
    {
        // The live menu carries the noted id (owner recording 2026-10-12); the intake
        // canonicalises it before validation, so the load arms as the ring of recoil.
        Engine engine = engine();
        Widget ring = item(ItemID.ZENYTE_RING_ENCHANTED_RECOIL, 0);
        ChargeIntake intake = new ChargeIntake(selecting(item(2551, 2)), canonicalising(),
            new GpManagerConfig() {}, engine, null)
        {
            @Override
            String itemName(int itemId)
            {
                return itemId == ItemID.RING_OF_RECOIL ? "Ring of recoil" : null;
            }
        };
        intake.armLoad(click(MenuAction.WIDGET_TARGET_ON_WIDGET, "Use", ring), "");
        assertEquals(ChargeCheck.ChargedItem.SUFFERING,
            (engine.events.peek(Inbox.LOAD_TARGET) == null ? null : engine.events.peek(Inbox.LOAD_TARGET).variant));
        assertEquals("the noted id canonicalises to the ring of recoil",
            ItemID.RING_OF_RECOIL, engine.events.item(Inbox.LOAD_TARGET));
    }

    /** A lookup that canonicalises the noted recoil the way RuneLite's ItemManager does. */
    private static ItemLookup canonicalising()
    {
        return new ItemLookup(null)
        {
            @Override
            int canon(int id)
            {
                return id == 2551 ? ItemID.RING_OF_RECOIL : id;
            }
        };
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static com.gpmanager.EngineTestFixtures.mapOf;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ChargeLoadReviewLifecycleTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final String TARGET = "149:0:9764864:12934:BLOWPIPE";
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override public int stabilizationTicks() { return 2; }
        @Override public boolean keepTransferAuditRows() { return true; }
    };

    @Test
    public void measuredCheckConvertsLoadAndLaterUseBooksOneCost()
    {
        Engine engine = engine();
        long start = 10_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(12934, 100L));
        ChargeOutcomeTest.none(engine.observeCheck(blowpipe(0, 10), TARGET, start));

        engine.markChargeLoad(ChargeCheck.ChargedItem.BLOWPIPE,
            12934, "Zulrah's scales", TARGET, 8);
        engine.markDirty();
        Transaction load = settle(engine, snapshot(12934, 50L), start + 600L);
        assertEquals("a validated recharge is neutral on arrival", TransactionType.TRANSFER, load.original());
        assertFalse(load.counts());
        assertEquals("Charge load transfer", load.note());
        assertEquals(0L, engine.metrics(start + 2_400L).net);
        assertEquals(0L, engine.metrics(start + 2_400L).cost);

        assertEquals("the loaded scales are not use", ChargeDelta.CheckResult.SAME,
            engine.observeCheck(blowpipe(50, 10), TARGET, start + 3_000L).result);
        assertEquals(TransactionType.TRANSFER, load.original());
        assertEquals(0L, engine.metrics(start + 3_000L).net);

        ChargeDelta use = engine.observeCheck(
            blowpipe(48, 10), TARGET, start + 4_000L);
        assertNotNull(use);
        Transaction spend = engine.bookChargeSpend(
            use,
            "Toxic blowpipe",
            Collections.singletonList(new Flow(12934, "Zulrah's scales", -2L, 100,
                -200L, PriceSource.GRAND_EXCHANGE)),
            start + 4_000L, null);
        assertTrue(spend != null);
        assertEquals(-200L, spend.net());
        assertEquals(200L, engine.metrics(start + 4_000L).cost);
        assertEquals(-200L, engine.metrics(start + 4_000L).net);
    }

    /** Converting or trimming the Review row is a change like any other: the revision advances. */
    @Test
    public void measuredCheckConversionAdvancesTheRevision()
    {
        Engine engine = engine();
