    }

    private Engine startedWithBones(long quantity)
    {
        Engine engine = engine();
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(526, quantity));
        return engine;
    }

    private Engine engine()
    {
        return new Engine(valuator, new TransactionClassifier(), CONFIG);
    }

    private Engine alchemyEngine()
    {
        FlowValuator alchemy = deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> entry : deltas.entrySet())
            {
                int price = entry.getKey() == 995 ? 1 : 100;
                flows.add(new Flow(
                    entry.getKey(), "Item " + entry.getKey(), entry.getValue(), price,
                    entry.getValue() * price));
            }
            return flows;
        };
        return new Engine(alchemy, new TransactionClassifier(), CONFIG);
    }

    /** Valuator with potion dose names so open-intent dose matching can run offline. */
    private Engine namedEngine()
    {
        FlowValuator named = deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> entry : deltas.entrySet())
            {
                int id = entry.getKey();
                String name;
                int price;
                if (id == 2434)
                {
                    name = "Prayer potion(4)";
                    price = 200;
                }
                else if (id == 139)
                {
                    name = "Prayer potion(3)";
                    price = 100;
                }
                else if (id == 3012)
                {
                    name = "Energy potion(2)";
                    price = 120;
                }
                else if (id == 3014)
                {
                    name = "Energy potion(1)";
                    price = 60;
                }
                else if (id == 526)
                {
                    name = "Bones";
                    price = 31;
                }
                else if (id == 1942)
                {
                    name = "Potato";
                    price = 50;
                }
                else
                {
                    name = "Item " + id;
                    price = 100;
                }
                flows.add(new Flow(
                    id, name, entry.getValue(), price, entry.getValue() * price));
            }
            return flows;
        };
        return new Engine(named, new TransactionClassifier(), CONFIG);
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        assertNull(engine.processIfDirty(snapshot, firstTick, null));
        assertNull(engine.processIfDirty(snapshot, firstTick + 600L, null));
        return engine.processIfDirty(snapshot, firstTick + 1_200L, null);
    }

    private static ContainerSnapshot snapshot(int itemId, long quantity)
    {
        Map<Integer, Long> values = new HashMap<>();
        if (quantity > 0L)
        {
            values.put(itemId, quantity);
        }
        return new ContainerSnapshot(values);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/** Items held outside the inventory and worn slots still count (research 1.2). */
public class ContainerExtrasTest
{
    @Test
    public void dizanasQuiverAmmoCountsAsCarried() throws Exception
    {
        QuiverSupportTest.Harness harness = new QuiverSupportTest.Harness();
        harness.equipQuiver();
        harness.ammo = 250;
        assertEquals(250L, harness.capture().quantity(ItemID.DRAGON_ARROW));
    }

    @Test
    public void aCarriedAshSanctifierHoldsDeathRunesTenChargesEach()
    {
        ContainerSnapshot held = capture(Map.of(InventoryID.INV, items(ItemID.ASH_SANCTIFIER, 1, ItemID.DEATHRUNE, 40)), 125);
        assertEquals("40 loose runes and 125 charges = 12 more runes", 52L, held.quantity(ItemID.DEATHRUNE));
        ContainerSnapshot banked = capture(Map.of(InventoryID.INV, items(ItemID.DEATHRUNE, 40)), 125);
        assertEquals("a banked sanctifier's charges are not carried", 40L, banked.quantity(ItemID.DEATHRUNE));
    }

    private static Item[] items(int... idQuantity)
    {
        Item[] items = new Item[idQuantity.length / 2];
        for (int i = 0; i < items.length; i++)
        {
            items[i] = new Item(idQuantity[2 * i], idQuantity[2 * i + 1]);
        }
        return items;
    }

    private static ContainerSnapshot capture(Map<Integer, Item[]> containers, int sanctifierCharges)
    {
        Map<Integer, ItemContainer> byId = new HashMap<>();
        containers.forEach((id, items) -> byId.put(id, (ItemContainer) Proxy.newProxyInstance(
            ItemContainer.class.getClassLoader(), new Class<?>[]{ItemContainer.class},
            (proxy, method, args) -> "getItems".equals(method.getName()) ? items : null)));
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, args) -> {
                if ("getItemContainer".equals(method.getName()))
                {
                    return byId.get((int) args[0]);
                }
                if ("getVarbitValue".equals(method.getName()))
                {
                    return (int) args[0] == VarbitID.CHARGES_ASH_SANCTIFIER_QUANTITY ? sanctifierCharges : 0;
                }
                return null;
            });
        return new ContainerSnapshotFactory(client, null).capture(true, false);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Rune pouch runes are account state in live varbits, not an item container. Merging
 * them into the ownership baseline makes filling the pouch neutral and casting from it
 * a visible cost. Looting bag / seed box are not merged: the client only syncs those
 * containers when the bag is opened.
 */
public class ContainerSnapshotFactoryRunePouchTest
{
    private static final int FIRE_RUNE = 554;
    private static final int CHAOS_RUNE = 562;

    @Test
    public void pouchRunesJoinInventoryQuantitiesWhenEnabled()
    {
        Map<Integer, Integer> varbits = new HashMap<>();
        varbits.put(VarbitID.RUNE_POUCH_TYPE_1, 4); // enum index -> Fire rune
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 1_500);
        varbits.put(VarbitID.RUNE_POUCH_TYPE_2, 10); // -> Chaos rune
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_2, 40);
        varbits.put(VarbitID.RUNE_POUCH_TYPE_3, 0); // empty slot
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_3, 99);
        Map<Integer, Integer> runeEnum = new HashMap<>();
        runeEnum.put(4, FIRE_RUNE);
        runeEnum.put(10, CHAOS_RUNE);
        Client client = client(varbits, runeEnum, new Item(FIRE_RUNE, 20), new Item(995, 100));
        ContainerSnapshotFactory factory = new ContainerSnapshotFactory(client, null);

        ContainerSnapshot with = factory.capture(false, true);
        ContainerSnapshot without = factory.capture(false, false);

        assertEquals(1_520L, with.quantity(FIRE_RUNE));
        assertEquals(40L, with.quantity(CHAOS_RUNE));
        assertEquals(100L, with.quantity(995));
        assertEquals(20L, without.quantity(FIRE_RUNE));
        assertEquals(0L, without.quantity(CHAOS_RUNE));
        // Empty slot with a stale quantity contributes nothing.
        assertEquals(3, with.diff(new ContainerSnapshot(new HashMap<>())).size());
    }

    @Test
    public void emptyRunePouchDoesNotReportHiddenContents()
    {
        Map<Integer, Integer> varbits = new HashMap<>();
        varbits.put(VarbitID.RUNE_POUCH_TYPE_1, 4);
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 0);
        ContainerSnapshotFactory factory = new ContainerSnapshotFactory(
            client(varbits, new HashMap<>(), new Item(995, 7)), null);

        assertEquals(0L, factory.capture(false, true).quantity(FIRE_RUNE));
    }

    @Test
    public void castingFromThePouchIsAVisibleCostAndFillingIsNeutral()
    {
        Map<Integer, Integer> varbits = new HashMap<>();
        varbits.put(VarbitID.RUNE_POUCH_TYPE_1, 4);
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 100);
        Map<Integer, Integer> runeEnum = new HashMap<>();
        runeEnum.put(4, FIRE_RUNE);
        ContainerSnapshot before = new ContainerSnapshotFactory(
            client(varbits, runeEnum, new Item(FIRE_RUNE, 50)), null).capture(false, true);

        // Fill: 50 runes move from the inventory into the pouch.
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 150);
        ContainerSnapshot filled = new ContainerSnapshotFactory(client(varbits, runeEnum), null)
            .capture(false, true);
        assertTrue("fill nets to zero", filled.diff(before).isEmpty());

        // Cast: five runes leave the pouch with no inventory change at all.
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 145);
        ContainerSnapshot cast = new ContainerSnapshotFactory(client(varbits, runeEnum), null)
            .capture(false, true);
        assertEquals(Long.valueOf(-5L), cast.diff(filled).get(FIRE_RUNE));
    }

    @Test
    public void onlyPouchVarbitsAreRecognised()
    {
        assertTrue(ContainerSnapshotFactory.isPouchVarbit(VarbitID.RUNE_POUCH_TYPE_1));
        assertTrue(ContainerSnapshotFactory.isPouchVarbit(VarbitID.RUNE_POUCH_QUANTITY_6));
        assertFalse(ContainerSnapshotFactory.isPouchVarbit(VarbitID.LOOTINGBAG_USEALLITEMS));
        assertFalse(ContainerSnapshotFactory.isPouchVarbit(-1));
    }

    @Test
    public void missingEnumNeverBreaksTheSnapshot()
    {
        Map<Integer, Integer> varbits = new HashMap<>();
        varbits.put(VarbitID.RUNE_POUCH_TYPE_1, 4);
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 100);
        ContainerSnapshot snapshot = new ContainerSnapshotFactory(
            client(varbits, null, new Item(995, 7)), null).capture(false, true);
        assertEquals(7L, snapshot.quantity(995));
        assertNull(snapshot.diff(new ContainerSnapshot(new HashMap<>())).get(FIRE_RUNE));
    }

    @Test
    public void deathHeldSnapshotReadsInventoryAndEquipmentButNeverRunePouchVarbits()
    {
        Map<Integer, Integer> varbits = new HashMap<>();
        varbits.put(VarbitID.RUNE_POUCH_TYPE_1, 4);
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 900);
        ItemContainer inventory = proxy(ItemContainer.class, (name, args) ->
            "getItems".equals(name) ? new Item[] {new Item(FIRE_RUNE, 20), new Item(995, 50)} : null);
        ItemContainer worn = proxy(ItemContainer.class, (name, args) ->
            "getItems".equals(name) ? new Item[] {new Item(4151, 1)} : null);
        Client client = proxy(Client.class, (name, args) ->
        {
            if ("getItemContainer".equals(name) && args != null && args.length == 1)
            {
                int id = (Integer) args[0];
                return id == InventoryID.INV ? inventory : id == InventoryID.WORN ? worn : null;
            }
            if ("getVarbitValue".equals(name))
            {
                return varbits.getOrDefault((Integer) args[0], 0);
            }
            return null;
        });
        ContainerSnapshotFactory factory = new ContainerSnapshotFactory(client, null);

        ContainerSnapshot withEquipment = factory.captureDeathHeld();

        assertEquals(20L, withEquipment.quantity(FIRE_RUNE));
        assertEquals(50L, withEquipment.quantity(995));
        assertEquals(1L, withEquipment.quantity(4151));
        assertEquals(0L, withEquipment.quantity(CHAOS_RUNE));
    }

    private static Client client(Map<Integer, Integer> varbits, Map<Integer, Integer> runeEnum, Item... inventory)
    {
        ItemContainer inv = proxy(ItemContainer.class, (name, args) ->
            "getItems".equals(name) ? inventory : null);
        EnumComposition composition = runeEnum == null ? null : proxy(EnumComposition.class, (name, args) ->
            "getIntValue".equals(name) ? runeEnum.getOrDefault((Integer) args[0], -1) : null);
        return proxy(Client.class, (name, args) ->
        {
            if ("getItemContainer".equals(name) && args != null && args.length == 1 && args[0] instanceof Integer)
            {
                return (Integer) args[0] == InventoryID.INV ? inv : null;
            }
            if ("getVarbitValue".equals(name))
            {
                return varbits.getOrDefault((Integer) args[0], 0);
            }
            if ("getEnum".equals(name))
            {
                return (Integer) args[0] == EnumID.RUNEPOUCH_RUNE ? composition : null;
            }
            return null;
        });
    }

    private interface Answer
    {
        Object answer(String method, Object[] args);
    }

    private static <T> T proxy(Class<T> type, Answer answer)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type}, (obj, method, args) ->
        {
            Object value = answer.answer(method.getName(), args);
            if (value != null || !method.getReturnType().isPrimitive())
            {
                return value;
            }
            if (method.getReturnType() == boolean.class)
            {
                return false;
            }
            if (method.getReturnType() == long.class)
            {
                return 0L;
            }
            return 0;
        }));
    }
}

package com.gpmanager;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class ContainerSnapshotTest
{
    @Test
    public void computesItemByItemDeltas()
    {
        Map<Integer, Long> beforeValues = new HashMap<>();
        beforeValues.put(995, 1_000L);
        beforeValues.put(385, 2L);

        Map<Integer, Long> afterValues = new HashMap<>();
        afterValues.put(995, 750L);
        afterValues.put(385, 1L);
        afterValues.put(561, 10L);

        Map<Integer, Long> diff =
            new ContainerSnapshot(afterValues).diff(new ContainerSnapshot(beforeValues));

        assertEquals(Long.valueOf(-250L), diff.get(995));
        assertEquals(Long.valueOf(-1L), diff.get(385));
        assertEquals(Long.valueOf(10L), diff.get(561));
        assertEquals(3, diff.size());
        assertEquals(new ContainerSnapshot(afterValues), new ContainerSnapshot(afterValues));
        assertNotEquals(new ContainerSnapshot(afterValues), new ContainerSnapshot(beforeValues));
    }
}

