        assertFalse(zulrah.ambiguous);
        assertEquals(60_000L, BossRetrievalCatalogue.serviceFor("Claim", "Shura").fee);
        assertEquals(50_000L, BossRetrievalCatalogue.serviceFor("Search", "Magical chest").fee);
