}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Taking an item apart is neutral; a crystal tool's 120 shards are the only cost (owner 1.2). */
public class DismantleNeutralTest
{
    private static final Map<Integer, String> NAMES = Map.of(ItemID.CRYSTAL_HARPOON, "Crystal harpoon",
        ItemID.DRAGON_HARPOON, "Dragon harpoon", ItemID.PRIF_TOOL_SEED, "Crystal tool seed",
        ItemID.PRIF_CRYSTAL_SHARD, "Crystal shard", ItemID.AGS, "Armadyl godsword",
        ItemID.GODWARS_GODSWORD_BLADE1_2_3, "Godsword blade", ItemID.GODWARS_GODSWORD_HILT_ARMADYL, "Armadyl hilt",
        ItemID.WILD_CAVE_BRACELET_UNCHARGED, "Bracelet of ethereum (uncharged)",
        ItemID.WILD_CAVE_SHARD, "Revenant ether");
    private static final Map<Integer, Integer> PRICES = Map.of(ItemID.CRYSTAL_HARPOON, 0,
        ItemID.DRAGON_HARPOON, 3_000_000, ItemID.PRIF_TOOL_SEED, 1_000_000, ItemID.PRIF_CRYSTAL_SHARD, 2_000,
        ItemID.AGS, 12_000_000, ItemID.GODWARS_GODSWORD_BLADE1_2_3, 1_000_000, ItemID.GODWARS_GODSWORD_HILT_ARMADYL, 10_500_000,
        ItemID.WILD_CAVE_BRACELET_UNCHARGED, 40_000, ItemID.WILD_CAVE_SHARD, 250);

    private static Engine settle(int clicked, Map<Integer, Long> before, Map<Integer, Long> after)
    {
        return settle(clicked, before, after, new GpManagerConfig()
        {
        });
    }

    private static Engine settle(int clicked, Map<Integer, Long> before, Map<Integer, Long> after, GpManagerConfig config)
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, NAMES.get(id), quantity, PRICES.get(id),
                quantity * PRICES.get(id))));
            return flows;
        }, new TransactionClassifier(), config);
        engine.ensureSession(1_000_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(before)));
        engine.markDirty();
        if (clicked > 0)
        {
            engine.dismantle(clicked);
        }
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)), 1_000_000L + tick * 600L, null);
        }
        return engine;
    }

    private static final Map<Integer, Long> HARPOON = Map.of(ItemID.CRYSTAL_HARPOON, 1L);
    private static final Map<Integer, Long> PARTS = Map.of(ItemID.DRAGON_HARPOON, 1L, ItemID.PRIF_TOOL_SEED, 1L);

    @Test
    public void revertingACrystalToolCostsOnlyItsShards()
    {
        Engine engine = settle(ItemID.CRYSTAL_HARPOON, HARPOON, PARTS);
        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        Transaction shards = rows.get(0);
        assertEquals(TransactionType.CONSUMPTION, shards.original());
        assertEquals("Dismantled Crystal harpoon", shards.note());
        assertEquals(ItemID.PRIF_CRYSTAL_SHARD, shards.flows().get(0).item);
        assertEquals(-120L, shards.flows().get(0).quantity);
        assertEquals(-240_000L, engine.metrics(1_010_000L).net);
    }

    @Test
    public void withoutTheClickTheSameChangeStillNeedsReview()
    {
        Engine engine = settle(-1, HARPOON, PARTS);
        assertTrue(engine.session().transactions().stream().anyMatch(row -> row.original() == TransactionType.UNCERTAIN));
    }

    @Test
    public void dismantlingAGodswordBooksNothing()
    {
        Engine engine = settle(ItemID.AGS, Map.of(ItemID.AGS, 1L), Map.of(ItemID.GODWARS_GODSWORD_BLADE1_2_3, 1L, ItemID.GODWARS_GODSWORD_HILT_ARMADYL, 1L));
        assertTrue(engine.session().transactions().toString(),
            engine.session().transactions().isEmpty());
        assertEquals(0L, engine.metrics(1_010_000L).net);
    }

    @Test
    public void dismantlingABraceletOfEthereumIsNotNeutral()
    {
        // The parts (250 ether) are worth more than the item: the neutral parts rule would bury
        // the gain, so it settles like the same change without the click (Muse review 2026-10-12).
        Engine engine = settle(ItemID.WILD_CAVE_BRACELET_UNCHARGED,
            Map.of(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L), Map.of(ItemID.WILD_CAVE_SHARD, 250L));
        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertEquals(TransactionType.UNCERTAIN, rows.get(0).original());
        assertFalse(rows.get(0).counts());
        assertTrue(ReviewRules.needsReview(rows.get(0)));
        assertEquals(0L, engine.metrics(1_010_000L).net);
    }

    @Test
    public void aCountedUncertainSettingBooksTheBraceletConversion()
    {
        Engine engine = settle(ItemID.WILD_CAVE_BRACELET_UNCHARGED,
            Map.of(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L), Map.of(ItemID.WILD_CAVE_SHARD, 250L),
            new GpManagerConfig()
            {
                @Override public boolean countUncertainMixedChanges()
                {
                    return true;
                }
            });
        assertEquals(250L * 250L - 40_000L, engine.metrics(1_010_000L).net);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Owner 1.3.4: a dose variant RuneLite cannot quote is priced from its family's full quote at the
 * same rate per dose (the GP-Per-Hour fractional model), so a burning-amulet teleport books a
 * fifth of the amulet instead of the full price or an unknown row.
 */
public class DoseFamilyValueTest
{
    private static final int BURNING_5 = 21166;
    private static final int BURNING_4 = 21169;
    private static final int BURNING_3 = 21171;
    private static final int BURNING_2 = 21173;
    private static final int BURNING_1 = 21175;

    private static final Map<Integer, String> NAMES = Map.of(
        BURNING_5, "Burning amulet(5)",
        BURNING_4, "Burning amulet(4)",
        BURNING_3, "Burning amulet(3)",
        BURNING_2, "Burning amulet(2)",
        BURNING_1, "Burning amulet(1)");

    @Test
    public void aPartialDoseIsPricedFromItsFamilyFullQuote()
    {
        Valuation service = service(new GpManagerConfig() { }, Map.of(BURNING_5, 2_231));

        assertEquals("the full amulet keeps its own quote", 2_231, one(service, BURNING_5).unitPrice);
        assertEquals(1_784, one(service, BURNING_4).unitPrice);
        assertEquals(1_338, one(service, BURNING_3).unitPrice);
        assertEquals(892, one(service, BURNING_2).unitPrice);
        assertEquals(446, one(service, BURNING_1).unitPrice);
        assertEquals(PriceSource.GRAND_EXCHANGE, one(service, BURNING_4).source());

        Map<Integer, Long> swap = new HashMap<>();
        swap.put(BURNING_3, -1L);
        swap.put(BURNING_2, 1L);
        long net = 0L;
        for (Flow flow : service.value(swap, 1_000L)) net += flow.value;
        assertEquals("one teleport is a fifth of the amulet", -446L, net);
    }

    @Test
    public void aManualOverrideAnywhereInTheFamilyIsAuthoritative()
    {
        GpManagerConfig full = new GpManagerConfig()
        {
            @Override
            public String manualPriceOverrides()
            {
                return "21166=2500";
            }
        };
        Valuation fromFull = service(full, Map.of());
        assertEquals(2_000, one(fromFull, BURNING_4).unitPrice);
        assertEquals(PriceSource.MANUAL_OVERRIDE, one(fromFull, BURNING_4).source());

        GpManagerConfig oneDose = new GpManagerConfig()
        {
            @Override
            public String manualPriceOverrides()
            {
                return "21175=500";
            }
        };
        Valuation fromOne = service(oneDose, Map.of(BURNING_5, 2_231));
        assertEquals("an override outranks the family quote", 2_000,
            one(fromOne, BURNING_4).unitPrice);
        assertEquals(PriceSource.MANUAL_OVERRIDE, one(fromOne, BURNING_4).source());
    }

    @Test
    public void withoutAnyFamilyQuoteNothingIsInvented()
    {
        Valuation service = service(new GpManagerConfig() { }, Map.of());
        assertEquals(0, one(service, BURNING_4).unitPrice);
        assertEquals(PriceSource.UNPRICED, one(service, BURNING_4).source());
        assertEquals(PriceSource.UNPRICED, one(service, 999_999).source());
    }

    static Valuation service(GpManagerConfig config, Map<Integer, Integer> prices)
    {
        return ModelProbe.valuation(config,
            id -> composition(NAMES.getOrDefault(id, "Item " + id)),
            id -> prices.getOrDefault(id, 0));
    }

    private static ItemComposition composition(String name)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) ->
            {
                if ("getName".equals(method.getName())) return name;
                // Potions and amulets trade on the Grand Exchange.
                if (method.getReturnType() == boolean.class) return "isTradeable".equals(method.getName());
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
    }

    private static Flow one(Valuation service, int itemId)
    {
        List<Flow> flows = service.value(Map.of(itemId, 1L), 1_000L);
        assertNotNull(flows);
        return flows.stream().filter(flow -> flow.item == itemId).findFirst().orElseThrow();
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import org.junit.Test;
import org.junit.Before;
import org.junit.After;

import static org.junit.Assert.assertEquals;

/**
 * Owner 1.7.0: a real drop followed quickly by opening a bank must stay the player's own drop, so
 * picking the items back up is neutral; a genuine deposit stays a neutral bank transfer. Every item
 * is quoted at 10 GP; the account starts with 3 counted logs (30 GP of known basis).
 */
public class DropBankBoundaryTest
{
    private static final int LOGS = 1511, AIR = 556;
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override public int stabilizationTicks() { return 2; }
        @Override public boolean keepTransferAuditRows() { return true; }
    };

    private long now = 1_000;
    private java.util.function.LongSupplier previousClock;
    @Before public void fixedClock() {
        previousClock = SafeMath.clock;
        SafeMath.clock = () -> now;
    }
    @After public void restoreClock() { SafeMath.clock = previousClock; }

    private Engine engine(long logs, long air)
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, id == LOGS ? "Logs" : "Air rune", quantity,
                10, quantity * 10, PriceSource.GRAND_EXCHANGE)));
            return flows;
        }, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000);
        engine.setBaseline(held(logs, air));
        engine.session().addTransaction(Tx.of(1_000, TransactionType.GAIN, Context.GENERIC, "Initial loot", true,
            List.of(new Flow(LOGS, "Logs", logs, 10, logs * 10, PriceSource.GRAND_EXCHANGE))), 2_000, false);
        assertEquals(logs * 10, engine.metrics(now).net);
        assertEquals(logs, EngineProbe.availableQty(engine, LOGS));
        return engine;
    }

    private static ContainerSnapshot held(long logs, long air)
    {
        Map<Integer, Long> items = new HashMap<>();
        if (logs > 0) items.put(LOGS, logs);
        if (air > 0) items.put(AIR, air);
        return new ContainerSnapshot(items);
    }

    private void tick(Engine e, ContainerSnapshot inventory)
    {
        e.processIfDirty(inventory, now += 600, null);
    }

    private long bankLogs, bankAir;
    private boolean synced;

    /** The BANK callback: the plugin passes the bank's own counts. */
    private void bank(Engine e, long logs, long air)
    {
        bankLogs = logs;
        bankAir = air;
        synced = true;
        Map<Integer, Long> counts = new HashMap<>();
        if (logs > 0) counts.put(LOGS, logs);
        if (air > 0) counts.put(AIR, air);
        e.bankContents(counts, now, ignored -> {});
    }

    private void closeBank(Engine e)
    {
        synced = false;
        e.bankClosed();
    }

    private void bankTicks(Engine e, ContainerSnapshot inventory, int ticks)
    {
        for (int i = 0; i < ticks; i++)
        {
            // The BANK callback fires once when the bank opens, then only when its contents change.
            if (!synced) bank(e, bankLogs, bankAir);
            e.bankOpened(6);
            tick(e, inventory);
        }
    }

    private void closeAndPickUp(Engine e, ContainerSnapshot inventory)
    {
        closeBank(e);
        for (int i = 0; i < 4; i++) tick(e, held(0, 0));
        e.markDirty();
        for (int i = 0; i < 4; i++) tick(e, inventory);
    }

    private static Object zero(Class<?> type)
    {
        if (type == boolean.class) return false;
        if (type == int.class) return 0;
        if (type == long.class) return 0L;
        return null;
    }

    private static long count(Engine e, String note)
    {
        return e.session().transactions().stream().filter(t -> note.equals(t.note())).count();
    }

    private static Transaction dropped(Engine e)
    {
        return e.session().transactions().stream().filter(t -> "Dropped".equals(t.note())).findFirst().orElse(null);
    }

    /** Drop 3 logs, then the bank opens in one of the observed callback orders. */
    private Engine dropThenBank(boolean sampledBeforeBank, boolean bankContainerFirst)
    {
        Engine e = engine(3, 0);
        e.noteDrop(LOGS, 6);
        e.markDirty();
        if (sampledBeforeBank) tick(e, held(0, 0));
        if (bankContainerFirst) bank(e, bankLogs, bankAir);
        bankTicks(e, held(0, 0), 4);
        return e;
    }

    private void assertOwnDropRecovered(Engine e)
    {
        assertEquals("the drop books once at its captured value", 1, count(e, "Dropped"));
        assertEquals(-30, dropped(e).net());
        assertEquals(10, dropped(e).flows().get(0).unitPrice);
        assertEquals(0, e.metrics(now).net);
        closeAndPickUp(e, held(3, 0));
        assertEquals(1, count(e, "Picked back up"));
        assertEquals("own pickup restores the original Net", 30, e.metrics(now).net);
        assertEquals("no fresh income", 30, e.metrics(now).income);
        assertEquals(0, e.metrics(now).cost);
        assertEquals(3, EngineProbe.availableQty(e, LOGS));
        assertEquals(30, EngineProbe.availableBasisGp(e, LOGS));
    }

    @Test public void dropThenBankBeforeTheFirstSample() { assertOwnDropRecovered(dropThenBank(false, false)); }

    @Test public void dropAlreadyPendingWhenTheBankOpens() { assertOwnDropRecovered(dropThenBank(true, false)); }

    @Test public void bankContainerSyncWhileTheSampledDropIsPending() { assertOwnDropRecovered(dropThenBank(true, true)); }

    @Test public void bankContainerSyncBeforeTheFirstSample() { assertOwnDropRecovered(dropThenBank(false, true)); }

    @Test public void partialRecoveryDepletesOnlyTheItemsLeftOnTheGround()
    {
        Engine e = dropThenBank(true, true);
        closeAndPickUp(e, held(1, 0));
        assertEquals(-20, dropped(e).net());
        for (int i = 0; i < 300; i++) tick(e, held(1, 0));
        assertEquals(10, e.metrics(now).net);
        assertEquals(30, e.metrics(now).income);
        assertEquals(20, e.metrics(now).cost);
        assertEquals(1, EngineProbe.availableQty(e, LOGS));
        assertEquals(10, EngineProbe.availableBasisGp(e, LOGS));
    }

    @Test public void excessPickupCountsOnlyTheGenuinelyNewLogs()
    {
        Engine e = dropThenBank(false, true);
        closeAndPickUp(e, held(5, 0));
        assertEquals(1, count(e, "Picked back up"));
        assertEquals(50, e.metrics(now).net);
        assertEquals(50, e.metrics(now).income);
        assertEquals(0, e.metrics(now).cost);
        assertEquals(5, EngineProbe.availableQty(e, LOGS));
        assertEquals(50, EngineProbe.availableBasisGp(e, LOGS));
    }

    @Test public void aSettledDropStillReconcilesAfterBanking()
    {
        Engine e = engine(3, 0);
        e.noteDrop(LOGS, 6);
        e.markDirty();
        for (int i = 0; i < 4; i++) tick(e, held(0, 0));
        assertEquals(1, count(e, "Dropped"));
        bank(e, bankLogs, bankAir);
        bankTicks(e, held(0, 0), 4);
        closeAndPickUp(e, held(3, 0));
        assertEquals(30, e.metrics(now).net);
        assertEquals(30, e.metrics(now).income);
        assertEquals(3, EngineProbe.availableQty(e, LOGS));
    }

    @Test public void staleDropClickThenRealDepositAndWithdrawalStayNeutral()
    {
        for (boolean containerFirst : new boolean[] {false, true})
        {
            Engine e = engine(3, 0);
            e.noteDrop(LOGS, 6);
            if (containerFirst) bank(e, 0, 0);
            bankTicks(e, held(3, 0), 1);
            bank(e, 3, 0);
            e.markDirty();
            bankTicks(e, held(0, 0), 4);
            assertEquals(0, count(e, "Dropped"));
            assertEquals(30, e.metrics(now).net);
            bank(e, 0, 0);
            e.markDirty();
            bankTicks(e, held(3, 0), 4);
            closeBank(e);
            assertEquals(30, e.metrics(now).net);
            assertEquals(30, e.metrics(now).income);
            assertEquals(0, e.metrics(now).cost);
            assertEquals(3, EngineProbe.availableQty(e, LOGS));
            assertEquals(30, EngineProbe.availableBasisGp(e, LOGS));
        }
    }

    @Test public void staleDropClickWithAnUnrelatedInventoryCallbackThenDepositStaysNeutral()
    {
        Engine e = engine(3, 0);
        e.noteDrop(LOGS, 6);
        e.markDirty(); // something else touched the inventory; the logs never left
        bankTicks(e, held(3, 0), 1);
        bank(e, 3, 0);
        e.markDirty();
        bankTicks(e, held(0, 0), 4);
        closeBank(e);
        assertEquals(0, count(e, "Dropped"));
        assertEquals(30, e.metrics(now).net);
        assertEquals(0, e.metrics(now).cost);
        assertEquals(3, EngineProbe.availableQty(e, LOGS));
    }

    @Test public void depositedLogsAfterTheDropAreNeverAttributedToIt()
    {
        Engine e = engine(5, 4);
        e.noteDrop(LOGS, 6);
        e.markDirty();
        tick(e, held(2, 4));
        bank(e, 0, 0);
        bankTicks(e, held(2, 4), 1);
        bank(e, 2, 4);
        e.markDirty();
        bankTicks(e, held(0, 0), 4);
        assertEquals(1, count(e, "Dropped"));
        assertEquals("only the 3 dropped logs", -3, dropped(e).flows().get(0).quantity);
        assertEquals(50 - 30, e.metrics(now).net);
        closeAndPickUp(e, held(3, 0));
        assertEquals(50, e.metrics(now).net);
        assertEquals(50, e.metrics(now).income);
        assertEquals(0, e.metrics(now).cost);
        assertEquals("3 recovered plus 2 banked", 5, EngineProbe.availableQty(e, LOGS));
        assertEquals(50, EngineProbe.availableBasisGp(e, LOGS));
    }

    @Test public void aWithdrawalAfterThePendingDropStaysNeutral()
    {
        Engine e = engine(3, 0);
        e.noteDrop(LOGS, 6);
        e.markDirty();
        tick(e, held(0, 0));
        bankAir = 4;
        bankTicks(e, held(0, 0), 1);
        bank(e, 0, 0);
        e.markDirty();
        bankTicks(e, held(0, 4), 4);
        closeBank(e);
        assertEquals(1, count(e, "Dropped"));
        assertEquals(-30, dropped(e).net());
        assertEquals("the withdrawn runes book nothing", 0, e.metrics(now).net);
        assertEquals(0, EngineProbe.availableQty(e, AIR));
        for (int i = 0; i < 4; i++) tick(e, held(0, 4));
        e.markDirty();
        for (int i = 0; i < 4; i++) tick(e, held(3, 4));
        assertEquals(30, e.metrics(now).net);
        assertEquals(30, e.metrics(now).income);
        assertEquals(3, EngineProbe.availableQty(e, LOGS));
    }

    @Test public void aDropMixedWithAnotherChangeBeforeTheBankKeepsOnlyItsOwnItem()
    {
        Engine e = engine(3, 0);
        e.noteDrop(LOGS, 6);
