package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.4: a confirmed drop owns its item when a harvest lands in the same change (the live
 * calquat shape: Empty plant pot x-11 with a Calquat fruit gain). The drop books as its own
 * Dropped row and the sibling gain separately, with no Review; guard shapes cancel the split.
 */
public class DropMixedSettleTest
{
    private static final int CALQUAT_FRUIT = 5980;
    private static final int EMPTY_PLANT_POT = 5350;
    private static final int SHARK = 385;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) ->
            flows.add(new Flow(id, name(id), quantity, unit(id), quantity * unit(id))));
        return flows;
    };

    private static String name(int id)
    {
        switch (id)
        {
            case CALQUAT_FRUIT: return "Calquat fruit";
            case EMPTY_PLANT_POT: return "Empty plant pot";
            case SHARK: return "Shark";
            default: return "Item " + id;
        }
    }

    private static int unit(int id)
    {
        switch (id)
        {
            case CALQUAT_FRUIT: return 600;
            case SHARK: return 1_000;
            default: return 1;
        }
    }

    @Test
    public void aDropKeepsItsOwnItemWhenAHarvestLands()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L)), 1_600L);

        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 2, rows.size());
        Transaction drop = rows.get(0);
        assertEquals(TransactionType.CONSUMPTION, drop.type());
        assertEquals("Dropped", drop.note());
        assertTrue(drop.counts());
        assertEquals(11L, drop.quantity(EMPTY_PLANT_POT, false));
        Transaction harvest = rows.get(1);
        assertEquals(TransactionType.GAIN, harvest.type());
        assertEquals(1L, harvest.quantity(CALQUAT_FRUIT, true));
        assertEquals("no Review", 0, engine.getReviewRows(10_000L).size());
        Metrics metrics = engine.metrics(10_000L);
        assertEquals(11L, metrics.cost);
        assertEquals(600L, metrics.income);
    }

    @Test
    public void pickingPartOfTheSplitDropBackUpShrinksIt()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L)), 1_600L);

        engine.markDirty();
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L, EMPTY_PLANT_POT, 5L)), 4_000L);

        assertEquals("the pickup books no new row", 2, engine.session().transactions().size());
        Metrics metrics = engine.metrics(10_000L);
        assertEquals("6 pots stay on the ground", 6L, metrics.cost);
        assertEquals(600L, metrics.income);
    }

    @Test
    public void aSecondLossCancelsTheSplit()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L, SHARK, 2L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L, SHARK, 1L)), 1_600L);

        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertFalse("Dropped", "Dropped".equals(rows.get(0).note()));
        assertEquals(TransactionType.UNCERTAIN, rows.get(0).type());
        assertEquals(1, engine.getReviewRows(10_000L).size());
    }

    @Test
    public void aConsumeIntentCancelsTheSplit()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L, SHARK, 2L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        engine.noteConsume(SHARK, 6, false, null, null);
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L, SHARK, 1L)), 1_600L);

        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertFalse("Dropped", "Dropped".equals(rows.get(0).note()));
        assertEquals(TransactionType.CONSUMPTION, rows.get(0).type());
    }

    @Test
    public void aPkLootContextCancelsTheSplit()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        engine.markContext(Context.PK_LOOT, 6, "PKing");
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L)), 1_600L);

        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertFalse("Dropped", "Dropped".equals(rows.get(0).note()));
    }

    private Engine engine(Map<Integer, Long> baseline)
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(baseline)));
        return engine;
    }

    private static ContainerSnapshot held(Map<Integer, Long> quantities)
    {
        return new ContainerSnapshot(new HashMap<>(quantities));
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        assertNull(engine.processIfDirty(snapshot, firstTick, null));
        assertNull(engine.processIfDirty(snapshot, firstTick + 600L, null));
        Transaction tx = engine.processIfDirty(snapshot, firstTick + 1_200L, null);
        assertNotNull(tx);
        return tx;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Owner 1.3.3: a drop picked back up shrinks the Dropped row instead of adding a matching gain. */
public class DropPickupTest
{
    private static final int BOLTS = 9140;
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Iron bolts", quantity, 10, quantity * 10)));
        return flows;
    };

    private Engine dropped(long bolts)
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(new ContainerSnapshot(Collections.singletonMap(BOLTS, 3L)));
        engine.noteDrop(BOLTS, 6);
        Transaction drop = settle(engine, snapshot(3L - bolts), 1_600L);
        assertEquals("Dropped", drop.note());
        return engine;
    }

    @Test
    public void pickingAllOfADropBackUpLeavesNeitherRow()
    {
        Engine engine = dropped(3L);
        assertEquals(-30L, engine.metrics(3_000L).net);
        settle(engine, snapshot(3L), 4_000L);
        assertEquals("Net is back where it started", 0L, engine.metrics(6_000L).net);
        List<Transaction> rows = engine.session().transactions();
        assertEquals("only the Dropped row is kept, excluded", 1, rows.size());
        assertEquals(Correction.IGNORE, rows.get(0).correction());
        assertFalse(rows.get(0).counts());
    }

    @Test
    public void pickingPartOfADropBackUpShrinksIt()
    {
        Engine engine = dropped(3L);
        settle(engine, snapshot(1L), 4_000L);
        Transaction drop = engine.session().transactions().get(0);
        assertTrue(drop.counts());
        assertEquals("2 bolts stay on the ground", -20L, engine.metrics(6_000L).net);
        assertEquals(1, engine.session().transactions().size());
    }

    @Test
    public void pickingUpMoreThanWasDroppedBooksOnlyTheExtra()
    {
        Engine engine = dropped(1L);
        Transaction extra = settle(engine, snapshot(5L), 4_000L);
        assertEquals(TransactionType.GAIN, extra.type());
        assertEquals("1 cancels the drop, 2 are new", 20L, extra.revenue());
        assertEquals(20L, engine.metrics(6_000L).net);
    }

    @Test
    public void pickingUpFiredBoltsShrinksTheShot()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(100L));
        Transaction fired = settle(engine, snapshot(60L), 1_600L);
        assertEquals(ActionKind.FIRE, fired.action());
        assertEquals(400L, engine.metrics(3_000L).cost);
        engine.markDirty();
        settle(engine, snapshot(90L), 4_000L);
        Metrics metrics = engine.metrics(6_000L);
        assertEquals("never income", 0L, metrics.income);
        assertEquals("10 bolts stayed on the ground", 100L, metrics.cost);
    }

    private static final int DART = 807;
    private static final int SCALES = 12934;

    /** A blowpipe shot estimated at one dart and one scale, 10 gp each. */
    private Engine blowpipeShot()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(FixtureReads.empty());
        Transaction shot = engine.bookEstimatedCharge("pipe", "Toxic blowpipe", ActionKind.CAST,
            Arrays.asList(new Flow(DART, "Iron dart", -1L, 10, -10L),
                new Flow(SCALES, "Zulrah's scales", -1L, 10, -10L)), 1_100L);
        assertEquals(20L, shot.costs());
        return engine;
    }

    @Test
    public void pickingUpABlowpipeDartKeepsTheShotsScaleCost()
    {
        Engine engine = blowpipeShot();
        engine.markDirty();
        settle(engine, new ContainerSnapshot(Collections.singletonMap(DART, 1L)), 2_000L);
        List<Transaction> rows = engine.session().transactions();
        assertEquals("no gain row for the dart", 1, rows.size());
        assertTrue(rows.get(0).counts());
        assertEquals(0L, rows.get(0).quantity(DART, false));
        Metrics metrics = engine.metrics(4_000L);
        assertEquals(0L, metrics.income);
        assertEquals("the scale is still spent", 10L, metrics.cost);
    }

    @Test
    public void aCheckAfterADartPickupNeverCountsTheDartAgain()
    {
        Engine engine = blowpipeShot();
        engine.markDirty();
        settle(engine, new ContainerSnapshot(Collections.singletonMap(DART, 1L)), 2_000L);
        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.BLOWPIPE,
            Arrays.asList(new ChargeDelta.ComponentDelta(DART, -1L),
                new ChargeDelta.ComponentDelta(SCALES, -1L)), ChargeDelta.CheckResult.SPEND);
        engine.bookChargeSpend(delta, "Toxic blowpipe",
            Arrays.asList(new Flow(DART, "Iron dart", -1L, 10, -10L),
                new Flow(SCALES, "Zulrah's scales", -1L, 10, -10L)), 5_000L, "pipe");
        assertEquals("measured 20 less the 10 picked up", 10L, engine.metrics(6_000L).cost);
    }

    @Test
    public void aDartTheCheckAlreadyTookBackIsAnOrdinaryGain()
    {
        Engine engine = blowpipeShot();
        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.BLOWPIPE,
            Collections.singletonList(new ChargeDelta.ComponentDelta(SCALES, -1L)), ChargeDelta.CheckResult.SPEND);
        engine.bookChargeSpend(delta, "Toxic blowpipe",
            Collections.singletonList(new Flow(SCALES, "Zulrah's scales", -1L, 10, -10L)), 1_500L, "pipe");
        engine.clearPendingEstimates("pipe", Collections.singleton(DART));
        Transaction shot = engine.session().transactions().get(0);
        assertEquals("the Check found no dart used", 0L, shot.quantity(DART, false));

        engine.markDirty();
        Transaction gain = settle(engine, new ContainerSnapshot(Collections.singletonMap(DART, 1L)), 2_000L);
        assertEquals(TransactionType.GAIN, gain.type());
        assertEquals(10L, gain.revenue());
        assertEquals(10L, engine.metrics(4_000L).cost);
    }

    @Test
    public void scalesPickedUpAreAnOrdinaryGain()
    {
        Engine engine = blowpipeShot();
        engine.markDirty();
        Transaction gain = settle(engine, new ContainerSnapshot(Collections.singletonMap(SCALES, 1L)), 2_000L);
        assertEquals(TransactionType.GAIN, gain.type());
        assertEquals(20L, engine.metrics(4_000L).cost);
    }

    private static ContainerSnapshot snapshot(long bolts)
    {
        return new ContainerSnapshot(Collections.singletonMap(BOLTS, bolts));
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        assertNull(engine.processIfDirty(snapshot, firstTick, null));
        assertNull(engine.processIfDirty(snapshot, firstTick + 600L, null));
        Transaction tx = engine.processIfDirty(snapshot, firstTick + 1_200L, null);
        assertNotNull(tx);
        return tx;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.3: setting up and picking up a dwarf multicannon is neutral; only the cannonballs it
 * fired count. Balls it did not fire come back on pick-up and shrink the load. Owner 1.3.4: the
 * balls it takes are Supplies on the ledger, and a change mixing a ball loss with a gain stays
 * Review rather than being stamped.
 */
public class DwarfCannonTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }

        @Override
        public boolean keepTransferAuditRows()
        {
            return true;
        }
    };

    private static final Map<Integer, String> NAMES = Map.of(
        ItemID.TWPART1, "Cannon base", ItemID.TWPART2, "Cannon stand",
        ItemID.TWPART3, "Cannon barrels", ItemID.TWPART4, "Cannon furnace",
        ItemID.MCANNONBALL, "Cannonball", ItemID.GRANITE_CANNONBALL, "Granite cannonball",
        ItemID.BRONZE_CANNONBALL, "Bronze cannonball",
        ItemID.DRAGON_CHAINSHOT_CANNONBALL, "Dragon chainshot cannonball",
        ItemID.COINS, "Coins");

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> {
            int unit = id == ItemID.MCANNONBALL ? 200
                : id == ItemID.GRANITE_CANNONBALL ? 350
                : id == ItemID.BRONZE_CANNONBALL ? 30
                : id == ItemID.DRAGON_CHAINSHOT_CANNONBALL ? 300
                : id == ItemID.COINS ? 1 : 150_000;
            flows.add(new Flow(id, NAMES.get(id), quantity, unit, quantity * unit));
        });
        return flows;
    };

    @Test
    public void onlyTheFiredBallsCount()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(true, 100L));

        engine.moveCannon();
        settle(engine, snapshot(false, 100L), 1_600L);
        assertEquals("setting it up is neutral", 0L, engine.metrics(5_000L).net);

        engine.loadCannon(6);
        Transaction load = settle(engine, snapshot(false, 70L), 6_000L);
        assertEquals("Loaded into the cannon", load.note());
        assertEquals(-6_000L, engine.metrics(10_000L).net);
        assertEquals("the balls are a supply, not an item loss", ActionKind.SUPPLIES,
            load.action());
        assertEquals(CostKind.SUPPLIES, CostKind.of(load, load.flows().get(0)));

        engine.moveCannon();
        settle(engine, snapshot(true, 80L), 12_000L);
        assertEquals("20 balls were fired; parts and 10 balls came back", -4_000L, engine.metrics(20_000L).net);
        assertEquals(0, engine.getReviewRows(20_000L).size());
    }

    @Test
    public void aBareCannonballLossIsSuppliesToo()
    {
        // The live shape: the load settled with no drop intent attached, so it booked as a plain
        // consumption; it is still the cannon's balls (owner 1.3.4).
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(true, 100L));

        Transaction loss = settle(engine, snapshot(true, 55L), 2_000L);
        assertEquals("", loss.note());
        assertEquals(ActionKind.SUPPLIES, loss.action());
        assertEquals(CostKind.SUPPLIES, CostKind.of(loss, loss.flows().get(0)));
    }

    @Test
    public void graniteCannonballsAreSupplies()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(held(ItemID.GRANITE_CANNONBALL, 30L));

        Transaction loss = settle(engine, held(ItemID.GRANITE_CANNONBALL, 10L), 2_000L);
        assertEquals(ActionKind.SUPPLIES, loss.action());
        assertEquals(CostKind.SUPPLIES, CostKind.of(loss, loss.flows().get(0)));
    }

    @Test
    public void aChangeMixingBallsWithAnotherGainIsNotStamped()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(held(ItemID.MCANNONBALL, 100L, ItemID.COINS, 10L));

        Transaction mixed = settle(
            engine, held(ItemID.MCANNONBALL, 95L, ItemID.COINS, 20L), 2_000L);
        assertEquals(TransactionType.UNCERTAIN, mixed.type());
        assertNull(mixed.action());
        assertEquals(1, engine.getReviewRows(9_000L).size());
    }

    @Test
    public void aSetUpAutoLoadAndUseLoadAreArmedAndOnlyFiredBallsBook()
    {
        // The live shape (owner 2026-10-13): Set-up auto-loads the balls it finds with the parts
        // and using a ball on the cannon loads too. Both must book on ground, so an Empty return
        // shrinks them instead of booking a gain, and only what never comes back books.
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(FixtureReads.empty());
        settle(engine, held(ItemID.MCANNONBALL, 90L), 2_000L);
        assertEquals(18_000L, engine.metrics(10_000L).net);

        engine.moveCannon();
        engine.loadCannon(6);
        Transaction setup = settle(engine, held(ItemID.MCANNONBALL, 45L), 20_000L);
        assertEquals("Loaded into the cannon", setup.note());
        assertTrue(setup.onGround());
        assertEquals("the 45 it took book and can come back", 18_000L - 9_000L,
            engine.metrics(50_000L).net);

        engine.loadCannon(6);
        settle(engine, held(ItemID.MCANNONBALL, 25L), 60_000L);
        assertEquals(9_000L - 4_000L, engine.metrics(90_000L).net);

        settle(engine, held(ItemID.MCANNONBALL, 60L), 100_000L);
        assertEquals("the 35 returned shrink the loads; no gain books", 1L,
            engine.session().transactions().stream()
                .filter(row -> row.counts() && row.type() == TransactionType.GAIN)
                .count());
        assertEquals("30 balls stayed out: 65 loaded, 35 back", 18_000L - 30L * 200L,
            engine.metrics(150_000L).net);
        assertEquals(0, engine.getReviewRows(150_000L).size());

        wait(engine, held(ItemID.MCANNONBALL, 60L), 2_150L, 200_000L);
        assertEquals("nothing more books after the windows", 18_000L - 30L * 200L,
            engine.metrics(10_000_000L).net);
        assertEquals(1L,
            engine.session().transactions().stream()
                .filter(row -> row.counts() && row.type() == TransactionType.GAIN)
                .count());
    }

    @Test
    public void aSlowSetUpKeepsTheFurnaceNeutralAndArmsItsAutoLoad()
    {
        // The live shape (owner 2026-10-13, second session): the last part settles about 15
        // ticks after the click together with the auto-load, right at the old 15-tick custody
        // edge. The furnace must stay neutral and the 45 balls must still be a load.
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(true, 90L));

        engine.moveCannon();
        engine.loadCannon(40);
        wait(engine, snapshot(true, 90L), 20L, 2_000L);
        Transaction load = settle(engine, snapshot(false, 45L), 20_000L);
        assertEquals("Loaded into the cannon", load.note());
        assertTrue(load.onGround());
        assertEquals("parts are neutral; only the loaded 45 book", -(45L * 200L),
            engine.metrics(90_000L).net);

        settle(engine, snapshot(false, 80L), 100_000L);
        assertEquals("the return shrinks the load", -(10L * 200L), engine.metrics(150_000L).net);
        assertEquals(0, engine.getReviewRows(150_000L).size());
    }

    @Test
    public void aLoadRightAfterALoginPrimeStillBooksAsALoad()
    {
        // The login priming clears the click intent; the parts custody must carry the load
        // evidence through it (owner live 2026-10-13, second session: the first set-up's
        // auto-load booked a full loss because the prime wiped its intent).
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(true, 90L));

        engine.moveCannon();
        engine.loadCannon(40);
        engine.resetTracking(true);
        engine.setBaseline(snapshot(true, 90L));
        engine.markDirty();

        Transaction load = settle(engine, snapshot(false, 45L), 20_000L);
        assertEquals("Loaded into the cannon", load.note());
        assertEquals(-(45L * 200L), engine.metrics(50_000L).net);

        settle(engine, snapshot(false, 80L), 60_000L);
        assertEquals("the return shrinks the load, never a gain", -(10L * 200L),
            engine.metrics(90_000L).net);
        assertEquals(0L, engine.session().transactions().stream()
            .filter(row -> row.counts() && row.type() == TransactionType.GAIN).count());
    }

    @Test
    public void shipCannonballTiersAreSuppliesToo()
    {
        // Sailing's plain tiers, chainshot and incendiary are the same cannon economy: the balls
        // leaving the pack for a ship cannon read as Supplies like the dwarf load (owner 1.3.4
        // ship sweep).
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(held(ItemID.BRONZE_CANNONBALL, 40L, ItemID.DRAGON_CHAINSHOT_CANNONBALL, 5L));

        Transaction loss = settle(engine,
            held(ItemID.BRONZE_CANNONBALL, 25L, ItemID.DRAGON_CHAINSHOT_CANNONBALL, 2L), 2_000L);
        assertEquals(ActionKind.SUPPLIES, loss.action());
        assertEquals(CostKind.SUPPLIES, CostKind.of(loss, loss.flows().get(0)));
        assertEquals(-(15L * 30L) - (3L * 300L), engine.metrics(5_000L).net);
    }

    @Test
    public void aCannonAlreadyDeployedBeforeTrackingReturnsUnspentBallsNeutrally()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(false, 0));
        engine.syncCannon(4, 30, false);
        engine.moveCannon();
        settle(engine, snapshot(true, 30), 2_000L);
        assertEquals("pre-observation balls are not fresh income", 0L, engine.metrics(10_000L).net);
    }

    @Test
    public void resetAfterALoadStillShrinksTheOriginalCannonSupply()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(false, 90));
        engine.loadCannon(6);
        settle(engine, snapshot(false, 60), 2_000L);
        assertEquals(-6_000L, engine.metrics(5_000L).net);
        engine.resetTracking(true);
        engine.setBaseline(snapshot(false, 60));
        engine.moveCannon();
        settle(engine, snapshot(true, 70), 10_000L);
        assertEquals(-4_000L, engine.metrics(20_000L).net);
    }

    private static ContainerSnapshot snapshot(boolean parts, long balls)
    {
        Map<Integer, Long> held = new HashMap<>();
        if (parts)
        {
            held.put(ItemID.TWPART1, 1L);
            held.put(ItemID.TWPART2, 1L);
            held.put(ItemID.TWPART3, 1L);
            held.put(ItemID.TWPART4, 1L);
        }
        held.put(ItemID.MCANNONBALL, balls);
        return new ContainerSnapshot(held);
    }

    private static ContainerSnapshot held(Object... idsAndQuantities)
    {
        Map<Integer, Long> held = new HashMap<>();
        for (int index = 0; index < idsAndQuantities.length; index += 2)
        {
            held.merge((Integer) idsAndQuantities[index], (Long) idsAndQuantities[index + 1],
                Long::sum);
        }
        return new ContainerSnapshot(held);
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        Transaction row = null;
        for (long t = firstTick; row == null && t < firstTick + 6_000L; t += 600L) row = engine.processIfDirty(snapshot, t, null);
        assertNotNull(row);
        return row;
    }

    private static void wait(Engine engine, ContainerSnapshot snapshot, long ticks, long firstTick)
    {
        long now = firstTick;
        for (long tick = 0; tick < ticks; tick++) engine.processIfDirty(snapshot, now += 600L, null);
    }
}

package com.gpmanager;


/** Test-side reads of engine state; moved out of production to keep the plugin small. */
public final class EngineProbe
{
    public static String saveLiveSession(Engine engine, Session expected, Long start, long now) {
        synchronized (engine) {
            return engine.saveLiveSession(expected, start, engine.captureLiveSession(expected, start, now));
        }
    }

    public static String saveLiveSession(Engine engine, Session expected, Long start, SavedState.SavedSession copy) {
        return engine.saveLiveSession(expected, start, copy);
    }

    private EngineProbe()
    {
    }

    private static BasisPool pool(Engine engine, int itemId) {
        synchronized (engine.basis) {
            return engine.basis.stock.get(itemId);
        }
    }

    public static long availableQty(Engine engine, int itemId) {
        BasisPool pool = pool(engine, itemId);
        return pool == null ? 0L : pool.availableQty;
    }

    public static long availableBasisGp(Engine engine, int itemId) {
        BasisPool pool = pool(engine, itemId);
        return pool == null ? 0L : pool.availableBasisGp;
    }

    /** Known coverage held out by the item's open SELL custody records. */
    public static long reservedQty(Engine engine, int itemId) {
        long total = 0L;
        for (GeOffer record : engine.exchange.records()) {
            if (record.itemId == itemId && record.getSide() == GeOffer.Side.SELL) total += record.reservedQty();
        }
        return total;
    }

    public static long reservedBasisGp(Engine engine, int itemId) {
        long total = 0L;
        for (GeOffer record : engine.exchange.records()) {
            if (record.itemId == itemId && record.getSide() == GeOffer.Side.SELL) total += record.reservedBasis();
        }
        return total;
    }

    /** Exact known coverage for one canonical item. */
    public static long knownCoverageQty(Engine engine, int itemId) {
        return availableQty(engine, itemId) + reservedQty(engine, itemId);
    }

    /** Exact known coverage basis for one canonical item. */
    public static long knownCoverageBasisGp(Engine engine, int itemId) {
        return availableBasisGp(engine, itemId) + reservedBasisGp(engine, itemId);
    }

    public static boolean isBaselinePriming(Engine engine) {
        synchronized (engine) {
            return engine.warming;
        }
    }

    public static boolean isAwaitingDeathReclaim(Engine engine)
    {
        synchronized (engine)
        {
            return engine.death.isAwaitingReclaim();
        }
    }

    /** The cash retained internally pending exact attribution. */
    public static long pendingSettlementCash(GeCustodyLedger ledger)
    {
        synchronized (ledger)
        {
            return ledger.cash;
        }
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class EpochUndoProjectionTest {
    private static final long NOW = 1_700_000_000_000L;
    private static final int ITEM = 1203;
    private static final long UNIT = 1_000_000_000_000_000_000L;

    private static Engine engine() {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = new Engine(changes -> {
            var flows = new ArrayList<Flow>();
            changes.forEach((id, qty) -> flows.add(new Flow(id, "Iron dagger", qty, 100, qty * 100,
                    PriceSource.GRAND_EXCHANGE)));
            return flows;
        }, new TransactionClassifier(), ReviewFixesTest.CONFIG);
        engine.startCustom("Batch capacity audit", NOW - 2000);
        return engine;
    }

    private static Transaction row(Engine engine, long at, long qty, long value, boolean counted) {
        var tx = new Transaction(at, counted ? TransactionType.GAIN : TransactionType.UNCERTAIN,
                Context.GENERIC, "", "Audit", counted,
                List.of(new Flow(ITEM, "Iron dagger", qty, Math.abs(value / qty), value, PriceSource.MANUAL_OVERRIDE)),
                counted ? Confidence.CONFIRMED : Confidence.UNCERTAIN, "Audit", null);
        engine.session().addTransaction(tx, 2000, false);
        return tx;
    }

    private static void mixedUndo(long scale, boolean afterReload) {
        var engine = engine();
        row(engine, NOW + 1, 1, scale, true);
        var cost = row(engine, NOW + 10, 1, 4 * scale, true);
        assertTrue(engine.correctTransaction(cost.id(), Correction.COST, "A prior owner choice"));
        var gain = row(engine, NOW + 20, 1, 4 * scale, false);
        assertTrue(engine.correctTransaction(gain.id(), Correction.REVENUE, "Another prior owner choice"));
        assertTrue(engine.correctEntries(List.of(gain.id(), cost.id()), Correction.AUTO));
        row(engine, NOW + 30, 1, scale, true);
        assertEquals(6 * scale, engine.basis.known(ITEM).availableBasisGp);
        if (afterReload) {
            var saved = SaveCopies.copy(engine.savedState());
            engine = engine();
            engine.restore(saved, NOW + 100);
        }
        long beforeNet = engine.metrics(NOW + 200).net;
        int history = engine.session().correctionHistory.size();
        var gson = new com.google.gson.Gson();
        String beforeBasis = gson.toJson(engine.basis.stock);
        String beforeRows = gson.toJson(engine.session().transactions());
        String beforeHistory = gson.toJson(engine.session().correctionHistory);
        long revision = engine.revision();
        boolean undone = engine.undoCorrection();
        System.out.println("mixed undo scale=" + scale + " reload=" + afterReload + " applied=" + undone
                + " basis=" + engine.basis.known(ITEM).availableBasisGp + " net=" + engine.metrics(NOW + 200).net);
        if (undone) {
            assertEquals(100, scale);
            assertEquals("the two restored contributions preserve their exact combined basis", 6 * scale,
                    engine.basis.known(ITEM).availableBasisGp);
        } else {
            assertEquals(UNIT, scale);
            assertEquals(beforeNet, engine.metrics(NOW + 200).net);
            assertEquals(Correction.AUTO, engine.session().findTransaction(cost.id()).correction());
            assertEquals(Correction.AUTO, engine.session().findTransaction(gain.id()).correction());
            assertFalse(engine.session().latestCorrection().undone);
            assertEquals(beforeBasis, gson.toJson(engine.basis.stock));
            assertEquals(beforeRows, gson.toJson(engine.session().transactions()));
            assertEquals(beforeHistory, gson.toJson(engine.session().correctionHistory));
            assertEquals(revision, engine.revision());
        }
        assertEquals(history, engine.session().correctionHistory.size());
    }

    @Test public void aGroupedUndoMustNotSubtractAfterAnEarlierRestoreSaturatesThePool() {
        mixedUndo(UNIT, false);
    }

    @Test public void groupedUndoMustRemainSafeAfterReload() {
        mixedUndo(UNIT, true);
    }

    @Test public void ordinaryMixedUndoControlRestoresBothPriorChoices() {
        mixedUndo(100, false);
    }

    private static Engine migrationReview() {
        var engine = engine();
        row(engine, NOW - 1000, -1, -100, false);
        var state = SaveCopies.copy(engine.savedState());
        state.setTrackedBasis(null);
        var restored = engine();
        restored.restore(state, NOW);
        assertEquals(NOW, restored.basis.epoch);
        row(restored, NOW + 1, 1, 100, true);
        return restored;
    }

    private static void oldReview(boolean batch) {
        for (var choice : List.of(Correction.COST, Correction.REVENUE)) {
            var engine = migrationReview();
            var review = engine.session().transactions().stream().filter(ReviewRules::needsReview).findFirst().get();
            assertTrue(engine.session().canCorrect(review, choice));
            boolean applied = batch ? engine.correctEntries(List.of(review.id()), choice)
                    : engine.correctTransaction(review.id(), choice, "Old owner decision");
            assertTrue(applied);
            assertEquals(choice == Correction.COST ? 0 : 200, engine.metrics(NOW + 20).net);
            assertEquals("pre-epoch ownership is unknown, not a sink for newly acquired stock", 1,
                    engine.basis.known(ITEM).availableQty);
            assertEquals(100, engine.basis.known(ITEM).availableBasisGp);
            assertTrue(engine.undoCorrection());
            assertEquals(Correction.AUTO, review.correction());
            assertEquals(100, engine.metrics(NOW + 20).net);
            assertEquals(1, engine.basis.known(ITEM).availableQty);
            assertEquals(100, engine.basis.known(ITEM).availableBasisGp);
        }
    }

    @Test public void aPreEpochReviewMustNotConsumePostEpochAcquisitions() {
        oldReview(false);
    }

    @Test public void aPreEpochBatchMustNotConsumePostEpochAcquisitions() {
        oldReview(true);
    }

    @Test public void merelyPreviewingAnOldDecisionLeavesNewCoverageUnchanged() {
        var engine = migrationReview();
        long revision = engine.revision();
        var preview = engine.previewDecision(Decision.COST, row -> true, NOW + 20);
        assertEquals(1, preview.rowCount());
        assertEquals(1, engine.basis.known(ITEM).availableQty);
        assertEquals(100, engine.basis.known(ITEM).availableBasisGp);
        assertEquals(revision, engine.revision());
    }

    @Test public void preEpochUsedUpCannotConsumeNewCoverage() {
        var engine = migrationReview();
        var old = new Transaction(NOW - 1, TransactionType.CONSUMPTION, Context.GENERIC, "", "Old drop", true,
                List.of(new Flow(ITEM, "Iron dagger", -1, 100, -100, PriceSource.GRAND_EXCHANGE)),
                Confidence.CONFIRMED, "", null);
        engine.basis.onUsedUp(old);
        assertEquals(1, engine.basis.known(ITEM).availableQty);
        assertEquals(100, engine.basis.known(ITEM).availableBasisGp);
    }

    @Test public void preEpochPositiveCorrectionsRetainTheirExistingRefusal() {
        var engine = engine();
        var old = row(engine, NOW - 1000, 1, 100, false);
        var saved = SaveCopies.copy(engine.savedState());
        saved.setTrackedBasis(null);
        var restored = engine();
        restored.restore(saved, NOW);
        row(restored, NOW + 1, 1, 100, true);
        assertFalse(restored.correctTransaction(old.id(), Correction.REVENUE, "Cannot backfill old ownership"));
        assertEquals(1, restored.basis.known(ITEM).availableQty);
        assertEquals(100, restored.basis.known(ITEM).availableBasisGp);
    }

    @Test public void postEpochReviewStillConsumesItsEligibleCoverage() {
        var engine = migrationReview();
        var current = row(engine, NOW + 2, -1, -100, false);
        assertTrue(engine.correctTransaction(current.id(), Correction.COST, "Current decision"));
        assertEquals(0, engine.basis.known(ITEM).availableQty);
        assertEquals(0, engine.basis.known(ITEM).availableBasisGp);
    }

    private static Engine groupedSplits() {
        var engine = engine();
        var first = row(engine, NOW + 1, 2, 200, true);
        var second = Tx.of(NOW + 2, TransactionType.GAIN, Context.GENERIC, "", true,
                List.of(new Flow(882, "Bronze arrow", 2, 200, 400, PriceSource.MANUAL_OVERRIDE)));
        engine.session().addTransaction(second, 2000, false);
        assertTrue(engine.session().splitItem(first.id(), ITEM, 1, "First split"));
        assertTrue(engine.session().splitItem(second.id(), 882, 1, "Second split"));
        var changes = new ArrayList<CorrectionRecord.Change>();
        for (var record : engine.session().correctionHistory) changes.addAll(record.changes());
        engine.session().correctionHistory.clear();
        engine.session().correctionHistory.add(new CorrectionRecord("Grouped saved split", changes));
        return engine;
    }

    @Test public void groupedUndoRestoresBothFlowSnapshotsAtOriginalPrices() {
        var engine = groupedSplits();
        assertTrue(engine.undoCorrection());
        assertEquals(2, engine.basis.known(ITEM).availableQty);
        assertEquals(200, engine.basis.known(ITEM).availableBasisGp);
        assertEquals(2, engine.basis.known(882).availableQty);
        assertEquals(400, engine.basis.known(882).availableBasisGp);
        assertEquals(600, engine.metrics(NOW + 20).net);
        assertTrue(engine.session().correctionHistory.get(0).undone);
    }

    @Test public void aBlockedFlowSnapshotUndoDoesNotPartiallyRestoreTheOtherItem() {
        var engine = groupedSplits();
        engine.basis.fenceRealized(ITEM, NOW + 30);
        var gson = new com.google.gson.Gson();
        String before = gson.toJson(engine.basis.stock);
        String rows = gson.toJson(engine.session().transactions());
        String history = gson.toJson(engine.session().correctionHistory);
        assertFalse(engine.undoCorrection());
        assertEquals(before, gson.toJson(engine.basis.stock));
        assertEquals(rows, gson.toJson(engine.session().transactions()));
        assertEquals(history, gson.toJson(engine.session().correctionHistory));
    }

    @Test public void groupedFlowSnapshotsStillRestoreAfterReload() {
        var engine = groupedSplits();
        var restored = engine();
        restored.restore(SaveCopies.copy(engine.savedState()), NOW + 100);
        assertTrue(restored.undoCorrection());
        assertEquals(600, restored.metrics(NOW + 200).net);
        assertEquals(200, restored.basis.known(ITEM).availableBasisGp);
        assertEquals(400, restored.basis.known(882).availableBasisGp);
    }

    @Test public void ambiguousRepeatedUndoTargetsRefuseBeforeMutation() {
        var engine = groupedSplits();
        var record = engine.session().latestCorrection();
        record.changes.add(record.changes.get(0));
        var gson = new com.google.gson.Gson();
        String before = gson.toJson(engine.basis.stock);
        String rows = gson.toJson(engine.session().transactions());
        assertFalse(engine.undoCorrection());
        assertFalse(record.undone);
        assertEquals(before, gson.toJson(engine.basis.stock));
        assertEquals(rows, gson.toJson(engine.session().transactions()));
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static com.gpmanager.EngineTestFixtures.mapOf;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The bracelet of ethereum: revenant ether loads as a committed Supplies spend (an uncharge
 * destroys the stored ether), the charged bracelet prices from its uncharged form, and its
 * dismantle is not the neutral parts rule (the ether is worth more than the item) (OSRS Wiki,
 * Muse review, owner 2026-10-12).
 */
public class EthereumChargeTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final String BRACELET = "149:0:9764864:21816:ETHEREUM";
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override public int stabilizationTicks() { return 2; }
        @Override public boolean keepTransferAuditRows() { return true; }
    };

    @Test
    public void theChargedBraceletPricesFromItsUnchargedQuote()
    {
        // RuneLite's ItemMapping carries no bracelet entry; the charged form prices from the
        // uncharged form's live quote (Muse review 2026-10-12).
        Valuation valuation = ModelProbe.valuation(new GpManagerConfig() { }, EthereumChargeTest::composition,
            id -> id == ItemID.WILD_CAVE_BRACELET_UNCHARGED ? 40_000 : 0);
        Flow bracelet = valuation.valueComponent(ItemID.WILD_CAVE_BRACELET_CHARGED, 1L, 0L);
        assertEquals(40_000, bracelet.unitPrice);
        assertSame(PriceSource.GRAND_EXCHANGE, bracelet.source());
        assertEquals("the uncharged keeps its own quote",
            40_000, valuation.valueComponent(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L, 0L).unitPrice);
    }

    @Test
    public void committedEtherLoadsBookTheirEtherAsSupplies()
    {
        Engine engine = engine();
        long start = 100_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.WILD_CAVE_SHARD, 30L));

        assertTrue(engine.markChargeLoad(ChargeCheck.ChargedItem.ETHEREUM, ItemID.WILD_CAVE_SHARD,
            "Revenant ether", BRACELET, 8));
        engine.markDirty();
        Transaction load = settle(engine, snapshot(ItemID.WILD_CAVE_SHARD, 25L), start + 600L);

        assertEquals(TransactionType.CONSUMPTION, load.original());
        assertTrue(load.counts());
        assertEquals(GameData.msg("committedLoad") + "Bracelet of ethereum", load.note());
        assertEquals(ActionKind.SUPPLIES, load.action());
        assertEquals(-1_250L, load.net());
        assertEquals(1_250L, engine.metrics(start + 2_400L).cost);
    }

    @Test
    public void anUnchargeBooksNothing()
    {
        Engine engine = engine();
        long start = 120_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.WILD_CAVE_BRACELET_CHARGED, 1L));

        ChargeIntake intent = new ChargeIntake(selecting(null), null, CONFIG, engine, null);
        intent.armCheck(click(MenuAction.CC_OP, "Uncharge", item(ItemID.WILD_CAVE_BRACELET_CHARGED, 0)),
            "uncharge", "Bracelet of ethereum");
        assertNotNull("the uncharge watch arms", engine.events.peek(Inbox.UNCHARGE));
        engine.markDirty();
        settle(engine, snapshot(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L), start + 600L);

        assertTrue("the ether was booked at load; the uncharge adds nothing",
            engine.session().transactions().stream().noneMatch(Transaction::counts));
        assertEquals(0L, engine.metrics(start + 2_400L).net);
    }

    @Test
    public void theBankConfigureChargesRouteNeverPhantomBooks()
    {
        Engine engine = engine();
        long start = 140_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.WILD_CAVE_SHARD, 30L));

        ChargeIntake intent = new ChargeIntake(selecting(null), null, CONFIG, engine, null);
        intent.armCheck(click(MenuAction.CC_OP, "Configure-Charges", item(ItemID.WILD_CAVE_BRACELET_CHARGED, 0)),
            "configure-charges", "Bracelet of ethereum");
        assertNull("no load arms without a use-on click", engine.events.peek(Inbox.LOAD_TARGET));

        engine.markDirty();
        settle(engine, snapshot(ItemID.WILD_CAVE_SHARD, 25L), start + 600L);
        for (Transaction row : engine.session().transactions())
        {
            assertFalse("a bank load cannot phantom-book as a charge load",
                row.note() != null && row.note().startsWith(GameData.msg("committedLoad")));
        }
    }

    @Test
    public void alchemyBooksTheBraceletAtItsBaseQuoteOnce()
    {
        // The observed cast: the charged bracelet leaves and the coins arrive under consume
        // intent (the ConsumptionBurialEngineTest alchemy pattern).
        Engine engine = engine();
        long start = 160_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.WILD_CAVE_BRACELET_CHARGED, 1L));
        engine.noteConsume(ItemID.WILD_CAVE_BRACELET_CHARGED, 8, false, null, null);
        engine.markDirty();

        Transaction alchemy = settle(engine, snapshot(995, 45_000L), start + 600L);

        assertNotNull(alchemy);
        assertTrue(alchemy.counts());
        long braceletLeg = alchemy.flows().stream()
            .filter(flow -> flow.item == ItemID.WILD_CAVE_BRACELET_CHARGED)
            .mapToLong(flow -> flow.value).sum();
        assertEquals("the bracelet leaves at its uncharged form's quote", -40_000L, braceletLeg);
        assertEquals(5_000L, alchemy.net());
    }

    @Test
    public void theChargeToAlchFlowNetsTheGuideMargin()
    {
        Engine engine = engine();
        long start = 200_000L;
        engine.ensureSession(start);

        // Buy the bracelet and one ether (both net-neutral), charge (the committed load), then
        // alch: the counted lifetime net is the guide's margin.
        engine.setBaseline(snapshot(995, 100_000L));
        engine.markDirty();
        settle(engine, snapshot(mapOf(995, 60_000L, ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L)), start + 600L);

        engine.markDirty();
        settle(engine, snapshot(mapOf(995, 59_750L, ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L,
            ItemID.WILD_CAVE_SHARD, 1L)), start + 1_400L);

        engine.markChargeLoad(ChargeCheck.ChargedItem.ETHEREUM, ItemID.WILD_CAVE_SHARD,
            "Revenant ether", BRACELET, 8);
        engine.markDirty();
        settle(engine, snapshot(mapOf(995, 59_750L, ItemID.WILD_CAVE_BRACELET_CHARGED, 1L)), start + 2_200L);

        engine.noteConsume(ItemID.WILD_CAVE_BRACELET_CHARGED, 8, false, null, null);
        engine.markDirty();
        settle(engine, snapshot(995, 104_750L), start + 3_000L);

        assertEquals("45,000 - 40,000 - 250", 4_750L, engine.metrics(start + 5_000L).net);
    }

    @Test
    public void aDeathWipeAddsNoEtherDoubleCount()
    {
        Engine engine = engine();
        long start = 240_000L;
        engine.ensureSession(start);
        ContainerSnapshot carried = snapshot(ItemID.WILD_CAVE_BRACELET_CHARGED, 1L);
        engine.setBaseline(carried);
        engine.markDirty();
        for (int tick = 1; tick <= 3; tick++)
        {
            engine.processIfDirty(carried, start + tick * 600L, null);
        }

        engine.markPvmDeath(1, carried.items, Map.of(), engine.events.owner);
        engine.markDirty();
        Transaction wipe = settle(engine, FixtureReads.empty(), start + 3_000L);

        assertNotNull(wipe);
        assertEquals(TransactionType.TRANSFER, wipe.type());
        assertFalse(wipe.counts());
        assertEquals(0L, engine.metrics(start + 6_000L).net);
        for (Transaction row : engine.session().transactions())
        {
            assertFalse(row.note() != null && row.note().startsWith(GameData.msg("committedLoad")));
        }
    }

    private static ItemComposition composition(int id)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) ->
            {
                if ("getName".equals(method.getName())) return "Bracelet of ethereum";
                if ("getHaPrice".equals(method.getName())) return 45_000;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return false;
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                return null;
            });
    }

    private static Engine engine()
    {
        return new Engine(EthereumChargeTest::flows, new TransactionClassifier(), CONFIG);
    }

    private static List<Flow> flows(Map<Integer, Long> deltas)
    {
        List<Flow> flows = new ArrayList<>();
        for (Map.Entry<Integer, Long> entry : deltas.entrySet())
        {
            int price = priceOf(entry.getKey());
            flows.add(new Flow(entry.getKey(), nameOf(entry.getKey()), entry.getValue(), price,
                entry.getValue() * price));
        }
        return flows;
    }

    private static int priceOf(int itemId)
    {
        if (itemId == ItemID.COINS) return 1;
        if (itemId == ItemID.WILD_CAVE_SHARD) return 250;
        if (itemId == ItemID.WILD_CAVE_BRACELET_UNCHARGED
                || itemId == ItemID.WILD_CAVE_BRACELET_CHARGED) return 40_000;
        return 0;
    }

    private static String nameOf(int itemId)
    {
        if (itemId == ItemID.COINS) return "Coins";
        if (itemId == ItemID.WILD_CAVE_SHARD) return "Revenant ether";
        return "Bracelet of ethereum";
    }

    private static ContainerSnapshot snapshot(int id, long quantity)
    {
        return snapshot(mapOf(id, quantity));
    }

    private static ContainerSnapshot snapshot(Map<Integer, Long> quantities)
    {
        return new ContainerSnapshot(quantities);
    }


    private static Transaction settle(Engine engine, ContainerSnapshot next, long firstTick)
    {
        assertNull(engine.processIfDirty(next, firstTick, null));
        assertNull(engine.processIfDirty(next, firstTick + 600L, null));
        return engine.processIfDirty(next, firstTick + 1_200L, null);
    }

    private static Widget item(int itemId, int slot)
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[] {Widget.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getItemId": return itemId;
                    case "getIndex": return slot;
                    case "getId": return InterfaceID.Inventory.ITEMS;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        return null;
                }
            });
    }

    private static net.runelite.api.Client selecting(Widget selected)
    {
        return (net.runelite.api.Client) Proxy.newProxyInstance(
            net.runelite.api.Client.class.getClassLoader(), new Class<?>[] {net.runelite.api.Client.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getSelectedWidget": return selected;
                    case "getTickCount": return 101;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
    }

    private static MenuOptionClicked click(MenuAction action, String option, Widget clicked)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return option;
                    case "getTarget": return "";
                    case "getType": return action;
                    case "getWidget": return clicked;
                    case "getItemId": return clicked == null ? -1 : clicked.getItemId();
                    case "getParam0": return clicked == null ? -1 : clicked.getIndex();
                    case "getParam1": return clicked == null ? -1 : clicked.getId();
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class FiremakingSupplyEvidenceTest
{
    @Test
    public void explicitLightAndTendToFuelLossesAreTypedSupplies()
    {
        assertFuelAction("Light", "Willow logs");
        assertFuelAction("Tend-to", "Blisterwood logs");
        assertFuelAction("Tend to", "Juniper logs");
        assertTrue("existing Use Tinderbox evidence remains supported",
            FixtureReads.lightsFire("Use", "Tinderbox -> Willow logs"));
    }

    @Test
    public void unexplainedLossAndArbitraryUseRemainLosses()
    {
        Transaction unexplained = transaction("Logs");
        assertNull(ActionReader.resolve(null, unexplained.flows(), unexplained.type(), "Firemaking"));
        assertEquals(CostKind.LOSS, CostKind.of(unexplained, unexplained.flows().get(0)));

        ActionKind arbitraryUse = ActionReader.verbOf("Use");
        assertNull(arbitraryUse);
        assertNull(ActionReader.resolve(arbitraryUse, unexplained.flows(),
            unexplained.type(), "Firemaking"));
        assertEquals(CostKind.LOSS, CostKind.of(unexplained, unexplained.flows().get(0)));

        ActionKind mismatchedFuelIntent = ActionReader.resolve(ActionReader.verbOf("Light"),
            Collections.singletonList(new Flow(946, "Knife", -1L, 1, -1L)),
            TransactionType.CONSUMPTION, "Firemaking");
        assertNull("Light does not turn a non-fuel loss into Supplies", mismatchedFuelIntent);
    }

    private static void assertFuelAction(String menuOption, String name)
    {
        Transaction transaction = transaction(name);
        ActionKind resolved = ActionReader.resolve(ActionReader.verbOf(menuOption),
            transaction.flows(), transaction.type(), "Firemaking");
        assertEquals(ActionKind.SUPPLIES, resolved);
        transaction.setAction(resolved);
        assertEquals(CostKind.SUPPLIES, CostKind.of(transaction, transaction.flows().get(0)));
    }

    private static Transaction transaction(String name)
    {
        return new Transaction(1_000L, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Firemaking", true,
            Collections.singletonList(new Flow(1519, name, -1L, 100, -100L)),
            Confidence.CONFIRMED, "explicit evidence test", null);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static com.gpmanager.GameData.msg;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner live 2026-10-16: coins picked up at Commander Zilyana went to Review as "Grand Exchange
 * movement not claimable by a custody lifecycle", because a sale had finished in the last two
 * hours. The GE-collect gate stops new ones. The obsolete historical repair is now retired.
 */
public class GeCollectRecheckTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final int COINS = 995, BONES = 526;

    @Test
    public void aPreGateReviewStaysUntouchedWhileTodaysPickupStillBooks()
    {
        Engine engine = engine();
        engine.startCustom("Zilyana", T0);
        Session session = engine.session();
        Transaction old = geReview(Context.GENERIC, coins(19_911L));
        String id = old.id();
        session.addTransaction(old, 2_000, false);
        assertTrue("it starts in Review", ReviewRules.needsReview(old));
        long revision = engine.revision();

        engine.recheck();

        Transaction today = pickup(19_911L);
        assertNotNull("today's code books the same coins", today);
        assertSame(TransactionType.GAIN, today.type());
        assertTrue(today.counts());
        assertSame("retired migration cannot rewrite old history", TransactionType.UNCERTAIN, old.type());
        assertFalse(old.counts());
        assertTrue(ReviewRules.needsReview(old));
        assertEquals("Grand Exchange", old.note());
        assertEquals(msg("geMovement"), old.explanation());
        assertEquals("same row", id, old.id());
        assertEquals("same time", T0, old.timestamp);
        assertEquals("same activity", "Growler", old.activityName());
        assertSame(Correction.AUTO, old.correction());
        assertEquals("unprocessed history remains uncounted", 0L, session.metrics(T0).net);
        assertEquals(revision, engine.revision());

        revision = engine.revision();
        engine.recheck();
        assertEquals("a second pass changes nothing", revision, engine.revision());
    }

    @Test
    public void aMarketRowALossOrAnOwnerDecisionIsNeverRebooked()
    {
        Engine engine = engine();
        engine.startCustom("Zilyana", T0);
        Session session = engine.session();
        Transaction market = geReview(Context.MARKET, coins(5_000L));
        Transaction withLoss = geReview(Context.GENERIC, coins(5_000L),
            new Flow(BONES, "Bones", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE));
        Transaction withItem = geReview(Context.GENERIC, coins(5_000L),
            new Flow(BONES, "Bones", 1L, 100, 100L, PriceSource.GRAND_EXCHANGE));
        Transaction counted = geReview(Context.GENERIC, coins(5_000L));
        counted.applyCorrection(Correction.REVENUE, "Manual correction");
        for (Transaction row : List.of(market, withLoss, withItem, counted)) session.addTransaction(row, 2_000, false);
        long revision = engine.revision();

        engine.recheck();

        for (Transaction row : List.of(market, withLoss, withItem, counted))
        {
            assertSame(TransactionType.UNCERTAIN, row.original());
            assertEquals("Grand Exchange", row.note());
            assertEquals(msg("geMovement"), row.explanation());
            assertFalse(row.counted);
        }
        assertSame("the owner's Count stays theirs", Correction.REVENUE, counted.correction());
        assertEquals("nothing changed", revision, engine.revision());
    }

    private static Flow coins(long quantity)
    {
        return new Flow(COINS, "Coins", quantity, 1, quantity, PriceSource.FACE_VALUE);
    }

    /** A row as the pre-gate rule booked it. */
    private static Transaction geReview(Context context, Flow... flows)
    {
        return new Transaction(T0, TransactionType.UNCERTAIN, context, "Grand Exchange", "Growler", false,
            List.of(flows), Confidence.UNCERTAIN, msg("geMovement"), null);
    }

    /** The same coins landing in the pack today, with no Collect click. */
    private static Transaction pickup(long quantity)
    {
        Engine engine = engine();
        engine.startCustom("Zilyana", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(COINS, 0L))));
        engine.markDirty();
        List<Transaction> booked = new ArrayList<>();
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(COINS, quantity))),
                T0 + 600L + i * 600L, booked::add);
            if (settled != null) booked.add(settled);
        }
        return booked.isEmpty() ? null : booked.get(0);
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                flows.add(id == COINS ? coins(delta.getValue())
                    : new Flow(id, "Bones", delta.getValue(), 100, delta.getValue() * 100, PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-09: an offer collected to the bank never shows its cash or items in the
 * inventory, so it used to wait ten minutes and land in Review uncounted. The offer itself proves
 * what filled and what it cost, so it now settles: a buy exactly, a sale at its proven tax or, at
 * mixed prices, the highest tax it could have paid.
 */
public class GeCollectToBankTest
{
    private static final int COINS = ItemID.COINS;
    private static final int RUNE = ItemID.NATURERUNE;
    private static final long T0 = 1_000_000_000_000L;
    private static final long LATER = 31_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 1_000_000L, RUNE, 100L));
    private final OfferSlots ledger = new OfferSlots();
    private final Engine engine = engine(inventory);

    @Test
    public void aBuyCollectedToTheBankIsAPurchase()
    {
        long t = T0 + 10_000L;
        offer(0, BUYING, 1_000, 180, 0, 0, t);
        inventory.put(COINS, 1_000_000L - 180_000L);
        settle(t + 100L);
        offer(0, BOUGHT, 1_000, 180, 1_000, 176_000, t + 1_000L);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.tickGe(t + 2_000L + LATER);

        assertEquals("no Review", 0, reviewRows());
        assertTrue("one purchase", trades() == 1);
        assertEquals("buying is Net-neutral", 0L, net());
        engine.tickGe(t + 2_000L + 11L * 60_000L);
        assertEquals("still nothing in Review ten minutes later", 0, reviewRows());
    }

    @Test
    public void aSaleAtOnePriceCollectedToTheBankCountsItsTax()
    {
        long t = T0 + 10_000L;
        sell(40L, 5_600L, SOLD, t);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.tickGe(t + 2_000L + 10_000L);
        assertEquals("not before the bank wait", 0, trades());
        engine.tickGe(t + 2_000L + LATER);

        assertEquals("140 each pays 2 each", -80L, net());
        assertEquals(0, reviewRows());
        assertEquals(1, trades());
    }

    @Test
    public void aSaleAtSeveralPricesCountsTheHighestTaxItCouldHavePaid()
    {
        long t = T0 + 10_000L;
        sell(25L, 3_513L, SOLD, t);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.tickGe(t + 2_000L + LATER);

        assertEquals("3,513 / 50 = 70 at most, never less than the truth", -70L, net());
        assertEquals(0, reviewRows());
        assertTrue(lastTrade().explanation().contains("highest tax"));
    }

    @Test
    public void aCancelledSaleSendsWhatDidNotSellToTheBankToo()
    {
        long t = T0 + 10_000L;
        sell(40L, 0L, SELLING, t);
        offer(0, SELLING, 40, 140, 10, 1_400, t + 1_000L);
        offer(0, CANCELLED_SELL, 40, 140, 10, 1_400, t + 1_500L);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.tickGe(t + 2_000L + LATER);

        assertEquals("only the 10 sold pay tax", -20L, net());
        assertEquals("the 30 unsold went back neutrally", 0, reviewRows());
        engine.tickGe(t + 2_000L + 11L * 60_000L);
        assertEquals(0, reviewRows());
    }

    @Test
    public void coinsCollectedToTheInventoryStillSettleOnceFromThem()
    {
        long t = T0 + 10_000L;
        sell(40L, 5_600L, SOLD, t);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.noteGeCollect(t + 2_100L);
        inventory.put(COINS, inventory.get(COINS) + 5_600L - 80L);
        settle(t + 2_200L);
        engine.tickGe(t + 2_000L + LATER);

        assertEquals(-80L, net());
        assertEquals("settled once, from the coins", 1, trades());
        assertEquals(0, reviewRows());
    }

    private void sell(long quantity, long spent, GrandExchangeOfferState state, long t)
    {
        offer(0, SELLING, (int) quantity, 140, 0, 0, t);
        inventory.put(RUNE, inventory.get(RUNE) - quantity);
        settle(t + 100L);
        if (state == SOLD) offer(0, SOLD, (int) quantity, 140, (int) quantity, (int) spent, t + 1_000L);
    }

    private long net()
    {
        return engine.metrics(T0 + 60L * 60_000L).net;
    }

    private int reviewRows()
    {
        int count = 0;
        for (Transaction transaction : engine.session().transactions())
        {
            if (ReviewRules.needsReview(transaction)) count++;
        }
        return count;
    }

    private int trades()
    {
        int count = 0;
        for (Transaction transaction : engine.session().transactions())
        {
            if (transaction.original() == TransactionType.TRADE) count++;
        }
        return count;
    }

    private Transaction lastTrade()
    {
        Transaction last = null;
        for (Transaction transaction : engine.session().transactions())
        {
            if (transaction.original() == TransactionType.TRADE) last = transaction;
        }
        return last;
    }

    private void offer(int slot, GrandExchangeOfferState state, int total, int price, int traded, int spent, long at)
    {
        int item = state == EMPTY ? 0 : state == BUYING || state == BOUGHT ? ItemID.WILD_CAVE_SHARD : RUNE;
        ledger.observe(new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent))
            .ifPresent(transition -> engine.noteGeOffer(transition, "Item " + item, at));
    }

    private void settle(long at)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(new HashMap<>(inventory));
        engine.processIfDirty(snapshot, at, null);
        engine.processIfDirty(snapshot, at + 1L, null);
    }

    private static Engine engine(Map<Integer, Long> inventory)
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                long unit = id == COINS ? 1L : 137L;
                flows.add(new Flow(id, id == COINS ? "Coins" : "Item " + id, delta.getValue(), (int) unit,
                    delta.getValue() * unit, id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        });
        engine.startCustom("Trading", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
        return engine;
    }
}

package com.gpmanager;

import static net.runelite.api.GrandExchangeOfferState.*;
import static org.junit.Assert.*;

import java.lang.reflect.Proxy;
import java.util.*;
import java.util.function.IntUnaryOperator;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** Native collection boxes identify sale proceeds without replacing custody's money rules. */
public class GeCollectionBoxTest {
    static final int RUNE = ItemID.NATURERUNE, COINS = ItemID.COINS;
    static final long START = 1_800_000_000_000L;

    static class Harness {
        final Engine engine;
        final OfferSlots slots = new OfferSlots();
        final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 100_000L));

        Harness() {
            JsonCodec.bind(new com.google.gson.Gson());
            engine = new Engine(deltas -> {
                var flows = new ArrayList<Flow>();
                deltas.forEach((id, quantity) -> flows.add(new Flow(id,
                        id == COINS ? "Coins" : "Nature rune", quantity, id == COINS ? 1 : 210,
                        quantity * (id == COINS ? 1 : 210),
                        id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE)));
                return flows;
            }, new TransactionClassifier(), new GpManagerConfig() {
                public int stabilizationTicks() { return 0; }
            });
            engine.ensureSession(START);
            engine.setBaseline(new ContainerSnapshot(inventory));
        }

        void offer(int slot, GrandExchangeOfferState state, int traded, int spent, long at) {
            slots.observe(new OfferSlots.Snapshot(slot, state, RUNE, 20, traded, 210, spent))
                    .ifPresent(change -> engine.noteGeOffer(change, "Nature rune", at));
        }

        void place(int slot, long at) {
            inventory.put(RUNE, 20L);
            engine.setBaseline(new ContainerSnapshot(inventory));
            offer(slot, SELLING, 0, 0, at);
            inventory.put(RUNE, 0L);
            settle(at + 1);
            offer(slot, SELLING, 10, 2100, at + 600);
        }

        void pair() { place(0, START + 1000); place(1, START + 3000); }

        void settle(long at) {
            engine.markDirty();
            var snapshot = new ContainerSnapshot(inventory);
            engine.processIfDirty(snapshot, at, null);
            engine.processIfDirty(snapshot, at + 1, null);
        }

        void cash(long at) { inventory.merge(COINS, 2060L, Long::sum); settle(at); }

        void box(int slot, long cash, long at) {
            engine.noteGeBox(slot, cash == 0 ? new Item[0] : new Item[] {new Item(COINS, (int) cash)},
                    IntUnaryOperator.identity(), at);
        }

        GeOffer record(int slot) {
            return engine.exchange.records().stream().filter(row -> row.slot == slot).findFirst().get();
        }

        long reviews() {
            return engine.session().transactions().stream().filter(ReviewRules::needsReview).count();
        }

        long trades() {
            return engine.session().transactions().stream().filter(row -> row.type() == TransactionType.TRADE).count();
        }

        void empty(int slot, long at) {
            slots.observe(new OfferSlots.Snapshot(slot, EMPTY, 0, 0, 0, 0, 0))
                    .ifPresent(change -> engine.noteGeOffer(change, "", at));
        }
    }

    @Test public void identicalLiveSalesResolveForBothCashBoxOrders() {
        for (boolean cashFirst : new boolean[] {false, true}) {
            var h = new Harness(); h.pair(); h.box(0, 2060, START + 5000);
            h.engine.noteGeCollect(START + 6000);
            if (cashFirst) h.cash(START + 6100);
            h.box(0, 0, START + 6200);
            if (!cashFirst) h.cash(START + 6300);
            h.engine.tickGe(START + 8500);
            assertEquals(10, h.record(0).settledQty);
            assertEquals(0, h.record(1).settledQty);
            assertEquals(0, h.reviews());
            assertEquals(-40, h.engine.metrics(START + 8600).net);
        }
    }

    @Test public void sameTieWithoutBoxProofStillFailsClosed() {
        var h = new Harness(); h.pair(); h.engine.noteGeCollect(START + 6000);
