    private static void gain(Engine engine, int item, long quantity, long value, long at)
    {
        engine.session().addTransaction(new Transaction(at,
            TransactionType.GAIN, Context.GENERIC, "", "Loot", true,
            Collections.singletonList(new Flow(item, name(item), quantity,
                (int) (quantity > 0L ? value / quantity : 0L), value,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "", null), 500, false);
    }

    private static String name(int itemId)
    {
        switch (itemId)
        {
            case VIAL: return "Vial of blood";
            case AMETHYST_ARROW: return "Amethyst arrow";
            case CHICKEN: return "Cooked chicken";
            case RUNE: return "Nature rune";
            default: return "Item " + itemId;
        }
    }

    /** A real engine with per-item frozen references and offline GE offer observations. */
    private static final class Market
    {
        final Engine engine;
        final OfferSlots ledger = new OfferSlots();
        final Map<Integer, Long> prices = new HashMap<>();
        final Map<Integer, Long> inventory = new HashMap<>();
        long now = T0;

        Market()
        {
            engine = new Engine(deltas ->
            {
                List<Flow> flows = new ArrayList<>();
                for (Map.Entry<Integer, Long> delta : deltas.entrySet())
                {
                    int id = delta.getKey();
                    long unit = id == COINS ? 1L : prices.getOrDefault(id, 0L);
                    PriceSource source = id == COINS ? PriceSource.FACE_VALUE
                        : unit > 0L ? PriceSource.GRAND_EXCHANGE : PriceSource.UNPRICED;
                    flows.add(new Flow(id, id == COINS ? "Coins" : name(id), delta.getValue(),
                        (int) unit, delta.getValue() * unit, source));
                }
                return flows;
            }, new TransactionClassifier(), new GpManagerConfig()
            {
                @Override
                public Retention receiptRetentionDays()
                {
                    return Retention.DAYS_365;
                }
            });
            engine.startCustom("Trading", now);
            inventory.put(COINS, 1_000_000L);
        }

        /** Place a SELL offer for pre-existing (unknown-coverage) stock and collect its cash. */
        void sellUnknown(int slot, int item, long qty, long listedPrice, long gross, long received)
        {
            sellUnknown(slot, item, qty, listedPrice, gross, received, false);
        }

        /** {@code collect}: the coins arrive after a Collect click, as they do in the game. */
        void sellUnknown(int slot, int item, long qty, long listedPrice, long gross, long received,
            boolean collect)
        {
            inventory.put(item, qty);
            engine.setBaseline(new ContainerSnapshot(inventory));
            offer(slot, SELLING, item, (int) qty, 0, (int) listedPrice, 0);
            inventory.put(item, 0L);
            settle();
            offer(slot, SOLD, item, (int) qty, (int) qty, (int) listedPrice, (int) gross);
            if (collect) engine.noteGeCollect(now);
            inventory.put(COINS, inventory.getOrDefault(COINS, 0L) + received);
            settle();
        }

        void offer(int slot, GrandExchangeOfferState state, int item, int total, int traded,
            int price, int spent)
        {
            now += 5_000L;
            OfferSlots.Transition transition = ledger.observe(
                new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent))
                .orElse(null);
            if (transition != null)
            {
                engine.noteGeOffer(transition, name(item), now);
            }
        }

        void settle()
        {
            now += 5_000L;
            engine.markDirty();
            ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
            for (int i = 0; i < 3; i++)
            {
                engine.processIfDirty(snapshot, now, null);
                now += 1_000L;
            }
        }

        MarketRows.Row row(int itemId)
        {
            for (MarketRows.Row row : engine.marketRows())
            {
                if (row.itemId == itemId)
                {
                    return row;
                }
            }
            throw new AssertionError("no market row for " + itemId);
        }

        Transaction transaction(String id)
        {
            Session session = engine.session();
            return session == null ? null : session.findTransaction(id);
        }

        List<Transaction> transactions()
        {
            Session session = engine.session();
            return session == null ? Collections.emptyList() : session.transactions();
        }

        int counted()
        {
            int counted = 0;
            for (Transaction transaction : transactions())
            {
                if (transaction != null && transaction.counts())
                {
                    counted++;
                }
            }
            return counted;
        }

        long net()
        {
            return engine.metrics(now + 1_000L).net;
        }
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.4 live: the last amulet-of-glory charge leaves the plain uncharged amulet, and that
 * step must book like every other charge (3&gt;2, 2&gt;1) instead of landing in Review.
 */
public class GloryLastChargeTest
{
    private static final int GLORY = 1704;
    private static final int GLORY_1 = 1706;
    private static final int GLORY_2 = 1708;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    @Test
    public void theLastChargeStepMatchesThePlainAmulet()
    {
        assertTrue("glory(1) to the plain amulet is one dose step",
            ActionReader.doseStep(Arrays.asList(
                flow(GLORY_1, "Amulet of glory(1)", -1L),
                flow(GLORY, "Amulet of glory", 1L))));
        assertFalse("two remaining doses never leave the plain base",
            ActionReader.doseStep(Arrays.asList(
                flow(GLORY_2, "Amulet of glory(2)", -1L),
                flow(GLORY, "Amulet of glory", 1L))));
    }

    @Test
    public void theLastChargeBooksOneSuppliesStep()
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) ->
                flows.add(flow(id, id == GLORY_1 ? "Amulet of glory(1)" : "Amulet of glory",
                    quantity)));
            return flows;
        }, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(held(GLORY_1, 1L));

        Transaction step = settle(engine, held(GLORY, 1L), 1_600L);
        assertEquals(TransactionType.CONSUMPTION, step.type());
        assertEquals(ActionKind.SUPPLIES, step.action());
        assertEquals(0, engine.getReviewRows(10_000L).size());
        assertEquals("both legs priced at the same quote", 0L, engine.metrics(10_000L).net);
    }

    private static Flow flow(int itemId, String name, long quantity)
    {
        return new Flow(itemId, name, quantity, 11_931, quantity * 11_931);
    }

    private static ContainerSnapshot held(int itemId, long quantity)
    {
        return new ContainerSnapshot(new HashMap<>(Map.of(itemId, quantity)));
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        assertNull(engine.processIfDirty(snapshot, firstTick, null));
        assertNull(engine.processIfDirty(snapshot, firstTick + 600L, null));
        Transaction tx = engine.processIfDirty(snapshot, firstTick + 1_200L, null);
        assertNotNull(tx);
        return tx;
    }
}

