    public void lifecycleResumeCheckDoesNotEraseRunningBaseline()
    {
        Engine engine = engine();
        long now = 12_000L;
        engine.ensureSession(now);
        engine.setBaseline(FixtureReads.empty());

        // Normal gameplay calls this check even when there was no lifecycle pause.
        engine.resume(now + 100L, PauseReason.LIFECYCLE);
        engine.markDirty();
        Transaction gain = settle(engine, snapshot(1942, 1L), now + 600L);

        assertNotNull(gain);
        assertEquals(TransactionType.GAIN, gain.type());
    }

    @Test
    public void idlePauseSurvivesLifecycleUntilMeaningfulActivity()
    {
        Engine engine = engine();
        engine.ensureSession(1_000L);

        engine.session().pause(2_000L, PauseReason.IDLE);
        assertTrue(engine.isIdlePaused());
        assertTrue(engine.metrics(3_000L).paused);

        engine.pauseForLifecycle(4_000L);
        engine.resume(14_000L, PauseReason.LIFECYCLE);

        assertTrue(engine.isIdlePaused());
        assertTrue(engine.metrics(15_000L).paused);

        engine.resume(16_000L, PauseReason.IDLE);
        assertFalse(engine.isIdlePaused());
        assertFalse(engine.metrics(17_000L).paused);
    }

    @Test
    public void delayedPartialNpcLootRemainsClassified()
    {
        Engine engine = engine();
        long now = 50_000L;
        engine.ensureSession(now);
        engine.setBaseline(FixtureReads.empty());

        Map<Integer, Long> expected = new HashMap<>();
        expected.put(526, 1L);
        expected.put(555, 6L);
        engine.recordAction("Goblin");
        engine.markLoot(expected, 50, "Loot from Goblin", "Goblin");

        for (int tick = 0; tick < 10; tick++)
        {
            assertNull(engine.processIfDirty(FixtureReads.empty(), now + 600L * (tick + 1), null));
        }

        engine.markDirty();
        Transaction bones = settle(engine, snapshot(526, 1L), now + 7_000L);
        assertEquals(TransactionType.LOOT, bones.type());
        assertEquals("Goblin", bones.activityName());

        Map<Integer, Long> allLoot = new HashMap<>();
        allLoot.put(526, 1L);
        allLoot.put(555, 6L);
        engine.markDirty();
        Transaction runes = settle(engine, new ContainerSnapshot(allLoot), now + 10_000L);
        assertEquals(TransactionType.LOOT, runes.type());
        assertEquals("Goblin", runes.activityName());

    }

    private Engine engine()
    {
        return new Engine(
            valuator,
            new TransactionClassifier(),
            CONFIG);
    }

    private static Transaction settle(
        Engine engine,
        ContainerSnapshot snapshot,
        long firstTick)
    {
        Transaction transaction = engine.processIfDirty(snapshot, firstTick, null);
        assertNull(transaction);
        transaction = engine.processIfDirty(snapshot, firstTick + 600L, null);
        assertNull(transaction);
        return engine.processIfDirty(snapshot, firstTick + 1_200L, null);
    }

    private static ContainerSnapshot snapshot(int itemId, long quantity)
    {
        Map<Integer, Long> values = new HashMap<>();
        if (quantity > 0L)
        {
            values.put(itemId, quantity);
        }
        return new ContainerSnapshot(values);
    }

    @Test
    public void playerLootCreatesConfirmedPkEncounter()
    {
        Engine engine = engine();
        long now = 70_000L;
        engine.ensureSession(now);
        engine.setBaseline(FixtureReads.empty());

        engine.markPkLoot(
            Collections.singletonMap(526, 1L),
            50,
            now + 600L);
        engine.markDirty();
        Transaction loot = settle(engine, snapshot(526, 1L), now + 1_200L);

        assertEquals(TransactionType.PK_LOOT, loot.type());
        assertEquals(Confidence.CONFIRMED, loot.confidence());
        assertFalse(loot.encounterId().isEmpty());
        assertEquals(1, engine.session().pk().kills);
        assertEquals(31L, engine.bestKill());
    }

    @Test
    public void pkKillAndDeathEncountersRecordFactsButNeverALocation()
    {
        Engine engine = engine();
        long now = 72_000L;
        engine.ensureSession(now);
        engine.markPkLoot(Collections.emptyMap(), 10, now + 1L);
        engine.markPkDeath(now + 2L, java.util.Collections.emptyMap(), null, engine.events.owner);

        assertEquals(1, engine.session().pk().kills);
        assertEquals(1, engine.session().pk().deaths);
        String json = new com.google.gson.Gson().toJson(engine.session());
        assertFalse("location is a detection signal only, never a persisted PvP fact", json.contains("Wilderness"));
        assertFalse(json.contains("Gauntlet"));
        assertFalse(json.contains("locationLabel"));
    }

    @Test
    public void genericMixedChangeIsUncertainAndExcludedByDefault()
    {
        Engine engine = engine();
        long now = 80_000L;
        engine.ensureSession(now);
        engine.setBaseline(snapshot(995, 100L));

        Map<Integer, Long> after = new HashMap<>();
        after.put(995, 50L);
        after.put(526, 2L);
        engine.markDirty();
        Transaction transaction = settle(engine, new ContainerSnapshot(after), now + 600L);

        assertEquals(TransactionType.UNCERTAIN, transaction.type());
        assertEquals(Confidence.UNCERTAIN, transaction.confidence());
        assertFalse(transaction.counts());
        assertEquals(0L, engine.metrics(now + 3_000L).net);
    }


    @Test
    public void confirmedPkDeathCreatesLossEncounter()
    {
        Engine engine = engine();
        long now = 90_000L;
        engine.ensureSession(now);
        engine.setBaseline(snapshot(1265, 1L));

        engine.markPkDeath(now + 600L, java.util.Collections.emptyMap(), null, engine.events.owner);
        engine.markDirty();
        Transaction loss = settle(engine, FixtureReads.empty(), now + 1_200L);

        assertEquals(TransactionType.PK_DEATH_LOSS, loss.type());
        assertEquals(Confidence.CONFIRMED, loss.confidence());
        assertEquals(-100L, loss.net());
        assertEquals(1, engine.session().pk().deaths);
        assertFalse(loss.encounterId().isEmpty());
    }

    /** Guice calls every @Inject method when it builds the engine; only setters may carry it. */
    @Test
    public void onlySettersAreInjected()
    {
        for (java.lang.reflect.Method method : Engine.class.getDeclaredMethods())
        {
            if (method.isAnnotationPresent(javax.inject.Inject.class))
            {
                assertTrue(method.getName(), method.getName().startsWith("set"));
            }
        }
    }

}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.*;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Dropped items and fired ammo stay on the paid-price record while they can still be picked up,
 * and leave it when the pickup window closes: only what nobody picked up is used up.
 */
public class GroundBasisTest
{
    private static final int BOLTS = 9140;
    private static final int DART = 807;
    private static final long WINDOW_TICKS = 300;

    static
    {
        JsonCodec.bind(new Gson());
    }

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, id == DART ? "Iron dart" : "Iron bolts",
            quantity, 10, quantity * 10, PriceSource.GRAND_EXCHANGE)));
        return flows;
    };

    private long now = 1_000L;

    private static ContainerSnapshot pack(int itemId, long quantity)
    {
        return new ContainerSnapshot(Collections.singletonMap(itemId, quantity));
    }

    private void settle(Engine engine, ContainerSnapshot snapshot)
    {
        engine.markDirty();
        for (int tick = 0; tick < 4; tick++) engine.processIfDirty(snapshot, now += 600L, null);
    }

    private void wait(Engine engine, ContainerSnapshot snapshot, long ticks)
    {
        for (long tick = 0; tick < ticks; tick++) engine.processIfDirty(snapshot, now += 600L, null);
    }

    /** Ten counted bolts (known coverage 10), then three dropped. */
    private Engine droppedThree()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(now);
        engine.setBaseline(FixtureReads.empty());
        settle(engine, pack(BOLTS, 10L));
        assertEquals(10L, EngineProbe.knownCoverageQty(engine, BOLTS));
        engine.noteDrop(BOLTS, 6);
        settle(engine, pack(BOLTS, 7L));
        Transaction drop = engine.session().transactions().get(1);
        assertEquals("Dropped", drop.note());
        assertTrue(drop.onGround());
        return engine;
    }

    @Test
    public void aDropLeavesTheRecordOnlyWhenItsPickupWindowCloses()
    {
        Engine engine = droppedThree();
        assertEquals("still on the ground", 10L, EngineProbe.knownCoverageQty(engine, BOLTS));
        wait(engine, pack(BOLTS, 7L), WINDOW_TICKS);
        assertEquals("never picked up: used up", 7L, EngineProbe.knownCoverageQty(engine, BOLTS));
        assertFalse(engine.session().transactions().get(1).onGround());
    }

    @Test
    public void aDropPickedBackUpNeverLeavesTheRecord()
    {
        Engine engine = droppedThree();
        settle(engine, pack(BOLTS, 10L));
        wait(engine, pack(BOLTS, 10L), WINDOW_TICKS);
        assertEquals(10L, EngineProbe.knownCoverageQty(engine, BOLTS));
    }

    @Test
    public void aPartPickedUpLeavesOnlyTheRest()
    {
        Engine engine = droppedThree();
        settle(engine, pack(BOLTS, 9L));
        wait(engine, pack(BOLTS, 9L), WINDOW_TICKS);
        assertEquals("one bolt stayed on the ground", 9L, EngineProbe.knownCoverageQty(engine, BOLTS));
    }

    @Test
    public void aRestartSettlesWhatWasStillOnTheGround()
    {
        Engine engine = droppedThree();
        Gson gson = JsonCodec.gson();
        SavedState saved = gson.fromJson(gson.toJson(engine.savedState()), SavedState.class);
        Engine restarted = new Engine(valuator, new TransactionClassifier(), CONFIG);
        restarted.restore(saved, now);
        assertEquals(10L, EngineProbe.knownCoverageQty(restarted, BOLTS));
        restarted.processIfDirty(pack(BOLTS, 7L), now += 600L, null);
        assertEquals("its pickup memory did not survive", 7L, EngineProbe.knownCoverageQty(restarted, BOLTS));
    }

    @Test
    public void aDropCompactedWhileOnTheGroundStillLeavesTheRecord()
    {
        Engine engine = droppedThree();
        engine.session().compactBefore(now + 1L, null);
        assertTrue(engine.session().transactions().isEmpty());
        assertEquals(7L, EngineProbe.knownCoverageQty(engine, BOLTS));
        wait(engine, pack(BOLTS, 7L), WINDOW_TICKS);
        assertEquals("settled once", 7L, EngineProbe.knownCoverageQty(engine, BOLTS));
    }

    @Test
    public void anUndoneDropNeverLeavesTheRecord()
    {
        Engine engine = droppedThree();
        assertNotNull(engine.session().undoTransaction());
        wait(engine, pack(BOLTS, 7L), WINDOW_TICKS);
        assertEquals(10L, EngineProbe.knownCoverageQty(engine, BOLTS));
    }

    @Test
    public void dartsACheckMeasuredLeaveTheRecordAtOnce()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(now);
        engine.setBaseline(FixtureReads.empty());
        settle(engine, pack(DART, 10L));
        assertEquals(10L, EngineProbe.knownCoverageQty(engine, DART));
        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.BLOWPIPE,
            Collections.singletonList(new ChargeDelta.ComponentDelta(DART, -4L)), ChargeDelta.CheckResult.SPEND);
        Transaction spent = engine.bookChargeSpend(delta, "Toxic blowpipe",
            Collections.singletonList(new Flow(DART, "Iron dart", -4L, 10, -40L, PriceSource.GRAND_EXCHANGE)),
            now, null);
        assertNotNull(spent);
        assertFalse("a measured spend is not on the ground", spent.onGround());
        assertEquals(6L, EngineProbe.knownCoverageQty(engine, DART));
    }

    @Test
    public void onlyRowsOnTheGroundCarryTheFlagInASave()
    {
        Engine engine = droppedThree();
        String json = JsonCodec.gson().toJson(engine.session());
        assertEquals("one row on the ground", 1, json.split("\"onGround\"", -1).length - 1);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner live test 2026-10-12/13: emptying an essence pouch right before an altar craft made the
 * custody evidence neutralize the whole settle, hiding the crafted runes; depositing runes at
 * the rift's deposit pool booked a bogus Cast. The pouch owns only its essence; the craft's
 * runes classify normally, and the deposit pool is a bank move.
 */
public class GuardiansOfTheRiftBookingTest
{
    private static final int ESSENCE = ItemID.GOTR_GUARDIAN_ESSENCE;
    private static final int PURE_ESSENCE = ItemID.BLANKRUNE_HIGH;
    private static final int FIRE_RUNE = ItemID.FIRERUNE;
    private static final int STONE = ItemID.GOTR_GUARDIAN_STONE_ELEMENTAL;

    private static final Map<Integer, String> NAMES = Map.of(
        ESSENCE, "Guardian essence", PURE_ESSENCE, "Pure essence", FIRE_RUNE, "Fire rune",
        STONE, "Elemental guardian stone");
    private static final Map<Integer, Integer> PRICES = Map.of(
        ESSENCE, 30, PURE_ESSENCE, 5, FIRE_RUNE, 5, STONE, 30);

    private static final String POUCH_CUSTODY = "Container empty_to_inventory (essence_pouch)";
    private static final String DEPOSIT_POOL = "Deposit pool transfer";

    private static Engine engine()
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, NAMES.get(id), quantity, PRICES.get(id),
                quantity * PRICES.get(id))));
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
        });
        engine.ensureSession(1_000_000L);
        return engine;
    }

    private static Engine settle(
        Map<Integer, Long> before, Map<Integer, Long> after, String custodyNote)
    {
        Engine engine = engine();
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(before)));
        if (custodyNote != null) engine.markContext(Context.TRANSFER, 6, custodyNote);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)), 1_000_000L + tick * 600L, null);
        }
        return engine;
    }

    @Test
    public void aCraftInThePouchCustodyStillBooksItsRunes()
    {
        // The live shape: the pouch was emptied, then the craft consumed the essence and produced
        // runes plus a guardian stone. The strip removes the minigame items (essence, stone); the
        // custody must not swallow the runes with them.
        Engine engine = settle(Map.of(ESSENCE, 1L), Map.of(FIRE_RUNE, 132L, STONE, 40L), POUCH_CUSTODY);
        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertTrue(rows.get(0).counts());
        assertEquals(132L * 5L, engine.metrics(1_010_000L).net);
    }

    @Test
    public void thePouchEmptyItselfStaysNeutral()
    {
        // Pure essence has no minigame strip: the custody removal itself keeps the move neutral.
        Engine engine = settle(Map.of(), Map.of(PURE_ESSENCE, 28L), POUCH_CUSTODY);
        assertTrue(engine.session().transactions().toString(),
            engine.session().transactions().isEmpty());
        assertEquals(0L, engine.metrics(1_010_000L).net);
    }

    @Test
    public void aMergedEmptyAndCraftSplitsIntoTheRunesOnly()
    {
        // Empty (28 essence) and craft (24 essence used) inside one window: the net essence +4 is
        // the pouch's own leftover and stays neutral; the runes are the craft's real gain.
        Engine engine = settle(Map.of(), Map.of(PURE_ESSENCE, 4L, FIRE_RUNE, 96L), POUCH_CUSTODY);
        List<Transaction> rows = engine.session().transactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertTrue(rows.get(0).counts());
        assertEquals(96L * 5L, engine.metrics(1_010_000L).net);
    }

    @Test
    public void aCraftWithoutCustodyStaysACountedGain()
    {
        // The control: with no pouch click in the window the runes were already the one gain.
        Engine engine = settle(Map.of(ESSENCE, 1L), Map.of(FIRE_RUNE, 132L, STONE, 40L), null);
        assertEquals(132L * 5L, engine.metrics(1_010_000L).net);
    }

    @Test
    public void theDepositPoolDepositBooksNoCast()
    {
        // "Deposit-runes" on the deposit pool marks a custody transfer (neutral_transfers.tsv):
        // the runes leave for the bank and nothing counts, instead of a rune-only Cast.
        Engine engine = settle(Map.of(FIRE_RUNE, 253L), Map.of(), DEPOSIT_POOL);
        assertFalse(engine.session().transactions().stream().anyMatch(Transaction::counts));
        assertEquals(0L, engine.metrics(1_010_000L).net);
    }

    @Test
    public void theDepositPoolNoteComesFromItsTableRow()
    {
        // The plugin hands the joined menu text to NeutralTransfers; the row's note is this text.
        assertEquals(DEPOSIT_POOL, NeutralTransfers.storage("Deposit-runes Deposit Pool"));
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;
import static org.junit.Assert.*;

public class HandoffAccountingReviewTest {
    private static final long NOW = 1_700_000_000_000L;
    private static final int ITEM = 1203;

    private static Engine engine() {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = new Engine(changes -> {
            var result = new ArrayList<Flow>();
            changes.forEach((id, quantity) -> result.add(new Flow(id, id == 995 ? "Coins" : "Iron dagger",
                    quantity, id == 995 ? 1 : 100, quantity * (id == 995 ? 1 : 100),
                    id == 995 ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE)));
            return result;
        }, new TransactionClassifier(), ReviewFixesTest.CONFIG);
        engine.startCustom("Handoff accounting review", NOW);
        return engine;
    }

    private static Transaction handoff(Engine engine, boolean known) {
        return handoff(engine, known, 1, 1);
    }

    private static Transaction handoff(Engine engine, boolean known, long units, long filled) {
        engine.session().addTransaction(Tx.of(NOW + 1, TransactionType.GAIN, Context.GENERIC, "", true,
                List.of(new Flow(ITEM, "Iron dagger", units, known ? 100 : 0, known ? units * 100 : 0,
                        known ? PriceSource.GRAND_EXCHANGE : PriceSource.UNPRICED))), 2000, false);
        var held = engine.basis.reserve(ITEM, units);
        var record = new GeOffer("first-sale", 0, GeOffer.Side.SELL, ITEM, "Iron dagger", units, 150,
                NOW + 2, engine.session().id());
        record.capturedQty = units;
        record.filledQty = filled;
        record.spentGp = filled * 150;
        record.basisUnitPrice = known ? 100 : 0;
        record.basisSource = known ? PriceSource.GRAND_EXCHANGE : PriceSource.UNPRICED;
        record.reservedTrackedQty = held.trackedQty;
        record.reservedTrackedBasisGp = held.basisGp;
        record.basisCapturedAtEpochMillis = NOW + 3;
        engine.exchange.records.add(record);
        engine.exchange.now = NOW + 10;
        engine.exchange.handoff(record, "Ambiguous terminal");
        var review = engine.exchange.rows.get(0);
        engine.session().addTransaction(review, 2000, false);
        return review;
    }

    @Test public void anUnresolvedCapturedSaleCannotFundTheBasisOfAnUntrackedSpare() {
        var engine = engine();
        var unresolved = handoff(engine, true);
        assertTrue(ReviewRules.needsReview(unresolved));
        assertFalse("the captured share stays with its Review", engine.basis.known(ITEM).availableQty > 0);
        // Only the pre-existing, untracked spare remains in the carried inventory.
        engine.setBaseline(new ContainerSnapshot(Map.of(ITEM, 1L, 995, 10_000L)));
        var slots = new OfferSlots();
        slots.observe(new OfferSlots.Snapshot(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0));
        engine.noteGeOffer(slots.observe(new OfferSlots.Snapshot(1, GrandExchangeOfferState.SELLING,
                ITEM, 1, 0, 150, 0)).get(), "Iron dagger", NOW + 600);
        settle(engine, Map.of(995, 10_000L), NOW + 1200);
        engine.noteGeOffer(slots.observe(new OfferSlots.Snapshot(1, GrandExchangeOfferState.SOLD,
                ITEM, 1, 1, 150, 147)).get(), "Iron dagger", NOW + 3600);
        settle(engine, Map.of(995, 10_147L), NOW + 4200);
        var sale = engine.marketRows().get(0);
        assertTrue(ReviewRules.needsReview(unresolved));
        assertEquals("the first captured sale's share is not available to this spare", 0, sale.trackedBasisConsumedGp);
        assertEquals("this fixture has no independently proven tax", 0, sale.realizedResultGp);
        assertEquals("this fixture has no independently proven tax", 100, engine.metrics(NOW + 6000).net);
    }

    @Test public void resolvingAHandoffConsumesOnlyItsOwnShare() {
        var engine = engine();
        var unresolved = handoff(engine, true);
        assertEquals(0, engine.basis.known(ITEM).availableQty);
        engine.basis.release(ITEM, 1, 0);
        assertTrue(engine.correctTransaction(unresolved.id(), Correction.COST, "Owner decision"));
        assertEquals("unrelated free stock is not consumed", 1, engine.basis.known(ITEM).availableQty);
        assertEquals("unrelated free stock is not consumed", 0, engine.basis.known(ITEM).availableBasisGp);
    }

    @Test public void partialFillsKeepUnreturnedStockUnavailable() {
        var engine = engine();
        var unresolved = handoff(engine, true, 2, 1);
        assertEquals("an unfilled counter is not a proven return", 0, engine.basis.known(ITEM).availableQty);
        assertEquals(0, engine.basis.known(ITEM).availableBasisGp);
        assertTrue(engine.correctTransaction(unresolved.id(), Correction.REVENUE, "Owner decision"));
        assertEquals("the decision cannot return unobserved stock", 0,
                engine.basis.known(ITEM).availableQty);
        assertEquals(0, engine.basis.known(ITEM).availableBasisGp);
    }

    @Test public void knownZeroAndUnknownSharesNeverConsumeFreeStock() {
        var zero = engine();
        zero.basis.release(ITEM, 1, 0);
        var zeroReview = zeroHandoff(zero);
        zero.basis.release(ITEM, 1, 100);
        zero.basis.known(ITEM).acquiredAt = NOW;
        assertTrue(zero.correctTransaction(zeroReview.id(), Correction.REVENUE, "Owner decision"));
        assertEquals("known-zero coverage consumes nothing", 1, zero.basis.known(ITEM).availableQty);
        assertEquals(100, zero.basis.known(ITEM).availableBasisGp);

        var unknown = engine();
        var unknownReview = unknownHandoff(unknown);
        unknown.basis.release(ITEM, 1, 100);
        unknown.basis.known(ITEM).acquiredAt = NOW;
        assertTrue(unknown.correctTransaction(unknownReview.id(), Correction.REVENUE, "Owner decision"));
        assertEquals("unknown coverage consumes nothing", 1, unknown.basis.known(ITEM).availableQty);
        assertEquals(100, unknown.basis.known(ITEM).availableBasisGp);
    }

    private static Transaction zeroHandoff(Engine engine) {
        var held = engine.basis.reserve(ITEM, 1);
        return review(engine, "zero-sale", 1, held.trackedQty, held.basisGp, PriceSource.NO_VALUE);
    }

    private static Transaction unknownHandoff(Engine engine) {
        return review(engine, "unknown-sale", 1, 0, 0, PriceSource.UNPRICED);
    }

    private static Transaction review(Engine engine, String offerId, long units, long trackedQty, long trackedBasis,
            PriceSource source) {
        var record = new GeOffer(offerId, 0, GeOffer.Side.SELL, ITEM, "Iron dagger", units, 150,
                NOW + 2, engine.session().id());
        record.capturedQty = record.filledQty = units;
        record.spentGp = units * 150;
        record.basisUnitPrice = source == PriceSource.NO_VALUE ? 0 : 100;
        record.basisSource = source;
        record.reservedTrackedQty = trackedQty;
        record.reservedTrackedBasisGp = trackedBasis;
        record.basisCapturedAtEpochMillis = NOW + 3;
        engine.exchange.records.add(record);
        engine.exchange.now = NOW + 10;
        engine.exchange.handoff(record, "Ambiguous terminal");
        var review = engine.exchange.rows.get(0);
        engine.session().addTransaction(review, 2000, false);
        return review;
    }

    @Test public void aBatchMustNotSpendCoverageAcquiredAfterTheHandoff() {
        batch(true);
    }

    @Test public void chronologicalBatchControlRetainsTheLaterAcquisition() {
        batch(false);
    }

    private static void batch(boolean newestFirst) {
        var engine = engine();
        var earlier = handoff(engine, false);
        var later = Tx.of(NOW + 20, TransactionType.UNCERTAIN, Context.GENERIC, "", false,
                List.of(new Flow(ITEM, "Iron dagger", 1, 100, 100, PriceSource.GRAND_EXCHANGE)));
        engine.session().addTransaction(later, 2000, false);
        assertTrue(engine.session().canCorrect(earlier, Correction.REVENUE));
        assertTrue(engine.session().canCorrect(later, Correction.REVENUE));
        long before = engine.metrics(NOW + 30).net;
        boolean applied = engine.correctEntries(newestFirst ? List.of(later.id(), earlier.id())
                : List.of(earlier.id(), later.id()), Correction.REVENUE);
        var pool = engine.basis.known(ITEM);
        if (applied) {
            assertEquals("the later acquisition is still held after both financial choices", 1, pool.availableQty);
            assertEquals(100, pool.availableBasisGp);
        } else {
            assertEquals("an unsafe batch must refuse without changing money", before, engine.metrics(NOW + 30).net);
            assertEquals(Correction.AUTO, earlier.correction());
            assertEquals(Correction.AUTO, later.correction());
        }
    }

    @Test public void safeBatchAppliesCanonicalOrderWithOneGroupedUndo() {
        var engine = engine();
        var first = uncertain(NOW + 10, 1, 100, 100);
        var second = uncertain(NOW + 20, 1, 200, 200);
        engine.session().addTransaction(first, 2000, false);
        engine.session().addTransaction(second, 2000, false);
        var preview = engine.previewDecision(Decision.GAIN, row -> true, NOW + 30);
        assertEquals(2, preview.rowCount());
        assertEquals(300, preview.netDelta);
        int history = engine.session().correctionHistory.size();
        assertEquals(2, engine.applyDecision(preview));
        assertEquals("application matches the previewed Net", 300, engine.metrics(NOW + 30).net);
        assertEquals(history + 1, engine.session().correctionHistory.size());
        assertEquals("one grouped undo unit", 2, engine.session().latestCorrection().changes().size());
        assertTrue(engine.undoCorrection());
        assertEquals(0, engine.metrics(NOW + 31).net);
        assertEquals(Correction.AUTO, first.correction());
        assertEquals(Correction.AUTO, second.correction());
    }

    @Test public void anUnsafeBatchRefusesAtomicallyAndLogsNoUndo() {
        var engine = engine();
        engine.session().addTransaction(Tx.of(NOW + 1, TransactionType.GAIN, Context.GENERIC, "", true,
                List.of(new Flow(ITEM, "Iron dagger", 1, 100, 100, PriceSource.GRAND_EXCHANGE))), 2000, false);
        var blocked = uncertain(NOW + 10, -1, 100, -100);
        var eligible = uncertain(NOW + 15, 1, 50, 50);
        engine.session().addTransaction(blocked, 2000, false);
        engine.session().addTransaction(eligible, 2000, false);
        engine.session().addTransaction(Tx.of(NOW + 20, TransactionType.GAIN, Context.GENERIC, "", true,
                List.of(new Flow(ITEM, "Iron dagger", 1, 100, 100, PriceSource.GRAND_EXCHANGE))), 2000, false);
        assertFalse("the later acquisition blocks this Review", engine.session().canCorrect(blocked, Correction.COST));
        assertTrue(engine.session().canCorrect(eligible, Correction.COST));
        var preview = engine.previewDecision(Decision.COST, row -> true, NOW + 30);
        assertEquals("preview refuses the same unsafe batch", 0, preview.rowCount());
        assertEquals(0, preview.netDelta);
        long net = engine.metrics(NOW + 30).net;
        int undo = engine.session().correctionHistory.size();
        for (var ids : List.of(List.of(blocked.id(), eligible.id()), List.of(eligible.id(), blocked.id()))) {
            assertFalse(engine.correctEntries(ids, Correction.COST));
            assertEquals(net, engine.metrics(NOW + 30).net);
            assertEquals(undo, engine.session().correctionHistory.size());
            assertEquals(Correction.AUTO, blocked.correction());
            assertEquals(Correction.AUTO, eligible.correction());
            assertEquals(2, engine.basis.known(ITEM).availableQty);
            assertEquals(200, engine.basis.known(ITEM).availableBasisGp);
        }
    }

    @Test public void savedAndDetachedCoverageKeepHeldShareOwnership() {
        var engine = engine();
        var review = handoff(engine, true);
        var saved = SaveCopies.copy(engine.savedState());
        assertTrue(engine.correctTransaction(review.id(), Correction.COST, "Live decision"));
        var json = new com.google.gson.Gson().toJson(saved);
        var restored = engine();
        restored.restore(new com.google.gson.Gson().fromJson(json, SavedState.class), NOW + 100);
        var restoredReview = restored.session().findTransaction(review.id());
        assertTrue(restored.session().canCorrect(restoredReview, Correction.COST));
        assertEquals(0, restored.basis.known(ITEM).availableQty);
        assertTrue(restored.correctTransaction(review.id(), Correction.COST, "Detached decision"));
        assertEquals(0, restored.basis.known(ITEM).availableQty);
        assertEquals(0, restored.basis.known(ITEM).availableBasisGp);
    }

    @Test public void forecastMatchesTheAppliedHandoffDecision() {
        var engine = engine();
        var review = handoff(engine, true);
        var forecasts = engine.reviewNets(review.id());
        assertTrue(forecasts.containsKey(Decision.GAIN));
        assertTrue(engine.correctTransaction(review.id(), Correction.REVENUE, "Owner decision"));
        assertEquals((long) forecasts.get(Decision.GAIN), engine.metrics(NOW + 20).net);
    }

    private static Transaction uncertain(long at, long quantity, long unit, long value) {
        return new Transaction(at, TransactionType.UNCERTAIN, Context.GENERIC, "", "Review", false,
                List.of(new Flow(ITEM, "Iron dagger", quantity, unit, value, PriceSource.GRAND_EXCHANGE)),
                Confidence.UNCERTAIN, "Review", null);
    }

    private static void settle(Engine engine, Map<Integer, Long> inventory, long at) {
        engine.markDirty();
        for (int tick = 0; tick < 3; tick++)
            engine.processIfDirty(new ContainerSnapshot(inventory), at + tick * 600, null);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;
import static org.junit.Assert.*;

public class HandoffOwnershipGuardTest {
    private static final long NOW = 1_700_000_000_000L;
    private static final int ITEM = 1203;
    private static final long FOUR = 4_000_000_000_000_000_000L;

    private static Engine engine() {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = new Engine(changes -> {
            var flows = new ArrayList<Flow>();
            changes.forEach((id, qty) -> flows.add(new Flow(id, id == 995 ? "Coins" : "Iron dagger", qty,
                    id == 995 ? 1 : 100, qty * (id == 995 ? 1 : 100),
                    id == 995 ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE)));
            return flows;
        }, new TransactionClassifier(), ReviewFixesTest.CONFIG);
        engine.startCustom("Further accounting review", NOW);
        return engine;
    }

    private static Transaction gain(Engine engine, long at, long qty, long value) {
        var row = Tx.of(at, TransactionType.GAIN, Context.GENERIC, "", true,
                List.of(new Flow(ITEM, "Iron dagger", qty, value / qty, value, PriceSource.MANUAL_OVERRIDE)));
        engine.session().addTransaction(row, 2000, false);
        return row;
    }

    private static GeOffer handoff(Engine engine, long filled) {
        return handoff(engine, filled, 0);
    }

    private static GeOffer handoff(Engine engine, long filled, long returned) {
        gain(engine, NOW + 1, 2, 200);
        var held = engine.basis.reserve(ITEM, 2);
        var record = new GeOffer("lost-lineage", 0, GeOffer.Side.SELL, ITEM, "Iron dagger", 2, 150,
                NOW + 2, engine.session().id());
        record.capturedQty = 2;
        record.filledQty = filled;
        record.spentGp = filled * 150;
        record.basisUnitPrice = 100;
        record.basisSource = PriceSource.GRAND_EXCHANGE;
        record.reservedTrackedQty = held.trackedQty;
        record.reservedTrackedBasisGp = held.basisGp;
        record.basisCapturedAtEpochMillis = NOW + 3;
        record.confidence = GeOffer.CustodyConfidence.AMBIGUOUS;
        engine.exchange.records.add(record);
        engine.exchange.releaseShare(record, returned);
        record.returnedQty = returned;
        engine.exchange.now = NOW + 10;
        var previous = new OfferSlots.Snapshot(0, GrandExchangeOfferState.SELLING, ITEM, 2, (int) filled,
                150, (int) (filled * 150));
        engine.exchange.baseline.put(0, previous);
        engine.exchange.observe(previous, new OfferSlots.Snapshot(0, GrandExchangeOfferState.SELLING,
                882, 1, 0, 10, 0), "Bronze arrow");
        for (var review : engine.exchange.rows) engine.session().addTransaction(review, 2000, false);
        assertEquals("only the explicitly observed return is retained", returned, record.returnedQty);
        return record;
    }

    private static void sellUntrackedSpare(Engine engine) {
        engine.setBaseline(new ContainerSnapshot(Map.of(ITEM, 1L, 995, 10_000L)));
        var slots = new OfferSlots();
        slots.observe(new OfferSlots.Snapshot(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0));
        engine.noteGeOffer(slots.observe(new OfferSlots.Snapshot(1, GrandExchangeOfferState.SELLING,
                ITEM, 1, 0, 150, 0)).get(), "Iron dagger", NOW + 600);
        settle(engine, Map.of(995, 10_000L), NOW + 1200);
        engine.noteGeOffer(slots.observe(new OfferSlots.Snapshot(1, GrandExchangeOfferState.SOLD,
                ITEM, 1, 1, 150, 147)).get(), "Iron dagger", NOW + 3600);
        settle(engine, Map.of(995, 10_147L), NOW + 4200);
        var sale = engine.marketRows().stream().filter(row -> row.itemId == ITEM).findFirst().get();
        System.out.println("spare basis=" + sale.trackedBasisConsumedGp + " result=" + sale.realizedResultGp
                + " net=" + engine.metrics(NOW + 6000).net);
        assertEquals("unreturned custody basis is unavailable to the spare", 0, sale.trackedBasisConsumedGp);
        assertEquals("the fixture has no independently proven tax", 200, engine.metrics(NOW + 6000).net);
    }

    private static void settle(Engine engine, Map<Integer, Long> inventory, long at) {
        engine.markDirty();
        for (int tick = 0; tick < 3; tick++) engine.processIfDirty(new ContainerSnapshot(inventory), at + tick * 600, null);
    }

    @Test public void unfilledCapturedStockIsNotAProvenReturn() {
        var engine = engine();
        handoff(engine, 0);
        sellUntrackedSpare(engine);
    }

    @Test public void aPartialHandoffCannotReleaseUnreturnedUnfilledStock() {
        var engine = engine();
        handoff(engine, 1);
        sellUntrackedSpare(engine);
    }

    @Test public void keepingUnreturnedStockUnavailableLeavesTheSpareUnknown() {
        var engine = engine();
        handoff(engine, 1);
        engine.basis.reserve(ITEM, 1);
        sellUntrackedSpare(engine);
    }

    @Test public void saturationCannotLoseRemainingBasisWhenAGainBecomesACost() {
        var engine = engine();
        var first = gain(engine, NOW + 1, 1, FOUR);
        gain(engine, NOW + 2, 1, FOUR);
        gain(engine, NOW + 3, 1, FOUR);
        assertEquals(Long.MAX_VALUE, engine.basis.known(ITEM).availableBasisGp);
        assertFalse("lost saturation must refuse before changing the receipt", engine.correctTransaction(
                first.id(), Correction.COST, "Owner decision"));
        assertEquals(Correction.AUTO, first.correction());
        assertEquals(Long.MAX_VALUE, engine.metrics(NOW + 20).net);
        assertEquals(Long.MAX_VALUE, engine.basis.known(ITEM).availableBasisGp);
        assertTrue(engine.session().correctionHistory.isEmpty());
    }

    @Test public void aBatchCannotSubtractLostSaturationFromTheRemainingAcquisition() {
        var engine = engine();
        var first = gain(engine, NOW + 1, 1, FOUR);
        var second = gain(engine, NOW + 2, 1, FOUR);
        gain(engine, NOW + 3, 1, FOUR);
        for (var ids : List.of(List.of(second.id(), first.id()), List.of(first.id(), second.id()))) {
            assertFalse("saturation must refuse the complete batch", engine.correctEntries(ids, Correction.COST));
            assertEquals(Correction.AUTO, first.correction());
            assertEquals(Correction.AUTO, second.correction());
            assertEquals(Long.MAX_VALUE, engine.metrics(NOW + 20).net);
            assertEquals(Long.MAX_VALUE, engine.basis.known(ITEM).availableBasisGp);
            assertTrue(engine.session().correctionHistory.isEmpty());
        }
    }

    @Test public void ordinaryCorrectionControlRetainsOtherCountedAcquisitions() {
        var engine = engine();
        var first = gain(engine, NOW + 1, 1, 100);
        gain(engine, NOW + 2, 1, 100);
        gain(engine, NOW + 3, 1, 100);
        assertTrue(engine.correctTransaction(first.id(), Correction.COST, "Owner decision"));
        assertEquals(200, engine.basis.known(ITEM).availableBasisGp);
    }

    private static Transaction uncertain(Engine engine, String id, long quantity) {
        var row = new Transaction(NOW + 10, TransactionType.UNCERTAIN, Context.GENERIC, "", "Review", false,
                List.of(new Flow(ITEM, "Iron dagger", quantity, 100, quantity * 100, PriceSource.GRAND_EXCHANGE)),
                Confidence.UNCERTAIN, "Review", null);
        row.id = id;
        engine.session().addTransaction(row, 2000, false);
        return row;
    }

    @Test public void aBatchCannotIntroduceCoverageAfterItsOwnSameTimeSinkFence() {
        var engine = engine();
        var sink = uncertain(engine, "a-sink", -1);
        var gain = uncertain(engine, "b-gain", 1);
        assertTrue(engine.session().canCorrect(sink, Correction.REVENUE));
        assertTrue(engine.session().canCorrect(gain, Correction.REVENUE));
        long net = engine.metrics(NOW + 20).net;
        int history = engine.session().correctionHistory.size();
        var preview = engine.previewDecision(Decision.GAIN, row -> true, NOW + 20);
        boolean applied = engine.correctEntries(List.of(gain.id(), sink.id()), Correction.REVENUE);
        System.out.println("same-time batch applied=" + applied + " preview rows=" + preview.rowCount()
                + " net=" + engine.metrics(NOW + 20).net + " basis=" + engine.basis.known(ITEM).availableBasisGp);
        assertFalse("the projected sink invalidates the acquisition before any mutation", applied);
        assertEquals(0, preview.rowCount());
        assertEquals(net, engine.metrics(NOW + 20).net);
        assertEquals(history, engine.session().correctionHistory.size());
    }

    @Test public void sequentialSameTimeControlRejectsTheAcquisitionAfterTheSink() {
        var engine = engine();
        var sink = uncertain(engine, "a-sink", -1);
        var gain = uncertain(engine, "b-gain", 1);
        assertTrue(engine.correctTransaction(sink.id(), Correction.REVENUE, "First owner decision"));
        assertFalse(engine.session().canCorrect(gain, Correction.REVENUE));
        assertFalse(engine.correctTransaction(gain.id(), Correction.REVENUE, "Second owner decision"));
        assertEquals(0, engine.basis.known(ITEM).availableBasisGp);
    }

    @Test public void provenPartialReturnRemainsAvailableAfterTheHandoffAndDecision() {
        var engine = engine();
        handoff(engine, 1, 1);
        assertEquals(1, engine.basis.known(ITEM).availableQty);
        assertEquals(100, engine.basis.known(ITEM).availableBasisGp);
        var review = engine.session().transactions().stream().filter(ReviewRules::needsReview).findFirst().get();
        assertTrue(engine.correctTransaction(review.id(), Correction.COST, "Owner decision"));
        assertEquals(1, engine.basis.known(ITEM).availableQty);
        assertEquals(100, engine.basis.known(ITEM).availableBasisGp);
    }

    @Test public void aProvenFullReturnReleasesTheWholeReservationWithoutReview() {
        var engine = engine();
        handoff(engine, 0, 2);
        assertTrue(engine.session().transactions().stream().noneMatch(ReviewRules::needsReview));
        var returned = engine.basis.reserve(ITEM, 2);
        assertEquals(2, returned.trackedQty);
        assertEquals(200, returned.basisGp);
    }

    @Test public void batchProjectionDoesNotSpendLiveOrDetachedHandoffIdentities() {
        var engine = engine();
        handoff(engine, 1);
        var review = engine.session().transactions().stream().filter(ReviewRules::needsReview).findFirst().get();
        var gson = new com.google.gson.Gson();
        var before = gson.toJson(engine.basis.stock);
        var saved = SaveCopies.copy(engine.savedState());
        long revision = engine.revision();
        Engine.DecisionPreview preview = null;
        for (int count = 0; count < 3; count++) {
            preview = engine.previewDecision(Decision.GAIN, row -> row.transaction.equals(review.id()), NOW + 20);
            assertEquals(1, preview.rowCount());
            assertEquals(before, gson.toJson(engine.basis.stock));
            assertTrue(review.handoffHeld);
            assertEquals(Correction.AUTO, review.correction());
            assertEquals(revision, engine.revision());
        }
        assertEquals(1, engine.applyDecision(preview));
        assertFalse(review.handoffHeld);
        var restored = engine();
        restored.restore(saved, NOW + 100);
        var detached = restored.session().findTransaction(review.id());
        assertTrue(detached.handoffHeld);
        assertTrue(restored.correctTransaction(detached.id(), Correction.COST, "Detached owner"));
        assertEquals(0, restored.basis.known(ITEM).availableQty);
    }

    @Test public void saturationRefusalSurvivesReloadAndDoesNotBlockFinancialRemoval() {
        var engine = engine();
        var first = gain(engine, NOW + 1, 1, FOUR);
        gain(engine, NOW + 2, 1, FOUR);
        gain(engine, NOW + 3, 1, FOUR);
        var restored = engine();
        restored.restore(SaveCopies.copy(engine.savedState()), NOW + 100);
        assertFalse(restored.correctTransaction(first.id(), Correction.COST, "Unsafe inverse"));
        assertEquals(Long.MAX_VALUE, restored.basis.known(ITEM).availableBasisGp);
        assertTrue("financial removal retains its physical booking", restored.correctEntries(
                List.of(first.id()), Correction.IGNORE));
        assertEquals(Long.MAX_VALUE, restored.basis.known(ITEM).availableBasisGp);
        assertTrue(restored.undoCorrection());
        assertEquals(Long.MAX_VALUE, restored.metrics(NOW + 101).net);
    }

    @Test public void undoCannotSubtractTheLostExcessOfASaturatingDecision() {
        var engine = engine();
        gain(engine, NOW + 1, 1, FOUR);
        gain(engine, NOW + 2, 1, FOUR);
        var last = new Transaction(NOW + 3, TransactionType.UNCERTAIN, Context.GENERIC, "", "Review", false,
                List.of(new Flow(ITEM, "Iron dagger", 1, FOUR, FOUR, PriceSource.MANUAL_OVERRIDE)),
                Confidence.UNCERTAIN, "Review", null);
        engine.session().addTransaction(last, 2000, false);
        assertTrue(engine.correctTransaction(last.id(), Correction.REVENUE, "Count gain"));
        assertFalse(engine.undoCorrection());
        assertEquals(Correction.REVENUE, last.correction());
        assertEquals(Long.MAX_VALUE, engine.basis.known(ITEM).availableBasisGp);
        var restored = engine();
        restored.restore(SaveCopies.copy(engine.savedState()), NOW + 100);
        assertFalse(restored.undoCorrection());
        assertEquals(Long.MAX_VALUE, restored.basis.known(ITEM).availableBasisGp);
    }

    @Test public void saturatedQuantityCannotBeShrunkByAnUnprovableInverse() {
        var engine = engine();
        gain(engine, NOW + 1, Long.MAX_VALUE, 0);
        gain(engine, NOW + 2, 3, 0);
        assertFalse(engine.basis.canApply(ITEM, -1, 0, NOW + 10));
        assertEquals(Long.MAX_VALUE, engine.basis.known(ITEM).availableQty);
        assertTrue(engine.basis.canApply(ITEM, 1, 0, NOW + 10));
    }

    @Test public void fullyUnfilledHandoffRemainsUnavailableAfterReload() {
        var engine = engine();
        handoff(engine, 0);
        var restored = engine();
        restored.restore(SaveCopies.copy(engine.savedState()), NOW + 100);
        assertEquals(0, restored.basis.reserve(ITEM, 2).trackedQty);
        assertEquals(200, restored.metrics(NOW + 200).net);
    }

    @Test public void aNeutralDecisionKeepsTheHeldShareForItsLaterFinancialDecision() {
        var engine = engine();
        handoff(engine, 1);
        var review = engine.session().transactions().stream().filter(ReviewRules::needsReview).findFirst().get();
        assertTrue(engine.correctTransaction(review.id(), Correction.TRANSFER, "Neutral decision"));
        assertTrue(review.handoffHeld);
        engine.basis.release(ITEM, 1, 50);
        assertTrue(engine.correctTransaction(review.id(), Correction.REVENUE, "Financial decision"));
        assertFalse(review.handoffHeld);
        assertEquals(1, engine.basis.known(ITEM).availableQty);
        assertEquals(50, engine.basis.known(ITEM).availableBasisGp);
        long fence = engine.basis.known(ITEM).fencedAt;
        assertEquals(0, engine.basis.deplete(ITEM, 0, NOW + 100));
        assertEquals(fence, engine.basis.known(ITEM).fencedAt);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.EnumSet;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.api.WorldType;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-11-07: a Hardcore Worlds character only ever plays Hardcore Worlds, so GP Manager
 * tracks it with that economy's own prices: an item's alch value until the player trades it on the
 * Hardcore GE, then the price that fill paid per item. Main worlds never read those prices, and
 * Deadman, Leagues and the other special worlds stay paused.
 */
public class HardcoreWorldPricesTest
{
    static final int WHIP = 4151, TRINKET = 1234, MAIN_QUOTE = 2_000_000;

    static ItemComposition definition(int id)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[]{ItemComposition.class}, (proxy, method, args) -> {
                switch (method.getName())
                {
                    case "getName": return id == WHIP ? "Abyssal whip" : "Trinket";
                    case "getId": return id;
                    case "getHaPrice": return id == WHIP ? 72_000 : 0;
                    case "isTradeable": return true;
                    default: return method.getReturnType() == boolean.class ? false
                        : method.getReturnType() == int.class ? 0 : null;
                }
            });
    }

    static Valuation valuation(Valuation.Economy economy)
    {
        return new Valuation(new GpManagerConfig() {}, HardcoreWorldPricesTest::definition,
            (id, active) -> MAIN_QUOTE, id -> false, economy);
    }

    static Flow value(Valuation valuation, int id)
    {
        return valuation.value(Map.of(id, 1L), 1_000L).get(0);
    }

    @Test
    public void hardcoreWorldsAreTheirOwnEconomyWhileOtherModesStayPaused()
    {
        assertEquals(Valuation.Economy.HARDCORE,
            Valuation.economyFor(EnumSet.of(WorldType.MEMBERS, WorldType.HARDCORE_MAIN)));
        for (WorldType paused : new WorldType[] {WorldType.DEADMAN, WorldType.SEASONAL, WorldType.QUEST_SPEEDRUNNING,
            WorldType.BETA_WORLD, WorldType.TOURNAMENT_WORLD, WorldType.NOSAVE_MODE})
        {
            assertEquals(paused.name(), Valuation.Economy.UNSUPPORTED_SPECIAL,
                Valuation.economyFor(EnumSet.of(WorldType.MEMBERS, paused)));
        }
        assertEquals(Valuation.Economy.NORMAL, Valuation.economyFor(EnumSet.of(WorldType.MEMBERS)));
    }

    @Test
    public void anItemNeverTradedOnAHardcoreWorldTakesItsAlchValueNotTheMainGamePrice()
    {
        Flow whip = value(valuation(Valuation.Economy.HARDCORE), WHIP);
        assertEquals(72_000L, whip.unitPrice);
        assertEquals(PriceSource.HIGH_ALCHEMY, whip.source());
        Flow trinket = value(valuation(Valuation.Economy.HARDCORE), TRINKET);
        assertEquals("no alch value and no trade: worth nothing", 0L, trinket.unitPrice);
        assertEquals(PriceSource.NO_VALUE, trinket.source());
    }

    @Test
    public void aHardcoreGeFillTeachesThatItemsPriceForLaterDrops()
    {
        Valuation valuation = valuation(Valuation.Economy.HARDCORE);
        assertTrue(valuation.learn(WHIP, 5_000_000L, 2));
        Flow whip = value(valuation, WHIP);
        assertEquals("the fill's price per item", 2_500_000L, whip.unitPrice);
        assertEquals(PriceSource.GRAND_EXCHANGE, whip.source());
        assertTrue(valuation.learn(WHIP, 2_400_000L, 1));
        assertEquals("the latest fill wins", 2_400_000L, value(valuation, WHIP).unitPrice);
    }

    @Test
    public void mainWorldsNeverReadHardcorePricesAndOnlyHardcoreFillsTeach()
    {
        Valuation valuation = valuation(Valuation.Economy.HARDCORE);
        valuation.learn(WHIP, 5_000_000L, 2);
        valuation.setEconomy(Valuation.Economy.NORMAL);
        assertEquals((long) MAIN_QUOTE, value(valuation, WHIP).unitPrice);
        assertFalse("a main-world fill teaches nothing", valuation.learn(TRINKET, 900L, 1));
        valuation.setEconomy(Valuation.Economy.UNSUPPORTED_SPECIAL);
        assertFalse("a Deadman fill teaches nothing", valuation.learn(TRINKET, 900L, 1));
        valuation.setEconomy(Valuation.Economy.HARDCORE);
        assertFalse("an empty slot teaches nothing", valuation.learn(TRINKET, 0L, 0));
        assertEquals(Map.of(WHIP, 2_500_000L), valuation.learned);
    }

    /** The same measured death wipe: deleted (a counted loss) on a Hardcore World, gravestone storage elsewhere. */
    @Test
    public void aHardcoreDeathBooksWhatTheGravestoneDeletedAsALoss()
    {
        for (Valuation.Economy economy : new Valuation.Economy[] {Valuation.Economy.HARDCORE, Valuation.Economy.NORMAL})
        {
            Valuation valuation = valuation(economy);
            Engine engine = new Engine(valuation, new TransactionClassifier(), new GpManagerConfig() {});
            engine.ensureSession(1_000L);
            Flow whip = valuation.value(Map.of(WHIP, -1L), 1_000L).get(0);
            engine.death.onPvmDeath(Map.of(WHIP, 1L), valuation.hardcore());
            Transaction row = engine.deathWipeTransfer(new java.util.ArrayList<>(java.util.List.of(whip)), Map.of(WHIP, 1L), 2_000L);
            boolean hardcore = economy == Valuation.Economy.HARDCORE;
            assertEquals(economy.name(), hardcore, row.counts());
            if (hardcore)
            {
                assertEquals("Death: PvE", row.note());
                assertEquals(GameData.msg("hardcoreDeleted"), row.explanation());
                assertEquals("the whip at its alch value is gone", -72_000L, engine.metrics(3_000L).net);
            }
            else
            {
                assertEquals("main-world gravestone items stay owned", 0L, engine.metrics(3_000L).net);
            }
        }
    }

    @Test
    public void learnedPricesRoundTripThroughTheHiddenSetting() throws Exception
    {
        Valuation valuation = valuation(Valuation.Economy.HARDCORE);
        valuation.learn(WHIP, 5_000_000L, 2);
        valuation.learn(TRINKET, 900L, 3);
        assertEquals(valuation.learned, ItemRuleParser.parsePriceOverrides(valuation.learned()));
        ConfigItem item = GpManagerConfig.class.getMethod("hardcorePrices").getAnnotation(ConfigItem.class);
        assertEquals("the key the plugin writes", "hardcorePrices", item.keyName());
        assertTrue(item.hidden());
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.3 (in-game test): a herb box is worth nothing until opened, like a reward casket. Each
 * Take-one counts its herb; Bank-all only says how many went to the bank, so it counts nothing.
 */
public class HerbBoxTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(id == ItemID.NZONE_HERBBOX
            ? new Flow(id, "Herb box", quantity, 0, 0L, PriceSource.DEFERRED_CLAIM, 0L)
            : new Flow(id, "Grimy marrentill", quantity, 228, quantity * 228)));
        return flows;
    };

    @Test
    public void theBoxIsAClaimUntilOpened()
    {
        assertTrue(GameData.pattern("clue").matcher("herb box").matches());
        assertTrue(ActionReader.isClaim("Herb box"));
    }

    @Test
    public void everyTakeOneCountsItsHerbWithoutReview()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(1L, 0L));
        assertEquals(TransactionType.GAIN, settle(engine, snapshot(1L, 1L), 1_600L).type());
        assertEquals("the last herb empties the box", TransactionType.GAIN, settle(engine, snapshot(0L, 2L), 6_000L).type());
        assertEquals(456L, engine.metrics(20_000L).net);
        assertEquals(0, engine.getReviewRows(20_000L).size());
    }

    private static ContainerSnapshot snapshot(long boxes, long herbs)
    {
        Map<Integer, Long> held = new HashMap<>();
        if (boxes > 0) held.put(ItemID.NZONE_HERBBOX, boxes);
        if (herbs > 0) held.put(ItemID.UNIDENTIFIED_MARENTILL, herbs);
        return new ContainerSnapshot(held);
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        Transaction row = null;
        for (long t = firstTick; row == null && t < firstTick + 4_000L; t += 600L) row = engine.processIfDirty(snapshot, t, null);
        return row;
    }
}

package com.gpmanager;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.gameval.ItemID;
import net.runelite.http.api.item.ItemPrice;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * An open herb sack takes herbs harvested from a patch or a herbiboar, and herbs picked up, without
 * the inventory changing. The game prints one SPAM line per herb (RuneLite Loot Tracker's herbiboar
 * handler and test, Dude Where's My Stuff, Farming Run Profit): that line books it, once, whichever
 * of it and a picked-up herb's despawn arrives first. An open seed box names the seeds it takes from a
 * drop or a pickpocket (Dude Where's My Stuff, GIM Hub, GP Per Hour), and an open coal bag takes mined
 * coal (OSRS Wiki: Coal bag), counted only when it did not reach the inventory.
 */
public class HerbSackHarvestTest
{
    private static final int RANARR = ItemID.UNIDENTIFIED_RANARR, SEED = ItemID.RANARR_SEED;
    private static final int FOX_FUR = ItemID.HUNTING_FENNECFOX_FUR, FOX_MEAT = ItemID.HUNTING_FENNECFOX_MEAT,
        LARUPIA_MEAT = ItemID.HUNTING_LARUPIA_MEAT, LARUPIA_FUR = ItemID.HUNTING_FUR_JAGUAR_PERFECT;
    private static final Map<Integer, String> NAMES = Map.of(RANARR, "Grimy ranarr weed", SEED, "Ranarr seed",
        ItemID.COAL, "Coal", ItemID.UNCUT_RUBY, "Uncut ruby", FOX_FUR, "Fox fur", FOX_MEAT, "Raw pyre fox",
        LARUPIA_MEAT, "Raw larupia", LARUPIA_FUR, "Larupia fur");
    private static final String LINE = "You put the Grimy ranarr weed herb into your herb sack.";

    private final int[] tick = {10};

    private ReviewFixesTest.Plugin plugin(int... carried)
    {
        Engine engine = ReviewFixesTest.engine();
        ReviewFixesTest.Plugin p = ReviewFixesTest.plugin(engine, tick);
        Item[] items = new Item[carried.length];
        for (int i = 0; i < carried.length; i++) items[i] = new Item(carried[i], 1);
        ItemContainer pack = ReviewFixesTest.proxy(ItemContainer.class, Map.of("getItems", items));
        Map<String, Object> client = new HashMap<>();
        client.put("getTickCount", (java.util.function.IntSupplier) () -> tick[0]);
        client.put("getGameState", GameState.LOGGED_IN);
        client.put("getItemContainer", pack);
        client.put("getLocalPlayer", ReviewFixesTest.proxy(Player.class,
            Collections.singletonMap("getWorldLocation", new WorldPoint(100, 100, 0))));
        p.client = ReviewFixesTest.proxy(Client.class, client);
        p.containers = new ContainerSnapshotFactory(p.client, null)
        {
            @Override ContainerSnapshot capture(boolean equipment, boolean pouch) { return FixtureReads.empty(); }
        };
        p.lookup = new ItemLookup(null)
        {
            @Override ItemComposition composition(int id)
            {
                return ReviewFixesTest.proxy(ItemComposition.class, Map.of("getName", NAMES.getOrDefault(id, "Item " + id)));
            }

            /** RuneLite's search: every priced item whose name contains the query. */
            @Override List<ItemPrice> find(String name)
            {
                List<ItemPrice> found = new java.util.ArrayList<>();
                NAMES.forEach((id, item) -> {
                    if (!item.toLowerCase().contains(name.toLowerCase())) return;
                    ItemPrice price = new ItemPrice();
                    price.setId(id);
                    price.setName(item);
                    found.add(price);
                });
                return found;
            }
        };
        return p;
    }

    private static void chat(ReviewFixesTest.Plugin p, String text)
    {
        ChatMessage event = new ChatMessage();
        event.setType(ChatMessageType.SPAM);
        event.setMessage(text);
        p.onChatMessage(event);
    }

    /** The player's own herb pile on the clicked tile disappears as their Take succeeds. */
    private void pickUp(ReviewFixesTest.Plugin p, int item)
    {
        p.engine.markLoot(Collections.singletonMap(item, 1L), 100, "Loot from Chaos druid", "Chaos druid");
        Observation click = ReviewFixesTest.take(p);
        click.item = item;
        click.at = tick[0];
        click.x = 10;
        click.y = 10;
        Map<String, Object> pile = new HashMap<>();
        pile.put("getId", item);
        pile.put("getQuantity", 1);
        pile.put("getOwnership", net.runelite.api.TileItem.OWNERSHIP_SELF);
        p.onItemDespawned(new ItemDespawned(ReviewFollowupTest.tile(10, 10),
            ReviewFixesTest.proxy(net.runelite.api.TileItem.class, pile)));
    }

    @Test public void bothWordingsNameTheHerb()
    {
        for (String line : new String[] {LINE, "You put the Grimy kwuarm into your herb sack.",
            "You put the Grimy torstol herb into your open herb sack."})
        {
            java.util.regex.Matcher m = GameData.pattern("bag").matcher(line);
            assertTrue(line, m.matches());
            assertTrue(line, m.group(2).startsWith("Grimy ") && !m.group(2).endsWith(" herb"));
        }
        for (String other : new String[] {"You put the Grimy guam leaf into the vial of water.",
            "You add the herbs to your sack.", "Your herb sack is too full to hold the Grimy ranarr weed herb.",
            "You look in your herb sack and see:"})
            assertTrue(other, !GameData.pattern("bag").matcher(other).matches());
    }

    @Test public void eachHarvestedHerbBooksOnce()
    {
        for (int sack : new int[] {ItemID.SLAYER_HERB_SACK_OPEN, ItemID.SLAYER_HERB_SACK_SILK_OPEN})
        {
            ReviewFixesTest.Plugin p = plugin(sack);
            chat(p, LINE);
            chat(p, LINE);
            assertEquals("two picks, two herbs", 2L, ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
        }
    }

    @Test public void aClosedSackTakesNothing()
    {
        ReviewFixesTest.Plugin p = plugin(ItemID.SLAYER_HERB_SACK);
        p.containers = new ContainerSnapshotFactory(p.client, null);
        chat(p, LINE);
        assertEquals(0L, ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
    }

    @Test public void aPickedUpHerbBooksOnceInEitherOrder()
    {
        ReviewFixesTest.Plugin lineFirst = plugin(ItemID.SLAYER_HERB_SACK_OPEN);
        chat(lineFirst, LINE);
        pickUp(lineFirst, RANARR);
        assertEquals(1L, ReviewFixesTest.qty(lineFirst, Inbox.BAG_GAIN));

        ReviewFixesTest.Plugin despawnFirst = plugin(ItemID.SLAYER_HERB_SACK_OPEN);
        pickUp(despawnFirst, RANARR);
        assertEquals("the sack's own line books it", 0L, ReviewFixesTest.qty(despawnFirst, Inbox.BAG_GAIN));
        chat(despawnFirst, LINE);
        assertEquals(1L, ReviewFixesTest.qty(despawnFirst, Inbox.BAG_GAIN));
    }

    @Test public void otherOpenBagsStillBookTheirPickupFromTheDespawn()
    {
        ReviewFixesTest.Plugin looting = plugin(ItemID.LOOTING_BAG_OPEN);
        pickUp(looting, RANARR);
        assertEquals("no herb sack: the looting bag took it, and no line names it", 1L,
            ReviewFixesTest.qty(looting, Inbox.BAG_GAIN));

        ReviewFixesTest.Plugin gems = plugin(ItemID.GEM_BAG_OPEN);
        pickUp(gems, ItemID.UNCUT_RUBY);
        assertEquals(1L, ReviewFixesTest.qty(gems, Inbox.BAG_GAIN));
    }

    @Test public void seedsStolenIntoAnOpenSeedBoxCount()
    {
        ReviewFixesTest.Plugin p = plugin(ItemID.SEED_BOX_OPEN);
        chat(p, "You put the stolen Ranarr seed into your seed box.");
        chat(p, "The following stolen loot gets added to your seed box: Ranarr seed x 2.");
        assertEquals("one single and one batch steal", -3L, p.engine.baseline.quantity(SEED));
    }

    @Test public void aPickedUpSeedCountsOnceInEitherOrder()
    {
        ReviewFixesTest.Plugin lineFirst = plugin(ItemID.SEED_BOX_OPEN);
        chat(lineFirst, "You put 1 x Ranarr seed straight into your open seed box.");
        pickUp(lineFirst, SEED);
        assertEquals(-1L, lineFirst.engine.baseline.quantity(SEED));
        assertEquals(0L, ReviewFixesTest.qty(lineFirst, Inbox.BAG_GAIN));

        ReviewFixesTest.Plugin despawnFirst = plugin(ItemID.SEED_BOX_OPEN);
        pickUp(despawnFirst, SEED);
        chat(despawnFirst, "You put 1 x Ranarr seed straight into your open seed box.");
        assertEquals(-1L, despawnFirst.engine.baseline.quantity(SEED));
        assertEquals(0L, ReviewFixesTest.qty(despawnFirst, Inbox.BAG_GAIN));
    }

    @Test public void minedCoalCountsOnlyWhenTheOpenBagTookIt()
    {
        ReviewFixesTest.Plugin bagged = plugin(ItemID.COAL_BAG_OPEN);
        chat(bagged, "You manage to mine some coal.");
        tick[0]++;
        bagged.bagSettle();
        assertEquals("the bag took it", -1L, bagged.engine.baseline.quantity(ItemID.COAL));

        ReviewFixesTest.Plugin carried = plugin(ItemID.COAL_BAG_OPEN, ItemID.COAL);
        chat(carried, "You manage to mine some coal.");
        tick[0]++;
        carried.bagSettle();
        assertEquals("the pack took it; its own settle books it", 0L, carried.engine.baseline.quantity(ItemID.COAL));
    }

    /**
     * An open shade coffin takes only shade remains the player picks up (OSRS Wiki: Bronze coffin,
     * Gold coffin), and prints no line for it: the pickup's despawn books it, for every coffin.
     */
    @Test public void anOpenCoffinBooksPickedUpRemainsFromTheDespawn()
    {
        for (int coffin : new int[] {ItemID.SHADES_COFFIN_BRONZE_OPEN, ItemID.SHADES_COFFIN_STEEL_OPEN,
            ItemID.SHADES_COFFIN_BLACK_OPEN, ItemID.SHADES_COFFIN_SILVER_OPEN, ItemID.SHADES_COFFIN_GOLD_OPEN})
        {
            ReviewFixesTest.Plugin p = plugin(coffin);
            p.containers = new ContainerSnapshotFactory(p.client, null)
            {
                @Override ContainerSnapshot capture(boolean equipment, boolean pouch) { return FixtureReads.empty(); }
            };
            pickUp(p, ItemID.SHADE_BONES5);
            assertEquals(1L, ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
            tick[0]++;
            p.bagSettle();
            assertEquals("Fiyr remains the coffin took count once", -1L, p.engine.baseline.quantity(ItemID.SHADE_BONES5));
        }
    }

    /**
     * Open meat and fur pouches take a catch's meat and fur without the pack changing; the catch line
     * names the creature (TicTac7x Item Charges), the wiki its always-dropped items. A pitfall cat's
     * fur may be tatty, so only its meat counts.
     */
    @Test public void aCatchIntoOpenPouchesCountsItsFurAndMeatOnce()
    {
        ReviewFixesTest.Plugin both = plugin(ItemID.HG_MEATPOUCH_LARGE_OPEN, ItemID.HG_FURPOUCH_LARGE_OPEN);
        chat(both, "You've caught a pyre fox.");
        tick[0]++;
        both.bagSettle();
        assertEquals(-1L, both.engine.baseline.quantity(FOX_FUR));
        assertEquals(-1L, both.engine.baseline.quantity(FOX_MEAT));

        // A full meat pouch sent the meat to the pack; no fur pouch is open, so the fur is the pack's too.
        ReviewFixesTest.Plugin meatInPack = plugin(ItemID.HG_MEATPOUCH_SMALL_OPEN);
        chat(meatInPack, "You've caught a pyre fox.");
        tick[0]++;
        meatInPack.client = ReviewFixesTest.proxy(net.runelite.api.Client.class, Map.of(
            "getTickCount", (java.util.function.IntSupplier) () -> tick[0],
            "getItemContainer", ReviewFixesTest.proxy(ItemContainer.class, Map.of("getItems",
                new Item[] {new Item(ItemID.HG_MEATPOUCH_SMALL_OPEN, 1), new Item(FOX_MEAT, 1), new Item(FOX_FUR, 1)}))));
        meatInPack.bagSettle();
        assertEquals(0L, meatInPack.engine.baseline.quantity(FOX_MEAT));
        assertEquals(0L, meatInPack.engine.baseline.quantity(FOX_FUR));

        ReviewFixesTest.Plugin closed = plugin(ItemID.HG_MEATPOUCH_LARGE, ItemID.HG_FURPOUCH_LARGE);
        chat(closed, "You've caught a pyre fox.");
        assertEquals(0L, ReviewFixesTest.qty(closed, Inbox.BAG_GAIN));

        ReviewFixesTest.Plugin cat = plugin(ItemID.HG_MEATPOUCH_LARGE_OPEN, ItemID.HG_FURPOUCH_LARGE_OPEN);
        chat(cat, "You've caught a spined larupia!");
        tick[0]++;
        cat.bagSettle();
        assertEquals(-1L, cat.engine.baseline.quantity(LARUPIA_MEAT));
        assertEquals("its fur may be tatty", 0L, cat.engine.baseline.quantity(LARUPIA_FUR));
    }

    @Test public void gemLinesStillNameTheUncutGem()
    {
        ReviewFixesTest.Plugin p = plugin(ItemID.GEM_BAG_OPEN);
        chat(p, "You put the stolen Uncut ruby into your gem bag.");
        assertEquals(-1L, p.engine.baseline.quantity(ItemID.UNCUT_RUBY));
    }
    @Test public void aFullPouchMeatAlreadyInThePackCountsOnce()
    {
        // The inventory callback is visible before this catch message; the meat pouch is full.
        ReviewFixesTest.Plugin p = plugin(ItemID.HG_MEATPOUCH_SMALL_OPEN, FOX_MEAT);
        chat(p, "You've caught a pyre fox.");
        tick[0]++;
        p.bagSettle();
        p.engine.markDirty();
        ContainerSnapshot held = new ContainerSnapshot(Map.of(FOX_MEAT, 1L));
        p.engine.processIfDirty(held, ReviewFixesTest.T0 + 600, null);
        p.engine.processIfDirty(held, ReviewFixesTest.T0 + 1200, null);
        assertEquals("one physical meat at 100 GP must count once", 100L,
                p.engine.metrics(ReviewFixesTest.T0 + 1200).income);
    }

    @Test public void aMeatPickupBesideAHunterPouchStaysAMeasuredPickup()
    {
        ReviewFixesTest.Plugin p = plugin(ItemID.HG_MEATPOUCH_LARGE_OPEN, ItemID.LOOTING_BAG_OPEN);
        pickUp(p, FOX_MEAT);
        assertEquals("a ground pickup has no hunter-catch message", 1L,
                ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
    }

    @Test public void aHunterCatchNeverBecomesLootingBagStock()
    {
        ReviewFixesTest.Plugin p = plugin(ItemID.HG_MEATPOUCH_LARGE_OPEN, ItemID.LOOTING_BAG_OPEN);
        ItemContainer pack = ReviewFixesTest.proxy(ItemContainer.class, Map.of("getItems",
                new Item[] {new Item(ItemID.HG_MEATPOUCH_LARGE_OPEN, 1), new Item(ItemID.LOOTING_BAG_OPEN, 1)},
                "contains", true));
        p.client = ReviewFixesTest.proxy(Client.class, Map.of(
                "getTickCount", (java.util.function.IntSupplier) () -> tick[0], "getItemContainer", pack));
        chat(p, "You've caught a pyre fox.");
        tick[0]++;
        p.bagSettle();
        assertTrue("hunter meat went into the meat pouch, not the looting bag", p.engine.bag.isEmpty());
    }

}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import org.junit.Test;

import static org.junit.Assert.*;

/** Known alch-priced sips keep the selected policy without concealing unsupported pairs. */
public class HighAlchSipReviewTest {
    static final Map<Integer, String> NAMES = Map.of(2434, "Prayer potion(4)", 139,
            "Prayer potion(3)", 141, "Prayer potion(2)", 143, "Prayer potion(1)");

    static Valuation service(boolean alch, Map<Integer, Integer> values) {
        var service = ModelProbe.valuation(new GpManagerConfig() {}, id -> ReviewFixesTest.proxy(
                ItemComposition.class, Map.of("getName", NAMES.getOrDefault(id, "Item " + id),
                        "getHaPrice", values.getOrDefault(id, 0), "isTradeable", true)), id -> 1000);
        service.alch = alch;
        return service;
    }

    static List<Flow> pair(long quantity, int loss, int rest, PriceSource source) {
        return List.of(new Flow(2434, "Prayer potion(4)", -quantity, loss,
                        SafeMath.multiply(-quantity, loss), source),
                new Flow(139, "Prayer potion(3)", quantity, rest,
                        SafeMath.multiply(quantity, rest), source));
    }

    @Test public void alchSipRetainsCapturedQuotesAndLeavesReview() {
        // The bottle's base value makes these non-proportional: a sip loses 23, not the (1)'s 45.
        var values = new HashMap<>(Map.of(2434, 114, 139, 91, 141, 68, 143, 45));
        var service = service(true, values);
        var engine = new Engine(service, new TransactionClassifier(), new GpManagerConfig() {});
        engine.ensureSession(1000);
        engine.setBaseline(new ContainerSnapshot(Map.of(2434, 1L)));
        engine.noteConsume(2434, 6, false, ActionKind.DRINK, null);
        var row = ItemValuationServiceTest.settleDrink(engine, Map.of(139, 1L), 2000);

        assertEquals(TransactionType.CONSUMPTION, row.type());
        assertEquals(ActionKind.DRINK, row.action());
        assertTrue(row.counts());
        assertTrue(engine.getReviewRows(4000).isEmpty());
        assertEquals(-23, engine.metrics(4000).net);
        for (var flow : row.flows()) {
            assertEquals(PriceSource.HIGH_ALCHEMY, flow.source());
            assertEquals(values.get(flow.item).intValue(), flow.unitPrice);
        }
        values.replaceAll((id, price) -> price * 2);
        assertEquals("a later quote cannot reprice the sip", -23, engine.metrics(5000).net);
        var codec = new com.google.gson.Gson();
        var restored = codec.fromJson(codec.toJson(engine.session()), Session.class);
        assertEquals("reload keeps the captured difference", -23, restored.metrics(5000).net);
    }

    @Test public void normalModeRetainsUnsupportedAlchFallback() {
        assertNull(service(false, Map.of()).normalizeConsumedFlows(
                pair(1, 400, 300, PriceSource.HIGH_ALCHEMY), ActionKind.DRINK, 1000));
    }

    @Test public void reversedAlchPairStaysReview() {
        assertNull(service(true, Map.of()).normalizeConsumedFlows(
                pair(1, 300, 400, PriceSource.HIGH_ALCHEMY), ActionKind.DRINK, 1000));
    }

    @Test public void overflowingQuantitiesStayReview() {
        assertNull(service(true, Map.of()).normalizeConsumedFlows(
                pair(Long.MAX_VALUE, 400, 300, PriceSource.HIGH_ALCHEMY), ActionKind.DRINK, 1000));
    }

    @Test public void mixedSourcesStayReview() {
        var raw = new ArrayList<>(pair(1, 400, 300, PriceSource.HIGH_ALCHEMY));
        raw.set(1, new Flow(139, "Prayer potion(3)", 1, 300, 300, PriceSource.GRAND_EXCHANGE));
        assertNull(service(true, Map.of()).normalizeConsumedFlows(raw, ActionKind.DRINK, 1000));
    }

    @Test public void equalAlchPricesRemainZeroUnderTheSelectedPolicy() {
        var result = service(true, Map.of()).normalizeConsumedFlows(
                pair(1, 400, 400, PriceSource.HIGH_ALCHEMY), ActionKind.DRINK, 1000);
        assertNotNull(result);
        assertEquals(0, result.stream().mapToLong(flow -> flow.value).sum());
    }
}

package com.gpmanager;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Receipt detail may compact; reaching a session count never discards canonical money or Review. */
public class HistoryNeverTrimsTest {
    static final long NOW = StoredChargeFixture.NOW;

    @Test public void restoreAboveTheOldShippingCapKeepsMoneyAndUndecidedReview() {
        Engine engine = StoredChargeFixture.engine();
        for (int index = 0; index < 2001; index++) {
            long at = NOW - 400L * 86_400_000 - index * 1000L;
            var session = new Session("History " + index, at, SessionMode.GENERAL);
            session.addTransaction(gain(at), 2000, false);
            if (index == 0) {
                var review = Tx.of(at + 1, TransactionType.UNCERTAIN, Context.GENERIC, "Undecided", false,
                        List.of(new Flow(536, "Dragon bones", 1, 100, 100)));
                review.confidence = Confidence.UNCERTAIN;
                assertTrue(ReviewRules.needsReview(review));
                session.addTransaction(review, 2000, false);
            }
            session.close(at + 100);
            engine.history.add(0, session);
        }
        assertEquals(200_100, GrindsData.allTime(engine, NOW).net);
        Engine restored = StoredChargeFixture.engine();
        restored.restore(engine.savedState(), NOW + 1000);
        assertEquals(2001, restored.history.size());
        assertEquals(200_100, GrindsData.allTime(restored, NOW + 1000).net);
        assertEquals(1, restored.sessions().stream().flatMap(session -> session.transactions().stream())
                .filter(ReviewRules::needsReview).count());
        assertEquals("ordinary old details still compact", 1,
                restored.history.stream().mapToLong(session -> session.transactions().size()).sum());
    }

    @Test public void finishingGrindsCannotEvictOlderCanonicalSessions() {
        Engine engine = new Engine(StoredChargeFixture.engine().valuation, new TransactionClassifier(),
                new GpManagerConfig() { @Override public int maxHistorySessions() { return 1; } });
        engine.ensureSession(NOW);
        for (int index = 0; index < 3; index++) {
            engine.startCustom("Trip " + index, NOW + index * 1000);
            engine.session().addTransaction(gain(NOW + index * 1000 + 100), 2000, false);
            engine.finishCustom(NOW + index * 1000 + 500);
        }
        assertEquals(3, engine.history.size());
        assertEquals(300, GrindsData.allTime(engine, NOW + 10_000).net);
    }

    static Transaction gain(long at) {
        return Tx.of(at, TransactionType.GAIN, Context.GENERIC, "Owned history", true,
                List.of(new Flow(995, "Coins", 100, 1, 100, PriceSource.FACE_VALUE)));
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
