            assertEquals("a sip from " + names.get(step[0]) + " costs one (1)", -1_000L, net);
        }
        assertEquals("a (4) that is not drunk keeps its own quote", 3_600L,
            service.value(Collections.singletonMap(2434, 1L)).get(0).value);
    }

