    @Test
    public void localDeathClosesOnlyMatchingKeyAndNeverBooksKeyAsLoss()
    {
        Session session = new Session("PK", 1_000L, SessionMode.GENERAL);
        Transaction row = keyAuditRow(ItemID.WILDY_LOOT_KEY0, 1L, session);
        KeyClaims claims = new KeyClaims();
        claims.open(row.id(), ItemID.WILDY_LOOT_KEY0, 1L, 2_000L);
        claims.open("other", ItemID.WILDY_LOOT_KEY3, 1L, 2_000L);
        long beforeCosts = row.costs();
        long beforeRevenue = row.revenue();
        List<Flow> originalAuditFlows = new java.util.ArrayList<>(row.flows());
        claims.beginLocalDeath(Collections.singletonMap(ItemID.WILDY_LOOT_KEY0, 1L));

        claims.recordDeathLosses(
            Collections.singletonList(new Flow(ItemID.WILDY_LOOT_KEY0, "Loot key", -1L, 0, 0L)),
            Collections.<Integer, Long>emptyMap());

        assertNull("the lost key's claim is closed", find(claims, row.id()));
        assertNotNull("an unrelated key stays pending", find(claims, "other"));
        assertEquals("closing the claim never adds item flows", originalAuditFlows, row.flows());
        assertEquals(beforeRevenue, row.revenue());
        assertEquals(beforeCosts, row.costs());
        assertEquals(1, session.transactions().size());
    }

    @Test
    public void unrelatedFirstDeathSettlementKeepsKeyEvidenceForLaterBatch()
    {
        KeyClaims claims = new KeyClaims();
        claims.open("k2", ItemID.WILDY_LOOT_KEY2, 1L, 2_000L);
        claims.beginLocalDeath(Collections.singletonMap(ItemID.WILDY_LOOT_KEY2, 1L));

        claims.recordDeathLosses(
            Collections.singletonList(new Flow(995, "Coins", -1L, 1, -1L)),
            Collections.singletonMap(ItemID.WILDY_LOOT_KEY2, 1L));
        assertTrue("first unrelated inventory/equipment settle must not consume the bounded death snapshot",
            claims.settlingDeath());
        assertNotNull(find(claims, "k2"));

        claims.recordDeathLosses(
            Collections.singletonList(new Flow(ItemID.WILDY_LOOT_KEY2, "Loot key", -1L, 0, 0L)),
            Collections.<Integer, Long>emptyMap());

        assertNull(find(claims, "k2"));
        assertFalse(claims.settlingDeath());
    }

    @Test
    public void keyReceiptAuditNoteRemainsValueDeferred()
    {
        assertEquals("Loot key received - value deferred", KeyClaims.LOOT_KEY_NOTE);
    }

    private static PendingClaim find(KeyClaims claims, String claimId)
    {
        for (PendingClaim claim : claims.all())
        {
            if (claim.claimId().equals(claimId))
            {
                return claim;
            }
        }
        return null;
    }

    private static Transaction keyAuditRow(int keyItemId, long quantity, Session session)
    {
        Transaction row = new Transaction(2_000L, TransactionType.ADJUSTMENT,
            Context.PK_LOOT, KeyClaims.LOOT_KEY_NOTE, "PKing", false,
            Collections.singletonList(new Flow(keyItemId, "Loot key", quantity, 0, 0L)),
            Confidence.LIKELY, "Deferred loot-key value", null);
        session.addTransaction(row, 2_000, false);
        return row;
    }

    private static void assertDeathRemainsPending(boolean hasNegativeFlow, long currentQuantity)
    {
        KeyClaims claims = new KeyClaims();
        claims.open("k1", ItemID.WILDY_LOOT_KEY1, 1L, 2_000L);
        claims.beginLocalDeath(Collections.singletonMap(ItemID.WILDY_LOOT_KEY1, 1L));
        List<Flow> flows = hasNegativeFlow
            ? Collections.singletonList(new Flow(ItemID.WILDY_LOOT_KEY1, "Loot key", -1L, 0, 0L))
            : Collections.emptyList();

        claims.recordDeathLosses(flows, currentQuantity > 0L
            ? Collections.singletonMap(ItemID.WILDY_LOOT_KEY1, currentQuantity)
            : Collections.<Integer, Long>emptyMap());

        assertEquals(1L, find(claims, "k1").quantity());
    }

    private static ItemContainer itemContainer(Item... items)
    {
        return proxy(ItemContainer.class, (method, args) -> "getItems".equals(method) ? items : null);
    }

    private static boolean isMutable(Map<Integer, Long> map)
    {
        try
        {
            map.put(-999, 1L);
            map.remove(-999);
            return true;
        }
        catch (UnsupportedOperationException ignored)
        {
            return false;
        }
    }

    private interface Answer
    {
        Object answer(String method, Object[] args);
    }

    private static <T> T proxy(Class<T> type, Answer answer)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type}, (obj, method, args) ->
        {
            Object value = answer.answer(method.getName(), args);
            if (value != null || !method.getReturnType().isPrimitive())
            {
                return value;
            }
            if (method.getReturnType() == boolean.class)
            {
                return false;
            }
            if (method.getReturnType() == long.class)
            {
                return 0L;
            }
            return 0;
        }));
    }
}

package com.gpmanager;

import static org.junit.Assert.*;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.Test;

/** Retiring migrations preserves repaired wire data and does not rewrite untouched history. */
public class LegacyRepairRetirementTest {
    static final long START = 1_800_000_000_000L;

    static Engine engine() {
        JsonCodec.bind(new Gson());
        Engine engine = TargetFreshStartTest.engine();
        engine.ensureSession(START);
        return engine;
    }

    @Test public void alreadyRepairedSaveKeepsEveryReceiptAndItsValues() throws Exception {
        Engine engine = engine();
        try (var stream = getClass().getResourceAsStream("/com/gpmanager/repaired-legacy.json")) {
            assertNotNull("synthetic fixture was generated by the pre-retirement engine", stream);
            try (var reader = new InputStreamReader(stream, StandardCharsets.UTF_8)) {
                engine.restore(new Gson().fromJson(reader, SavedState.class), START + 10000);
            }
        }
        String before = new Gson().toJson(engine.session().transactions());
        long net = engine.session().metrics(START + 10001).net;
        engine.recheck();
        assertEquals(before, new Gson().toJson(engine.session().transactions()));
        assertEquals(net, engine.session().metrics(START + 10002).net);
        assertEquals(3, engine.session().transactions().size());
        assertEquals(0, engine.session().transactions().stream().filter(ReviewRules::needsReview).count());
        assertEquals(1, engine.session().transactions().stream().filter(row -> row.action() == ActionKind.CAST).count());
    }

    @Test public void anUntouchedOldSpellBundleIsNotSplitOrReclassified() {
        Engine engine = engine();
        Transaction old = new Transaction(START, TransactionType.CONSUMPTION, Context.GENERIC, "", "Magic", true,
                List.of(new Flow(562, "Chaos rune", -4, 105, -420),
                        new Flow(560, "Death rune", -2, 191, -382), new Flow(555, "Water rune", -4, 4, -16)),
                Confidence.LIKELY, "Historical receipt", null);
        engine.session().addTransaction(old, 2000, false);
        String before = new Gson().toJson(old);
        engine.recheck();
        assertEquals(before, new Gson().toJson(old));
        assertEquals(1, engine.session().transactions().size());
    }
}

package com.gpmanager;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class LegacyTargetProgressTest {
    private static final long HOUR = 3_600_000L;
    private static final long UNIT = 4_000_000_000_000_000_000L;

    private static Engine negativeStart() {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = TargetFreshStartTest.engine();
        TargetFreshStartTest.coins(engine, 5, -100);
        engine.setTargets(100L, null, HOUR);
        return engine;
    }

    @Test public void anOlderTargetMustRetainItsNegativeStartingNet() {
        var engine = negativeStart();
        engine.session().sessionStartAt = null;
        TargetFreshStartTest.coins(engine, HOUR + 5, 50);
        var live = TargetFreshStartTest.live(engine, 2 * HOUR);
        assertEquals(-50, live.net);
        assertEquals("a 50-gp gain after a -100-gp start is 50 progress", 50, live.goal.current);
    }

    @Test public void theNegativeBaselineMustRemainUsableAfterReload() {
        var engine = negativeStart();
        engine.session().sessionStartAt = null;
        TargetFreshStartTest.coins(engine, HOUR + 5, 50);
        var saved = SaveCopies.copy(engine.savedState());
        var restored = TargetFreshStartTest.engine();
        restored.restore(saved, 2 * HOUR);
        var live = TargetFreshStartTest.live(restored, 2 * HOUR);
        assertEquals(-100, restored.session().profitTargetSetNet.longValue());
        assertEquals(-50, live.net);
        assertEquals(50, live.goal.current);
    }

    private static Engine overflowLoss(boolean oldWindow) {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = TargetFreshStartTest.engine();
        hugeReceipt(engine, 5, true);
        String first = engine.session().transactions().get(0).id();
        engine.setTargets(100L, null, HOUR);
        if (oldWindow) engine.session().sessionStartAt = null;
        assertTrue(engine.correctEntries(List.of(first), Correction.IGNORE));
        hugeReceipt(engine, HOUR + 5, false);
        hugeReceipt(engine, HOUR + 6, false);
        assertEquals(-2 * UNIT, engine.metrics(2 * HOUR).net);
        return engine;
    }

    private static void hugeReceipt(Engine engine, long at, boolean gain) {
        var flow = new Flow(1203, "Iron dagger", gain ? 1 : -1, UNIT, gain ? UNIT : -UNIT,
                PriceSource.MANUAL_OVERRIDE);
        engine.session().addTransaction(Tx.of(at, gain ? TransactionType.GAIN : TransactionType.CONSUMPTION,
                Context.GENERIC, "", true, List.of(flow)), 2000, false);
    }

    @Test public void aLargeLegacyTargetLossMustNotWrapIntoReachedProfit() {
        var engine = overflowLoss(true);
        var live = TargetFreshStartTest.live(engine, 2 * HOUR);
        assertEquals(Long.MIN_VALUE, live.goal.current);
        assertFalse(live.goal.reached);
    }

    @Test public void resavingAnUnreachedLegacyTargetMustNotRestartIt() {
        var engine = overflowLoss(true);
        engine.setTargets(100L, null, 2 * HOUR);
        assertNull("an unchanged unreached target keeps its existing window", engine.session().sessionStartAt);
        assertEquals(UNIT, engine.session().profitTargetSetNet.longValue());
    }

    @Test public void aCurrentTargetWindowKeepsItsOwnNegativeStartProgress() {
        var engine = negativeStart();
        TargetFreshStartTest.coins(engine, HOUR + 5, 50);
        var live = TargetFreshStartTest.live(engine, 2 * HOUR);
        assertEquals(50, live.net);
        assertEquals(50, live.goal.current);
    }

    @Test public void aCurrentWindowDoesNotWrapTheSameLargeLoss() {
        var engine = overflowLoss(false);
        var live = TargetFreshStartTest.live(engine, 2 * HOUR);
        assertEquals(-2 * UNIT, live.goal.current);
        assertFalse(live.goal.reached);
    }

    @Test public void positiveAndMissingLegacyBaselinesKeepTheirOrdinaryMeaning() {
        var session = new Session("Audit", 0, SessionMode.GENERAL);
        session.setNetTarget(100L, 100, 0);
        assertEquals(50, session.targetProgress(150));
        session.profitTargetSetNet = null;
        assertEquals(50, session.targetProgress(50));
    }
}

package com.gpmanager;

import static com.gpmanager.TargetFreshStartTest.HOUR;
import static com.gpmanager.TargetFreshStartTest.coins;
import static com.gpmanager.TargetFreshStartTest.live;
import static com.gpmanager.TargetFreshStartTest.recentTotal;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Owner 1.5.2: one reset flow. The ACTIVE clock starts a new Live session (Net, Recent, GP/h and
 * the clock at zero); a target starts one too; the run keeps every row and its whole total.
 */
public class LiveSessionTest
{
    @Test
    public void aNewSessionStartsLiveAtZeroAndTheRunKeepsEverything()
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 1_000L);
        engine.newLive(HOUR);
        LiveSnapshot fresh = live(engine, HOUR);
        assertEquals(0L, fresh.net);
        assertEquals(0L, fresh.income);
        assertEquals(0L, fresh.elapsed);
        assertEquals(0L, fresh.rate);
        assertTrue("Recent starts empty", fresh.recent.isEmpty());
        assertTrue("the run total line shows", fresh.fresh);
        assertEquals("the run keeps its whole total", 1_000L, fresh.run);

        coins(engine, HOUR + 5L, 500L);
        LiveSnapshot later = live(engine, 2 * HOUR);
        assertEquals(500L, later.net);
        assertEquals(500L, recentTotal(later));
        assertEquals(HOUR, later.elapsed);
        assertEquals(500L, later.rate);
        assertEquals(2, engine.session().transactions().size());
        assertEquals(1_500L, engine.metrics(2 * HOUR).net);
    }

    @Test
    public void aNewSessionDuringATargetStartsTheTargetAgain()
    {
        Engine engine = TargetFreshStartTest.engine();
        engine.setTargets(5_000_000L, null, 0L);
        coins(engine, 5L, 1_000L);
        engine.newLive(HOUR);
        assertEquals(0L, live(engine, HOUR).goal.current);
        coins(engine, HOUR + 5L, 300L);
        assertEquals(300L, live(engine, 2 * HOUR).goal.current);
    }

    /** The run total under the Net brings the whole run back to Live; a running target stays. */
    @Test
    public void theRunTotalShowsTheWholeRunAgain()
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 1_000L);
        engine.newLive(HOUR);
        coins(engine, HOUR + 5L, 500L);
        engine.showWholeRun();
        LiveSnapshot whole = live(engine, 2 * HOUR);
        assertFalse(whole.fresh);
        assertEquals(1_500L, whole.net);
        assertEquals(1_500L, recentTotal(whole));
        assertEquals(2 * HOUR, whole.elapsed);

        engine.setTargets(5_000_000L, null, 2 * HOUR);
        engine.showWholeRun();
        assertTrue("a running target keeps its session", live(engine, 2 * HOUR).fresh);
        engine.setTargets(null, null, 2 * HOUR);
        engine.showWholeRun();
        assertEquals("after Done it can", 1_500L, live(engine, 2 * HOUR).net);
    }

    @Test
    public void theWholeRunHasNoTotalLine()
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 1_000L);
        assertFalse(live(engine, HOUR).fresh);
    }

    @Test
    public void theClockKeepsNewSessionAlongsideTheRateRestart() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        engine.ensureSession(System.currentTimeMillis() - HOUR);
        SidebarPanel panel = MilestoneTest.onEdt(() -> new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null));
        Shell shell = panel.shell;
        GrindsController grinds = new GrindsController(panel);
        assertEquals("Session controls", MilestoneTest.onEdt(() ->
        {
            grinds.newSession();
            String title = ShellProbe.sheetTitle(shell);
            ShellProbe.pressSheet(shell, "New session");
            return title;
        }));
        assertTrue(engine.session().sessionStartAt != null);
    }
}

package com.gpmanager;

import java.nio.charset.StandardCharsets;
