    private static final class Seam
    {
        final List<Boolean> activeFlags = new ArrayList<>();
        final List<Integer> asked = new ArrayList<>();
        long quote = 100;
        boolean failIfAsked;
    }

    private static Valuation service(GpManagerConfig config, Seam seam,
        Valuation.Economy state)
    {
        return new Valuation(config, id -> null, (id, active) ->
        {
            if (seam.failIfAsked)
            {
                throw new AssertionError("automatic market must not be queried");
            }
            seam.activeFlags.add(active);
            seam.asked.add(id);
            return seam.quote;
        }, id -> false, state);
    }

    private static GpManagerConfig override(String overrides)
    {
        return new GpManagerConfig()
        {
            @Override public String manualPriceOverrides()
            {
                return overrides;
            }
        };
    }

    private static GpManagerConfig config()
    {
        return new GpManagerConfig()
        {
            @Override public int stabilizationTicks()
            {
                return 0;
            }
        };
    }

    private static ChargeDelta observe(Engine engine, String chat, long now)
    {
        ChargeCheck read = ChargeCheck.parse(chat);
        assertNotNull(chat, read);
        ChargeDelta delta = engine.observeCheck(read, "149:5:0:22323:X", now);
        return delta == null || delta.getComponentDeltas().isEmpty() ? null : delta;
    }

    private static Map<Integer, Long> with(Map<Integer, Long> base, Object... pairs)
    {
        Map<Integer, Long> map = new HashMap<>(base);
        for (int i = 0; i < pairs.length; i += 2)
        {
            long quantity = (Long) pairs[i + 1];
            if (quantity <= 0L)
            {
                map.remove((Integer) pairs[i]);
            }
            else
            {
                map.put((Integer) pairs[i], quantity);
            }
        }
        return map;
    }

    private static String name(int id)
    {
        if (id == ItemID.COINS)
        {
            return "Coins";
        }
        return id == RUNE ? "Nature rune" : "Item " + id;
    }

    private static final class Market
    {
        final Engine engine;
        final OfferSlots ledger = new OfferSlots();
        long now = T0;
        Map<Integer, Long> inventory = new HashMap<>();

        Market(Valuation service)
        {
            engine = new Engine(service, new TransactionClassifier(), config());
            engine.startCustom("Trading", now);
            inventory.put(ItemID.COINS, 100_000L);
            engine.setBaseline(new ContainerSnapshot(inventory));
        }

        void offer(int slot, GrandExchangeOfferState state, int item, int total, int traded,
            int price, int spent)
        {
            now += 600L;
            OfferSlots.Transition transition = ledger.observe(
                new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent)).orElse(null);
            if (transition != null)
            {
                engine.noteGeOffer(transition,
                    name(transition.current.item), now);
            }
        }

        void settle(Map<Integer, Long> next)
        {
            now += 600L;
            inventory = new HashMap<>(next);
            engine.markDirty();
            ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
            for (int i = 0; i < 3; i++)
            {
                engine.processIfDirty(snapshot, now, null);
                now += 600L;
            }
        }
    }

    private static final Valuation.Economy NORMAL =
        Valuation.Economy.NORMAL;
    private static final Valuation.Economy UNSUPPORTED_SPECIAL =
        Valuation.Economy.UNSUPPORTED_SPECIAL;

    private static String read(String relative)
    {
        try
        {
            return new String(Files.readAllBytes(Paths.get(relative)), StandardCharsets.UTF_8);
        }
        catch (Exception ex)
        {
            throw new AssertionError("Unable to read " + relative, ex);
        }
    }

    private static String productionSource()
    {
        try (Stream<Path> files = Files.walk(Paths.get("src/main/java")))
        {
            return files.filter(path -> path.toString().endsWith(".java"))
                .map(path ->
                {
                    try
                    {
                        return new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
                    }
                    catch (Exception ex)
                    {
                        throw new AssertionError("Unable to read " + path, ex);
                    }
                })
                .collect(Collectors.joining("\n"));
        }
        catch (Exception ex)
        {
            throw new AssertionError("Unable to census production sources", ex);
        }
    }
}

package com.gpmanager;

import org.junit.Test;
import static org.junit.Assert.*;
import static com.gpmanager.TargetFreshStartTest.*;

public class MilestoneExpiryTest {
    @Test public void reachedMilestoneFadesThenClearsOnlyItself() {
        Engine engine = engine();
        engine.setTargets(10_000L, 60_000L, 10L);
        coins(engine, 20L, 400_000L);
        engine.setMilestone(400_000L);
        engine.tickMilestone(100L);
        HudBuilder hud = new HudBuilder(HudBuilderTest.config(false, 4), null);
        assertEquals("Milestone reached · 400k", hud.update(live(engine, 100L), f -> true, 100L).context);
        assertEquals(255, hud.current.contextColor.getAlpha());
        engine.tickMilestone(7_600L);
        int alpha = hud.update(live(engine, 7_600L), f -> true, 7_600L).contextColor.getAlpha();
        assertTrue("last second fades", alpha > 0 && alpha < 255);
        engine.tickMilestone(8_100L);
        assertNull(engine.freePlay().milestoneGp);
        assertEquals("", hud.update(live(engine, 8_100L), f -> true, 8_100L).context);
        assertEquals(Long.valueOf(10_000L), engine.session().targetGp());
        assertEquals(Long.valueOf(60_000L), engine.session().timeTargetMillis());
        long revision = engine.revision();
        engine.tickMilestone(9_000L);
        assertEquals(revision, engine.revision());
    }

    @Test public void replacingTargetOrFreePlayCancelsTheOldCountdown() {
        Engine engine = engine();
        coins(engine, 10L, 400_000L); engine.setMilestone(400_000L);
        engine.tickMilestone(100L);
        engine.setMilestone(500_000L);
        engine.tickMilestone(8_100L);
        assertEquals(Long.valueOf(500_000L), engine.freePlay().milestoneGp);
        engine.setMilestone(400_000L); engine.tickMilestone(8_200L);
        engine.startFreePlayOver(8_300L); engine.tickMilestone(20_000L);
        assertEquals(Long.valueOf(400_000L), engine.freePlay().milestoneGp);
    }

    @Test public void completionSurvivesANetDipAndDoesNotRequireAVisibleHud() {
        Engine engine = engine();
        coins(engine, 10L, 400_000L); engine.setMilestone(400_000L);
        engine.tickMilestone(100L);
        coins(engine, 1_000L, -10_000L);
        engine.tickMilestone(8_100L);
        assertNull(engine.freePlay().milestoneGp);
    }

    @Test public void aGrindCannotConsumeFreePlaysMilestone() {
        Engine engine = engine();
        coins(engine, 10L, 400_000L); engine.setMilestone(400_000L);
        engine.startCustom("Vorkath", 20L); engine.tickMilestone(30L);
        engine.tickMilestone(9_000L);
        assertEquals(Long.valueOf(400_000L), engine.freePlay().milestoneGp);
    }

    @Test public void aRestoredProfilesFutureTargetCannotInheritThePreviousCountdown() {
        JsonCodec.bind(new com.google.gson.Gson());
        Engine engine = engine();
        coins(engine, 10L, 400_000L); engine.setMilestone(400_000L); engine.tickMilestone(100L);
        Engine other = engine(); other.setMilestone(500_000L);
        engine.restoreProfile("other", other.savedState(), 1_000L);
        assertEquals(0L, live(engine, 1_000L).targetUntil);
        HudBuilder hud = new HudBuilder(HudBuilderTest.config(false, 4), null);
        assertEquals("", hud.update(live(engine, 1_000L), f -> true, 1_000L).context);
        engine.tickMilestone(10_000L);
        assertEquals(Long.valueOf(500_000L), engine.freePlay().milestoneGp);
    }
}

