    @Test public void privateCashProofReservesOnlyWholeTokensWithoutLosingItsSource() {
        for (int proof : new int[]{500, 1000, 1500, 2000}) {
            Engine engine = engine();
            engine.markLoot(Map.of(COINS, (long) proof), 50, "Loot from Guard", "Guard");
            long reserved = engine.events.reserve(Inbox.PRIVATE_LOOT, TOKENS, 2, Inbox.LOOT_RESERVE);
            assertEquals(proof / 1000, reserved);
            var source = engine.events.peek(Inbox.PRIVATE_LOOT);
            assertEquals(proof % 1000, source == null ? 0 : source.qty);
            if (reserved > 0) {
                var match = engine.consumeQueuedLoot(List.of(new Flow(COINS, "Coins", reserved * 1000, 1, reserved * 1000)));
                assertEquals("Loot from Guard", match.note);
            }
        }
    }

    @Test public void previouslyBookedRawTokenHistoryKeepsItsFrozenUnitsAndPrice() {
        Engine engine = engine();
        var old = new Transaction(NOW, TransactionType.LOOT, Context.LOOT, "Old receipt", "General", true,
                List.of(new Flow(TOKENS, "Platinum token", 2, 987, 1974)), Confidence.CONFIRMED, "", null);
        engine.add(old, false);
        var persisted = JsonCodec.gson().fromJson(JsonCodec.gson().toJson(engine.savedState()), SavedState.class);
        engine.restore(persisted, NOW);
        var retained = engine.session().transactions().get(0).flows().get(0);
        assertEquals(TOKENS, retained.item);
        assertEquals(2, retained.quantity);
        assertEquals(987, retained.unitPrice);
        assertEquals(1974, retained.value);
        assertEquals(1974, engine.metrics(NOW).income);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class PreEpochReceiptRestoreTest {
    private static final long NOW = 1_700_000_000_000L;
    private static final int ITEM = 1203;

    static Engine engine() {
        JsonCodec.bind(new com.google.gson.Gson());
        var result = new Engine(changes -> {
            var flows = new ArrayList<Flow>();
            changes.forEach((id, qty) -> flows.add(new Flow(id, "Iron dagger", qty, 100, qty * 100,
                    PriceSource.GRAND_EXCHANGE)));
            return flows;
        }, new TransactionClassifier(), ReviewFixesTest.CONFIG);
        result.startCustom("Epoch restore review", NOW - 2000);
        return result;
    }

    private static Transaction add(Engine engine, long timestamp, long quantity, long value, PriceSource source) {
        var row = Tx.of(timestamp, quantity > 0 ? TransactionType.GAIN : TransactionType.CONSUMPTION,
                Context.GENERIC, "", true,
                List.of(new Flow(ITEM, "Iron dagger", quantity, Math.abs(value), value, source)));
        engine.session().addTransaction(row, 2000, false);
        return row;
    }

    private static Engine legacy(long quantity, long value, PriceSource source) {
        var original = engine();
        add(original, NOW - 1000, quantity, value, source);
        var state = SaveCopies.copy(original.savedState());
        state.setTrackedBasis(null);
        var restored = engine();
        restored.restore(state, NOW);
        assertEquals(NOW, restored.basis.epoch);
        assertEquals(0, restored.basis.known(ITEM).availableQty);
        return restored;
    }

    private static void restoreOldGain(boolean reload) {
        var engine = legacy(1, 100, PriceSource.GRAND_EXCHANGE);
        String id = engine.session().transactions().get(0).id();
        assertEquals(100, engine.metrics(NOW + 1).net);
        assertNotNull(engine.undoTransaction());
        assertEquals(0, engine.metrics(NOW + 2).net);
        if (reload) {
            var saved = SaveCopies.copy(engine.savedState());
            engine = engine();
            engine.restore(saved, NOW + 100);
        }
        var restored = engine.restoreUndo();
        assertNotNull("restore rebooks a captured receipt, without backfilling old coverage", restored);
        assertEquals(id, restored.id());
        assertEquals(100, engine.metrics(NOW + 200).net);
        assertEquals(0, engine.basis.known(ITEM).availableQty);
        assertEquals(0, engine.basis.known(ITEM).availableBasisGp);
    }

    @Test public void anUndonePreEpochGainMustRemainRestorable() {
        restoreOldGain(false);
    }

    @Test public void aPreEpochGainRestoreMustWorkAfterReload() {
        restoreOldGain(true);
    }

    @Test public void oldKnownZeroReceiptHistoryMustRemainRestorableWithoutCoverage() {
        var engine = legacy(1, 0, PriceSource.NO_VALUE);
        assertNotNull(engine.undoTransaction());
        assertNotNull(engine.restoreUndo());
        assertEquals(1, engine.session().transactions().size());
        assertEquals(0, engine.metrics(NOW + 2).net);
        assertEquals(0, engine.basis.known(ITEM).availableQty);
    }

    @Test public void aPreEpochExpenseControlRestoresWithoutCoverage() {
        var engine = legacy(-1, -100, PriceSource.GRAND_EXCHANGE);
        assertNotNull(engine.undoTransaction());
        assertNotNull(engine.restoreUndo());
        assertEquals(-100, engine.metrics(NOW + 2).net);
        assertEquals(0, engine.basis.known(ITEM).availableQty);
    }

    @Test public void aCurrentGainControlRestoresItsOwnCoverage() {
        var engine = engine();
        add(engine, NOW, 1, 100, PriceSource.GRAND_EXCHANGE);
        assertNotNull(engine.undoTransaction());
        assertNotNull(engine.restoreUndo());
        assertEquals(100, engine.metrics(NOW + 2).net);
        assertEquals(1, engine.basis.known(ITEM).availableQty);
        assertEquals(100, engine.basis.known(ITEM).availableBasisGp);
    }

    @Test public void restoringOldReceiptLeavesNewReservedAndFencedStockUntouched() {
        var engine = legacy(1, 100, PriceSource.GRAND_EXCHANGE);
        assertNotNull(engine.undoTransaction());
        add(engine, NOW + 1, 5, 500, PriceSource.GRAND_EXCHANGE);
        engine.basis.reserve(ITEM, 4);
        engine.basis.fenceRealized(ITEM, NOW + 2);
        engine.basis.openReservationLookup = id -> NOW + 2;
        var gson = new com.google.gson.Gson();
        String before = gson.toJson(engine.basis.stock);
        var restored = engine.restoreUndo();
        assertNotNull(restored);
        assertEquals(100, restored.flows().get(0).unitPrice);
        assertEquals(PriceSource.GRAND_EXCHANGE, restored.flows().get(0).source());
        assertEquals(600, engine.metrics(NOW + 3).net);
        assertEquals(before, gson.toJson(engine.basis.stock));
    }

    @Test public void currentReceiptRestoreStillRefusesALaterRealizationFence() {
        var engine = engine();
        add(engine, NOW, 1, 100, PriceSource.GRAND_EXCHANGE);
        assertNotNull(engine.undoTransaction());
        engine.basis.fenceRealized(ITEM, NOW + 1);
        assertNull(engine.restoreUndo());
        assertEquals(0, engine.metrics(NOW + 2).net);
        assertEquals(0, engine.basis.known(ITEM).availableQty);
        assertFalse(engine.session().undoHistory.get(0).restored);
    }

    @Test public void currentReceiptRestoreStillRefusesAnOpenReservation() {
        var engine = engine();
        add(engine, NOW, 1, 100, PriceSource.GRAND_EXCHANGE);
        assertNotNull(engine.undoTransaction());
        engine.basis.openReservationLookup = id -> NOW + 1;
        assertNull(engine.restoreUndo());
        assertEquals(0, engine.metrics(NOW + 2).net);
        assertEquals(0, engine.basis.known(ITEM).availableQty);
    }

    @Test public void currentPhysicalSinkAndNullRestoresRemainRefused() {
        var engine = engine();
        var sink = add(engine, NOW, -1, -100, PriceSource.GRAND_EXCHANGE);
        assertFalse(engine.basis.canAdd(sink));
        assertFalse(engine.basis.canAdd(null));
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.LootFilter;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Ground Items filtering is presentation only. A live presentation filter can never change
 * canonical money, rollups or corrections. Bank-close burial remains an observed supply cost.
 */
public class PresentationFilterAccountingIsolationEngineTest
{
    private Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig() {
            public int stabilizationTicks() { return 2; }
            public boolean keepTransferAuditRows() { return true; }
            public LootFilter lootPresentationFilter() { return LootFilter.HIGHLIGHTED_LIST_ONLY; }
        };
        Engine engine = new Engine(deltas -> {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Bones", quantity, 35, quantity * 35L)));
            return flows;
        }, new TransactionClassifier(), config);
        engine.ensureSession(1000L);
        return engine;
    }

    /** A Ground Items rule set that would show only feathers; bones are hidden from presentation. */
    private void onlyFeathers(Engine engine)
    {
        engine.setContributionEligibility(new LootPresentationFilterService(new GroundItemsPrefs(
            true, "Feather", "Bones", false)));
    }

    private Transaction gain(Flow... flows)
    {
        return Tx.of(1600L, TransactionType.GAIN, Context.GENERIC,
            "Pickup", true, Arrays.asList(flows));
    }

    @Test public void burialCallbackBeforeGameTickBankCloseMustNotLatchOldTransfer()
    {
        Engine engine = engine();
        ContainerSnapshot bones = new ContainerSnapshot(Collections.singletonMap(526, 1L));
        engine.setBaseline(bones);
        engine.bankOpened(6);
        engine.processIfDirty(bones, 1000L, null);
        engine.markDirty();
        engine.bankClosed();
        engine.processIfDirty(FixtureReads.empty(), 1600L, null);
        engine.processIfDirty(FixtureReads.empty(), 2200L, null);
        Transaction tx = engine.processIfDirty(FixtureReads.empty(), 2800L, null);
        assertEquals(TransactionType.CONSUMPTION, tx.type());
    }

    @Test public void hiddenItemsStillCountInNetAndInsights()
    {
        Engine engine = engine();
        onlyFeathers(engine);
        engine.session().addTransaction(gain(new Flow(526, "Bones", 1L, 35, 35L)), 100, false);
        assertEquals(35L, engine.metrics(2800L).net);
    }

    @Test public void correctionsOperateOnTheWholeCanonicalRow()
    {
        Engine engine = engine();
        onlyFeathers(engine);
        Transaction tx = gain(new Flow(526, "Bones", 1L, 35, 35L),
            new Flow(314, "Feather", 1L, 10, 10L));
        engine.session().addTransaction(tx, 100, false);
        assertEquals(45L, engine.metrics(2800L).income);
        engine.session().correctTransaction(tx.id(), Correction.REVENUE, "Manual correction");
        assertEquals(45L, engine.metrics(3100L).income);
    }

    @Test public void compactionFoldsExactRawValues()
    {
        Engine engine = engine();
        onlyFeathers(engine);
        Session session = engine.session();
        session.addTransaction(gain(new Flow(526, "Bones", 1L, 35, 35L)), 1, false);
        session.addTransaction(gain(new Flow(526, "Bones", 1L, 35, 35L)), 1, false);
        assertTrue(session.compactedTransactionCount > 0L);
        assertEquals(70L, engine.metrics(2800L).net);
    }
}

package com.gpmanager;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static net.runelite.api.GrandExchangeOfferState.*;

/** A proven custody splitter must leave complete, source-backed preparation eligible. */
public class ProductionCustodyRecipeTest {
    static final Map<Integer,Long> DOUGH_BEFORE=Map.of(1933,1L,1937,1L);
    static final Map<Integer,Long> DOUGH_AFTER=Map.of(2307,1L,1931,1L,1935,1L);

    static Map<Integer,Long> coins(Map<Integer,Long> items,long amount) {
        var result=new HashMap<>(items);result.put(995,amount);return result;
    }
    static ProductionRecentTest.Fixture refund(Map<Integer,Long> before) {
        var f=new ProductionRecentTest.Fixture(coins(before,1000));
        f.engine.valuation=deltas->{
            var flows=new ArrayList<Flow>();
            deltas.forEach((id,q)->{
                long price=id==995?1:ProductionRecentTest.price(id);
                flows.add(new Flow(id,id==995?"Coins":ProductionRecentTest.NAMES.getOrDefault(id,"Other"),q,
                    price,SafeMath.multiply(q,price),id==995?PriceSource.FACE_VALUE:PriceSource.GRAND_EXCHANGE));
            });return flows;
        };
        var slots=new OfferSlots();
        f.engine.noteGeOffer(slots.observe(new OfferSlots.Snapshot(0,BUYING,561,1,0,100,0)).get(),"Nature rune",f.at);
        f.become(coins(before,900));
        assertEquals(0,f.live().net);
        f.engine.noteGeOffer(slots.observe(new OfferSlots.Snapshot(0,CANCELLED_BUY,561,1,0,100,0)).get(),"Nature rune",f.at);
        f.engine.noteGeCollect(f.at);
        return f;
    }
    static void recipe(ProductionRecentTest.Fixture f,Transaction made,Map<Integer,Long> before,Map<Integer,Long> after) {
        assertEquals(TransactionType.PROCESSING,made.type());
        assertEquals("Cooking",made.activityName());
        assertFalse(ReviewRules.needsReview(made));
        assertTrue(made.flows().stream().noneMatch(flow->flow.item==995));
        assertNotNull(ProductionRecipes.match(made.flows()));
        assertEquals(100,f.engine.exchange.records.get(0).refundedGp);
        assertEquals(ProductionRecentTest.net(before,after),f.live().net);
        assertEquals(1,f.live().recent.size());
        var row=f.live().recent.get(0);
        assertEquals(f.live().net,row.net());
        var detail=LedgerData.capture(f.engine,f.at,LivePage.entryFor(row));
        // The canceled offer can retain incomplete Market coverage; its neutral refund is no profit.
        assertEquals(f.live().net,detail.net);
        assertEquals(f.live().net,detail.detail.group.value);
        assertEquals(made.flows().size(),detail.detail.group.entries.size());
    }
    @Test public void refundedCoinsAndDoughCountInEitherEvidenceOrdering() {
        for(boolean inventoryFirst:new boolean[]{false,true}) {
            var f=refund(DOUGH_BEFORE);
            if(inventoryFirst) {
                f.engine.markDirty();
                assertNull(f.engine.processIfDirty(new ContainerSnapshot(coins(DOUGH_AFTER,1000)),f.at+=600,null));
            }
            f.use(false);
            recipe(f,f.become(coins(DOUGH_AFTER,1000)),DOUGH_BEFORE,DOUGH_AFTER);
        }
    }
    @Test public void pizzaPreparationOutranksOnlyTheInferredPartialFoodFallback() {
        for(int[] step:new int[][]{{2283,1982,2285},{2285,1985,2287},{2289,319,2297}}) {
            var before=Map.of(step[0],1L,step[1],1L);var after=Map.of(step[2],1L);
            var f=refund(before);f.use(false);
            recipe(f,f.become(coins(after,1000)),before,after);
        }
    }
    @Test public void separatelySettledRefundAndAlreadyArmedProductionKeepWorking() {
        for(boolean separate:new boolean[]{false,true}) {
            var f=refund(DOUGH_BEFORE);
            if(separate)f.become(coins(DOUGH_BEFORE,1000));
            else f.engine.markContext(Context.PRODUCTION,6,"Cooking");
            f.use(false);
            recipe(f,f.become(coins(DOUGH_AFTER,1000)),DOUGH_BEFORE,DOUGH_AFTER);
        }
    }
    @Test public void missingExpiredOrOwnerFencedPreparationDoesNotBecomeProduction() {
        for(String boundary:List.of("missing","expired","owner","tracking")) {
            var f=refund(DOUGH_BEFORE);
            if(!boundary.equals("missing"))f.use(false);
            if(boundary.equals("expired"))f.engine.events.tick(100);
            if(boundary.equals("owner"))f.engine.events.owner(1);
            if(boundary.equals("tracking")) {
                f.engine.resetTracking(false);f.engine.setBaseline(new ContainerSnapshot(coins(DOUGH_BEFORE,900)));
            }
            assertNotEquals(boundary,TransactionType.PROCESSING,f.become(coins(DOUGH_AFTER,1000)).type());
        }
    }
    @Test public void incompleteWrongRatioAndUnrelatedResidualsStayUnmerged() {
        for(Map<Integer,Long> after:List.of(Map.of(2307,1L,1931,1L),Map.of(2307,2L,1931,1L,1935,1L),
            Map.of(2307,1L,1931,1L,1935,1L,560,1L))) {
            var f=refund(DOUGH_BEFORE);f.use(false);
            assertNotEquals(TransactionType.PROCESSING,f.become(coins(after,1000)).type());
        }
    }
    @Test public void explicitConsumeAndDropKeepTheirOwnership() {
        for(boolean drop:new boolean[]{false,true}) {
            var f=refund(Map.of(2289,1L,319,1L));f.use(false);
            if(drop)f.engine.noteDrop(2289,6);
            else f.engine.noteConsume(2289,6,false,ActionKind.EAT,null);
            Transaction made=f.become(coins(Map.of(2297,1L),1000));
            assertNotEquals("drop="+drop,TransactionType.PROCESSING,made.type());
        }
    }
    @Test public void transferMarketAndLootContextsDoNotGainRecipeAuthority() {
        for(Context context:new Context[]{Context.TRANSFER,Context.MARKET,Context.LOOT}) {
            var f=refund(DOUGH_BEFORE);f.use(false);
            f.engine.markContext(context,6,context==Context.MARKET?"Grand Exchange":"fixture");
            assertNotEquals(context.name(),TransactionType.PROCESSING,f.become(coins(DOUGH_AFTER,1000)).type());
        }
    }
    @Test public void residualGroupRemovalUndoAndReloadKeepOriginalPrices() {
        var f=refund(DOUGH_BEFORE);f.use(false);
        var made=f.become(coins(DOUGH_AFTER,1000));recipe(f,made,DOUGH_BEFORE,DOUGH_AFTER);
        String original=JsonCodec.gson().toJson(made.flows());
        assertTrue(f.engine.correctEntries(f.live().recent.get(0).receipts,Correction.IGNORE));
        assertEquals(0,f.live().net);
        var restored=ProductionRecipeTest.engine();restored.restore(SaveCopies.copy(f.engine.savedState()),f.at);
        assertTrue(restored.undoCorrection());
        assertEquals(73,restored.metrics(f.at+1).net);
        assertEquals(original,JsonCodec.gson().toJson(restored.session().findTransaction(made.id()).flows()));
    }
}

package com.gpmanager;

