package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-11-03 (Colosseum Profit Tracker 1.3.3, Hub PR 19987): Minimus takes a spare Dizana's
 * quiver (uncharged) for 4,000 sunfire splinters (OSRS Wiki, Transcript:Minimus). The quiver keeps
 * its alch value when it is won; the swap books one counted Exchanged trade for the difference.
 */
public class QuiverExchangeTest
{
    private static final int QUIVER = 28947, LOCKED = 28949, SPLINTERS = 28924;
    private static final Map<Integer, String> NAMES = Map.of(QUIVER, "Dizana's quiver (uncharged)",
        LOCKED, "Dizana's quiver (l) (uncharged)", SPLINTERS, "Sunfire splinters");
    private static final Map<Integer, Integer> PRICES = Map.of(QUIVER, 48_000, LOCKED, 48_000, SPLINTERS, 333);

    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(QUIVER, 1L, LOCKED, 1L));
    private final Engine engine = new Engine(deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, NAMES.get(id), quantity, PRICES.get(id),
            quantity * PRICES.get(id), PriceSource.GRAND_EXCHANGE)));
        return flows;
    }, new TransactionClassifier(), new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    });
    private long now = 1_000_000L;

    private void start()
    {
        engine.startCustom("Colosseum", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
    }

    private Transaction change(Object... idsAndDeltas)
    {
        for (int index = 0; index < idsAndDeltas.length; index += 2)
            inventory.merge((Integer) idsAndDeltas[index], (Long) idsAndDeltas[index + 1], Long::sum);
        inventory.values().removeIf(quantity -> quantity == 0L);
        int before = engine.session().transactions().size();
        now += 3_000L;
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now, null);
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now + 600L, null);
        List<Transaction> all = engine.session().transactions();
        return all.size() > before ? all.get(all.size() - 1) : null;
    }

    private void talking()
    {
        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
    }

    @Test
    public void minimusSwapBooksOneCountedExchange()
    {
        start();
        talking();
        Transaction swap = change(QUIVER, -1L, SPLINTERS, 4_000L);
        assertSame(TransactionType.TRADE, swap.type());
        assertEquals("Exchanged", swap.note());
        assertTrue(swap.counts());
        assertFalse("not Review", ReviewRules.needsReview(swap));
        assertEquals("the splinters less the quiver's booked value", 4_000L * 333 - 48_000,
            engine.metrics(now + 1_000L).net);
    }

    @Test
    public void otherShapesStayAsTheyWere()
    {
        start();
        assertTrue("without a conversation it stays Review",
            ReviewRules.needsReview(change(QUIVER, -1L, SPLINTERS, 4_000L)));
        talking();
        Transaction locked = change(LOCKED, -1L, SPLINTERS, 4_000L);
        assertNotEquals("only the listed quiver", "Exchanged", locked == null ? null : locked.note());
        talking();
        Transaction partial = change(SPLINTERS, -4_000L, QUIVER, 1L);
        assertNotEquals("the reverse is not the swap", "Exchanged", partial == null ? null : partial.note());
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Receipt retention compacts individually inspectable detail while preserving exact totals
 * and correction-aware metrics.
 */
public class ReceiptRetentionTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final long DAY = 86_400_000L;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int maxHistorySessions()
        {
            return 2_000;
        }

        @Override
        public Retention receiptRetentionDays()
        {
            return Retention.DAYS_90;
        }
    };

    @Test
    public void compactsRowsStrictlyOlderThanTheCutoffByTransactionTimeAcrossOwners()
    {
        // Section L: the cutoff is transaction time, whether the owner is closed or still active.
        long now = 100L * DAY + 12L * 60L * 60L * 1_000L;
        long cutoff = now - 30L * DAY;
        Session boundary = new Session("Boundary", cutoff - 10_000L, SessionMode.GENERAL);
        boundary.addTransaction(receipt(cutoff, 100L), 10, false);
        boundary.close(cutoff + 1_000L);
        Session old = new Session("Old", cutoff - 10_000L, SessionMode.GENERAL);
        old.addTransaction(receipt(cutoff - 1L, 200L), 10, false);
        old.close(cutoff + 2_000L);
        Session active = new Session("Active", cutoff - 2L * DAY, SessionMode.GENERAL);
        active.addTransaction(receipt(cutoff - DAY, 300L), 10, false);
        active.addTransaction(receipt(cutoff + DAY, 50L), 10, false);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Arrays.asList(boundary, old, old, active)), now);

        assertEquals(2, FixtureReads.compactOlderThan(engine, 30, now));
        assertEquals("a row exactly at the cutoff is retained", 1, boundary.transactions().size());
        assertTrue(old.transactions().isEmpty());
        assertEquals(1L, old.compactedTransactionCount);
        assertEquals(200L, old.metrics(now).income);
        assertEquals("only the active owner's overdue row folds", 1, active.transactions().size());
        assertEquals(350L, active.metrics(now).income);
        assertEquals(0, FixtureReads.compactOlderThan(engine, 30, now));
        assertEquals(0, FixtureReads.compactOlderThan(engine, 0, now));
    }

    @Test
    public void derivedPendingClaimIdKeepsItsOriginAuditRowRetained()
    {
        long now = 400L * DAY;
        Session session = new Session("Loot origin", now - 200L * DAY, SessionMode.GENERAL);
        Transaction audit = receipt(now - 200L * DAY + 1_000L, 0L);
        session.addTransaction(audit, 10, false);
        session.close(now - 200L * DAY + 2_000L);

        SavedState state = new SavedState(null, null, Collections.singletonList(session));
        state.setPendingClaims(Collections.singletonList(new SavedState.PendingClaim(
            audit.id() + "#2", net.runelite.api.gameval.ItemID.WILDY_LOOT_KEY1, 1L,
            audit.timestamp)));

        Engine engine = engine();
        engine.restore(state, now);

        assertEquals("a multi-key claim protects the shared origin audit row", 1,
            session.transactions().size());
        assertTrue(engine.pendingClaims().get(0).claimId().endsWith("#2"));
        assertEquals(0, FixtureReads.compactOlderThan(engine, 90, now));
    }

    @Test
    public void compactionKeepsTheNameEncountersAndExactTotals()
    {
        long now = 400L * DAY;
        Session session = new Session("Favourite trip", now - 200L * DAY, SessionMode.AUTO);

        session.addTransaction(receipt(now - 200L * DAY + 1_000L, 100L), 10, false);
        session.addTransaction(receipt(now - 200L * DAY + 61_000L, 250L), 10, false);
        session.addTransaction(receipt(now - 200L * DAY + 62_500L, -40L), 10, false);
        String encounter = session.addEncounter(true, now - 200L * DAY + 62_000L);
        session.attachToEncounter(session.transactions().get(1).id(), encounter, false);
        session.close(now - 200L * DAY + 120_000L);

        Metrics before = session.metrics(now);
        long bestKillBefore = session.bestKill();
        Engine engine = engine();
        engine.restore(new SavedState(null, null, Collections.singletonList(session)), now);

        assertEquals("current-schema restore already compacted the overdue rows", 0,
            FixtureReads.compactOlderThan(engine, 90, now));

        assertTrue(session.transactions().isEmpty());
        assertEquals(3L, session.compactedTransactionCount);
        assertEquals("Favourite trip", session.name());
        assertEquals("compacted receipts keep the kill count", 1, session.pk().kills);

        Metrics after = session.metrics(now);
        assertEquals(before.income, after.income);
        assertEquals(before.cost, after.cost);
        assertEquals(before.net, after.net);
        assertEquals(350L, after.income);
        assertEquals(40L, after.cost);
        assertEquals(250L, bestKillBefore);
        assertEquals(bestKillBefore, session.bestKill());
    }

    @Test
    public void currentSchemaRestoreCompactsOverdueRowsWithoutWaitingForUtcRollover()
    {
        long now = 120L * DAY + 12L * 60L * 60L * 1_000L;
        Session overdue = closedWithReceipt("Overdue", now - 120L * DAY - 1L, 750L);
        SavedState current = new SavedState(null, null, Collections.singletonList(overdue));

        Engine engine = engine();
        engine.restore(current, now);

        assertTrue(overdue.transactions().isEmpty());
        assertEquals(1L, overdue.compactedTransactionCount);
        assertEquals(750L, overdue.metrics(now).income);
        assertEquals("the restore counts as today's sweep", 0, engine.maintainRetention(now + 1_000L));
    }

    @Test
    public void shippingRetentionWindowsAreBoundedAndUnknownReadsAs90Days()
    {
        assertEquals(Arrays.asList(30, 90, 180, 365), Arrays.asList(
            Retention.DAYS_30.getDays(), Retention.DAYS_90.getDays(),
            Retention.DAYS_180.getDays(), Retention.DAYS_365.getDays()));
        assertEquals(4, Retention.values().length);
        for (Retention period : Retention.values())
        {
            assertFalse("no shipping window means retain forever", period.getDays() <= 0);
        }
    }

    private static Session closedWithReceipt(String name, long endedAt, long value)
    {
        long start = Math.max(0L, endedAt - 10_000L);
        Session session = new Session(name, start, SessionMode.GENERAL);
        session.addTransaction(receipt(start + 1_000L, value), 10, false);
        session.close(endedAt);
        return session;
    }

    private static Transaction receipt(long timestamp, long value)
    {
        return Tx.of(timestamp, value < 0L ? TransactionType.CONSUMPTION : TransactionType.LOOT,
            Context.LOOT, "receipt", true, Collections.singletonList(new Flow(995, "Coins",
                value < 0L ? -1L : 1L, (int) Math.min(Integer.MAX_VALUE, Math.abs(value)), value)));
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), CONFIG);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.function.LongSupplier;
import org.junit.Assume;
import org.junit.Test;
import org.junit.experimental.categories.Category;

/**
 * Release pass 2026-09-28: timing budget on a heavy profile (a running Grind at the 2,000 detailed
 * receipts the default keeps, 300 finished Grinds). Dev-only; runs when GP_PERF is set:
 * {@code GP_PERF=1 ./gradlew test --tests 'com.gpmanager.ReleasePerfTest'}. Prints median/p99.
 */
@Category(PerformanceBudget.class)
public class ReleasePerfTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final Random RANDOM = new Random(20260928L);

    @Test
    public void heavyProfileStaysInsideTheFrameBudget() throws Exception
    {
        Assume.assumeTrue("set GP_PERF to run", System.getenv("GP_PERF") != null);
        Engine engine = PresentationLifecycleTest.engine();
        for (int grind = 0; grind < 300; grind++)
        {
            Session done = new Session("Grind " + grind, T0 - (300 - grind) * 3_600_000L, SessionMode.GENERAL);
            for (int i = 0; i < 60; i++)
            {
                done.addTransaction(receipt(done.startedAt + i * 1_000L), 2_000, false);
            }
            done.close(done.startedAt + 3_000_000L);
            engine.history.add(0, done);
        }
        engine.startCustom("Greater Nechryael", T0);
        for (int i = 0; i < 2_000; i++)
        {
            engine.session().addTransaction(receipt(T0 + i * 1_800L), 2_000, false);
        }
        long now = T0 + 4_000_000L;

        List<Transaction> all = engine.session().transactions();
        report("Bp.transaction x2000", () -> all.stream().mapToLong(t -> Accounting.transaction(t).cost).sum());
        report("Bp.costSplit x2000", () -> all.stream().mapToLong(t -> Accounting.costSplit(t).supplies).sum());
        report("spellName x2000", () -> all.stream().mapToLong(t -> t.spellName().length()).sum());
        report("Ledger contributions x2000", () -> all.stream().mapToLong(t -> Contribution.project(t).size()).sum());
        report("session metrics", () -> engine.session().metrics(now).net);
        int[] flip = {0};
        report("Live capture (cold)", () -> LiveSnapshot.capture(engine, now,
            new LiveContext(false, null, flip[0]++ % 2, PvpState.NONE, "", false, "", false)).net);
        report("Live capture (warm)", () -> LiveSnapshot.capture(engine, now, LiveContext.NONE).net);
        report("Ledger capture", () -> LedgerData.capture(engine, now, LedgerData.Entry.current()).net);
        report("Grinds capture", () -> GrindsData.capture(engine, now, false, null).plans.size());
        // A flipper-sized G.E. history (the 64 retained closed lifecycles plus 8 open slots), each
        // settled by a receipt deep in the finished Grinds, so Market rows pay their receipt lookups.
        for (int i = 0; i < 72; i++)
        {
            GeOffer offer = new GeOffer("perf-offer-" + i, i < 64 ? -1 : i - 64,
                i % 2 == 0 ? GeOffer.Side.SELL : GeOffer.Side.BUY, 1_319, "Rune axe", 10L, 7_202L,
                T0 - i * 60_000L, engine.session().id());
            Session holder = engine.history.get(engine.history.size() - 1 - i);
            offer.settlementId = holder.transactions().get(holder.transactions().size() - 1).id();
            offer.stage = i < 64 ? GeOffer.Stage.CLOSED : GeOffer.Stage.OPEN;
            engine.exchange.records.add(offer);
        }
        report("Market rows x72 (old)", () -> engine.marketRows().size());
        report("Live capture (warm, G.E.)", () -> LiveSnapshot.capture(engine, now, LiveContext.NONE).net);
        // Settlements in the newest Grinds, then settlements whose receipts retention has compacted.
        List<GeOffer> offers = engine.exchange.records;
        for (int i = 0; i < offers.size(); i++)
        {
            Session holder = engine.history.get(i);
            offers.get(i).settlementId = holder.transactions().get(0).id();
        }
        report("Market rows x72 (recent)", () -> engine.marketRows().size());
        for (GeOffer offer : offers)
        {
            offer.settlementId = "compacted-" + offer.offerId;
        }
        report("Market rows x72 (compacted)", () -> engine.marketRows().size());
        GpManagerConfig config = HudBuilderTest.config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
        LiveSnapshot snapshot = LiveSnapshot.capture(engine, now, LiveContext.NONE);
        report("HUD+ update + render", () ->
        {
            builder.update(snapshot, f -> true, now);
            return overlay.render(g).width;
        });
        Gson gson = new Gson();
        String once = gson.toJson(engine.savedState());
        SavedState copy = gson.fromJson(once, SavedState.class);
        System.out.println("PERF save JSON bytes " + once.length()
            + ", identical to the old detached copy: " + once.equals(gson.toJson(copy)));
        report("save snapshot (engine lock)", () -> engine.savedState().schemaVersion);
        report("detach round trip", () -> gson.fromJson(gson.toJson(engine.savedState()), SavedState.class).schemaVersion);
        report("save snapshot + JSON", () -> gson.toJson(engine.savedState()).length());
        SessionRepository repository = new SessionRepository(gson,
            FilepathTestSupport.root(java.nio.file.Files.createTempDirectory("gp-perf")), false);
        Persistence coordinator = new Persistence(null, null, repository,
            new OrderedPersistenceWriter(repository, null), engine);
        report("save intent (client thread)", () -> coordinator.currentIntent().base);
        // 1.1: the periodic gameplay save reuses closed sessions' JSON; every 10th is full.
        report("quick save intent (client thread)", () -> coordinator.currentIntent().base);
        System.out.println("PERF quick save identical to one toJson: "
            + PersistenceProbe.snapshotJson(coordinator, null, true).replaceFirst("\"savedAtEpochMillis\":\\d+", "")
                .equals(gson.toJson(engine.savedState()).replaceFirst("\"savedAtEpochMillis\":\\d+", "")));
    }

    private static Transaction receipt(long at)
    {
        List<Flow> flows;
        TransactionType type;
        ActionKind action = null;
        switch (RANDOM.nextInt(5))
        {
            case 0:
                type = TransactionType.LOOT;
                flows = Arrays.asList(new Flow(1_319, "Rune axe", 1L, 7_202, 7_202L),
                    new Flow(560, "Death rune", 46L, 187, 8_602L));
                break;
            case 1:
                type = TransactionType.CONSUMPTION;
                action = ActionKind.CAST;
                flows = Arrays.asList(new Flow(560, "Death rune", -4L, 187, -748L),
                    new Flow(565, "Blood rune", -2L, 341, -682L), new Flow(555, "Water rune", -6L, 5, -30L));
                break;
            case 2:
                type = TransactionType.CONSUMPTION;
                action = ActionKind.DRINK;
                flows = Arrays.asList(new Flow(2434, "Prayer potion(4)", -1L, 9_800, -9_800L),
                    new Flow(139, "Prayer potion(3)", 1L, 7_350, 7_350L));
                break;
            case 3:
                type = TransactionType.CONSUMPTION;
                action = ActionKind.FIRE;
                flows = Collections.singletonList(new Flow(808, "Steel dart", -2L, 4, -8L));
                break;
            default:
                type = TransactionType.GAIN;
                flows = Collections.singletonList(new Flow(526, "Bones", 1L, 37, 37L));
                break;
        }
        Transaction transaction = new Transaction(at, type,
            type == TransactionType.LOOT ? Context.LOOT : Context.GENERIC, "",
            "Greater Nechryael", true, flows, Confidence.CONFIRMED, "perf", null);
        transaction.setAction(action);
        return transaction;
    }

    private static void report(String name, LongSupplier work)
    {
        for (int i = 0; i < 20; i++)
        {
            work.getAsLong();
        }
        long[] times = new long[100];
        for (int i = 0; i < times.length; i++)
        {
            long start = System.nanoTime();
            work.getAsLong();
            times[i] = System.nanoTime() - start;
        }
        Arrays.sort(times);
        System.out.printf("PERF %-24s median %7.3f ms  p99 %7.3f ms%n", name, times[50] / 1e6, times[98] / 1e6);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;
import static org.junit.Assert.*;

/** Missing-price recovery must publish financial facts and physical coverage atomically. */
public class RepricedBasisTest {
    private static final long NOW = 1_700_000_000_000L;
    private static final int ITEM = 1203;

    private static Engine engine(long price, PriceSource source) {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = new Engine(changes -> {
            var result = new ArrayList<Flow>();
            changes.forEach((id, quantity) -> result.add(new Flow(id, id == 995 ? "Coins" : "Iron dagger",
                    quantity, id == 995 ? 1 : price, quantity * (id == 995 ? 1 : price),
                    id == 995 ? PriceSource.FACE_VALUE : source)));
            return result;
        }, new TransactionClassifier(), ReviewFixesTest.CONFIG);
        engine.startCustom("Recovered prices", NOW);
        return engine;
    }

    private static Transaction gain(Engine engine, long at) {
        var row = Tx.of(at, TransactionType.GAIN, Context.GENERIC, "", true,
                List.of(new Flow(ITEM, "Iron dagger", 1, 0, 0, PriceSource.UNPRICED)));
        engine.session().addTransaction(row, 2000, false);
        return row;
    }

    private static void coverage(Engine engine, long quantity, long value) {
        assertEquals(quantity, engine.basis.known(ITEM).availableQty);
        assertEquals(value, engine.basis.known(ITEM).availableBasisGp);
    }

    @Test public void aNewlyKnownAcquisitionSuppliesItsBasisOnce() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = gain(engine, NOW + 1);
        var old = row.flows().get(0);
        engine.recheck();
        coverage(engine, 1, 100);
        assertEquals(100, engine.metrics(NOW + 100).net);
        assertEquals(PriceSource.GRAND_EXCHANGE, row.flows().get(0).source());
        assertEquals("Iron dagger", row.flows().get(0).name);
        assertEquals("a detached old flow cannot acquire the new quote", PriceSource.UNPRICED, old.source());
        long revision = engine.revision();
        engine.recheck();
        coverage(engine, 1, 100);
        assertEquals(revision, engine.revision());
        assertEquals(1, engine.session().transactions().size());
    }

    @Test public void theLaterSaleBooksOnlyItsDifferenceFromRecoveredBasis() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        gain(engine, NOW + 1);
        engine.recheck();
        engine.setBaseline(new ContainerSnapshot(Map.of(ITEM, 1L, 995, 10_000L)));
        var slots = new OfferSlots();
        slots.observe(new OfferSlots.Snapshot(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0));
        engine.noteGeOffer(slots.observe(new OfferSlots.Snapshot(0, GrandExchangeOfferState.SELLING,
                ITEM, 1, 0, 150, 0)).get(), "Iron dagger", NOW + 600);
        settle(engine, Map.of(995, 10_000L), NOW + 1200);
        engine.noteGeOffer(slots.observe(new OfferSlots.Snapshot(0, GrandExchangeOfferState.SOLD,
                ITEM, 1, 1, 150, 147)).get(), "Iron dagger", NOW + 3600);
        settle(engine, Map.of(995, 10_147L), NOW + 4200);
        assertEquals(147, engine.metrics(NOW + 6000).net);
        assertEquals(100, engine.marketRows().get(0).trackedBasisConsumedGp);
        assertEquals(47, engine.marketRows().get(0).realizedResultGp);
        coverage(engine, 0, 0);
    }

    private static void settle(Engine engine, Map<Integer, Long> inventory, long at) {
        engine.markDirty();
        for (int tick = 0; tick < 3; tick++)
            engine.processIfDirty(new ContainerSnapshot(inventory), at + tick * 600, null);
    }

    @Test public void knownZeroIsCoverageRatherThanAnUnknownBasis() {
        var engine = engine(0, PriceSource.NO_VALUE);
        gain(engine, NOW + 1);
        engine.recheck();
        coverage(engine, 1, 0);
        assertEquals(1, engine.basis.reserve(ITEM, 1).trackedQty);
    }

    @Test public void anUnloadedQuoteIsAReadOnlyRetry() {
        var engine = engine(0, PriceSource.UNPRICED);
        var row = gain(engine, NOW + 1);
        long revision = engine.revision();
        engine.recheck();
        assertEquals(revision, engine.revision());
        assertEquals(PriceSource.UNPRICED, row.flows().get(0).source());
        coverage(engine, 0, 0);
    }

    @Test public void aLaterPhysicalUseRefusesTheWholePriceUpdate() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = gain(engine, NOW + 1);
        var use = Tx.of(NOW + 2, TransactionType.CONSUMPTION, Context.GENERIC, "", true,
                List.of(new Flow(ITEM, "Iron dagger", -1, 0, 0, PriceSource.UNPRICED)));
        engine.session().addTransaction(use, 2000, false);
        engine.recheck();
        assertEquals(PriceSource.UNPRICED, row.flows().get(0).source());
        assertEquals("pricing a sink does not deplete it twice", NOW + 2, engine.basis.known(ITEM).fencedAt);
        coverage(engine, 0, 0);
    }

    @Test public void aFullyUnknownOpenSaleBlocksRetroactiveCoverage() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = gain(engine, NOW + 1);
        custody(engine);
        long revision = engine.revision();
        engine.recheck();
        assertEquals(PriceSource.UNPRICED, row.flows().get(0).source());
        assertEquals(revision, engine.revision());
        coverage(engine, 0, 0);
    }

    @Test public void aKnownReservationAlsoBlocksRetroactiveCoverage() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = gain(engine, NOW + 1);
        var record = custody(engine);
        record.reservedTrackedQty = 1;
        record.reservedTrackedBasisGp = 80;
        engine.recheck();
        assertEquals(PriceSource.UNPRICED, row.flows().get(0).source());
        assertEquals(80, record.reservedBasis());
        coverage(engine, 0, 0);
    }

    @Test public void anOutsideCollectionLeavesARealizationFenceEvenForUnknownStock() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = gain(engine, NOW + 1);
        var record = custody(engine);
        engine.exchange.away(record);
        engine.recheck();
        assertEquals(PriceSource.UNPRICED, row.flows().get(0).source());
        coverage(engine, 0, 0);
    }

    @Test public void anAmbiguousCustodyHandoffCannotResurrectUnknownStock() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = gain(engine, NOW + 1);
        engine.exchange.handoff(custody(engine), "Unknown disposition");
        engine.recheck();
        assertEquals(PriceSource.UNPRICED, row.flows().get(0).source());
        coverage(engine, 0, 0);
    }

    @Test public void aConfirmedFullReturnAllowsTheStillOwnedItemToBePriced() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        gain(engine, NOW + 1);
        var record = custody(engine);
        record.returnedQty = 1;
        engine.recheck();
        coverage(engine, 1, 100);
    }

    @Test public void aPartialReturnDoesNotInventAnUnreservedShare() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = gain(engine, NOW + 1);
        var record = custody(engine);
        record.capturedQty = record.offeredQty = 2;
        record.returnedQty = 1;
        engine.recheck();
        assertEquals(PriceSource.UNPRICED, row.flows().get(0).source());
        coverage(engine, 0, 0);
    }

    @Test public void recordedDecisionsAndExistingQuotesAreNotRewritten() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var ignored = gain(engine, NOW + 1);
        ignored.applyCorrection(Correction.IGNORE, "Owner decision");
        var known = Tx.of(NOW + 2, TransactionType.GAIN, Context.GENERIC, "", true,
                List.of(new Flow(526, "Bones", 1, 7, 7, PriceSource.MANUAL_OVERRIDE)));
        engine.session().addTransaction(known, 2000, false);
        long revision = engine.revision();
        engine.recheck();
        assertEquals(revision, engine.revision());
        assertEquals(PriceSource.UNPRICED, ignored.flows().get(0).source());
        assertEquals(Correction.IGNORE, ignored.correction());
        assertEquals(7, known.flows().get(0).value);
        assertEquals(PriceSource.MANUAL_OVERRIDE, known.flows().get(0).source());
    }

    @Test public void aQuoteFailureCannotPublishHalfOfAReceipt() {
        var engine = new Engine(changes -> {
            if (changes.containsKey(526)) throw new IllegalStateException("Unavailable quote");
            return List.of(new Flow(ITEM, "Iron dagger", 1, 100, 100, PriceSource.GRAND_EXCHANGE));
        }, new TransactionClassifier(), ReviewFixesTest.CONFIG);
        engine.startCustom("Atomic quote", NOW);
        var row = Tx.of(NOW + 1, TransactionType.GAIN, Context.GENERIC, "", true, List.of(
                new Flow(ITEM, "Iron dagger", 1, 0, 0, PriceSource.UNPRICED),
                new Flow(526, "Bones", 1, 0, 0, PriceSource.UNPRICED)));
        engine.session().addTransaction(row, 2000, false);
        long revision = engine.revision();
        assertThrows(IllegalStateException.class, engine::recheck);
        assertEquals(revision, engine.revision());
        assertTrue(row.flows().stream().allMatch(flow -> flow.source() == PriceSource.UNPRICED));
        assertEquals(0, engine.metrics(NOW + 100).net);
        coverage(engine, 0, 0);
    }

    private static GeOffer custody(Engine engine) {
        var record = new GeOffer();
        record.offerId = "synthetic-custody";
        record.itemId = ITEM;
        record.side = GeOffer.Side.SELL;
        record.offeredQty = record.capturedQty = 1;
        record.placedAtEpochMillis = record.basisCapturedAtEpochMillis = NOW + 10;
        record.basisSource = PriceSource.UNPRICED;
        engine.exchange.records.add(record);
        engine.exchange.now = NOW + 20;
        return record;
    }

    @Test public void preEpochPricesMayResolveWithoutBackfillingOwnership() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = gain(engine, NOW + 1);
        engine.basis.epoch = NOW + 10;
        engine.recheck();
        assertEquals(100, row.flows().get(0).value);
        coverage(engine, 0, 0);
    }

    @Test public void rejectedMixedRowsKeepAllOriginalQuotesAndCachedMoney() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        var row = Tx.of(NOW + 1, TransactionType.GAIN, Context.GENERIC, "", true, List.of(
                new Flow(ITEM, "Iron dagger", 1, 0, 0, PriceSource.UNPRICED),
                new Flow(526, "Bones", 1, 7, 7, PriceSource.MANUAL_OVERRIDE)));
        engine.session().addTransaction(row, 2000, false);
        engine.basis.fenceRealized(ITEM, NOW + 2);
        var snapshot = MoneySnapshot.of(engine);
        long revision = engine.revision();
        engine.recheck();
        assertSame(snapshot, MoneySnapshot.of(engine));
        assertEquals(revision, engine.revision());
        assertEquals(PriceSource.UNPRICED, row.flows().get(0).source());
        assertEquals(7, row.flows().get(1).value);
        coverage(engine, 0, 0);
    }

    @Test public void recoveryAndItsCoverageSurviveReloadWithoutDuplicating() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        gain(engine, NOW + 1);
        engine.recheck();
        var restored = engine(100, PriceSource.GRAND_EXCHANGE);
        restored.restore(SaveCopies.copy(engine.savedState()), NOW + 100);
        restored.recheck();
        coverage(restored, 1, 100);
        assertEquals(100, restored.metrics(NOW + 200).net);
        restored.resetData(NOW + 300);
        restored.recheck();
        coverage(restored, 0, 0);
    }

    @Test public void aDifferentLoadedOwnerNeverReceivesThePreviousOwnersCoverage() {
        var engine = engine(100, PriceSource.GRAND_EXCHANGE);
        gain(engine, NOW + 1);
        engine.recheck();
        var originalOwner = SaveCopies.copy(engine.savedState());
        engine.restore(new SavedState(null, null, List.of()), NOW + 100);
        engine.recheck();
        coverage(engine, 0, 0);
        engine.restore(originalOwner, NOW + 200);
        engine.recheck();
        coverage(engine, 1, 100);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A data / factory reset leaves the profile exactly as a new install: no session, nothing
 * accruing. Only Start or the plugin's genuine-activity start
 * ({@link Engine#autoStart}, when Automatic tracking is on)
 * begins tracking, each exactly once; the passive work around a reset (priming, ticks with
 * unchanged containers, saved-state snapshots, restore) never does.
 */
public class ResetStateLifecycleTest
{
    private static final int OAK_LOGS = 1521;

    private static Engine engine(AtomicBoolean autoStart)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public boolean autoStartSession() { return autoStart.get(); }
            @Override public int stabilizationTicks() { return 0; }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> e : deltas.entrySet())
            {
                flows.add(new Flow(e.getKey(), "Oak logs", e.getValue(), 40, e.getValue() * 40L));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }

    private static Engine resetEngine(AtomicBoolean autoStart)
    {
        Engine engine = engine(autoStart);
        engine.ensureSession(1_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        engine.session().addTransaction(Tx.of(1_500L, TransactionType.GAIN,
            Context.GENERIC, "Old", true,
            Collections.singletonList(new Flow(OAK_LOGS, "Oak logs", 5L, 40, 200L))), 100, false);
        engine.resetData(2_000L);
        return engine;
    }

    @Test
    public void resetLeavesANewInstall()
    {
        Engine engine = resetEngine(new AtomicBoolean(true));
        assertNull("no session until play or Start", engine.session());
        assertNull(engine.freePlay());
        assertEquals("no history survives", 0, engine.history().size());
        assertEquals(0L, engine.metrics(2_000L).net);
        assertEquals(0L, engine.metrics(3_600_000L).elapsed);
        assertFalse("no custom session starts because of reset", engine.customActive());
    }

    @Test
    public void startAfterResetBeginsTrackingOnce()
    {
        Engine engine = resetEngine(new AtomicBoolean(false));
        engine.togglePause(3_000L);
        assertNotNull("Start creates Free play", engine.session());
        assertFalse("and it runs, never born paused", engine.session().paused);
        assertEquals("active time starts at Start", 60_000L, engine.session().elapsed(63_000L));
        String id = engine.session().id();
        assertFalse("no second start from the activity path", engine.autoStart(3_100L));
        assertEquals(id, engine.session().id());
    }

    @Test
    public void genuineActivityStartsTrackingOnceAndThenBooks()
    {
        Engine engine = resetEngine(new AtomicBoolean(true));
        assertTrue(engine.autoStart(3_000L));
        assertFalse("already running: no duplicate start", engine.autoStart(3_100L));

        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        engine.markDirty();
        Map<Integer, Long> logs = new HashMap<>();
        logs.put(OAK_LOGS, 1L);
        assertNull(engine.processIfDirty(new ContainerSnapshot(logs), 3_200L, null));
        Transaction gain = engine.processIfDirty(new ContainerSnapshot(logs), 3_800L, null);
        assertNotNull(gain);
        assertEquals(40L, gain.net());
        assertEquals(40L, engine.metrics(4_000L).net);
    }

    @Test
    public void passiveResetWorkNeverStartsTracking()
    {
        Engine engine = resetEngine(new AtomicBoolean(true));
        engine.beginPriming();
        ContainerSnapshot unchanged = new ContainerSnapshot(new HashMap<>());
        for (int tick = 0; tick < 20; tick++)
        {
            assertNull(engine.processIfDirty(unchanged, 2_200L + tick * 600L, null));
        }
        engine.resume(15_000L, PauseReason.LIFECYCLE);
        engine.resume(15_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        engine.resume(15_000L, PauseReason.IDLE);
        assertNull("resumes have nothing to resume", engine.session());

        SavedState committed = engine.savedState();
        assertTrue(committed.history().isEmpty());
        Engine reloaded = engine(new AtomicBoolean(true));
        reloaded.restore(new Gson().fromJson(new Gson().toJson(committed), SavedState.class), 16_000L);
        assertNull("a reload of the reset profile is still a new install", reloaded.session());
        assertEquals(0L, reloaded.metrics(3_600_000L).net);
    }

    @Test
    public void activityStartHonoursAutomaticTracking()
    {
        AtomicBoolean autoStart = new AtomicBoolean(false);
        Engine engine = resetEngine(autoStart);
        assertFalse("Automatic tracking off: activity cannot start", engine.autoStart(3_000L));
        assertNull(engine.session());
        autoStart.set(true);
        assertTrue(engine.autoStart(4_000L));
        assertFalse(engine.autoStart(4_100L));
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.client.util.Filepath;
import org.junit.BeforeClass;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Checkpoint 4 retention/compaction soak (charter L, T, 4.1). One synthetic owner with 11k+
 * receipts over three years of UTC days: corrected, split, excluded, unpriced and uncertain rows,
 * PK encounters and one unresolved loot-key claim. Every window compacts the
 * same fixture and must reconcile exactly against totals computed from the uncompacted rows.
 * Offline model/engine only — not a live client soak.
 */
public class RetentionCompactionSoakTest
{
    private static final long DAY = 86_400_000L;
    private static final int DAYS = 1_100;
    private static final long BASE = Instant.parse("2023-01-15T00:00:00Z").toEpochMilli();
    private static final long NOW = BASE + DAYS * DAY + 12L * 3_600_000L;
    private static final int LOGS = 1511;
    private static final int SHARK = 385;
    private static final int COINS = 995;
    private static final int UNPRICED = 4151;
    private static final int KEY = 26_892;
    private static final long WINDOW = 60_000L;
    /** The unresolved claim's audit row id; assigned by {@link #fixture()}. */
    private static String PENDING_CLAIM_ROW = "";
    private static final String SETTLED_CLAIM_ID = "settled-claim-id";

    private static final Gson GSON = new Gson();

    @Rule
    public final TemporaryFolder folder = new TemporaryFolder();

    @BeforeClass
    public static void bindCodec()
    {
        JsonCodec.bind(GSON);
    }

    /** Ground truth computed from the uncompacted fixture rows. */
    private static final class Truth
    {
        final Map<String, long[]> sessionMoney = new LinkedHashMap<>();
        /** Default-window compacted subset, independent of post-restore aggregates. */
        final Map<String, long[]> sessionCompactedMoney = new LinkedHashMap<>();
        final Map<String, long[]> sessionPk = new LinkedHashMap<>();
        final TreeMap<String, Long> dayNet = new TreeMap<>();
        long transactions;
        long net;
        long activeMillis;
        long kills;
        long deaths;
        long bestKill;
        int sessions;
    }

    private final StringBuilder report = new StringBuilder();

    @Test
    public void tenThousandReceiptsOverThreeYearsCompactAndReconcileAcrossEveryWindowAndReload() throws Exception
    {
        List<Session> fixture = fixture();
        Truth truth = truth(fixture);
        assertTrue("10k+ transaction fixture: " + truth.transactions, truth.transactions >= 10_000L);
        assertTrue("multi-year fixture: " + DAYS + " UTC days", DAYS >= 3 * 365);
        assertEquals(DAYS, truth.dayNet.size());
        line("label=SYNTHETIC_NOT_LIVE_CLIENT");
        line("fixture_sessions=" + truth.sessions);
        line("fixture_transactions=" + truth.transactions);
        line("fixture_utc_days=" + DAYS);
        line("fixture_pk_encounters=" + (truth.kills + truth.deaths));

        SavedState fullState = state(fixture, true);
        String fullJson = GSON.toJson(fullState);
        line("uncompacted_json_bytes=" + fullJson.getBytes(StandardCharsets.UTF_8).length);

        // Uncompacted save/load through the repository: the 10k+ profile round trip and its cost.
        Path uncompactedDir = folder.newFolder("uncompacted").toPath();
        SessionRepository uncompacted = new SessionRepository(GSON,
            FilepathTestSupport.root(uncompactedDir), false);
        long t = System.nanoTime();
        assertTrue(PersistenceProbe.save(uncompacted, copy(fullJson)));
        line("uncompacted_save_ms=" + ms(t));
        t = System.nanoTime();
        SavedState loadedFull = uncompacted.load();
        line("uncompacted_load_ms=" + ms(t));
        assertEquals(truth.sessions, loadedFull.history().size());
        line("uncompacted_dir_bytes=" + dirSize(uncompactedDir));

        // Every shipping window compacts the same fixture and reconciles exactly.
        for (Retention period : Retention.values())
        {
            verifyWindow(period, fullJson, truth);
        }
        // Legacy Forever migrates to 365 days (charter L); the enum read is the migration.

        // The default 90-day window carries the lifetime, merge, CSV and reload soak.
        Engine engine = engine(Retention.DAYS_90);
        t = System.nanoTime();
        engine.restore(copy(fullJson), NOW);
        line("restore_and_compact_90d_ms=" + ms(t));
        verifyLifetimeArchive(engine, truth, fixture);
        verifyPendingClaim(engine, truth, "after restore");
        verifyCsvReconciliation(engine, truth);
        verifyRepeatedSaveReload(engine, truth);

        Path out = Path.of("build", "reports", "perf");
        Files.createDirectories(out);
        Files.write(out.resolve("retention-compaction-soak.txt"),
            ("retention_compaction_soak\n" + report).getBytes(StandardCharsets.UTF_8));
    }

    // ── windows ───────────────────────────────────────────────────────────────

    private void verifyWindow(Retention period, String fullJson, Truth truth)
    {
        int days = period.getDays();
        Engine engine = engine(period);
        long t = System.nanoTime();
        engine.restore(copy(fullJson), NOW);
        long restoreMs = ms(t);
        long cutoff = NOW - days * DAY;
        int retained = 0;
        long compacted = 0L;
        int kept = 0;
        for (Session session : engine.history())
        {
            long[] money = truth.sessionMoney.get(session.name());
            assertNotNull(session.name(), money);
            Metrics metrics = session.metrics(NOW);
            assertEquals(session.name() + " revenue " + days + "d", money[0], metrics.income);
            assertEquals(session.name() + " costs " + days + "d", money[1], metrics.cost);
            assertEquals(session.name() + " net " + days + "d", money[2], metrics.net);
            assertEquals(session.name() + " elapsed", money[3], metrics.elapsed);
            long[] pk = truth.sessionPk.get(session.name());
            if (pk != null)
            {
                assertEquals(pk[0], session.pk().kills);
                assertEquals(pk[1], session.pk().deaths);
                assertEquals(session.name() + " best kill", pk[2], session.bestKill());
            }
            for (Transaction row : session.transactions())
            {
                retained++;
                if (row.id().equals(PENDING_CLAIM_ROW))
                {
                    kept++;
                    continue;
                }
                assertTrue(days + "d window retained an older row at " + row.timestamp,
                    row.timestamp >= cutoff || ReviewRules.needsReview(row));
            }
            compacted += session.compactedTransactionCount;
        }
        assertEquals("retained + compacted = every fixture row (" + days + "d)", truth.transactions, retained + compacted);
        assertTrue(days + "d window compacted nothing", compacted > 0L);
        assertEquals("the unresolved claim's audit row survives every window", 1, kept);
        assertEquals("a second sweep is a no-op", 0, FixtureReads.compactOlderThan(engine, days, NOW));
        line(String.format(Locale.ROOT, "window_%dd retained_rows=%d compacted_rows=%d restore_ms=%d",
            days, retained, compacted, restoreMs));
    }

    // ── lifetime archive / records ────────────────────────────────────────────

    private void verifyLifetimeArchive(Engine engine, Truth truth, List<Session> fixture)
    {
        // PvP facts live on each session and survive receipt compaction and reload.
        AllTime pvp = new AllTime();
        pvp.addPvp(engine.sessions());
        assertEquals(truth.kills, pvp.kills);
        assertEquals(truth.deaths, pvp.deaths);
        assertEquals("best kill survives compaction", truth.bestKill, pvp.bestKill);
        Engine reloaded = engine(Retention.DAYS_90);
        reloaded.restore(copy(GSON.toJson(engine.savedState())), NOW);
        AllTime afterReload = new AllTime();
        afterReload.addPvp(reloaded.sessions());
        assertEquals(pvp.toString(), afterReload.toString());
    }

    /** All-time facts summed from day rows and/or the lifetime archive; equal strings mean equal facts. */
    private static final class AllTime
    {
        long net, active, kills, deaths, bestKill, starts, namedStarts;

        void addPvp(List<Session> sessions)
        {
            for (Session session : sessions)
            {
                kills += session.pk().kills;
                deaths += session.pk().deaths;
                bestKill = Math.max(bestKill, session.bestKill());
            }
        }

        @Override
        public String toString()
        {
            StringBuilder sb = new StringBuilder();
            sb.append("net=").append(net).append(" active=").append(active).append(" kills=").append(kills)
                .append(" deaths=").append(deaths).append(" bestKill=").append(bestKill).append(" starts=").append(starts)
                .append(" named=").append(namedStarts).append('\n');
            return sb.toString();
        }
    }

    // ── pending claim ─────────────────────────────────────────────────────────

    private void verifyPendingClaim(Engine engine, Truth truth, String when)
    {
        List<SavedState.PendingClaim> claims = engine.pendingClaims();
        assertEquals("the unresolved claim is neither lost nor duplicated " + when, 1, claims.size());
        assertEquals(PENDING_CLAIM_ROW, claims.get(0).claimId());
        Session owner = null;
        Transaction audit = null;
        int settledRows = 0;
        for (Session session : engine.history())
        {
            for (Transaction row : session.transactions())
            {
                if (row.id().equals(PENDING_CLAIM_ROW))
                {
                    owner = session;
                    audit = row;
                }
                if (row.claimId().equals(SETTLED_CLAIM_ID)) settledRows++;
            }
        }
        assertNotNull("the unresolved claim's audit row stays individually inspectable " + when, audit);
        assertEquals("Day 3", owner.name());
        assertEquals("the audit row is not counted twice", 0L, audit.net());
        assertEquals("the settled claim was dropped on restore, its settlement booked once",
            0, settledRows == 0 ? 0 : settledRows - 1);
        assertEquals(truth.sessionMoney.get("Day 3")[2], owner.metrics(NOW).net);
    }

    // ── performance ───────────────────────────────────────────────────────────

    // ── CSV ───────────────────────────────────────────────────────────────────

    /** Retained receipts plus the one compacted contribution reconcile exactly to the session. */
    private void verifyCsvReconciliation(Engine engine, Truth truth)
    {
        for (String name : new String[] {"PK trip " + (DAYS - 90), "Day 10"})
        {
            Session session = session(engine, name);
            assertTrue(session.compactedTransactionCount > 0L);
            Metrics metrics = session.metrics(NOW);
            assertEquals(truth.sessionMoney.get(name)[2], metrics.net);
            Session.CompactedContribution compacted = session.compactedContribution();
            long revenue = compacted.income;
            long costs = compacted.cost;
            for (Transaction row : session.transactions())
            {
                Accounting.Amounts amounts = Accounting.transaction(row);
                if (amounts.available && amounts.included)
                {
                    revenue += amounts.income;
                    costs += amounts.cost;
                }
            }
            assertEquals(name + ": retained + compacted revenue", metrics.income, revenue);
            assertEquals(name + ": retained + compacted costs", metrics.cost, costs);
        }
    }

    // ── merge ─────────────────────────────────────────────────────────────────

    // ── repeated save / reload ────────────────────────────────────────────────

    private void verifyRepeatedSaveReload(Engine seed, Truth truth) throws IOException
    {
        Path directory = folder.newFolder("reload").toPath();
        SessionRepository repository = new SessionRepository(GSON,
            FilepathTestSupport.root(directory), false);
        Engine engine = seed;
        String fingerprint = fingerprint(engine);
        long saveNs = 0L;
        long loadNs = 0L;
        long restoreNs = 0L;
        long minBytes = Long.MAX_VALUE;
        long maxBytes = 0L;
        final int rounds = 200;
        for (int round = 0; round < rounds; round++)
        {
            long t = System.nanoTime();
            SavedState state = engine.savedState();
            assertTrue("save round " + round, PersistenceProbe.save(repository, state));
            saveNs += System.nanoTime() - t;
            long bytes = Files.size(FilepathTestSupport.path(
                repository.dataDir().joinSegment("sessions.json")));
            minBytes = Math.min(minBytes, bytes);
            maxBytes = Math.max(maxBytes, bytes);
            t = System.nanoTime();
            SavedState loaded = repository.load();
            loadNs += System.nanoTime() - t;
            assertEquals(SavedState.CURRENT_SCHEMA_VERSION, loaded.schemaVersion);
            assertEquals(round + 1L, loaded.revision);
            engine = engine(Retention.DAYS_90);
            t = System.nanoTime();
            engine.restore(loaded, NOW + round);
            restoreNs += System.nanoTime() - t;
            assertEquals("round " + round + " drifted", fingerprint, fingerprint(engine));
        }
        verifyPendingClaim(engine, truth, "after " + rounds + " reloads");
        // The only expected byte-size drift is the decimal width of the monotonically increasing
        // revision field; payload shape and financial fingerprint remain stable.
        assertTrue("file size only changes with revision width: " + minBytes + ".." + maxBytes,
            maxBytes - minBytes <= Long.toString(rounds + 1L).length() - 1L);
        line("reload_rounds=" + rounds);
        line("reload_profile_bytes=" + maxBytes);
        line("reload_avg_save_ms=" + saveNs / rounds / 1_000_000L);
        line("reload_avg_load_ms=" + loadNs / rounds / 1_000_000L);
        line("reload_avg_restore_ms=" + restoreNs / rounds / 1_000_000L);
        line("reload_dir_bytes=" + dirSize(directory));
    }

    /** Every accounting fact a reload must preserve, as one comparable string. */
    private static String fingerprint(Engine engine)
    {
        StringBuilder sb = new StringBuilder();
        AllTime pvp = new AllTime();
        pvp.addPvp(engine.sessions());
        sb.append(pvp.kills).append('|').append(pvp.bestKill).append('|');
        sb.append(engine.history().size()).append('|').append(engine.pendingClaims().size()).append('|');
        for (Session session : engine.history())
        {
            Metrics metrics = session.metrics(NOW);
            sb.append(session.id()).append(':').append(metrics.income).append(':').append(metrics.cost)
                .append(':').append(session.transactions().size()).append(':').append(session.compactedTransactionCount)
                .append(':').append(session.pk().encounters()).append(':').append(session.bestKill()).append(';');
        }
        return sb.toString();
    }

    // ── fixture ───────────────────────────────────────────────────────────────

    private static List<Session> fixture()
    {
        List<Session> sessions = new ArrayList<>();
        for (int day = 0; day < DAYS; day++)
        {
            // Day DAYS-90 straddles the default cutoff: its kill compacts, its later death stays retained.
            boolean pk = day % 10 == 5 || day == DAYS - 90;
            long start = BASE + day * DAY + 3_600_000L;
            Session session = new Session(pk ? "PK trip " + day : "Day " + day, start,
                SessionMode.AUTO);
            session.setActivityHint(pk ? "PKing" : "Woodcutting");
            long logsQuantity = dayLogsQuantity(day);
            String splitTarget = null;
            String ignoreTarget = null;
            for (int i = 0; i < 7; i++)
            {
                Transaction loot = row(start + (i + 1) * 60_000L, TransactionType.LOOT, Context.LOOT,
                    "Woodcutting", true, Confidence.CONFIRMED,
                    new Flow(LOGS, "Logs", logsQuantity, 39, logsQuantity * 39L));
                session.addTransaction(loot, 100_000, false);
                if (i == 1) splitTarget = loot.id();
                if (i == 2) ignoreTarget = loot.id();
                session.recordAction("Woodcutting");
            }
            session.addTransaction(row(start + 8 * 60_000L, TransactionType.CONSUMPTION, Context.GENERIC,
                "Woodcutting", true, Confidence.CONFIRMED,
                new Flow(SHARK, "Shark", -2L, 385, -770L)), 100_000, false);
            session.addTransaction(row(start + 9 * 60_000L, TransactionType.UNCERTAIN, Context.GENERIC,
                "Woodcutting", false, Confidence.UNCERTAIN,
                new Flow(COINS, "Coins", 1_000L, 1, 1_000L)), 100_000, false);
            session.addTransaction(row(start + 10 * 60_000L, TransactionType.LOOT, Context.LOOT,
                "Woodcutting", true, Confidence.LIKELY,
                new Flow(UNPRICED, "Abyssal whip", 1L, 0, 0L)), 100_000, false);
            if (day % 3 == 0) assertTrue(session.correctTransaction(ignoreTarget, Correction.IGNORE, "Not mine"));
            if (day % 3 == 1) assertTrue(session.correctTransaction(ignoreTarget, Correction.COST, "Bought"));
            if (day % 3 == 2) assertTrue(session.splitItem(splitTarget, LOGS, logsQuantity / 2, "half"));
            if (day == 3)
            {
                Transaction audit = row(start + 13 * 60_000L, TransactionType.ADJUSTMENT, Context.PK_LOOT,
                    "Loot key audit", false, Confidence.CONFIRMED,
                    new Flow(KEY, "Loot key", 1L, 0, 0L));
                PENDING_CLAIM_ROW = audit.id();
                session.addTransaction(audit, 100_000, false);
            }
            if (day == 4)
            {
                Transaction settlement = row(start + 13 * 60_000L, TransactionType.PK_LOOT, Context.PK_LOOT,
                    "Loot key chest", true, Confidence.CONFIRMED,
                    new Flow(COINS, "Coins", 5_000L, 1, 5_000L));
                settlement.setSourceClaimId(SETTLED_CLAIM_ID);
                session.addTransaction(settlement, 100_000, false);
            }
            if (pk)
            {
                long killAt = start + 20 * 60_000L;
                String kill = session.addEncounter(true, killAt);
                Transaction loot = row(killAt + 1_000L, TransactionType.PK_LOOT, Context.PK_LOOT, "PKing", true,
                    Confidence.CONFIRMED, new Flow(COINS, "Coins", 50_000L + (DAYS - day) * 10L, 1, 50_000L + (DAYS - day) * 10L));
                session.addTransaction(loot, 100_000, false);
                session.attachToEncounter(loot.id(), kill, false);
                long deathAt = start + 12L * 3_600_000L;
                String death = session.addEncounter(false, deathAt);
                Transaction loss = row(deathAt + 1_000L, TransactionType.PK_DEATH_LOSS, Context.PK_DEATH, "PKing", true,
                    Confidence.CONFIRMED, new Flow(SHARK, "Shark", -(80L + day % 7), 385, -(80L + day % 7) * 385L));
                session.addTransaction(loss, 100_000, false);
                session.attachToEncounter(loss.id(), death, false);
            }
            session.close(pk ? start + 13L * 3_600_000L : start + 60 * 60_000L);
            sessions.add(session);
        }
        return sessions;
    }

    private static long dayLogsQuantity(long day)
    {
        return 20L + day % 7;
    }

    private static Transaction row(long at, TransactionType type, Context context, String activity,
        boolean counted, Confidence confidence, Flow flow)
    {
        return new Transaction(at, type, context, type.name().toLowerCase(Locale.ROOT), activity, counted,
            Collections.singletonList(flow), confidence, "soak", null);
    }

    private static Truth truth(List<Session> sessions)
    {
        Truth truth = new Truth();
        truth.sessions = sessions.size();
        for (Session session : sessions)
        {
            Metrics metrics = session.metrics(NOW);
            truth.sessionMoney.put(session.name(), new long[] {metrics.income, metrics.cost, metrics.net, metrics.elapsed});
            long compactedRevenue = 0L;
            long compactedCosts = 0L;
            long cutoff = NOW - Retention.DAYS_90.getDays() * DAY;
            for (Transaction row : session.transactions())
            {
                if (row.timestamp >= cutoff
                    || row.id().equals(PENDING_CLAIM_ROW)
                    || SETTLED_CLAIM_ID.equals(row.claimId())
                    || row.type() == TransactionType.TRANSFER
                    || !row.counts())
                {
                    continue;
                }
                compactedRevenue += row.revenue();
                compactedCosts += row.costs();
            }
            truth.sessionCompactedMoney.put(session.name(),
                new long[] {compactedRevenue, compactedCosts});
            truth.net += metrics.net;
            truth.activeMillis += metrics.elapsed;
            truth.transactions += session.transactions().size();
            for (Transaction row : session.transactions())
            {
                if (!row.counts()) continue;
                String day = LocalDate.ofEpochDay(Math.floorDiv(row.timestamp, DAY)).toString();
                truth.dayNet.merge(day, row.net(), Long::sum);
            }
            if (session.name().startsWith("PK trip"))
            {
                PkTally pk = session.pk();
                truth.sessionPk.put(session.name(), new long[] {pk.kills, pk.deaths, session.bestKill()});
                truth.kills += pk.kills;
                truth.deaths += pk.deaths;
                truth.bestKill = Math.max(truth.bestKill, session.bestKill());
            }
        }
        return truth;
    }

    private static SavedState state(List<Session> sessions, boolean withClaims)
    {
        List<Session> newestFirst = new ArrayList<>(sessions);
        Collections.reverse(newestFirst);
        SavedState state = new SavedState(null, null, newestFirst);
        state.setSchemaVersion(SavedState.CURRENT_SCHEMA_VERSION);
        state.setProfileTimeZoneId("UTC");
        state.setSavedAtEpochMillis(NOW);
        if (!withClaims) return state;
        List<SavedState.PendingClaim> claims = new ArrayList<>();
        claims.add(new SavedState.PendingClaim(PENDING_CLAIM_ROW, KEY, 1L,
            BASE + 3 * DAY));
        claims.add(new SavedState.PendingClaim(SETTLED_CLAIM_ID, KEY, 1L,
            BASE + 4 * DAY));
        state.setPendingClaims(claims);
        return state;
    }

    private static SavedState copy(String json)
    {
        return GSON.fromJson(json, SavedState.class);
    }

    private static Engine engine(Retention period)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int maxHistorySessions() { return 5_000; }
            @Override public int maxTransactionsPerSession() { return 100_000; }
            @Override public Retention receiptRetentionDays() { return period; }
        };
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), config);
    }

    private static Session session(Engine engine, String name)
    {
        for (Session session : engine.history())
        {
            if (session.name().equals(name)) return session;
        }
        throw new AssertionError("no session " + name);
    }

    private void line(String text)
    {
        report.append(text).append('\n');
    }

    private static long ms(long startNanos)
    {
        return (System.nanoTime() - startNanos) / 1_000_000L;
    }

    private static long dirSize(Path root) throws IOException
    {
        final long[] total = {0L};
        try (java.util.stream.Stream<Path> paths = Files.walk(root))
        {
            paths.filter(Files::isRegularFile).forEach(path ->
            {
                try { total[0] += Files.size(path); }
                catch (IOException ex) { throw new java.io.UncheckedIOException(ex); }
            });
        }
        return total[0];
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ReviewInboxEngineTest
{
    @Test
    public void inboxContainsOnlyAutomaticUncertainRowsAndGroupsReasons()
    {
        Engine engine = engine();
        long now = 100_000L;
        engine.ensureSession(now - 10_000L);
        Transaction first = uncertain("Mixed inventory change", now - 5_000L, 100L);
        Transaction second = uncertain("Mixed inventory change", now - 2_000L, 200L);
        Transaction otherReason = uncertain("Unknown source", now - 1_000L, 300L);
        engine.session().addTransaction(first, 20, false);
        engine.session().addTransaction(second, 20, false);
        engine.session().addTransaction(otherReason, 20, false);
        assertTrue(engine.correctTransaction(second.id(), Correction.COST, "Owner already decided"));

        List<ReviewRow> rows = engine.getReviewRows(now);
        assertEquals(2, rows.size());
        assertEquals(5_000L, Math.max(rows.get(0).ageMillis, rows.get(1).ageMillis));
        assertEquals("Mixed inventory change", rows.get(1).why);
        ReviewRow row = rows.get(0);
        assertEquals(otherReason.id(), row.transaction);
        assertEquals(engine.session().id(), row.session);
        assertEquals(300L, row.value);
        assertEquals("Unknown source", row.why);
        assertEquals(1, row.items.size());
        assertTrue(row.decisions.contains(Decision.IGNORE));
        assertFalse(rows.stream().anyMatch(entry -> second.id().equals(entry.transaction)));
    }

    @Test
    public void decideAllCreatesOnePersistedUndoUnitAndSkipsHandCorrectedRows()
    {
        Engine engine = engine();
        long now = 200_000L;
        engine.ensureSession(now - 10_000L);
        Transaction first = uncertain("Review", now - 3_000L, 100L);
        Transaction second = uncertain("Review", now - 2_000L, 200L);
        Transaction handCorrected = uncertain("Review", now - 1_000L, 50L);
        engine.session().addTransaction(first, 20, false);
        engine.session().addTransaction(second, 20, false);
        engine.session().addTransaction(handCorrected, 20, false);
        assertTrue(engine.correctTransaction(handCorrected.id(), Correction.COST, "Single decision"));

        assertEquals(2, engine.applyDecision(engine.previewDecision(Decision.GAIN, row -> true, now)));
        assertEquals(2, latestDecision(engine).changes().size());
        assertEquals(250L, engine.metrics(now).net);
        assertEquals(Correction.COST, handCorrected.correction());
        assertEquals(0, engine.getReviewRows(now).size());

        Gson gson = new Gson();
        Session restored = gson.fromJson(gson.toJson(engine.session()), Session.class);
        assertEquals(250L, restored.metrics(now).net);
        assertTrue(restored.undoCorrection());
        assertEquals(Correction.AUTO, find(restored, first.id()).correction());
        assertEquals(Correction.AUTO, find(restored, second.id()).correction());
        assertEquals(Correction.COST, find(restored, handCorrected.id()).correction());
        assertEquals(-50L, restored.metrics(now + 1L).net);
        assertTrue(restored.correctionHistory.get(restored.correctionHistory.size() - 1).undone);
        assertTrue(engine.undoCorrection());
        assertTrue(latestDecision(engine).undone);
    }

    @Test
    public void decideAllPreviewIsExactAndRevisionBound()
    {
        Engine engine = engine();
        long now = 300_000L;
        engine.ensureSession(now - 10_000L);
        Transaction first = uncertain("Review", now - 3_000L, 100L);
        Transaction second = uncertain("Review", now - 2_000L, 200L);
        Transaction handCorrected = uncertain("Review", now - 1_000L, 50L);
        engine.session().addTransaction(first, 20, false);
        engine.session().addTransaction(second, 20, false);
        engine.session().addTransaction(handCorrected, 20, false);
        assertTrue(engine.correctTransaction(handCorrected.id(), Correction.COST, "Single"));

        Engine.DecisionPreview gain = engine.previewDecision(Decision.GAIN, row -> true, now);
        assertEquals("exact affected rows from canonical ids", 2, gain.rowCount());
        assertEquals(Arrays.asList(first.id(), second.id()), gain.transactionIds);
        assertEquals("exact prospective personal-Net delta", 300L, gain.netDelta);
        assertEquals(-300L, engine.previewDecision(Decision.COST, row -> true, now).netDelta);
        assertEquals(0L, engine.previewDecision(Decision.IGNORE, row -> true, now).netDelta);
        assertEquals(0, engine.previewDecision(Decision.GAIN, row -> false, now).rowCount());

        // A canonical mutation after the preview moves the revision: the stale preview never applies.
        long before = engine.revision();
        engine.session().addTransaction(uncertain("Review", now - 100L, 5L), 20, false);
        assertTrue(engine.revision() != before);
        assertEquals(-1, engine.applyDecision(gain));
        assertEquals(Correction.AUTO, first.correction());
        assertEquals(-50L, engine.metrics(now).net);

        Engine.DecisionPreview fresh = engine.previewDecision(Decision.GAIN, row -> true, now);
        assertEquals(3, fresh.rowCount());
        assertEquals(305L, fresh.netDelta);
        assertEquals(3, engine.applyDecision(fresh));
        assertEquals("applied delta equals the previewed delta", -50L + 305L, engine.metrics(now).net);
        assertEquals("one undo unit for the whole batch", 3, latestDecision(engine).changes().size());
        assertTrue(engine.undoCorrection());
        assertEquals(-50L, engine.metrics(now + 1L).net);
    }

    private static Transaction find(Session session, String id)
    {
        for (Transaction transaction : session.transactions())
        {
            if (id.equals(transaction.id())) return transaction;
        }
        throw new AssertionError("Missing transaction " + id);
    }

    private static Transaction uncertain(String why, long at, long value)
    {
        return new Transaction(at, TransactionType.UNCERTAIN, Context.GENERIC,
            "Uncertain item change", "Testing", false,
            Arrays.asList(new Flow((int) value, "Item " + value, 1L, (int) value, value)),
            Confidence.UNCERTAIN, why, null);
    }

    private static Engine engine()
    {
        return new Engine(deltas -> java.util.Collections.<Flow>emptyList(),
            new TransactionClassifier(), new GpManagerConfig() { });
    }

    private static CorrectionRecord latestDecision(Engine engine)
    {
        java.util.List<CorrectionRecord> log = engine.session().correctionHistory;
        return log.get(log.size() - 1);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.Map;
import net.runelite.api.ItemComposition;
import static net.runelite.api.gameval.ItemID.*;
import net.runelite.client.game.ItemMapping;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;

/**
 * Untradeable reward containers opened for their contents (OSRS Wiki, 2026-11-07; Gilded Ledger's
 * minigame rewards listed the Wintertodt supply crate). Each keeps its own alchemy value, so
 * opening one is the container leaving and its contents arriving: income, never a Review.
 */
@RunWith(Parameterized.class)
public class RewardContainerOpeningTest {
    @Parameterized.Parameters(name="{1}") public static Object[][] containers() {
        return new Object[][] {
            {PIRATE_CASKET,"Casket",30},
            {TOA_RUNE_CACHE,"Cache of runes",60},
            {FROZEN_CACHE,"Frozen cache",60},
            {FORGOTTEN_LOCKBOX,"Forgotten lockbox",60},
            {MACRO_QUIZ_MYSTERY_BOX,"Mystery box",3},
            {BH_EP_CRATE_2,"Bounty crate (tier 1)",300},
            {BH_EP_CRATE_10,"Bounty crate (tier 9)",300},
            {WINT_REROLL_BOX,"Extra supply crate",300},
            {CONSTRUCTION_SUPPLY_CRATE,"Supply crate",87},
            {CASTLEWARS_CRATE,"Castle wars supply crate",1}
        };
    }
    @Parameterized.Parameter(0) public int container;
    @Parameterized.Parameter(1) public String name;
    @Parameterized.Parameter(2) public int ha;
    static final int REWARD = UNCUT_SAPPHIRE;
    private long now = 1_000_000;

    private ItemComposition definition(int id) {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
                new Class<?>[]{ItemComposition.class}, (proxy, method, args) -> {
            switch(method.getName()) {
                case "getName": return id == container ? name : id == COINS ? "Coins" : "Uncut sapphire";
                case "getId": return id;
                case "getHaPrice": return id == container ? ha : 1;
                case "isTradeable": return id != container;
                default: return method.getReturnType() == boolean.class ? false : method.getReturnType() == int.class ? 0 : null;
            }
        });
    }
    private Engine engine() {
        JsonCodec.bind(new com.google.gson.Gson());
        var values = new Valuation(new GpManagerConfig(){}, this::definition, (id,active) -> id == REWARD ? 50 : 0,
                id -> Valuation.hasUnsupportedMapping(ItemMapping.map(id)), Valuation.Economy.NORMAL);
        var engine = new Engine(values,new TransactionClassifier(),new GpManagerConfig(){
            @Override public int stabilizationTicks(){return 0;}
        });
        engine.startCustom("Reward container",now);
        engine.setBaseline(new ContainerSnapshot(Map.of(container,1L)));
        return engine;
    }

    @Test public void openingBooksTheContentsAsIncomeWithoutAReview() {
        var engine = engine(); var opened = Map.of(REWARD,4L,COINS,500L);
        engine.processIfDirty(new ContainerSnapshot(opened),now += 3000,null);
        engine.processIfDirty(new ContainerSnapshot(opened),now + 600,null);
        var rows = engine.session().transactions();
        assertEquals(rows.toString(),1,rows.size());
        assertFalse(name+" must not wait for a decision",ReviewRules.needsReview(rows.get(0)));
        assertEquals("the contents less the container's own alchemy value",4*50L+500-ha,engine.metrics(now+1000).net);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.Map;
import net.runelite.api.ItemComposition;
import static net.runelite.api.gameval.ItemID.*;
import net.runelite.client.game.ItemMapping;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;

/** Wiki-pinned shop packs; current HA policy stays intact, optional Loot Tracker is absent. */
@RunWith(Parameterized.class)
public class RewardPackOpeningTest {
    @Parameterized.Parameters(name="{0}: {1}") public static Object[][] packs() {
        return new Object[][] {
            {PACK_SOFTCLAY,"Soft clay pack",6,12012,"Golden nugget",60,10,SOFTCLAY,"Soft clay",100},
            {PACK_SOFTCLAY_GUILD,"Soft clay pack",6,21341,"Unidentified minerals",30,10,SOFTCLAY,"Soft clay",100},
            {STAR_PACK_SOFTCLAY,"Soft clay pack",90,25527,"Stardust",30,150,SOFTCLAY,"Soft clay",100},
            {REWARD_GEM_BAG,"Bag full of gems",24,12012,"Golden nugget",60,40,UNCUT_SAPPHIRE,"Uncut sapphire",40},
            {REWARD_GEM_BAG_GUILD,"Bag full of gems",24,21341,"Unidentified minerals",30,20,UNCUT_SAPPHIRE,"Uncut sapphire",40},
            {STAR_REWARD_GEM_BAG,"Bag full of gems",180,25527,"Stardust",30,300,UNCUT_SAPPHIRE,"Uncut sapphire",40}
        };
    }
    @Parameterized.Parameter(0) public int pack;
    @Parameterized.Parameter(1) public String name;
    @Parameterized.Parameter(2) public int ha;
    @Parameterized.Parameter(3) public int currency;
    @Parameterized.Parameter(4) public String currencyName;
    @Parameterized.Parameter(5) public int currencyHa;
    @Parameterized.Parameter(6) public int cost;
    @Parameterized.Parameter(7) public int reward;
    @Parameterized.Parameter(8) public String rewardName;
    @Parameterized.Parameter(9) public int quantity;
    private long now = 1_000_000;

    private ItemComposition definition(int id) {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
                new Class<?>[]{ItemComposition.class}, (proxy, method, args) -> {
            switch(method.getName()) {
                case "getName": return id == pack ? name : id == currency ? currencyName : rewardName;
                case "getId": return id;
                case "getHaPrice": return id == pack ? ha : id == currency ? currencyHa : 1;
                case "isTradeable": return id == reward;
                default: return method.getReturnType() == boolean.class ? false : method.getReturnType() == int.class ? 0 : null;
            }
        });
    }
    private Valuation values() {
        return new Valuation(new GpManagerConfig(){}, this::definition,
                (id,active) -> id == reward ? 50 : id == 561 ? 100 : 0,
                id -> Valuation.hasUnsupportedMapping(ItemMapping.map(id)), Valuation.Economy.NORMAL);
    }
    private Engine engine() {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = new Engine(values(),new TransactionClassifier(),new GpManagerConfig(){
            @Override public int stabilizationTicks(){return 0;}
        });
        engine.startCustom("Reward pack",now);
        engine.setBaseline(new ContainerSnapshot(Map.of()));
        return engine;
    }
    private Transaction settle(Engine engine, Map<Integer,Long> held) {
        now += 3000;
        engine.processIfDirty(new ContainerSnapshot(held),now,null);
        engine.processIfDirty(new ContainerSnapshot(held),now + 600,null);
        var rows = engine.session().transactions();
        return rows.isEmpty() ? null : rows.get(rows.size()-1);
    }
    @Test public void openingAfterPurchaseBooksTheContentsWithoutOptionalLootTracker() {
        var engine = engine();
        settle(engine,Map.of(currency,(long)cost));
        assertEquals((long)cost*currencyHa,engine.metrics(now+1000).net);
        engine.events.put(Inbox.DIALOGUE,0,1,4,null);
        assertEquals(TransactionType.TRADE,settle(engine,Map.of(pack,1L)).type());
        assertEquals("held pack retains its current own HA",ha,engine.metrics(now+1000).net);
        engine.events.drop(Inbox.DIALOGUE);
        var opened = settle(engine,Map.of(reward,(long)quantity));
        System.out.println("pack="+pack+" before="+ha+" actualAfter="+engine.metrics(now+1000).net
                +" expectedAfter="+quantity*50L+" opening="+opened.type());
        assertFalse("opening a paid reward pack must not require a decision",ReviewRules.needsReview(opened));
        assertEquals(quantity*50L,engine.metrics(now+1000).net);
    }
    @Test public void theReviewMustNotChangePackOrCurrencyValuationPolicy() {
        var values = values();
        var flow = values.value(Map.of(pack,1L),now).get(0);
        assertEquals(ha,flow.unitPrice);
        assertEquals(PriceSource.HIGH_ALCHEMY,flow.source());
        assertEquals(currencyHa,values.value(Map.of(currency,1L),now).get(0).unitPrice);
    }

    @Test public void anExecutedShopSaleStillBooksATrade() {
        var engine=engine();engine.setBaseline(new ContainerSnapshot(Map.of(pack,1L)));
        engine.markContext(Context.MARKET,4,"sell 1 "+name);
        var sale=settle(engine,Map.of(currency,1L));
        assertEquals(TransactionType.TRADE,sale.type());
        assertEquals("Exchanged",Semantics.verbOf(sale));
        assertEquals(currencyHa-ha,engine.metrics(now+1000).net);
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

import com.google.gson.Gson;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * PRE-R5C.2B.3: schema-105 durable proven action labels are bounded presentation metadata that
 * survive restart, repository round trips and profile backup, while never touching money.
 */
public class Schema105ActionLabelPersistenceTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final String PROFILE = "profile-key-105";

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    @Test
    public void exactLabelIsDurableInSchema105StateAndReloads()
    {
        Session session = new Session("General", 1_000L, SessionMode.GENERAL);
        Transaction labelled = cast("Ice Burst", 2_000L);
        Transaction generic = genericCast(3_000L);
        session.addTransaction(labelled, 100, false);
        session.addTransaction(generic, 100, false);
        SavedState state = new SavedState(session, null, Collections.emptyList());
        assertEquals(110, state.schemaVersion);
        String json = new Gson().toJson(state);
        assertTrue("the bounded label is a stable JSON field",
            json.contains("\"observedActionLabel\":\"Ice Burst\""));

        SavedState loaded = new Gson().fromJson(json, SavedState.class);
        Transaction restored = FixtureReads.currentSession(loaded).transactions().get(0);
        assertNotNull(restored.actionLabel());
        assertEquals("Ice Burst", restored.actionLabel().value);
        assertEquals("the reloaded receipt keeps its money", labelled.net(), restored.net());
        assertNull("an unlabelled receipt stays generic",
            FixtureReads.currentSession(loaded).transactions().get(1).actionLabel());
    }

    @Test
    public void malformedOversizedControlAndGenericLabelsNormalizeToNull()
    {
        assertNull("invalid punctuation is rejected",
            normalizedWire("\"Ice Burst!!!\"", false).actionLabel());
        assertNull("oversized labels are rejected",
            normalizedWire("\"" + repeat("Ice Burst ", 7) + "\"", false).actionLabel());
        assertNull("control characters are rejected",
            normalizedWire("\"Ice\\u0000Burst\"", false).actionLabel());
        assertNull("generic Cast text never becomes an exact label",
            normalizedWire("\"Cast\"", false).actionLabel());
        assertNull("Autocast text never becomes an exact label",
            normalizedWire("\"Autocast\"", false).actionLabel());

        Transaction sanitized = normalizedWire("\"<col=ff9040>Ice Burst</col>\"", false);
        assertNotNull(sanitized.actionLabel());
        assertEquals("markup is stripped, never displayed", "Ice Burst",
            sanitized.actionLabel().value);
        assertFalse(sanitized.actionLabel().value.contains("<"));

        Transaction nonCast = normalizedWire("\"Ice Burst\"", true);
        assertNull("a non-CAST receipt cannot keep a stale spell label",
            nonCast.actionLabel());
    }

    @Test
    public void labelMutationsNeverDriftFinancialFingerprint()
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", T0);
        Transaction transaction = cast(null, T0 + 100L);
        engine.session().addTransaction(transaction, 100, false);
        String before = fingerprint(transaction);
        long netBefore = engine.metrics(T0 + 200L).net;

        transaction.setActionLabel(ActionLabel.of("Ice Burst"));
        assertEquals("setting a label never changes money", before, fingerprint(transaction));
        transaction.setActionLabel(ActionLabel.of("Smoke Barrage"));
        assertEquals("changing a label never changes money", before, fingerprint(transaction));
        transaction.setActionLabel(null);
        assertEquals("clearing a label never changes money", before, fingerprint(transaction));
        assertEquals(netBefore, engine.metrics(T0 + 200L).net);

        Transaction trade = trade();
        String tradeBefore = fingerprint(trade);
        trade.setActionLabel(ActionLabel.of("Ice Burst"));
        assertNull("a non-CAST receipt never reads a spell label", trade.actionLabel());
        assertEquals("GE-shaped receipts stay financially identical", tradeBefore, fingerprint(trade));
    }

    @Test
    public void ownerFenceKeepsBookedLabelsAndClearsOnlyPendingEvidence()
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", T0);
        Transaction cast = cast("Ice Burst", T0 + 100L);
        engine.session().addTransaction(cast, 100, false);
        long net = engine.metrics(T0 + 200L).net;

        engine.clearActionEvidence();

        assertNotNull("booked labels survive the presentation owner fence",
            cast.actionLabel());
        assertEquals("Ice Burst", cast.actionLabel().value);
        assertEquals("the fence never touches money", net, engine.metrics(T0 + 200L).net);
    }

    @Test
    public void onlyTheCurrentSchemaIsRead()
    {
        assertEquals(110, SavedState.CURRENT_SCHEMA_VERSION);
        SavedState old = new SavedState();
        old.setSchemaVersion(107);
        assertFalse("an older schema is never read", old.isSupportedSchema());
        assertFalse((old.schemaVersion > SavedState.CURRENT_SCHEMA_VERSION));
        SavedState future = new SavedState();
        future.setSchemaVersion(SavedState.CURRENT_SCHEMA_VERSION + 1);
        assertTrue((future.schemaVersion > SavedState.CURRENT_SCHEMA_VERSION));
        assertFalse("a newer schema is refused/read-only", future.isSupportedSchema());
        assertEquals("a restored profile saves as the current schema", 110,
            engine().savedState().schemaVersion);
    }

    @Test
    public void exactSpellGroupsSurviveRestartAndMergeLaterCasts()
    {
        long now = System.currentTimeMillis();
        Engine source = engine();
        source.startCustom("Vorkath", now);
        source.session().addTransaction(cast("Ice Burst", now + 1_000L), 100, false);
        source.session().addTransaction(cast("Ice Burst", now + 2_000L), 100, false);
        // Runes that name no spell (a staff covered them) keep the click; runes that do name one win.
        Transaction smoke = genericCast(now + 3_000L);
        smoke.setActionLabel(ActionLabel.of("Smoke Barrage"));
        source.session().addTransaction(smoke, 100, false);
        source.session().addTransaction(genericCast(now + 4_000L), 100, false);
        SavedState detached = source.savedState();
        assertEquals("detach keeps the bounded label", "Ice Burst",
            FixtureReads.currentSession(detached).transactions().get(0).actionLabel().value);

        Engine restored = engine();
        restored.restore(detached, now + 5_000L);
        Session session = restored.session();
        List<Transaction> restoredTransactions = session.transactions();
        assertEquals("Ice Burst", restoredTransactions.get(0).actionLabel().value);

        Semantics.Result before = SemanticProbe.capture(
            restoredTransactions, null, session.id(), null);
        Semantics.Group burst = groupNamed(before.groups, "Ice Burst");
        assertNotNull(burst);
        assertEquals(2, burst.count);
        String stableGroupId = burst.id;
        assertTrue("search terms survive restore", burst.terms.contains("Ice Burst"));

        session.addTransaction(cast("Ice Burst", now + 6_000L), 100, false);
        Semantics.Result after = SemanticProbe.capture(
            session.transactions(), null, session.id(), null);
        Semantics.Group merged = groupNamed(after.groups, "Ice Burst");
        assertNotNull(merged);
        assertEquals("a later exact cast merges into the restored group", 3, merged.count);
        assertEquals("semantic identity stays stable for search and deep links",
            stableGroupId, merged.id);
        assertNotNull("Smoke Barrage stays separate",
            groupNamed(after.groups, "Smoke Barrage"));
        Semantics.Group generic = groupNamed(after.groups, "Cast");
        assertNotNull("the old generic Cast stays generic", generic);
        assertNotEquals(merged.id, generic.id);
    }

    @Test
    public void repositoryRoundTripAndBackupRotationPreserveTheLabel() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        Session session = new Session("General", 1_000L, SessionMode.GENERAL);
        Transaction labelled = cast("Ice Burst", 2_000L);
        session.addTransaction(labelled, 100, false);
        SavedState state = new SavedState(session, null, Collections.emptyList());
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        PersistenceProbe.save(repository, state);
        // Ordinary next save rotates the previous labelled generation into the backup file.
        session.addTransaction(cast("Smoke Barrage", 3_000L), 100, false);
        PersistenceProbe.save(repository, new SavedState(session, null, Collections.emptyList()));

        SavedState reloaded = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false).load();
        assertEquals(110, reloaded.schemaVersion);
        Transaction restored = FixtureReads.currentSession(reloaded).transactions().get(0);
        assertEquals(labelled.id(), restored.id());
        assertEquals(labelled.flows().size(), restored.flows().size());
        assertEquals(labelled.net(), restored.net());
        assertEquals("Ice Burst", restored.actionLabel().value);
        assertTrue("backup rotation does not strip the field",
            Files.readString(directory.resolve("sessions.backup.json")).contains("Ice Burst"));
    }

    @Test
    public void compactionDoesNotArchiveOrInferActionNames()
    {
        long old = T0 - 400L * 24L * 60L * 60L * 1_000L;
        Engine engine = engine();
        engine.startCustom("Old Grind", old);
        engine.session().addTransaction(cast("Ice Burst", old + 1_000L), 100, false);
        String sessionId = engine.session().id();
        engine.finishCustom(old + 2_000L);
        FixtureReads.compactOlderThan(engine, 1, T0);

        Session compacted = engine.historySession(sessionId);
        assertNotNull(compacted);
        assertTrue("the receipt detail is compacted away",
            compacted.transactions().isEmpty());
        assertTrue(compacted.compactedTransactionCount > 0);
        String json = new Gson().toJson(engine.savedState());
        assertFalse("a compacted receipt takes its action name with it",
            json.contains("Ice Burst"));
        assertFalse("no sidecar action-label archive exists",
            json.contains("actionLabelHistory"));
    }

    // ── fixtures ───────────────────────────────────────────────────────────────────────────────

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig()
            {
                @Override
                public Retention receiptRetentionDays()
                {
                    return Retention.DAYS_365;
                }
            });
    }

    private static SavedState stateWith(Transaction transaction)
    {
        Session session = new Session("General", 1_000L, SessionMode.GENERAL);
        session.addTransaction(transaction, 100, false);
        return new SavedState(session, null, Collections.emptyList());
    }

    /** Serialize, inject one raw wire value and reload; every read revalidates the label. */
    private static Transaction normalizedWire(String rawJsonValue, boolean nonCast)
    {
        Transaction source = nonCast ? eat("Ice Burst") : cast("Ice Burst", 2_000L);
        String json = new Gson().toJson(stateWith(source))
            .replace("\"observedActionLabel\":\"Ice Burst\"", "\"observedActionLabel\":" + rawJsonValue);
        SavedState loaded = new Gson().fromJson(json, SavedState.class);
        return FixtureReads.currentSession(loaded).transactions().get(0);
    }

    private static Transaction cast(String label, long at)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                new Flow(560, "Death rune", -2L, 188, -376L, PriceSource.GRAND_EXCHANGE),
                new Flow(562, "Chaos rune", -4L, 106, -424L, PriceSource.GRAND_EXCHANGE),
                new Flow(555, "Water rune", -4L, 5, -20L, PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setAction(ActionKind.CAST);
        if (label != null)
        {
            transaction.setActionLabel(ActionLabel.of(label));
        }
        return transaction;
    }

    /** A Cast whose runes no spell pays (a Nature rune too), so it stays generic, never Ice Burst. */
    private static Transaction genericCast(long at)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                new Flow(560, "Death rune", -2L, 188, -376L, PriceSource.GRAND_EXCHANGE),
                new Flow(561, "Nature rune", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setAction(ActionKind.CAST);
        return transaction;
    }

    private static Transaction eat(String label)
    {
        Transaction transaction = new Transaction(T0 + 100L,
            TransactionType.CONSUMPTION, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(385, "Shark", -1L, 950, -950L,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "Food", null);
        transaction.setAction(ActionKind.EAT);
        if (label != null)
        {
            transaction.setActionLabel(ActionLabel.of(label));
        }
        return transaction;
    }

    private static Transaction trade()
    {
        Transaction transaction = new Transaction(T0 + 100L, TransactionType.TRADE,
            Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(561, "Nature rune", -10L, 100, -1_000L,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "GE sale", null);
        return transaction;
    }

    private static String fingerprint(Transaction transaction)
    {
        return transaction.net() + "|" + transaction.revenue() + "|" + transaction.costs()
            + "|" + transaction.counts() + "|" + transaction.type() + "|"
            + transaction.context() + "|" + transaction.correction() + "|"
            + transaction.action() + "|"
            + new Gson().toJson(transaction.flows());
    }

    private static String repeat(String text, int times)
    {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < times; i++)
        {
            out.append(text);
        }
        return out.toString();
    }

    private static Semantics.Group groupNamed(
        List<Semantics.Group> groups, String name)
    {
        for (Semantics.Group group : groups)
        {
            if (name.equals(group.name))
            {
                return group;
            }
        }
        return null;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-13 gap pass: a farming-contract seed pack and the Bounty Hunter supply crate are
 * claims like the herb box — worth nothing until taken from, and each Take counts its contents
 * without Review.
 */
public class SeedPackTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(id == ItemID.SEEDBOX
            ? new Flow(id, "Seed pack", quantity, 0, 0L, PriceSource.DEFERRED_CLAIM, 0L)
            : new Flow(id, "Ranarr seed", quantity, 25_000, quantity * 25_000)));
        return flows;
    };

    @Test
    public void thePackIsAClaimUntilTakenFrom()
    {
        assertTrue(ActionReader.isClaim("Seed pack"));
        assertTrue("the Bounty supply crate is the same shape",
            ActionReader.isClaim("Bounty supply crate (anglerfish)"));
    }

    @Test
    public void everyTakeCountsItsSeedsWithoutReview()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(1L, 0L));
        assertEquals(TransactionType.GAIN, settle(engine, snapshot(1L, 1L), 1_600L).type());
        assertEquals("the last seed empties the pack", TransactionType.GAIN,
            settle(engine, snapshot(0L, 2L), 6_000L).type());
        assertEquals(50_000L, engine.metrics(20_000L).net);
        assertEquals(0, engine.getReviewRows(20_000L).size());
    }

    private static ContainerSnapshot snapshot(long packs, long seeds)
    {
        Map<Integer, Long> held = new HashMap<>();
        if (packs > 0) held.put(ItemID.SEEDBOX, packs);
        if (seeds > 0) held.put(ItemID.RANARR_SEED, seeds);
        return new ContainerSnapshot(held);
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        Transaction row = null;
        for (long t = firstTick; row == null && t < firstTick + 4_000L; t += 600L)
            row = engine.processIfDirty(snapshot, t, null);
        return row;
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * GP Per Hour 1.22 parity (2026-11-01): a seedling is untradeable and worth nothing, so sowing a
 * seed went to Review and a sapling grown in the bank never came back. A seedling now reads as the
 * sapling it grows into (item_states.tsv), and the sow click arms Farming because sowing gives no
 * XP (Wiki "Seedling", "Rosewood seedling").
 */
public class SeedlingSaplingTest {
    static final int SEED = ItemID.ROSEWOOD_SEED, POT = ItemID.PLANTPOT_COMPOST, TROWEL = ItemID.GARDENING_TROWEL,
        SEEDLING = ItemID.PLANTPOT_ROSEWOOD_SEED, WATERED = ItemID.PLANTPOT_ROSEWOOD_SEED_WATERED,
        SAPLING = ItemID.PLANTPOT_ROSEWOOD_SAPLING, CAN_8 = ItemID.WATERING_CAN_8, CAN_7 = ItemID.WATERING_CAN_7;
    static final long T0 = ReviewFixesTest.T0;
    static final Map<Integer, String> NAMES = Map.of(SEED, "Rosewood seed", POT, "Filled plant pot",
        TROWEL, "Gardening trowel", SAPLING, "Rosewood sapling", CAN_8, "Watering can(8)", CAN_7, "Watering can(7)");
    static final Map<Integer, Long> PRICES = Map.of(SEED, 135_000L, POT, 40L, SAPLING, 140_000L, CAN_8, 8L, CAN_7, 7L);

    static class Fixture {
        final Map<Integer, Long> pack = new HashMap<>();
        int tick = 100;
        Widget selected;
        final Engine engine;
        final GpManagerPluginProbe plugin = new GpManagerPluginProbe();
        final ItemContainer inventory = LootingBagMovementTest.proxy(ItemContainer.class, (method, args) -> {
            if (method.equals("contains")) return pack.containsKey((int) args[0]);
            if (method.equals("getItems")) {
                List<Item> items = new ArrayList<>();
                pack.forEach((id, q) -> items.add(new Item(id, q.intValue())));
                return items.toArray(new Item[0]);
            }
            return null;
        });

        Fixture(Map<Integer, Long> held) {
            JsonCodec.bind(new Gson());
            engine = new Engine(deltas -> {
                List<Flow> result = new ArrayList<>();
                deltas.forEach((id, q) -> {
                    long unit = PRICES.getOrDefault(id, 0L);
                    result.add(new Flow(id, NAMES.getOrDefault(id, "Item " + id), q, unit, q * unit));
                });
                return result;
            }, new TransactionClassifier(), ReviewFixesTest.CONFIG);
            engine.ensureSession(T0);
            pack.putAll(held);
            plugin.client = LootingBagMovementTest.proxy(Client.class, (method, args) -> {
                if (method.equals("getItemContainer")) return (int) args[0] == InventoryID.INV ? inventory : null;
                if (method.equals("getTickCount")) return tick;
                if (method.equals("getSelectedWidget")) return selected;
                if (method.equals("getGameState")) return GameState.LOGGED_IN;
                return null;
            });
            plugin.engine = engine;
            plugin.config = ReviewFixesTest.CONFIG;
            plugin.containers = new ContainerSnapshotFactory(plugin.client, null);
            plugin.targets = GpManagerPluginProbe.tracker(plugin.client, engine, plugin.config);
            plugin.charges = new ChargeIntake(plugin.client, null, plugin.config, engine, null);
            plugin.activity = new ActivityDetector(plugin.config, engine);
            plugin.idle = new CharacterIdleTracker(null, new CharacterIdleModel());
            engine.setBaseline(capture());
        }

        ContainerSnapshot capture() {
            return plugin.containers.capture(false, false);
        }

        /** Use one inventory item on another, as the game sends it. */
        void use(int item, String itemName, int on, String onName) {
            selected = LootingBagMovementTest.widget(item, 149 << 16);
            plugin.onMenuOptionClicked(LootingBagMovementTest.menu("Use", MenuAction.WIDGET_TARGET_ON_WIDGET,
                LootingBagMovementTest.widget(on, 149 << 16),
                "<col=ff9040>" + itemName + "<col=ffffff> -> <col=ff9040>" + onName));
        }

        void become(Map<Integer, Long> held) {
            pack.clear();
            pack.putAll(held);
            plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventory));
            engine.markDirty();
            engine.processIfDirty(capture(), T0 + 600L * (++tick), null);
            engine.processIfDirty(capture(), T0 + 600L * (++tick), null);
        }

        List<Transaction> rows() {
            return engine.session().transactions();
        }
    }

    @Test
    public void sowingInEitherUseOrderIsMadeNotReview() {
        for (boolean potFirst : new boolean[] {false, true}) {
            Fixture f = new Fixture(Map.of(SEED, 2L, POT, 2L, TROWEL, 1L));
            if (potFirst) f.use(POT, "Filled plant pot", SEED, "Rosewood seed");
            else f.use(SEED, "Rosewood seed", POT, "Filled plant pot");
            f.become(Map.of(SEED, 1L, POT, 1L, TROWEL, 1L, SEEDLING, 1L));

            assertEquals(f.rows().toString(), 1, f.rows().size());
            Transaction sown = f.rows().get(0);
            assertEquals(TransactionType.PROCESSING, sown.type());
            assertTrue(sown.counts());
            assertEquals("Sowing", sown.note());
            assertEquals("the HUD+ tray never says Harvested", "Sowed", HudTray.labelFor(sown.note()));
            assertEquals("the seedling is its sapling", 1L, sown.quantity(SAPLING, true));
            assertEquals(1L, sown.quantity(SEED, false));
            assertEquals(1L, sown.quantity(POT, false));
            assertEquals("no Review", 0, f.engine.getReviewRows(T0 + 100_000L).size());
            assertEquals(140_000L - 135_000L - 40L, f.engine.metrics(T0 + 100_000L).net);
        }
    }

    @Test
    public void wateringAndGrowingBookOnlyTheCan() {
        Fixture f = new Fixture(Map.of(SEEDLING, 1L, CAN_8, 1L));
        f.use(CAN_8, "Watering can(8)", SEEDLING, "Rosewood seedling");
        f.become(Map.of(WATERED, 1L, CAN_7, 1L));
        assertEquals(f.rows().toString(), 1, f.rows().size());
        Transaction watered = f.rows().get(0);
        assertEquals(0L, watered.quantity(SAPLING, true));
        assertEquals(0L, watered.quantity(SAPLING, false));
        assertEquals(1L, watered.quantity(CAN_8, false));

        f.become(Map.of(SAPLING, 1L, CAN_7, 1L));
        assertEquals("growing into the sapling books nothing", 1, f.rows().size());
        assertEquals(0, f.engine.getReviewRows(T0 + 100_000L).size());
    }

    @Test
    public void withoutTheSowClickTheSwapStaysReview() {
        Fixture f = new Fixture(Map.of(SEED, 2L, POT, 2L, TROWEL, 1L));
        f.become(Map.of(SEED, 1L, POT, 1L, TROWEL, 1L, SEEDLING, 1L));
        assertEquals(f.rows().toString(), 1, f.rows().size());
        assertEquals(TransactionType.UNCERTAIN, f.rows().get(0).type());
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SessionHistoryEngineTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int maxHistorySessions()
        {
            return 100;
        }
    };

    @Test
    public void restoredActiveSessionWaitsPausedForRecovery()
    {
        Session interrupted = session("Interrupted", Context.LOOT, TransactionType.LOOT, 100L);
        Engine engine = engine();
        engine.restore(new SavedState(interrupted, null, Collections.emptyList()), SafeMath.now());

        assertNotNull(engine.session());
        assertEquals(PauseReason.RECOVERY, engine.session().pauseReason());
    }

    @Test
    public void editsAndDeletesHistory()
    {
        Session pvm = session("Bossing", Context.LOOT, TransactionType.LOOT, 1_000L);
        pvm.close(3_600_000L);
        Session skilling = session("Fletching", Context.PRODUCTION, TransactionType.PROCESSING, 500L);
        skilling.close(3_600_000L);
        Session trading = session("Flipping", Context.MARKET, TransactionType.TRADE, -200L);
        trading.close(3_600_000L);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Arrays.asList(pvm, skilling, trading)), 3_600_000L);

        engine.historySession(pvm.id()).rename("Vorkath");
        assertEquals("Vorkath", engine.historySession(pvm.id()).name());

        assertTrue(engine.deleteHistory(skilling.id()));
        assertNull(engine.historySession(skilling.id()));
        assertEquals(2, engine.history().size());
    }

    @Test
    public void historicalCorrectionRecalculatesSummaryImmediately()
    {
        Session session = session("Review", Context.GENERIC, TransactionType.CONSUMPTION, -300L);
        session.close(60_000L);
        Transaction transaction = session.transactions().get(0);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Collections.singletonList(session)), 60_000L);
        Metrics before = engine.historyMetrics(session.id(), 60_000L);
        assertEquals(-300L, before.net);

        assertTrue(engine.historySession(session.id()).correctTransaction(
            transaction.id(), Correction.REVENUE, "Manual correction"));
        Metrics after = engine.historyMetrics(session.id(), 70_000L);
        assertEquals(300L, after.net);
    }

    @Test
    public void historySummaryCarriesStripMetadataWithoutLeakingSession()
    {
        Session session = session("Vorkath", Context.LOOT, TransactionType.LOOT, 1_000L);
        session.grind = true;
        session.close(60_000L);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Collections.singletonList(session)), 60_000L);

        Session retained = engine.historySession(session.id());
        assertTrue(retained.grind);
        assertFalse(retained.mode() == SessionMode.AUTO);
    }

    @Test
    public void historyIsNewestFirst()
    {
        long day = 24L * 60L * 60L * 1000L;
        long now = 100L * day;
        Session pvm = sessionAt("Vorkath", now - day, Context.LOOT, TransactionType.LOOT, 1_000L);
        Session skilling = sessionAt("Fletching", now - 10L * day, Context.PRODUCTION, TransactionType.PROCESSING, 500L);
        Session trading = sessionAt("Flipping", now - 40L * day, Context.MARKET, TransactionType.TRADE, -200L);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Arrays.asList(pvm, skilling, trading)), now);

        assertEquals("Vorkath", engine.history().get(0).name());
        assertEquals(3, engine.history().size());

    }

    private static Engine engine()
    {
        return new Engine(
            deltas -> Collections.emptyList(),
            new TransactionClassifier(),
            CONFIG);
    }

    private static Session sessionAt(
        String name, long start, Context context, TransactionType type, long value)
    {
        Session session = new Session(name, start, SessionMode.GENERAL);
        long quantity = value < 0L ? -1L : 1L;
        session.addTransaction(Tx.of(
            start + 1_000L, 1_000L, type, context, name, name, true,
            Collections.singletonList(new Flow(1, "Item", quantity, (int) Math.abs(value), value))), 100, false);
        session.close(start + 3_600_000L);
        return session;
    }

    private static Session session(
        String name,
        Context context,
        TransactionType type,
        long value)
    {
        Session session = new Session(name, 0L, SessionMode.GENERAL);
        long quantity = value < 0L ? -1L : 1L;
        long absolute = Math.abs(value);
        session.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                type,
                context,
                name,
                name,
                true,
                Collections.singletonList(new Flow(1, "Item", quantity, (int) absolute, value))),
            100, false);
        return session;
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class SessionOwnershipTest
{
    private Engine engine(int historyLimit)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 0; }
            @Override public int maxHistorySessions() { return historyLimit; }
            @Override public boolean keepTransferAuditRows() { return true; }
        };
        return new Engine(deltas ->
            Collections.singletonList(new Flow(995, "Coins", deltas.get(995), 1, deltas.get(995))),
            new TransactionClassifier(), config);
    }

    @Test
    public void customSessionSuspendsGeneralAndOwnsEachObservedTransaction()
    {
        Engine engine = engine(10);
        engine.ensureSession(0L);
        Session general = engine.freePlay();
        assertEquals("Overall", general.name());
        engine.setBaseline(snapshot(0L));

        engine.startCustom("Vorkath", 100L);
        Session custom = engine.session();
        assertNotEquals(general.id(), custom.id());
        assertTrue(general.paused);
        engine.setBaseline(snapshot(0L));
        engine.markDirty();
        engine.processIfDirty(snapshot(250L), 200L, null);
        Transaction transaction = engine.processIfDirty(snapshot(250L), 201L, null);

        assertEquals(250L, transaction.net());
        assertEquals(1, custom.transactions().size());
        assertEquals(0, general.transactions().size());
        assertTrue(engine.finishCustom(1_000L));
        assertEquals(general.id(), engine.session().id());
        assertFalse(general.paused);
        assertEquals(1, engine.history().size());
        assertEquals(custom.id(), engine.history().get(0).id());
        assertEquals(1_100L, engine.metrics(2_000L).elapsed);
    }

    @Test
    public void shutdownKeepsGeneralDurableAndRestoresItAsRecovery()
    {
        Engine engine = engine(10);
        engine.ensureSession(1_000L);
        String generalId = engine.freePlay().id();

        engine.pauseForLifecycle(2_000L);
        SavedState saved = engine.savedState();

        assertEquals(generalId, saved.generalSession.id());
        assertEquals(0, saved.history().size());
        Engine restored = engine(10);
        restored.restore(saved, SafeMath.now());
        assertEquals(generalId, restored.session().id());
        assertEquals(PauseReason.RECOVERY, restored.session().pauseReason());
    }

    @Test
    public void startCreatesARunningGeneralOwnerWhenAutoStartWasDisabled()
    {
        Engine engine = engine(10);

        engine.togglePause(1_000L);

        assertEquals("Overall", engine.session().name());
        assertEquals(engine.freePlay().id(), engine.session().id());
        assertFalse("Start begins tracking; it never creates a paused owner", engine.session().paused);
    }

    @Test
    public void customTransitionPreservesEveryGeneralPauseOwner()
    {
        for (PauseReason reason : new PauseReason[] {PauseReason.IDLE, PauseReason.MANUAL, PauseReason.RECOVERY})
        {
            Engine engine = engine(10);
            engine.ensureSession(1_000L);
            Session general = engine.freePlay();
            if (reason == PauseReason.IDLE) engine.session().pause(1_100L, PauseReason.IDLE);
            if (reason == PauseReason.MANUAL) engine.togglePause(1_100L);
            if (reason == PauseReason.RECOVERY) general.pause(1_100L, PauseReason.RECOVERY);
            engine.startCustom("Custom", 1_200L);
            engine.finishCustom(1_300L);
            assertEquals(reason, general.pauseReason());
            if (reason == PauseReason.IDLE || reason == PauseReason.RECOVERY)
            {
                engine.resume(1_400L, PauseReason.IDLE, PauseReason.RECOVERY);
                assertFalse(general.paused);
            }
            else
            {
                engine.resume(1_400L, PauseReason.IDLE, PauseReason.RECOVERY);
                assertTrue(general.paused);
            }
        }
    }

    @Test
    public void startingSecondCustomDoesNotArchiveTheFirst()
    {
        Engine engine = engine(10);
        engine.ensureSession(0L);
        engine.startCustom("First", 1L);
        String first = engine.session().id();
        engine.startCustom("Second", 2L);
        assertEquals(first, engine.session().id());
        assertEquals(0, engine.history().size());
    }

    @Test
    public void idleGeneralPauseOwnerSurvivesCustomPersistenceAndFinish()
    {
        Engine engine = engine(10);
        engine.ensureSession(1_000L);
        engine.session().pause(1_100L, PauseReason.IDLE);
        engine.startCustom("Raid", 1_200L);
        SavedState saved = new Gson().fromJson(new Gson().toJson(engine.savedState()), SavedState.class);

        Engine restored = engine(10);
        restored.restore(saved, SafeMath.now());
        restored.finishCustom(1_300L);

        assertEquals(PauseReason.IDLE, restored.freePlay().pauseReason());
        restored.resume(1_400L, PauseReason.IDLE, PauseReason.RECOVERY);
        assertFalse(restored.freePlay().paused);
    }

    @Test
    public void explicitOwnersSurviveRestartAndCustomRecoveryWithoutMerging()
    {
        Engine engine = engine(10);
        engine.ensureSession(1_000L);
        String generalId = engine.freePlay().id();
        engine.startCustom("Raid", 2_000L);
        String customId = engine.session().id();

        SavedState saved = new Gson().fromJson(new Gson().toJson(engine.savedState()), SavedState.class);
        Engine restored = engine(10);
        restored.restore(saved, SafeMath.now());

        assertEquals(generalId, restored.freePlay().id());
        assertEquals(customId, restored.session().id());
        assertTrue(restored.customActive());
        assertEquals(PauseReason.RECOVERY, restored.session().pauseReason());
        assertTrue(restored.freePlay().paused);
    }

    @Test
    public void pauseLogoutAndRetentionDoNotCreateASecondOwner()
    {
        Engine engine = engine(2);
        engine.ensureSession(1_000L);
        String generalId = engine.freePlay().id();
        engine.togglePause(2_000L);
        engine.pauseForLifecycle(3_000L);
        engine.resume(4_000L, PauseReason.LIFECYCLE);
        assertTrue(engine.session().paused);
        engine.resume(6_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        assertTrue("a manual pause waits for Resume", engine.session().paused);

        engine.startCustom("First", 7_000L);
        engine.finishCustom(8_000L);
        engine.startCustom("Second", 9_000L);
        engine.finishCustom(10_000L);
        engine.startCustom("Third", 11_000L);
        engine.finishCustom(12_000L);

        assertEquals(generalId, engine.freePlay().id());
        assertEquals(generalId, engine.session().id());
        assertEquals("all three finished trips stay owned beyond the old cap", 3, engine.history().size());
        assertEquals(PauseReason.MANUAL, engine.freePlay().pauseReason());
    }

    private static ContainerSnapshot snapshot(long coins)
    {
        return new ContainerSnapshot(Collections.singletonMap(995, coins));
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;

/** Fixed quotes isolate the shop evidence/matcher from the separate valuation policy. */
@RunWith(Parameterized.class)
public class ShopCurrencyMatcherTest {
    @Parameterized.Parameters(name = "{1}")
    public static Object[][] currencies() {
        return new Object[][] {
            {6529, "Tokkul"}, {25527, "Stardust"}, {21341, "Unidentified minerals"},
            {12012, "Golden nugget"}, {24711, "Hallowed mark"}, {4067, "Castle wars ticket"},
            {21656, "Mermaid's tear"}, {11849, "Mark of Grace"}, {28134, "Anima-infused bark"},
            {6306, "Trading sticks"}, {4278, "Ecto-token"}, {29480, "Agility arena ticket"},
            {29482, "Brimhaven voucher"}, {8951, "Pieces of eight"}, {30038, "Termites"},
            {1464, "Archery ticket"}, {26792, "Abyssal pearls"}, {25588, "Spirit flakes"},
            {22820, "Molch pearl"}
        };
    }

    @Parameterized.Parameter public int currency;
    @Parameterized.Parameter(1) public String name;
    private static final long NOW = 1_000_000L;
    private static final int REWARD = ItemID.LOGS;

    private Engine engine(boolean known) {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = new Engine(deltas -> {
            var flows = new ArrayList<Flow>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, id == currency ? name : "Logs", quantity,
                    id == currency ? 30 : 100, quantity * (id == currency ? 30 : 100),
                    id == currency && !known ? PriceSource.UNPRICED : PriceSource.GRAND_EXCHANGE)));
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig() {
            @Override public int stabilizationTicks() { return 0; }
        });
        engine.startCustom("Shop currency", NOW);
        engine.setBaseline(new ContainerSnapshot(Map.of(currency, 100L, REWARD, 10L)));
        return engine;
    }

    private Transaction change(Engine engine, boolean buy) {
        var next = new ContainerSnapshot(Map.of(currency, buy ? 90L : 110L, REWARD, buy ? 11L : 9L));
        engine.processIfDirty(next, NOW + 3000, null);
        engine.processIfDirty(next, NOW + 3600, null);
        var rows = engine.session().transactions();
        assertEquals(1, rows.size());
        return rows.get(0);
    }

    @Test public void dialoguePurchaseIsCountedWithTheCapturedCost() {
        var engine = engine(true);
        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        var row = change(engine, true);
        assertEquals(TransactionType.TRADE, row.type());
        assertEquals(Context.MARKET, row.context());
        assertTrue(row.counts());
        assertFalse(ReviewRules.needsReview(row));
        assertEquals(-200, engine.metrics(NOW + 4000).net);
        assertEquals(10, row.quantity(currency, false));
    }

    @Test public void dialogueSaleKeepsItsOppositeNet() {
        var engine = engine(true);
        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        var row = change(engine, false);
        assertEquals(TransactionType.TRADE, row.type());
        assertTrue(row.counts());
        assertFalse(ReviewRules.needsReview(row));
        assertEquals(200, engine.metrics(NOW + 4000).net);
    }

    @Test public void withoutShopOrDialogueTheSameChangeStaysReview() {
        var engine = engine(true);
        assertTrue(ReviewRules.needsReview(change(engine, true)));
        assertEquals(0, engine.metrics(NOW + 4000).net);
    }

    @Test public void anExecutedNonCoinShopClickReadsExchanged() {
        var engine = engine(true);
        engine.markContext(Context.MARKET, 4, "buy 1 Logs");
        var row = change(engine, true);
        assertTrue(row.counts());
        assertEquals("Exchanged", Semantics.verbOf(row));
        assertEquals(-200, engine.metrics(NOW + 4000).net);
    }

    @Test public void mixedCurrencyAndOtherGainsDoNotBecomeAShopSale() {
        var engine = engine(true);
        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        var next = new ContainerSnapshot(Map.of(currency, 110L, REWARD, 9L, ItemID.COINS, 50L));
        engine.processIfDirty(next, NOW + 3000, null);
        engine.processIfDirty(next, NOW + 3600, null);
        assertTrue(ReviewRules.needsReview(engine.session().transactions().get(0)));
        assertEquals(0, engine.metrics(NOW + 4000).net);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.4: a shop window turns coins-for-items into a counted "Bought" and items-for-coins
 * into a counted "Sold" instead of a mixed Review row; the trade branches still fail closed when
 * the shapes are not exact.
 */
public class ShopPurchaseTest
{
    static String tradedItems(Transaction row, Contribution part) {
        var parts = Semantics.tradeParts(row, part);
        return parts == null ? "" : parts[0]+" "+parts[1];
    }

    private static final int COINS = 995;
    private static final int JAR = 11260;
    private static final int PLATEBODY = 1127;
    private static final int TOKKUL = 6529;
    private static final int DEATH_RUNE = 560;
    private static final int BOOK = 9003; // Security book: untradeable, no market price
    private static final Map<Integer, String> NAMES = Map.of(COINS, "Coins", JAR, "Impling jar",
        PLATEBODY, "Rune platebody", TOKKUL, "Tokkul", DEATH_RUNE, "Death rune", BOOK, "Security book");
    private static final Map<Integer, Integer> PRICES = Map.of(COINS, 1, JAR, 290, PLATEBODY, 38_000, TOKKUL, 9);

    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 100_000L, PLATEBODY, 5L, TOKKUL, 100_000L));
    private final Engine engine = new Engine(deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) ->
        {
            int unit = PRICES.getOrDefault(id, 0);
            flows.add(new Flow(id, NAMES.getOrDefault(id, "Item " + id), quantity, unit,
                quantity * unit,
                id == COINS ? PriceSource.FACE_VALUE
                    : id == BOOK ? PriceSource.UNPRICED : PriceSource.GRAND_EXCHANGE));
        });
        return flows;
    }, new TransactionClassifier(), new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    });
    private long now = 1_000_000L;

    @Test
    public void buyingAnUntradeableIsAPurchaseNotReview()
    {
        // A shop/dialogue purchase of an item with no market (untradeable) spends coins that
        // can never be recovered: the purchase books the cost (Coinflow 1.7.1 calls this the
        // unrealizable case; owner probe 2026-10-13).
        start();
        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction bought = change(COINS, -2L, BOOK, 1L);
        assertSame(TransactionType.TRADE, bought.type());
        assertEquals("Bought", bought.note());
        assertTrue(bought.counts());
        assertFalse("not Review", ReviewRules.needsReview(bought));
        assertEquals(-2L, engine.metrics(now + 1_000L).net);
    }

    @Test
    public void coinsForAnItemWithAShopOpenIsAPurchase()
    {
        start();
        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction bought = change(COINS, -2_000L, JAR, 1L);
        assertSame(TransactionType.TRADE, bought.type());
        assertEquals("Bought", bought.note());
        assertTrue(bought.counts());
        assertFalse("not Review", ReviewRules.needsReview(bought));
    }

    @Test
    public void itemsForCoinsWithAShopOpenIsASale()
    {
        start();
        assertTrue("without the shop window it stays Review",
            ReviewRules.needsReview(change(PLATEBODY, -1L, COINS, 38_000L)));

        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction sold = change(PLATEBODY, -1L, COINS, 38_000L);
        assertSame(TransactionType.TRADE, sold.type());
        assertSame(Context.MARKET, sold.context());
        assertEquals("Sold", sold.note());
        assertTrue(sold.counts());
        assertFalse("not Review", ReviewRules.needsReview(sold));
    }

    @Test
    public void aShopTradeEntryNamesWhatItBoughtOrSold()
    {
        start();
        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        engine.markContext(Context.MARKET, 4, "buy 1 Impling jar");
        Transaction bought = change(COINS, -290L, JAR, 1L);
        assertSame(TransactionType.TRADE, bought.type());
        assertEquals("a coin shop keeps its own verb", "Traded", Semantics.verbOf(bought));
        assertEquals("Bought Impling jar",
            tradedItems(bought, contributionOf(bought, COINS)));
        assertEquals("Paid Coins ×290",
            tradedItems(bought, contributionOf(bought, JAR)));

        engine.markContext(Context.MARKET, 4, "buy 50 Death rune");
        Transaction exchanged = change(TOKKUL, -14_550L, DEATH_RUNE, 50L);
        assertSame(TransactionType.TRADE, exchanged.type());
        assertEquals("a non-coin currency shop reads Exchanged", "Exchanged",
            Semantics.verbOf(exchanged));
        assertEquals("Bought Death rune ×50",
            tradedItems(exchanged, contributionOf(exchanged, TOKKUL)));
        assertEquals("Paid Tokkul ×14,550",
            tradedItems(exchanged, contributionOf(exchanged, DEATH_RUNE)));

        engine.markContext(Context.MARKET, 4, "sell 1 Rune platebody");
        Transaction sold = change(PLATEBODY, -1L, COINS, 380L);
        assertSame(TransactionType.TRADE, sold.type());
        assertEquals("Traded", Semantics.verbOf(sold));
        assertEquals("Sold Rune platebody",
            tradedItems(sold, contributionOf(sold, COINS)));
        assertEquals("Sold for Coins ×380",
            tradedItems(sold, contributionOf(sold, PLATEBODY)));
    }

    @Test
    public void aTokkulSaleThroughItsSellClickIsAnExchangedTrade()
    {
        start();
        // The sell click arms the shop's MARKET context; outside it the same change fails closed.
        assertTrue("without the click context it stays Review",
            ReviewRules.needsReview(change(PLATEBODY, -1L, TOKKUL, 380L)));

        engine.markContext(Context.MARKET, 4, "sell 1 Rune platebody");
        Transaction sold = change(PLATEBODY, -1L, TOKKUL, 380L);
        assertSame(TransactionType.TRADE, sold.type());
        assertSame(Context.MARKET, sold.context());
        assertEquals("a non-coin currency shop reads Exchanged", "Exchanged", Semantics.verbOf(sold));
        assertTrue(sold.counts());
        assertFalse("not Review", ReviewRules.needsReview(sold));
    }

    private static Contribution contributionOf(Transaction transaction, int itemId)
    {
        for (Contribution contribution : Contribution.project(transaction))
            if (contribution.item == itemId) return contribution;
        throw new AssertionError("no contribution for item " + itemId);
    }

    @Test
    public void aMixedCoinAndItemGainIsNotASale()
    {
        start();
        engine.events.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction mixed = change(PLATEBODY, -1L, COINS, 1_000L, JAR, 1L);
        assertTrue("coins plus another item is not a sale",
            ReviewRules.needsReview(mixed));
    }

    @Test
    public void aVisibleShopWindowIsShopEvidence()
    {
        assertTrue("InterfaceID.Shopmain.FRAME",
            Widgets.isShopOpen(clientWith(0x012c_0001)));
        assertTrue("InterfaceID.OmnishopMain.FRAME",
            Widgets.isShopOpen(clientWith(0x0333_0007)));
        assertFalse("a quantity button is not the shop window",
            Widgets.isShopOpen(clientWith(0x012c_0008)));
        assertFalse(Widgets.isShopOpen(clientWith(0)));
    }

    private static Client clientWith(int componentId)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[] {Client.class}, (proxy, method, args) ->
            {
                if ("getWidget".equals(method.getName()))
                    return componentId > 0 && (int) args[0] == componentId ? visibleWidget() : null;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                return null;
            });
    }

    private static Widget visibleWidget()
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
            new Class<?>[] {Widget.class}, (proxy, method, args) ->
            {
                if ("isHidden".equals(method.getName())) return false;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                return null;
            });
    }

    private void start()
    {
        engine.startCustom("Shops", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
    }

    private Transaction change(Object... idsAndDeltas)
    {
        for (int index = 0; index < idsAndDeltas.length; index += 2)
        {
            inventory.merge((Integer) idsAndDeltas[index], (Long) idsAndDeltas[index + 1],
                Long::sum);
        }
        inventory.values().removeIf(quantity -> quantity == 0L);
        int before = engine.session().transactions().size();
        now += 3_000L;
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now, null);
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now + 600L, null);
        List<Transaction> all = engine.session().transactions();
        return all.size() > before ? all.get(all.size() - 1) : null;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;

/** Owner report 2026-09-28: ore used up by a failed iron smelt is a supply, not a loss. */
public class SmeltingSupplyTest
{
    private static final int IRON_ORE = 440;
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void aFailedSmeltInsideTheRunIsASupplyAndNeverReview()
    {
        Engine engine = engine();
        engine.startCustom("Smithing", T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(IRON_ORE, 7L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(held)));

        // The furnace's Smelt click (or a failed-smelt message) keeps the run in PRODUCTION.
        engine.markContext(Context.PRODUCTION, 6, "Smelting");
        held.put(IRON_ORE, 6L);
        Transaction failed = settle(engine, held, T0 + 600L);

        assertNotNull(failed);
        assertFalse("a failed smelt is not a Review decision", ReviewRules.needsReview(failed));
        assertEquals("the ore it used is a supply", CostKind.SUPPLIES, CostKind.of(failed, failed.flows().get(0)));
        assertEquals("the run's first receipt names its skill before any XP", "Smithing", failed.activityName());
    }

    @Test
    public void takingOffWornEquipmentStartsNoProductionRun()
    {
        // "Remove" is the worn-equipment option; removing furniture returns nothing to book.
        assertEquals("", ActionSignals.transformSkill("Remove"));
        assertEquals("Construction", ActionSignals.transformSkill("Build"));
    }

    @Test
    public void anOreGoneWithoutAnyRunStaysALoss()
    {
        Engine engine = engine();
        engine.startCustom("Smithing", T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(IRON_ORE, 7L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(held)));

        held.put(IRON_ORE, 6L);
        Transaction gone = settle(engine, held, T0 + 600L);
        assertNotNull(gone);
        assertEquals(CostKind.LOSS, CostKind.of(gone, gone.flows().get(0)));
    }

    private static Transaction settle(Engine engine, Map<Integer, Long> held, long now)
    {
        engine.markDirty();
        Transaction result = null;
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(held)), now + i * 600L, null);
            if (settled != null)
            {
                result = settled;
            }
        }
        return result;
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                flows.add(new Flow(delta.getKey(), "Iron ore", delta.getValue(), 71, delta.getValue() * 71L,
                    PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import static org.junit.Assert.assertFalse;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner live 2026-10-16: High Level Alchemy and a broken Bones to peaches tablet booked as plain
 * changes, not spells, and a Progress hat or a peach (untradeable, no alch value) showed "?".
 */
public class SpellShapesTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final int NATURE = 561, STEAM = 4694, PLATESKIRT = 1093, COINS = 995;
    private static final int TABLET = 8015, BONES = 526, PEACH = 6883, HAT = 6885, DART = 811, SHARD = 23962;
    private static final Map<Integer, String> NAMES = Map.of(NATURE, "Nature rune", STEAM, "Steam rune",
        PLATESKIRT, "Rune plateskirt", COINS, "Coins", TABLET, "Bones to peaches", BONES, "Bones",
        PEACH, "Peach", HAT, "Progress hat", DART, "Rune dart", SHARD, "Crystal shard");

    @Test
    public void highAlchemyBooksAsItsSpellWithTheCoinsItMade()
    {
        Transaction alch = settle(Map.of(NATURE, 10L, STEAM, 50L, PLATESKIRT, 1L, COINS, 0L),
            Map.of(NATURE, 9L, STEAM, 45L, PLATESKIRT, 0L, COINS, 38_400L),
            PLATESKIRT, ActionKind.CAST, ActionLabel.of("High Level Alchemy"));
        assertSame(ActionKind.CAST, alch.action());
        assertEquals("High Level Alchemy", alch.spellName());
        assertEquals("the coins stay on the cast", 4, alch.flows().size());
    }

    @Test
    public void aBrokenTabletBooksAsTheSpellItHolds()
    {
        assertEquals("the tablet's name spells its spell", "Bones to Peaches", Spells.named("bones to peaches"));
        assertSame("Break is a cast", ActionKind.CAST, ActionReader.verbOf("break"));
        Transaction tablet = settle(Map.of(TABLET, 5L, BONES, 3L, PEACH, 0L),
            Map.of(TABLET, 4L, BONES, 0L, PEACH, 3L),
            TABLET, ActionReader.verbOf("break"), ActionLabel.of(Spells.named("bones to peaches")));
        assertSame(ActionKind.CAST, tablet.action());
        assertEquals("Bones to Peaches", tablet.spellName());
    }

    /** Owner live 2026-10-16: an Eat clicked two ticks after a Break left the tablet in Review. */
    @Test
    public void aFastSecondClickNeverTakesTheFirstSpendsEvidence()
    {
        Engine engine = engine();
        engine.startCustom("Magic", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(TABLET, 5L, BONES, 3L, PEACH, 1L))));
        engine.noteConsume(TABLET, 10, false, ActionReader.verbOf("break"), ActionLabel.of(Spells.named("bones to peaches")));
        Map<Integer, Long> broken = Map.of(TABLET, 4L, BONES, 0L, PEACH, 4L);
        engine.markDirty();
        List<Transaction> booked = new ArrayList<>();
        Transaction first = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(broken)), T0 + 600L, booked::add);
        assertNull("the break is still settling when the Eat is clicked", first);
        engine.noteConsume(PEACH, 10, false, ActionKind.EAT, null);
        for (int i = 1; i < 4; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(broken)), T0 + 600L + i * 600L, booked::add);
            if (settled != null) booked.add(settled);
        }
        Transaction tablet = booked.stream().filter(t -> t.flows().stream().anyMatch(f -> f.item == TABLET))
            .findFirst().orElse(null);
        assertNotNull("the break booked: " + booked, tablet);
        assertSame("the break is still its spell", ActionKind.CAST, tablet.action());
        assertEquals("Bones to Peaches", tablet.spellName());

        Map<Integer, Long> eaten = Map.of(TABLET, 4L, BONES, 0L, PEACH, 3L);
        engine.markDirty();
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(eaten)), T0 + 4_000L + i * 600L, booked::add);
            if (settled != null) booked.add(settled);
        }
        Transaction bite = booked.stream().filter(t -> t.flows().size() == 1 && t.flows().get(0).item == PEACH)
            .findFirst().orElse(null);
        assertNotNull("the bite books on its own: " + booked, bite);
        assertSame("and keeps its own verb", ActionKind.EAT, bite.action());
    }

    /** Owner live 2026-10-16: a spell with a product is one row named by its spell, at its net. */
    @Test
    public void aSpellWithAProductIsOneRow()
    {
        settle(Map.of(TABLET, 5L, BONES, 3L, PEACH, 0L), Map.of(TABLET, 4L, BONES, 0L, PEACH, 3L),
            TABLET, ActionReader.verbOf("break"), ActionLabel.of(Spells.named("bones to peaches")));
        List<LiveSnapshot.Recent> rows = LiveSnapshot.capture(last, T0 + 5_000L, null).recent;
        assertEquals("one row: " + rows.stream().map(r -> r.name).collect(java.util.stream.Collectors.toList()), 1, rows.size());
        assertEquals("Bones to Peaches", rows.get(0).name);
        assertEquals("the tablet and bones it took, the fruit worth nothing", -400L, rows.get(0).value);

        settle(Map.of(NATURE, 10L, STEAM, 50L, PLATESKIRT, 1L, COINS, 0L),
            Map.of(NATURE, 9L, STEAM, 45L, PLATESKIRT, 0L, COINS, 38_400L),
            PLATESKIRT, ActionKind.CAST, ActionLabel.of("High Level Alchemy"));
        rows = LiveSnapshot.capture(last, T0 + 5_000L, null).recent;
        assertEquals(1, rows.size());
        assertEquals("High Level Alchemy", rows.get(0).name);
        assertEquals("coins less the item and runes", 38_400L - 37_000L - 600L, rows.get(0).value);
    }

    /** Ongoing repricing survives retirement of historical spell relabeling. */
    @Test
    public void oldUnpricedRowsRecoverWithoutHistoricalSpellRelabeling()
    {
        Engine engine = engine();
        engine.startCustom("Magic", T0);
        Session session = engine.session();
        Transaction ate = old(TransactionType.CONSUMPTION, Confidence.LIKELY, true, "",
            new Flow(PEACH, "Peach", -1L, 0, 0L, PriceSource.UNPRICED));
        Transaction shards = old(TransactionType.GAIN, Confidence.LIKELY, true, "",
            new Flow(SHARD, "Crystal shard", 3L, 0, 0L, PriceSource.UNPRICED));
        Transaction review = old(TransactionType.UNCERTAIN, Confidence.UNCERTAIN, false, "",
            new Flow(TABLET, "Bones to peaches", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE),
            new Flow(BONES, "Bones", -3L, 100, -300L, PriceSource.GRAND_EXCHANGE),
            new Flow(PEACH, "Peach", 3L, 0, 0L, PriceSource.UNPRICED));
        Transaction high = alch(38_400L);
        Transaction low = alch(25_600L);
        Transaction dropped = old(TransactionType.CONSUMPTION, Confidence.LIKELY, true, "Dropped Bones to peaches",
            new Flow(TABLET, "Bones to peaches", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE));
        Transaction decided = old(TransactionType.CONSUMPTION, Confidence.LIKELY, true, "",
            new Flow(TABLET, "Bones to peaches", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE));
        decided.applyCorrection(Correction.IGNORE, "Manual correction");
        for (Transaction row : List.of(ate, shards, review, high, low, dropped, decided)) session.addTransaction(row, 2_000, false);

        engine.recheck();

        assertSame("an old peach reads as worth nothing", PriceSource.NO_VALUE, ate.flows().get(0).source());
        assertSame("an old untradeable takes its alch value", PriceSource.HIGH_ALCHEMY, shards.flows().get(0).source());
        assertEquals("and the row's total follows", 18_000L, shards.autoNet());
        assertNull(review.action());
        assertEquals("", review.spellName());
        assertSame("retired repair cannot reclassify history", TransactionType.UNCERTAIN, review.type());
        assertFalse(review.counts());
        assertTrue(ReviewRules.needsReview(review));
        assertEquals("", high.spellName());
        assertEquals("", low.spellName());
        assertNull("a dropped tablet is no cast", dropped.action());
        assertNull("an owner decision is never rewritten", decided.action());

        long revision = engine.revision();
        engine.recheck();
        assertEquals("a second pass changes nothing", revision, engine.revision());
    }

    private static Transaction alch(long coins)
    {
        return old(TransactionType.CONSUMPTION, Confidence.LIKELY, true, "",
            new Flow(NATURE, "Nature rune", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE),
            new Flow(STEAM, "Steam rune", -5L, 100, -500L, PriceSource.GRAND_EXCHANGE),
            new Flow(PLATESKIRT, "Rune plateskirt", -1L, 37_000, -37_000L, PriceSource.GRAND_EXCHANGE),
            new Flow(COINS, "Coins", coins, 1, coins, PriceSource.FACE_VALUE));
    }

    private static Transaction old(TransactionType type, Confidence confidence, boolean counted, String note, Flow... flows)
    {
        return new Transaction(T0, type, Context.GENERIC, note, "Magic", counted, List.of(flows), confidence, "old", null);
    }

    /** Owner live 2026-10-16: 39 rune darts picked up with a tablet break rode the spell's row. */
    @Test
    public void aPickupWithASpellBooksOnItsOwn()
    {
        Engine engine = engine();
        engine.startCustom("Magic", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(TABLET, 5L, BONES, 3L, PEACH, 0L, DART, 0L))));
        engine.noteConsume(TABLET, 10, false, ActionReader.verbOf("break"), ActionLabel.of(Spells.named("bones to peaches")));
        engine.markDirty();
        List<Transaction> booked = new ArrayList<>();
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(
                Map.of(TABLET, 4L, BONES, 0L, PEACH, 3L, DART, 39L))), T0 + 600L + i * 600L, booked::add);
            if (settled != null) booked.add(settled);
        }
        Transaction spell = booked.stream().filter(t -> t.action() == ActionKind.CAST).findFirst().orElse(null);
        assertNotNull("the break books as its spell: " + booked, spell);
        assertTrue("without the darts", spell.flows().stream().noneMatch(f -> f.item == DART));
        assertTrue("the darts book as their own gain", booked.stream().anyMatch(t -> t != spell
            && t.flows().size() == 1 && t.flows().get(0).item == DART && t.action() == null));

        // A row already booked with both (a dev build only) stays as item rows, darts apart.
        Transaction old = old(TransactionType.CONSUMPTION, Confidence.LIKELY, true, "",
            new Flow(TABLET, "Bones to peaches", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE),
            new Flow(BONES, "Bones", -3L, 100, -300L, PriceSource.GRAND_EXCHANGE),
            new Flow(PEACH, "Peach", 3L, 0, 0L, PriceSource.NO_VALUE),
            new Flow(DART, "Rune dart", 39L, 100, 3_900L, PriceSource.GRAND_EXCHANGE));
        old.setAction(ActionKind.CAST);
        old.setActionLabel(ActionLabel.of("Bones to Peaches"));
        List<String> rows = new ArrayList<>();
        for (Semantics.Group group : Semantics.transactionUnits(old, f -> true)) rows.add(group.name + " " + group.value);
        assertTrue("a gain the spell does not make keeps the rows apart: " + rows,
            rows.contains("Rune dart 3900") && rows.size() == 4);
    }

