        // Ten attacks spend ten charges: one shard, twenty nature and twenty death runes.
        engine.markDirty();
        Transaction spend = settle(engine, capture(charged, Map.of(VarbitID.CHARGES_OBLIGATOR_QUANTITY, 110)),
            now + 20_000);
        assertNotNull(spend);
        assertEquals(TransactionType.CONSUMPTION, spend.type());
        assertEquals("spent, counted as a cost", 1L, spend.quantity(ItemID.ASCENSION_SHARDS, false));
        assertEquals(20L, spend.quantity(ItemID.NATURERUNE, false));
        assertEquals(20L, spend.quantity(ItemID.DEATHRUNE, false));
        assertEquals("41 items at the fixture's 100 gp", -4_100L, engine.metrics(now + 40_000).net);
    }

    @Test
    public void aCounterSharedByTwoCarriedItemsCountsOnceAndSpendsOnce()
    {
        Map<Integer, Item[]> both = Map.of(InventoryID.INV, items(ItemID.CELESTIAL_RING_CHARGED, 1,
            ItemID.CELESTIAL_SIGNET_CHARGED, 1));
        assertEquals("one pool of 900 stardust", 900L,
            capture(both, Map.of(VarbitID.CHARGES_CELESTIAL_RING_QUANTITY, 900)).quantity(ItemID.STAR_DUST));
        Engine engine = ReviewFixesTest.engine();
        long now = ReviewFixesTest.T0 + 1_000;
        engine.setBaseline(capture(both, Map.of(VarbitID.CHARGES_CELESTIAL_RING_QUANTITY, 900)));
        engine.markDirty();
        settle(engine, capture(both, Map.of(VarbitID.CHARGES_CELESTIAL_RING_QUANTITY, 899)), now);
        assertEquals("one charge, one stardust at the fixture's 100 gp", -100L, engine.metrics(now + 20_000).net);
        ContainerSnapshot two = capture(Map.of(InventoryID.INV, items(ItemID.PLANK_SACK, 1)),
            Map.of(VarbitID.PLANK_SACK_OAK, 4, VarbitID.PLANK_SACK_TEAK, 3));
        assertEquals("other stores keep their own counters", 4L, two.quantity(ItemID.PLANK_OAK));
        assertEquals(3L, two.quantity(ItemID.PLANK_TEAK));
    }

    private static Transaction settle(Engine engine, ContainerSnapshot next, long at)
    {
        Transaction booked = null;
        for (int tick = 0; tick < 8 && booked == null; tick++)
        {
            booked = engine.processIfDirty(next, at + tick * 600L, null);
        }
        return booked;
    }

    private static Item[] items(int... idQuantity)
    {
        Item[] items = new Item[idQuantity.length / 2];
        for (int i = 0; i < items.length; i++)
        {
            items[i] = new Item(idQuantity[2 * i], idQuantity[2 * i + 1]);
        }
        return items;
    }

    private static ContainerSnapshot capture(Map<Integer, Item[]> containers, Map<Integer, Integer> varbits)
    {
        Map<Integer, ItemContainer> byId = new HashMap<>();
        containers.forEach((id, items) -> byId.put(id, (ItemContainer) Proxy.newProxyInstance(
            ItemContainer.class.getClassLoader(), new Class<?>[]{ItemContainer.class},
            (proxy, method, args) -> "getItems".equals(method.getName()) ? items : null)));
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, args) -> {
                switch (method.getName())
                {
                    case "getItemContainer":
                        return byId.get((int) args[0]);
                    case "getVarbitValue":
                        return varbits.getOrDefault((int) args[0], 0);
                    default:
                        return null;
                }
            });
        return new ContainerSnapshotFactory(client, null).capture(true, false);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static com.gpmanager.EngineTestFixtures.mapOf;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The ring of suffering's recoils are committed: a discharge never refunds them, so a load books
 * one counted Supplies row at the recoil's price (owner 2026-10-12). The ring keeps no Check
 * comparison; the effect toggle, an uncharge and the bank's Configure-Charges book nothing.
 */
public class SufferingCommittedLoadTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final String RING = "149:0:9764864:20657:SUFFERING";
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override public int stabilizationTicks() { return 2; }
        @Override public boolean keepTransferAuditRows() { return true; }
    };

    @Test
    public void committedRecoilLoadsBookTheirRecoilsAsSupplies()
    {
        Engine engine = engine();
        long start = 100_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.RING_OF_RECOIL, 30L));

        assertTrue(engine.markChargeLoad(ChargeCheck.ChargedItem.SUFFERING, ItemID.RING_OF_RECOIL,
            "Ring of recoil", RING, 8));
        engine.markDirty();
        Transaction load = settle(engine, snapshot(ItemID.RING_OF_RECOIL, 25L), start + 600L);

        assertEquals(TransactionType.CONSUMPTION, load.original());
        assertTrue(load.counts());
        assertEquals(GameData.msg("committedLoad") + "Ring of suffering", load.note());
        assertEquals(ActionKind.SUPPLIES, load.action());
        assertEquals(-2_500L, load.net());
        assertEquals(2_500L, engine.metrics(start + 2_400L).cost);
    }

    @Test
    public void theRingsCheckLineBooksNothing()
    {
        Engine engine = engine();
        long start = 120_000L;
        engine.ensureSession(start);

        // The exact live Check line (owner recording 2026-10-12): a committed load has nothing
        // to compare, so the read never books.
        new ChargeIntake(null, null, CONFIG, engine, null).observeCheck(
            "Your ring currently has 5,097 recoil charges remaining. The recoil effect is currently disabled.",
            start);

        assertTrue(engine.session().transactions().isEmpty());
        assertEquals(0L, engine.metrics(start).net);
    }

    @Test
    public void anUnchargeBooksNothing()
    {
        Engine engine = engine();
        long start = 140_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.NZONE_ZENYTE_RING_ENCHANTED_RECOIL, 1L));

        ChargeIntake intent = new ChargeIntake(selecting(null), null, CONFIG, engine, null);
        intent.armCheck(click(MenuAction.CC_OP, "Uncharge", item(ItemID.NZONE_ZENYTE_RING_ENCHANTED_RECOIL, 0)),
            "uncharge", "Ring of suffering (ri)");
        assertNotNull("the uncharge watch arms", engine.events.peek(Inbox.UNCHARGE));
        engine.markDirty();
        settle(engine, snapshot(ItemID.ZENYTE_RING_ENCHANTED, 1L), start + 600L);

        assertTrue("the charge was booked at load; the uncharge adds nothing",
            engine.session().transactions().stream().noneMatch(Transaction::counts));
        assertEquals(0L, engine.metrics(start + 2_400L).net);
    }

    @Test
    public void theBankConfigureChargesRouteNeverPhantomBooks()
    {
        Engine engine = engine();
        long start = 160_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.RING_OF_RECOIL, 30L));

        ChargeIntake intent = new ChargeIntake(selecting(null), null, CONFIG, engine, null);
        intent.armCheck(click(MenuAction.CC_OP, "Configure-Charges", item(ItemID.NZONE_ZENYTE_RING_ENCHANTED_RECOIL, 0)),
            "configure-charges", "Ring of suffering (ri)");
        assertNull("no load arms without a use-on click", engine.events.peek(Inbox.LOAD_TARGET));

        // Bank-side charges are a documented blind spot: a recoil move without the use click is
        // never a charge load, and the recoils still book as the ordinary spend they are.
        engine.markDirty();
        settle(engine, snapshot(ItemID.RING_OF_RECOIL, 25L), start + 600L);
        for (Transaction row : engine.session().transactions())
        {
            assertFalse("a bank load cannot phantom-book as a charge load",
                row.note() != null && row.note().startsWith(GameData.msg("committedLoad")));
        }
        assertTrue("the recoils still book ordinarily",
            engine.session().transactions().stream().anyMatch(Transaction::counts));
    }

    private static Engine engine()
    {
        return new Engine(SufferingCommittedLoadTest::flows, new TransactionClassifier(), CONFIG);
    }

    private static List<Flow> flows(Map<Integer, Long> deltas)
    {
        List<Flow> flows = new ArrayList<>();
        for (Map.Entry<Integer, Long> entry : deltas.entrySet())
        {
            flows.add(new Flow(entry.getKey(), "Ring of recoil", entry.getValue(), 500,
                entry.getValue() * 500));
        }
        return flows;
    }

    private static ContainerSnapshot snapshot(int id, long quantity)
    {
        return snapshot(mapOf(id, quantity));
    }

    private static ContainerSnapshot snapshot(Map<Integer, Long> quantities)
    {
        return new ContainerSnapshot(quantities);
    }


    private static Transaction settle(Engine engine, ContainerSnapshot next, long firstTick)
    {
        assertNull(engine.processIfDirty(next, firstTick, null));
        assertNull(engine.processIfDirty(next, firstTick + 600L, null));
        return engine.processIfDirty(next, firstTick + 1_200L, null);
    }

    private static Widget item(int itemId, int slot)
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[] {Widget.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getItemId": return itemId;
                    case "getIndex": return slot;
                    case "getId": return InterfaceID.Inventory.ITEMS;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        return null;
                }
            });
    }

    private static Client selecting(Widget selected)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getSelectedWidget": return selected;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
    }

    private static MenuOptionClicked click(MenuAction action, String option, Widget clicked)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return option;
                    case "getTarget": return "";
                    case "getType": return action;
                    case "getWidget": return clicked;
                    case "getItemId": return clicked == null ? -1 : clicked.getItemId();
                    case "getParam0": return clicked == null ? -1 : clicked.getIndex();
                    case "getParam1": return clicked == null ? -1 : clicked.getId();
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }
}

package com.gpmanager;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.5.2: a target starts a new Live session. Net, Gains, Recent, the clock and GP/h count
 * from it while the run keeps every booking; Done leaves the session counting.
 */
public class TargetFreshStartTest
{
    static final long MINUTE = 60_000L;
    static final long HOUR = 60L * MINUTE;

    static Engine engine()
    {
        Engine engine = new Engine(deltas -> java.util.Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig() {});
        engine.ensureSession(0L);
        return engine;
    }

    static void coins(Engine engine, long at, long gp)
    {
        engine.session().addTransaction(new Transaction(at, TransactionType.GAIN, Context.GENERIC, "",
            "General", true, java.util.List.of(new Flow(995, "Coins", gp, 1, gp, PriceSource.FACE_VALUE)),
            Confidence.LIKELY, "", null), 2_000, false);
    }

    /** What Recent adds up to: same-item rows merge, so the sum, not the count, is the check. */
    static long recentTotal(LiveSnapshot live)
    {
        return live.recent.stream().filter(row -> !row.open).mapToLong(LiveSnapshot.Recent::net).sum();
    }

    static LiveSnapshot live(Engine engine, long now)
    {
        return LiveSnapshot.capture(engine, now, null);
    }

    @Test
    public void aTargetStartsLiveFreshAndDoneBringsTheWholeRunBack()
    {
        Engine engine = engine();
        Session run = engine.session();
        coins(engine, 5L, 1_000L);
        engine.setTargets(5_000_000L, null, HOUR);

        LiveSnapshot started = live(engine, HOUR);
        assertEquals("Net starts at zero", 0L, started.net);
        assertEquals("so do Gains", 0L, started.income);
        assertEquals("and the clock", 0L, started.elapsed);
        assertEquals("the hero's aim pair agrees", 0L, started.goal.current);
        assertTrue("Recent starts fresh for the target", started.recent.isEmpty());

        coins(engine, HOUR + 5L, 500L);
        LiveSnapshot later = live(engine, 2 * HOUR);
        assertEquals("what came after counts", 500L, later.net);
        assertEquals(500L, later.income);
        assertEquals(HOUR, later.elapsed);
        assertEquals(500L, later.rate);
        assertEquals(500L, later.goal.current);
        assertEquals("Net plus the base is the whole run", 1_500L, later.net + later.netBase);
        assertSame("the same run", run, engine.session());
        assertEquals("the run keeps every booking", 2, run.transactions().size());
        assertEquals(1_500L, engine.metrics(2 * HOUR).net);

        Long session = run.sessionStartAt;
        engine.setTargets(null, null, 2 * HOUR);
        LiveSnapshot done = live(engine, 2 * HOUR);
        assertEquals("Done keeps the session counting", session, run.sessionStartAt);
        assertEquals(500L, done.net);
        assertEquals(500L, recentTotal(done));
        assertEquals(HOUR, done.elapsed);
        assertNull(done.goal);
    }

    @Test
    public void reSavingKeepsTheCountAndAChangedTargetStartsAgain()
    {
        Engine engine = engine();
        coins(engine, 5L, 1_000L);
        engine.setTargets(5_000_000L, HOUR, HOUR);
        coins(engine, HOUR + 5L, 500L);

        engine.setTargets(5_000_000L, HOUR, HOUR + 10L * MINUTE);
        assertEquals("re-saving the same target keeps its count", 500L, live(engine, HOUR + 10L * MINUTE).net);

        engine.setTargets(5_000_000L, 2 * HOUR, HOUR + 20L * MINUTE);
        LiveSnapshot changed = live(engine, HOUR + 20L * MINUTE);
        assertEquals("a changed time starts the whole target again", 0L, changed.net);
        assertEquals(0L, changed.goal.current);
        assertEquals(0L, engine.session().timeWindowMillis(HOUR + 20L * MINUTE));
    }

    /** A row timed before the target (a login recheck, a Review fix) stays out of the target run. */
    @Test
    public void rowsBookedBeforeTheTargetStayOut()
    {
        Engine engine = engine();
        coins(engine, 5L, 1_000L);
        engine.setTargets(5_000_000L, null, HOUR);
        coins(engine, 10L, 700L);
        assertEquals(0L, live(engine, HOUR + MINUTE).net);
        assertEquals(0L, engine.session().targetProgress(engine.metrics(HOUR + MINUTE).net));
        assertEquals("the run counts it", 1_700L, engine.metrics(HOUR + MINUTE).net);
    }

    @Test
    public void aGrindKeepsItsWholeRun()
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", 0L);
        coins(engine, 5L, 1_000L);
        engine.setTargets(5_000_000L, null, HOUR);
        coins(engine, HOUR + 5L, 500L);
        assertEquals(500L, live(engine, 2 * HOUR).net);
        assertEquals("the Grind's own numbers (best run, average GP/h) keep the whole run",
            1_500L, engine.session().metrics(2 * HOUR).net);
    }

    @Test
    public void anOlderSaveWithoutAStartReadsTheWholeRun()
    {
        Engine engine = engine();
        coins(engine, 5L, 1_000L);
        engine.setTargets(5_000_000L, null, HOUR);
        engine.session().sessionStartAt = null;
        coins(engine, HOUR + 5L, 500L);
        LiveSnapshot live = live(engine, 2 * HOUR);
        assertEquals(1_500L, live.net);
        assertEquals("the aim keeps its own baseline", 500L, live.goal.current);
    }

    @Test
    public void aTimeTargetCountsDownWithoutAProjection()
    {
        Engine engine = engine();
        coins(engine, 5L, 1_000_000L);
        engine.setTargets(null, HOUR, HOUR);
        coins(engine, HOUR + 5L * MINUTE, 100_000L);
        LiveSnapshot live = live(engine, HOUR + 30L * MINUTE);
        assertNull("the hero's GP/h already says the pace", live.goal.eta);
        assertEquals(30L * MINUTE, live.goal.remaining);
    }

    /** Engine.restartTarget (Again) starts a new session with the same target. */
    @Test
    public void againAndResetStartTheTargetFresh()
    {
        Engine engine = engine();
        engine.setTargets(5_000_000L, 10L * MINUTE, 0L);
        coins(engine, 5L, 1_000L);
        assertTrue(engine.restartTarget(HOUR));
        assertEquals(0L, live(engine, HOUR).net);
        coins(engine, HOUR + 5L, 400L);
        assertTrue(engine.restartTarget(2 * HOUR));
        assertEquals(0L, live(engine, 2 * HOUR).net);
        assertEquals(1_400L, engine.metrics(2 * HOUR).net);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import org.junit.Test;
import org.junit.Before;
import org.junit.After;

import static org.junit.Assert.*;

/** Recorded first Revenant teleport: the click precedes the confirmation and physical tablet loss. */
public class TeleportStartBoundaryTest
{
    private static final int TABLET = 21802;
    private static final GpManagerConfig CONFIG = new GpManagerConfig() {
        @Override public int stabilizationTicks() { return 1; }
    };

    private long now = 1_000;
    private java.util.function.LongSupplier previousClock;
    @Before public void fixedClock() { previousClock = SafeMath.clock; SafeMath.clock = () -> now; }
    @After public void restoreClock() { SafeMath.clock = previousClock; }

    private final Engine engine = new Engine(deltas -> {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, count) -> flows.add(new Flow(id, "Revenant cave teleport", count,
                492, count * 492, PriceSource.GRAND_EXCHANGE)));
        return flows;
    }, new TransactionClassifier(), CONFIG);

    private void click() throws Exception
    {
        click(true);
    }

    /** An item click on the tablet, or an NPC's own Teleport option (a wizard) with the tablet in slot 0. */
    private void click(boolean item) throws Exception
    {
        ItemContainer inventory = proxy(ItemContainer.class, method ->
                "getItems".equals(method) ? new Item[] {new Item(TABLET, 1)} : null);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
                new Class<?>[] {Client.class}, (object, method, args) -> {
                    if ("getGameState".equals(method.getName())) return GameState.LOGGED_IN;
                    if ("getItemContainer".equals(method.getName()))
                        return Integer.valueOf(InventoryID.INV).equals(args[0]) ? inventory : null;
                    if (!method.getReturnType().isPrimitive()) return null;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == long.class) return 0L;
                    return 0;
                });
        GpManagerPlugin plugin = new GpManagerPluginProbe();
        GpManagerPluginProbe.set(plugin, "client", client);
        GpManagerPluginProbe.set(plugin, "config", CONFIG);
        GpManagerPluginProbe.set(plugin, "engine", engine);
        GpManagerPluginProbe.set(plugin, "containers", new ContainerSnapshotFactory(client, null));
        GpManagerPluginProbe.set(plugin, "targets", GpManagerPluginProbe.tracker(client, engine, CONFIG));
        GpManagerPluginProbe.set(plugin, "charges", new ChargeIntake(client, null, CONFIG, engine, null));
        MenuEntry entry = proxy(MenuEntry.class, method -> {
            if ("getOption".equals(method)) return "Teleport";
            if ("getTarget".equals(method)) return item ? "Revenant cave teleport" : "Aubury";
            if ("getItemId".equals(method)) return item ? TABLET : -1;
            if ("getType".equals(method)) return item ? MenuAction.CC_OP : MenuAction.NPC_THIRD_OPTION;
            if ("isItemOp".equals(method)) return item;
            return null;
        });
        plugin.onMenuOptionClicked(new MenuOptionClicked(entry));
    }

    private void settle(long quantity)
    {
        engine.markDirty();
        ContainerSnapshot held = new ContainerSnapshot(quantity == 0 ? Map.of() : Map.of(TABLET, quantity));
        for (int tick = 1; tick <= 6; tick++) engine.processIfDirty(held, now += 600, null);
    }

    @Test public void firstTeleportStartsBeforeTheTabletDisappears() throws Exception
    {
        click();
        assertNotNull("the menu starts tracking before the item changes", engine.session());
        settle(0);
        assertEquals(0, engine.metrics(now).income);
        assertEquals(492, engine.metrics(now).cost);
        assertEquals(1, engine.session().transactions().size());
        Flow spent = engine.session().transactions().get(0).flows().get(0);
        assertEquals(-1, spent.quantity);
        assertEquals(492, spent.unitPrice);
    }

    @Test public void anNpcTeleportNeverNamesTheItemInTheFirstSlot() throws Exception
    {
        click(false);
        assertTrue("an NPC entry's scene coordinates are not an inventory slot",
                engine.intent() == null || engine.intent().item != TABLET);
    }

    @Test public void cancelledTeleportNeverInventsACost() throws Exception
    {
        click();
        settle(1);
        assertEquals(0, engine.metrics(now).net);
        assertTrue(engine.session() == null || engine.session().transactions().isEmpty());
    }

    @Test public void aManuallyPausedRunStaysPaused() throws Exception
    {
        engine.ensureSession(now);
        engine.setBaseline(new ContainerSnapshot(Map.of(TABLET, 1L)));
        engine.session().pause(now, PauseReason.MANUAL);
        click();
        settle(0);
        assertTrue(engine.session().paused);
        assertEquals(0, engine.metrics(now).cost);
    }

    @Test public void anAlreadyRunningTeleportCountsOnlyOnce() throws Exception
    {
        engine.ensureSession(now);
        engine.setBaseline(new ContainerSnapshot(Map.of(TABLET, 1L)));
        click();
        settle(0);
        settle(0);
        assertEquals(492, engine.metrics(now).cost);
        assertEquals(1, engine.session().transactions().size());
    }

    private static <T> T proxy(Class<T> type, java.util.function.Function<String, Object> values)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type},
                (object, method, args) -> {
                    Object value = values.apply(method.getName());
                    if (value != null || !method.getReturnType().isPrimitive()) return value;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == long.class) return 0L;
                    return 0;
                }));
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.3: an abyssal tentacle costs nothing per hit; it is a loss only when it is used up or
 * dissolved, which leaves the kraken tentacle and loses the whip (OSRS Wiki).
 */
public class TentacleWornOutTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    /** RuneLite prices the tentacle as the whip (1.3M) plus the kraken tentacle (300k). */
    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> {
            int unit = id == ItemID.ABYSSAL_TENTACLE ? 1_600_000 : 300_000;
            flows.add(new Flow(id, id == ItemID.ABYSSAL_TENTACLE ? "Abyssal tentacle" : "Kraken tentacle",
                quantity, unit, quantity * unit));
        });
        return flows;
    };

    @Test
    public void aUsedUpTentacleBooksTheWhipAsALossWithoutReview()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(ItemID.ABYSSAL_TENTACLE));
        Transaction row = settle(engine, snapshot(ItemID.KRAKEN_TENTACLE), 1_600L);
        assertNotNull(row);
        assertTrue(row.counts());
        assertEquals(TransactionType.CONSUMPTION, row.type());
        assertEquals("the whip is the loss", -1_300_000L, engine.metrics(10_000L).net);
        Flow tentacle = row.flows().stream().filter(Flow::cost).findFirst().get();
        assertEquals(CostKind.LOSS, CostKind.of(row, tentacle));
        assertEquals(0, engine.getReviewRows(10_000L).size());
    }

    @Test
    public void aTentacleLeavingWithoutItsKrakenTentacleIsNotThisRow()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(ItemID.ABYSSAL_TENTACLE));
        Transaction row = settle(engine, FixtureReads.empty(), 1_600L);
        assertTrue("only a used-up or dissolved tentacle books this way",
            row == null || !GameData.msg("tentacleUsed").equals(row.note()));
    }

    private static ContainerSnapshot snapshot(int itemId)
    {
        return new ContainerSnapshot(Collections.singletonMap(itemId, 1L));
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        Transaction row = null;
        for (long t = firstTick; row == null && t < firstTick + 6_000L; t += 600L) row = engine.processIfDirty(snapshot, t, null);
        return row;
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
