    private static ChargeDelta observe(Engine engine, String chat, String target, long now)
    {
        ChargeCheck read = ChargeCheck.parse(chat);
        assertNotNull(chat, read);
        ChargeDelta delta = engine.observeCheck(read, target, now);
        return delta;
    }

    /** Prices every measured component the way the intake does (coins at face value). */
    private static Transaction book(Engine engine, ChargeDelta delta, String label, long now)
    {
        List<Flow> losses = new ArrayList<>();
        for (ChargeDelta.ComponentDelta component : delta.getComponentDeltas())
        {
            int id = component.getItemId();
            int unitPrice = id == 995 ? 1 : id == 12934 ? 2 : 100;
            losses.add(new Flow(id, "Item " + id, component.getQuantityDelta(), unitPrice,
                component.getQuantityDelta() * unitPrice,
                id == 995 ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE, now));
        }
        Transaction result = engine.bookChargeSpend(delta, label, losses, now, null);
        assertTrue(label, result != null);
        return result;
    }

    private static Engine engine()
    {
        Engine engine = new Engine(
            deltas -> Collections.<Flow>emptyList(), new TransactionClassifier(), new GpManagerConfig() { });
        engine.ensureSession(500L);
        return engine;
    }

    private static void assertSupplies(Transaction spend)
    {
        for (Flow flow : spend.flows())
        {
            assertEquals("charge spend is Supplies, never Loss", CostKind.SUPPLIES, CostKind.of(spend, flow));
        }
    }

    private static long quantityDelta(ChargeDelta delta, int itemId)
    {
        for (ChargeDelta.ComponentDelta component : delta.getComponentDeltas())
        {
            if (component.getItemId() == itemId)
            {
                return component.getQuantityDelta();
            }
        }
        throw new AssertionError("Missing component delta for item " + itemId);
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public final class ChargeLoadTransferEvidenceTest
{
    @Test
    public void itemOnItemIntentCannotPartitionWithoutQuantity()
    {
        Engine evidence = ReviewFixesTest.engine();
        assertTrue(evidence.markChargeLoad(
            ChargeCheck.ChargedItem.BLOWPIPE,
            12934,
            "Zulrah's scales",
            null,
            5));

        Flow scales = new Flow(12934, "Zulrah's scales", -50L, 100, -5_000L);
        Flow darts = new Flow(ItemID.RUNE_DART, "Rune dart", -1L, 500, -500L);
        LoadTarget partition = evidence.loadTarget(Arrays.asList(scales, darts));

        assertTrue(partition.remaining.isEmpty());
        assertEquals(Arrays.asList(scales, darts), partition.unknown);
    }

    @Test
    public void allSupportedSameIdCandidatesStayInReview()
    {
        Engine evidence = ReviewFixesTest.engine();
        assertTrue(evidence.markChargeLoad(
            ChargeCheck.ChargedItem.BLOWPIPE, 12934, "Zulrah's scales", null, 5));
        Flow first = new Flow(12934, "Zulrah's scales", -20L, 100, -2_000L);
        Flow second = new Flow(12934, "Zulrah's scales", -30L, 100, -3_000L);

        LoadTarget partition = evidence.loadTarget(Arrays.asList(first, second));

        assertTrue(partition.remaining.isEmpty());
        assertEquals(Arrays.asList(first, second), partition.unknown);
    }

    @Test
    public void secondSameIdLossInWindowAlsoFailsClosed()
    {
        Engine evidence = ReviewFixesTest.engine();
        assertTrue(evidence.markChargeLoad(
            ChargeCheck.ChargedItem.BLOWPIPE, 12934, "Zulrah's scales", null, 5));
        Flow first = new Flow(12934, "Zulrah's scales", -3L, 100, -300L);
        Flow second = new Flow(12934, "Zulrah's scales", -2L, 100, -200L);

        LoadTarget firstPartition = evidence.loadTarget(Collections.singletonList(first));
        LoadTarget secondPartition = evidence.loadTarget(Collections.singletonList(second));

        assertEquals(Collections.singletonList(first), firstPartition.unknown);
        assertEquals(Collections.singletonList(second), secondPartition.unknown);
    }

    @Test
    public void anotherWeaponComponentAndMismatchedIdentityCannotArm()
    {
        Engine evidence = ReviewFixesTest.engine();
        assertFalse(evidence.markChargeLoad(
            ChargeCheck.ChargedItem.BLOWPIPE,
            ItemID.RUNE_DART,
            "Adamant dart",
            null,
            5));
        assertTrue(evidence.markChargeLoad(
            ChargeCheck.ChargedItem.BLOWPIPE,
            ItemID.RUNE_DART,
            "Rune dart",
            null,
            5));

        Flow scales = new Flow(12934, "Zulrah's scales", -2L, 100, -200L);
        LoadTarget partition = evidence.loadTarget(Collections.singletonList(scales));
        assertEquals(Collections.singletonList(scales), partition.remaining);
    }

    @Test
    public void intentExpiresOnTickWithoutInventorySettlement()
    {
        Engine evidence = ReviewFixesTest.engine();
        assertTrue(evidence.markChargeLoad(
            ChargeCheck.ChargedItem.TRIDENT_SEAS,
            560,
            "Death rune",
            null,
            2));
        evidence.events.tick(evidence.events.now + 1);
        evidence.events.tick(evidence.events.now + 1);
        assertNull("the stale load intent is gone", evidence.events.peek(Inbox.LOAD_TARGET));
    }

}

