        assertNotNull(transaction);
        assertEquals(TransactionType.CONSUMPTION, transaction.type());
        assertTrue(transaction.counts());
        assertEquals(ActionKind.FIRE, transaction.action());
        assertEquals(-308L, transaction.net());
