    @Test
    public void unrelatedAndMalformedMessagesCannotSpend()
    {
        assertNull(ChargeCheck.parse("You cast a spell."));
        ChargeCheck malformed = ChargeCheck.parse(
            "Darts: Adamant dart x many. Scales: 100 (1.0%).");
        assertNotNull(malformed);
        assertFalse(malformed.supported);

        MeasuredChargeReadTracker tracker = new MeasuredChargeReadTracker();
        ChargeOutcomeTest.none(observe(tracker, trident("seas", "", 10)));
        ChargeOutcomeTest.none(observe(tracker, malformed));
        assertNull(tracker.baseline.get("single-target"));
    }

    private static ChargeDelta observe(
        MeasuredChargeReadTracker tracker,
        ChargeCheck read)
    {
        return tracker.observe(read, "single-target", System.currentTimeMillis());
    }

    private static ChargeCheck trident(String type, String enhanced, long charges)
    {
        String count = charges == 1L ? "one charge" : charges == 0L ? "no charges" : charges + " charges";
        return ChargeCheck.parse(
            "Your Trident of the " + type + enhanced + " has " + count + ".");
    }

    private static ChargeCheck blowpipe(String dart, long scales, long darts)
    {
        return ChargeCheck.parse(
            "Darts: " + dart + " dart x " + darts + ". Scales: " + scales + " (1.0%).");
    }

    private static ChargeCheck noDarts(long scales)
    {
        return ChargeCheck.parse(
            "Darts: None. Scales: " + scales + " (1.0%).");
    }

    private static MenuOptionClicked menuCheck(int itemId, int widgetId, int slot)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return "Check";
                    case "getTarget": return "Toxic blowpipe";
                    case "getIdentifier": return itemId;
                    case "getItemId": return itemId;
                    case "getType": return MenuAction.ITEM_FIRST_OPTION;
                    case "getParam0": return slot;
                    case "getParam1": return widgetId;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }

    /** A worn Check whose item and widget fields are omitted; the slot widget carries both. */
    private static MenuOptionClicked menuCheckViaWidget(int itemId, int widgetId, int slot)
    {
        Widget widget = (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
            new Class<?>[] {Widget.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getId": return widgetId;
                    case "getItemId": return itemId;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return "Check";
                    case "getTarget": return "Toxic blowpipe";
                    case "getIdentifier": return -1;
                    case "getItemId": return -1;
                    case "getType": return MenuAction.ITEM_FIRST_OPTION;
                    case "getParam0": return slot;
                    case "getParam1": return 0;
                    case "getWidget": return widget;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }

    private static long quantityDelta(ChargeDelta delta, int itemId)
    {
        assertNotNull(delta);
        for (ChargeDelta.ComponentDelta component : delta.getComponentDeltas())
        {
            if (component.getItemId() == itemId)
            {
                return component.getQuantityDelta();
            }
        }
        throw new AssertionError("Missing component delta for item " + itemId);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class AccountingFoldContractTest {
    private static final long NOW = 1_700_000_000_000L;

    private static Transaction row(long at, long value) {
        return Tx.of(at, TransactionType.ADJUSTMENT, Context.GENERIC, "", true,
                List.of(new Flow(995, "Coins", value, 1, value, PriceSource.FACE_VALUE)));
    }

    @Test public void scalarHistoryAndAllNullFlowCoverageKeepTheirDistinctMeaning() {
        var scalar = row(NOW, 1);
        scalar.flows = List.of();
        scalar.revenue = 77;
        scalar.costs = 30;
        assertEquals(47, Accounting.transaction(scalar).net());
        scalar.applyCorrection(Correction.COST, "Owner decision");
        assertEquals(107, Accounting.transaction(scalar).cost);
        var absent = row(NOW, 1);
        absent.flows = new ArrayList<>(Arrays.asList(null, null));
        assertFalse(Accounting.transaction(absent).included);
    }

    @Test public void zeroMixedAndExtremeCorrectionsRetainTheirOriginalQuotedFacts() {
        var row = Tx.of(NOW, TransactionType.ADJUSTMENT, Context.GENERIC, "", true, List.of(
                new Flow(995, "Coins", 40, 1, 40, PriceSource.FACE_VALUE),
                new Flow(526, "Bones", -1, 10, -10, PriceSource.MANUAL_OVERRIDE),
                new Flow(1203, "Iron dagger", 1, 0, 0, PriceSource.NO_VALUE)));
        assertEquals(30, Accounting.transaction(row).net());
        row.applyCorrection(Correction.REVENUE, "Gain");
        assertEquals(50, Accounting.transaction(row).income);
        assertEquals(0, Accounting.transaction(row).cost);
        row.applyCorrection(Correction.COST, "Cost");
        assertEquals(50, Accounting.transaction(row).cost);
        assertEquals(0, Accounting.transaction(row).income);
        assertEquals(-10, row.flows().get(1).value);
        assertEquals(PriceSource.NO_VALUE, row.flows().get(2).source());
        row.applyCorrection(Correction.IGNORE, "Exclude");
        assertFalse(Accounting.transaction(row).included);
        var extreme = Tx.of(NOW, TransactionType.ADJUSTMENT, Context.GENERIC, "", true, List.of(
                new Flow(526, "Bones", -1, Long.MAX_VALUE, Long.MIN_VALUE, PriceSource.MANUAL_OVERRIDE),
                new Flow(995, "Coins", 1, 1, 1, PriceSource.FACE_VALUE)));
        extreme.applyCorrection(Correction.REVENUE, "Gain");
        assertEquals(Long.MAX_VALUE, Accounting.transaction(extreme).income);
    }

    @Test public void retentionKeepsItsBoundaryPredicateOrderAndProtectedReceipt() {
        var engine = ReviewFixesTest.engine();
        engine.startCustom("Retention contract", NOW);
        var first = row(NOW + 1, 10);
        var protectedRow = row(NOW + 2, 20);
        var boundary = row(NOW + 3, 30);
        var future = row(NOW + 4, 40);
        var session = engine.session();
        for (var transaction : List.of(first, protectedRow, boundary, future))
            session.addTransaction(transaction, 2000, false);
        session.transactions.add(0, null);
        var visited = new ArrayList<String>();
        int folded = session.compactBefore(NOW + 3, transaction -> {
            visited.add(transaction.id());
            return transaction == protectedRow;
        });
        assertEquals(1, folded);
        assertEquals(List.of(first.id(), protectedRow.id()), visited);
        assertEquals(10, session.retainedRevenue);
        assertEquals(1, session.compactedTransactionCount);
        assertTrue(session.transactions.contains(protectedRow));
        assertTrue(session.transactions.contains(boundary));
        assertTrue(session.transactions.contains(future));
    }
}

package com.gpmanager;

import org.junit.Test;
import static org.junit.Assert.*;

/** Preserve the UTF-16 character gate and the ordered removal of native markup. */
public class ActionLabelSharingContractTest {
    @Test public void everyCodeUnitAndSupplementaryNamesKeepTheirOldEligibility() {
        for(int code=0;code<=Character.MAX_VALUE;code++) {
            String text=String.valueOf((char)code);
            boolean valid=Character.isLetterOrDigit(code)||code==' '||code=='\''||code=='-'||code==',';
            assertEquals("code unit "+code,valid?text:null,ActionLabel.useful(text));
        }
        for(String text:new String[]{"Cast","cASt","ca\u017ft","Autocast","Cancel","", "a".repeat(65),
            "Cast Ice Barrage","\ud801\udc00","a\ud801\udc00b","\ud83d\ude00","\ud800","\udc00"}) {
            boolean valid=!text.isEmpty()&&text.length()<=64&&!text.equalsIgnoreCase("cast")
                &&!text.equalsIgnoreCase("autocast")&&!text.equalsIgnoreCase("cancel")
                &&text.chars().allMatch(c->Character.isLetterOrDigit(c)||c==' '||c=='\''||c=='-'||c==',');
            assertEquals(text,valid?text:null,ActionLabel.useful(text));
        }
    }
    @Test public void markupRemovalStillRunsBeforeEntityAndWhitespaceNormalization() {
        for(String first:new String[]{"","<col=ff0000>","@abc@","<x @abc@>","@ab<x>c@","<x\ny>","<@abc@"})
            for(String second:new String[]{"","&nbsp;","&#160;","@123456@","@1234567@","\n\t Ice ","\u00a0"}) {
                String text=first+second;
                String expected=text.replaceAll("<[^>]*>"," ").replaceAll("@[a-zA-Z0-9]{3,6}@"," ")
                    .replace("&nbsp;"," ").replace("&#160;"," ").replaceAll("\\s+"," ").trim();
                assertEquals(text,expected,ActionLabel.clean(text));
            }
        assertEquals("",ActionLabel.clean(null));
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class BasisDeltaTrimContractTest {
    @Test public void signedDeltasKeepOrderAbsentZeroPairsAndDetachedArrays() {
        var basis = new TrackedBasisLedger();
        var before = new LinkedHashMap<Integer, long[]>();
        before.put(1, new long[]{2, 200});
        before.put(2, new long[]{1, 0});
        before.put(3, new long[]{0, 0});
        var after = new LinkedHashMap<Integer, long[]>();
        after.put(1, new long[]{1, 100});
        after.put(2, new long[]{1, 0});
        after.put(4, new long[]{0, 0});
        after.put(5, new long[]{2, 0});
        var delta = basis.deltas(before, after);
        assertEquals(List.of(1, 4, 5), new ArrayList<>(delta.keySet()));
        assertArrayEquals(new long[]{-1, -100}, delta.get(1));
        assertArrayEquals(new long[]{0, 0}, delta.get(4));
        assertArrayEquals(new long[]{2, 0}, delta.get(5));
        delta.get(1)[0] = 99;
        delta.get(5)[0] = 99;
        assertEquals(2, before.get(1)[0]);
        assertEquals(1, after.get(1)[0]);
        assertEquals(2, after.get(5)[0]);
    }

    @Test public void deltaComponentsRetainSignedCapacityBoundaries() {
        var before = new LinkedHashMap<Integer, long[]>();
        var after = new LinkedHashMap<Integer, long[]>();
        before.put(1, new long[]{Long.MAX_VALUE, 0});
        before.put(2, new long[]{0, Long.MAX_VALUE});
        before.put(3, new long[]{Long.MAX_VALUE, Long.MAX_VALUE});
        after.put(1, new long[]{0, Long.MAX_VALUE});
        after.put(2, new long[]{Long.MAX_VALUE, 0});
        after.put(3, new long[]{Long.MAX_VALUE, Long.MAX_VALUE});
        var delta = new TrackedBasisLedger().deltas(before, after);
        assertEquals(List.of(1, 2), new ArrayList<>(delta.keySet()));
        assertArrayEquals(new long[]{-Long.MAX_VALUE, Long.MAX_VALUE}, delta.get(1));
        assertArrayEquals(new long[]{Long.MAX_VALUE, -Long.MAX_VALUE}, delta.get(2));
    }

    @Test public void nullTargetsKeepTheirOriginalExistingAndAbsentKeyBehavior() {
        var before = new LinkedHashMap<Integer, long[]>();
        var after = new LinkedHashMap<Integer, long[]>();
        before.put(1, new long[]{1, 100});
        after.put(1, null);
        assertArrayEquals(new long[]{-1, -100}, new TrackedBasisLedger().deltas(before, after).get(1));
        after.put(2, null);
        try {
            new TrackedBasisLedger().deltas(before, after);
            fail("an absent key with a null delta vector remains invalid");
        } catch (NullPointerException expected) {
            assertEquals(1, before.get(1)[0]);
        }
    }

    @Test public void aMissingNormalizedUndoTargetRefusesWithoutPartialChanges() {
        var engine = PreEpochReceiptRestoreTest.engine();
        long at = 1_700_000_000_001L;
        for (int id : new int[]{1203, 882})
            engine.session().addTransaction(Tx.of(at++, TransactionType.GAIN, Context.GENERIC,
                    "", true, List.of(new Flow(id, "Item", 1, 100, 100, PriceSource.MANUAL_OVERRIDE))), 2000, false);
        var rows = new ArrayList<>(engine.session().transactions());
        assertTrue(engine.correctEntries(List.of(rows.get(0).id(), rows.get(1).id()), Correction.COST));
        engine.session().transactions.remove(rows.get(0));
        var gson = new com.google.gson.Gson();
        String basis = gson.toJson(engine.basis.stock);
        String receipts = gson.toJson(engine.session().transactions());
        String history = gson.toJson(engine.session().correctionHistory);
        assertFalse(engine.undoCorrection());
        assertEquals(basis, gson.toJson(engine.basis.stock));
        assertEquals(receipts, gson.toJson(engine.session().transactions()));
        assertEquals(history, gson.toJson(engine.session().correctionHistory));
    }
}

package com.gpmanager;

import java.util.List;
import java.util.function.Supplier;
import org.junit.Test;
import static org.junit.Assert.*;

/** Confirmation totals must equal the canonical totals after applying the same change. */
public class CorrectionPreviewSaturationTest {
    private static final long NOW = ReviewFixesTest.T0 + 1000;
    private static final long FOUR_E18 = 4_000_000_000_000_000_000L;

    private static Transaction book(Engine engine, int item, long quantity, long value, boolean review) {
        var row = Tx.of(NOW, review ? TransactionType.UNCERTAIN
                        : quantity < 0 ? TransactionType.CONSUMPTION : TransactionType.GAIN,
                Context.GENERIC, "", !review, List.of(new Flow(item, "Item " + item, quantity, 100, value)));
        row.confidence = review ? Confidence.UNCERTAIN : Confidence.CONFIRMED;
        engine.session().addTransaction(row, 2000, false);
        return row;
    }

    private static <T> T readOnly(Engine engine, Supplier<T> request) {
        String before = JsonCodec.gson().toJson(engine.session());
        long revision = engine.revision();
        T preview = request.get();
        assertEquals("preview must not change saved receipts, history or Undo", before,
                JsonCodec.gson().toJson(engine.session()));
        assertEquals("preview must not advance the revision", revision, engine.revision());
        return preview;
    }

    private static void remove(Engine engine, Transaction target, long after, long change) {
        var preview = readOnly(engine, () -> LedgerData.preview(engine, target.id(), Correction.IGNORE, NOW));
        assertNotNull(preview);
        assertEquals(after, preview.afterNet);
        assertEquals(change, preview.change);
        long before = engine.metrics(NOW).net;
        assertTrue(engine.correctEntries(List.of(target.id()), Correction.IGNORE));
        assertEquals(after, engine.metrics(NOW).net);
        assertTrue(engine.undoCorrection());
        assertEquals("Undo restores the original saturated total", before, engine.metrics(NOW).net);
    }

    @Test public void singleRemovalUsesTheRealAfterTotalWithSaturatedGains() {
        var engine = ReviewFixesTest.engine();
        book(engine, 536, 2_000_000_000L, FOUR_E18, false);
        book(engine, 537, 2_000_000_000L, FOUR_E18, false);
        var target = book(engine, 538, 2_000_000_000L, FOUR_E18, false);
        remove(engine, target, 8_000_000_000_000_000_000L, -1_223_372_036_854_775_807L);
    }

    @Test public void singleRemovalUsesTheRealAfterTotalWithSaturatedCosts() {
        var engine = ReviewFixesTest.engine();
        book(engine, 536, -2_000_000_000L, -FOUR_E18, false);
        book(engine, 537, -2_000_000_000L, -FOUR_E18, false);
        var target = book(engine, 538, -2_000_000_000L, -FOUR_E18, false);
        remove(engine, target, -8_000_000_000_000_000_000L, 1_223_372_036_854_775_807L);
    }

    @Test public void singleRemovalFoldsIncomeAndCostsSeparatelyBeforeTakingNet() {
        var engine = ReviewFixesTest.engine();
        book(engine, 536, 1, Long.MAX_VALUE - 100, false);
        var target = book(engine, 537, 3, 300, false);
        book(engine, 995, -1, -50, false);
        remove(engine, target, Long.MAX_VALUE - 150, -100);
    }

    @Test public void removalIncludesCompactedContributions() {
        var engine = ReviewFixesTest.engine();
        book(engine, 536, 1, Long.MAX_VALUE - 100, false);
        engine.session().evict(1);
        var target = book(engine, 537, 3, 300, false);
        remove(engine, target, Long.MAX_VALUE - 100, -100);
    }

    private static void split(boolean compacted) {
        var engine = ReviewFixesTest.engine();
        book(engine, 536, 1, Long.MAX_VALUE - 100, false);
        if (compacted) engine.session().evict(1);
        var target = book(engine, 537, 3, 300, false);
        var preview = readOnly(engine, () -> LedgerData.splitPreview(engine, target.id(), 537, 1, NOW));
        assertEquals(Long.MAX_VALUE, preview.afterNet);
        assertEquals("reducing one receipt need not reduce saturated Net", 0, preview.change);
        assertTrue(engine.splitItem(target.id(), 537, 1, "Saturation regression"));
        assertEquals(preview.afterNet, engine.metrics(NOW).net);
        assertEquals(1, target.quantity(537, true));
        assertTrue(engine.undoCorrection());
        assertEquals(3, target.quantity(537, true));
        assertEquals(Long.MAX_VALUE, engine.metrics(NOW).net);
    }

    @Test public void splitUsesTheRealAfterTotal() { split(false); }
    @Test public void splitIncludesCompactedContributions() { split(true); }

    private static void decide(boolean compacted, boolean cost) {
        var engine = ReviewFixesTest.engine();
        book(engine, 536, cost ? -1 : 1, cost ? -Long.MAX_VALUE + 100 : Long.MAX_VALUE - 100, false);
        if (compacted) engine.session().evict(1);
        var target = book(engine, 537, 1, 200, true);
        var unselected = book(engine, 538, 1, 300, true);
        var preview = readOnly(engine, () -> engine.previewDecision(cost ? Decision.COST : Decision.GAIN,
                row -> row.transaction.equals(target.id()), NOW));
        assertEquals(List.of(target.id()), preview.transactionIds);
        assertEquals(cost ? -100 : 100, preview.netDelta);
        int undoUnits = engine.session().correctionHistory.size();
        assertEquals(1, engine.applyDecision(preview));
        assertEquals(cost ? -Long.MAX_VALUE : Long.MAX_VALUE, engine.metrics(NOW).net);
        assertEquals(Correction.AUTO, unselected.correction());
        assertEquals(undoUnits + 1, engine.session().correctionHistory.size());
        assertTrue(engine.undoCorrection());
        assertEquals(Correction.AUTO, target.correction());
        assertEquals(cost ? -Long.MAX_VALUE + 100 : Long.MAX_VALUE - 100, engine.metrics(NOW).net);
    }

    @Test public void decideAllUsesTheRealGainChangeAndKeepsScopeAndUndo() { decide(false, false); }
    @Test public void decideAllUsesTheRealCostChange() { decide(false, true); }
    @Test public void decideAllIncludesCompactedContributions() { decide(true, false); }

    @Test public void aPreviewChangeAcrossTheSignedRangeSaturatesInsteadOfWrapping() {
        assertEquals(Long.MAX_VALUE, new LedgerData.CorrectionPreview(-Long.MAX_VALUE, Long.MAX_VALUE, 0).change);
        assertEquals(Long.MIN_VALUE, new LedgerData.CorrectionPreview(Long.MAX_VALUE, -Long.MAX_VALUE, 0).change);
    }

    @Test public void missingRowsAndEmptyDecisionScopesKeepNetAndRevision() {
        var engine = ReviewFixesTest.engine();
        book(engine, 536, 1, 300, false);
        var missing = readOnly(engine, () -> LedgerData.preview(engine, "missing", Correction.IGNORE, NOW));
        assertEquals(300, missing.afterNet);
        assertEquals(0, missing.change);
        var split = readOnly(engine, () -> LedgerData.splitPreview(engine, "missing", 536, 1, NOW));
        assertEquals(300, split.afterNet);
        var empty = readOnly(engine, () -> engine.previewDecision(Decision.GAIN, row -> false, NOW));
        assertEquals(0, empty.rowCount());
        assertEquals(0, empty.netDelta);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class CostKindTest
{
    @Test
    public void classifiesSupplyLossAndMarketFromEffectiveCountedFlows()
    {
        assertEquals(CostKind.SUPPLIES, kind(TransactionType.CONSUMPTION, "Eating", 7, -100L));
        // A decrease nobody evidenced (no action kind) is an item gone: a loss, never a supply.
        assertEquals(CostKind.LOSS, kind(TransactionType.CONSUMPTION, "Unexplained", 7, -100L));
        assertEquals(CostKind.SUPPLIES, kind(TransactionType.PROCESSING, "Herblore", 7, -100L));
        assertEquals(CostKind.SUPPLIES, kind(TransactionType.PK_SUPPLY_COST, "PKing", 7, -100L));
        assertEquals(CostKind.LOSS, kind(TransactionType.PK_DEATH_LOSS, "PKing", 7, -100L));
        // The death-reclaim fee is a plain typed consumption; the label is not the authority.
        assertEquals(CostKind.LOSS, kind(TransactionType.CONSUMPTION, "Death reclaim", 7, -100L));
        assertEquals(CostKind.MARKET, kind(TransactionType.TRADE, "GE buy", 7, -100L));
    }

    /** Owner 1.1: burying, scattering and offering are Supplies, like eating; never a loss. */
    @Test
    public void buryScatterAndOfferAreSupplies()
    {
        for (ActionKind kind : new ActionKind[] {ActionKind.BURY, ActionKind.SCATTER, ActionKind.OFFER})
        {
            Transaction spend = transaction(TransactionType.CONSUMPTION, "Prayer", 526, -100L);
            spend.setAction(kind);
            assertEquals(kind.name(), CostKind.SUPPLIES, CostKind.of(spend, spend.flows().get(0)));
        }
    }

    @Test
    public void actionTaxAndCorrectionsUseEffectiveContribution()
    {
        Transaction action = transaction(TransactionType.GAIN, "General", 7, -100L);
        action.setAction(ActionKind.EAT);
        assertEquals(CostKind.SUPPLIES, CostKind.of(action, action.flows().get(0)));

        Transaction tax = transaction(TransactionType.ADJUSTMENT, "GE", CostKind.GE_TAX_ITEM_ID, -100L);
        assertEquals(CostKind.LOSS, CostKind.of(tax, tax.flows().get(0)));

        Transaction corrected = transaction(TransactionType.LOOT, "Loot", 7, 100L);
        corrected.applyCorrection(Correction.COST, "Owner correction");
        assertEquals(CostKind.LOSS, CostKind.of(corrected, corrected.flows().get(0)));
        corrected.applyCorrection(Correction.IGNORE, "Owner exclusion");
        assertEquals(CostKind.NONE, CostKind.of(corrected, corrected.flows().get(0)));
    }

    @Test
    public void presentationTextNeverSelectsTheCategory()
    {
        // A tax-looking explanation cannot reclassify a typed trade.
        Transaction annotated = transaction(TransactionType.TRADE, "GE buy", 7, -100L);
        annotated.setExplanation("Grand Exchange collect. GE tax 2% (capped).");
        assertEquals(CostKind.MARKET, CostKind.of(annotated, annotated.flows().get(0)));

        // A death-reclaim activity label cannot reclassify a typed trade either.
        assertEquals(CostKind.MARKET, kind(TransactionType.TRADE, "Death reclaim", 7, -100L));

        // A typed action kind, not a tax-looking label, selects Supplies.
        Transaction labelled = transaction(TransactionType.CONSUMPTION, "ge tax 2% (capped)", 7, -100L);
        labelled.setAction(ActionKind.EAT);
        assertEquals("a typed action kind, not the label, selects Supplies",
            CostKind.SUPPLIES, CostKind.of(labelled, labelled.flows().get(0)));

        // A free-form owner reason cannot manufacture a tax category on a market movement.
        Transaction reasonTax = transaction(TransactionType.TRADE, "GE", 7, -100L);
        reasonTax.applyCorrection(Correction.COST, "GE tax settlement");
        assertEquals(CostKind.MARKET, CostKind.of(reasonTax, reasonTax.flows().get(0)));

        // The synthetic tax flow id remains the typed tax authority whatever the label says.
        assertEquals(CostKind.LOSS, kind(TransactionType.ADJUSTMENT, "anything", CostKind.GE_TAX_ITEM_ID, -100L));
    }

    @Test
    public void uncountedTransfersAndDeferredClaimsAreNotCostKinds()
    {
        Transaction transfer = transaction(TransactionType.TRANSFER, "Bank", 7, -100L);
        assertEquals(CostKind.NONE, CostKind.of(transfer, transfer.flows().get(0)));

        Transaction uncounted = Tx.of(1L, TransactionType.CONSUMPTION,
            Context.GENERIC, "review", false,
            Collections.singletonList(new Flow(7, "Food", -1L, 100, -100L)));
        assertEquals(CostKind.NONE, CostKind.of(uncounted, uncounted.flows().get(0)));

        Transaction deferred = transaction(TransactionType.CONSUMPTION, "Chest", 7, -100L);
        deferred.setAction(ActionKind.DEFERRED_CLAIM);
        assertEquals(CostKind.NONE, CostKind.of(deferred, deferred.flows().get(0)));
    }

    @Test
    public void typedCategoryIsDeterministicAcrossSerialization()
    {
        com.google.gson.Gson gson = new com.google.gson.Gson();
        Transaction tax = transaction(TransactionType.ADJUSTMENT, "GE", CostKind.GE_TAX_ITEM_ID, -100L);
        Transaction trade = transaction(TransactionType.TRADE, "GE buy", 7, -100L);
        Transaction fee = transaction(TransactionType.CONSUMPTION, "Death reclaim", 7, -100L);

        Transaction restoredTax = gson.fromJson(gson.toJson(tax), Transaction.class);
        Transaction restoredTrade = gson.fromJson(gson.toJson(trade), Transaction.class);
        Transaction restoredFee = gson.fromJson(gson.toJson(fee), Transaction.class);

        assertEquals(CostKind.LOSS, CostKind.of(restoredTax, restoredTax.flows().get(0)));
        assertEquals(CostKind.MARKET, CostKind.of(restoredTrade, restoredTrade.flows().get(0)));
        assertEquals("a legacy reclaim fee row stays a typed loss after reload",
            CostKind.LOSS, CostKind.of(restoredFee, restoredFee.flows().get(0)));
    }

    private static CostKind kind(TransactionType type, String activity, int itemId, long value)
    {
        Transaction transaction = transaction(type, activity, itemId, value);
        return CostKind.of(transaction, transaction.flows().get(0));
    }

    private static Transaction transaction(TransactionType type, String activity,
        int itemId, long value)
    {
        Transaction transaction = Tx.of(1L, null, type, Context.GENERIC,
            activity, activity, true,
            Collections.singletonList(new Flow(itemId, "Item", value >= 0 ? 1L : -1L,
                (int) Math.min(Integer.MAX_VALUE, Math.abs(value)), value)));
        if ("Eating".equals(activity)) transaction.setAction(ActionKind.EAT);
        return transaction;
    }
}

package com.gpmanager;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class CustodyTrimContractTest {
    private static final long NOW = 1_700_000_000_000L;
    private static final int ITEM = 1203;

    @Test public void aNullSinkOwnerStillCannotBorrowAnotherReviewsFence() {
        var basis = new TrackedBasisLedger();
        basis.epoch = NOW;
        basis.fenceRealized(ITEM, NOW + 1, "its-review");
        var gson = new com.google.gson.Gson();
        String before = gson.toJson(basis.stock);
        assertFalse(basis.canIntroduceSink(Map.of(), Map.of(ITEM, 1L), NOW + 1, null));
        assertTrue(basis.canIntroduceSink(Map.of(), Map.of(ITEM, 1L), NOW + 1, "its-review"));
        assertFalse(basis.canIntroduceSink(Map.of(ITEM, 1L), Map.of(ITEM, 2L), NOW + 1, "its-review"));
        assertFalse(basis.canIntroduceSink(Map.of(), Map.of(), NOW + 1, null));
        assertEquals(before, gson.toJson(basis.stock));
    }

    private static GeOffer record(GeOffer.Side side) {
        var row = new GeOffer("audit-offer", 0, side, ITEM, "Iron dagger", 2, 150, NOW, "origin");
        row.offerState = side == GeOffer.Side.SELL ? "SOLD" : "BOUGHT";
        row.filledQty = row.settledQty = row.collectedQty = row.capturedQty = 2;
        row.reserveGp = row.spentGp = 300;
        return row;
    }

    @Test public void sellRetirementRequiresNoPendingFillOrHeldItemsAndATerminalState() {
        var row = record(GeOffer.Side.SELL);
        assertTrue(row.reconciled());
        row.settledQty = 1;
        assertFalse(row.reconciled());
        row.settledQty = 2;
        row.capturedQty = 3;
        assertFalse(row.reconciled());
        row.capturedQty = 2;
        row.offerState = "SELLING";
        assertFalse(row.reconciled());
        row.cleared = true;
        assertTrue(row.reconciled());
        row.capturedQty = 3;
        assertFalse(row.reconciled());
    }

    @Test public void buyRetirementRequiresCollectedItemsAndReturnedChange() {
        var row = record(GeOffer.Side.BUY);
        assertTrue(row.reconciled());
        row.collectedQty = 1;
        assertFalse(row.reconciled());
        row.collectedQty = 2;
        row.reserveGp = 320;
        assertFalse(row.reconciled());
        row.refundedGp = 20;
        assertTrue(row.reconciled());
        row.offerState = null;
        assertFalse(row.reconciled());
        row.cleared = true;
        assertTrue(row.reconciled());
        row.side = null;
        assertTrue(row.reconciled());
        row.reserveGp = row.spentGp = Long.MAX_VALUE;
        row.refundedGp = 0;
        assertTrue(row.reconciled());
    }

    @Test public void numericMapFactoriesPreserveConcreteTypesOrderAndIndependentOwnership() {
        var engine = PreEpochReceiptRestoreTest.engine();
        assertEquals(HashMap.class, engine.stored.getClass());
        assertEquals(HashMap.class, engine.reward.getClass());
        assertEquals(HashMap.class, engine.bag.getClass());
        assertEquals(HashMap.class, engine.contents.getClass());
        assertEquals(HashMap.class, engine.death.items.getClass());
        assertEquals(HashMap.class, engine.raids.state.supplies.getClass());
        engine.stored.put(ITEM, 1L);
        assertTrue(engine.reward.isEmpty());
        assertTrue(engine.bag.isEmpty());
        assertTrue(engine.contents.isEmpty());
        var ordered = Phrases.orderedNumberMap();
        assertEquals(LinkedHashMap.class, ordered.getClass());
        ordered.put(2, 1L);
        ordered.put(1, 1L);
        assertEquals(List.of(2, 1), List.copyOf(ordered.keySet()));
        assertTrue(Phrases.orderedNumberMap().isEmpty());
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Release pass 2026-09-28: the dose pairing (a sip books one dose, never a gain plus a whole potion)
 * must agree everywhere money is read. For generated sips, bites, decants, mixed loot and corrected
 * rows: the per-flow amounts add up to the transaction amounts, Net stays the raw flow sum, the cost
 * split covers the costs, and the Ledger contributions add up to the same Net.
 */
public class DosePairingInvariantTest
{
    private static final String[] POTIONS = {"Prayer potion", "Super defence", "Saradomin brew"};
    private static final ActionKind[] ACTIONS = {ActionKind.DRINK, ActionKind.EAT, ActionKind.SUPPLIES, null};
    private static final Correction[] CORRECTIONS = {Correction.AUTO, Correction.AUTO,
        Correction.AUTO, Correction.COST, Correction.REVENUE, Correction.IGNORE};

    @Test
    public void everyReaderAgreesOnGeneratedConsumption()
    {
        Random random = new Random(20260928L);
        int paired = 0;
        for (int i = 0; i < 2_000; i++)
        {
            Transaction transaction = generated(random, i);
            Accounting.Amounts total = Accounting.transaction(transaction);
            if (!total.included)
            {
                continue;
            }
            long revenue = 0L;
            long costs = 0L;
            long raw = 0L;
            for (Flow flow : transaction.flows())
            {
                Accounting.Amounts amounts = Accounting.flow(transaction, flow);
                revenue += amounts.income;
                costs += amounts.cost;
                raw += flow.value;
            }
            String where = "case " + i + " " + transaction.flows();
            assertEquals(where, total.income, revenue);
            assertEquals(where, total.cost, costs);
            if (transaction.correction() == Correction.AUTO)
            {
                assertEquals("Net stays the raw flow sum: " + where, raw, total.net());
            }
            Accounting.CostSplit split = Accounting.costSplit(transaction);
            if (split.available)
            {
                assertEquals("the split covers the costs: " + where, total.cost, split.supplies + split.other);
            }
            long ledger = 0L;
            for (Contribution contribution : Contribution.project(transaction))
            {
                ledger += contribution.value;
            }
            assertEquals("the Ledger adds up to Net: " + where, total.net(), ledger);
            if (!Accounting.consumePairs(transaction).isEmpty())
            {
                paired++;
            }
        }
        assertTrue("the generator exercises dose pairs (" + paired + ")", paired > 200);
    }

    private static Transaction generated(Random random, int i)
    {
        List<Flow> flows = new ArrayList<>();
        String potion = POTIONS[random.nextInt(POTIONS.length)];
        int dose = 1 + random.nextInt(4);
        int unit = 500 + random.nextInt(3_000);
        long sips = 1 + random.nextInt(3);
        switch (random.nextInt(5))
        {
            case 0:
                // A sip: (n) -> (n-1), or (1) -> vial or nothing.
                flows.add(new Flow(1_000 + dose, potion + "(" + dose + ")", -sips, unit * dose, -sips * unit * dose));
                if (dose > 1)
                {
                    flows.add(new Flow(1_000 + dose - 1, potion + "(" + (dose - 1) + ")", sips, unit * (dose - 1),
                        sips * unit * (dose - 1)));
                }
                else if (random.nextBoolean())
                {
                    flows.add(new Flow(229, "Vial", sips, 3, sips * 3));
                }
                break;
            case 1:
                // A bite of a pie.
                flows.add(new Flow(2327, "Meat pie", -1L, 40, -40L));
                flows.add(new Flow(2331, "Half a meat pie", 1L, 18, 18L));
                break;
            case 2:
                // A decant: two (2) become one (4); doses are conserved.
                flows.add(new Flow(1_002, potion + "(2)", -2L, unit * 2, -4L * unit));
                flows.add(new Flow(1_004, potion + "(4)", 1L, unit * 4, 4L * unit));
                flows.add(new Flow(229, "Vial", 1L, 3, 3L));
                break;
            case 3:
                // A sip settled together with a pickup.
                flows.add(new Flow(1_000 + dose, potion + "(" + dose + ")", -1L, unit * dose, -(long) unit * dose));
                if (dose > 1)
                {
                    flows.add(new Flow(1_000 + dose - 1, potion + "(" + (dose - 1) + ")", 1L, unit * (dose - 1),
                        (long) unit * (dose - 1)));
                }
                flows.add(new Flow(536, "Dragon bones", 1L + random.nextInt(3), 2_000, 2_000L * (1 + random.nextInt(3))));
                break;
            default:
                // A price that fell between the sip's two legs (the remainder worth more than the loss).
                flows.add(new Flow(1_002, potion + "(2)", -1L, unit, -unit));
                flows.add(new Flow(1_001, potion + "(1)", 1L, unit * 2, unit * 2L));
                break;
        }
        TransactionType type = random.nextInt(4) == 0 ? TransactionType.LOOT : TransactionType.CONSUMPTION;
        Transaction transaction = new Transaction(1_000L + i, type, Context.GENERIC, "",
            "Vorkath", true, flows, Confidence.LIKELY, "fixture", null);
        transaction.setAction(ACTIONS[random.nextInt(ACTIONS.length)]);
        Correction correction = CORRECTIONS[random.nextInt(CORRECTIONS.length)];
        if (correction != Correction.AUTO)
        {
            transaction.applyCorrection(correction, "Manual correction");
        }
        return transaction;
    }
}

