package com.gpmanager;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.AccessDeniedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.TimeUnit;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

/** The actual Windows failure from the soak: two immediate atomic renames can both be denied. */
public class AtomicSaveRetryTest {
    @Rule public TemporaryFolder temporary = new TemporaryFolder();
    static final Duration TIMEOUT = Duration.ofSeconds(5);

    static class Denials extends SessionRepository {
        int remaining, attempts;
        Denials(Path directory) { super(new Gson(), FilepathTestSupport.root(directory), false); }
        @Override void atomicMove(Filepath source, Filepath target) throws IOException {
            if (target.getFileName().toString().equals("sessions.json")) {
                attempts++;
                if (remaining > 0) {
                    remaining--;
                    throw new AccessDeniedException(source.toString(), target.toString(), "Injected Windows denial");
                }
            }
            super.atomicMove(source, target);
        }
    }

    static class Writer extends OrderedPersistenceWriter {
        final List<Long> waits = new CopyOnWriteArrayList<>();
        Writer(SessionRepository repository) { super(repository); resetRevision(repository.revision); }
        @Override boolean retryLater(long millis) {
            waits.add(millis);
            return super.retryLater(millis);
        }
        void close() throws InterruptedException {
            shutdown(TIMEOUT);
            if (executor != null) assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
        }
    }

    @Test public void deniedImmediateMovesRetryThroughTheProductionSchedulerAndCommitOnce() throws Exception {
        Path directory = temporary.newFolder().toPath();
        var repository = new Denials(directory);
        PrimaryReadFailureTest.seed(repository);
        long base = repository.revision;
        repository.attempts = 0;
        repository.remaining = 2;
        var writer = new Writer(repository);
        try {
            assertTrue(writer.submit(new WriteIntent(null, repository.generation, base,
                    PrimaryReadFailureTest.money(4_650), null)));
            assertTrue("only a committed snapshot acknowledges durability", writer.flush(TIMEOUT));
            assertEquals(List.of(50L), writer.waits);
            assertEquals(3, repository.attempts);
            assertEquals(base + 1, writer.appliedRevision());
            var restored = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false).load();
            assertEquals(base + 1, restored.revision);
            assertEquals(4_650, FixtureReads.currentSession(restored).metrics(20_000L).net);
            assertEquals(4_550, FixtureReads.currentSession(restored).compactedTransactionCount);
        } finally { writer.close(); }
    }

    @Test public void persistentDenialExhaustsTheRealBoundWithoutAcknowledgingOrReplacingTheSave() throws Exception {
        Path directory = temporary.newFolder().toPath();
        var repository = new Denials(directory);
        PrimaryReadFailureTest.seed(repository);
        byte[] primary = Files.readAllBytes(directory.resolve("sessions.json"));
        long base = repository.revision;
        repository.attempts = 0;
        repository.remaining = 6;
        var writer = new Writer(repository);
        try {
            assertTrue(writer.submit(new WriteIntent(null, repository.generation, base,
                    PrimaryReadFailureTest.money(4_650), null)));
            assertFalse(writer.flush(TIMEOUT));
            assertEquals(List.of(50L, 200L), writer.waits);
            assertEquals("two rename calls per each of the three attempts", 6, repository.attempts);
            assertEquals(base, repository.revision);
            assertEquals(base, writer.appliedRevision());
            assertArrayEquals(primary, Files.readAllBytes(directory.resolve("sessions.json")));
            assertEquals(4_600, FixtureReads.currentSession(repository.load()).metrics(20_000L).net);
        } finally { writer.close(); }
    }
}

package com.gpmanager;

import java.nio.file.Files;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Review 2026-10-09: "Back up profile" holds the persistence lock while it writes; the game thread's
 * readiness check must answer at once from its last result instead of waiting behind the disk.
 */
public class BackupNoStallTest
{
    @Test
    public void aBackupHoldingTheLockNeverStallsTheGameThread() throws Exception
    {
        SessionRepository repository = new SessionRepository(new com.google.gson.Gson(),
            FilepathTestSupport.root(Files.createTempDirectory("gp-busy")), false);
        Persistence persistence = new Persistence(null, null, repository, new OrderedPersistenceWriter(repository, null), null);
        persistence.okay = true;
        CountDownLatch held = new CountDownLatch(1);
        CountDownLatch release = new CountDownLatch(1);
        Thread backup = new Thread(() ->
        {
            persistence.busy = true;
            synchronized (persistence)
            {
                held.countDown();
                try
                {
                    release.await(5, TimeUnit.SECONDS);
                }
                catch (InterruptedException ignored)
                {
                    Thread.currentThread().interrupt();
                }
            }
            persistence.busy = false;
        });
        backup.start();
        assertTrue(held.await(5, TimeUnit.SECONDS));
        long started = System.nanoTime();
        assertEquals("the last answer, not a wait", true, persistence.isTrackingReady());
        assertTrue("answered at once", System.nanoTime() - started < TimeUnit.MILLISECONDS.toNanos(500));
        release.countDown();
        backup.join(5_000);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.stream.Stream;
import net.runelite.api.Client;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Charter section 14/15 interruption classes for the save/replace/restore commit protocol: every
 * crash point resolves to exactly one of "old valid state untouched" or "new valid state committed
 * and finished idempotently on the next load". Never a mix.
 */
public class CommitInterruptionTest
{
    private static final String PROFILE = "rsprofile.interrupt";
    private static final TrackingIdentity IDENTITY = new TrackingIdentity(PROFILE, TrackingIdentity.ACCOUNT_HASH_INVALID);
    private static final long NOW = 1_800_000_000_000L;

    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    private static SavedState named(String name, long revision)
    {
        SavedState state = new SavedState(new Session(name, 1_000L, SessionMode.GENERAL), null, Collections.emptyList());
        state.setRevision(revision);
        return state;
    }

    private static SessionRepository bound(Path root)
    {
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true);
        repository.bindIdentity(IDENTITY);
        return repository;
    }

    /** A repository that fails the first replace whose target file has {@code failingTarget}'s name. */
    private static SessionRepository failingAt(Path root, String failingTarget)
    {
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true)
        {
            @Override
            void replaceFile(Filepath source, Filepath target) throws IOException
            {
                if (target.getFileName().toString().equals(failingTarget))
                {
                    throw new IOException("Simulated crash replacing " + failingTarget);
                }
                super.replaceFile(source, target);
            }
        };
        repository.bindIdentity(IDENTITY);
        return repository;
    }

    private static String primary(SessionRepository repository) throws IOException
    {
        return Files.readString(FilepathTestSupport.path(repository.dataDir().joinSegment("sessions.json")), StandardCharsets.UTF_8);
    }

    private static String activeName(SessionRepository repository)
    {
        return FixtureReads.currentSession(repository.load()).name();
    }

    @Test
    public void crashBeforeThePrimaryIsReplacedLeavesTheOldStateAndRecoversCleanly() throws Exception
    {
        for (String crashPoint : new String[] {"sessions.backup.json", "sessions.json"})
        {
            Path root = temporary.newFolder().toPath();
            SessionRepository good = bound(root);
            assertTrue(PersistenceProbe.save(good, named("Old", 1L)));
            String before = primary(good);

            SessionRepository failing = failingAt(root, crashPoint);
            failing.load();
            assertFalse(crashPoint, failing.save(new WriteIntent(IDENTITY, failing.generation, 1L, named("New", 2L), null)));

            // Old valid state, byte-identical primary; the next load sees exactly that.
            SessionRepository reload = bound(root);
            assertEquals(crashPoint, "Old", activeName(reload));
            assertEquals(crashPoint, before, primary(reload));
            assertEquals(1L, reload.revision);
            assertEquals("", reload.recovery);

            // Recovery finishes idempotently: the next save advances from the old lineage and
            // leaves no staged leftovers behind.
            assertTrue(reload.save(new WriteIntent(IDENTITY, reload.generation, 1L, named("After", 2L), null)));
            assertEquals("After", activeName(bound(root)));
            assertFalse(reload.dataDir().joinSegment("sessions.commit.stage").exists());
            assertFalse(reload.dataDir().joinSegment("sessions.next.json").exists());
        }
    }

    @Test
    public void renameFallbackStillCommitsOnlyValidatedFilesAndLeavesNoTemporaries() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        SessionRepository noAtomic = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true)
        {
            @Override
            void atomicMove(Filepath source, Filepath target) throws IOException
            {
                throw new java.nio.file.AtomicMoveNotSupportedException(source.toString(), target.toString(), "simulated volume");
            }
        };
        noAtomic.bindIdentity(IDENTITY);
        assertTrue(PersistenceProbe.save(noAtomic, named("First", 1L)));
        assertTrue(PersistenceProbe.save(noAtomic, named("Second", 2L)));
        assertTrue(noAtomic.replaceStateDetailed(new WriteIntent(IDENTITY, noAtomic.generation, 2L, named("Reset", 3L), null)).isCommitted());
        assertEquals("Reset", activeName(bound(root)));
        try (Stream<Path> files = Files.list(FilepathTestSupport.path(noAtomic.dataDir())))
        {
            assertTrue(files.map(path -> path.getFileName().toString()).noneMatch(name -> name.endsWith(".tmp")));
        }
    }

    @Test
    public void aCorruptPrimaryFallsBackToTheCrashCopyAndReportsWhereFrom() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        SessionRepository repository = bound(root);
        assertTrue(PersistenceProbe.save(repository, named("One", 1L)));
        assertTrue(PersistenceProbe.save(repository, named("Two", 2L)));
        assertTrue(PersistenceProbe.save(repository, named("Three", 3L)));
        Path dir = FilepathTestSupport.path(repository.dataDir());
        assertEquals("one crash copy, no rotation (owner 2026-09-28)", 0, PersistenceProbe.rotatedBackupCount(repository));
        Files.writeString(dir.resolve("sessions.json"), "{not json", StandardCharsets.UTF_8);

        SessionRepository reload = bound(root);
        assertEquals("Two", activeName(reload));
        assertEquals("sessions.backup.json", reload.recovery);
        assertEquals(2L, reload.revision);
        try (Stream<Path> files = Files.list(dir))
        {
            assertTrue("the corrupt primary is preserved as evidence",
                files.map(path -> path.getFileName().toString()).anyMatch(name -> name.startsWith("sessions.corrupt-")));
        }
        // The next save continues from the recovered lineage.
        assertTrue(reload.save(new WriteIntent(IDENTITY, reload.generation, 2L, named("Four", 3L), null)));
        assertEquals("Four", activeName(bound(root)));
        assertEquals("", bound(root).recovery);
    }

    private static Client client()
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (proxy, method, args) -> {
                if (method.getName().equals("getAccountHash")) return 77L;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return false;
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                return null;
            });
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.AbstractExecutorService;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * 1.7.0 durability: a save is acknowledged only once its snapshot (or a newer one of the same
 * scope generation) committed. Up to three attempts per accepted snapshot, 50 and 200 ms apart on
 * the writer's own worker; an exhausted snapshot stays queued for a newer snapshot, a retry or a
 * restart, and lifecycle steps that would replace the owner wait for that acknowledgement.
 * Retry waits go through the writer's retry seam, so no test sleeps through them.
 */
public class DurableSaveAckTest
{
    private static final TrackingIdentity ALICE = new TrackingIdentity("rsprofile.alice", -1L);
    private static final TrackingIdentity BOB = new TrackingIdentity("rsprofile.bob", -1L);

    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    /** Fails the next {@code failures} ordinary saves without touching disk; counts every attempt. */
    private static class FlakyRepository extends SessionRepository
    {
        final AtomicInteger failures = new AtomicInteger();
        final AtomicInteger calls = new AtomicInteger();

        FlakyRepository(Path root)
        {
            super(new Gson(), FilepathTestSupport.root(root), true);
        }

        @Override
        synchronized boolean save(WriteIntent intent)
        {
            calls.incrementAndGet();
            if (failures.get() > 0)
            {
                failures.decrementAndGet();
                return false;
            }
            return super.save(intent);
        }
    }

    private static final class Rig
    {
        final Path root;
        final FlakyRepository repository;
        final List<Long> pauses = Collections.synchronizedList(new ArrayList<>());
        final OrderedPersistenceWriter writer;
        final Engine engine = new Engine(d -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig() {});
        volatile TrackingIdentity who = ALICE;
        final Persistence coordinator;

        Rig(Path root)
        {
            this(root, null, false);
        }

        Rig(Path root, boolean production)
        {
            this(root, null, production);
        }

        Rig(Path root, java.util.concurrent.ExecutorService executor)
        {
            this(root, executor, false);
        }

        Rig(Path root, java.util.concurrent.ExecutorService executor, boolean production)
        {
            this.root = root;
            repository = new FlakyRepository(root);
            writer = production ? new OrderedPersistenceWriter(repository)
                : executor == null ? new PausingWriter(repository, pauses)
                : new PausingWriter(repository, executor, pauses);
            coordinator = new Persistence(null, null, repository, writer, engine)
            {
                @Override
                TrackingIdentity resolveCurrentIdentity()
                {
                    return who;
                }
            };
            JsonCodec.bind(new Gson());
        }

        void seed(String name)
        {
            assertTrue(coordinator.switchIdentity(ALICE, true));
            engine.ensureSession(1_000L);
            engine.session().rename(name);
            assertTrue(coordinator.saveNow());
        }

        String disk(TrackingIdentity owner)
        {
            return DurableSaveAckTest.disk(root, owner);
        }
    }

    static String disk(Path root, TrackingIdentity owner)
    {
        SessionRepository reader = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true);
        reader.bindIdentity(owner);
        SavedState state = reader.load();
        return FixtureReads.currentSession(state) == null ? null : FixtureReads.currentSession(state).name();
    }

    /** Records each retry delay and lets the drain reschedule immediately. */
    private static final class PausingWriter extends OrderedPersistenceWriter
    {
        final List<Long> pauses;

        PausingWriter(SessionRepository repository, List<Long> pauses)
        {
            super(repository);
            this.pauses = pauses;
        }

        PausingWriter(SessionRepository repository, java.util.concurrent.ExecutorService executor, List<Long> pauses)
        {
            super(repository, executor);
            this.pauses = pauses;
        }

        @Override // RETRY-SEAM
        boolean retryLater(long millis) // RETRY-SEAM
        { // RETRY-SEAM
            pauses.add(millis); // RETRY-SEAM
            drain(); // RETRY-SEAM
            return true; // RETRY-SEAM
        } // RETRY-SEAM
    }

    /** Runs queued writer tasks only when the test says so. */
    private static final class ManualExecutor extends AbstractExecutorService
    {
        final List<Runnable> queued = new ArrayList<>();

        @Override public synchronized void execute(Runnable command) { queued.add(command); }

        synchronized void runAll()
        {
            while (!queued.isEmpty()) queued.remove(0).run();
        }

        @Override public void shutdown() { }
        @Override public List<Runnable> shutdownNow() { return new ArrayList<>(); }
        @Override public boolean isShutdown() { return false; }
        @Override public boolean isTerminated() { return false; }
        @Override public boolean awaitTermination(long timeout, TimeUnit unit) { return true; }
    }

    @Test
    public void aFailedSaveIsNeverAcknowledgedWhileTheWarningStaysQuiet() throws Exception
    {
        Rig rig = new Rig(temporary.newFolder().toPath());
        try
        {
            rig.seed("Seed");
            rig.engine.session().rename("Unsaved");
            rig.repository.failures.set(Integer.MAX_VALUE);
            int before = rig.repository.calls.get();

            assertFalse("a failed write is not durable", rig.coordinator.saveNow());
            assertNotEquals("one failed request stays quiet", SaveStatus.State.FAILED, rig.writer.status().state);
            assertEquals("disk keeps the previous save", "Seed", rig.disk(ALICE));
            assertEquals("three attempts for the accepted snapshot", 3, rig.repository.calls.get() - before);
            assertEquals(java.util.Arrays.asList(50L, 200L), rig.pauses);
        }
        finally
        {
            rig.writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void aTransientFailureCommitsWithinTheBoundedAttemptsAndStaysQuiet() throws Exception
    {
        Rig rig = new Rig(temporary.newFolder().toPath());
        try
        {
            rig.seed("Seed");
            rig.engine.session().addTransaction(new Transaction(2_000L, TransactionType.GAIN, Context.GENERIC,
                "Coins", "", true, Collections.singletonList(new Flow(995, "Coins", 10L, 1, 10L)),
                Confidence.CONFIRMED, "fixture", null), 2_000, false);
            rig.engine.session().rename("Recovered");
            rig.repository.failures.set(2);

            assertTrue(rig.coordinator.saveNow());
            assertEquals("Recovered", rig.disk(ALICE));
            assertEquals(SaveStatus.State.OK, rig.writer.status().state);
            assertEquals(0, rig.writer.failed);
            SessionRepository reader = new SessionRepository(new Gson(), FilepathTestSupport.root(rig.root), true);
            reader.bindIdentity(ALICE);
            assertEquals("the receipt is saved once", 1, FixtureReads.currentSession(reader.load()).transactions().size());
        }
        finally
        {
            rig.writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void anExhaustedSnapshotStaysRecoverableWithoutSpinning() throws Exception
    {
        Rig rig = new Rig(temporary.newFolder().toPath());
        try
        {
            rig.seed("Seed");
            rig.engine.session().rename("Kept");
            rig.repository.failures.set(Integer.MAX_VALUE);
            int before = rig.repository.calls.get();
            assertFalse(rig.coordinator.saveNow());
            assertFalse("a second flush does not invent an acknowledgement", rig.writer.flush(Duration.ofSeconds(1)));
            assertEquals("no background spin after the bounded attempts", 3, rig.repository.calls.get() - before);

            rig.repository.failures.set(0);
            rig.writer.start();
            assertTrue("a restart retries the retained snapshot", rig.writer.flush(Duration.ofSeconds(5)));
            assertEquals("Kept", rig.disk(ALICE));
        }
        finally
        {
            rig.writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void productionSchedulerCommitsDelayedRetriesOnTheWriterWorker() throws Exception
    {
        Rig rig = new Rig(temporary.newFolder().toPath(), true);
        try
        {
            rig.seed("Seed");
            rig.engine.session().rename("Scheduled");
            int before = rig.repository.calls.get();
            rig.repository.failures.set(2);

            assertTrue(rig.coordinator.saveNow());
            assertEquals("two delayed retries then the commit", 3, rig.repository.calls.get() - before);
            assertEquals("Scheduled", rig.disk(ALICE));
            assertEquals(SaveStatus.State.OK, rig.writer.status().state);
        }
        finally
        {
            rig.writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void productionShutdownFinalizesScheduledRetriesOnItsOwnWorker() throws Exception
    {
        Rig rig = new Rig(temporary.newFolder().toPath(), true);
        try
        {
            rig.seed("Seed");
            rig.engine.session().rename("Final");
            int before = rig.repository.calls.get();
            rig.repository.failures.set(2);

            rig.coordinator.shutdown();
            assertTrue("the writer worker owns the retry window",
                rig.writer.executor.awaitTermination(5, TimeUnit.SECONDS));
            assertEquals("the final snapshot still uses both retries", 3, rig.repository.calls.get() - before);
            assertEquals("Final", rig.disk(ALICE));
            assertTrue(rig.writer.flush(Duration.ofSeconds(1)));
        }
        finally
        {
            rig.writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void aNewerSnapshotDuringAFailedWriteCoversTheOlderRequest() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        CountDownLatch entered = new CountDownLatch(1);
        CountDownLatch release = new CountDownLatch(1);
        AtomicBoolean gate = new AtomicBoolean();
        Engine engine = new Engine(d -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        JsonCodec.bind(new Gson());
        FlakyRepository gated = new FlakyRepository(root)
        {
            @Override
            synchronized boolean save(WriteIntent intent)
            {
                if (gate.compareAndSet(true, false))
                {
                    calls.incrementAndGet();
                    entered.countDown();
                    try
                    {
                        assertTrue(release.await(5, TimeUnit.SECONDS));
                    }
                    catch (InterruptedException ex)
                    {
                        throw new AssertionError(ex);
                    }
                    return false;
                }
                return super.save(intent);
            }
        };
        List<Long> pauses = Collections.synchronizedList(new ArrayList<>());
        OrderedPersistenceWriter writer = new PausingWriter(gated, pauses);
        Persistence coordinator = new Persistence(null, null, gated, writer, engine)
        {
            @Override
            TrackingIdentity resolveCurrentIdentity()
            {
                return ALICE;
            }
        };
        try
        {
            assertTrue(coordinator.switchIdentity(ALICE, true));
            engine.ensureSession(1_000L);
            engine.session().rename("Seed");
            assertTrue(coordinator.saveNow());

            engine.session().rename("Older");
            gate.set(true);
            coordinator.scheduleSave();
            assertTrue(entered.await(5, TimeUnit.SECONDS));
            boolean[] olderAcknowledged = {false};
            Thread waiter = new Thread(() -> olderAcknowledged[0] = writer.flush(Duration.ofSeconds(5)));
            waiter.start();
            engine.session().rename("Newer");
            coordinator.scheduleSave();
            release.countDown();
            waiter.join(10_000L);
            assertFalse(waiter.isAlive());

            assertTrue("the newer same-owner snapshot covers the older watermark", olderAcknowledged[0]);
            assertTrue(writer.flush(Duration.ofSeconds(5)));
            assertEquals("only the latest state is committed", "Newer", disk(root, ALICE));
            assertEquals("a superseded failure is not retried", Collections.emptyList(), pauses);
        }
        finally
        {
            writer.shutdown(Duration.ofSeconds(5));
        }
    }

