package com.gpmanager;

import com.google.gson.Gson;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Collections;
import java.util.List;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.*;

/** Owner 2026-09-28: backups in their own folder, newest 10 per account, clearable and restorable. */
public class ProfileBackupsTest
{
    private static final TrackingIdentity ALICE = new TrackingIdentity("rsprofile.alice", -1L);
    private static final long T0 = 1_700_000_000_000L;
    @Rule public TemporaryFolder temporary = new TemporaryFolder();

    @Test
    public void backupsKeepTenClearToOneAndRestoreWithASafetyCopy() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        Engine engine = new Engine(d -> Collections.emptyList(),
            new TransactionClassifier(), new GpManagerConfig() {});
        Persistence coordinator = new Persistence(null, null, repository, writer, engine)
        {
            @Override TrackingIdentity resolveCurrentIdentity() { return ALICE; }
        };
        try
        {
            JsonCodec.bind(new Gson());
            assertTrue(coordinator.switchIdentity(ALICE, true));
            engine.ensureSession(1_000L);
            engine.session().rename("Before restore");
            assertTrue(coordinator.saveNow());

            Filepath first = coordinator.writeBackup(T0);
            assertEquals("backups", first.getParent().getFileName());
            assertTrue(first.getFileName().startsWith("rsprofile.alice-"));
            for (int i = 1; i <= 11; i++)
            {
                coordinator.writeBackup(T0 + i * 1_000L);
            }
            List<Filepath> kept = coordinator.backups();
            assertEquals("only the newest 10 per account are kept", 10, kept.size());
            assertFalse("the oldest went first", kept.contains(first));


            assertEquals(9, coordinator.pruneBackups(1));
            assertEquals(1, coordinator.backups().size());
        }
        finally { writer.shutdown(Duration.ofSeconds(5)); }
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.nio.file.Files;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/** Full and quick saves capture fresh detached state; injected Gson retains its settings. */
public class QuickSaveTest
{
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void detachedSaveIsByteIdenticalUnderEveryGsonSetting() throws Exception
    {
        for (Gson gson : new Gson[] {new Gson(), new GsonBuilder().serializeNulls().create(),
            new GsonBuilder().disableHtmlEscaping().create(), new GsonBuilder().setPrettyPrinting().create()})
        {
            Engine engine = engine();
            Persistence coordinator = coordinator(gson, engine);
            assertEquals(plain(gson, engine), strip(PersistenceProbe.snapshotJson(coordinator, null, false)));
            assertEquals(plain(gson, engine), strip(PersistenceProbe.snapshotJson(coordinator, null, true)));
        }
    }

    @Test
    public void emptyHistoryAndNoSessionsStillMatch() throws Exception
    {
        Gson gson = new Gson();
        Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        Persistence coordinator = coordinator(gson, engine);
        assertEquals(plain(gson, engine), strip(PersistenceProbe.snapshotJson(coordinator, null, true)));
    }

    @Test
    public void quickSaveFollowsChangesThatStampTheSession() throws Exception
    {
        Gson gson = new Gson();
        Engine engine = engine();
        Persistence coordinator = coordinator(gson, engine);
        PersistenceProbe.snapshotJson(coordinator, null, false);
        Session closed = engine.history.get(1);
        String row = closed.transactions().get(3).id();
        closed.correctTransaction(row, Correction.IGNORE, "test");
        assertEquals(plain(gson, engine), strip(PersistenceProbe.snapshotJson(coordinator, null, true)));
        closed.compactBefore(closed.startedAt + 5_000L, null);
        assertEquals(plain(gson, engine), strip(PersistenceProbe.snapshotJson(coordinator, null, true)));
        Session newlyClosed = new Session("Fresh", T0, SessionMode.GENERAL);
        newlyClosed.addTransaction(receipt(T0 + 1L), 2_000, false);
        newlyClosed.close(T0 + 10L);
        engine.history.add(0, newlyClosed);
        assertEquals(plain(gson, engine), strip(PersistenceProbe.snapshotJson(coordinator, null, true)));
        engine.session().addTransaction(receipt(T0 + 2L), 2_000, false);
        assertEquals(plain(gson, engine), strip(PersistenceProbe.snapshotJson(coordinator, null, true)));
    }

    @Test
    public void everyQuickAndFullSaveCapturesClosedHistoryAfresh() throws Exception
    {
        Gson gson = new Gson();
        Engine engine = engine();
        Persistence coordinator = coordinator(gson, engine);
        coordinator.currentIntent();
        for (int quick = 1; quick <= 12; quick++)
        {
            engine.history.get(0).rename("Renamed " + quick);
            WriteIntent captured = coordinator.currentIntent();
            assertNull("encoding belongs to the writer", captured.json);
            assertEquals(plain(gson, engine), strip(gson.toJson(captured.state)));
        }
        engine.history.get(0).rename("Again");
        assertEquals(plain(gson, engine), strip(gson.toJson(coordinator.currentIntent().state)));
        assertEquals(plain(gson, engine), strip(gson.toJson(coordinator.currentIntent().state)));
    }

    private static String plain(Gson gson, Engine engine)
    {
        return strip(gson.toJson(engine.savedState()));
    }

    /** Each snapshot stamps the time, and a save's header its revision; compare the rest. */
    private static String strip(String json)
    {
        return json.replaceFirst("\"savedAtEpochMillis\": ?\\d+,\\s*\"revision\": ?\\d+,", "");
    }

    private static Engine engine()
    {
        Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        for (int grind = 0; grind < 5; grind++)
        {
            Session done = new Session("Grind <" + grind + "> & 'co'", T0 - (5 - grind) * 3_600_000L, SessionMode.GENERAL);
            for (int i = 0; i < 8; i++)
            {
                done.addTransaction(receipt(done.startedAt + i * 1_000L), 2_000, false);
            }
            done.close(done.startedAt + 30_000L);
            engine.history.add(0, done);
        }
        engine.history.add(2, null);
        engine.startCustom("Greater Nechryael", T0);
        engine.session().addTransaction(receipt(T0), 2_000, false);
        return engine;
    }

    private static Persistence coordinator(Gson gson, Engine engine) throws Exception
    {
        SessionRepository repository = new SessionRepository(gson,
            FilepathTestSupport.root(Files.createTempDirectory("gp-quick")), false);
        return new Persistence(null, null, repository, new OrderedPersistenceWriter(repository, null), engine);
    }

    private static Transaction receipt(long at)
    {
        return new Transaction(at, TransactionType.LOOT, Context.LOOT, "", "Guard", true,
            Collections.singletonList(new Flow(560, "Death rune", 46L, 187, 8_602L)), Confidence.CONFIRMED, "test", null);
    }
}

package com.gpmanager;
import com.google.gson.Gson;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Deterministic scheduler: no sleeps, real files, game client, or wall-clock timing tolerance. */
public class RetryDelayProbeTest {
    @Test public void daemonSchedulerDefaultsMatchTheRemovedRedundantSetters() {
        var executor=(ScheduledThreadPoolExecutor) OrderedPersistenceWriter.daemonExecutor("gp-manager-offline-probe");
        try {
            assertTrue(executor.getExecuteExistingDelayedTasksAfterShutdownPolicy());
            assertFalse(executor.getContinueExistingPeriodicTasksAfterShutdownPolicy());
            assertTrue(executor.getThreadFactory().newThread(() -> {}).isDaemon());
        } finally { executor.shutdown(); }
    }
    static class Scheduler extends ScheduledThreadPoolExecutor {
        final List<Runnable> delayed = new ArrayList<>();
        Scheduler() { super(1); }
        @Override public void execute(Runnable task) { task.run(); }
        @Override public ScheduledFuture<?> schedule(Runnable task,long delay,TimeUnit unit) {
            assertTrue(delay > 0); delayed.add(task); return null;
        }
        void advance() { delayed.remove(0).run(); }
    }
    static class Repository extends SessionRepository {
        int calls;
        Repository() { super(new Gson()); }
        @Override synchronized boolean save(WriteIntent intent) {
            calls++;
            if(calls == 1) return false;
            revision = intent.state.revision;
            return true;
        }
    }
    static WriteIntent intent(Repository repo,long revision) {
        var state=new SavedState();state.setRevision(revision);
        return new WriteIntent(new TrackingIdentity("rsprofile.probe",-1),repo.generation,0,state,null);
    }
    @Test public void flushDoesNotRunThePendingRetryAheadOfItsScheduledDelay() {
        var repo=new Repository();var executor=new Scheduler();var writer=new OrderedPersistenceWriter(repo,executor);
        try {
            assertTrue(writer.submit(intent(repo,1)));assertEquals(1,repo.calls);
            assertFalse(writer.flush(Duration.ZERO));
            assertEquals("flush must not bypass the scheduled retry",1,repo.calls);
            executor.advance();assertEquals(2,repo.calls);assertTrue(writer.flush(Duration.ZERO));
        } finally { executor.shutdown(); }
    }
    @Test public void queuedRetryCannotStartAfterTheShutdownRetryWindowExpired() {
        var repo=new Repository();var executor=new Scheduler();var writer=new OrderedPersistenceWriter(repo,executor);
        try {
            assertTrue(writer.submit(intent(repo,1)));
            writer.shutdown(Duration.ZERO);
            assertEquals("shutdown must not force the delayed retry early",1,repo.calls);
            executor.advance();
            assertEquals("an expired window cannot start another attempt",1,repo.calls);
            assertFalse(writer.flush(Duration.ZERO));
            assertSame(writer.merged.get(),writer.stuck);
        } finally { executor.shutdown(); }
    }
    @Test public void aNewSnapshotCoalescesWhileTheExistingDelayRemainsInForce() {
        var repo=new Repository();var executor=new Scheduler();var writer=new OrderedPersistenceWriter(repo,executor);
        try {
            assertTrue(writer.submit(intent(repo,1)));assertTrue(writer.submit(intent(repo,2)));
            assertEquals("coalescing does not bypass the existing scheduled delay",1,repo.calls);
            executor.advance();assertEquals(2,repo.calls);assertEquals(2,repo.revision);
            assertTrue(writer.flush(Duration.ZERO));
        } finally { executor.shutdown(); }
    }
}

