import static org.junit.Assert.*;

public class SaveScheduleTest {
    @Rule public TemporaryFolder temporary=new TemporaryFolder();

    static SavedState named(String name,long revision){
        var state=new SavedState(new Session(name,1_000L,SessionMode.GENERAL),null,Collections.emptyList());
        state.setRevision(revision);return state;
    }

    @Test public void refusedScheduleDoesNotAdvanceTheMarker(){
        var engine=ReviewFixesTest.engine();
        var storage=new Persistence(null,null,null,null,engine){
            boolean accepted;
            @Override boolean scheduleSave(){return accepted;}
            @Override SaveStatus saveStatus(){return SaveStatus.neverSaved();}
        };
        var plugin=new GpManagerPlugin();plugin.engine=engine;plugin.storage=storage;plugin.savedRevision=-1;
        plugin.persist();assertEquals(-1,plugin.savedRevision);
        storage.accepted=true;plugin.persist();assertEquals(engine.revision(),plugin.savedRevision);
        assertTrue(GpManagerPlugin.saveDue(50,engine.revision(),engine.revision()-1));
        assertFalse(GpManagerPlugin.saveDue(50,engine.revision(),engine.revision()));
        assertTrue(GpManagerPlugin.saveDue(500,engine.revision(),engine.revision()));
    }

    @Test public void writerReturnsTrueForCoveredAndFalseForStaleGeneration() throws Exception {
        Path directory=temporary.newFolder().toPath();
        SessionRepository repository=new SessionRepository(new Gson(),FilepathTestSupport.root(directory),false);
        var writer=new OrderedPersistenceWriter(repository,rejecting());
        long gen=repository.generation;
        writer.merged.set(new OrderedPersistenceWriter.PendingWrite(new WriteIntent(null,gen,0L,named("Pending",9L),null)));
        assertTrue("a newer same-generation snapshot covers the request",
                writer.submit(new WriteIntent(null,gen,0L,named("Covered",2L),null)));
        writer.merged.set(new OrderedPersistenceWriter.PendingWrite(new WriteIntent(null,gen+1,0L,named("NewerScope",1L),null)));
        assertFalse("a lower generation cannot replace a newer pending scope",
                writer.submit(new WriteIntent(null,gen,0L,named("StaleScope",1L),null)));
        writer.shutdown(Duration.ZERO);
    }

    @Test public void writerRefusesStoppedConflictedAndRejectedWork() throws Exception {
        Path directory=temporary.newFolder().toPath();
        SessionRepository repository=new SessionRepository(new Gson(),FilepathTestSupport.root(directory),false);
        var executor=OrderedPersistenceWriter.daemonExecutor("save-schedule-test");
        var writer=new OrderedPersistenceWriter(repository,executor);
        try{
            long gen=repository.generation;
            assertTrue(writer.submit(new WriteIntent(null,gen,0L,named("A",1L),null)));
            assertTrue(writer.submit(new WriteIntent(null,gen,0L,named("B",2L),null)));
            assertTrue(writer.flush(Duration.ofSeconds(5)));
            writer.accept=false;
            assertFalse(writer.submit(new WriteIntent(null,gen,0L,named("Stopped",3L),null)));
            writer.accept=true;
            writer.conflict.set(gen);
            assertFalse(writer.submit(new WriteIntent(null,gen,0L,named("Conflict",4L),null)));
        }finally{
            writer.shutdown(Duration.ofSeconds(5));executor.shutdown();
        }
        var rejecting=rejecting();
        var rejected=new OrderedPersistenceWriter(repository,rejecting);
        assertFalse(rejected.submit(new WriteIntent(null,repository.generation,0L,named("Rejected",5L),null)));
        assertFalse(rejected.flush(Duration.ofMillis(50)));
        rejected.shutdown(Duration.ZERO);
    }

    static AbstractExecutorService rejecting(){
        return new AbstractExecutorService(){
            public void execute(Runnable command){throw new RejectedExecutionException();}
            public void shutdown(){}
            public List<Runnable> shutdownNow(){return List.of();}
            public boolean isShutdown(){return false;}
            public boolean isTerminated(){return false;}
            public boolean awaitTermination(long timeout,TimeUnit unit){return true;}
        };
    }
}

package com.gpmanager;

import com.google.gson.*;
import java.lang.reflect.*;
import java.util.*;
import org.junit.Test;
import java.nio.file.Files;
import static org.junit.Assert.*;

/** Persisted graph closure and ownership; reflection stays in offline tests. */
public class SaveSnapshotIsolationTest {
    static Set<Object> inspected=Collections.newSetFromMap(new IdentityHashMap<>());
    static List<Field> fields(Class<?> type) {
        List<Field> result = new ArrayList<>();
        for (Class<?> owner=type;owner!=null&&owner!=Object.class;owner=owner.getSuperclass())
            result.addAll(Arrays.asList(owner.getDeclaredFields()));
        return result;
    }
    static JsonElement seed(Type type, String path) {
        if(type instanceof ParameterizedType) {
            ParameterizedType p=(ParameterizedType)type;
            if(p.getRawType()==List.class||p.getRawType()==Set.class) {JsonArray a=new JsonArray();a.add(seed(p.getActualTypeArguments()[0],path+"[0]"));return a;}
            if(p.getRawType()==Map.class) {JsonObject o=new JsonObject();o.add(p.getActualTypeArguments()[0]==Integer.class?"19":"key",seed(p.getActualTypeArguments()[1],path+".value"));return o;}
            throw new AssertionError(type);
        }
        Class<?> c=(Class<?>)type;
        if(c.isArray()){JsonArray a=new JsonArray();a.add(seed(c.getComponentType(),path+"[0]"));return a;}
        if(c==String.class)return new JsonPrimitive(path);
        if(c==boolean.class||c==Boolean.class)return new JsonPrimitive(true);
        if(c.isPrimitive()||Number.class.isAssignableFrom(c))return new JsonPrimitive(123);
        if(c.isEnum())return new JsonPrimitive(((Enum<?>)c.getEnumConstants()[0]).name());
        JsonObject object=new JsonObject();
        for(Field f:fields(c)) if(!Modifier.isStatic(f.getModifiers())&&!Modifier.isTransient(f.getModifiers())&&!f.isSynthetic()) object.add(f.isAnnotationPresent(com.google.gson.annotations.SerializedName.class)?f.getAnnotation(com.google.gson.annotations.SerializedName.class).value():f.getName(),seed(f.getGenericType(),path+"."+f.getName()));
        return object;
    }
    static void aliases(Object a,Object b) throws Exception {
        if(a==null) {if(b!=null)throw new AssertionError();return;}
        Class<?> c=a.getClass();
        if(c.isEnum()||a instanceof String||a instanceof Number||a instanceof Boolean)return;
        if(a==b)throw new AssertionError("shared mutable reference: "+c);
        if(!inspected.add(a))return;
        if(a instanceof Set) {var x=((Set<?>)a).iterator();var y=((Set<?>)b).iterator();while(x.hasNext())aliases(x.next(),y.next());return;}
        if(c.isArray()){for(int i=0;i<java.lang.reflect.Array.getLength(a);i++)aliases(java.lang.reflect.Array.get(a,i),java.lang.reflect.Array.get(b,i));return;}
        if(a instanceof List) {List<?> x=(List<?>)a,y=(List<?>)b;for(int i=0;i<x.size();i++)aliases(x.get(i),y.get(i));return;}
        if(a instanceof Map) {Map<?,?> x=(Map<?,?>)a,y=(Map<?,?>)b;for(Object key:x.keySet())aliases(x.get(key),y.get(key));return;}
        for(Field f:fields(c))if(!Modifier.isStatic(f.getModifiers())&&!Modifier.isTransient(f.getModifiers())&&!f.isSynthetic()) {f.setAccessible(true);aliases(f.get(a),f.get(b));}
    }
    static void mutate(Object o) throws Exception {
        if(o==null||!inspected.add(o))return;
        if(o instanceof List) {for(Object v:(List<?>)o)mutate(v);((List<?>)o).clear();return;}
        if(o instanceof Map) {((Map<?,?>)o).clear();return;}
        Class<?> c=o.getClass();
        if(!c.getName().startsWith("com.gpmanager.")||c.isEnum())return;
        for(Field f:fields(c)) if(!Modifier.isStatic(f.getModifiers())&&!Modifier.isTransient(f.getModifiers())&&!f.isSynthetic()) {
            f.setAccessible(true);Object value=f.get(o);mutate(value);
            if(Modifier.isFinal(f.getModifiers()))continue;
            if(f.getType()==String.class)f.set(o,"mutated");
            else if(f.getType()==long.class)f.setLong(o,9876L);
            else if(f.getType()==int.class)f.setInt(o,9876);
            else if(f.getType()==boolean.class)f.setBoolean(o,!f.getBoolean(o));
        }
    }
    static SavedState capture(SavedState source) throws Exception {
        Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {}) {
            @Override SavedState savedState() {
                assertTrue("capture reads under the engine monitor", Thread.holdsLock(this));
                return source;
            }
        };
        Gson gson = new Gson();
        SessionRepository repository = new SessionRepository(gson,
                FilepathTestSupport.root(Files.createTempDirectory("gp-detached-contract")), false);
        Persistence disk = new Persistence(null, null, repository, new OrderedPersistenceWriter(repository, null), engine);
        WriteIntent intent = disk.currentIntent();
        assertNull("capture must not encode JSON", intent.json);
        return intent.state;
    }

    static JsonElement payload(Gson gson, SavedState state) {
        JsonObject json = gson.toJsonTree(state).getAsJsonObject();
        json.remove("savedAtEpochMillis");
        json.remove("revision");
        return json;
    }

    @Test public void everyPersistedFieldSurvivesCaptureWithoutMutableAliases() throws Exception {
        Gson gson = new Gson();
        SavedState source = gson.fromJson(seed(SavedState.class, "root"), SavedState.class);
        JsonElement before = payload(gson, source);
        SavedState copy = capture(source);
        assertEquals(before, payload(gson, copy));
        inspected.clear();
        aliases(source, copy);
        inspected.clear();
        mutate(source);
        assertEquals("later corrections cannot mutate an enqueued payload", before, payload(gson, copy));
    }

    @Test public void nullAndEmptyStructuresStayDistinct() throws Exception {
        Gson gson = new GsonBuilder().serializeNulls().create();
        for (String json : new String[]{"{}", "{\"history\":null,\"savedGrinds\":null,\"savedSessions\":null}",
                "{\"history\":[null],\"pendingClaims\":[null],\"lootingBag\":null}"}) {
            SavedState source = gson.fromJson(json, SavedState.class);
            assertEquals(payload(gson, source), payload(gson, capture(source)));
        }
    }

    @Test public void capturedSessionsHaveNoRuntimeListenersObserversOrMemo() throws Exception {
        Gson gson = new Gson();
        SavedState source = gson.fromJson(seed(SavedState.class, "root"), SavedState.class);
        source.generalSession.changeListener = () -> { throw new AssertionError("live listener escaped"); };
        source.generalSession.ownedValueObserver = new TrackedBasisLedger();
        source.generalSession.saveStamp = 17;
        Transaction receipt = source.generalSession.transactions.get(0);
        receipt.memo = new Object[]{"old"};
        receipt.castItemId = 123;
        SavedState copy = capture(source);
        assertNull(copy.generalSession.changeListener);
        assertNull(copy.generalSession.ownedValueObserver);
        assertEquals(0, copy.generalSession.saveStamp);
        assertNull(copy.generalSession.transactions.get(0).memo);
        assertEquals(0, copy.generalSession.transactions.get(0).castItemId);
        assertEquals(17, source.generalSession.saveStamp);
        assertEquals(123, receipt.castItemId);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.*;

/** Schema 110: an older save is set aside and the profile starts fresh; a newer one is never touched. */
public class SchemaFreshStartTest
{
    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    private static SavedState state(String name)
    {
        return new SavedState(new Session(name, 1_000L, SessionMode.GENERAL), null, Collections.emptyList());
    }

    /** Rewrites the saved file's schema field; a negative schema removes it. */
    private static void stamp(Path directory, int schema) throws Exception
    {
        for (String name : new String[] {"sessions.json", "sessions.backup.json"})
        {
            Path file = directory.resolve(name);
            if (!Files.exists(file)) continue;
            JsonObject json = new JsonParser().parse(Files.readString(file)).getAsJsonObject();
            if (schema < 0) json.remove("schemaVersion");
            else json.addProperty("schemaVersion", schema);
            Files.writeString(file, json.toString());
        }
    }

    private static long setAside(Path directory) throws Exception
    {
        try (java.util.stream.Stream<Path> paths = Files.list(directory))
        {
            return paths.filter(path -> path.getFileName().toString().contains(".schema")).count();
        }
    }

    private void startsFresh(int olderSchema) throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        assertTrue(PersistenceProbe.save(repository, state("Old")));
        assertTrue(PersistenceProbe.save(repository, state("Older backup")));
        stamp(directory, olderSchema);

        SavedState loaded = repository.load();
        assertNull("nothing from the older save is read", FixtureReads.currentSession(loaded));
        assertTrue(loaded.isSupportedSchema());
        assertEquals("primary and backup are kept beside the profile", 2L, setAside(directory));

        assertTrue("the fresh profile saves normally", PersistenceProbe.save(repository, state("New")));
        assertEquals("New", FixtureReads.currentSession(repository.load()).name());
    }

    @Test
    public void anOlderSaveIsSetAsideAndTheProfileStartsFresh() throws Exception
    {
        startsFresh(108);
    }

    @Test
    public void theReleasedSaveIsSetAsideAndTheProfileStartsFresh() throws Exception
    {
        // The actual 1.3.3 (schema 109) → 1.3.4 (schema 110) transition.
        startsFresh(109);
    }

    @Test
    public void aSaveWithoutASchemaStartsFreshInsteadOfBlockingEverySave() throws Exception
    {
        startsFresh(-1);
    }

    @Test
    public void aSaveThatMeetsAnOlderFileSetsItAsideInsteadOfRefusing() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository writer = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        assertTrue(PersistenceProbe.save(writer, state("Old")));
        stamp(directory, 108);

        SessionRepository fresh = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        assertTrue(fresh.save(new WriteIntent(null, fresh.generation, fresh.revision,
            state("New"), null)));
        assertEquals("New", FixtureReads.currentSession(fresh.load()).name());
        assertEquals(1L, setAside(directory));
    }

    @Test
    public void aNewerSaveIsNeverReadAsCurrentOrOverwritten() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        assertTrue(PersistenceProbe.save(repository, state("Future")));
        stamp(directory, SavedState.CURRENT_SCHEMA_VERSION + 1);
        String before = Files.readString(directory.resolve("sessions.json"));

        assertFalse(repository.load().isSupportedSchema());
        assertFalse(PersistenceProbe.save(repository, state("Downgrade")));
        assertEquals(before, Files.readString(directory.resolve("sessions.json")));
        assertEquals(0L, setAside(directory));
    }
}

