/** Optional full small values retain the existing icon layout and compact fallback. */
public class HudSemiCompactTest
{
    @Test public void valuesBelowTenMillionAreExactAndBothSignsUseTheSameBoundary()
    {
        long[] amounts = {31_799L, 9_999_999L, 10_000_000L, 200_000_000L};
        String[] expected = {"31,799", "9,999,999", "10.0M", "200M"};
        for (int i = 0; i < amounts.length; i++)
            for (int sign : new int[]{1, -1})
            {
                var fixture = fixture(true, true, true, 225);
                Transaction transaction = sign > 0 ? receipt(NOW, TransactionType.LOOT,
                    flow(1201, "Rune kiteshield", 1, (int) amounts[i]))
                    : new Transaction(NOW, TransactionType.CONSUMPTION, Context.GENERIC, "Dropped", "General", true,
                        List.of(flow(1201, "Rune kiteshield", -1, (int) amounts[i])), Confidence.CONFIRMED, "fixture", null);
                fixture.plugin.transactionBooked(transaction, NOW);
                HudFrame.Row row = fixture.frame(NOW + 1000).rows.get(0);
                assertEquals((sign < 0 ? "−" : "") + expected[i] + " ×1", row.value);
                assertEquals("", row.name);
                assertNotNull(row.icon);
                if (sign < 0) assertEquals(Kit.Tone.LOSS.color, row.color);
            }
    }

    @Test public void unknownAndValuelessItemsStayDistinct()
    {
        var unknown = fixture(true, true, true, 225);
        unknown.book(41, NOW, 100, "Unpriced item", 2, 0);
        assertEquals("Pending ×2", unknown.frame(NOW + 1000).rows.get(0).value);
        var worthless = fixture(true, true, true, 225);
        worthless.plugin.transactionBooked(receipt(NOW, TransactionType.LOOT,
            new Flow(101, "Valueless ticket", 2, 0, 0, PriceSource.NO_VALUE)), NOW);
        assertEquals("×2", worthless.frame(NOW + 1000).rows.get(0).value);
    }

    @Test public void namedAndMissingIconRowsKeepTheirExistingPresentation()
    {
        for (var fixture : new HudBatchPresentationTest.Fixture[]{fixture(false, true, true, 225),
            fixture(true, false, true, 225)})
        {
            fixture.book(41, NOW, 1201, "Rune kiteshield", 1, 31_799);
            HudFrame.Row row = fixture.frame(NOW + 1000).rows.get(0);
            assertEquals("Rune kiteshield ×1", row.name);
            assertEquals("+31.7k", row.value);
        }
    }

    @Test public void pendingPriceAndQuantityFitTheMinimumHudWidth() {
        var fixture = fixture(true, true, true, 120);
        fixture.book(41, NOW, 100, "Unpriced item", 2, 0);
        var frame = fixture.frame(NOW + 1000);
        var image = new BufferedImage(640, 300, BufferedImage.TYPE_INT_ARGB);
        var graphics = image.createGraphics();
        try {
            var overlay = new HudOverlay(fixture.builder, fixture.config);
            var size = overlay.render(graphics);
            int valueWidth = graphics.getFontMetrics(overlay.body).stringWidth(frame.rows.get(0).value);
            assertTrue("pending value and count fit beside the icon", overlay.indent + valueWidth + HudOverlay.PAD * 2 <= size.width);
            assertEquals("Pending ×2", frame.rows.get(0).value);
        } finally { graphics.dispose(); }
    }

    @Test public void narrowHudRendersTheCompleteCompactFallbackInsteadOfClippingFullFigures()
    {
        var compact = fixture(true, true, false, 120);
        var semi = fixture(true, true, true, 120);
        for (var fixture : new HudBatchPresentationTest.Fixture[]{compact, semi})
            fixture.book(41, NOW, 1201, "Stacked loot", 20_000, 499);
        assertEquals("9,980,000 ×20.0k", semi.frame(NOW + 1000).rows.get(0).value);
        assertArrayEquals(pixels(render(compact)), pixels(render(semi)));
    }

    @Test public void wideHudRendersTheFullValueBesideItsIconAndKeepsHighlightColor()
    {
        var compact = fixture(true, true, false, 225);
        var semi = fixture(true, true, true, 225);
        for (var fixture : new HudBatchPresentationTest.Fixture[]{compact, semi})
        {
            fixture.builder.filter = new RecentFilter()
            {
                @Override public boolean isFlowIncluded(Flow item) { return true; }
                @Override public Color highlight(String name, long quantity) { return Color.MAGENTA; }
            };
            fixture.book(41, NOW, 1201, "Rune kiteshield", 1, 31_799);
        }
        BufferedImage shown = render(semi);
        assertFalse("full figures are actually painted", Arrays.equals(pixels(render(compact)), pixels(shown)));
        int left = Integer.MAX_VALUE;
        for (int y = 0; y < shown.getHeight(); y++)
            for (int x = 0; x < shown.getWidth(); x++)
                if (shown.getRGB(x, y) == Color.MAGENTA.getRGB()) left = Math.min(left, x);
        assertTrue("highlighted figures stay beside the icon", left >= 27 && left <= 30);
    }

    static HudBatchPresentationTest.Fixture fixture(boolean compact, boolean icons, boolean semi, int width)
    {
        return new HudBatchPresentationTest.Fixture(compact, icons, semi, width);
    }

    static BufferedImage render(HudBatchPresentationTest.Fixture fixture)
    {
        fixture.frame(NOW + 1000);
        var image = new BufferedImage(640, 300, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            Dimension size = new HudOverlay(fixture.builder, fixture.config).render(graphics);
            assertTrue(size.width <= fixture.config.hudMaxWidth());
        }
        finally { graphics.dispose(); }
        return image;
    }

    static int[] pixels(BufferedImage image)
    {
        return image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth());
    }
}

package com.gpmanager;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

import static com.gpmanager.HudBuilderTest.NOW;
import static com.gpmanager.HudBuilderTest.config;
import static com.gpmanager.HudBuilderTest.grind;
import static com.gpmanager.HudTrayTest.flow;
import static com.gpmanager.HudTrayTest.receipt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Auto width hugs content, stops at a ceiling, and shortens what does not fit. */
public class HudSizingTest
{
    private static final Graphics2D G = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();

    @Test
    public void fitShortensWithOneEllipsisAndLeavesShortTextAlone()
    {
        FontMetrics metrics = G.getFontMetrics(FontManager.getRunescapeFont());
        assertEquals("Logs ×4", HudOverlay.fit(metrics, "Logs ×4", 200));
        String cut = HudOverlay.fit(metrics, "Superior dragon bones ×2", 60);
        assertTrue(cut, cut.endsWith("…"));
        assertTrue(metrics.stringWidth(cut) <= 60);
    }

    /** Owner 1.2: a long name shortens before its count, and "(uncharged)" reads "(u)". */
    @Test
    public void aLongNameShortensButKeepsItsCount()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        builder.tray.booked(receipt(NOW, TransactionType.LOOT, flow(21817, "Bracelet of ethereum (uncharged)", 2L, 90_000)), NOW, false, NOW);
        builder.tray.booked(receipt(NOW + 1L, TransactionType.LOOT, flow(1, "An extraordinarily long item name that "
            + "would never fit any sensible overlay", 3L, 10)), NOW + 1L, false, NOW + 1L);
        builder.update(grind(46L, null), f -> true, NOW + 10L);
        overlay.render(G);
        assertTrue(overlay.names[0], overlay.names[0].endsWith("… ×3"));
        assertTrue(overlay.names[1], overlay.names[1].startsWith("Bracelet of ethereum (u)"));
        assertTrue(overlay.names[1], overlay.names[1].endsWith(" ×2"));
    }

    @Test
    public void spritesCropToTheirVisiblePixels()
    {
        BufferedImage sprite = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
        assertEquals("a sprite still loading keeps its whole canvas", new Rectangle(36, 32), Kit.visible(sprite));
        Graphics2D g = sprite.createGraphics();
        g.fillRect(10, 12, 4, 6);
        g.dispose();
        assertEquals(new Rectangle(10, 12, 4, 6), Kit.visible(sprite));
    }

    @Test
    public void autoWidthHugsContentAndStopsAtTheCeiling()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        builder.update(grind(46L, null), f -> true, NOW);
        Dimension resting = overlay.render(G);
        assertTrue("short content leaves room below the ceiling", resting.width < config.hudMaxWidth());
        assertTrue(resting.width >= HudOverlay.MIN_WIDTH);

        builder.tray.booked(receipt(NOW, TransactionType.LOOT, flow(1, "An extraordinarily long item name that "
            + "would never fit any sensible overlay", 1L, 10)), NOW, false, NOW);
        builder.update(grind(46L, null), f -> true, NOW + 10L);
        assertEquals("long rows stop at Max width and shorten instead", config.hudMaxWidth(), overlay.render(G).width);
    }

    /** Owner 2026-09-28: GP/h sits beside "Net / target" whenever HUD+ has the room. */
    @Test
    public void theRateSharesTheNetLineWhenItFits()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        builder.update(grind(-3_800L, 5_000_000L), f -> true, NOW);
        assertTrue("room to spare", overlay.render(G).width < config.hudMaxWidth());
        assertEquals("no line of its own", 0, overlay.moneyY[3]);
    }

    @Test
    public void tickingDigitsNeverWobbleTheWidth()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        builder.interaction("Ancient Wyvern of the Long Tail", true);
        Engine engine = HudBuilderTest.engine();
        engine.startCustom("Vorkath", NOW);
        builder.update(LiveSnapshot.capture(engine, NOW + 11_000L, null),
            f -> true, NOW + 11_000L);
        int narrowDigits = overlay.render(G).width;
        assertTrue("the title needs more than the minimum", narrowDigits > HudOverlay.MIN_WIDTH);
        builder.update(LiveSnapshot.capture(engine, NOW + 18_000L, null),
            f -> true, NOW + 18_000L);
        assertEquals(narrowDigits, overlay.render(G).width);
    }

    @Test
    public void emptyFreePlayFitsTimerAndRateOnOneLineAtEveryTextSize()
    {
        for (GpManagerConfig.TextSize textSize : GpManagerConfig.TextSize.values())
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override
                public boolean hudHideWhenIdle() { return false; }
                @Override
                public TextSize hudTextSize() { return textSize; }
            };
            Engine engine = HudBuilderTest.engine();
            engine.ensureSession(NOW);
            HudBuilder builder = new HudBuilder(config, null);
            HudFrame snapshot = builder.update(LiveSnapshot.capture(engine, NOW + 533_000L, null),
                f -> true, NOW + 533_000L);
            assertEquals("8m53s", snapshot.timer);
            assertEquals("0/h", snapshot.rate);
            HudOverlay overlay = new HudOverlay(builder, config);
            Dimension rendered = overlay.render(G);
            assertTrue("empty " + textSize + " HUD fits below the old floor", rendered.width < 120);
            assertEquals("only one line remains", HudOverlay.PAD * 2 + G.getFontMetrics(FixtureReads.bold(overlay)).getHeight(),
                rendered.height);
            FontMetrics metrics = G.getFontMetrics(FixtureReads.body(overlay));
            assertTrue("timer and rate retain a gap", HudOverlay.PAD + 11 + HudOverlay.width(metrics, snapshot.timer) + 8
                <= rendered.width - HudOverlay.PAD - HudOverlay.width(metrics, snapshot.rate));
        }
    }

    /**
     * Owner live 2026-10-14: with the run's name off the HUD the rate rides the gem row, so the
     * old money-row wrap trigger is gone; the ceiling is the invariant that remains.
     */
    @Test
    public void aNarrowHudNeverDrawsWiderThanItsCeiling()
    {
        for (int ceiling : new int[] {320, 120})
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override
                public int hudMaxWidth() { return ceiling; }
                @Override
                public boolean reducedMotion() { return true; }
            };
            HudBuilder builder = new HudBuilder(config, null);
            builder.tray.booked(receipt(NOW, TransactionType.LOOT,
                flow(1, "Whip", 1L, 1_500_000)), NOW, false, NOW);
            builder.update(grind(123_400_000L, null), f -> false, NOW + 10L);
            HudOverlay overlay = new HudOverlay(builder, config);
            Dimension rendered = overlay.render(G);
            assertTrue("the HUD never draws wider than its ceiling", rendered.width <= ceiling);
        }
    }

    /** Owner live 2026-10-14: the kill count survives even the narrowest HUD. */
    @Test
    public void theKillCountSurvivesNarrowCeilings()
    {
        for (int ceiling : new int[] {320, 100})
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override
                public int hudMaxWidth() { return ceiling; }
                @Override
                public boolean reducedMotion() { return true; }
            };
            HudBuilder builder = new HudBuilder(config, null);
            builder.update(grind(1_000L, null), f -> true, NOW - 1L);
            builder.interaction("Goblin", true);
            builder.tray.kill("Goblin", NOW - 1L, false);
            builder.update(grind(1_000L, null), f -> true, NOW);
            HudOverlay overlay = new HudOverlay(builder, config);
            overlay.render(G);
            if (ceiling == 320)
            {
                assertEquals("KC: 1", overlay.title);
            }
            else
            {
                assertTrue("the count survives narrow widths",
                    overlay.title.equals("KC: 1") || overlay.title.equals("1"));
                assertFalse("never an ellipsized count", overlay.title.contains("\u2026"));
            }
        }
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class HudTrayTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final long STAY = 5_000L;

    static Transaction receipt(long at, TransactionType type, Flow... flows)
    {
        return new Transaction(at, type, Context.LOOT, "", "Vorkath", true,
            Arrays.asList(flows), Confidence.CONFIRMED, "fixture", null);
    }

    static Flow flow(int id, String name, long quantity, int unit)
    {
        return new Flow(id, name, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE);
    }

    @Test
    public void eatingAndDrinkingNeverRideTheTray()
    {
        HudTray tray = new HudTray();
        tray.booked(receipt(T0, TransactionType.CONSUMPTION, flow(2434, "Prayer potion(4)", -1L, 9_800),
            flow(139, "Prayer potion(3)", 1L, 7_300)), T0, false, T0);
        Transaction wine = receipt(T0 + 600L, TransactionType.CONSUMPTION, flow(1993, "Jug of wine", -1L, 5),
            flow(1935, "Jug", 1L, 1));
        wine.setAction(ActionKind.DRINK);
        tray.booked(wine, T0 + 600L, false, T0 + 600L);
        Transaction pie = receipt(T0 + 1_200L, TransactionType.CONSUMPTION, flow(2327, "Meat pie", -1L, 30),
            flow(2331, "Half a meat pie", 1L, 12));
        pie.setAction(ActionKind.EAT);
        tray.booked(pie, T0 + 1_200L, false, T0 + 1_200L);
        assertTrue("a sip, a drink or a bite is not a drop", tray.entries().isEmpty());
        assertFalse(tray.hasBooked());
    }

    /** Owner 2026-09-28: Greater Nechryael's death spawns never break its kill streak. */
    @Test
    public void spawnsNeverBreakTheKillStreak()
    {
        // The plugin never passes a spawn on: no header, engage or kill (owner: "Death spawn ×6").
        assertTrue(HudTray.minion("Death spawn"));
        assertTrue(HudTray.minion(" death SPAWN "));
        assertFalse(HudTray.minion("Greater Nechryael"));
        assertFalse(HudTray.minion(null));
        HudTray tray = new HudTray();
        tray.kill("Greater Nechryael", T0, false);
        tray.kill("Greater Nechryael", T0 + 20_000L, false);
        tray.kill("Greater Nechryael", T0 + 40_000L, false);
        assertEquals("G. Nechryael", tray.streak(T0 + 41_000L).getKey());
        assertEquals(3, (int) tray.streak(T0 + 41_000L).getValue());
        tray.kill("Abyssal demon", T0 + 60_000L, false);
        assertEquals("a kill of another NPC starts its own streak", 1, (int) tray.streak(T0 + 61_000L).getValue());
    }

    /** Owner 2026-09-28: a drop reads "Dropped", and a hidden item dropped stays off the tray. */
    @Test
    public void aDropReadsDroppedAndAHiddenDropStaysHidden()
    {
        HudTray tray = new HudTray();
        Transaction drop = new Transaction(T0, TransactionType.CONSUMPTION, Context.GENERIC,
            "Dropped", "Vorkath", true, Arrays.asList(flow(526, "Bones", -1L, 90)),
            Confidence.CONFIRMED, "fixture", null);
        tray.booked(drop, T0, false, T0);
        assertEquals("Dropped", tray.label());
        HudTray.Entry bones = tray.entries().get(0);
        assertEquals(HudTray.State.LOST, bones.state);
        assertTrue("a lost row carries no tag: the Dropped headline and red value say it",
            bones.state.tag.isEmpty());
        LiveContext hideCheap = new LiveContext(false, null, 1_000L, PvpState.NONE, "", false, "", false);
        assertFalse("below the minimum shown value, the dropped Bones stay hidden",
            hideCheap.flowVisible(new Flow(bones.item, bones.name, bones.quantity, bones.unitPrice, bones.value)));
        HudTray looting = new HudTray();
        looting.booked(receipt(T0, TransactionType.LOOT, flow(536, "Dragon bones", 1L, 2_000)), T0, false, T0);
        looting.booked(drop, T0 + 600L, false, T0 + 600L);
        assertEquals("a drop mid-trip keeps the loot beside it", 2, looting.entries().size());
        assertEquals("Looted", looting.label());
    }

    @Test
    public void aPickupShowsExactlyOnce()
    {
        HudTray tray = new HudTray();
        tray.booked(receipt(T0 + 600L, TransactionType.LOOT, flow(536, "Dragon bones", 2L, 2_000)), T0 + 600L, false, T0 + 600L);
        List<HudTray.Entry> entries = tray.entries();
        assertEquals("the pickup shows exactly once", 1, entries.size());
        assertEquals(HudTray.State.RECEIVED, entries.get(0).state);
        assertEquals(2L, entries.get(0).quantity);
        assertEquals(4_000L, entries.get(0).value);
    }

    @Test
    public void aRowThatGrowsMovesToTheTop()
    {
        HudTray tray = new HudTray();
        tray.booked(receipt(T0, TransactionType.LOOT, flow(536, "Dragon bones", 1L, 2_000)), T0, false, T0);
        tray.booked(receipt(T0 + 1L, TransactionType.LOOT, flow(1753, "Green dragonhide", 1L, 1_500)), T0 + 1L, false, T0 + 1L);
        tray.booked(receipt(T0 + 2L, TransactionType.LOOT, flow(536, "Dragon bones", 1L, 2_000)), T0 + 2L, false, T0 + 2L);

        List<HudTray.Entry> entries = tray.entries();
        // Owner 1.2: the newest loot is always on top, more of an item included.
        assertEquals("the row that last grew leads", "Dragon bones", entries.get(0).name);
        assertEquals("Green dragonhide", entries.get(1).name);
        assertEquals(2L, entries.get(0).quantity);
        assertEquals(4_000L, entries.get(0).value);
    }

    @Test
    public void aClaimedRewardLeadsAndKeepsItsFadeIdentity()
    {
        HudTray tray = new HudTray();
        tray.observed(995, "Coins", 5_000L, 1L, T0, false);
        assertEquals(HudTray.State.PENDING, tray.entries().get(0).state);

        tray.booked(receipt(T0 + 1L, TransactionType.LOOT, flow(1753, "Green dragonhide", 1L, 1_500)), T0 + 1L, false, T0 + 1L);
        tray.booked(receipt(T0 + 2L, TransactionType.GAIN, flow(995, "Coins", 5_000L, 1)), T0 + 2L, false, T0 + 2L);

        List<HudTray.Entry> entries = tray.entries();
        assertEquals(2, entries.size());
        assertEquals("the claim is the newest loot (owner 1.2)", "Coins", entries.get(0).name);
        assertEquals(HudTray.State.CLAIMED, entries.get(0).state);
        assertEquals("the row keeps its first-seen identity", T0, entries.get(0).born);
        assertEquals(5_000L, entries.get(0).quantity);
    }

    @Test
    public void pendingRewardsBecomeClaimed()
    {
        HudTray tray = new HudTray();
        tray.observed(995, "Coins", 5_000L, 1L, T0, false);
        tray.booked(receipt(T0 + 600L, TransactionType.GAIN, flow(995, "Coins", 5_000L, 1)), T0 + 600L, false, T0 + 600L);
        assertEquals(1, tray.entries().size());
        assertEquals(HudTray.State.CLAIMED, tray.entries().get(0).state);
    }

    @Test
    public void routineUseNeverRidesButRoutineDropsDo()
    {
        HudTray tray = new HudTray();
        tray.booked(receipt(T0, TransactionType.LOOT, flow(560, "Death rune", 50L, 200),
            flow(11212, "Dragon arrow", 20L, 900)), T0, false, T0);
        assertEquals("a rune or ammo pickup is a drop like any other", 2, tray.entries().size());
        assertEquals("Death rune", tray.entries().get(0).name);
        assertEquals("Dragon arrow", tray.entries().get(1).name);
        tray.booked(receipt(T0 + 1L, TransactionType.CONSUMPTION, flow(2434, "Prayer potion(4)", -1L, 9_000)), T0 + 1L, false, T0 + 1L);
        assertEquals("routine use still never rides", 2, tray.entries().size());
        tray.booked(receipt(T0 + 2L, TransactionType.TRANSFER, flow(536, "Dragon bones", 5L, 2_000)), T0 + 2L, false, T0 + 2L);
        assertEquals("a transfer is neutral; it never rides", 2, tray.entries().size());
    }

    @Test
    public void aDropOfTenMillionLightsGoldAndOneLessDoesNot()
    {
        HudTray tray = new HudTray();
        tray.booked(receipt(T0, TransactionType.LOOT, flow(1, "Almost", 1L, 9_999_999)), T0, false, T0);
        assertFalse(tray.entries().get(0).gold);

        tray.booked(receipt(T0 + 1L, TransactionType.LOOT, flow(2, "Twisted bow", 1L, 10_000_000)), T0 + 1L, false, T0 + 1L);
        assertTrue(tray.entries().get(0).gold);
    }

    @Test
    public void deathsDropsAndDestroysAreLostButOtherItemUseIsNot()
    {
        HudTray tray = new HudTray();
        tray.booked(receipt(T0, TransactionType.CONSUMPTION, flow(8013, "Teleport to house", -1L, 553)), T0, false, T0);
        assertFalse("a teleport tab broken is routine use", !tray.entries.isEmpty());
        Transaction dropped = receipt(T0, TransactionType.CONSUMPTION, flow(536, "Dragon bones", -1L, 2_000));
        dropped.note = "Dropped";
        tray.booked(dropped, T0, false, T0);
        assertEquals(HudTray.State.LOST, tray.entries().get(0).state);
    }




    @Test
    public void anotherNpcStartsItsOwnStreakSoItsLootNeverJoinsTheLastOne()
    {
        HudTray tray = new HudTray();
        tray.kill("Guard", T0, false);
        tray.booked(receipt(T0 + 600L, TransactionType.LOOT, flow(995, "Coins", 30L, 1)), T0 + 600L, false, T0 + 600L);
        tray.kill("Guard", T0 + 10_000L, false);
        assertEquals("Guard", tray.streak(T0 + 10_000L).getKey());
        assertEquals(2, (int) tray.streak(T0 + 10_000L).getValue());

        tray.kill("Hill Giant", T0 + 20_000L, false);
        assertTrue("the Guard's coins leave with the Guard streak", tray.entries().isEmpty());
        tray.booked(receipt(T0 + 20_600L, TransactionType.LOOT, flow(532, "Big bones", 1L, 300)), T0 + 20_600L, false, T0 + 20_600L);
        assertEquals(1, tray.entries().size());
        assertEquals("Hill Giant", tray.streak(T0 + 20_600L).getKey());
        assertEquals(1, (int) tray.streak(T0 + 20_600L).getValue());
    }

    @Test
    public void aNewNpcsFirstKillRefreshesTheTrayToItsOwnStreak()
    {
        HudTray tray = new HudTray();
        tray.kill("Skeleton", T0, false);
        tray.booked(receipt(T0 + 600L, TransactionType.LOOT, flow(526, "Bones", 1L, 50)), T0 + 600L, false, T0 + 600L);
        assertEquals("a kill streak's heading names its NPC", "Skeleton", tray.label());

        assertFalse("the Skeleton's loot stays while the Guard is only attacked", tray.entries().isEmpty());
        int trip = tray.tripId();
        tray.kill("Guard", T0 + 2_000L, false);
        assertFalse("the Guard's first kill starts its own streak", trip == tray.tripId());
        assertEquals(1, (int) tray.streak(T0 + 2_000L).getValue());
    }

    @Test
    public void anotherNpcsLeftoverLootNeverJoinsTheNewStreak()
    {
        HudTray tray = new HudTray();
        tray.kill("Skeleton", T0, false);
        tray.booked(npcLoot(T0 + 600L, "Guard", flow(995, "Coins", 30L, 1)), T0 + 600L, false, T0 + 600L);
        assertTrue("the Guard's coins, picked up late, stay off the Skeleton's tray", tray.entries().isEmpty());
        tray.booked(npcLoot(T0 + 1_200L, "Skeleton", flow(526, "Bones", 1L, 50)), T0 + 1_200L, false, T0 + 1_200L);
        assertEquals(1, tray.entries().size());
        assertEquals("Bones", tray.entries().get(0).name);
    }

    @Test
    public void theHeadingSaysWhatTheStreakDid()
    {
        HudTray tray = new HudTray();
        tray.booked(receipt(T0, TransactionType.LOOT, flow(536, "Dragon bones", 1L, 2_000)), T0, false, T0);
        assertEquals("Looted", tray.label());

        Transaction chest = receipt(T0 + 1_000L, TransactionType.LOOT, flow(1_631, "Uncut dragonstone", 1L, 10_000));
        chest.setAction(ActionKind.DEFERRED_CLAIM);
        tray.booked(chest, T0 + 1_000L, false, T0 + 1_000L);
        assertEquals("Claimed", tray.label());

        tray.booked(Tx.of(T0 + 2_000L, null, TransactionType.GAIN, Context.GENERIC, "",
            "Thieving", true, Arrays.asList(flow(995, "Coins", 3L, 1))), T0 + 2_000L, false, T0 + 2_000L);
        assertEquals("Stole", tray.label());
    }

    private static Transaction npcLoot(long at, String npc, Flow flow)
    {
        return Tx.of(at, null, TransactionType.LOOT, Context.LOOT, "Loot from " + npc, npc, true,
            Arrays.asList(flow));
    }

    @Test
    public void aKillNeverOpensTheTrayOnlyItsLootDoes()
    {
        HudTray tray = new HudTray();
        tray.kill("Guard", T0, false);
        tray.booked(receipt(T0 + 600L, TransactionType.LOOT, flow(995, "Coins", 30L, 1)), T0 + 600L, false, T0 + 600L);
        assertFalse("folded after the stay", open(tray, T0 + 600L + STAY));

        tray.kill("Guard", T0 + 20_000L, false);
        assertFalse("the next kill leaves the tray folded", open(tray, T0 + 20_000L));
