            builder.tray.booked(receipt(NOW + 1L, TransactionType.LOOT, flow(1420, "Iron mace", 1L, 42)), NOW + 1L, false, NOW + 1L);
            HudFrame s = builder.update(HudBuilderTest.grind(1_042L, null), f -> true, NOW + 2L);
