package com.gpmanager;

import com.gpmanager.Semantics.Receipt;
import java.awt.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.*;
import javax.swing.JPopupMenu;

/** Test-side access to LedgerPage state; moved out of production to keep the plugin small. */
public final class LedgerPageProbe
{

    /** The page's current read model. */
    public static LedgerData data(LedgerPage page)
    {
        return page.data;
    }
    private LedgerPageProbe()
    {
    }

    /** OVERVIEW, RECEIPTS (a group's list) or EXACT (a receipt selected under it). */
    public static String drill(LedgerPage p)
    {
        return p.data == null || p.data.detail == null || p.detail.getComponentCount() == 0 ? "OVERVIEW"
            : p.data.detail.exact != null ? "EXACT" : "RECEIPTS";
    }

    /** The selected receipt's Correct ▾ menu labels, in order. */
    public static List<String> correctMenu(LedgerPage p)
    {
        List<String> labels = new ArrayList<>();
        if (p.data != null && p.data.detail != null && p.data.detail.exact != null)
        {
            for (Component item : p.correctMenu(p.data.detail.exact).getComponents())
            {
                labels.add(((JMenuItem) item).getText());
            }
        }
        return labels;
    }

    /** Runs one entry of the selected receipt's Correct ▾ menu. */
    public static void chooseCorrection(LedgerPage p, String label)
    {
        for (Component item : p.correctMenu(p.data.detail.exact).getComponents())
        {
            if (((JMenuItem) item).getText().equals(label))
            {
                ((JMenuItem) item).doClick();
            }
        }
    }

    /**
     * The one effective Net contribution of a booked settlement, as the old proof worded it;
     * {@code corrected} is the receipt's own correction state, as the Ledger passes it.
     */
    public static String netContributionText(MarketRows.Row market, boolean corrected)
    {
        if (!market.realizedResultCorrectionAware)
        {
            return "0 · not counted";
        }
        if (corrected)
        {
            return Fmt.exactSigned(market.realizedResultGp) + " gp · corrected";
        }
        if (market.knownCostOnly)
        {
            return Fmt.exactSigned(market.realizedResultGp) + " gp · GE tax";
        }
        boolean knownResult = market.coverage != MarketRows.Coverage.FULLY_UNKNOWN
            || market.manualFinancialResult;
        return knownResult && market.settledQty > 0L
            ? Fmt.exactSigned(market.realizedResultGp) + " gp · Result"
            : "0 · not counted";
    }

    /** One rendered Market receipt row as "title|sub|value". */
    public static String marketReceiptRowText(Receipt receipt, long capturedAt)
    {
        boolean realized = MarketText.realized(receipt);
        return MarketText.receiptTitle(receipt) + "|" + MarketText.receiptSub(receipt, capturedAt) + "|"
            + (realized ? Fmt.exactSigned(MarketText.receiptPrimary(receipt)) + " gp"
                : MarketText.stateWord(receipt.market));
    }


    public static List<String> overviewRows(LedgerPage p, LedgerPageProbe.FinancialTable table)
    {
        return p.data == null || p.data.detail != null ? Collections.emptyList() : TableRows.names(axd(p, table));
    }

    public static String overviewPageLabel(LedgerPage p, LedgerPageProbe.FinancialTable table)
    {
        return p.data == null || p.data.detail != null ? "" : TableRows.pageText(axd(p, table));
    }

    public static void toggleTable(LedgerPage p, LedgerPageProbe.FinancialTable table)
    {
        axd(p, table).setFolded(!axd(p, table).isFolded());
    }

    public static void toggleCorrected(LedgerPage p)
    {
        p.corrections = !p.corrections;
        if (p.data != null)
        {
            p.apply(p.data);
        }
    }

    public static void clickReceipt(LedgerPage p, String transactionId)
    {
        if (p.data == null || p.data.detail == null)
        {
            return;
        }
        if (p.data.detail.group.market)
        {
            for (Receipt receipt : p.data.detail.entries)
            {
                if (receipt.transaction.equals(transactionId))
                {
                    p.clickReceipt(receipt.transaction, receipt.id);
                    return;
                }
            }
            return;
        }
        for (LedgerData.Card card : LedgerData.cards(p.data.detail.group))
        {
            if (card.transaction.equals(transactionId))
            {
                p.clickReceipt(card.transaction, card.id);
                return;
            }
        }
    }

    public static List<String> receiptCardTransactionIds(LedgerPage p)
    {
        List<String> ids = new ArrayList<>();
        if (!"OVERVIEW".equals(drill(p)))
        {
            if (p.data.detail.group.market)
            {
                for (Receipt receipt : p.data.detail.entries)
                {
                    if (!ids.contains(receipt.transaction))
                    {
                        ids.add(receipt.transaction);
                    }
                }
            }
            else
            {
                for (LedgerData.Card card : LedgerData.cards(p.data.detail.group))
                {
                    ids.add(card.transaction);
                }
            }
        }
        return ids;
    }

    public static List<String> detailReceiptRowTexts(LedgerPage p)
    {
        List<String> texts = new ArrayList<>();
        if ("OVERVIEW".equals(drill(p)))
        {
            return texts;
        }
        Semantics.Group group = p.data.detail.group;
        if (group.market)
        {
            for (Receipt receipt : p.data.detail.entries)
            {
                texts.add(marketReceiptRowText(receipt, p.data.at));
            }
            return texts;
        }
        for (LedgerData.Card card : LedgerData.cards(group))
        {
            texts.add(group.name + "|" + card.summaryText() + "|"
                + (card.incomplete ? "—" : Fmt.exactSigned(card.value) + " gp"));
        }
        return texts;
    }

    /** The detail's one Back: straight to the Ledger overview. */
    public static void back(LedgerPage p)
    {
        p.actions.selectionChanged(null, null, null);
    }

    public static void preview(LedgerPage p, LedgerData.CorrectionPreview preview, Correction correction)
    {
        p.preview = preview;
        p.pendingCorrection = correction;
        p.transaction = p.data == null || p.data.detail == null || p.data.detail.exact == null ? null
            : p.data.detail.exact.transaction;
    }

    public static void select(LedgerPage p, String transactionId)
    {
        p.actions.selectionChanged(transactionId == null || transactionId.isEmpty() ? null : transactionId, null, null);
    }

    public static String marketRowSemantics(LedgerPage p, String groupId)
    {
        for (Semantics.Group group : p.data == null ? Collections.<Semantics.Group>emptyList()
            : p.data.market.groups)
        {
            if (group.id.equals(groupId))
            {
                return Fmt.signed(MarketText.marketPrimary(p.data, group)) + "|" + MarketText.marketLead(p.data, group);
            }
        }
        return "";
    }

    public static JPopupMenu reviewMenu(LedgerPage p, ReviewRow row)
    {
        JPopupMenu menu = new JPopupMenu();
        for (Decision decision : Decision.values())
        {
            if (row.decisions.contains(decision))
            {
                menu.add(Kit.item(LedgerPage.reviewLabel(decision), () -> p.actions.decide(row.transaction, decision)));
            }
        }
        return menu;
    }

    public static List<String> detailTexts(LedgerPage p)
    {
        List<String> texts = new ArrayList<>();
        walk(p.detail, texts, false);
        return texts;
    }

    public static List<String> detailTooltips(LedgerPage p)
    {
        List<String> tips = new ArrayList<>();
        walk(p.detail, tips, true);
        return tips;
    }
    public enum FinancialTable { GAINS, COSTS, MARKET }
    private static Table axd(LedgerPage p, FinancialTable table) {
        return table == FinancialTable.GAINS ? p.income : table == FinancialTable.MARKET ? p.market : p.cost;
    }

    static void walk(Component component, List<String> out, boolean tips) {
        String text = tips ? component instanceof JComponent ? ((JComponent) component).getToolTipText() : null
            : component instanceof JLabel ? ((JLabel) component).getText() : null;
        if (text != null && !text.isEmpty()) {
            out.add(text);
        }
        if (component instanceof Container) {
            for (Component child : ((Container) component).getComponents()) {
                walk(child, out, tips);
            }
        }
    }
}

package com.gpmanager;

import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

/** Unknown values retain receipts and known totals; a classification Review has its own label. */
public class PendingItemPriceTest {
    private static final long NOW = 1_700_000_000_000L;

    @Test public void pendingPricesKeepQuantityAndKnownMoneyAcrossLiveAndLedger() throws Exception {
        SwingTestSupport.onEdt(() -> {
            var engine = ReviewFixesTest.engine();
            engine.startCustom("Price pending", NOW);
            var transaction = Tx.of(NOW + 1000, TransactionType.GAIN, Context.GENERIC, "", true,
                    List.of(new Flow(995, "Coins", 100, 1, 100, PriceSource.FACE_VALUE),
                            new Flow(999999, "Undefined item", 2, 0, 0, PriceSource.UNPRICED)));
            engine.session().addTransaction(transaction, 2000, false);
            long revision = engine.revision();
            var snapshot = LiveSnapshot.capture(engine, NOW + 2000, LiveContext.NONE);
            assertTrue("unpriced receipts wait in Ledger",snapshot.recent.stream().noneMatch(row -> row.unknown));
            assertEquals(100, snapshot.net);
            assertEquals(2, transaction.quantity(999999, true));
            var entry = LedgerData.Entry.current();
            var data = LedgerData.capture(engine, NOW + 2000, entry);
            var group = data.income.groups.stream().filter(row -> row.incomplete()).findFirst().orElseThrow();
            data = LedgerData.capture(engine, NOW + 2000, entry.withSelection(null, null, group.id));
            var page = new LedgerPage(ReviewFixesTest.proxy(LedgerPage.Actions.class, Map.of()), id -> null);
            page.apply(data);
            assertEquals("Price pending", page.groupRow(group, Kit.Tone.GAIN).value);
            var item = page.items(group).stream().filter(row -> row.name.equals("Undefined item")).findFirst().orElseThrow();
            assertEquals("Price pending", item.value);
            assertEquals("", item.exact);
            assertTrue(page.receipts.rows.stream().anyMatch(row -> row.value.equals("Price pending") && row.exact.isEmpty()));
            assertEquals("Price pending", page.receiptRow(group.entries.stream()
                    .filter(row -> row.unknown).findFirst().orElseThrow()).value);
            assertEquals(PriceSource.UNPRICED, transaction.flows().get(1).source());
            assertEquals(revision, engine.revision());
            assertEquals(100, engine.metrics(NOW + 2000).net);
            return null;
        });
    }

    @Test public void aPricedReviewRequestsADecisionInsteadOfAPrice() throws Exception {
        SwingTestSupport.onEdt(() -> {
            var engine = ReviewFixesTest.engine();
            engine.startCustom("Review", NOW);
            var transaction = new Transaction(NOW + 1000, TransactionType.UNCERTAIN, Context.GENERIC,
                    "", "Review", true, List.of(new Flow(526, "Bones", 1, 100, 100, PriceSource.GRAND_EXCHANGE)),
                    Confidence.UNCERTAIN, "No action evidence", null);
            engine.session().addTransaction(transaction, 2000, false);
            var data = LedgerData.capture(engine, NOW + 2000, LedgerData.Entry.current());
            var page = new LedgerPage(ReviewFixesTest.proxy(LedgerPage.Actions.class, Map.of()), id -> null);
            page.apply(data);
            assertEquals("Review", page.review.rows.get(0).value);
            var group = SemanticProbe.capture(List.of(transaction), List.of(), "", null).groups.get(0);
            assertEquals("Review", page.groupRow(group, Kit.Tone.REVIEW).value);
            assertEquals(100, transaction.flows().get(0).value);
            assertEquals(Correction.AUTO, transaction.correction());
            return null;
        });
    }
}

package com.gpmanager;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.*;
import static net.runelite.api.gameval.ItemID.LOGS;
import static net.runelite.api.gameval.ItemID.OAK_LOGS;

/** Review confirmations and application must share eligibility, atomicity and exact Net. */
public class ReviewConfirmationEligibilityTest {
    private static final long NOW = 1_000_000_000_000L;

    private static Engine engine() {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        engine.startCustom("Review confirmation", NOW);
        engine.setBaseline(new ContainerSnapshot(Map.of(995, 1_000_000L)));
        return engine;
    }

    private static Transaction book(Engine engine, long at, int item, long quantity, boolean counted, boolean review) {
        return book(engine, at, item, quantity, 100, counted, review);
    }

    private static Transaction book(Engine engine, long at, int item, long quantity, int unit, boolean counted, boolean review) {
        var row = new Transaction(at, review ? TransactionType.UNCERTAIN
                        : quantity > 0 ? TransactionType.GAIN : TransactionType.CONSUMPTION,
                Context.GENERIC, "", "Review confirmation", counted,
                List.of(new Flow(item, "Item " + item, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE)),
                review ? Confidence.UNCERTAIN : Confidence.CONFIRMED, "", null);
        engine.session().addTransaction(row, 500, false);
        return row;
    }

    private static Transaction delayed(Engine engine) {
        book(engine, NOW - 60_000, LOGS, 10, true, false);
        var review = book(engine, NOW - 30_000, LOGS, -4, false, true);
        book(engine, NOW - 10_000, LOGS, 5, 200, true, false);
        return review;
    }

    private static void refused(Engine engine, Decision decision) {
        String saved = JsonCodec.gson().toJson(engine.session());
        long revision = engine.revision(), net = engine.metrics(NOW).net;
        long quantity = EngineProbe.knownCoverageQty(engine, LOGS);
        long basis = EngineProbe.knownCoverageBasisGp(engine, LOGS);
        var preview = engine.previewDecision(decision, row -> true, NOW);
        assertEquals("one blocked row must refuse the complete selection", 0, preview.rowCount());
        assertEquals("a refused selection cannot promise a Net change", 0, preview.netDelta);
        assertEquals(0, engine.applyDecision(preview));
        assertEquals(saved, JsonCodec.gson().toJson(engine.session()));
        assertEquals(revision, engine.revision());
        assertEquals(net, engine.metrics(NOW).net);
        assertEquals(quantity, EngineProbe.knownCoverageQty(engine, LOGS));
        assertEquals(basis, EngineProbe.knownCoverageBasisGp(engine, LOGS));
    }

    @Test public void delayedCostHasNoApplicableConfirmation() {
        var engine = engine();
        delayed(engine);
        refused(engine, Decision.COST);
    }

    @Test public void delayedGainHasNoApplicableConfirmation() {
        var engine = engine();
        delayed(engine);
        refused(engine, Decision.GAIN);
    }

    private static void mixed(boolean eligibleFirst) {
        var engine = engine();
        Transaction eligible = eligibleFirst ? book(engine, NOW - 90_000, OAK_LOGS, 5, false, true) : null;
        var blocked = book(engine, NOW - 60_000, LOGS, 10, true, true);
        book(engine, NOW - 30_000, LOGS, -4, true, false);
        if (!eligibleFirst) eligible = book(engine, NOW - 10_000, OAK_LOGS, 5, false, true);
        assertTrue(engine.reviewNets(eligible.id()).containsKey(Decision.COST));
        assertFalse(engine.reviewNets(blocked.id()).containsKey(Decision.COST));
        refused(engine, Decision.COST);
        assertEquals(Correction.AUTO, eligible.correction());
        assertEquals(Correction.AUTO, blocked.correction());
    }

    @Test public void blockedFirstRowRefusesTheWholeBatch() { mixed(false); }
    @Test public void blockedLastRowRefusesTheWholeBatch() { mixed(true); }

    @Test public void eligibleBatchMatchesCanonicalNetAndKeepsOneUndo() {
        var engine = engine();
        var first = book(engine, NOW - 60_000, LOGS, 5, false, true);
        var second = book(engine, NOW - 30_000, OAK_LOGS, 3, false, true);
        String saved = JsonCodec.gson().toJson(engine.session());
        long revision = engine.revision();
        var preview = engine.previewDecision(Decision.GAIN, row -> true, NOW);
        assertEquals(saved, JsonCodec.gson().toJson(engine.session()));
        assertEquals(revision, engine.revision());
        assertEquals(List.of(first.id(), second.id()), preview.transactionIds);
        assertEquals(800, preview.netDelta);
        int history = engine.session().correctionHistory.size();
        assertEquals(2, engine.applyDecision(preview));
        assertEquals(800, engine.metrics(NOW).net);
        assertEquals(history + 1, engine.session().correctionHistory.size());
        assertTrue(engine.undoCorrection());
        assertEquals(0, engine.metrics(NOW).net);
        assertEquals(Correction.AUTO, first.correction());
        assertEquals(Correction.AUTO, second.correction());
    }

    private static SidebarPanel panel(Engine engine, AtomicInteger saves) throws Exception {
        var storage = new Persistence(null, null, null, null, engine) {
            @Override boolean scheduleSave() { saves.incrementAndGet(); return true; }
            @Override SaveStatus saveStatus() { return SaveStatus.neverSaved(); }
        };
        return SwingTestSupport.onEdt(() -> {
            var panel = new SidebarPanel(engine, new GpManagerConfig() {}, null, null, storage);
            panel.mutationOwner = Runnable::run;
            return panel;
        });
    }

    private static void open(SidebarPanel panel, Transaction row, Decision decision) throws Exception {
        SwingTestSupport.onEdt(() -> {
            new LedgerController(panel).decide(row.id(), decision);
            return null;
        });
    }

    private static void press(SidebarPanel panel, String button) throws Exception {
        SwingTestSupport.onEdt(() -> { ShellProbe.pressSheet(panel.shell, button); return null; });
    }

    private static void notApplied(SidebarPanel panel) throws Exception {
        assertTrue(SwingTestSupport.onEdt(() -> ShellProbe.noticeText(panel.shell)).contains("Not applied"));
    }

    @Test public void blockedDecisionReportsRefusalWithoutOfferingApply() throws Exception {
        var engine = engine();
        var review = delayed(engine);
        var saves = new AtomicInteger();
        var panel = panel(engine, saves);
        String saved = JsonCodec.gson().toJson(engine.session());
        open(panel, review, Decision.COST);
        assertFalse(SwingTestSupport.onEdt(() -> ShellProbe.sheetButtonTexts(panel.shell)).contains("Apply"));
        notApplied(panel);
        assertEquals(saved, JsonCodec.gson().toJson(engine.session()));
        assertEquals(0, saves.get());
    }

    @Test public void aBasisRefusalAfterConfirmationReportsZeroApplied() throws Exception {
        var engine = engine();
        var review = book(engine, NOW - 30_000, LOGS, 10, true, true);
        var panel = panel(engine, new AtomicInteger());
        open(panel, review, Decision.COST);
        assertTrue(SwingTestSupport.onEdt(() -> ShellProbe.sheetButtonTexts(panel.shell)).contains("Apply"));
        long revision = engine.revision();
        engine.session().ownedValueObserver.reserve(LOGS, 1);
        String saved = JsonCodec.gson().toJson(engine.session());
        assertEquals("the basis guard, rather than the revision fence, refuses this edit", revision, engine.revision());
        press(panel, "Apply");
        notApplied(panel);
        assertEquals(saved, JsonCodec.gson().toJson(engine.session()));
        assertEquals(Correction.AUTO, review.correction());
        assertEquals(9, EngineProbe.knownCoverageQty(engine, LOGS));
    }

    @Test public void anEligibleConfirmationAppliesAndSavesOnce() throws Exception {
        var engine = engine();
        var review = book(engine, NOW - 30_000, LOGS, 5, false, true);
        var saves = new AtomicInteger();
        var panel = panel(engine, saves);
        open(panel, review, Decision.COST);
        press(panel, "Apply");
        assertEquals(-500, engine.metrics(NOW).net);
        assertEquals(Correction.COST, review.correction());
        assertEquals(1, saves.get());
        assertTrue(engine.undoCorrection());
        assertEquals(0, engine.metrics(NOW).net);
    }

    @Test public void cancelKeepsTheLedgerAndDoesNotSave() throws Exception {
        var engine = engine();
        var review = book(engine, NOW - 30_000, LOGS, 5, false, true);
        var saves = new AtomicInteger();
        var panel = panel(engine, saves);
        String saved = JsonCodec.gson().toJson(engine.session());
        open(panel, review, Decision.COST);
        press(panel, "Cancel");
        assertEquals(saved, JsonCodec.gson().toJson(engine.session()));
        assertEquals(0, saves.get());
    }

    @Test public void aStaleConfirmationReportsRefusalAndKeepsTheNewLedger() throws Exception {
        var engine = engine();
        var review = book(engine, NOW - 30_000, LOGS, 5, false, true);
        var panel = panel(engine, new AtomicInteger());
        open(panel, review, Decision.COST);
        book(engine, NOW - 10_000, OAK_LOGS, 2, true, false);
        String saved = JsonCodec.gson().toJson(engine.session());
        press(panel, "Apply");
        notApplied(panel);
        assertEquals(saved, JsonCodec.gson().toJson(engine.session()));
        assertEquals(Correction.AUTO, review.correction());
    }
}

package com.gpmanager;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;
import static net.runelite.api.gameval.ItemID.LOGS;

/** Only decisions accepted by the existing basis guard may have inline forecasts. */
public class ReviewHintEligibilityTest {
    private static final long NOW = 1_000_000_000_000L;

    private static Engine engine() {
        JsonCodec.bind(new com.google.gson.Gson());
        var engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        engine.startCustom("Review eligibility", NOW);
        engine.setBaseline(new ContainerSnapshot(Map.of(995, 1_000_000L)));
        return engine;
    }

    private static Transaction book(Engine engine, long at, long quantity, int unit, boolean counted, boolean review) {
        var row = new Transaction(at, review ? TransactionType.UNCERTAIN
                        : quantity > 0 ? TransactionType.GAIN : TransactionType.CONSUMPTION,
                Context.GENERIC, "", "Review eligibility", counted,
                List.of(new Flow(LOGS, "Logs", quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE)),
                review ? Confidence.UNCERTAIN : Confidence.CONFIRMED, "", null);
        engine.session().addTransaction(row, 500, false);
        return row;
    }

    private static Map<Decision, Long> readOnly(Engine engine, Transaction review) {
        String saved = JsonCodec.gson().toJson(engine.session());
        long revision = engine.revision();
        long quantity = EngineProbe.knownCoverageQty(engine, LOGS);
        long basis = EngineProbe.knownCoverageBasisGp(engine, LOGS);
        var nets = engine.reviewNets(review.id());
        assertEquals("eligibility reads must preserve receipts, history and Undo", saved,
                JsonCodec.gson().toJson(engine.session()));
        assertEquals(revision, engine.revision());
        assertEquals(quantity, EngineProbe.knownCoverageQty(engine, LOGS));
        assertEquals(basis, EngineProbe.knownCoverageBasisGp(engine, LOGS));
        return nets;
    }

    private static Map<Decision, Long> refused(Engine engine, Transaction review, Decision decision) {
        String saved = JsonCodec.gson().toJson(engine.session());
        long revision = engine.revision();
        var nets = readOnly(engine, review);
        assertNull(LedgerData.preview(engine, review.id(), decision.correction, NOW));
        assertFalse("the existing guard must continue refusing this correction",
                engine.correctEntries(List.of(review.id()), decision.correction));
        assertEquals(saved, JsonCodec.gson().toJson(engine.session()));
        assertEquals(revision, engine.revision());
        assertFalse("a refused " + decision + " must have no forecast: " + nets, nets.containsKey(decision));
        return nets;
    }

    private static void delayed(Decision decision) {
        var engine = engine();
        book(engine, NOW - 60_000, 10, 100, true, false);
        var review = book(engine, NOW - 30_000, -4, 100, false, true);
        book(engine, NOW - 10_000, 5, 200, true, false);
        assertEquals(15, EngineProbe.knownCoverageQty(engine, LOGS));
        var nets = refused(engine, review, decision);
        assertEquals(2000, engine.metrics(NOW).net);
        assertEquals("neither financial choice is eligible in this state", "",
                LedgerPage.netPreview(Engine.reviewRow(engine.session(), review, NOW), nets));
    }

    @Test public void delayedReviewOmitsRefusedCost() { delayed(Decision.COST); }
    @Test public void delayedReviewOmitsRefusedGain() { delayed(Decision.GAIN); }

    @Test public void spentAcquisitionOmitsCostButKeepsTheEligibleGain() {
        var engine = engine();
        var review = book(engine, NOW - 60_000, 10, 100, true, true);
        book(engine, NOW - 30_000, -4, 100, true, false);
        assertEquals(6, EngineProbe.knownCoverageQty(engine, LOGS));
        var nets = refused(engine, review, Decision.COST);
        assertEquals(Long.valueOf(600), nets.get(Decision.GAIN));
        assertEquals("If counted as a gain: Net " + Fmt.signed(600),
                LedgerPage.netPreview(Engine.reviewRow(engine.session(), review, NOW), nets));
        assertTrue(engine.correctEntries(List.of(review.id()), Correction.REVENUE));
        assertEquals(nets.get(Decision.GAIN).longValue(), engine.metrics(NOW).net);
        assertEquals(6, EngineProbe.knownCoverageQty(engine, LOGS));
    }

    @Test public void eligibleCostKeepsItsCanonicalAfterTotal() {
        var engine = engine();
        book(engine, NOW - 60_000, 10, 100, true, false);
        var review = book(engine, NOW - 30_000, -4, 100, false, true);
        var nets = readOnly(engine, review);
        assertEquals(Long.valueOf(600), nets.get(Decision.COST));
        assertTrue(engine.correctEntries(List.of(review.id()), Correction.COST));
        assertEquals(nets.get(Decision.COST).longValue(), engine.metrics(NOW).net);
        assertEquals(6, EngineProbe.knownCoverageQty(engine, LOGS));
    }

    @Test public void eligibleGainKeepsItsCanonicalAfterTotal() {
        var engine = engine();
        var review = book(engine, NOW - 30_000, 5, 100, false, true);
        var nets = readOnly(engine, review);
        assertEquals(Long.valueOf(500), nets.get(Decision.GAIN));
        assertTrue(engine.correctEntries(List.of(review.id()), Correction.REVENUE));
        assertEquals(nets.get(Decision.GAIN).longValue(), engine.metrics(NOW).net);
        assertEquals(5, EngineProbe.knownCoverageQty(engine, LOGS));
    }
}

