package com.gpmanager;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** A death's bag and measured gear remain separate facts behind one presentation row. */
public class DeathRowGroupingTest {
    static Transaction loss(String fight, boolean bag, Flow... flows) {
        return new Transaction(bag ? 1000 : 1600, TransactionType.PK_DEATH_LOSS, Context.PK_DEATH,
                bag ? GameData.msg("bagLoss") : "PK death loss", "PKing", true, Arrays.asList(flows),
                Confidence.LIKELY, bag ? GameData.msg("bagLossProof") : "Measured gear loss", fight);
    }
    static Transaction gear(String fight) {
        return loss(fight, false, new Flow(861, "Magic shortbow", -1, 715, -715),
                new Flow(11941, "Looting bag", -1, 6, -6));
    }
    static Transaction bag(String fight) {
        return loss(fight, true, new Flow(1079, "Rune platelegs", -2, 37872, -75744),
                new Flow(995, "Coins", -693, 1, -693));
    }
    static Semantics.Result capture(Transaction... rows) {
        return SemanticProbe.capture(Arrays.asList(rows), List.of(), "", null);
    }

    @Test public void oneDeathRowKeepsEveryCanonicalReceiptAndItsValue() {
        var bag = bag("death:1"); var gear = gear("death:1");
        var projection = capture(bag, gear);
        assertEquals(1, projection.groups.size());
        var group = projection.groups.get(0);
        assertEquals("Death: PvP", group.name);
        assertEquals(-77158, group.value);
        assertEquals(Set.of(bag.id(), gear.id()), group.ids);
        assertEquals(4, group.entries.size());
        assertTrue(group.matchesText("Rune platelegs"));
        assertTrue(group.matchesText("Magic shortbow"));
        assertFalse("two receipts must not display as two deaths", group.actionGroup());
        assertEquals(-1, group.quantity);
        assertEquals(1, LiveProbe.recent(List.of(bag, gear), LiveContext.NONE).size());
    }

    @Test public void separateAndLegacyUnlinkedDeathsNeverMerge() {
        assertEquals(2, capture(gear("death:1"), gear("death:2")).groups.size());
        assertEquals(2, capture(gear(null), gear(null)).groups.size());
    }

    @Test public void partialUnknownStaysOneHonestIncompleteDeath() {
        var unknown = loss("death:1", false, new Flow(999999, "Unknown", -1, 0, 0, PriceSource.UNPRICED));
        var groups = capture(bag("death:1"), unknown).groups;
        assertEquals(1, groups.size());
        assertTrue(groups.get(0).incomplete());
        assertEquals(-76437, groups.get(0).value);
    }

    @Test public void correctionsRemainExactAndCannotHideTheOtherReceipt() {
        var bag = bag("death:1"); var gear = gear("death:1");
        gear.applyCorrection(Correction.IGNORE, "Manual correction");
        var groups = capture(bag, gear).groups;
        assertEquals(1, groups.size());
        assertTrue(groups.stream().noneMatch(group -> group.ids.contains(gear.id())));
        assertTrue(groups.get(0).ids.contains(bag.id()));
        assertEquals(Correction.IGNORE, gear.correction());
        assertEquals(-76437, Semantics.summarize(groups).cost);
    }

    @Test public void graveMovementsNeverBecomeRows() {
        var row = new Transaction(1000, TransactionType.TRANSFER, Context.TRANSFER,
                GameData.msg("deathItems"), "Death reclaim", false,
                List.of(new Flow(10499, "Ava's accumulator", -1, 600, -600),
                        new Flow(19564, "Royal seed pod", -1, 12, -12)), Confidence.LIKELY, "Owned items", null);
        assertTrue(capture(row).groups.isEmpty());
        assertEquals(0, capture(row).groups.size());
    }
}

package com.gpmanager;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/** Every verb, reason and correction/review label, pinned against a golden written from the switch tables. */
public class LabelTablesTest
{
    private static final Path GOLDEN = Paths.get("src/test/resources/com/gpmanager/label-tables.txt");

    static String snapshot()
    {
        StringBuilder out = new StringBuilder();
        for (ActionKind kind : ActionKind.values())
        {
            out.append("action ").append(kind).append(" = ").append(Semantics.actionVerb(kind)).append('\n');
        }
        out.append("correction null = ").append(Semantics.correctionLabel(null)).append('\n');
        for (Correction correction : Correction.values())
        {
            out.append("correction ").append(correction).append(" = ")
                .append(Semantics.correctionLabel(correction)).append(" | ")
                .append(LedgerPage.correctionLabel(correction)).append('\n');
        }
        for (Decision decision : Decision.values())
        {
            out.append("review ").append(decision).append(" = ").append(LedgerPage.reviewLabel(decision)).append('\n');
        }
        for (TransactionType type : TransactionType.values())
        {
            for (boolean counted : new boolean[]{true, false})
            {
                for (long value : new long[]{250L, -250L})
                {
                    Transaction tx = Tx.of(1_000L, type, Context.GENERIC, "", counted,
                        Collections.singletonList(new Flow(526, "Bones", value > 0 ? 1 : -1, 250, value)));
                    out.append("type ").append(type).append(' ').append(counted).append(' ').append(value).append(" = ")
                        .append(Semantics.verbOf(tx)).append(" | ")
                        .append(Semantics.why(tx, false, false)).append('\n');
                }
            }
            for (Correction correction : Correction.values())
            {
                Transaction tx = Tx.of(1_000L, type, Context.GENERIC, "", true,
                    Collections.singletonList(new Flow(526, "Bones", 1, 250, 250L)));
                tx.correction = correction;
                out.append("why ").append(type).append(' ').append(correction).append(" = ")
                    .append(Semantics.why(tx, false, false)).append(" | ")
                    .append(Semantics.why(tx, true, false)).append(" | ")
                    .append(Semantics.why(tx, false, true)).append('\n');
            }
        }
        return out.toString();
    }

    @Test
    public void labelsMatchTheGolden() throws java.io.IOException
    {
        String now = snapshot();
        if (Boolean.getBoolean("gp.golden.write"))
        {
            Files.createDirectories(GOLDEN.getParent());
            Files.write(GOLDEN, now.getBytes(StandardCharsets.UTF_8));
        }
        assertEquals(new String(Files.readAllBytes(GOLDEN), StandardCharsets.UTF_8).replace("\r\n", "\n"), now);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * PRE-R5C.2A semantic projection laws: living exact/generic Cast groups, measured-charge resource
 * truth, the mixed-action guard and unpriced-vs-Review routing.
 */
public class SemanticFinancialProjectionTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final int DEATH = 560;
    private static final int CHAOS = 562;
    private static final int WATER = 555;
    private static final int BLOOD = 565;
    private static final int NATURE = 561;

    @Test
    public void repeatedExactSpellUpdatesOneLivingGroupAndBubbles()
    {
        Transaction first = exactCast(T0 + 1_000L, "Ice Barrage", 1, 1, 1);
        Transaction second = exactCast(T0 + 2_000L, "Ice Barrage", 1, 1, 1);

        Semantics.Result result = capture(first, second);
        assertEquals("repeated compatible casts are one living group", 1, result.groups.size());
        Semantics.Group group = result.groups.get(0);
        assertEquals("Ice Barrage", group.name);
        assertEquals(-360L, group.value);
        assertEquals(2, group.count);
        assertEquals(T0 + 2_000L, group.at);
        assertTrue(group.actionGroup());
        assertEquals("3 rune types", group.context);
        assertEquals(1, Semantics.summarize(result.groups).entries);
        assertEquals(2, Semantics.summarize(result.groups).receipts);
        assertEquals(-360L, Semantics.summarize(result.groups).cost);

        Transaction third = exactCast(T0 + 3_000L, "Blood Barrage", 1, 1, 1);
        Semantics.Result bubbled = capture(first, second, third);
        assertEquals("a newer compatible-free receipt bubbles to the top", 2, bubbled.groups.size());
        assertEquals("Blood Barrage", bubbled.groups.get(0).name);
        assertEquals("Ice Barrage", bubbled.groups.get(1).name);
    }

    @Test
    public void differentExactNamesNeverMergeDespiteSharedResources()
    {
        Semantics.Result result = capture(
            exactCast(T0 + 1_000L, "Ice Barrage", 1, 1, 1),
            exactCast(T0 + 2_000L, "Blood Barrage", 1, 1, 1));

        assertEquals(2, result.groups.size());
        assertTrue(result.groups.stream().anyMatch(group -> "Ice Barrage".equals(group.name)));
        assertTrue(result.groups.stream().anyMatch(group -> "Blood Barrage".equals(group.name)));
        assertFalse("different exact names never share a group id",
            result.groups.get(0).id.equals(result.groups.get(1).id));
    }

    @Test
    public void genericCastsShareOneGroupOnlyUnderTheSameNormalisedComposition()
    {
        Semantics.Result scaled = capture(
            genericCast(T0 + 1_000L, 2, 4, 6),
            genericCast(T0 + 2_000L, 4, 8, 12));

        assertEquals("2/4/6 and 4/8/12 share the same scale-normalised composition",
            1, scaled.groups.size());
        Semantics.Group group = scaled.groups.get(0);
        assertEquals("Cast", group.name);
        assertEquals(2, group.count);
        assertEquals(-1_740L, group.value);

        Semantics.Result different = capture(
            genericCast(T0 + 1_000L, 1, 1, 1),
            bloodGenericCast(T0 + 2_000L));
        assertEquals("a different resource composition stays separate", 2, different.groups.size());
    }

    @Test
    public void genericCastsNeverReceiveAnInferredSpellName()
    {
        Semantics.Result result = capture(
            exactCast(T0 + 1_000L, "Ice Barrage", 1, 1, 1),
            genericCast(T0 + 2_000L, 1, 1, 1));

        Semantics.Group generic = result.groups.stream()
            .filter(group -> "Cast".equals(group.name)).findFirst().orElseThrow(AssertionError::new);
        Semantics.Group exact = result.groups.stream()
            .filter(group -> "Ice Barrage".equals(group.name)).findFirst().orElseThrow(AssertionError::new);

        assertFalse("the generic group must not carry the proven spell name",
            generic.terms.contains("Ice Barrage"));
        assertFalse("the generic group must not match the exact spell name",
            generic.matchesText("Ice Barrage"));
        assertFalse("exact never merges with generic",
            exact.id.equals(generic.id));
        assertTrue("search metadata reaches the exact group", exact.matchesText("Ice Barrage"));
        assertTrue("search metadata reaches underlying resources of the exact group",
            exact.matchesText("Death rune"));
        assertEquals("a matched group keeps its full total", -180L, exact.value);
    }

    @Test
    public void mixedGainAndCostActionStaysAdditiveContributionTruth()
    {
        Transaction alchemy = new Transaction(T0 + 1_000L,
            TransactionType.CONSUMPTION, Context.GENERIC, "", "Vorkath", true,
            Arrays.asList(
                new Flow(NATURE, "Nature rune", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE),
                new Flow(995, "Coins", 120L, 1, 120L, PriceSource.FACE_VALUE)),
            Confidence.CONFIRMED, "High alchemy", null);
        alchemy.setAction(ActionKind.CAST);

        Semantics.Result result = capture(alchemy);
        assertEquals("a mixed action never collapses into one cost composite", 2, result.groups.size());
        Semantics.Group cost = result.groups.stream()
            .filter(group -> group.table == Semantics.Table.COSTS_SUPPLIES)
            .findFirst().orElseThrow(AssertionError::new);
        Semantics.Group gain = result.groups.stream()
            .filter(group -> group.table == Semantics.Table.GAINS)
            .findFirst().orElseThrow(AssertionError::new);
        assertEquals("Nature rune", cost.name);
        assertEquals(-100L, cost.value);
        assertEquals("Coins", gain.name);
        assertEquals(120L, gain.value);
        assertEquals("the additive parts reconcile to the canonical Net",
            alchemy.net(), cost.value + gain.value);
        assertFalse("no action composite was invented",
            result.groups.stream().anyMatch(Semantics.Group::actionGroup));
    }

    @Test
    public void estimatedChargeCastsAreChargeUseAndSpellsStaySupplies()
    {
        Transaction estimate = estimatedCharge(T0 + 1_000L, "Trident of the Seas",
            new Flow(DEATH, "Death rune", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE),
            new Flow(CHAOS, "Chaos rune", -1L, 50, -50L, PriceSource.GRAND_EXCHANGE));

        Semantics.Result result =
            capture(estimate, exactCast(T0 + 2_000L, "Ice Barrage", 1, 1, 1));
        Semantics.Group charge = named(result.groups, "Trident of the Seas");
        assertNotNull(charge);
        assertTrue("an estimated charge cast is charge use", charge.charge);
        assertEquals(Semantics.Table.COSTS_SUPPLIES, charge.table);
        assertEquals("Cast", charge.label);

        Semantics.Group spell = named(result.groups, "Ice Barrage");
        assertNotNull(spell);
        assertFalse("an ordinary spell is a supply, never a charge", spell.charge);

        Semantics.Group measured = named(capture(measuredCharge(
            T0 + 3_000L, ActionKind.CAST, "Trident of the swamp",
            new Flow(DEATH, "Death rune", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE))).groups,
            "Death rune");
        assertNotNull(measured);
        assertTrue("a measured charge spend is charge use", measured.charge);
    }

    @Test
    public void estimatedScytheChargeWearsTheSpentComponent()
    {
        Transaction estimate = estimatedCharge(T0 + 1_000L, "Scythe of vitur",
            new Flow(BLOOD, "Blood rune", -2L, 100, -200L, PriceSource.GRAND_EXCHANGE));

        Semantics.Group charge = named(capture(estimate).groups, "Scythe of vitur");
        assertNotNull(charge);
        assertTrue("a scythe estimate is charge use", charge.charge);
        assertEquals("a charge row wears what it spent (owner live 2026-10-13)",
            BLOOD, charge.item);
    }

    @Test
    public void aMultiComponentChargeWearsTheWeapon()
    {
        // Owner live 2026-10-14: the sailors' amulet's cast spends law and water runes; no single
