    }

    private static Transaction planting(long at, Flow... extra)
    {
        List<Flow> flows = new ArrayList<>();
        flows.add(new Flow(31_481, "Camphor sapling", -1L, 7_507, -7_507L, PriceSource.GRAND_EXCHANGE));
        flows.addAll(Arrays.asList(extra));
