    static String rows(GrindsPage page) { return String.join(" ", TableRows.of(page.mine, "MY GRINDS")); }
    static Component firstVisible(JComponent root) { for (Component c : root.getComponents()) if (c.isVisible()) return c; return null; }
    static Rectangle bounds(Component child, JComponent root) { return SwingUtilities.convertRectangle(child.getParent(), child.getBounds(), root); }
    static void size(JComponent component, int width) { component.setSize(width, component.getPreferredSize().height); ActivityHeaderLayoutTest.layout(component); }
    static void resize(Component component) { component.dispatchEvent(new ComponentEvent(component, ComponentEvent.COMPONENT_RESIZED)); }
    static void click(Component component) { click(component, MouseEvent.BUTTON1); }
    static void click(Component component, int button) { for (MouseListener listener : component.getMouseListeners()) listener.mouseClicked(new MouseEvent(component, MouseEvent.MOUSE_CLICKED, NOW, 0, 1, 1, 1, false, button)); }
    static AbstractButton find(Component root, String text) {
        if (root instanceof AbstractButton && text.equals(((AbstractButton) root).getText())) return (AbstractButton) root;
        if (root instanceof Container) for (Component c : ((Container) root).getComponents()) { AbstractButton found = find(c, text); if (found != null) return found; }
        return null;
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.awt.Component;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JMenu;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static com.gpmanager.SwingTestSupport.onEdt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * An applied factory reset clears the bound HUD+ trip through the real menu/confirm path; a refused
 * one leaves it exactly as it was.
 */
public class FactoryResetPresentationTest
{
    @Rule
    public final TemporaryFolder temporary = new TemporaryFolder();

    private final AtomicReference<SidebarPanel> panel = new AtomicReference<>();

    @Test
    public void appliedFactoryResetClearsTheBoundHudTrip() throws Exception
    {
        JsonCodec.bind(new Gson());
        GpManagerConfig config = testConfig();
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        Engine engine = new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        Persistence coordinator = new Persistence(null,
            IsolatedConfigManager.create("rsprofile.alice"), repository, writer, engine);
        try
        {
            coordinator.start();
            assertTrue(coordinator.switchIdentity(new TrackingIdentity("rsprofile.alice", TrackingIdentity.ACCOUNT_HASH_INVALID), true));

            long now = System.currentTimeMillis();
            engine.ensureSession(now);
            HudBuilder builder = axn(config, engine, repository, coordinator);
            render(builder, engine, now);
            bookLoot(builder, now + 1L);
            HudFrame before = render(builder, engine, now + 2L);
            assertFalse("booked loot shows before the reset", before.rows.isEmpty());

            onEdt(() ->
            {
                resetThroughTheMenu(panel.get());
                return null;
            });
            PersistenceProbe.drain(coordinator, 2);

            HudFrame after = render(builder, engine, now + 12L);
            assertTrue("the applied reset clears the tray", after.rows.isEmpty());
            assertEquals("the applied reset clears the trip chip", "", after.trip);

            onEdt(() ->
            {
                SidebarPanelProbe.refresh(panel.get());
                return null;
            });
            LivePage live = (LivePage) SidebarPanelProbe.livePage(panel.get());
            assertFalse("after a reset the status gem starts tracking; no Start button",
                LivePageProbe.hasTrackingButton(live.body()));
        }
        finally
        {
            coordinator.shutdown();
        }
    }

    @Test
    public void refusedFactoryResetLeavesTheBoundHudTripAlone() throws Exception
    {
        JsonCodec.bind(new Gson());
        GpManagerConfig config = testConfig();
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        Engine engine = new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        // No bound identity: the coordinator refuses the destructive replace.
        Persistence coordinator = new Persistence(null, null, repository, writer, engine);
        try
        {
            coordinator.start();
            long now = System.currentTimeMillis();
            engine.ensureSession(now);
            HudBuilder builder = axn(config, engine, repository, coordinator);
            render(builder, engine, now);
            bookLoot(builder, now + 1L);
            assertFalse(render(builder, engine, now + 2L).rows.isEmpty());

            onEdt(() ->
            {
                resetThroughTheMenu(panel.get());
                return null;
            });
            PersistenceProbe.drain(coordinator, 2);

            HudFrame after = render(builder, engine, now + 12L);
            assertFalse("a refused reset keeps the tray", after.rows.isEmpty());
        }
        finally
        {
            coordinator.shutdown();
        }
    }

    private HudBuilder axn(GpManagerConfig config, Engine engine, SessionRepository repository,
        Persistence coordinator) throws Exception
    {
        return onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, config, null, repository, coordinator);
            HudBuilder builder = new HudBuilder(config, null);
            created.bindHud(builder);
            panel.set(created);
            return builder;
        });
    }

    private static void bookLoot(HudBuilder builder, long now)
    {
        for (int k = 0; k < 3; k++)
        {
            builder.tray.kill("Vorkath", now + k, false);
        }
        builder.tray.booked(receipt(now, flow(11286, "Draconic visage", 1L, 2_500_000)), now, false, now);
    }

    private static HudFrame render(HudBuilder builder, Engine engine, long now) throws Exception
    {
        return onEdt(() -> builder.update(LiveSnapshot.capture(engine, now, null), f -> true, now));
    }

    private static void resetThroughTheMenu(SidebarPanel panel)
    {
        JMenuItem reset = find(SidebarPanelProbe.dataMenu(panel), "Delete Profile");
        assertNotNull("the reset action is present", reset);
        assertTrue("the reset action is enabled", reset.isEnabled());
        reset.doClick();
        assertEquals("Delete Profile", ShellProbe.sheetTitle(panel.shell));
        ShellProbe.pressSheet(panel.shell, "Back up & delete");
        assertEquals("the sheet closes once the reset ran", "", ShellProbe.sheetTitle(panel.shell));
    }

    private static JMenuItem find(JPopupMenu menu, String textPrefix)
    {
        return find(menu.getComponents(), textPrefix);
    }

    private static JMenuItem find(Component[] components, String textPrefix)
    {
        for (Component component : components)
        {
            if (component instanceof JMenu)
            {
                JMenuItem nested = find(((JMenu) component).getMenuComponents(), textPrefix);
                if (nested != null)
                {
                    return nested;
                }
            }
            else if (component instanceof JMenuItem && ((JMenuItem) component).getText() != null
                && ((JMenuItem) component).getText().startsWith(textPrefix))
            {
                return (JMenuItem) component;
            }
        }
        return null;
    }

    private static Transaction receipt(long at, Flow... flows)
    {
        return new Transaction(at, TransactionType.LOOT, Context.LOOT, "", "Vorkath", true,
            Arrays.asList(flows), Confidence.CONFIRMED, "fixture", null);
    }

    private static Flow flow(int id, String name, long quantity, int unit)
    {
        return new Flow(id, name, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE);
    }

    private static GpManagerConfig testConfig()
    {
        return new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
    }

}

