package com.gpmanager;

import java.util.Collections;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** R4 recap: biggest gain and cost and loot by source, derived and factual. */
public class GrindRecapTest
{

    private static Transaction loot(String npc, long at, long value)
    {
        return new Transaction(at, TransactionType.LOOT, Context.LOOT, "Loot from " + npc, npc, true,
            Collections.singletonList(new Flow(1, "Loot", 1L, (int) value, value)), Confidence.CONFIRMED,
            "fixture", null);
    }

    @Test
    public void recapMatchesTheCanonicalSummaryAndKeepsFullSessionRate() throws Exception
    {
        Engine engine = engine();
        long now = System.currentTimeMillis();
        long start = now - 2 * 3_600_000L;
        String grindId = runGrind(engine, "Vorkath", start, now, 6_000_000L, 500_000L, 5_000_000L,
            3L * 3_600_000L);
        Session session = engine.history().get(0);
        assertEquals(grindId, session.grindId());

        Metrics metrics = engine.historyMetrics(session.id(), now);
        String aay = GrindHistory.netOutcome(session.targetGp(), metrics.net, true);
        String akd = GrindHistory.timeOutcome(session.timeTargetMillis(),
            metrics.elapsed);
        assertTrue(aay.contains("Reached"));
        assertTrue(akd.contains("remaining"));
        assertFalse("the word Failed never appears", aay.contains("Failed"));
        assertFalse(akd.contains("Failed"));
    }

    @Test
    public void targetOutcomesAreFactualForEveryCombination() throws Exception
    {
        Engine engine = engine();
        long now = System.currentTimeMillis();
        long start = now - 3_600_000L;
        runGrind(engine, "Vorkath", start, now, 2_000_000L, 0L, 5_000_000L, 3L * 3_600_000L);
        Session session = engine.history().get(0);
        Metrics metrics = engine.historyMetrics(session.id(), now);
        String aay = GrindHistory.netOutcome(session.targetGp(), metrics.net, true);
        String akd = GrindHistory.timeOutcome(session.timeTargetMillis(),
            metrics.elapsed);

        assertTrue("not reached is stated factually: " + aay, aay.contains("Ended before target"));
        assertTrue("time target is still open: " + akd, akd.contains("remaining"));
        assertFalse(aay.toLowerCase().contains("fail"));
        assertFalse(akd.toLowerCase().contains("fail"));
        assertEquals("Reached 5.00M Net",
            GrindHistory.netOutcome(5_000_000L, 6_000_000L, true));
        assertEquals("No Net target", GrindHistory.netOutcome(null, 1L, true));
        assertEquals("Time target reached", GrindHistory.timeOutcome(60_000L, 120_000L));
        assertEquals("No Active Time target", GrindHistory.timeOutcome(null, 120_000L));
    }




    private static void collectLabelColours(java.awt.Component component,
        java.util.Map<String, java.awt.Color> out)
    {
        if (component instanceof javax.swing.JLabel)
        {
            String text = ((javax.swing.JLabel) component).getText();
            if (text != null && !text.isEmpty())
            {
                out.putIfAbsent(text, ((javax.swing.JLabel) component).getForeground());
            }
        }
        if (component instanceof java.awt.Container)
        {
            for (java.awt.Component child : ((java.awt.Container) component).getComponents())
            {
                collectLabelColours(child, out);
            }
        }
    }

    // ---- helpers ----------------------------------------------------------------------------

    private static Engine engine()
    {
        return PresentationLifecycleTest.engine();
    }

    private static String runGrind(Engine engine, String name, long start, long end, long gainValue,
        long costValue, Long netTarget, Long timeTarget)
    {
        SavedState.SavedGrind definition = engine.saveGrind(name, netTarget, timeTarget, false);
        String grindId = definition.id();
        engine.startGrind(name, grindId, netTarget, timeTarget, start);
        if (gainValue != 0L)
        {
            engine.session().addTransaction(
                gain(start + 1_000L, "Dragon bones", 1, 1, (int) gainValue, gainValue), 2_000, false);
        }
        if (costValue != 0L)
        {
            Transaction consumed = cost(start + 2_000L, "Prayer potion(4)", 3, costValue);
            consumed.setAction(ActionKind.DRINK);
            engine.session().addTransaction(consumed, 2_000, false);
        }
        engine.finishCustom(end);
        return grindId;
    }

    private static Transaction gain(long at, String name, int itemId, long quantity, int unitPrice, long value)
    {
        return receipt(at, TransactionType.GAIN, name, itemId, quantity, unitPrice, value);
    }

    private static Transaction cost(long at, String name, int itemId, long value)
    {
        return receipt(at, TransactionType.CONSUMPTION, name, itemId, -1L, (int) Math.abs(value), -Math.abs(value));
    }

    private static Transaction receipt(long at, TransactionType type, String name, int itemId, long quantity,
        int unitPrice, long value)
    {
        return new Transaction(at, type, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value)),
            Confidence.LIKELY, "test", null);
    }

    private static void collectLabels(java.awt.Component component, java.util.List<String> out)
    {
        if (component instanceof javax.swing.JLabel)
        {
            String text = ((javax.swing.JLabel) component).getText();
            if (text != null && !text.isEmpty())
            {
                out.add(text);
            }
        }
        if (component instanceof java.awt.Container)
        {
            for (java.awt.Component child : ((java.awt.Container) component).getComponents())
            {
                collectLabels(child, out);
            }
        }
    }

}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class GrindRollupOverflowTest {
    private static final long NOW = 1_700_000_000_000L;
    private static final long UNIT = 1_000_000_000_000_000_000L;

    private static List<Session> runs(long... values) {
        var engine = ReviewFixesTest.engine();
        for (int index = 0; index < values.length; index++) {
            long at = NOW + index * 60_000;
            engine.startCustom("Run " + index, at);
            long value = values[index];
            engine.session().addTransaction(Tx.of(at + 1,
                    value >= 0 ? TransactionType.GAIN : TransactionType.CONSUMPTION, Context.GENERIC, "", true,
                    List.of(new Flow(526, "Bones", value >= 0 ? 1 : -1, SafeMath.abs(value), value,
                            PriceSource.MANUAL_OVERRIDE))), 2000, false);
            engine.finishCustom(at + 60_000);
        }
        return new ArrayList<>(engine.history());
    }

    private static MoneySnapshot.Rollup rollup(List<Session> sessions) {
        var engine = ReviewFixesTest.engine();
        engine.history.addAll(sessions);
        return engine.summary().new Rollup(sessions);
    }

    @Test public void positiveAndNegativeTotalsNeverWrapTheirSigns() {
        var positive = rollup(runs(4 * UNIT, 4 * UNIT, 4 * UNIT));
        assertEquals(Long.MAX_VALUE, positive.total);
        assertTrue(Session.hourly(positive.total, positive.millis) > 0);
        var negative = rollup(runs(-4 * UNIT, -4 * UNIT, -4 * UNIT));
        assertEquals(-Long.MAX_VALUE, negative.total);
        assertTrue(Session.hourly(negative.total, negative.millis) < 0);
    }

    @Test public void mixedSignsUseOneBoundedFoldInBothRunOrders() {
        var sessions = runs(4 * UNIT, 4 * UNIT, 4 * UNIT, -4 * UNIT);
        assertEquals(Long.MAX_VALUE - 4 * UNIT, rollup(sessions).total);
        Collections.reverse(sessions);
        assertEquals(Long.MAX_VALUE - 4 * UNIT, rollup(sessions).total);
    }

    @Test public void durationAdditionSaturatesWithoutChangingRunSelection() {
        var sessions = runs(10, 20, 30);
        sessions.forEach(session -> session.savedActiveMillis = 4 * UNIT);
        var total = rollup(sessions);
        assertEquals(Long.MAX_VALUE, total.millis);
        assertEquals(60, total.total);
        assertEquals(3, total.count);
        assertEquals(30, total.last);
        assertEquals(30, total.best);
        assertEquals(NOW + 120_000, total.at);
    }

    @Test public void ordinaryAndEmptyRunsKeepTheirOriginalAverageAndFlags() {
        var ordinary = rollup(runs(100, -40, 30));
        assertEquals(90, ordinary.total);
        assertEquals(180_000, ordinary.millis);
        assertEquals(1800, Session.hourly(ordinary.total, ordinary.millis));
        assertEquals(100, ordinary.best);
        assertEquals(30, ordinary.last);
        assertTrue(ordinary.has);
        var empty = rollup(List.of());
        assertEquals(0, empty.total);
        assertEquals(0, empty.millis);
        assertEquals(0, empty.count);
        assertFalse(empty.has);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.*;

/** History already captured by identity must not be searched again for every displayed row. */
public class GrindsHistoryLookupTest {
    private static final long NOW = 1_700_000_000_000L;

    static class Probe extends Engine {
        int lookups;

        Probe() {
            super(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        }

        @Override synchronized Session historySession(String id) {
            lookups++;
            return super.historySession(id);
        }
    }

    static Transaction gain(long at, long quantity) {
        return Tx.of(at, TransactionType.GAIN, Context.GENERIC, "", true,
                Collections.singletonList(new Flow(995, "Coins", quantity, 1, quantity)));
    }

    @Test public void aFullGrindsCaptureDoesNotRescanHistoryForEveryCanonicalSession() {
        var engine = new Probe();
        for (int index = 0; index < 2_000; index++) {
            var session = new Session("Run " + index, NOW - (index + 1L) * 100_000L, SessionMode.GENERAL);
            session.addTransaction(gain(session.startedAt, 500), 2_000, false);
            session.close(session.startedAt + 60_000L);
            engine.history.add(session);
        }
        engine.startCustom("Current", NOW);
        engine.session().addTransaction(gain(NOW, 1_000), 2_000, false);
        var view = GrindsData.capture(engine, NOW + 60_000L, false, null);
        assertEquals(2_000, view.recent.size());
        assertEquals(1_001_000L, view.overall.net);
        assertEquals(1_000L, view.activeNet);
        assertEquals("already captured canonical sessions need no history lookup", 0, engine.lookups);
    }

    @Test public void anAliasStillUsesTheRetainedHistoricalCopy() {
        var engine = new Probe();
        var retained = new Session("Retained", NOW, SessionMode.GENERAL);
        retained.addTransaction(gain(NOW, 500), 2_000, false);
        retained.close(NOW + 60_000L);
        var alias = SaveCopies.copy(retained);
        alias.addTransaction(gain(NOW + 1, 900), 2_000, false);
        engine.history.add(retained);
        var snapshot = engine.summary();
        assertEquals(500, snapshot.run(engine, alias, NOW + 120_000L).net());
        assertEquals("an uncaptured alias keeps the history fallback", 1, engine.lookups);
        assertEquals(500, snapshot.run(engine, retained, NOW + 120_000L).net());
        assertEquals("the canonical copy reuses its captured facts", 1, engine.lookups);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** My Grinds persistence: one additive schema step inside the canonical state, truthful lineage. */
public class GrindsPersistenceTest
{
    /** The plugin loads every profile through agl, never through restore. */
    @Test
    public void profileLoadKeepsThatProfilesGrindsAndNoOtherProfiles() throws Exception
    {
        JsonCodec.bind(new com.google.gson.Gson());
        Engine source = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        SavedState.SavedGrind grind = source.saveGrind("Vorkath", 5_000_000L, null, true);
        assertNotNull(grind);
        SavedState alice = source.savedState();

        Engine live = PresentationLifecycleTest.engine();
        live.restoreProfile("alice", alice, now);
        assertEquals("a loaded profile shows its Grinds", 1, live.plans(true).size());
        assertEquals("and the next save keeps them", 1, live.savedState().savedGrinds().size());

        live.restoreProfile("bob", new SavedState(), now + 1_000L);
        assertEquals("another profile never inherits them", 0, live.plans(true).size());
        assertEquals(0, live.savedState().savedGrinds().size());
    }

    @Test
    public void schemaIsAdditiveAndFutureVersionsStayReadOnly() throws Exception
    {
        assertEquals(110, SavedState.CURRENT_SCHEMA_VERSION);
        SavedState old = new SavedState();
        old.setSchemaVersion(103);
        assertFalse("pre-1.0 states are never read", old.isSupportedSchema());
        assertFalse((old.schemaVersion > SavedState.CURRENT_SCHEMA_VERSION));
        SavedState future = new SavedState();
        future.setSchemaVersion(SavedState.CURRENT_SCHEMA_VERSION + 1);
        assertTrue((future.schemaVersion > SavedState.CURRENT_SCHEMA_VERSION));
        assertFalse("a newer state is never written back", future.isSupportedSchema());
    }

    @Test
    public void schema102UpgradeLeavesFinancialTotalsUntouchedAndAddsEmptyGrindState() throws Exception
    {
        Engine source = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        source.startCustom("Legacy grind", now);
        source.session().addTransaction(booked(now + 1_000L, "Dragon bones", 1, 2, 3_200, 6_400), 2_000, false);
        source.finishCustom(now + 2_000L);
        SavedState legacy = source.savedState();
        legacy.setSchemaVersion(102);

        Engine upgraded = PresentationLifecycleTest.engine();
        upgraded.restore(legacy, now + 3_000L);
        assertEquals("no inference during upgrade", 0, upgraded.plans(true).size());
        assertEquals("history survives", 1, upgraded.history().size());
        assertEquals("financial totals are untouched", 6_400L,
            upgraded.historyMetrics(upgraded.history().get(0).id(), now + 3_000L).net);
        assertFalse("old sessions are not auto-linked",
            upgraded.history().get(0).isLinked());
    }

    @Test
    public void noRetroactiveNameMatchingDuringRestore() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(booked(now + 1_000L, "Dragon bones", 1, 1, 3_200, 3_200), 2_000, false);
        engine.finishCustom(now + 2_000L);
        SavedState state = engine.savedState();
        SavedState.SavedGrind grind = engine.saveGrind("Vorkath", null, null, false);
        assertNotNull(grind);
        state.setSavedGrinds(engine.plans(true));

        Engine restored = PresentationLifecycleTest.engine();
        restored.restore(state, now + 3_000L);
        assertEquals(1, restored.plans(true).size());
        assertEquals("display names never link history", 0,
            restored.linkedSessions(grind.id()).size());
    }

    @Test
    public void nativeRoundTripKeepsGrindsTargetsAndLineage() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now - 60_000L);
        engine.session().setNetTarget(5_000_000L, 0, 0);
        engine.session().setTimeTarget(3L * 3_600_000L, now);
        long setAt = engine.session().timeSetMillis();
        engine.session().pauseTimeTarget(now + 500L);
        engine.session().profitTargetSetNet = 12_345L;
        String sessionId = engine.session().id();
        SavedState.SavedGrind grind = engine.saveGrind("Vorkath", 5_000_000L, 3L * 3_600_000L, true);
        engine.session().setGrindId(grind.id());
        assertNotNull(grind);
        engine.finishCustom(now + 1_000L);
        SavedState state = engine.savedState();

        Engine restored = PresentationLifecycleTest.engine();
        restored.restore(state, now + 2_000L);
        SavedState.SavedGrind reloaded = restored.plan(grind.id());
        assertNotNull("the definition round-trips", reloaded);
        assertEquals("Vorkath", reloaded.name());
        assertEquals(Long.valueOf(5_000_000L), reloaded.targetGp());
        assertEquals(Long.valueOf(3L * 3_600_000L), reloaded.timeTargetMillis());
        assertTrue(reloaded.favorite);
        assertEquals("lineage round-trips by stable id", 1,
            restored.linkedSessions(grind.id()).size());
        assertEquals("the actual target snapshot round-trips", Long.valueOf(5_000_000L),
            restored.historySession(sessionId).targetGp());
        assertEquals(Long.valueOf(3L * 3_600_000L),
            restored.historySession(sessionId).timeTargetMillis());
        assertEquals("the count baseline round-trips", setAt,
            restored.historySession(sessionId).timeSetMillis());
        assertTrue("the timer pause round-trips",
            restored.historySession(sessionId).timeTargetPaused());
        assertEquals("the Net baseline round-trips", 12_345L,
            restored.historySession(sessionId).profitTargetSetNet());
    }

    @Test
    public void savedGrindsAreProfileScoped() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        SavedState profileA = engine.savedState();
        engine.saveGrind("Vorkath", 5_000_000L, null, false);
        profileA = engine.savedState();

        SavedState profileB = new SavedState();
        profileB.setOwnerKey("profile-b");

        engine.restore(profileA, System.currentTimeMillis());
        assertEquals("profile A sees exactly its own state", 1, engine.plans(true).size());
        engine.restore(profileB, System.currentTimeMillis());
        assertEquals("profile B never sees A's My Grinds", 0, engine.plans(true).size());
        engine.restore(profileA, System.currentTimeMillis());
        assertEquals(1, engine.plans(true).size());
    }

    @Test
    public void newFieldsDefaultSafelyOnLegacyShapes() throws Exception
    {
        SavedState legacy = new SavedState();
        legacy.setSchemaVersion(102);
        assertTrue("no NPE on a legacy state without the list", legacy.savedGrinds().isEmpty());

        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        assertEquals("no inferred lineage for a new instance", "", engine.session().grindId());
        assertNull(engine.session().timeTargetMillis());
        engine.session().setGrindId(null);
        assertEquals("", engine.session().grindId());
        engine.session().setTimeTarget(null, now);
        assertNull(engine.session().timeTargetMillis());
        assertEquals("clearing forgets the count", 0L,
            engine.session().timeSetMillis());
    }

    @Test
    public void clearingTargetsWorksWithoutTouchingFinancialState() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(booked(now + 1_000L, "Dragon bones", 1, 1, 3_200, 3_200), 2_000, false);
        engine.setTargets(5_000_000L, 3L * 3_600_000L, now + 2_000L);
        long net = engine.metrics(now + 2_000L).net;
        engine.setTargets(null, null, now + 3_000L);
        assertNull(engine.session().targetGp());
        assertNull(engine.session().timeTargetMillis());
        assertEquals("clearing a target changes no money", net, engine.metrics(now + 3_000L).net);
    }

    private static Transaction booked(long at, String name, int itemId, long quantity, int unitPrice, long value)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value)),
            Confidence.LIKELY, "Test sample.", null);
    }
}

