        {
            super(null, null, null, null, null);
        }

        @Override
        Persistence.ResetOutcome factoryReset(long now, boolean backup)
        {
            calls.add("reset");
            return new Persistence.ResetOutcome(!refuse, refuse ? "disk full" : "");
        }
    }

