    @Test
    public void aBookingAfterThePreviewSplitsNothing() throws Exception
    {
        Fixture fixture = new Fixture();
        Transaction transaction = fixture.book(new Flow(536, "Dragon bones", 4L, 2_000, 8_000L));
        fixture.confirm = false;
        fixture.split(transaction.id());
        fixture.type("1");
        fixture.press("OK");
        fixture.book(new Flow(995, "Coins", 10L, 1, 10L));

        onEdt(() ->
        {
            fixture.controller.applySplit(transaction.id(), fixture.pending, fixture.previewed.revision);
            return null;
        });
        assertTrue(ShellProbe.noticeText(fixture.shell()).startsWith("Not split"));
        assertEquals(4L, transaction.quantity(536, true));
    }

    private static final class Fixture
    {
        final Engine engine;
        final SidebarPanel panel;
        final LedgerController controller;

        Fixture() throws Exception
        {
            this(new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
                new GpManagerConfig() {}));
        }

        Fixture(Engine engine) throws Exception
        {
            this.engine = engine;
            JsonCodec.bind(new com.google.gson.Gson());
            panel = onEdt(() -> new SidebarPanel(engine, new GpManagerConfig() {}, null, null, null));
            controller = new LedgerController(panel);
            engine.startCustom("Vorkath", NOW);
        }

        Shell shell()
        {
            return panel.shell;
        }

        Transaction book(Flow... flows)
        {
            Transaction transaction = new Transaction(NOW + 1_000L, TransactionType.LOOT, Context.LOOT, "", "Vorkath", true,
                Arrays.asList(flows), Confidence.CONFIRMED, "fixture", null);
            engine.session().addTransaction(transaction, 2_000, false);
            return transaction;
        }

        LedgerData.CorrectionPreview previewed;
        long[] pending;
        boolean confirm = true;

        void split(String transactionId) throws Exception
        {
            onEdt(() ->
            {
                // Owner 1.1: the split previews first; this harness confirms at once.
                controller.split(transactionId, (split, preview) ->
                {
                    previewed = preview;
                    pending = split;
                    if (confirm) controller.applySplit(transactionId, split, preview.revision);
                });
                return null;
            });
        }

        void type(String text) throws Exception
        {
            onEdt(() ->
            {
                ShellProbe.typeSheet(panel.shell, text);
                return null;
            });
        }

        void press(String label) throws Exception
        {
            onEdt(() ->
            {
                ShellProbe.pressSheet(panel.shell, label);
                return null;
            });
        }

        void closeAndStartAnotherRun()
        {
            engine.finishCustom(NOW + 2_000L);
            engine.startCustom("Other", NOW + 3_000L);
        }
    }

    /** Refuses every split, so the controller's refusal feedback can be pinned. */
    private static final class RefusingEngine extends Engine
    {
        RefusingEngine()
        {
            super(deltas -> Collections.emptyList(), new TransactionClassifier(),
                new GpManagerConfig() {});
        }

        @Override
        synchronized boolean splitItem(String transactionId, int itemId, long keepQuantity,
            String optionalNote)
        {
            return false;
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        Object[] result = new Object[1];
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result[0] = callable.call();
            }
            catch (Exception ex)
            {
                throw new RuntimeException(ex);
            }
        });
        return (T) result[0];
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.awt.Component;
import java.util.Collections;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-01 (F01): undo mutates the live run only. Historical and Today scopes
 * disable it, and a menu opened while Current cannot mutate after a scope or owner switch.
 */
public class LedgerUndoScopeTest
{
    static
    {
        JsonCodec.bind(new Gson());
    }

    private static final long NOW = 1_700_000_000_000L;

    @Test
    public void historicalAndTodayDisableUndoWhileCurrentEnablesIt()
    {
        Fixture fixture = new Fixture();
        fixture.apply(LedgerData.Entry.current());
        JPopupMenu current = fixture.page().moreMenu();
        assertTrue(undo(current, "Undo latest correction").isEnabled());
        assertTrue(undo(current, "Undo last change").isEnabled());
        assertTrue(undo(current, "Restore last undo").isEnabled());

        fixture.apply(LedgerData.Entry.current().withScope(LedgerData.Scope.HISTORY, "past-run", "Past run"));
        JPopupMenu historical = fixture.page().moreMenu();
        assertFalse(undo(historical, "Undo latest correction").isEnabled());
        assertFalse(undo(historical, "Undo last change").isEnabled());
        assertFalse(undo(historical, "Restore last undo").isEnabled());

        fixture.apply(LedgerData.Entry.current().withScope(LedgerData.Scope.TODAY, null, null));
        assertFalse(undo(fixture.page().moreMenu(), "Undo last change").isEnabled());
    }

    @Test
    public void aStaleMenuCannotMutateAfterAScopeSwitch()
    {
        Fixture fixture = new Fixture();
        fixture.apply(LedgerData.Entry.current());
        JMenuItem undoLast = undo(fixture.page().moreMenu(), "Undo last change");
        assertTrue(undoLast.isEnabled());

        fixture.apply(LedgerData.Entry.current().withScope(LedgerData.Scope.HISTORY, "past-run", "Past run"));
        undoLast.doClick();

        assertEquals("an open menu must not undo across a scope switch", 0, fixture.engine.lastChanges);
    }

    @Test
    public void currentScopeStillUndoesAllThreeOperations()
    {
        Fixture fixture = new Fixture();
        fixture.apply(LedgerData.Entry.current());
        undo(fixture.page().moreMenu(), "Undo latest correction").doClick();
        undo(fixture.page().moreMenu(), "Undo last change").doClick();
        undo(fixture.page().moreMenu(), "Restore last undo").doClick();

        assertEquals(1, fixture.engine.corrections);
        assertEquals(1, fixture.engine.lastChanges);
        assertEquals(1, fixture.engine.restores);
    }

    @Test
    public void anOwnerSwitchLeavesAnOpenMenuInert()
    {
        Fixture fixture = new Fixture();
        fixture.apply(LedgerData.Entry.current());
        JMenuItem undoLast = undo(fixture.page().moreMenu(), "Undo last change");

        fixture.engine.restoreProfile("profile-b", new SavedState(), NOW + 1_000L);
        undoLast.doClick();

        assertEquals("an open menu must not undo another owner's run", 0, fixture.engine.lastChanges);
    }

    private static JMenuItem undo(JPopupMenu menu, String text)
    {
        for (Component component : menu.getComponents())
        {
            if (component instanceof JMenuItem && text.equals(((JMenuItem) component).getText()))
            {
                return (JMenuItem) component;
            }
        }
        throw new AssertionError("missing menu item: " + text);
    }

    private static final class Fixture
    {
        final UndoSpy engine = new UndoSpy();
        final SidebarPanel panel;

        Fixture()
        {
            try
            {
                SidebarPanel[] holder = new SidebarPanel[1];
                SwingUtilities.invokeAndWait(() -> holder[0] = new SidebarPanel(engine, new GpManagerConfig() {}, null, null, null));
                panel = holder[0];
            }
            catch (Exception ex)
            {
                throw new AssertionError(ex);
            }
            engine.ensureSession(NOW);
        }

        LedgerPage page()
        {
            return panel.ledger;
        }

        void apply(LedgerData.Entry entry)
        {
            panel.scope = entry;
            panel.ledger.apply(LedgerData.capture(engine, NOW + 10L, entry));
        }
    }

    /** Counts the engine mutations the controller would perform. */
    private static final class UndoSpy extends Engine
    {
        int corrections;
        int lastChanges;
        int restores;

        UndoSpy()
        {
            super(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        }

        @Override
        synchronized boolean undoCorrection()
        {
            corrections++;
            return true;
        }

        @Override
        synchronized Transaction undoTransaction()
        {
            lastChanges++;
            return null;
        }

        @Override
        synchronized Transaction restoreUndo()
        {
            restores++;
            return null;
        }
    }
}

package com.gpmanager;

import java.util.Collections;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Owner 2026-10-01 (F23): a hop says Reconnecting; a logout says Logged out. */
public class LifecycleWordTest
{
    private static final long NOW = 1_700_000_000_000L;

    @Test
    public void aHopSaysReconnectingWhileALogoutSaysLoggedOut() throws Exception
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", NOW);
        engine.pauseForLifecycle(NOW + 1_000L);

        LiveSnapshot hop = LiveSnapshot.capture(engine, NOW + 2_000L, context(false, true));
        assertTrue("the lifecycle pause still holds", hop.offline);
        assertEquals("RECONNECTING", LivePage.wordOf(hop));
        assertTrue(LivePage.statusTooltip(hop).startsWith("Reconnecting"));

        LiveSnapshot out = LiveSnapshot.capture(engine, NOW + 2_000L, context(true, false));
        assertEquals("LOGGED OUT", LivePage.wordOf(out));

        engine.resume(NOW + 3_000L, PauseReason.LIFECYCLE);
        assertEquals("the resume cue takes over", "CALIBRATING",
            LivePage.wordOf(LiveSnapshot.capture(engine, NOW + 3_100L, context(false, false))));
        assertEquals("then tracking is plainly live", "",
            LivePage.wordOf(LiveSnapshot.capture(engine, NOW + 6_000L, context(false, false))));
    }

    @Test
    public void aManualPauseSurvivesLifecycleResumeAndKeepsItsWord() throws Exception
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", NOW);
        engine.togglePause(NOW + 1_000L);
        engine.resume(NOW + 2_000L, PauseReason.LIFECYCLE);
        assertTrue("a manual pause never becomes an automatic resume",
            engine.session().paused);
        assertEquals("PAUSED",
            LivePage.wordOf(LiveSnapshot.capture(engine, NOW + 2_100L, context(false, false))));
    }

    @Test
    public void theSidebarReadsTheHopSupplier() throws Exception
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", NOW);
        engine.pauseForLifecycle(NOW + 1_000L);
        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine, new GpManagerConfig() {}, null, null, null));
        onEdt(() ->
        {
            panel.bindHopping(() -> true);
            SidebarPanelProbe.refresh(panel);
            return null;
        });
        assertEquals("RECONNECTING", LivePage.wordOf(SidebarPanelProbe.live(panel)));
    }

    private static LiveContext context(boolean offline, boolean hopping)
    {
        return new LiveContext(false, null, 0L, PvpState.NONE, "", offline, "", hopping);
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig() {});
    }

    @SuppressWarnings("unchecked")
    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        Object[] result = new Object[1];
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result[0] = callable.call();
            }
            catch (Exception ex)
            {
                throw new RuntimeException(ex);
            }
        });
        return (T) result[0];
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/** Recent Activity uses the item/action evidence that the settled receipt actually carries. */
public class LiveActionWordingTest
{
    @Test
    public void exactSpellNameAndGenericFallbackRenderWithoutSearchCoupling() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        Transaction exact = cast(now + 1L, "Ice Burst",
            rune("Death rune", 560, -1L, -100L), rune("Chaos rune", 562, -1L, -50L),
            rune("Water rune", 555, -1L, -30L));
        exact.setActionLabel(ActionLabel.of("Ice Burst"));
        Transaction generic = cast(now + 2L, "",
            rune("Death rune", 560, -1L, -100L), rune("Chaos rune", 562, -1L, -50L),
            rune("Water rune", 555, -1L, -30L));
        engine.session().addTransaction(exact, 2_000, false);
        engine.session().addTransaction(generic, 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, now + 10L, LiveContext.NONE);
        LiveSnapshot.Recent exactRow = snapshot.recent.stream()
            .filter(row -> row.receiptId.equals(exact.id())).findFirst().orElseThrow(AssertionError::new);
        LiveSnapshot.Recent genericRow = snapshot.recent.stream()
            .filter(row -> row.receiptId.equals(generic.id())).findFirst().orElseThrow(AssertionError::new);
        assertEquals("Ice Burst", exactRow.name);
        assertEquals("Cast", LivePage.metaOf(exactRow));
        assertEquals("Cast", genericRow.name);
        assertEquals("3 rune types", LivePage.metaOf(genericRow));

        LedgerData.Entry deepLink = LivePage.entryFor(exactRow);
        assertEquals("deep link has no hidden action-name search", "", deepLink.search);
        assertEquals("an exact Cast links to Costs/Supplies",
            LedgerData.CostView.SUPPLIES, exactRow.cost);
        LedgerData linked = LedgerData.capture(engine, now + 10L, deepLink);
        assertNotNull("the stable receipt opens its semantic group", linked.detail);
        assertTrue(linked.detail.group.containsContribution(exactRow.id));

        LedgerData searched = LedgerData.capture(engine, now + 10L,
            new LedgerData.Entry(LedgerData.Scope.CURRENT_GRIND, null, null,
                LedgerData.CostView.SUPPLIES, "Ice Burst", null, null, null, null));
        assertEquals("exact action text search keeps the whole group", 1, searched.cost.entries);
        assertEquals("Ice Burst", searched.cost.groups.get(0).name);
    }

    @Test
    public void supplyVerbsAndMeasuredWeaponsUseProvenNames() throws Exception
    {
        LiveSnapshot.Recent potion = recent(action(1L, ActionKind.DRINK,
            new Flow(2434, "Prayer potion(4)", -1L, 200, -200L),
            new Flow(139, "Prayer potion(3)", 1L, 175, 175L)));
        assertEquals("Prayer potion", potion.name);
        assertEquals("Drank · 1 dose", LivePage.metaOf(potion));

        LiveSnapshot.Recent food = recent(action(2L, ActionKind.EAT,
            new Flow(385, "Shark", -1L, 950, -950L)));
        assertEquals("Shark", food.name);
        assertEquals("Ate", LivePage.metaOf(food));

        LiveSnapshot.Recent partialFood = recent(action(3L, ActionKind.EAT,
            new Flow(2309, "Whole pineapple pizza", -1L, 1_000, -1_000L),
            new Flow(2313, "Half pineapple pizza", 1L, 500, 500L)));
        assertEquals("pineapple pizza", partialFood.name);
        assertEquals("Ate · 1 portion", LivePage.metaOf(partialFood));

        LiveSnapshot.Recent sapling = recent(action(30L, ActionKind.SUPPLIES,
            new Flow(5373, "Yew sapling", -3L, 22_800, -68_400L),
            new Flow(5350, "Empty plant pot", 3L, 8, 24L)));
        assertEquals("Yew sapling", sapling.name);
        assertEquals("a planted sapling is not a portion", "×3", sapling.qty);

        LiveSnapshot.Recent buried = recent(action(4L, ActionKind.BURY,
            new Flow(536, "Dragon bones", -1L, 2_000, -2_000L)));
        assertEquals("Dragon bones", buried.name);
        assertEquals("Buried", LivePage.metaOf(buried));

        LiveSnapshot.Recent offered = recent(action(5L, ActionKind.OFFER,
            new Flow(536, "Dragon bones", -1L, 2_000, -2_000L)));
        assertEquals("Offered", LivePage.metaOf(offered));

        LiveSnapshot.Recent ammo = recent(action(6L, ActionKind.FIRE,
            new Flow(892, "Rune arrow", -2L, 100, -200L)));
        assertEquals("Rune arrow", ammo.name);
        assertEquals("Fired · ×2", LivePage.metaOf(ammo));

        LiveSnapshot.Recent genericSupply = recent(action(7L, ActionKind.SUPPLIES,
            new Flow(1511, "Willow logs", -1L, 50, -50L)));
        assertEquals("Used", LivePage.metaOf(genericSupply));

        Transaction unsupported = transaction(8L,
            new Flow(385, "Shark", -1L, 950, -950L));
        LiveSnapshot.Recent unsupportedRow = recent(unsupported);
        assertEquals("Shark", unsupportedRow.name);
        assertEquals("unsupported evidence stays generic", "Used",
            LivePage.metaOf(unsupportedRow));

        Transaction blowpipe = action(9L, ActionKind.FIRE,
            new Flow(11230, "Dragon dart", -2L, 100, -200L),
            new Flow(12934, "Zulrah's scales", -1L, 110, -110L));
        blowpipe.note = "Measured charge spend \u00b7 Toxic blowpipe";
        List<LiveSnapshot.Recent> blowpipeRows = recents(blowpipe);
        assertEquals("owner 1.3.4: the darts as Supplies and the scales as a charge row", 2,
            blowpipeRows.size());
        LiveSnapshot.Recent darts = blowpipeRows.stream().filter(row -> "Dragon dart".equals(row.name))
            .findFirst().orElseThrow(AssertionError::new);
        assertEquals(LedgerData.CostView.SUPPLIES, darts.cost);
        LiveSnapshot.Recent scales = blowpipeRows.stream().filter(row -> "Zulrah's scales".equals(row.name))
            .findFirst().orElseThrow(AssertionError::new);
        assertEquals(LedgerData.CostView.CHARGES, scales.cost);

        Transaction trident = action(10L, ActionKind.CAST,
            rune("Death rune", 560, -1L, -100L), rune("Chaos rune", 562, -1L, -50L),
            rune("Soul rune", 566, -1L, -100L));
        trident.note = "Measured charge spend \u00b7 Trident of the swamp";
        List<LiveSnapshot.Recent> tridentRows = recents(trident);
        assertFalse("charge use is listed now (owner 1.3.4)", tridentRows.isEmpty());
        assertTrue("every trident row is a Ledger charge row",
            tridentRows.stream().allMatch(row -> row.cost == LedgerData.CostView.CHARGES));
    }

    private static List<LiveSnapshot.Recent> recents(Transaction transaction)
    {
        return LiveProbe.recent(Collections.singletonList(transaction), LiveContext.NONE);
    }

    private static LiveSnapshot.Recent rowNamed(List<LiveSnapshot.Recent> rows, String name)
    {
        for (LiveSnapshot.Recent row : rows)
        {
            if (name.equals(row.name))
            {
                return row;
            }
        }
        return null;
    }

    /** Owner 2026-09-28: autocast never clicks a spell, yet its row names the spell and shows its icon. */
    @Test
    public void anAutocastReadsAsItsSpellWithItsIcon()
    {
        List<Transaction> casts = Arrays.asList(
            action(1L, ActionKind.CAST, rune("Death rune", 560, -4L, -748L), rune("Blood rune", 565, -2L, -682L),
                rune("Water rune", 555, -6L, -30L)),
            action(2L, ActionKind.CAST, rune("Death rune", 560, -4L, -748L), rune("Blood rune", 565, -2L, -682L),
                rune("Water rune", 555, -6L, -30L)));
        List<LiveSnapshot.Recent> rows = LiveProbe.recent(casts, LiveContext.NONE);
        assertEquals("one row for the spell", 1, rows.size());
        assertEquals("Ice Barrage", rows.get(0).name);
        assertEquals("the spellbook icon", -328, rows.get(0).item);
    }

    /** Owner 2026-09-28: a whole potion drunk dose by dose is one Recent row, not one per sip. */
    @Test
    public void aWholePotionDrunkIsOneRecentRow()
    {
        List<Transaction> sips = Arrays.asList(
            action(4L, ActionKind.DRINK, new Flow(2442, "Super defence(4)", -1L, 3_364, -3_364L),
                new Flow(163, "Super defence(3)", 1L, 2_523, 2_523L)),
            action(3L, ActionKind.DRINK, new Flow(163, "Super defence(3)", -1L, 2_523, -2_523L),
                new Flow(165, "Super defence(2)", 1L, 1_682, 1_682L)),
            action(2L, ActionKind.DRINK, new Flow(165, "Super defence(2)", -1L, 1_682, -1_682L),
                new Flow(167, "Super defence(1)", 1L, 841, 841L)),
            action(1L, ActionKind.DRINK, new Flow(167, "Super defence(1)", -1L, 841, -841L)));
        List<LiveSnapshot.Recent> rows = LiveProbe.recent(sips, LiveContext.NONE);
        assertEquals("one row for the potion", 1, rows.size());
        assertEquals("Super defence", rows.get(0).name);
        assertEquals("every dose costs the same", -4L * 841L, rows.get(0).value);
        assertEquals("Drank · ×4 doses", LivePage.metaOf(rows.get(0)));
    }

    private static LiveSnapshot.Recent recent(Transaction transaction)
    {
        return LiveProbe.recent(Collections.singletonList(transaction), LiveContext.NONE).get(0);
    }

    private static Transaction action(long at, ActionKind kind, Flow... flows)
    {
        Transaction transaction = transaction(at, flows);
        transaction.setAction(kind);
        return transaction;
    }

    private static Transaction cast(long at, String name, Flow... flows)
    {
        Transaction transaction = action(at, ActionKind.CAST, flows);
        if (!name.isEmpty()) transaction.setActionLabel(ActionLabel.of(name));
        return transaction;
    }

    private static Transaction transaction(long at, Flow... flows)
    {
        return new Transaction(at, TransactionType.CONSUMPTION, Context.GENERIC,
            "", "Vorkath", true, Arrays.asList(flows), Confidence.CONFIRMED,
            "Positive action fixture", null);
    }

    private static Flow rune(String name, int id, long quantity, long value)
    {
        return new Flow(id, name, quantity, Math.toIntExact(Math.abs(value)), value);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.*;
import java.util.function.LongSupplier;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import org.junit.*;
import static org.junit.Assert.*;
import static com.gpmanager.MilestoneTest.onEdt;

/** Live category navigation and the bounded, unpaged Recent list preserve canonical bookings. */
public class LiveCategoryLayoutTest {
    static final long NOW=120_000;
    LongSupplier previous;
    @Before public void clock(){previous=SafeMath.clock;SafeMath.clock=()->NOW;}
    @After public void restore(){SafeMath.clock=previous;}
    static Engine engine(){
        var engine=new Engine(deltas->List.of(),new TransactionClassifier(),new GpManagerConfig(){});
        engine.ensureSession(0);return engine;
    }
    static void gain(Engine engine,int index,long at){
        engine.session().addTransaction(new Transaction(at,TransactionType.GAIN,Context.GENERIC,"","Test",true,
                List.of(new Flow(2000+index,"Item "+index,1,100,100,PriceSource.GRAND_EXCHANGE)),
                Confidence.CONFIRMED,"",null),2000,false);
    }
    static Field field(Class<?> type,String name){
        try{var f=type.getDeclaredField(name);f.setAccessible(true);return f;}
        catch(ReflectiveOperationException ex){throw new AssertionError("Missing proposed presentation state: "+name,ex);}
    }
    static LedgerData.Entry category(Semantics.Table table){
        var entry=LedgerData.Entry.current();
        try{field(LedgerData.Entry.class,"table").set(entry,table);return entry;}
        catch(IllegalAccessException ex){throw new AssertionError(ex);}
    }
    static LedgerPage focused(SidebarPanel panel){
        try{return (LedgerPage)field(SidebarPanel.class,"categoryPage").get(panel);}
        catch(IllegalAccessException ex){throw new AssertionError(ex);}
    }
    static void recent(LedgerPage page){
        try{LedgerPage.Actions.class.getMethod("recent").invoke(page.actions);}
        catch(ReflectiveOperationException ex){throw new AssertionError(ex);}
