package com.gpmanager;

import java.util.Collections;
import java.util.List;

/** Test-side Live rows straight from receipts, without an engine. */
public final class LiveProbe
{
    private LiveProbe()
    {
    }

    /** The bounded Live preview for these receipts. */
    public static List<LiveSnapshot.Recent> recent(List<Transaction> transactions, LiveContext ctx)
    {
        LiveContext context = ctx == null ? LiveContext.NONE : ctx;
        return LiveSnapshot.recentRows(SemanticProbe.capture(transactions, Collections.emptyList(),
            "", context::flowVisible), Collections.emptyMap(), context.filter);
    }

    /** The first Live row one receipt produces; null when it produces none. */
    public static LiveSnapshot.Recent toRecent(Transaction transaction)
    {
        List<LiveSnapshot.Recent> rows = recent(Collections.singletonList(transaction), LiveContext.NONE);
        return rows.isEmpty() ? null : rows.get(0);
    }
}

package com.gpmanager;

import java.util.Collections;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** The Live list is reused between ticks and rebuilt on a booking, a Market change or a filter change. */
public class LiveRecentCacheTest
{
    @Test
    public void theLiveListIsReusedUntilSomethingItShowsChanges()
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = 1_700_000_000_000L;
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(Tx.of(now, TransactionType.LOOT, Context.GENERIC, "", true,
            Collections.singletonList(new Flow(536, "Dragon bones", 1, 2_000, 2_000L))), 2_000, false);

        boolean[] hideBones = {false};
        String[] version = {"a"};
        RecentFilter filter = new RecentFilter()
        {
            public boolean isFlowIncluded(Flow flow)
            {
                return !(hideBones[0] && flow.item == 536);
            }

            public String version()
            {
                return version[0];
            }
        };
        LiveContext context = new LiveContext(false, filter, 0L, PvpState.NONE, "", false, "", false);
        LiveSnapshot first = LiveSnapshot.capture(engine, now + 1_000L, context);
        LiveSnapshot tick = LiveSnapshot.capture(engine, now + 1_600L, context);
        assertSame("an unchanged tick reuses the list", first.recent, tick.recent);
        assertEquals(1, tick.recent.size());

        engine.session().addTransaction(Tx.of(now + 2_000L, TransactionType.LOOT, Context.GENERIC,
            "", true, Collections.singletonList(new Flow(385, "Shark", 1, 900, 900L))), 2_000, false);
        LiveSnapshot booked = LiveSnapshot.capture(engine, now + 2_200L, context);
        assertNotSame("a booking rebuilds it", tick.recent, booked.recent);
        assertEquals(2, booked.recent.size());

        hideBones[0] = true;
        version[0] = "b";
        LiveSnapshot filtered = LiveSnapshot.capture(engine, now + 2_800L, context);
        assertEquals("a filter change applies its new decisions", 1, filtered.recent.size());

        // A GE offer placed and progressing changes the Market rows without a new revision.
        OfferSlots ledger = new OfferSlots();
        ledger.observe(new OfferSlots.Snapshot(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0));
        engine.noteGeOffer(ledger.observe(new OfferSlots.Snapshot(0,
            GrandExchangeOfferState.BUYING, 385, 10, 0, 900, 0)).get(), "Shark", now + 3_000L);
        LiveSnapshot placed = LiveSnapshot.capture(engine, now + 3_100L, context);
        long revision = engine.revision();
        engine.noteGeOffer(ledger.observe(new OfferSlots.Snapshot(0,
            GrandExchangeOfferState.BUYING, 385, 10, 4, 900, 3_600)).get(), "Shark", now + 3_500L);
        assertEquals("GE progress alone books nothing", revision, engine.revision());
        LiveSnapshot progressed = LiveSnapshot.capture(engine, now + 3_600L, context);
        assertTrue("the Market row change is seen", placed.recent != progressed.recent);
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Live Recent Activity is rebuilt from the shared semantic projection as living groups. */
public class LiveSemanticGroupsTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final int DEATH = 560;
    private static final int CHAOS = 562;
    private static final int WATER = 555;
    private static final int BLOOD = 565;

    @Test
    public void repeatedExactSpellUpdatesOneLiveRowAndBubbles()
    {
        Engine engine = session("Vorkath");
        engine.session().addTransaction(exactCast(T0 + 1_000L, "Ice Barrage", 1, 1, 1), 2_000, false);
        engine.session().addTransaction(exactCast(T0 + 2_000L, "Ice Barrage", 1, 1, 1), 2_000, false);
        engine.session().addTransaction(exactCast(T0 + 3_000L, "Ice Barrage", 1, 1, 1), 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 4_000L, LiveContext.NONE);

        assertEquals("repeated exact spells are one updating row", 1, snapshot.recent.size());
        LiveSnapshot.Recent row = snapshot.recent.get(0);
        assertEquals("Ice Barrage", row.name);
        assertEquals("the row counts the receipts it speaks for", 3, row.entries);
        assertEquals(-540L, row.value);
        assertEquals("Cast \u00b7 \u00d73", LivePage.metaOf(row));

        engine.session().addTransaction(exactCast(T0 + 5_000L, "Blood Barrage", 1, 1, 1), 2_000, false);
        LiveSnapshot bubbled = LiveSnapshot.capture(engine, T0 + 6_000L, LiveContext.NONE);
        assertEquals(2, bubbled.recent.size());
        assertEquals("the newest group bubbles to the top", "Blood Barrage", bubbled.recent.get(0).name);
        assertEquals("Ice Barrage", bubbled.recent.get(1).name);
        assertEquals(3, bubbled.recent.get(1).entries);
    }

    @Test
    public void genericCastCompositionsStaySeparateAndGeneric()
    {
        Engine engine = session("Vorkath");
        engine.session().addTransaction(genericCast(T0 + 1_000L, 1, 1, 1), 2_000, false);
        // 2/2/2 would be Ice Rush's exact cost (named since 2026-09-28); 3/3/3 is no spell's.
        engine.session().addTransaction(genericCast(T0 + 2_000L, 3, 3, 3), 2_000, false);
        engine.session().addTransaction(bloodGenericCast(T0 + 3_000L), 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 4_000L, LiveContext.NONE);
        assertEquals("same normalised composition groups, a different one splits", 2, snapshot.recent.size());
        for (LiveSnapshot.Recent row : snapshot.recent)
        {
            assertEquals("generic casts never receive an inferred spell name", "Cast", row.name);
        }
        LiveSnapshot.Recent grouped = snapshot.recent.stream()
            .filter(row -> row.entries == 2).findFirst().orElseThrow(AssertionError::new);
        assertEquals(-720L, grouped.value);
        assertEquals("3 rune types \u00b7 \u00d72", LivePage.metaOf(grouped));
    }

    @Test
    public void liveRecentStaysBoundedToOnePageOfSemanticRows()
    {
        Engine engine = session("Vorkath");
        for (int i = 0; i < LiveSnapshot.RECENT_ROWS + 2; i++)
        {
            engine.session().addTransaction(
                gain(T0 + 1_000L + i * 1_000L, "Item " + i, 2_000 + i, 1L, 100, 100L), 2_000, false);
        }
        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 20_000L, LiveContext.NONE);

        assertEquals("the Live preview is bounded", LiveSnapshot.RECENT_ROWS, snapshot.recent.size());
        assertEquals("the newest rows are kept", "Item 16", snapshot.recent.get(0).name);
        assertEquals("Item 2", snapshot.recent.get(LiveSnapshot.RECENT_ROWS - 1).name);
    }

    @Test
    public void unpricedFinancialRowsAreNotReviewButCanonicalReviewStillIs()
    {
        Engine engine = session("Vorkath");
        engine.session().addTransaction(unpricedGain(T0 + 1_000L, "Unidentified mineral", 8), 2_000, false);
        engine.session().addTransaction(review(T0 + 2_000L, "Unknown rune", 777), 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 3_000L, LiveContext.NONE);

        assertEquals("only the canonical review transaction needs a decision", 1, snapshot.reviews);
        assertNull("unpriced acquisitions wait outside Recent", rowNamed(snapshot.recent, "Unidentified mineral"));
        assertNull("unpriced decisions also wait outside Recent", rowNamed(snapshot.recent, "Unknown rune"));
        var ledger = LedgerData.capture(engine, T0 + 3_000L, LedgerData.Entry.current());
        var unpriced = ledger.income.groups.stream().filter(group -> group.name.equals("Unidentified mineral"))
                .findFirst().orElseThrow();
        assertTrue(unpriced.incomplete());
        assertFalse("an unpriced acquisition is not a classification decision", unpriced.review);
        assertEquals(Semantics.Table.GAINS, unpriced.table);
        assertEquals(1, ledger.review.rows.size());
    }

    @Test
    public void measuredResourceRowsShowInRecentAndStayInTheLedgerChargesChip()
    {
        Engine engine = session("Vorkath");
        engine.session().addTransaction(gain(T0 + 500L, "Older gain", 999, 1L, 50, 50L), 2_000, false);
        engine.session().addTransaction(blowpipeSpend(T0 + 1_000L), 2_000, false);
        engine.session().addTransaction(blowpipeSpend(T0 + 2_000L), 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 3_000L, LiveContext.NONE);

        // Owner 1.3.4: charge use shows in Recent like any row; the Ledger's Charges chip still
        // holds it.
        LiveSnapshot.Recent scales = rowNamed(snapshot.recent, "Zulrah's scales");
        assertNotNull("the scales charge row is listed now", scales);
        assertEquals(LedgerData.CostView.CHARGES, scales.cost);
        assertNotNull("owner 1.1: darts are Supplies like arrows", rowNamed(snapshot.recent, "Dragon dart"));
        assertEquals("the darts, the scales and the gain are in Recent", 3, snapshot.recent.size());
        assertNotNull(rowNamed(snapshot.recent, "Older gain"));

        LedgerData ledger = LedgerData.capture(engine, T0 + 3_000L,
            new LedgerData.Entry(LedgerData.Scope.CURRENT_GRIND, null, null,
                LedgerData.CostView.CHARGES, "", null, null, null, null));
        assertEquals("only the scales live in Charges",
            1, ledger.costCounts[LedgerData.CostView.CHARGES.ordinal()]);
        assertEquals("the darts are Supplies", 1, ledger.costCounts[LedgerData.CostView.SUPPLIES.ordinal()]);
    }

    @Test
    public void exactSpellRowCarriesStableDeepLinkIdentity()
    {
        Engine engine = session("Vorkath");
        Transaction newest = exactCast(T0 + 2_000L, "Ice Barrage", 1, 1, 1);
        engine.session().addTransaction(exactCast(T0 + 1_000L, "Ice Barrage", 1, 1, 1), 2_000, false);
        engine.session().addTransaction(newest, 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 3_000L, LiveContext.NONE);
        LiveSnapshot.Recent row = snapshot.recent.get(0);

        assertEquals("the representative receipt is the newest one", newest.id(), row.receiptId);
        assertNotNull(row.id);
        LedgerData.Entry entry = LivePage.entryFor(row);
        assertEquals("deep links never smuggle a search string", "", entry.search);
        assertEquals(newest.id(), entry.transaction);
        LedgerData linked = LedgerData.capture(engine, T0 + 3_000L, entry);
        assertNotNull("the stable identity resolves to its group detail", linked.detail);
        assertTrue(linked.detail.group.containsTransaction(newest.id()));
    }

    // ── fixtures ───────────────────────────────────────────────────────────────────────────────

    private static Engine session(String name)
    {
        Engine engine = PresentationLifecycleTest.engine();
        engine.startCustom(name, T0);
        return engine;
    }

    private static LiveSnapshot.Recent rowNamed(List<LiveSnapshot.Recent> rows, String name)
    {
        for (LiveSnapshot.Recent row : rows)
        {
            if (name.equals(row.name))
            {
                return row;
            }
        }
        return null;
    }

    private static Transaction exactCast(long at, String name, int deathQty, int chaosQty, int waterQty)
    {
        Transaction transaction = genericCast(at, deathQty, chaosQty, waterQty);
        transaction.setActionLabel(ActionLabel.of(name));
        return transaction;
    }

    private static Transaction genericCast(long at, int deathQty, int chaosQty, int waterQty)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                rune(DEATH, "Death rune", -deathQty, 100),
                rune(CHAOS, "Chaos rune", -chaosQty, 50),
                rune(WATER, "Water rune", -waterQty, 30)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setAction(ActionKind.CAST);
        return transaction;
    }

    private static Transaction bloodGenericCast(long at)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                rune(DEATH, "Death rune", -1L, 100),
                rune(BLOOD, "Blood rune", -1L, 200),
                rune(WATER, "Water rune", -1L, 30)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setAction(ActionKind.CAST);
        return transaction;
    }

    private static Flow rune(int id, String name, long quantity, int unit)
    {
        return new Flow(id, name, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE);
    }

    private static Transaction blowpipeSpend(long at)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "Measured charge spend \u00b7 Toxic blowpipe", "Vorkath", true,
            Arrays.asList(
                new Flow(11230, "Dragon dart", -2L, 100, -200L, PriceSource.GRAND_EXCHANGE),
                new Flow(12934, "Zulrah's scales", -1L, 110, -110L, PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "Measured Check difference for Toxic blowpipe.", null);
        transaction.setAction(ActionKind.FIRE);
        return transaction;
    }

    private static Transaction gain(long at, String name, int itemId, long quantity, int unitPrice, long value)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.LIKELY, "Test gain", null);
    }

    private static Transaction unpricedGain(long at, String name, int itemId)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, 8L, 0, 0L, PriceSource.UNPRICED)),
            Confidence.LIKELY, "Unpriced test gain", null);
    }

    private static Transaction review(long at, String name, int itemId)
    {
        return new Transaction(at, TransactionType.UNCERTAIN, Context.GENERIC, "", "Vorkath",
            true, Collections.singletonList(new Flow(itemId, name, -1L, 0, 0L)),
            Confidence.UNCERTAIN, "Awaiting a decision", null);
    }
}

package com.gpmanager;

import java.awt.*;
import javax.swing.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.gpmanager.MilestoneTest.onEdt;

public class LiveStatusPillTest {
    @Test public void statusesOccupyTheRightPillAndNamesStayOnOneRow() throws Exception {
        onEdt(() -> {
            LivePage page = MilestoneTest.page();
            LiveSnapshot snapshot = TargetFreshStartTest.live(TargetFreshStartTest.engine(), 20L);
            snapshot.activityLabel = "Wilderness Agility Course";
            for (int width : new int[]{213, 225, 300}) {
                page.hero.setSize(width, 100);
                for (String status : new String[]{"AWAY", "CALIBRATING", "PAUSED"}) {
                    snapshot.idle = status.equals("AWAY");
                    snapshot.warming = status.equals("CALIBRATING");
                    snapshot.paused = status.equals("PAUSED");
                    page.apply(snapshot);
                    page.hero.setSize(width, page.hero.getPreferredSize().height);
                    ActivityHeaderLayoutTest.layout(page.hero);
                    JLabel pill = page.hero.word;
                    assertEquals(status, LivePage.wordOf(snapshot));
                    assertEquals(status + " pill colour", status.equals("AWAY") ? Kit.ACCENT
                            : status.equals("CALIBRATING") ? Kit.Tone.GAIN.color : Kit.Tone.REVIEW.color, pill.getForeground());
                    assertTrue("status has a visible pill border", pill.getBorder() != null);
                    Rectangle badge = SwingUtilities.convertRectangle(pill.getParent(), pill.getBounds(), page.hero);
                    Rectangle name = SwingUtilities.convertRectangle(page.hero.name.getParent(), page.hero.name.getBounds(), page.hero);
                    assertEquals("pill is at right edge", width - 4, badge.getMaxX(), 1d);
                    assertEquals("shared vertical center", name.getCenterY(), badge.getCenterY(), 1d);
                    assertEquals(status+" keeps activity readable", snapshot.activityLabel, page.hero.name.getText());
                    assertTrue("title fits", page.hero.name.getPreferredSize().width <= page.hero.name.getWidth());
                    assertEquals("one row", page.hero.name.getFontMetrics(page.hero.name.getFont()).getHeight(), page.hero.name.getPreferredSize().height);
                }
            }
            return null;
        });
    }

    @Test public void pillColoursFollowVisibleStatusAndResetAcrossTransitions() throws Exception {
        onEdt(() -> {
            LivePage page = MilestoneTest.page();
            LiveSnapshot snapshot = TargetFreshStartTest.live(TargetFreshStartTest.engine(), 20L);
            snapshot.warming = true;
            page.apply(snapshot);
            assertEquals(Kit.Tone.GAIN.color, page.hero.word.getForeground());
            snapshot.idle = true;
            page.apply(snapshot);
            assertEquals(Kit.ACCENT, page.hero.word.getForeground());
            snapshot.offline = true;
            page.apply(snapshot);
            assertEquals("Logged out", page.hero.word.getText());
            assertEquals(Kit.Tone.LOSS.color, page.hero.word.getForeground());
            snapshot.hopping = true;
            page.apply(snapshot);
            assertEquals("Reconnecting", page.hero.word.getText());
            assertEquals(Kit.Tone.MARKET.color, page.hero.word.getForeground());
            snapshot.offline = false;
            snapshot.hopping = false;
            snapshot.idle = false;
            snapshot.paused = true;
            page.apply(snapshot);
            assertEquals("Paused", page.hero.word.getText());
            assertEquals(Kit.Tone.REVIEW.color, page.hero.word.getForeground());
            snapshot.paused = false;
            snapshot.warming = false;
            page.apply(snapshot);
            assertFalse(page.hero.word.isVisible());
            assertEquals(Kit.LABEL, page.hero.word.getForeground());
            return null;
        });
    }

    @Test public void resumingAndCompleteUseGreenWhileAnUnknownStateUsesTheDefault() throws Exception {
        onEdt(() -> {
            LivePage page = MilestoneTest.page();
            LiveSnapshot snapshot = TargetFreshStartTest.live(TargetFreshStartTest.engine(), 20L);
            snapshot.present = false;
            snapshot.resumeSeconds = 3L;
            page.apply(snapshot);
            assertEquals("Resuming 3s", page.hero.word.getText());
            assertEquals(Kit.Tone.GAIN.color, page.hero.word.getForeground());
            page.hero.status(Kit.OFF, "", "Vorkath", "COMPLETE", null);
            assertEquals(Kit.Tone.GAIN.color, page.hero.word.getForeground());
            page.hero.status(Kit.OFF, "", "", "OTHER", null);
            assertEquals(Kit.LABEL, page.hero.word.getForeground());
            return null;
        });
    }

    @Test public void onlyLeftClickTogglesTheStatusDotAndDisabledDotsDoNothing() throws Exception {
        onEdt(() -> {
            Hero hero = new Hero();
            int[] toggles = {0};
            hero.status(Kit.Tone.GAIN.color, "", "", "", () -> toggles[0]++);
            DirectHeaderControlsTest.click(hero.dot, java.awt.event.MouseEvent.BUTTON3);
            DirectHeaderControlsTest.click(hero.dot, java.awt.event.MouseEvent.BUTTON2);
            assertEquals("other buttons cannot pause tracking", 0, toggles[0]);
            DirectHeaderControlsTest.click(hero.dot);
            assertEquals(1, toggles[0]);
            hero.status(Kit.OFF, "", "", "LOGGED OUT", null);
            DirectHeaderControlsTest.click(hero.dot);
            assertEquals(1, toggles[0]);
            assertEquals(Cursor.DEFAULT_CURSOR, hero.dot.getCursor().getType());
            return null;
