    @Test public void countsRemainSeparateFromTheActivityInConditionalContent() throws Exception {
        onEdt(() -> {
            LivePage page = MilestoneTest.page();
            Engine engine = TargetFreshStartTest.engine();
            LiveSnapshot snapshot = TargetFreshStartTest.live(engine, 20L);
            snapshot.reviews = 2;
            snapshot.keys = 1;
            page.apply(snapshot);
            assertNull(page.pageBar());
            assertTrue(SwingUtilities.isDescendingFrom(page.counts, page.body()));
            assertTrue(SwingUtilities.isDescendingFrom(page.hero.icons, page.body()));
            assertFalse(SwingUtilities.isDescendingFrom(page.hero.icons, page.hero));
            return null;
        });
    }

    @Test public void normalTrackingAndLogoutKeepTheirExistingStatusRules() throws Exception {
        onEdt(() -> {
            LivePage page = MilestoneTest.page();
            LiveSnapshot snapshot = TargetFreshStartTest.live(TargetFreshStartTest.engine(),20L);
            page.apply(snapshot); assertFalse(page.hero.word.isVisible());
            snapshot.offline = true; page.apply(snapshot);
            assertEquals("Logged out", page.hero.word.getText());
            assertNull(page.pageBar());
            snapshot.hopping = true; page.apply(snapshot);
            assertEquals("Reconnecting", page.hero.word.getText());
            return null;
        });
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.LootFilter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import net.runelite.api.WorldType;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner report 2026-09-28: drops showed "?" values. Each Display loot filter mode shows the right
 * rows, every shown drop keeps its price, and no mode changes Net.
 */
public class LootDisplayModesTest
{
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void everyLootDisplayModeKeepsDropValuesAndShowsItsRows()
    {
        // The Ground Items lists: Iron mace highlighted, Bones hidden, Onion seed on neither.
        LootPresentationFilterService service = new LootPresentationFilterService(
            new GroundItemsPrefs(true, "Iron mace", "Bones", false));
        Engine engine = PresentationLifecycleTest.engine();
        engine.startCustom("Guard", T0);
        book(engine, T0 + 1_000L, new Flow(1420, "Iron mace", 1, 52, 52L));
        book(engine, T0 + 2_000L, new Flow(526, "Bones", 4, 90, 360L));
        book(engine, T0 + 3_000L, new Flow(5319, "Onion seed", 4, 3, 12L));
        long net = engine.metrics(T0 + 4_000L).net;

        assertEquals(List.of("Onion seed", "Bones", "Iron mace"),
            shown(engine, service, LootFilter.ALL_ITEMS));
        assertEquals("Follow Ground Items hides the hidden list", List.of("Onion seed", "Iron mace"),
            shown(engine, service, LootFilter.FOLLOW_GROUND_ITEMS));
        assertEquals("Highlighted list only shows the highlighted list", List.of("Iron mace"),
            shown(engine, service, LootFilter.HIGHLIGHTED_LIST_ONLY));
        assertEquals("no display mode changes Net", net, engine.metrics(T0 + 5_000L).net);
        assertEquals(52L + 360L + 12L, net);
    }

    /** Ordinary main-game worlds, PvP and LMS included, price drops; only separate economies do not. */
    @Test
    public void mainGameWorldsPriceDrops()
    {
        for (WorldType flag : EnumSet.complementOf(EnumSet.of(WorldType.DEADMAN, WorldType.SEASONAL,
            WorldType.HARDCORE_MAIN, WorldType.QUEST_SPEEDRUNNING, WorldType.BETA_WORLD,
            WorldType.TOURNAMENT_WORLD, WorldType.NOSAVE_MODE)))
        {
            Valuation valuation = new Valuation(new GpManagerConfig() {}, id -> null,
                (id, active) -> 52, id -> false,
                Valuation.economyFor(EnumSet.of(WorldType.MEMBERS, flag)));
            Flow drop = valuation.value(Collections.singletonMap(1420, 1L), T0).get(0);
            assertEquals(flag + " prices drops", PriceSource.GRAND_EXCHANGE, drop.source());
            assertEquals(52L, drop.value);
        }
    }

    private static List<String> shown(Engine engine, LootPresentationFilterService service,
        LootFilter mode)
    {
        RecentFilter filter = flow -> service.isFlowIncluded(flow, mode);
        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 4_000L,
            new LiveContext(false, filter, 0L, PvpState.NONE, "", false, "", false));
        List<String> names = new ArrayList<>();
        for (LiveSnapshot.Recent row : snapshot.recent)
        {
            assertFalse(mode + ": " + row.name + " keeps its price", row.unknown);
            assertTrue(mode + ": " + row.name + " shows a value", row.value > 0L);
            names.add(row.name);
        }
        return names;
    }

    private static void book(Engine engine, long at, Flow flow)
    {
        engine.session().addTransaction(Tx.of(at, TransactionType.LOOT, Context.LOOT,
            "Loot from Guard", true, Collections.singletonList(flow)), 2_000, false);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static com.gpmanager.SwingTestSupport.onEdt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The current loot visibility settings are presentation-only: they change which Live rows
 * appear, never what was booked. Priced costs stay visible; unpriced gains remain in Ledger.
 */
public class LootVisibilityPresentationTest
{
    @Test
    public void minimumDisplayedLootValueHidesCheapPricedGainsOnly() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(
            transaction(now + 1_000L, "Cheap bones", 1, TransactionType.GAIN, 2, 100, 200L), 2_000, false);
        engine.session().addTransaction(
            transaction(now + 2_000L, "Valuable hide", 2, TransactionType.GAIN, 1, 5_000, 5_000L), 2_000, false);
        long net = engine.metrics(now + 3_000L).net;

        LiveSnapshot unfiltered = LiveSnapshot.capture(engine, now + 3_000L, LiveContext.NONE);
        assertEquals("both gains are visible with no minimum", 2, unfiltered.recent.size());

        LiveContext minimum = new LiveContext(false, null, 1_000L, PvpState.NONE, "", false, "", false);
        LiveSnapshot filtered = LiveSnapshot.capture(engine, now + 3_000L, minimum);
        assertEquals("the cheap gain is hidden from presentation", 1, filtered.recent.size());
        assertEquals("Valuable hide", filtered.recent.get(0).name);
        assertEquals("canonical net is untouched by presentation filtering", net,
            engine.metrics(now + 3_000L).net);
        assertEquals("the hidden receipt is still canonical session truth",
            2, engine.session().transactions().size());
    }

    @Test
    public void minimumDisplayedLootValueKeepsCostsAndLeavesUnpricedGainsInLedger() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(
            transaction(now + 1_000L, "Prayer potion(4)", 3, TransactionType.CONSUMPTION, -2, 9_800, -19_600L), 2_000, false);
        // Unit price 0: the price is unknown, so the minimum cannot judge it.
        engine.session().addTransaction(
            transaction(now + 2_000L, "Unidentified mineral", 8, TransactionType.GAIN, 8, 0, 0L), 2_000, false);

        LiveContext minimum = new LiveContext(false, null, 1_000_000L, PvpState.NONE, "", false, "", false);
        LiveSnapshot filtered = LiveSnapshot.capture(engine, now + 3_000L, minimum);
        assertEquals("priced costs stay discoverable", 1, filtered.recent.size());
        LiveSnapshot.Recent mineral = null;
        for (LiveSnapshot.Recent row : filtered.recent)
        {
            if ("Unidentified mineral".equals(row.name))
            {
                mineral = row;
            }
        }
        assertNull("the unpriced gain waits outside Recent", mineral);
        var ledger = LedgerData.capture(engine, now + 3_000L, LedgerData.Entry.current());
        assertTrue("the receipt remains available in Ledger", ledger.income.groups.stream()
                .anyMatch(group -> group.name.equals("Unidentified mineral") && group.incomplete()));
    }

    @Test
    public void itemFilterHidesOnlyPresentationAndKeepsCanonicalTruth() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(
            transaction(now + 1_000L, "Vial", 1, TransactionType.GAIN, 3, 1, 3L), 2_000, false);
        engine.session().addTransaction(
            transaction(now + 2_000L, "Dragon bones", 1, TransactionType.GAIN, 2, 3_200, 6_400L), 2_000, false);
        long net = engine.metrics(now + 3_000L).net;

        SidebarPanel panel = onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            created.bindFilter(flow -> !"Vial".equals(flow.name));
            SidebarPanelProbe.refresh(created);
            return created;
        });
        LiveSnapshot snapshot = SidebarPanelProbe.live(panel);
        assertNotNull(snapshot);
        assertEquals("the filtered item is not rendered", 1, snapshot.recent.size());
        assertEquals("Dragon bones", snapshot.recent.get(0).name);
        assertEquals("the booked net is unchanged by the presentation filter", net, snapshot.net);
        assertTrue("the hidden receipt stays canonical", engine.session().transactions().size() == 2);
    }

    @Test
    public void minimumValueSettingParsesPlainAndSuffixedForms() throws Exception
    {
        assertEquals(0L, Fmt.parseGp(null));
        assertEquals(0L, Fmt.parseGp(""));
        assertEquals(0L, Fmt.parseGp("abc"));
        assertEquals(0L, Fmt.parseGp("0"));
        assertEquals(3_000L, Fmt.parseGp("3000"));
        assertEquals(200_000L, Fmt.parseGp("200k"));
        assertEquals(1_500_000L, Fmt.parseGp("1.5m"));
        assertEquals(2_500L, Fmt.parseGp("2,500"));
        assertEquals(0L, Fmt.parseGp("-5k"));
    }

    @Test
    public void panelReadsTheCurrentMinimumSettingOnEveryRefresh() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(
            transaction(now + 1_000L, "Cheap bones", 1, TransactionType.GAIN, 2, 100, 200L), 2_000, false);

        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine, minimumConfig("500"), null, null, null));
        onEdt(() ->
        {
            SidebarPanelProbe.refresh(panel);
            return null;
        });
        assertTrue("a 500 gp minimum hides a 100 gp unit-price gain", SidebarPanelProbe.live(panel).recent.isEmpty());

        SidebarPanel open = onEdt(() -> new SidebarPanel(engine, minimumConfig("0"), null, null, null));
        onEdt(() ->
        {
            SidebarPanelProbe.refresh(open);
            return null;
        });
        assertFalse("no minimum shows the same booked gain", SidebarPanelProbe.live(open).recent.isEmpty());
    }

    private static GpManagerConfig minimumConfig(String minimum)
    {
        return new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }

            @Override
            public String minimumDisplayedLootValue()
            {
                return minimum;
            }
        };
    }

    private static Transaction transaction(long at, String name, int itemId, TransactionType type,
        long quantity, int unitPrice, long value)
    {
        return new Transaction(at, type, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value)),
            Confidence.LIKELY, "Test sample.", null);
    }

}

package com.gpmanager;

import static com.gpmanager.TargetFreshStartTest.HOUR;
import static com.gpmanager.TargetFreshStartTest.coins;
import static com.gpmanager.TargetFreshStartTest.live;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** Owner 1.5.2: Free play's Net milestone counts all of Free play; the HUD says when it is reached. */
public class MilestoneTest
{
    static LivePage page()
    {
        LivePage.Actions actions = (LivePage.Actions) java.lang.reflect.Proxy.newProxyInstance(
            LivePage.Actions.class.getClassLoader(), new Class<?>[] {LivePage.Actions.class},
            (proxy, method, args) -> method.getReturnType() == boolean.class ? false : null);
        return new LivePage(actions, id -> null);
    }

    @Test
    public void itCountsAllOfFreePlayWhileATargetCountsFresh()
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 400_000_000L);
        assertTrue(engine.setMilestone(1_000_000_000L));
        engine.setTargets(5_000_000L, null, HOUR);
        LiveSnapshot live = live(engine, HOUR);
        assertEquals("the target counts fresh", 0L, live.net);
        assertEquals("the milestone counts all of Free play", 400_000_000L, live.run);
        assertFalse(live.milestoneReached());

        coins(engine, HOUR + 5L, 600_000_000L);
        assertTrue(live(engine, HOUR + 10L).milestoneReached());
    }

    @Test
    public void aGrindLeavesItAloneAndCannotSetIt()
    {
        Engine engine = TargetFreshStartTest.engine();
        engine.setMilestone(1_000_000_000L);
        engine.startCustom("Vorkath", HOUR);
        assertNull(live(engine, HOUR).milestone);
        assertFalse(engine.setMilestone(5_000_000_000L));
        assertEquals(Long.valueOf(1_000_000_000L), engine.freePlay().milestoneGp);
    }

    /** The HUD+ kill-streak line measures the whole run, so a target start never moves it. */
    @Test
    public void aTargetStartLeavesTheHudNetBaseWhole()
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 1_000L);
        HudBuilder builder = new HudBuilder(HudBuilderTest.config(false, 4), null);
        builder.update(live(engine, 10L), f -> true, 10L);
        engine.setTargets(5_000_000L, null, 20L);
        builder.update(live(engine, 30L), f -> true, 30L);
        assertEquals(1_000L, builder.lastNet);
    }

    @Test
    public void theTargetsSheetOffersItInFreePlayOnly() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        engine.ensureSession(System.currentTimeMillis());
        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null));
        Shell shell = panel.shell;
        GrindsController grinds = new GrindsController(panel);
        assertTrue("a milestone pick", onEdt(() ->
        {
            grinds.openTargets();
            assertEquals("Set a Target", shell.heading);
            boolean picked = ShellProbe.pressSheetText(shell, "5b");
            ShellProbe.pressSheet(shell, "Save");
            return picked;
        }));
        assertEquals(Long.valueOf(5_000_000_000L), engine.freePlay().milestoneGp);
        assertNull("a milestone alone sets no target", engine.session().targetGp());
        assertNull(engine.session().sessionStartAt);

        engine.startCustom("Vorkath", System.currentTimeMillis());
        assertFalse("no milestone in a Grind", onEdt(() ->
        {
            grinds.openTargets();
            return ShellProbe.pressSheetText(shell, "5b");
        }));
    }

    static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        java.util.concurrent.atomic.AtomicReference<T> result = new java.util.concurrent.atomic.AtomicReference<>();
        java.util.concurrent.atomic.AtomicReference<Exception> failure = new java.util.concurrent.atomic.AtomicReference<>();
        javax.swing.SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result.set(callable.call());
            }
            catch (Exception ex)
            {
                failure.set(ex);
            }
        });
        if (failure.get() != null)
        {
            throw failure.get();
        }
        return result.get();
    }

    /** While Live counts fresh, the line under the Net says what the run holds. */
    @Test
    public void underTheNetLiveSaysWhatTheRunHolds() throws Exception
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 420_000_000L);
        LivePage page = page();
        assertFalse("the whole run needs no total line", onEdt(() ->
        {
            page.apply(live(engine, HOUR));
            return page.total.isVisible();
        }));
        engine.setTargets(5_000_000L, null, HOUR);
        LiveSnapshot live = live(engine, HOUR);
        assertEquals("Free play " + Fmt.signed(420_000_000L), onEdt(() ->
        {
            page.apply(live);
            return page.total.isVisible() ? page.total.getText() : "";
        }));
        assertEquals("Live itself counts fresh", 0L, live.net);
    }

    @Test
    public void aFactoryResetClearsIt()
    {
        Engine engine = TargetFreshStartTest.engine();
        engine.setMilestone(1_000_000_000L);
        engine.resetData(HOUR);
        engine.ensureSession(HOUR);
        assertNull(engine.freePlay().milestoneGp);
    }
}

package com.gpmanager;

import java.time.Instant;
import java.time.ZoneId;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class PaginationPresentationTest
{
    @Test
    public void ledgerTablesRetainAndDeepLinkPastTheOldTwoHundredRowCap() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        Transaction oldest = null;
        for (int i = 0; i < 225; i++)
        {
            Transaction transaction = booked(now + i + 1L, "Item " + i, 1_000 + i, 100L);
            if (oldest == null) oldest = transaction;
            engine.session().addTransaction(transaction, 2_000, false);
        }
        assertNotNull(oldest);
        final String oldId = oldest.id();

        LedgerData first = LedgerData.capture(engine, now + 1_000L,
            LedgerData.Entry.current());
        assertEquals(225, first.income.entries);
        assertEquals("every retained row reaches the page table, which pages it", 225, first.income.groups.size());
        assertEquals(22_500L, first.income.total);

        LedgerData searched = LedgerData.capture(engine, now + 1_000L,
            new LedgerData.Entry(LedgerData.Scope.CURRENT_GRIND, null, null,
                LedgerData.CostView.SUPPLIES, "Item 222", null, null, null, null));
        assertEquals("search sees the full retained set before page slicing", 1, searched.income.entries);
        assertEquals("Item 222", searched.income.groups.get(0).name);

        LedgerData deepLink = LedgerData.capture(engine, now + 1_000L,
            new LedgerData.Entry(LedgerData.Scope.CURRENT_GRIND, null, null,
                LedgerData.CostView.SUPPLIES, "", oldId, null, null, null));
        assertNotNull("the deep link opens the owning group detail", deepLink.detail);
        assertTrue(deepLink.detail.group.containsTransaction(oldId));
    }

    @Test
    public void grindSectionsCarryFullHistoryAndSavedSetAndUseThePassedProfileZone() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        for (int i = 0; i < 31; i++)
        {
            engine.startCustom("History " + i, now + i * 10L);
            engine.finishCustom(now + i * 10L + 1L);
        }
        for (int i = 0; i < 31; i++)
        {
            engine.saveGrind("Saved " + i, null, null, false);
        }

        GrindsData data = GrindsData.capture(engine, now + 2_000L, false, null);
        assertEquals("every saved Grind reaches the table", 31, data.plans.size());
        assertEquals("no Recent runs cap", 31, data.recent.stream().filter(run -> !run.general).count());

        long recentAt = Instant.parse("2024-01-01T11:00:00Z").toEpochMilli();
        long profileNow = Instant.parse("2024-01-01T13:00:00Z").toEpochMilli();
        GrindsData.Recent sample = new GrindsData.Recent("s", "Grind", recentAt, 0L, 0L, false);
        String label = GrindsPage.contextLine(sample, profileNow, ZoneId.of("Pacific/Kiritimati"));
        assertTrue("Recent Grind day labels follow the supplied analytics zone", label.startsWith("Today"));
    }

    private static Transaction booked(long at, String name, int itemId, long value)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC,
            "", "Vorkath", true, Collections.singletonList(new Flow(itemId, name, 1L,
                Math.toIntExact(value), value)), Confidence.LIKELY, "test", null);
    }
}

package com.gpmanager;

