package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static com.gpmanager.SwingTestSupport.onEdt;
import static org.junit.Assert.*;

/** Client-side owner fencing must not wait on a busy EDT or revive queued old-owner work. */
public class PanelOwnerQueueTest {
    private static final long NOW = 1_700_000_000_000L;

    @Test public void suspendFencesImmediatelyWithoutWaitingForEdt() throws Exception {
        CountingPanel panel = panel();
        Object previous = panel.ownerToken;
        panel.engine.events.put(Inbox.CONSUME, 385, 1, 10, null);
        try (BlockedEdt edt = new BlockedEdt()) {
            edt.client(panel::suspend);
            assertTrue(panel.suspended);
            assertNotSame(previous, panel.ownerToken);
            assertNull("action evidence clears before EDT work", panel.engine.events.peek(Inbox.CONSUME));
        }
        onEdt(() -> { assertNull(panel.snapshot); return null; });
    }

    @Test public void anObsoleteQueuedResumeCannotLiftANewerFence() throws Exception {
        CountingPanel panel = panel();
        AtomicReference<Boolean> fenceBetweenTasks = new AtomicReference<>();
        try (BlockedEdt edt = new BlockedEdt()) {
            edt.client(() -> { panel.suspend(); panel.resume(); });
            SwingUtilities.invokeLater(() -> fenceBetweenTasks.set(panel.suspended));
            edt.client(panel::suspend);
        }
        assertEquals("old resume must remain fenced even before the later clear runs", Boolean.TRUE, fenceBetweenTasks.get());
        assertTrue(panel.suspended);
        assertTrue(panel.captures.isEmpty());
    }

    @Test public void queuedClearCannotEraseAnOwnerResumedDirectlyOnEdt() throws Exception {
        CountingPanel panel = panel();
        try (BlockedEdt edt = new BlockedEdt()) {
            edt.client(panel::suspend);
            edt.beforeQueued = () -> {
                load(panel.engine, "b", "Owner B", 200);
                panel.suspend();
                panel.resume();
                panel.ledgerSearch = "Owner B search";
            };
        }
        onEdt(() -> {
            assertFalse(panel.suspended);
            assertEquals("Owner B search", panel.ledgerSearch);
            assertNotNull(panel.snapshot);
            assertEquals(200, panel.snapshot.net);
            assertFalse(panel.captures.isEmpty());
            assertTrue(panel.captures.stream().allMatch("Owner B"::equals));
            return null;
        });
    }

    @Test public void rapidAToBToAKeepsOnlyTheFinalGeneration() throws Exception {
        CountingPanel panel = panel();
        AtomicReference<Object> firstA = new AtomicReference<>();
        try (BlockedEdt edt = new BlockedEdt()) {
            edt.client(() -> {
                panel.suspend(); firstA.set(panel.ownerToken); panel.resume();
                load(panel.engine, "b", "Owner B", 200);
                panel.suspend(); panel.resume();
                load(panel.engine, "a", "Returned A", 300);
                panel.suspend(); panel.resume();
            });
            assertTrue(panel.suspended);
            assertNotSame("same account still needs a new generation", firstA.get(), panel.ownerToken);
        }
        onEdt(() -> {
            assertFalse(panel.suspended);
            assertFalse(panel.captures.isEmpty());
            assertTrue(panel.captures.stream().allMatch("Returned A"::equals));
            assertEquals(300, panel.snapshot.net);
            return null;
        });
    }

    @Test public void directResumeCompletesAPendingClearForTheSameGeneration() throws Exception {
        CountingPanel panel = panel();
        panel.ledgerSearch = "old search";
        try (BlockedEdt edt = new BlockedEdt()) {
            edt.client(panel::suspend);
            edt.beforeQueued = panel::resume;
        }
        onEdt(() -> {
            assertFalse(panel.suspended);
            assertEquals("", panel.ledgerSearch);
            assertNotNull("the late clear must not erase the resumed snapshot", panel.snapshot);
            assertFalse(panel.captures.isEmpty());
            assertTrue(panel.captures.stream().allMatch("Owner A"::equals));
            return null;
        });
    }

    @Test public void queuedOldOwnerEditCannotMutateTheReturnedAccount() throws Exception {
        CountingPanel panel = panel();
        AtomicReference<Runnable> pending = new AtomicReference<>();
        panel.mutationOwner = pending::set;
        onEdt(() -> { panel.mutate(() -> panel.engine.session().rename("stale edit")); return null; });
        try (BlockedEdt edt = new BlockedEdt()) {
            edt.client(() -> {
                panel.suspend(); load(panel.engine, "b", "Owner B", 200); panel.resume();
                panel.suspend(); load(panel.engine, "a", "Returned A", 300); panel.resume();
                pending.get().run();
            });
        }
        assertEquals("Returned A", panel.engine.session().name());
    }

    @Test public void aNewFenceDuringResumeCannotBeLiftedByThatResume() throws Exception {
        CountingPanel panel = panel();
        panel.suspend();
        onEdt(() -> null);
        CountDownLatch entered = new CountDownLatch(1), release = new CountDownLatch(1);
        panel.clearHook = () -> {
            entered.countDown();
            try {
                if (!release.await(5, TimeUnit.SECONDS)) throw new AssertionError("resume gate timed out");
            } catch (InterruptedException ex) { throw new AssertionError(ex); }
        };
        try {
            panel.resume();
            assertTrue(entered.await(2, TimeUnit.SECONDS));
            panel.suspend();
            assertTrue(panel.suspended);
        } finally {
            release.countDown();
            onEdt(() -> null);
        }
        assertTrue("a stale in-progress resume cannot lift the new synchronous fence", panel.suspended);
        assertTrue(panel.captures.isEmpty());
    }

    private static CountingPanel panel() throws Exception {
        JsonCodec.bind(new com.google.gson.Gson());
        Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        load(engine, "a", "Owner A", 100);
        return onEdt(() -> {
            CountingPanel panel = new CountingPanel(engine);
            panel.active = true;
            panel.refreshNow();
            panel.captures.clear();
            return panel;
        });
    }

    private static void load(Engine engine, String owner, String name, long gp) {
        var session = new Session(name, NOW, SessionMode.GENERAL);
        session.addTransaction(Tx.of(NOW, TransactionType.GAIN, Context.GENERIC, "Owner", true,
                Collections.singletonList(new Flow(995, "Coins", gp, 1, gp))), 2000, false);
        engine.restoreProfile("rsprofile." + owner, new SavedState(session, null, Collections.emptyList()), NOW);
    }

    private static class CountingPanel extends SidebarPanel {
        final List<String> captures = new ArrayList<>();
        volatile Runnable clearHook;
        CountingPanel(Engine engine) { super(engine, new GpManagerConfig() {}, null, null, null); }
        @Override void clearOwner(Object owner) {
            super.clearOwner(owner);
            if (clearHook != null) clearHook.run();
        }
        @Override void refreshNow() {
            if (captures != null && !suspended) captures.add(engine.session().name());
            super.refreshNow();
        }
    }

    private static class BlockedEdt implements AutoCloseable {
        final CountDownLatch entered = new CountDownLatch(1), release = new CountDownLatch(1);
        final ExecutorService caller = Executors.newSingleThreadExecutor();
        final AtomicReference<Throwable> failure = new AtomicReference<>();
        volatile Runnable beforeQueued = () -> {};
        BlockedEdt() throws Exception {
            SwingUtilities.invokeLater(() -> {
                entered.countDown();
                try {
                    if (!release.await(5, TimeUnit.SECONDS)) throw new AssertionError("EDT gate timed out");
                    beforeQueued.run();
                } catch (Throwable ex) { failure.set(ex); }
            });
            assertTrue(entered.await(2, TimeUnit.SECONDS));
        }
        void client(Runnable work) throws Exception { caller.submit(work).get(1, TimeUnit.SECONDS); }
        public void close() throws Exception {
            release.countDown();
            caller.shutdown();
            assertTrue(caller.awaitTermination(5, TimeUnit.SECONDS));
            onEdt(() -> null);
            if (failure.get() != null) throw new AssertionError(failure.get());
        }
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-09: a sale collected while still in progress (1,300 of 1,927 revenant ether, then
 * 500, then the last 127) books one settlement per collect. Live shows them as the offer's one
 * market row with the running total and Result, never as a separate "Traded" item cost.
 */
public class PartialSaleRecentTest
{
    private static final int COINS = 995;
    private static final int ETHER = 21820;

    private final OfferSlots ledger = new OfferSlots();
    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 1_000_000L, ETHER, 1_927L));
    private final Engine engine = new Engine(deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, id == COINS ? "Coins" : "Revenant ether", quantity,
            id == COINS ? 1 : 174, quantity * (id == COINS ? 1 : 174), id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE)));
        return flows;
    }, new TransactionClassifier(), new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    });
    private long now = System.currentTimeMillis() - 600_000L;

    @Test
    public void aSaleCollectedInPartsIsOneMarketRowWithTheRunningResult()
    {
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
        offer(SELLING, 0, 0);
        move(ETHER, -1_927L);

        offer(SELLING, 1_300, 226_200);
        collect(222_300L);
        check("first collect", 1_300L, 222_300L, -3_900L);

        offer(SELLING, 1_800, 313_200);
        collect(85_500L);
        check("second collect", 1_800L, 307_800L, -5_400L);

        offer(SELLING, 1_927, 335_298);
        offer(SOLD, 1_927, 335_298);
        collect(21_717L);
        offer(EMPTY, 0, 0);
        check("last collect", 1_927L, 329_517L, -5_781L);
        assertEquals("three settlements, one per collect", 3, engine.session().transactions().size());
        assertEquals("only the tax is lost", -5_781L, engine.metrics(now).net);
    }

    private void check(String step, long quantity, long received, long result)
    {
        Map<String, MarketRows.Row> rows = new HashMap<>();
        for (MarketRows.Row row : engine.marketRows())
        {
            rows.put(row.presentationId, row);
            assertEquals(step + ": the Result adds every settlement", result, row.realizedResultGp);
        }
        List<LiveSnapshot.Recent> recent = LiveSnapshot.recentRows(engine.summary().view(engine.summary().scope(
            Collections.singletonList(engine.session())), LiveContext.NONE::flowVisible), rows, null);
        assertEquals(step + ": one row, no separate Traded item cost", 1, recent.size());
        LiveSnapshot.Recent row = recent.get(0);
        assertTrue(step, row.market);
        assertEquals(step, quantity, row.quantity);
        assertEquals(step + ": the received cash so far", received, row.value);
    }

    private void offer(GrandExchangeOfferState state, int traded, int spent)
    {
        now += 1_000L;
        boolean empty = state == EMPTY;
        OfferSlots.Transition transition = ledger.observe(new OfferSlots.Snapshot(0, state, empty ? 0 : ETHER,
            empty ? 0 : 1_927, traded, empty ? 0 : 174, spent)).orElse(null);
        if (transition != null)
        {
            engine.noteGeOffer(transition, "Revenant ether", now);
        }
    }

    private void collect(long coins)
    {
        now += 3_000L;
        engine.noteGeCollect(now);
        move(COINS, coins);
    }

    private void move(int item, long delta)
    {
        inventory.merge(item, delta, Long::sum);
        inventory.values().removeIf(quantity -> quantity == 0L);
        now += 600L;
        engine.markDirty();
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now, null);
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now + 1L, null);
    }
}

package com.gpmanager;

import java.util.Collections;
import javax.swing.JButton;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Owner 2026-10-01 (F06): a save failure stays visible until the backend actually recovers. */
public class PersistentSaveStatusTest
{
    @Test
    public void aStickyFailureIgnoresTheTimerAndTextClicks() throws Exception
    {
        Fixture fixture = new Fixture();
        onEdt(() ->
        {
            fixture.shell.notifySticky("Data not saved", "disk full", "Retry", () -> { });
            assertTrue(fixture.shell.notice.isVisible());
            assertFalse("a failure has no auto-dismiss timer", fixture.shell.timer.isRunning());
            fixture.shell.noticeClicked();
            assertTrue("a text click does not dismiss a failure", fixture.shell.notice.isVisible());
            fixture.shell.tell("Saved as My Grind", "future defaults only", false);
            assertTrue("routine news never replaces a failure",
                ShellProbe.noticeText(fixture.shell).startsWith("Data not saved"));
            fixture.shell.clearSticky();
            assertFalse("recovery takes the failure down", fixture.shell.notice.isVisible());
            fixture.shell.tell("Saved as My Grind", "future defaults only", false);
            assertTrue("routine news flows again",
                ShellProbe.noticeText(fixture.shell).startsWith("Saved as My Grind"));
            return null;
        });
    }

    @Test
    public void retryRunsAndAPersistingFailureComesBack() throws Exception
    {
        Fixture fixture = new Fixture();
        boolean[] retried = {false};
        onEdt(() ->
        {
            fixture.shell.notifySticky("Data not saved", "disk full", "Retry", () -> retried[0] = true);
            ((JButton) fixture.shell.noticeAction.getComponent(0)).doClick();
            assertTrue("the retry action runs", retried[0]);
            assertFalse("the attempt hides the failure", fixture.shell.notice.isVisible());
            fixture.shell.notifySticky("Data not saved", "disk full", "Retry", () -> { });
            assertTrue("still failing means still visible", fixture.shell.notice.isVisible());
            assertFalse("and still no timer", fixture.shell.timer.isRunning());
            return null;
        });
    }

    @Test
    public void theSidebarFollowsTheBackendStatusUntilRecovery() throws Exception
    {
        FakePersist persist = new FakePersist();
        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine(), new GpManagerConfig() {}, null, null, persist));
        Shell shell = panel.shell;
        onEdt(() ->
        {
            persist.status = new SaveStatus(SaveStatus.State.FAILED, "disk full", false, "");
            panel.showPersistenceWarning();
            assertTrue(shell.notice.isVisible());
            assertTrue(ShellProbe.noticeText(shell).startsWith("Data not saved"));
            panel.showPersistenceWarning();
            assertTrue("a repeated failing status stays up", shell.notice.isVisible());

            persist.status = new SaveStatus(SaveStatus.State.OK, "", false, "backup-2026");
            panel.showPersistenceWarning();
            assertTrue("recovery replaces it with the recovery note",
                ShellProbe.noticeText(shell).startsWith("Recovered from backup"));
            assertTrue("routine recovery has a timer", shell.timer.isRunning());

            persist.status = new SaveStatus(SaveStatus.State.FAILED, "disk full", false, "");
            panel.showPersistenceWarning();
            assertTrue(shell.notice.isVisible());
            panel.suspend();
            assertFalse("a profile switch drops the old profile's failure", shell.notice.isVisible());
            return null;
        });
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig() {});
    }

    private static final class Fixture
    {
        final SidebarPanel panel;
        final Shell shell;

        Fixture() throws Exception
        {
            panel = onEdt(() -> new SidebarPanel(engine(), new GpManagerConfig() {}, null, null, null));
            shell = panel.shell;
        }
    }

    /** Returns the status the test chooses; the real writer is never involved. */
    private static final class FakePersist extends Persistence
    {
        SaveStatus status = SaveStatus.neverSaved();

        FakePersist()
        {
            super(null, null, null, null, null);
        }

        @Override
        SaveStatus saveStatus()
        {
            return status;
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        Object[] result = new Object[1];
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result[0] = callable.call();
            }
            catch (Exception ex)
            {
                throw new RuntimeException(ex);
            }
        });
        return (T) result[0];
    }
}

