    @Test public void sessionHelpFitsTheNarrowSheet() throws Exception {
        onEdt(() -> {
            SidebarPanel panel = RateRestartTest.panel(engine());
            new GrindsController(panel).newSession();
            for (int width : new int[]{173, 185, 260}) {
                DirectHeaderControlsTest.size(panel.shell.sheet, width);
                boolean found = false;
                java.util.ArrayDeque<java.awt.Component> pending = new java.util.ArrayDeque<>();
                pending.add(panel.shell.sheet);
                while (!pending.isEmpty()) {
                    java.awt.Component component = pending.removeFirst();
                    if (component instanceof java.awt.Container)
                        java.util.Collections.addAll(pending, ((java.awt.Container) component).getComponents());
                    if (component instanceof javax.swing.JLabel
                            && ((javax.swing.JLabel) component).getText().startsWith("<html>")) {
                        found = true;
                        assertTrue("help fits the inner sheet at " + width,
                                component.getPreferredSize().width <= component.getWidth());
                    }
                }
                assertTrue("Session controls has readable help", found);
            }
            return null;
        });
    }

    @Test public void compactControlsKeepTwoButtonRowsAndDetailedHelp() throws Exception {
        onEdt(() -> {
            SidebarPanel panel = RateRestartTest.panel(engine());
            new GrindsController(panel).newSession();
            java.util.List<javax.swing.JButton> buttons = ShellProbe.sheetButtons(panel.shell);
            javax.swing.JButton fresh = buttons.stream().filter(b -> b.getText().equals("New session")).findFirst().get();
            javax.swing.JButton restore = buttons.stream().filter(b -> b.getText().equals("Restore time")).findFirst().get();
            javax.swing.JButton restart = buttons.stream().filter(b -> b.getText().equals("Restart GP/h")).findFirst().get();
            javax.swing.JButton cancel = buttons.stream().filter(b -> b.getText().equals("Cancel")).findFirst().get();
            assertEquals(4, buttons.size());
            assertSame(fresh.getParent(), restore.getParent());
            assertSame(restart.getParent(), cancel.getParent());
            assertNotSame(fresh.getParent(), restart.getParent());
            assertFalse(fresh.getToolTipText().isEmpty());
            assertTrue(restore.getToolTipText().contains("original"));
            for (int width : new int[]{173, 185, 260}) {
                DirectHeaderControlsTest.size(panel.shell.sheet, width);
                assertTrue("compact sheet at " + width, panel.shell.sheet.getHeight() <= 160);
                for (javax.swing.JButton button : buttons) {
                    java.awt.Rectangle box = DirectHeaderControlsTest.bounds(button, panel.shell.sheet);
                    assertTrue(button.getText() + " stays inside at " + width,
                            box.x >= 0 && box.getMaxX() <= width && box.y >= 0
                                    && box.getMaxY() <= panel.shell.sheet.getHeight());
                    assertTrue(button.getText() + " stays readable at " + width,
                            button.getFontMetrics(button.getFont()).stringWidth(button.getText())
                                    + button.getInsets().left + button.getInsets().right <= button.getWidth());
                }
            }
            return null;
        });
    }

    static void choose(Engine engine, long at, String choice) {
        SafeMath.clock = () -> at;
        SidebarPanel panel = RateRestartTest.panel(engine);
        new GrindsController(panel).newSession();
        assertTrue("Session controls offers " + choice, ShellProbe.sheetButtonTexts(panel.shell).contains(choice));
        ShellProbe.pressSheet(panel.shell, choice);
        assertEquals("", panel.shell.heading);
    }

    private static void assertClock(Engine engine, long at, long elapsed, long rate) {
        LiveSnapshot live = live(engine, at);
        assertEquals("Live Active Time", elapsed, live.elapsed);
        if (elapsed >= MINUTE || elapsed == 0L) assertEquals(rate, live.rate);
        assertEquals(elapsed >= MINUTE, live.ready);
        HudBuilder builder = new HudBuilder(HudBuilderTest.config(false, 4), null);
        HudFrame hud = builder.update(live, f -> true, at);
        assertEquals(builder.timer(elapsed), hud.timer);
        assertEquals(LivePage.rateText(live.ready, rate), hud.rate);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * One cross-surface rate law: an immature/unavailable rate never renders as 0/h, every surface
 * agrees for identical canonical facts, and Pace only answers a question that exists.
 */
public class RatePaceConsistencyTest
{
    @Test
    public void immatureRateIsUnavailableNotZeroOnEverySurface() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now - 19_000L);
        engine.session().addTransaction(consumed(now - 10_000L, "Prayer potion(4)", 3, -1, 100, -100L), 2_000, false);

        LiveSnapshot live = LiveSnapshot.capture(engine, now, LiveContext.NONE);
        assertTrue("nineteen seconds is not a trustworthy rate window", live.elapsed < RateReadiness.MIN_ACTIVE_MILLIS);
        assertFalse("Live must not claim an established rate", live.ready);
        assertEquals("Calculating…", LivePage.rateText(live.ready, live.rate));

        GrindsData grinds =
            GrindsData.capture(engine, now, false, null);
        assertFalse("Grinds must agree with Live", grinds.ready);
        assertEquals("—  GP/h", GrindsPage.rateLine(
            grinds.ready, grinds.rate));
        assertEquals("both surfaces agree exactly",
            live.ready, grinds.ready);
    }

    @Test
    public void matureRateMayShowAZeroBecauseItIsReal() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now - 5 * 60_000L);
        // Balanced receipts: a real booked net of zero, with a mature Active-Time window.
        engine.session().addTransaction(gain(now - 4 * 60_000L, 100L), 2_000, false);
        engine.session().addTransaction(consumed(now - 3 * 60_000L, "Prayer potion(4)", 3, -1, 100, -100L), 2_000, false);

        LiveSnapshot live = LiveSnapshot.capture(engine, now, LiveContext.NONE);
        assertTrue("five minutes is a mature window", live.elapsed >= RateReadiness.MIN_ACTIVE_MILLIS);
        assertTrue("the canonical rolling rate is available", live.ready);
        assertEquals("0/h", LivePage.rateText(live.ready, live.rate));

        GrindsData grinds =
            GrindsData.capture(engine, now, false, null);
        assertTrue(grinds.ready);
        assertEquals("0/h", GrindsPage.rateLine(
            grinds.ready, grinds.rate));
    }

    @Test
    public void positiveAndNegativeRatesStillRenderTruthfully() throws Exception
    {
        assertEquals("2.03M/h", LivePage.rateText(true, 2_030_000L));
        assertEquals("\u2212412k/h", LivePage.rateText(true, -412_000L));
        assertEquals("Calculating…", LivePage.rateText(false, 0L));
    }

    @Test
    public void paceAnswersOnlyQuestionsThatExist() throws Exception
    {
        // No targets: no Pace row, no Calculating, no dead space.
        GrindsData.Pace none =
            GrindsData.pace(null, null, 0L, false, 0L, 0L);
        assertFalse(none.present);
        assertFalse(none.available);
        assertEquals("", none.line);

        // Target present but immature evidence: Calculating (not a fabricated projection).
        GrindsData.Pace netPending =
            GrindsData.pace(5_000_000L, null, 0L, false, 0L, 20_000L);
        assertTrue(netPending.present);
        assertFalse(netPending.available);
        assertEquals("Calculating\u2026", netPending.line);

        GrindsData.Pace timePending =
            GrindsData.pace(null, 3L * 3_600_000L, 0L, false, 0L, 20_000L);
        assertTrue(timePending.present);
        assertEquals("Calculating\u2026", timePending.line);

        GrindsData.Pace bothPending =
            GrindsData.pace(5_000_000L, 3L * 3_600_000L, 0L, false, 0L, 20_000L);
        assertTrue(bothPending.present);
        assertEquals("Calculating\u2026", bothPending.line);

        // Trustworthy evidence: the truthful approximate output returns.
        GrindsData.Pace ready =
            GrindsData.pace(5_000_000L, null, 2_840_000L, true, 2_030_000L, 3_600_000L);
        assertTrue(ready.present);
        assertTrue(ready.available);
        assertTrue(ready.line.contains("remaining"));

        // A mature zero rate is still an established answer: no fake ETA, never "Calculating".
        GrindsData.Pace zeroRate =
            GrindsData.pace(5_000_000L, null, 0L, true, 0L, 300_000L);
        assertTrue(zeroRate.present);
        assertTrue("an established rate always produces an answer", zeroRate.available);
        assertEquals("Not earning at this rate", zeroRate.line);

        GrindsData.Pace negativeRate =
            GrindsData.pace(5_000_000L, null, 0L, true, -200_000L, 300_000L);
        assertTrue(negativeRate.available);
        assertEquals("Not earning at this rate", negativeRate.line);
    }

    @Test
    public void establishedRatesProjectTruthfullyEvenWhenNonPositive() throws Exception
    {
        // Net-only positive: an ETA; zero/negative: an honest "not on pace", never Calculating.
        GrindsData.Pace positive =
            GrindsData.pace(5_000_000L, null, 2_840_000L, true, 2_030_000L, 3_600_000L);
        assertTrue(positive.available);
        assertTrue(positive.line.contains("remaining"));

        // Time-only: the countdown, whatever the rate (owner 1.5.2: no projected Net).
        GrindsData.Pace flat =
            GrindsData.pace(null, 3L * 3_600_000L, 2_000_000L, true, -200_000L,
                1L * 3_600_000L);
        assertTrue(flat.available);
        assertEquals("2h 0m left", flat.line);

        // Both targets with an established negative rate still give the countdown and requirement.
        GrindsData.Pace both =
            GrindsData.pace(5_000_000L, 3L * 3_600_000L, 2_000_000L, true,
                -200_000L, 1L * 3_600_000L);
        assertTrue(both.available);
        assertEquals("2h 0m left", both.line);
        assertNotNull(both.second);
        assertTrue(both.second.contains("Required average"));

        // Target already reached only when the established evidence says so.
        GrindsData.Pace reached =
            GrindsData.pace(1_000_000L, null, 2_000_000L, true, 0L, 300_000L);
        assertEquals("Target reached", reached.line);

        // Projection never writes accounting.
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now - 5 * 60_000L);
        engine.session().addTransaction(gain(now - 4 * 60_000L, 1_000L), 2_000, false);
        long net = engine.metrics(now).net;
        long revision = engine.revision();
        GrindsData.capture(engine, now, false, null);
        GrindsData.pace(1_000_000L, 3L * 3_600_000L, net, true, -1L, 300_000L);
        assertEquals("estimates never book", net, engine.metrics(now).net);
        assertEquals("estimates never revise", revision, engine.revision());
    }

    @Test
    public void rateDerivationNeverTouchesAccounting() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now - 20_000L);
        long net = engine.metrics(now).net;
        long revision = engine.revision();
        for (int i = 0; i < 5; i++)
        {
            LiveSnapshot.capture(engine, now, LiveContext.NONE);
            GrindsData.capture(engine, now, false, null);
        }
        assertEquals("derivation never books", net, engine.metrics(now).net);
        assertEquals("derivation never revises", revision, engine.revision());
    }

    private static Transaction gain(long at, long value)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(1, "Dragon bones", 1, (int) value, value)),
            Confidence.LIKELY, "test", null);
    }

    private static Transaction consumed(long at, String name, int itemId, long quantity, int unitPrice, long value)
    {
        return new Transaction(at, TransactionType.CONSUMPTION, Context.GENERIC, "", "Vorkath",
            true, Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value)),
            Confidence.LIKELY, "test", null);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.function.LongSupplier;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static com.gpmanager.MilestoneTest.onEdt;
import static com.gpmanager.TargetFreshStartTest.*;
import static org.junit.Assert.*;

/** Restarting the clock recalculates displayed Net over the new Active Time, keeping accounting. */
public class RateRestartTest {
    private LongSupplier clock;
    @Before public void setUp() { clock = SafeMath.clock; JsonCodec.bind(new Gson()); }
    @After public void restoreClock() { SafeMath.clock = clock; }

    @Test public void retainedNetSetsTheRateAtOneMinuteAndItFallsWithActiveTime() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            coins(engine, 5L, 566_329L);
            restart(engine, HOUR);
            LiveSnapshot waiting = live(engine, HOUR + MINUTE - 1L);
            assertFalse(waiting.ready);
            assertEquals("Calculating…", LivePage.rateText(waiting.ready, waiting.rate));
            long[] activeMillis = {MINUTE, 72_000L, 2L * MINUTE, HOUR};
            long[] expectedRates = {33_979_740L, 28_316_450L, 16_989_870L, 566_329L};
            for (int i = 0; i < activeMillis.length; i++) {
                LiveSnapshot next = live(engine, HOUR + activeMillis[i]);
                assertTrue(next.ready);
                assertEquals(activeMillis[i], next.elapsed);
                assertEquals(expectedRates[i], next.rate);
                assertEquals(566_329L, next.net);
                assertEquals(566_329L, recentTotal(next));
                HudFrame hud = new HudBuilder(HudBuilderTest.config(false, 4), null)
                        .update(next, f -> true, HOUR + activeMillis[i]);
                assertEquals(LivePage.rateText(true, expectedRates[i]), hud.rate);
            }
            return null;
        });
    }

    @Test public void restartUsesTheDisplayedSessionNetInsteadOfOlderRunReceipts() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            coins(engine, 5L, 500_000L);
            engine.newLive(HOUR);
            coins(engine, HOUR + 5L, 566_329L);
            restart(engine, 2L * HOUR);
            LiveSnapshot next = live(engine, 2L * HOUR + MINUTE);
            assertEquals(566_329L, next.net);
            assertEquals(1_066_329L, next.run);
            assertEquals(566_329L, recentTotal(next));
            assertEquals(33_979_740L, next.rate);
            assertEquals(MINUTE, next.elapsed);
            return null;
        });
    }

    @Test public void freePlayKeepsNetRecentAndLedgerWhileRateUsesTheRetainedNet() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            coins(engine, 5L, 500_000L);
            Session run = engine.session();
            ContainerSnapshot baseline = FixtureReads.empty();
            engine.baseline = baseline;
            restart(engine, HOUR);
            assertSame("a rate reset cannot re-prime inventory or lose pending movement", baseline, engine.baseline);
            LiveSnapshot just = live(engine, HOUR);
            assertEquals(500_000L, just.net);
            assertEquals(500_000L, recentTotal(just));
            assertEquals(0L, just.elapsed);
            assertEquals(0L, just.rate);
            assertFalse(just.ready);
            coins(engine, HOUR + 5L, 50_000L);
            LiveSnapshot next = live(engine, HOUR + HOUR / 2L);
            assertEquals(550_000L, next.net);
            assertEquals(550_000L, next.run);
            assertEquals(550_000L, recentTotal(next));
            assertEquals(HOUR / 2L, next.elapsed);
            assertEquals(1_100_000L, next.rate);
            assertSame(run, engine.session());
            assertEquals(2, run.transactions().size());
            assertTrue(engine.history().isEmpty());
            assertEquals(550_000L, engine.summary().metrics(run, HOUR + HOUR / 2L).net);
            HudFrame hud = new HudBuilder(HudBuilderTest.config(false, 4), null)
                    .update(next, f -> true, HOUR + HOUR / 2L);
            assertEquals(Fmt.signed(next.net), hud.net);
            assertEquals(LivePage.rateText(true, next.rate), hud.rate);
            assertEquals(new HudBuilder(HudBuilderTest.config(false, 4), null).timer(next.elapsed), hud.timer);
            return null;
        });
    }

    @Test public void lossesAndRepeatedRestartsUseTheDisplayedSignedNet() throws Exception {
        onEdt(() -> {
            for (long base : new long[]{0L, -1_000L}) {
                Engine engine = engine();
                if (base != 0L) coins(engine, 5L, base);
                restart(engine, HOUR);
                coins(engine, HOUR + 5L, -200L);
                assertEquals(base - 200L, live(engine, 2L * HOUR).net);
                assertEquals(base - 200L, live(engine, 2L * HOUR).rate);
                restart(engine, 2L * HOUR);
                coins(engine, 2L * HOUR + 5L, 50L);
                assertEquals(base - 150L, live(engine, 3L * HOUR).net);
                assertEquals(base - 150L, live(engine, 3L * HOUR).rate);
            }
            Engine extreme = engine();
            coins(extreme, 5L, Long.MIN_VALUE + 1L);
            restart(extreme, HOUR);
            coins(extreme, HOUR + 5L, Long.MAX_VALUE);
            coins(extreme, HOUR + 6L, Long.MAX_VALUE);
            assertEquals("saturated revenue and costs leave zero displayed Net", 0L,
                    live(extreme, 2L * HOUR).net);
            assertEquals(0L, live(extreme, 2L * HOUR).rate);
            for (long net : new long[]{Long.MAX_VALUE, -Long.MAX_VALUE}) {
                Engine signed = engine();
                coins(signed, 5L, net);
                restart(signed, HOUR);
                LiveSnapshot next = live(signed, HOUR + MINUTE);
                assertEquals(net, next.net);
                assertEquals("a signed rate saturates rather than wrapping",
                        net > 0L ? Long.MAX_VALUE : Long.MIN_VALUE, next.rate);
            }
            return null;
        });
    }

    @Test public void netTimeTargetsAndMilestonesKeepTheirOwnProgress() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            engine.setTargets(5_000L, 4L * HOUR, 0L);
            engine.setMilestone(400_000L);
            coins(engine, 5L, 1_000L);
            LiveSnapshot before = live(engine, HOUR);
            restart(engine, HOUR);
            LiveSnapshot after = live(engine, HOUR);
            assertEquals(before.goal.current, after.goal.current);
            assertEquals(before.goal.remaining, after.goal.remaining);
            assertEquals(before.milestone, after.milestone);
            assertEquals(before.run, after.run);
            coins(engine, HOUR + 5L, 500L);
            LiveSnapshot next = live(engine, HOUR + HOUR / 2L);
            assertEquals(1_500L, next.goal.current);
            assertEquals(5L * HOUR / 2L, next.goal.remaining);
            assertEquals(3_000L, next.rate);
            return null;
        });
    }

    @Test public void pausedRestartsStayPausedAndExcludeThePausedTime() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            coins(engine, 5L, 1_000L);
            engine.togglePause(HOUR);
            restart(engine, 2L * HOUR);
            assertTrue(engine.session().paused);
            assertEquals(0L, live(engine, 3L * HOUR).elapsed);
            engine.togglePause(3L * HOUR);
            coins(engine, 3L * HOUR + 5L, 500L);
            LiveSnapshot next = live(engine, 4L * HOUR);
            assertEquals(HOUR, next.elapsed);
            assertEquals(1_500L, next.rate);
            assertEquals(1_500L, next.net);
            return null;
        });
    }

    @Test public void undoAndRestoreKeepTheRateAlignedWithDisplayedNet() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            coins(engine, 5L, 1_000L);
            restart(engine, HOUR);
            engine.undoTransaction();
            assertEquals(0L, live(engine, 2L * HOUR).net);
            assertEquals("zero displayed Net means a zero rate", 0L,
                    live(engine, 2L * HOUR).rate);
            engine.restoreUndo();
            assertEquals(1_000L, live(engine, 2L * HOUR).net);
            assertEquals(1_000L, live(engine, 2L * HOUR).rate);
            coins(engine, HOUR + 5L, 500L);
            assertEquals(1_500L, live(engine, 2L * HOUR).rate);
            return null;
        });
    }

    @Test public void savedRateWindowsRoundTripAndOlderOrInvalidMarksUseTheNormalRate() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            coins(engine, 5L, 1_000L);
            restart(engine, HOUR);
            coins(engine, HOUR + 5L, 500L);
            Gson gson = new Gson();
            JsonObject json = gson.toJsonTree(engine.exportState()).getAsJsonObject();
            Engine loaded = load(json, 2L * HOUR);
            assertEquals(1_500L, live(loaded, 2L * HOUR).net);
            assertEquals(1_500L, live(loaded, 2L * HOUR).rate);
            assertEquals(HOUR, live(loaded, 2L * HOUR).elapsed);
            JsonObject savedRun = json.getAsJsonObject("generalSession");
            savedRun.remove("rateStartAt");
            savedRun.remove("rateSetMillis");
            savedRun.addProperty("rateSetNet", 1_000L);
            assertEquals(750L, live(load(json, 2L * HOUR), 2L * HOUR).rate);
            for (long invalid : new long[]{-1L, 3L * HOUR}) {
                savedRun.addProperty("rateStartAt", HOUR);
                savedRun.addProperty("rateSetMillis", invalid);
                assertEquals(750L, live(load(json, 2L * HOUR), 2L * HOUR).rate);
                savedRun.addProperty("rateSetMillis", HOUR);
                savedRun.addProperty("rateStartAt", invalid);
                assertEquals(750L, live(load(json, 2L * HOUR), 2L * HOUR).rate);
            }
            return null;
        });
    }

    @Test public void wholeRunBookingsRestoreTheOriginalClock() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            coins(engine, 5L, 1_000L);
            restart(engine, HOUR);
            engine.newLive(2L * HOUR);
