    @Test public void grindHistoryKeepsTheWholeRunAndAnotherGrindGetsNoOldBaseline() throws Exception {
        onEdt(() -> {
            Engine engine = engine();
            engine.startCustom("Vorkath", 0L);
            coins(engine, 5L, 1_000L);
