            String id = EngineProbe.saveLiveSession(engine, source, source.sessionStartAt, 2 * MINUTE);
            AtomicReference<String> copied = new AtomicReference<>("unchanged");
            GrindsController controller = controller(RateRestartTest.panel(engine), copied);
            assertTrue(engine.deleteHistory(id));
            controller.copySummary(id);
            assertEquals("unchanged", copied.get());
            return null;
        });
    }

    @Test public void clipboardFailureReportsLocallyAndKeepsTheSession() throws Exception
    {
        onEdt(() ->
        {
            Engine engine = SavedSessionTest.window();
            SidebarPanel panel = RateRestartTest.panel(engine);
            SafeMath.clock = () -> 2 * MINUTE;
            GrindsController controller = new GrindsController(panel)
            {
                @Override void copyText(String text) { throw new IllegalStateException("clipboard busy"); }
            };
            copyLive(controller);
            assertEquals("Copy failed · clipboard busy", panel.shell.message.getToolTipText());
            assertEquals(1_500L, engine.metrics(2 * MINUTE).net);
            return null;
        });
    }

    @Test public void summariesKeepUnavailableCostSplitsUnsplit()
    {
        String text = GrindsController.summary("Old run", 50, 100, 50, -1, -1, false, MINUTE);
        assertTrue(text.contains("Costs: 50 gp"));
        assertFalse(text.contains("Supplies:"));
        assertFalse(text.contains("Losses:"));
    }

    static GrindsController controller(SidebarPanel panel, AtomicReference<String> copied)
    {
        return new GrindsController(panel)
        {
            @Override void copyText(String text) { copied.set(text); }
        };
    }

    static JMenuItem liveItem(GrindsController controller)
    {
        for (java.awt.Component component : controller.dataMenu().getComponents())
            if (component instanceof JMenuItem && "Copy Live summary".equals(((JMenuItem) component).getText()))
                return (JMenuItem) component;
        fail("gear menu offers Copy Live summary");
        return null;
    }

    static void copyLive(GrindsController controller) { liveItem(controller).doClick(); }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static com.gpmanager.SwingTestSupport.onEdt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The shell restores exactly the four selected top-level pages, Live by default. */
public class ShellNavigationTest
{
    @Test
    public void navigationHasExactlyTheThreeFinalLabelsWithoutDecorativeGlyphs() throws Exception
    {
        SidebarPanel panel = onEdt(() -> new SidebarPanel(PresentationLifecycleTest.engine(),
            PresentationLifecycleTest.config(), null, null, null));
        Shell shell = panel.shell;
        assertEquals(3, ShellProbe.tabLabels(shell).length);
        assertEquals("live", shell.current);
        assertEquals(List.of("Live", "Ledger", "Grinds"), List.of(ShellProbe.tabLabels(shell)));
        for (String label : ShellProbe.tabLabels(shell))
        {
            assertEquals("text-first tab label", label, label.trim());
            assertTrue("no decorative pictogram in the final navigation: " + label,
                label.matches("[A-Za-z ]+"));
        }
    }

    @Test
    public void ledgerPlaceholderIsReplacedByTheRealAuditSurface() throws Exception
    {
        SidebarPanel panel = onEdt(() -> new SidebarPanel(PresentationLifecycleTest.engine(),
            PresentationLifecycleTest.config(), null, null, null));
        panel.shell.show(Shell.LEDGER);
        java.util.List<String> labels = new java.util.ArrayList<>();
        collectLabels(panel, labels);
        assertFalse("no placeholder copy remains on Ledger", labels.contains("Ledger recovery pending R2"));
    }

    @Test
    public void notificationShowsOneMessageAndDismissesOnDemand() throws Exception
    {
        SidebarPanel panel = onEdt(() -> new SidebarPanel(PresentationLifecycleTest.engine(),
            PresentationLifecycleTest.config(), null, null, null));
        Shell shell = panel.shell;
        onEdt(() ->
        {
            shell.notify("Exported Vorkath", "vorkath.csv", false, null, null);
            shell.notify("Backup failed", "disk full", true, null, null);
            return null;
        });
        assertEquals("only the latest message shows", "Backup failed \u00b7 disk full", ShellProbe.noticeText(shell));
        onEdt(() ->
        {
            shell.dismiss();
            return null;
        });
        assertEquals("", ShellProbe.noticeText(shell));
    }

    private static void collectLabels(java.awt.Container root, List<String> out)
    {
        if (root instanceof javax.swing.JLabel)
        {
            String text = ((javax.swing.JLabel) root).getText();
            if (text != null && !text.isEmpty())
            {
                out.add(text);
            }
        }
        for (java.awt.Component child : root.getComponents())
        {
            if (child instanceof java.awt.Container)
            {
                collectLabels((java.awt.Container) child, out);
            }
            else if (child instanceof javax.swing.JLabel)
            {
                String text = ((javax.swing.JLabel) child).getText();
                if (text != null && !text.isEmpty())
                {
                    out.add(text);
                }
            }
        }
    }

    @Test
    public void everyPageIsSelectableAndTheShellReturnsToLive() throws Exception
    {
        SidebarPanel panel = onEdt(() -> new SidebarPanel(PresentationLifecycleTest.engine(),
            PresentationLifecycleTest.config(), null, null, null));
        Shell shell = panel.shell;

        shell.show(Shell.LEDGER);
        assertEquals("ledger", shell.current);
        shell.show(Shell.GRINDS);
        assertEquals("grinds", shell.current);
        shell.show(Shell.LIVE);
        assertEquals("live", shell.current);
        assertEquals("live", ShellProbe.selectedTab(shell));
    }
}

