    private static Engine session()
    {
        Engine engine = PresentationLifecycleTest.engine();
        engine.startCustom("Vorkath", T0);
        return engine;
    }

    private static LedgerData capture(Engine engine, long now, LedgerData.Entry entry)
    {
        return LedgerData.capture(engine, now, entry);
    }

    private static Semantics.Group groupNamed(
        List<Semantics.Group> groups, String name)
    {
        for (Semantics.Group group : groups)
        {
            if (name.equals(group.name))
            {
                return group;
            }
        }
        return null;
    }

    private static Transaction exactCast(long at, String name, int deathQty, int chaosQty, int waterQty)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                new Flow(DEATH, "Death rune", -deathQty, 100, -deathQty * 100L),
                new Flow(CHAOS, "Chaos rune", -chaosQty, 50, -chaosQty * 50L),
                new Flow(WATER, "Water rune", -waterQty, 30, -waterQty * 30L)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setAction(ActionKind.CAST);
        transaction.setActionLabel(ActionLabel.of(name));
        return transaction;
    }

    private static Transaction gain(long at, String name, int itemId, long quantity,
        int unitPrice, long value)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath",
            true, java.util.Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value,
                PriceSource.GRAND_EXCHANGE)), Confidence.LIKELY, "Test gain", null);
    }

    private static Transaction food(long at, String name, int itemId, long value)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true,
            java.util.Collections.singletonList(new Flow(itemId, name, -1L, (int) value, -value,
                PriceSource.GRAND_EXCHANGE)), Confidence.CONFIRMED, "Test food", null);
        transaction.setAction(ActionKind.EAT);
        return transaction;
    }

    private static List<String> labels(Component component)
    {
        List<String> out = new ArrayList<>();
        walkLabels(component, out);
        return out;
    }

    private static void walkLabels(Component component, List<String> out)
    {
        if (component instanceof JLabel)
        {
            String text = ((JLabel) component).getText();
            if (text != null && !text.isEmpty())
            {
                out.add(text);
            }
        }
        if (component instanceof javax.swing.AbstractButton)
        {
            String text = ((javax.swing.AbstractButton) component).getText();
            if (text != null && !text.isEmpty())
            {
                out.add(text);
            }
        }
        if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                walkLabels(child, out);
            }
        }
    }

    private static boolean containsNav(Component component)
    {
        if (component instanceof net.runelite.client.ui.components.materialtabs.MaterialTabGroup)
        {
            return true;
        }
        if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                if (containsNav(child))
                {
                    return true;
                }
            }
        }
        return false;
    }

    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            return callable.call();
        }
        AtomicReference<T> value = new AtomicReference<>();
        AtomicReference<Throwable> failure = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() ->
        {
            try { value.set(callable.call()); }
            catch (Throwable ex) { failure.set(ex); }
        });
        if (failure.get() != null)
        {
            throw new AssertionError(failure.get());
        }
        return value.get();
    }

    private static final class NoopActions implements LedgerPage.Actions
    {
        @Override public void openScopeMenu(javax.swing.JComponent anchor) { }
        @Override public void costViewChanged(LedgerData.CostView view) { }
        @Override public void searchChanged(String text) { }
        @Override public LedgerData.CorrectionPreview preview(String id,
            Correction correction) { return null; }
        @Override public LedgerPage.CorrectionOutcome correct(String id,
            Correction correction, long previewRevision)
        { return LedgerPage.CorrectionOutcome.REFUSED; }
        @Override public void split(String id, java.util.function.BiConsumer<long[], LedgerData.CorrectionPreview> previewed) { }
        @Override public void undoCorrection() { }
        @Override public void refresh() { }
    }
}

package com.gpmanager;

import java.util.Collections;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

/** A tab fills at once when shown, and an unchanged page is not re-read or rebuilt on the way back. */
public class TabSwitchTest
{
    @Test
    public void aShownTabFillsAtOnceAndAnUnchangedPageKeepsItsRows() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(Tx.of(now, TransactionType.LOOT, Context.GENERIC, "", true,
            Collections.singletonList(new Flow(536, "Dragon bones", 1, 2_000, 2_000L))), 2_000, false);
        SidebarPanel[] holder = new SidebarPanel[1];
        SwingUtilities.invokeAndWait(() ->
        {
            holder[0] = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            holder[0].active = true;
        });
        SidebarPanel panel = holder[0];

        SwingUtilities.invokeAndWait(() -> panel.shell.show(Shell.LEDGER));
        SwingUtilities.invokeAndWait(() -> { });
        LedgerData first = panel.ledger.data;
        assertNotNull("the Ledger fills when shown, without waiting for a game tick", first);

        SwingUtilities.invokeAndWait(() -> panel.shell.show(Shell.LIVE));
        SwingUtilities.invokeAndWait(() -> panel.shell.show(Shell.LEDGER));
        SwingUtilities.invokeAndWait(() -> { });
        assertSame("nothing changed: the Ledger keeps its rows", first, panel.ledger.data);

        engine.session().addTransaction(Tx.of(now + 1_000L, TransactionType.LOOT, Context.GENERIC,
            "", true, Collections.singletonList(new Flow(536, "Dragon bones", 1, 2_000, 2_000L))), 2_000, false);
        SwingUtilities.invokeAndWait(() -> panel.shell.show(Shell.LIVE));
        SwingUtilities.invokeAndWait(() -> panel.shell.show(Shell.LEDGER));
        SwingUtilities.invokeAndWait(() -> { });
        assertNotSame("a new booking re-reads the Ledger", first, panel.ledger.data);
    }
}

package com.gpmanager;

import java.awt.Component;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static com.gpmanager.SwingTestSupport.onEdt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;

/**
 * The per-game-tick pulse must not rebuild the sidebar. Rebuilding every 0.6 s replaced the rows
 * a Swing menu was anchored to (the owner's disappearing dropdowns) and the labels a reader was
 * walking. Values still update in place, and a real data change still rebuilds.
 */
public class TickRefreshStabilityTest
{
    @Test
    public void liveRowsSurviveTicksAndRebuildOnlyWhenTheDataChanges() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(gain(now + 1_000L, "Dragon bones", 536, 3_200L), 2_000, false);
        SidebarPanel panel = onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            SidebarPanelProbe.refresh(created);
            return created;
        });
        List<Component> before = onEdt(() -> children(SidebarPanelProbe.livePage(panel).body()));

        for (int tick = 0; tick < 3; tick++)
        {
            panel.tick();
            flushEdt();
        }
        List<Component> afterTicks = onEdt(() -> children(SidebarPanelProbe.livePage(panel).body()));
        assertEquals(before.size(), afterTicks.size());
        for (int index = 0; index < before.size(); index++)
        {
            assertSame("tick " + index + " kept the same component", before.get(index), afterTicks.get(index));
        }

        engine.session().addTransaction(gain(now + 2_000L, "Rune platebody", 1127, 38_000L), 2_000, false);
        panel.tick();
        flushEdt();
        List<Component> afterBooking = onEdt(() -> children(SidebarPanelProbe.livePage(panel).body()));
        assertNotEquals("a new booking rebuilds the recent rows", before, afterBooking);
    }

    @Test
    public void openLedgerIsNotRebuiltByTicksButIsByANewBooking() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.session().addTransaction(gain(now + 1_000L, "Dragon bones", 536, 3_200L), 2_000, false);
        SidebarPanel panel = onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            SidebarPanelProbe.refresh(created);
            SidebarPanelProbe.openLedger(created, LedgerData.Entry.current());
            return created;
        });
        flushEdt();
        List<Component> before = onEdt(() -> children(SidebarPanelProbe.ledgerPage(panel).body()));

        panel.tick();
        flushEdt();
        panel.tick();
        flushEdt();
        List<Component> afterTicks = onEdt(() -> children(SidebarPanelProbe.ledgerPage(panel).body()));
        assertEquals("ticks never rebuild the open Ledger", before, afterTicks);

        engine.session().addTransaction(gain(now + 2_000L, "Rune platebody", 1127, 38_000L), 2_000, false);
        panel.tick();
        flushEdt();
        List<Component> afterBooking = onEdt(() -> children(SidebarPanelProbe.ledgerPage(panel).body()));
        assertNotEquals("a new booking re-reads the Ledger", before, afterBooking);
    }

    private static Transaction gain(long at, String name, int itemId, long value)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, 1L, (int) value, value)),
            Confidence.LIKELY, "Test sample.", null);
    }

    /** Every component under the body, depth first; a rebuilt row shows up as a new instance. */
    private static List<Component> children(JComponent body)
    {
        List<Component> out = new java.util.ArrayList<>();
        java.util.Deque<Component> stack = new java.util.ArrayDeque<>(Arrays.asList(body.getComponents()));
        while (!stack.isEmpty())
        {
            Component component = stack.pop();
            out.add(component);
            if (component instanceof java.awt.Container)
            {
                stack.addAll(Arrays.asList(((java.awt.Container) component).getComponents()));
            }
        }
        return out;
    }

    /** Run everything already queued on the EDT, including a drain the last call scheduled. */
    private static void flushEdt() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> { });
        SwingUtilities.invokeAndWait(() -> { });
    }

}

