    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.*;
import java.util.function.LongSupplier;
import org.junit.*;
import static org.junit.Assert.*;

/** Reuse frozen financial facts while time, visibility and ownership remain independently live. */
public class WindowProjectionCacheTest {
    static final long START=60_000, NOW=120_000;
    LongSupplier clock;
    @Before public void setUp(){clock=SafeMath.clock;SafeMath.clock=()->NOW;JsonCodec.bind(new Gson());}
    @After public void tearDown(){SafeMath.clock=clock;}

    static class CountedSession extends Session {
        int windowFolds;
        CountedSession(){super(DURABLE_OWNER_NAME,0,SessionMode.GENERAL);}
        @Override Metrics metrics(List<Transaction> rows,long elapsed){windowFolds++;return super.metrics(rows,elapsed);}
    }
    static Engine engine(){
        var e=new Engine(d->List.of(),new TransactionClassifier(),new GpManagerConfig(){});
        var run=new CountedSession();e.general=e.current=run;e.attachListeners(run);return e;
    }
    static Transaction gain(Engine e,long at,int id,long amount){
        var row=new Transaction(at,TransactionType.GAIN,Context.GENERIC,"","Test",true,
            List.of(new Flow(id,"Item "+id,1,(int)amount,amount,PriceSource.GRAND_EXCHANGE)),Confidence.CONFIRMED,"",null);
        e.session().addTransaction(row,10000,false);return row;
    }
    static Engine window(){var e=engine();gain(e,5,2000,1000);e.newLive(START);gain(e,START+5,2001,500);return e;}
    static LiveSnapshot live(Engine e,long at){return LiveSnapshot.capture(e,at,null);}
    static CountedSession run(Engine e){return (CountedSession)e.session();}

    @Test public void unchangedTicksReuseMoneyWhileTheClockAndRateAdvance(){
        var e=window();var first=live(e,NOW);assertEquals(500,first.net);assertEquals(30_000,first.rate);
        for(int i=1;i<=100;i++)live(e,NOW+i*600);
        var later=live(e,NOW+60_000);assertEquals(120_000,later.elapsed);assertEquals(15_000,later.rate);
        assertEquals("one receipt-window fold for unchanged money",1,run(e).windowFolds);
        assertEquals(1500,e.metrics(NOW).net);
    }
    @Test public void freshRecentDoesNotBuildTheWholeRunsSemanticProjection(){
        var e=window();live(e,NOW);
        assertTrue("only the requested window needs projecting",e.summary().scopes.isEmpty());
        var all=LedgerData.capture(e,NOW,LedgerData.Entry.current());assertEquals(1500,all.net);
        assertFalse("Ledger still builds its whole-run scope",e.summary().scopes.isEmpty());
    }
    @Test public void visibilityChangesReuseMoneyAndKeepTheirOwnRecentResult(){
        var e=window();var hidden=new boolean[]{false};
        var f=new RecentFilter(){
            public boolean isFlowIncluded(Flow flow){return !hidden[0];}
            public String version(){return Boolean.toString(hidden[0]);}
        };
        var ctx=new LiveContext(false,f,0,PvpState.NONE,"",false,"",false);
        assertEquals(1,LiveSnapshot.capture(e,NOW,ctx).recent.size());hidden[0]=true;
        var after=LiveSnapshot.capture(e,NOW+600,ctx);assertTrue(after.recent.isEmpty());assertEquals(500,after.net);
        assertEquals(1,run(e).windowFolds);
    }
    @Test public void aNewBookingAndCorrectionsInvalidateTheWindowTogether(){
        var e=window();live(e,NOW);var added=gain(e,NOW+5,2002,200);
        var next=live(e,NOW+600);assertEquals(700,next.net);assertEquals(2,next.recent.size());
        assertTrue(e.correctTransaction(added.id(),Correction.IGNORE,"Test"));
        var corrected=live(e,NOW+800);assertEquals(500,corrected.net);
        assertEquals(3,run(e).windowFolds);
        assertEquals(500,LedgerData.capture(e,NOW+800,LedgerData.Entry.current().live(Semantics.Table.GAINS)).net);
    }
    @Test public void aChangedBoundaryIsDetectedEvenWithoutARevisionChange(){
        var e=window();gain(e,START+10,2002,200);live(e,NOW);long revision=e.revision();
        run(e).sessionStartAt=START+8;run(e).sessionStartMillis=START+8;
        var next=live(e,NOW+600);assertEquals(200,next.net);assertEquals(1,next.recent.size());
        assertEquals(revision,e.revision());assertEquals(2,run(e).windowFolds);
    }
    @Test public void restartPauseAndRestoreOnlyChangeTheLiveClock(){
        var e=window();live(e,NOW);e.restartRate(NOW, true);var reset=live(e,NOW);
        assertEquals(0,reset.elapsed);assertEquals(500,reset.net);
        e.togglePause(NOW+10_000);assertEquals(10_000,live(e,NOW+20_000).elapsed);
        e.restoreRate(NOW+20_000);assertEquals(60_000,live(e,NOW+30_000).elapsed);
        assertEquals(500,live(e,NOW+30_000).net);assertEquals(1500,e.metrics(NOW+30_000).net);
    }
    @Test public void aNewRunAndOwnerCannotReuseThePreviousWindow(){
        var e=window();live(e,NOW);e.startCustom("Vorkath",NOW);gain(e,NOW+5,2003,300);
        e.newLive(NOW+10);gain(e,NOW+15,2004,400);
        var next=live(e,NOW+60_000);assertEquals(400,next.net);assertEquals(1,next.recent.size());
        e.restoreProfile("another",new SavedState(),NOW+70_000);e.ensureSession(NOW+70_000);
        assertEquals(0,live(e,NOW+80_000).net);assertTrue(live(e,NOW+80_000).recent.isEmpty());
    }
    @Test public void wholeRunModeRetainsItsOriginalAccountingAndGrouping(){
        var e=window();live(e,NOW);e.showWholeRun();var whole=live(e,NOW+600);
        assertFalse(whole.fresh);assertEquals(1500,whole.net);assertEquals(2,whole.recent.size());
        assertEquals(NOW+600,whole.elapsed);
    }
    @Test public void oldOpenOffersStayFirstWhileOldSalesCancelledAndForeignRowsStayOut(){
        var markets=new ArrayList<MarketRows.Row>();
        var e=new Engine(d->List.of(),new TransactionClassifier(),new GpManagerConfig(){}){
            @Override synchronized List<MarketRows.Row> marketRows(){return markets;}
        };
        e.ensureSession(0);var old=gain(e,5,2000,1000);e.newLive(START);var current=gain(e,START+5,2001,500);
        String[] names={"Pending old","Partial old","Old sale","Fresh sale","Cancelled","Foreign"};
        MarketRows.Lifecycle[] states={MarketRows.Lifecycle.PENDING,MarketRows.Lifecycle.PARTIALLY_REALIZED,
            MarketRows.Lifecycle.REALIZED,MarketRows.Lifecycle.REALIZED,MarketRows.Lifecycle.CANCELLED_RETURNED,
            MarketRows.Lifecycle.PENDING};
        for(int i=0;i<names.length;i++){
            var row=LiveCategoryLayoutTest.marketRow(e);row.presentationId=names[i];row.itemName=names[i];
            row.timestampEpochMillis=i+10;row.lifecycle=states[i];
            row.settlementId=i==3||i==4?current.id():i==0||i==5?"":old.id();
            row.earlierSettlements="";if(i==5)row.scopeSessionId="other-owner";
            markets.add(row);
        }
        var snapshot=live(e,NOW);var namesSeen=new ArrayList<String>();
        for(var row:snapshot.recent)namesSeen.add(row.name);
        assertEquals(List.of("Partial old","Pending old","Fresh sale"),namesSeen);
        assertTrue(snapshot.recent.get(0).open);assertTrue(snapshot.recent.get(1).open);assertFalse(snapshot.recent.get(2).open);
        assertEquals(500,snapshot.net);assertEquals(1500,snapshot.run);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * A Grind's GP/h, live or closed, is the full-session rate; the
 * rate is Net over active time, so compaction never hides it.
 */
public class ClosedRateReadinessTest
{
    private static final long NOW = 1_700_000_000_000L;
    private static final long HOUR = 3_600_000L;

    @Test
    public void aCompactedClosedRunStillShowsItsFullRunRate()
    {
        Fixture fixture = new Fixture();
        fixture.engine.startCustom("Vorkath", NOW - HOUR);
        Session session = fixture.engine.session();
        String id = session.id();
        book(session, NOW - HOUR + 60_000L, 1_000_000L);
        book(session, NOW - 30_000L, 1_000_000L);
        fixture.engine.finishCustom(NOW);

        Session closed = fixture.engine.historySession(id);
        closed.compactBefore(NOW - 30_000L, null);
        GrindsData data = GrindsData.capture(fixture.engine, NOW, false, id);
        assertTrue("the closed detail rate is established", data.detail.ready);
        assertEquals("on the full-session basis", 2_000_000L, data.detail.rate);
        assertEquals("the money stays exact", 2_000_000L, data.detail.net);
    }

    @Test
    public void theActiveRateSurvivesCompaction()
    {
        Fixture fixture = new Fixture();
        fixture.engine.startCustom("Vorkath", NOW - HOUR);
        Session session = fixture.engine.session();
        book(session, NOW - HOUR + 60_000L, 1_000_000L);
        book(session, NOW - 30_000L, 1_000_000L);
        session.compactBefore(NOW - 30_000L, null);
        GrindsData data = GrindsData.capture(fixture.engine, NOW, false, session.id());
        assertTrue("compaction never hides the live rate: it is Net over active time",
            data.detail.ready);
        assertEquals(2_000_000L, data.detail.rate);
    }

    @Test
    public void theClosedFloorIsSixtySecondsAndZeroIsHonest()
    {
        Engine under = engine();
        under.startCustom("Vorkath", NOW - 59_000L);
        book(under.session(), NOW - 58_000L, 60_000L);
        String underId = under.session().id();
        under.finishCustom(NOW);
        assertFalse("under a minute has no rate",
            GrindsData.capture(under, NOW, false, underId).detail.ready);

        Engine exact = engine();
        exact.startCustom("Vorkath", NOW - 60_000L);
        book(exact.session(), NOW - 59_000L, 60_000L);
        String exactId = exact.session().id();
        exact.finishCustom(NOW);
        GrindsData closed = GrindsData.capture(exact, NOW, false, exactId);
        assertTrue("exactly a minute qualifies", closed.detail.ready);
        assertEquals(3_600_000L, closed.detail.rate);

        Engine zero = engine();
        zero.startCustom("Vorkath", NOW - 120_000L);
        String zeroId = zero.session().id();
        zero.finishCustom(NOW);
        GrindsData empty = GrindsData.capture(zero, NOW, false, zeroId);
        assertTrue("a real zero is not unavailable", empty.detail.ready);
        assertEquals(0L, empty.detail.rate);
    }

    private static void book(Session session, long at, long value)
    {
        session.addTransaction(new Transaction(at, TransactionType.LOOT, Context.LOOT, "", "Vorkath", true,
            Collections.singletonList(new Flow(536, "Dragon bones", 1L, (int) value, value)),
            Confidence.CONFIRMED, "fixture", null), 2_000, false);
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig()
            {
            });
    }

    private static final class Fixture
    {
        final Engine engine = engine();
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * G2 (owner policy 2026-09-24): a GE sale listed in one Grind and collected in another books in
 * the collecting Grind, is labelled with the listing Grind, and never appears in (or rewrites) the
 * closed origin Grind's Ledger.
 */
public class CrossGrindSaleReceiptTest
{
    private static final long T0 = System.currentTimeMillis() - 10 * 60_000L;
    private static final int COINS = ItemID.COINS;
    private static final int SHARK = ItemID.SHARK;
    private static final long QTY = 30L;
    private static final long GROSS = 29_280L;
    private static final long TAX = 570L;
    private static final long RECEIVED = GROSS - TAX;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void saleListedInOneGrindBooksAndIsLabelledInTheCollectingGrind()
    {
        Fixture fixture = new Fixture();
        fixture.engine.startCustom("Grind A", T0);
        fixture.engine.setBaseline(new ContainerSnapshot(fixture.inventory));
        String grindA = fixture.engine.session().id();
        fixture.placeAndSell(0, SHARK, QTY, GROSS, T0 + 1_000L);

        fixture.engine.finishCustom(T0 + 5_000L);
        fixture.engine.startCustom("Grind B", T0 + 6_000L);
        fixture.engine.setBaseline(new ContainerSnapshot(fixture.inventory));
        Session grindB = fixture.engine.session();
        fixture.collectAlone(0, SHARK, RECEIVED, T0 + 10_000L);

        Transaction settlement = fixture.settlement();
        assertNotNull(settlement);
        assertTrue("counted in the collecting Grind", settlement.counts());
        assertTrue(grindB.transactions().contains(settlement));
        assertFalse(ReviewRules.needsReview(settlement));
        assertEquals("Grind B pays exactly the proven tax", -TAX, fixture.engine.metrics(T0 + 11_000L).net);

        MarketRows.Row row = fixture.row(SHARK);
        assertEquals("the row follows its settlement's session", grindB.id(), row.scopeSessionId);
        assertEquals("Grind A", row.listedDuring);
        List<String> lines = MarketText.humanLines(row, false);
        assertTrue("labelled with the listing Grind: " + lines, lines.contains("Listed during|Grind A"));
        assertTrue(lines.contains("Received|" + Fmt.exact(RECEIVED) + " gp"));

        LedgerData current = fixture.capture(LedgerData.Scope.CURRENT_GRIND, null, null);
        assertEquals("the collecting Grind shows the sale once", 1, current.market.receipts);
        LedgerData origin = fixture.capture(LedgerData.Scope.HISTORY, grindA, "Grind A");
        assertEquals("the closed origin Grind is not rewritten", 0, origin.market.receipts);
        assertEquals(0L, origin.net);
    }

    @Test
    public void saleListedInFreePlayIsLabelledOverallInTheGrind()
    {
        Fixture fixture = new Fixture();
        fixture.engine.ensureSession(T0);
        fixture.engine.setBaseline(new ContainerSnapshot(fixture.inventory));
        fixture.placeAndSell(0, SHARK, QTY, GROSS, T0 + 1_000L);

        fixture.engine.startCustom("Grind B", T0 + 6_000L);
        fixture.engine.setBaseline(new ContainerSnapshot(fixture.inventory));
        fixture.collectAlone(0, SHARK, RECEIVED, T0 + 10_000L);

        MarketRows.Row row = fixture.row(SHARK);
        assertEquals("Overall", row.listedDuring);
        assertTrue(MarketText.humanLines(row, false).contains("Listed during|Overall"));
    }

    @Test
    public void sameSessionSaleHasNoListedDuringLabel()
    {
        Fixture fixture = new Fixture();
        fixture.engine.startCustom("Grind A", T0);
        fixture.engine.setBaseline(new ContainerSnapshot(fixture.inventory));
        fixture.placeAndSell(0, SHARK, QTY, GROSS, T0 + 1_000L);
        fixture.collectAlone(0, SHARK, RECEIVED, T0 + 10_000L);

        MarketRows.Row row = fixture.row(SHARK);
        assertEquals("", row.listedDuring);
        assertFalse(MarketText.humanLines(row, false).stream()
            .anyMatch(line -> line.startsWith("Listed during")));
    }

    private static final class Fixture
    {
        final Engine engine;
        final OfferSlots ledger = new OfferSlots();
        final Map<Integer, Long> inventory = new HashMap<>();

        Fixture()
        {
            engine = new Engine(deltas ->
            {
                List<Flow> flows = new ArrayList<>();
                for (Map.Entry<Integer, Long> delta : deltas.entrySet())
                {
                    int id = delta.getKey();
                    long unit = id == COINS ? 1L : 978L;
                    flows.add(new Flow(id, id == COINS ? "Coins" : "Shark", delta.getValue(),
                        (int) unit, delta.getValue() * unit,
                        id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
                }
                return flows;
            }, new TransactionClassifier(), new GpManagerConfig()
            {
                @Override
                public Retention receiptRetentionDays()
                {
                    return Retention.DAYS_365;
                }

                @Override
                public int stabilizationTicks()
                {
                    return 0;
                }
            });
            inventory.put(COINS, 1_000_000L);
        }

        void placeAndSell(int slot, int item, long qty, long gross, long at)
        {
            inventory.put(item, qty);
            engine.setBaseline(new ContainerSnapshot(inventory));
            offer(slot, SELLING, item, (int) qty, 0, 978, 0, at);
            inventory.put(item, 0L);
            settleAt(at + 100L);
            offer(slot, SOLD, item, (int) qty, (int) qty, 978, (int) gross, at + 200L);
        }

        void collectAlone(int slot, int item, long received, long at)
        {
            offer(slot, EMPTY, item, 0, 0, 0, 0, at - 600L);
            engine.noteGeCollect(at);
            inventory.put(COINS, inventory.getOrDefault(COINS, 0L) + received);
            settleAt(at);
        }

        Transaction settlement()
        {
            String id = row(SHARK).settlementId;
            for (Transaction transaction : engine.session().transactions())
            {
                if (transaction.id().equals(id))
                {
                    return transaction;
                }
            }
            return null;
        }

        MarketRows.Row row(int itemId)
        {
            for (MarketRows.Row row : engine.marketRows())
            {
                if (row.itemId == itemId)
                {
                    return row;
                }
            }
            throw new AssertionError("no market row for " + itemId);
        }

        LedgerData capture(LedgerData.Scope scope, String historyId, String historyName)
        {
            return LedgerData.capture(engine, T0 + 20_000L,
                new LedgerData.Entry(scope, historyId, historyName,
                    LedgerData.CostView.SUPPLIES, "", null, null, null, null));
        }

        private void offer(int slot, GrandExchangeOfferState state, int item, int total, int traded,
            int price, int spent, long at)
        {
            OfferSlots.Transition transition = ledger.observe(
                new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent)).orElse(null);
            if (transition != null)
            {
                engine.noteGeOffer(transition, "Shark", at);
            }
        }

        private void settleAt(long at)
        {
            engine.markDirty();
            ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
            engine.processIfDirty(snapshot, at, null);
            engine.processIfDirty(snapshot, at + 1L, null);
        }
    }
}

