    @Test
    public void theDetailPagerSurvivesRefreshesAndClampsWhenRowsShrink() throws Exception
    {
        Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig() {});
        engine.startCustom("Vorkath", T0);
        for (int i = 0; i < 8; i++)
        {
